INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('1df7c77d-8240-40f9-afc8-dd3d55cd850b','বৃষ্টির দিনে তোমার প্রেমে','Alex Maruf Raj','6019ebc0-aeeb-42fa-9851-b27451a2558c','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/b654e627-b536-4bcb-9e25-f9cfa9b72bf8.png','আরিফ ও নীলাঞ্জনার প্রথম দেখা হয় এক বৃষ্টিভেজা বিকেলে। একটি ছোট্ট পরিচয় থেকে শুরু হয় তাদের বন্ধুত্ব, আর সেই বন্ধুত্ব একসময় রূপ নেয় গভীর ভালোবাসায়। কিন্তু ভালোবাসার পথে কি সবকিছু সহজ হয়? দূরত্ব, অভিমান আর নানা বাধা পেরিয়ে তারা কি একসঙ্গে থাকতে পারবে? জানতে পড়ুন এক মিষ্টি প্রেমের গল্প—“বৃষ্টির দিনে তোমার প্রেমে”।','published','complete',0,0,46,4,0,'2026-10-26T13:55:48.371Z','2026-10-26T13:55:48.371Z','#123E39','#F5C660','',1,'চলমান',0,'','','',1,1,'both','episodes','gwephmjp');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('95b4cdd4-4d37-4bb2-ba1c-996e967b1061','আমাদের অসমাপ্ত গল্প','Mehedi Hasan','696b1d81-e4f5-4607-92a7-9b6d2f574755','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/70b46916-803b-458b-a78d-3945c27448a7.png',replace('কিছু ভালোবাসা হঠাৎ করেই জীবনে আসে, হৃদয়ে হাজারো স্বপ্ন জাগায়, আবার কখনো নীরবে দূরে চলে যায়।\n\nআরিশ ও মায়ার গল্পটা ঠিক তেমনই। প্রথম দেখা, মিষ্টি ঝগড়া, অভিমান, একে অপরের প্রতি অজান্তেই দুর্বল হয়ে পড়া—সবকিছু মিলিয়ে তাদের জীবন হয়ে ওঠে ভালোবাসার এক নতুন অধ্যায়।\n\nকিন্তু ভাগ্য কি সব ভালোবাসাকে পূর্ণতা দেয়? পরিবারের বাধা, ভুল বোঝাবুঝি আর অতীতের কিছু গোপন সত্য কি তাদের আলাদা করে দেবে?\n\nনাকি সব বাধা পেরিয়ে একদিন তারা খুঁজে পাবে একে অপরকে?\n\nজানতে হলে পড়তে হবে—আমাদের অসমাপ্ত গল্প। কারণ কিছু গল্পের শেষ হয় না, শুধু অপেক্ষায় থাকে নতুন একটি অধ্যায়ের।','\n',char(10)),'published','complete',0,0,71,6,0,'2026-10-26T14:25:41.206Z','2026-10-27 03:12:53','#123E39','#F5C660','',1,'চলমান',0,'','','',1,1,'both','episodes','k5745s2k');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('71e59a9a-70fc-47e7-84cd-cf9406c3e3d7','Toxic Lover','Teha Chawdhary','696b1d81-e4f5-4607-92a7-9b6d2f574755','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/4b067b09-52b2-4707-8f2d-36669fb2376b.png','👀🕊️','published','',0,0,43,4,0,'2026-10-27 09:20:19','2026-10-27 09:20:19','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','x4xs8r3r');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('70315848-fc25-4b07-8e69-adb1ac9c5483','অন্ধকার পেড়িয়ে আলো','Nibir Ahmed','f935dbd8-dc79-47d8-947b-4745d9d382d7','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/c11edc94-4267-400c-b815-c35c886084d5.png','রাফি একজন সাধারণ ছেলে, যে অভাব ও ব্যর্থতার মধ্যেও নিজের জীবনে সফল হতে চায়। পরীক্ষায় খারাপ ফল করে এবং মানুষের কটুকথা শুনে সে ভেঙে পড়লেও, এক বৃদ্ধের উপদেশ তাকে নতুন করে সাহস জোগায়। এরপর রাফি নিজের ভুল শুধরে প্রতিদিন পরিশ্রম করার সিদ্ধান্ত নেয়। সে বিশ্বাস করতে শেখে, আজকের খারাপ সময়ই তার জীবনের শেষ নয়—চেষ্টা চালিয়ে গেলে একদিন সফলতা আসবেই।','published','',0,0,21,0,0,'2026-10-27 16:31:59','2026-10-27 16:31:59','#123E39','#F5C660','',1,'সম্পূর্ণ',0,'','','',1,0,'both','episodes','k4apdaf2');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('f8eb53fa-f24b-4c87-b3d4-b504eeebf8b2','ছায়াসাম্রাজ্য — শেষ উত্তরাধিকারী','Nibir Ahmed','ab7f9bb7-e8a4-45fe-ae47-1dd1eb7dea8a','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/29a4bf94-f72f-4651-871c-4fd9cacd80af.jpg',replace('সাতটি জাদুর রাজ্য, একটি হারিয়ে যাওয়া সাম্রাজ্য আর এমন এক কিশোর, যার জন্মের রহস্য জানলে কেঁপে উঠবে পুরো পৃথিবী।\n\nসাধারণ জীবন কাটানো আরিন কখনো জানত না যে তার শরীরে ঘুমিয়ে আছে হাজার বছর আগের এক ধ্বংস হয়ে যাওয়া সাম্রাজ্যের শক্তি। তার ষোলোতম জন্মদিনে আকাশে দেখা দিল কালো চাঁদ, জেগে উঠল নিষিদ্ধ জাদু, আর তার হাতে ফুটে উঠল এক রহস্যময় চিহ্ন।\n\nসেই রাতেই নিখোঁজ হয়ে গেল তার বাবা। রেখে গেলেন একটি ভাঙা তলোয়ার, রক্তে লেখা একটি বার্তা এবং এমন এক নাম—যে নাম উচ্চারণ করাও নিষিদ্ধ।\n\nবাবাকে খুঁজতে গিয়ে আরিন প্রবেশ করবে এমন এক জগতে, যেখানে ছায়ারা কথা বলে, মৃত রাজারা স্বপ্নে ফিরে আসে, আর প্রতিটি জাদুর পেছনে লুকিয়ে থাকে ভয়ংকর মূল্য।\n\nকিন্তু সবচেয়ে বড় রহস্য হলো—আরিন কি পৃথিবীকে বাঁচানোর জন্য জন্মেছে, নাকি পৃথিবীকে ধ্বংস করার জন্য?\n\nছায়াসাম্রাজ্যের দরজা খুলেছে। এবার আর কিছুই আগের মতো থাকবে না।','\n',char(10)),'published','',0,0,33,0,0,'2026-10-27 16:32:14','2026-10-27 16:32:14','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','aszqawr7');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('aca31ba8-956d-4587-8c86-eec72cc2d6be','অপূর্ণতায় তুমি','Md. Shihab Ahmed Panna','2027aaed-a453-404d-bf1e-881090a41e1a','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/a19b425a-265b-4da8-bf31-2afc60e9d503.jpg','‘অপূর্ণতায় তুমি’ একটি রহস্য, প্রতিশোধ, ভালোবাসা ও আবেগে ঘেরা উপন্যাস। নীলা, নাদিম ও আদনানের জীবনের জটিল অনুভূতির পাশাপাশি নাইম ও রিমির ভালোবাসার গল্প এগিয়ে চলে ভিন্ন এক পথে। অন্যদিকে, জমিদার মাহবুবুর রহমানের অতীত, মাহতাবের রহস্যময় কর্মকাণ্ড এবং একের পর এক শিশু নিখোঁজ হওয়ার ঘটনা গল্পটিকে আরও রহস্যময় করে তুলেছে। ভালোবাসা, অতীতের প্রতিশোধ আর অজানা রহস্যের জালে জড়িয়ে পড়েছে সবার জীবন।','published','',0,0,17,1,0,'2026-10-27 16:52:39','2026-10-27 16:54:16','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','vj8ctydm');
