INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('3cd9c22b-ae96-4503-8d89-f3ee32cb2c07','লাল বাড়ির কাহিনি','Nibir Ahmed','3520be79-28c1-4c45-9c4d-920292885a61','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/0ce2762b-0c8a-4ece-a33f-90a4ec068ff3.jpg',replace('লাল বাড়ির রহস্য — সারাংশ\n\nএক রহস্যময় রাতে গ্রামের পুরোনো লাল বাড়িতে খুন হন জমিদার রাশেদ চৌধুরী। বন্ধ ঘরের ভেতরে ঘটে যাওয়া এই খুনের কোনো সূত্র খুঁজে পায় না পুলিশ। রহস্যের সমাধানে আসে তরুণ গোয়েন্দা আরিয়ান রহমান। তদন্ত করতে গিয়ে সে আবিষ্কার করে একটি গোপন ঘর, পুরোনো ছবি এবং দশ বছর আগে নিখোঁজ হওয়া নিজের বাবার সঙ্গে এই বাড়ির অদ্ভুত সম্পর্ক। কিন্তু সত্যের কাছাকাছি পৌঁছাতেই অন্ধকার থেকে ভেসে আসে এক হুমকি। কে এই খুনি? আর আরিয়ানের বাবার নিখোঁজ হওয়ার পেছনে কি লুকিয়ে আছে ভয়ংকর কোনো রহস্য?','\n',char(10)),'published','',0,0,39,4,0,'2026-10-27 18:52:46','2026-10-28 04:59:39','#123E39','#F5C660','',1,'সম্পূর্ণ',0,'','','',1,0,'both','episodes','mqcevber');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('767cb584-4f32-47e3-b976-2e77450aa511','তুমি আমার শেষ ঠিকানা','Md Abu Taleb','6019ebc0-aeeb-42fa-9851-b27451a2558c','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/c4e64623-5e0e-4625-ac38-e87e5879c6cd.png',replace('গল্পের নাম: তুমি আমার শেষ ঠিকানা ❤️\n\nআরিয়ান ও নীলার গল্পটি দুটি অচেনা মানুষের প্রথম দেখা থেকে শুরু হওয়া এক মিষ্টি ভালোবাসার গল্প। প্রথমে খুনসুটি, তারপর বন্ধুত্ব, আর ধীরে ধীরে একে অপরের প্রতি গভীর টান—সব মিলিয়ে তাদের সম্পর্ক হয়ে ওঠে বিশেষ। কিন্তু নীলার পরিবার যখন তার বিয়ের কথা ভাবতে শুরু করে, তখন আরিয়ানের মনে জন্ম নেয় নীলাকে হারানোর ভয়। নিজের মনের কথা কি আরিয়ান নীলাকে বলতে পারবে? নাকি সময়ের আগেই তাদের ভালোবাসার গল্পে নেমে আসবে বিচ্ছেদের ছায়া? জানতে হলে পড়তে হবে ‘তুমি আমার শেষ ঠিকানা’—ভালোবাসা, আবেগ, অভিমান ও অপেক্ষায় ভরা একটি রোমান্টিক উপন্যাস।','\n',char(10)),'published','',0,0,23,3,0,'2026-10-28 08:02:14','2026-10-28 08:02:14','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','kd5y82ej');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('c4867502-b7f2-4c77-b704-eba7e96e8b8d','~ তোমার অন্ধকারে আমার বসন্ত ~','Noor Islam','6019ebc0-aeeb-42fa-9851-b27451a2558c','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/9d7d0ec5-f9e0-4274-ac31-e05e32a848b3.png','**তীব্র প্রেম,গোপন অতীত আর ভালোবাসায় নতুন জীবনের গল্প**🌙🖊️','published','',0,0,52,7,0,'2026-10-28 10:11:52','2026-10-28 10:11:52','#123E39','#F5C660','',1,'চলমান',0,'','','Noor Islam',1,1,'both','episodes','kyr7gwcw');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('4f94b40b-3163-4e82-be86-71aae1de626d','তোমাতেই আমার পূর্ণতা','Sumi Akther','f935dbd8-dc79-47d8-947b-4745d9d382d7','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/20b78edb-836a-4576-aafb-1c72be6e4110.png',replace('কিছু মানুষ জীবনে আসে, হৃদয়জুড়ে ভালোবাসা হয়ে থেকে যায়। ❤️\n\nকখনো মিষ্টি খুনসুটি, কখনো ছোট্ট অভিমান, আবার কখনো একে অপরকে হারানোর ভয়—সব মিলিয়েই ভালোবাসার গল্প।\n\nদুজন মানুষ একে অপরকে ভীষণ ভালোবাসে। অথচ কিছু ভুল বোঝাবুঝি, কিছু না বলা কথা আর জমে থাকা অভিমান তাদের আলাদা করে দেয়। দূরত্ব বাড়লেও কি মুছে যায় মনের টান? নাকি ভাগ্য আবারও তাদের একই পথে ফিরিয়ে আনে?\n\nঅভিমান ভেঙে, চোখের জল মুছে, সব বাধা পেরিয়ে তারা কি আবার একে অপরের হাত ধরতে পারবে?\n\nএটি শুধু প্রেমের গল্প নয়, এটি অপেক্ষার গল্প, হারিয়ে গিয়েও ফিরে পাওয়ার গল্প, আর এমন এক ভালোবাসার গল্প—যেখানে হাজারো অপূর্ণতার মাঝেও একজন মানুষই হয়ে ওঠে অন্যজনের পূর্ণতা।\n\n“তোমাতেই আমার পূর্ণতা” 🌸💌','\n',char(10)),'published','',0,0,10,0,0,'2026-10-28 10:38:58','2026-10-28 10:38:58','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','z5nffwf3');
