INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('826859bd-a939-4018-a898-2994a1ba388a','মির্জার বিষাক্ত মায়া','Jannatul Mahi','696b1d81-e4f5-4607-92a7-9b6d2f574755','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/5d80baba-8d22-4c63-be69-8f8a99ca3b61.png','🖤🥀 “প্রিয়সী, তুমি আমার জীবনের সেই অভিশাপ, যাকে আমি মুক্তি দিতে চাই না; সেই পাপ, যার প্রায়শ্চিত্ত করতে আমার অনন্তকালও কম পড়বে। তোমাকে ভালোবাসতে গিয়ে আমি আমার ভেতরের মানুষটাকে কবর দিয়েছি, অথচ তোমার জন্য বাঁচিয়ে রেখেছি আমার শেষ কোমলতাটুকু। তুমি আমার অন্ধকার, আমার উন্মাদনা, আমার সর্বনাশের নেশা! আর যদি কোনোদিন আমার গল্পের শেষ পৃষ্ঠায় আমার নামটুকুও অবশিষ্ট না থাকে, তবুও মনে রেখো—একটা দানবও একদিন ভালোবেসেছিল, আর তার সমস্ত অন্ধকারের ওপারে একমাত্র তুমিই ছিলে তার জান্নাত, তার সর্বনাশ, তার অনন্তকাল…!” 🥀🖤','published','',0,0,25,0,0,'2026-10-28 15:04:35','2026-10-28 15:04:35','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','m2tbby2h');
