INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('26cb6db9-27be-4121-8301-f19e3f6e0dec','THE BLACK BILLIONAIRE','Nibir Ahmed','696b1d81-e4f5-4607-92a7-9b6d2f574755','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/250452ce-30c5-495b-8602-e8d3bec0e884.jpg',replace('The Black Billionaire — সারাংশ\n\nআরিয়ান রহমান একজন তরুণ উদ্যোক্তা, যার স্বপ্ন নিজের ব্যবসায়িক সাম্রাজ্য গড়ে তোলা। সামান্য পুঁজি থেকে শুরু করে সে ধীরে ধীরে সফলতার পথে এগিয়ে যায়। কিন্তু প্রভাবশালী ব্যবসায়ী রাশেদ করিমের সঙ্গে একটি বড় চুক্তি তার জীবনকে অন্যদিকে নিয়ে যায়। চুক্তির আড়ালে লুকিয়ে আছে রহস্য, প্রতারণা ও কোটি টাকার খেলা। নিজের স্বপ্ন, সম্মান ও ব্যবসা রক্ষার লড়াইয়ে আরিয়ানকে মুখোমুখি হতে হবে বিশ্বাসঘাতকতা, শত্রুতা এবং নির্মম ব্যবসায়িক ষড়যন্ত্রের।','\n',char(10)),'published','',0,0,9,0,0,'2026-10-28 17:01:55','2026-10-28 17:30:34','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','mc7g2m6z');
