INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('b98c6429-e76f-4896-8621-fd2d226b335c','মাফিয়া কিংয়ের পাগল করা ভালোবাসা','Humaira Jannat','f935dbd8-dc79-47d8-947b-4745d9d382d7','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/eba2a56b-5423-41d2-85fc-7b3da9389f45.png','অতীতের রহস্য খুঁজতে যাকে হাতিয়ার বানিয়েছিল তার প্রতি আসতে আসতে দুর্বল হয়ে পরে শহরে বিখ্যাত মাফিয়া','published','',0,0,20,1,0,'2026-10-29 06:35:00','2026-10-29 06:35:00','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','d6k5qdqm');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('c6cad923-5458-4e54-9718-f26151ffb31d','“প্রেমের বদলে প্রিন্সিপালের বকা”','Afrin Akter','6019ebc0-aeeb-42fa-9851-b27451a2558c','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/b2cc3200-bd9e-4b44-8761-df7eac2398a7.png',replace('কলেজজীবন, দুষ্টুমি, ঝগড়া আর হাস্যকর সব কাণ্ডকারখানা নিয়ে আরহাম চৌধুরী ও মেহরিন ইসলামের গল্প—‘প্রেমের বদলে প্রিন্সিপালের বকা’! 😂🖤\n\nআরহাম কলেজের সবচেয়ে দুষ্টু ছেলে, আর মেহরিন এমন এক মেয়ে, যে আরহামের কোনো দুষ্টুমিই সহ্য করতে পারে না। দুজনের দেখা হলেই শুরু হয় ঝগড়া, খুনসুটি আর একে অপরকে হারানোর প্রতিযোগিতা। তাদের এই যুদ্ধের মাঝে আছে বাবলার আজগুবি বুদ্ধি, তিশার গসিপ আর প্রিন্সিপাল স্যারের অন্তহীন বকা!\n\nকিন্তু কলেজে হঠাৎ ঘটে যেতে থাকে অদ্ভুত কিছু ঘটনা। রহস্যময় চিঠি, অজানা দুষ্টুমি আর সাত দিনের এক অদ্ভুত চ্যালেঞ্জ—সবকিছু যেন তাদের জীবন ওলটপালট করে দেয়।\n\nযে দুজন একে অপরকে দেখলেই ঝগড়া করে, তাদেরই কি এবার একসঙ্গে রহস্যের সমাধান করতে হবে? নাকি প্রেমের আগেই কপালে জুটবে প্রিন্সিপালের আরও এক দফা বকা? 🤭\n\nহাসি, বন্ধুত্ব, দুষ্টুমি আর অপ্রত্যাশিত রহস্যে ভরা এই গল্পে স্বাগতম—‘প্রেমের বদলে প্রিন্সিপালের বকা’! 👑📚','\n',char(10)),'published','',0,0,9,1,0,'2026-10-29 10:46:06','2026-10-29 10:46:06','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','jqpasnx5');
