INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('90a23f6f-1b22-44ae-9e70-6132ca169bfa','৩০৭ নম্বর কক্ষ','Unique Writer','ab7f9bb7-e8a4-45fe-ae47-1dd1eb7dea8a','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/78b51c02-35e8-4281-ae38-498980ecc295.png','একটি হোটেলের ৩০৭ নম্বর কক্ষে প্রতি রাতে অদ্ভুত ঘটনা ঘটে। এক রাতে কক্ষটি বাইরে থেকে তালাবদ্ধ থাকা সত্ত্বেও একজন মানুষ নিখোঁজ হয়ে যায়।','published','',0,0,7,1,0,'2026-10-29 17:20:43','2026-10-29 17:20:43','#123E39','#F5C660','',1,'সম্পূর্ণ',0,'','','',1,0,'both','episodes','63unqrn6');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('b83dde16-d997-4cb8-85e6-a792492117eb','চিঠির বাক্স','Unique Writer','6019ebc0-aeeb-42fa-9851-b27451a2558c','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/8cc45acc-a35d-4e4f-9c26-759863a2fb87.png','একটি বাক্স, দুটি মানুষ, অসংখ্য না বলা কথা। ক্যাম্পাসের কৃষ্ণচূড়া গাছ, বৃষ্টি ভেজা বিকেল আর হুইলচেয়ারে বসা এক মেয়ের অপেক্ষার গল্প — চিঠির বাক্স। একটি মিষ্টি প্রেমের গল্প যা আপনাকে কাঁদাবে, হাসাবে।','published','',0,0,12,2,0,'2026-10-29 17:21:33','2026-10-29 17:21:33','#123E39','#F5C660','',1,'সম্পূর্ণ',0,'','','',1,0,'both','episodes','auv3mjd2');
INSERT INTO "books" ("id","title","author","category_id","cover_url","description","status","writer_status","is_new","featured","views","likes","dislikes","created_at","updated_at","color","accent","home_section","views_visible","display_status","hide_title_on_cover","pdf_url","dedication","author_name","show_ads","pdf_reward_ad","visible_on","story_type","short_id") VALUES('6b7c1105-1b75-4e90-8d98-234684d5046e','“অতীতের মাশুল”','Mahi😊🎀','ab7f9bb7-e8a4-45fe-ae47-1dd1eb7dea8a','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/3c99f398-bf89-4599-aaf3-ce233cd3ed74.png','🥀 “খন্দকার সাহেব, আপনাকে ভালোবেসে অর্ধাঙ্গিনী হয়েছিলাম, অথচ আপনার হৃদয়ে আমার ঠাঁই হলো না!”❤️‍🩹','published','',0,0,15,1,0,'2026-10-30 02:42:18','2026-10-30 02:42:18','#123E39','#F5C660','',1,'চলমান',0,'','','',1,0,'both','episodes','bbbf79ju');
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('91968853-7aa0-40f0-9cdd-fcaa659d4ece','d878bb53-dd8d-4818-b498-56f3c884ef3f','মির্জা গালিবের বিখ্যাত উক্তি সমূহ:',replace('1. মদে আর কতটুকু নেশা গালিব,\nসর্বনাশ তো করেছে প্রেমিকার চোখে,,💔😅\nমির্জা গালিব\n2. প্রেমে পড়েছো আবার সম্মানও চাও,ভালোবাসছো আবার মর্জাদাও চাও,তুমি বড়ই নাদান গালিব,বিষ খেয়েছো আবার বাচতেও চাও,,💔😅\nমির্জা গালিব\n3. হাতের রেখায় ভাগ্য দেখতে যেওনা গালিব….\nযাদের হাত নেই তাদেরও কিন্তু ভাগ্য আছে\n-মির্জা গালিব\n4. ~❝”হৃদয় তো পাথর নয়,,, যে ব্যাথায় ভরে উঠবে না!”❞ ~💔\n~মির্জা গালিব\n5. ~❝”ভালোবাসা পাওয়ার চেয়ে ভালোবাসতে পারাটাই বড় সৌভাগ্য!”❞ ~ ❣️🫀\n~Mirza Galib\n6. মির্জা গালিব বলেছিলেন….!!\nআমি তো হেরে যাইনি গালিব….!!\nআমি লজ্জায় নিজেকে সরিয়ে নিয়েছি….!!\nকারণ আমার হৃদয়ে থাকা মানুষটাই আজ…..!!\nআমার বিপক্ষে দাঁড়িয়ে কথা বলে…..!!🥀🦋\n7.~❝”সময়ের এই পর্যায় টা কেটে যাবে গালিব!”\n“একটু ধৈর্য ধরো!”\n” যখন সুখ স্থায়ী হয়নি, তখন দুঃখের ও বা কতটুকু ক্ষমতা আছে?”❞~\n~মির্জা গালিব\n8. এক ফোটা শান্তির আশায় আমি হ্নদয় বিক্রি করতে বেরিয়েছিলাম,\nকিন্তু খরিদদার দুঃখ দিয়ে গেলো আবার হ্নদয়ও নিয়ে গেলো,,💔😅\n9. *মদ তো শুধু নামেই বদনাম গালিব”\n*আসল নেশা তো লুকিয়ে আছে ওই এক জোড়া মায়াবী চোখে-!👀❤️‍🩹\n10. সময়ের সাথে যেখানে গোটা পৃথিবী বদলে যায়,,\nসেখানে মানুষ আর কি জিনিস,,💔😅','\n',char(10)),2,'published',0,'2026-09-07T16:07:31.928Z','2026-09-07T16:07:31.928Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('c96b40a2-0934-4739-84e3-c867a98d3826','15ecf51b-fe9a-4baf-aa56-2af6f1bfce52','অন্ধকার কূপ থেকে আলোর পথে',replace('> এক ছোট্ট ছেলে। নাম ইউসুফ।\n\nতার চোখে ছিল নিষ্পাপ স্বপ্ন, আর হৃদয়ে ছিল আল্লাহর প্রতি গভীর বিশ্বাস। এক রাতে সে একটি আশ্চর্য স্বপ্ন দেখল। স্বপ্নে সে দেখল—এগারোটি তারকা, সূর্য ও চাঁদ যেন তার সামনে নত হয়ে আছে।\n\nঘুম ভাঙার পর ইউসুফ ছুটে গেলেন তাঁর পিতা ইয়াকুব (আ.)-এর কাছে।\n\n— “আব্বাজান, আমি একটি অদ্ভুত স্বপ্ন দেখেছি…”\n\nইয়াকুব (আ.) মনোযোগ দিয়ে ছেলের কথা শুনলেন। তিনি বুঝতে পারলেন, এই স্বপ্নের মধ্যে বিশেষ কোনো ইঙ্গিত রয়েছে। তাই তিনি ছেলেকে সতর্ক করে বললেন, এই স্বপ্নের কথা যেন ভাইদের কাছে না বলে।\n\nকিন্তু মানুষের অন্তরে যখন হিংসা জায়গা করে নেয়, তখন আপনজনও দূরের মানুষ হয়ে যায়।\n\nইউসুফের ভাইদের মনে ধীরে ধীরে ঈর্ষা জন্ম নিল। তারা ভাবতে লাগল, কেন ইউসুফকে তাদের পিতার কাছে এত প্রিয় মনে হয়?\n\nএকদিন তারা ইউসুফকে সঙ্গে নিয়ে দূরে চলে গেল।\n\nতারপর এমন এক মুহূর্ত এলো, যখন নিষ্পাপ শিশুটিকে তারা একটি গভীর কূপে ফেলে দিল।\n\nকূপের অন্ধকারে একা পড়ে রইলেন ইউসুফ।\n\nচারদিকে অন্ধকার।\n\nকেউ নেই।\n\nকোনো আপনজন নেই।\n\nকিন্তু তিনি একা ছিলেন না।\n\n==আল্লাহ তাঁর সঙ্গে ছিলেন।==\n\nউপরে আকাশের সামান্য অংশ দেখা যাচ্ছিল। ইউসুফ হয়তো জানতেন না, তাঁর জীবনে এরপর কী ঘটবে। কিন্তু আল্লাহ জানতেন।\n\nকিছু সময় পর একটি কাফেলা সেই পথ দিয়ে যাচ্ছিল। তারা কূপ থেকে পানি তুলতে গিয়ে ইউসুফকে দেখতে পেল।\n\nএকটি অন্ধকার কূপ—সেখান থেকেই শুরু হলো তাঁর জীবনের নতুন অধ্যায়।\n\nইউসুফকে মিসরে নিয়ে যাওয়া হলো। জীবনের পথে তাঁকে আরও অনেক পরীক্ষা দিতে হলো। কখনো তিনি অন্যায়ের শিকার হলেন, কখনো কারাগারে গেলেন।\n\n## কিন্তু একটি বিষয় তিনি কখনো হারাননি—\n\nআল্লাহর ওপর বিশ্বাস।\n\nবছরের পর বছর কেটে গেল।\n\nযে ছেলেটিকে একদিন তাঁর ভাইয়েরা কূপে ফেলে দিয়েছিল, আল্লাহ একদিন তাকেই সম্মান ও ক্ষমতার এমন জায়গায় পৌঁছে দিলেন, যেখানে মানুষ তাঁর কাছে সাহায্যের জন্য আসত।\n\nতারপর একদিন তাঁর ভাইয়েরাও তাঁর সামনে এসে দাঁড়াল।\n\nতারা তাঁকে চিনতে পারেনি।\n\nইউসুফ চাইলে প্রতিশোধ নিতে পারতেন।\n\n## চাইলে বলতে পারতেন—\n\n“তোমরা আমাকে কূপে ফেলে দিয়েছিলে। আজ তোমাদের সেই শাস্তি আমি দেব।”\n\nকিন্তু ইউসুফ তা করলেন না।\n\nতিনি প্রতিশোধের বদলে ক্ষমাকে বেছে নিলেন।\n\nতিনি তাদের ক্ষমা করে দিলেন।\n\n## 🌿 শিক্ষাটি কী?\n\nজীবনে কখনো এমন সময় আসতে পারে, যখন মনে হবে চারদিকে শুধু অন্ধকার।\n\nআপন মানুষ কষ্ট দিতে পারে।\n\nবন্ধু বিশ্বাসঘাতকতা করতে পারে।\n\nঅন্যায়ভাবে কেউ তোমাকে নিচে নামিয়ে দিতে পারে।\n\nকিন্তু মনে রেখো—\n\nকূপের অন্ধকারও আল্লাহর দৃষ্টি থেকে লুকানো নয়।\n\nতুমি যেখানে শেষ দেখতে পাচ্ছ, আল্লাহ হয়তো সেখান থেকেই তোমার নতুন শুরু লিখছেন।\n\nতাই বিপদে ভেঙে পড়ো না।\n\nঅন্যায়ের জবাবে অন্যায় করো না।\n\nআর আল্লাহর ওপর বিশ্বাস হারিয়ো না।\n\nকারণ ইউসুফ (আ.)-এর জীবনের মতোই, কখনো কখনো অন্ধকার কূপই মানুষকে আলোর পথে নিয়ে যায়।','\n',char(10)),0,'published',0,'2026-09-09T14:52:51.896Z','2026-09-09T14:52:51.896Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('df37e8d3-f28a-4463-afcf-41a0e6082f6e','7c7c16cd-f6f3-45f7-a004-2c20af714667','যেদিন মক্কা বিজয় হলো',replace('যেদিন মক্কা বিজয় হলো\n\nভূমিকা\n\nমক্কা—রাসুলুল্লাহ ﷺ-এর জন্মভূমি।\n\nএই শহরেই তিনি সত্যের দাওয়াত শুরু করেছিলেন। এই শহরেই তাঁকে ও তাঁর সাহাবিদের অসংখ্য নির্যাতন সহ্য করতে হয়েছিল। শেষ পর্যন্ত মুসলমানদের একটি বড় অংশকে মক্কা ছেড়ে মদিনায় হিজরত করতে হয়েছিল।\n\nকিন্তু সময় বদলাল।\n\nযে মানুষগুলো একদিন মক্কা থেকে অসহায় অবস্থায় বেরিয়ে গিয়েছিল, একদিন তারাই ফিরে আসবে—তবে প্রতিশোধ নেওয়ার জন্য নয়; বরং আল্লাহর ঘরকে শিরকের প্রতীক থেকে মুক্ত করার জন্য।\n\nসেই দিনটির নাম হয়ে গেল—\n\n- ফাতহে মক্কা—মক্কা বিজয়।\n\n---\n\n## মক্কা থেকে মদিনা\n\nরাসুলুল্লাহ ﷺ যখন মক্কায় ইসলাম প্রচার শুরু করেন, কুরাইশের অনেক নেতা তাঁর বিরোধিতা করতে থাকে।\n\nমুসলমানদের ওপর নির্যাতন বাড়তে থাকে। কেউ শারীরিকভাবে নির্যাতিত হন, কেউ সামাজিকভাবে বয়কটের শিকার হন, আবার অনেককে নিজেদের ঘরবাড়ি ছেড়ে চলে যেতে হয়।\n\nশেষ পর্যন্ত রাসুলুল্লাহ ﷺ মদিনায় হিজরত করেন।\n\nমদিনায় মুসলিম সমাজ গড়ে উঠল।\n\nবছরের পর বছর কেটে গেল।\n\nমক্কা তখনও মুসলমানদের জন্য অত্যন্ত প্রিয় একটি শহর। কারণ সেখানেই ছিল কাবা—ইবরাহিম (আ.)-এর প্রতিষ্ঠিত পবিত্র ঘর।\n\nকিন্তু কাবার চারপাশে তখন অসংখ্য মূর্তি স্থাপন করা হয়েছিল।\n\n---\n\n## হুদাইবিয়ার সন্ধি\n\n৬ হিজরিতে রাসুলুল্লাহ ﷺ সাহাবিদের নিয়ে উমরাহ করার উদ্দেশ্যে মক্কার দিকে যাত্রা করেন। কিন্তু কুরাইশ তাদের মক্কায় প্রবেশ করতে দেয়নি।\n\nআলোচনার পর হুদাইবিয়ায় একটি শান্তিচুক্তি হয়।\n\nপ্রথম দেখায় চুক্তির কিছু শর্ত মুসলমানদের জন্য কঠিন মনে হয়েছিল। কিন্তু আল্লাহ এই ঘটনাকে “স্পষ্ট বিজয়” হিসেবে উল্লেখ করেন সূরা আল-ফাতহে।\n\nএই শান্তির সময় ইসলামের দাওয়াত আরও বিস্তৃত হওয়ার সুযোগ পেল।\n\nকিন্তু কিছুদিন পর সেই শান্তিচুক্তি ভেঙে যায়।\n\n---\n\n## মক্কার দিকে যাত্রা\n\n৮ হিজরির রমজান মাস।\n\nরাসুলুল্লাহ ﷺ প্রায় দশ হাজার মুসলিম নিয়ে মদিনা থেকে মক্কার দিকে রওনা হলেন।\n\nএবার মক্কা বুঝতে পারল—মুসলমানরা বিশাল শক্তি নিয়ে এগিয়ে আসছে।\n\nকিন্তু রাসুলুল্লাহ ﷺ-এর উদ্দেশ্য ছিল না মক্কার সাধারণ মানুষকে ধ্বংস করা।\n\nতিনি চেয়েছিলেন মক্কাকে শান্তিপূর্ণভাবে ইসলামের অধীনে আনতে।\n\nমুসলিম বাহিনী মক্কার কাছে পৌঁছালে রাতের অন্ধকারে অসংখ্য আগুন জ্বলতে দেখা গেল। এত আগুন দেখে আবু সুফিয়ান বিস্মিত হয়ে গেলেন।\n\nতাঁকে মুসলিম শিবিরে নিয়ে আসা হলো।\n\nসেখানে তিনি রাসুলুল্লাহ ﷺ-এর সঙ্গে সাক্ষাৎ করেন এবং ইসলাম গ্রহণ করেন।\n\n---\n\n## মক্কায় প্রবেশ\n\nঅবশেষে সেই সকাল এলো।\n\nরাসুলুল্লাহ ﷺ মক্কার দিকে এগিয়ে গেলেন।\n\nমুসলিম বাহিনী বিভিন্ন দিক দিয়ে মক্কায় প্রবেশ করল। সহিহ বুখারির বর্ণনায় রয়েছে, রাসুলুল্লাহ ﷺ নিজে এক দিক দিয়ে প্রবেশ করেন এবং খালিদ ইবনুল ওয়ালিদ (রা.)-কে মক্কার অন্য একটি দিক দিয়ে প্রবেশের নির্দেশ দেওয়া হয়েছিল।\n\nতবে কিছু জায়গায় সংঘর্ষ হয়েছিল এবং কয়েকজন নিহত হন। তাই ঘটনাটিকে সম্পূর্ণ রক্তপাতহীন বলা ঠিক নয়।\n\nকিন্তু সামগ্রিকভাবে মক্কার বিজয় খুব দ্রুত সম্পন্ন হয়।\n\nরাসুলুল্লাহ ﷺ মক্কায় প্রবেশ করলেন।\n\nযে শহর একদিন তাঁকে বের করে দিয়েছিল—\n\nআজ সেই শহর তাঁর সামনে।\n\n---\n\n## বিজয়ের মুহূর্ত\n\nএই মুহূর্তটি ছিল অসাধারণ।\n\nএকজন সাধারণ বিজয়ী হলে হয়তো অহংকারে মাথা উঁচু করতেন।\n\nকিন্তু রাসুলুল্লাহ ﷺ বিজয়ের সময়ও বিনয়ী ছিলেন।\n\nতিনি মক্কায় প্রবেশ করেন এবং কাবার দিকে এগিয়ে যান।\n\nকাবার চারপাশে তখন *৩৬০টি* মূর্তি ছিল।\n\nরাসুলুল্লাহ ﷺ সেগুলো অপসারণ করতে থাকেন এবং কুরআনের আয়াত পাঠ করেন—\n\n> “সত্য এসেছে এবং মিথ্যা বিলুপ্ত হয়েছে।”\n\nসহিহ বুখারিতে এই ঘটনার স্পষ্ট বর্ণনা রয়েছে।\n\nকাবার ভেতরেও বিভিন্ন মূর্তি ও চিত্র ছিল। রাসুলুল্লাহ ﷺ সেগুলো বের করার নির্দেশ দেন। এরপর তিনি কাবার ভেতরে প্রবেশ করেন এবং তাকবির দেন।\n\nমক্কার কেন্দ্র থেকে শিরকের প্রতীকগুলো সরিয়ে দেওয়া হলো।\n\nকাবা আবার তাওহিদের কেন্দ্র হিসেবে প্রতিষ্ঠিত হলো।\n\n---\n\n## প্রতিশোধের সুযোগ\n\nকিন্তু এবার আসল পরীক্ষা ছিল অন্য জায়গায়।\n\nযারা মুসলমানদের ওপর বছরের পর বছর নির্যাতন করেছিল, তাদের অনেকেই আজ রাসুলুল্লাহ ﷺ-এর সামনে অসহায়।\n\nযারা তাঁকে মক্কা ছাড়তে বাধ্য করেছিল—\n\nআজ তাদের শহর তাঁর নিয়ন্ত্রণে।\n\nযারা মুসলমানদের বিরুদ্ধে যুদ্ধ করেছিল—\n\nআজ তাদের পরাজয় নিশ্চিত।\n\nপ্রতিশোধ নেওয়ার ক্ষমতা তাঁর হাতে ছিল।\n\nকিন্তু বিজয়ের প্রকৃত সৌন্দর্য এখানেই—\n\nক্ষমতা থাকা সত্ত্বেও অন্যায় প্রতিশোধ না নেওয়া।\n\nমক্কা বিজয়ের ঘটনায় রাসুলুল্লাহ ﷺ-এর আচরণ ছিল শৃঙ্খলা, তাওহিদ এবং আল্লাহর প্রতি বিনয়ের প্রকাশ।\n\n---\n\n## একটি নতুন অধ্যায়ের শুরু\n\nমক্কা বিজয়ের পর কাবা আর মূর্তিপূজার কেন্দ্র রইল না।\n\nতাওহিদের পতাকা দৃঢ় হলো।\n\nযে শহর থেকে ইসলামকে মুছে ফেলার চেষ্টা করা হয়েছিল, সেই শহরই ইসলামের অন্যতম প্রধান কেন্দ্র হয়ে উঠল।\n\nরাসুলুল্লাহ ﷺ-এর জীবনের এই ঘটনা শুধু একটি সামরিক বিজয় ছিল না।\n\nএটি ছিল—\n\n==অন্ধকারের ওপর আলোর বিজয়।==\n\n==শিরকের ওপর তাওহিদের বিজয়।==\n\n==অত্যাচারের ওপর সত্যের বিজয়।==\n\nআর সবচেয়ে বড় কথা—\n\n==অহংকারের ওপর বিনয়ের বিজয়।==\n\n---\n\n**মক্কা বিজয় থেকে আমাদের শিক্ষা**\n\nমক্কা বিজয় আমাদের কয়েকটি গভীর শিক্ষা দেয়।\n\n১. *ধৈর্যের ফল আসে।*\nমুসলমানরা বছরের পর বছর কষ্ট সহ্য করেছিল। কিন্তু শেষ পর্যন্ত আল্লাহ তাদের জন্য বিজয়ের দরজা খুলে দেন।\n\n২. *বিজয় মানুষকে অহংকারী করা উচিত নয়।*\nরাসুলুল্লাহ ﷺ বিজয়ের মুহূর্তেও আল্লাহর প্রতি বিনয়ী ছিলেন।\n\n৩. *সত্যকে ধরে রাখতে হয়।*\nপরিস্থিতি যত কঠিনই হোক, সত্যের পথ ছেড়ে দেওয়া উচিত নয়।\n\n৪. *ক্ষমা ও মহানুভবতা বিজয়ের সৌন্দর্য বাড়ায়।*\nশত্রুর ওপর ক্ষমতা পাওয়া সহজ; কিন্তু ক্ষমতার পর নিজেকে নিয়ন্ত্রণ করা অনেক কঠিন।\n\n৫. *আল্লাহর পরিকল্পনা মানুষের ধারণার চেয়ে বড়।*\nযে মক্কা একদিন মুসলমানদের জন্য অত্যাচারের স্থান ছিল, সেই মক্কাই পরে ইসলামের পবিত্রতম কেন্দ্রগুলোর একটি হয়ে উঠল।\n\n---\n\n## শেষ কথা\n\nএকদিন রাসুলুল্লাহ ﷺ মক্কা ছেড়েছিলেন।\n\nসেদিন তাঁর সঙ্গে ছিল ঈমান, ধৈর্য এবং আল্লাহর ওপর পূর্ণ ভরসা।\n\nকয়েক বছর পর তিনি আবার সেই মক্কায় ফিরলেন।\n\nকিন্তু এবার তিনি অসহায় অবস্থায় নন।\n\nতিনি ফিরলেন বিজয়ী হয়ে।\n\nতবুও সেই বিজয় তাঁর মধ্যে অহংকার সৃষ্টি করেনি।\n\nকারণ তিনি জানতেন—\n\n- বিজয় মানুষের শক্তিতে নয়, আল্লাহর সাহায্যে আসে।\n\nআর তাই মক্কা বিজয়ের ইতিহাস আজও আমাদের মনে করিয়ে দেয়—\n\n> সত্যের পথে ধৈর্য ধরো।\nআল্লাহর ওপর ভরসা রাখো।\nআর বিজয় এলে অহংকার নয়—কৃতজ্ঞতা প্রকাশ করো।','\n',char(10)),1,'published',0,'2026-09-09T17:21:57.190Z','2026-09-09T17:21:57.190Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('0a7419a1-8e2f-4753-bab0-038a6dfca258','74ddce58-379a-46a0-a39e-ef8c09cd1f30','বদরের প্রান্তরে বিজয়',replace('## একটি অসম যুদ্ধের সূচনা\n\nমদিনায় হিজরত করার পর মুসলমানদের জীবন সহজ হয়ে যায়নি। মক্কার কুরাইশরা তাদের ওপর নির্যাতন চালিয়েছিল, সম্পদ কেড়ে নিয়েছিল এবং নতুন গড়ে ওঠা মুসলিম সমাজের বিরুদ্ধেও শত্রুতা অব্যাহত রেখেছিল।\n\n২ হিজরির রমজান মাস।\n\nএকটি বাণিজ্য কাফেলা সিরিয়া থেকে মক্কার দিকে ফিরছিল। কাফেলাটির নেতৃত্বে ছিলেন আবু সুফিয়ান। মুসলমানরা কাফেলাটির গতিবিধি সম্পর্কে জানতে পারলেন।\n\nরাসুলুল্লাহ ﷺ সাহাবিদের নিয়ে বের হলেন।\n\nকিন্তু তাঁরা প্রথমে কোনো বিশাল যুদ্ধের প্রস্তুতি নিয়ে বের হননি। উদ্দেশ্য ছিল কাফেলার মোকাবিলা করা।\n\nঅন্যদিকে আবু সুফিয়ান পরিস্থিতি বুঝতে পেরে মক্কায় খবর পাঠালেন। কুরাইশরা কাফেলাকে রক্ষা করার জন্য একটি বড় বাহিনী পাঠাল।\n\nএরপর পরিস্থিতি বদলে গেল।\n\nএকটি কাফেলার পরিবর্তে সামনে এসে দাঁড়াল একটি সশস্ত্র কুরাইশ বাহিনী।\n\n---\n\n## বদরের দিকে যাত্রা\n\nরাসুলুল্লাহ ﷺ-এর সঙ্গে ছিলেন মাত্র প্রায় *৩১৩ জন সাহাবি।*\n\nতাদের কাছে ঘোড়া ছিল খুব অল্প এবং উটও সীমিত ছিল। অনেক সাহাবিকে পালা করে একই উটে চলতে হয়েছিল।\n\nঅন্যদিকে কুরাইশ বাহিনী ছিল প্রায় এক হাজারের কাছাকাছি।\n\nসংখ্যার দিক থেকে মুসলমানরা ছিল অনেক কম।\n\nঅস্ত্র ও যুদ্ধের প্রস্তুতির দিক থেকেও তারা শক্তিশালী অবস্থানে ছিল না।\n\nকিন্তু তাদের ছিল এমন একটি শক্তি, যা শুধু অস্ত্র দিয়ে মাপা যায় না—\n\n*ঈমান।*\n\n---\n\n## সাহাবিদের সঙ্গে পরামর্শ\n\nরাসুলুল্লাহ ﷺ সাহাবিদের সঙ্গে পরামর্শ করলেন।\n\nমুহাজির ও আনসার—দুই পক্ষের সাহাবিরাই তাঁর পাশে থাকার অঙ্গীকার করলেন।\n\nমদিনার আনসারদের পক্ষ থেকেও স্পষ্ট সমর্থন এলো।\n\nএতে রাসুলুল্লাহ ﷺ-এর মন দৃঢ় হলো।\n\nমুসলমানরা বদরের দিকে এগিয়ে গেল।\n\n---\n\n## বদরের প্রান্তর\n\nঅবশেষে দুই বাহিনী বদরের কাছে মুখোমুখি হলো।\n\nমুসলমানরা এমন একটি অবস্থানে পৌঁছাল, যেখানে পানির উৎসের নিয়ন্ত্রণ তাদের জন্য গুরুত্বপূর্ণ ছিল।\n\nআল্লাহ মুসলমানদের ওপর বৃষ্টি বর্ষণ করলেন। কুরআনে বদরের দিনের ঘটনাগুলোর প্রসঙ্গে এই বৃষ্টির কথা উল্লেখ করা হয়েছে। এটি মুসলমানদের জন্য ভূমি দৃঢ় করতে এবং তাদের প্রস্তুতিতে সহায়তা করেছিল।\n\nরাত নেমে এলো।\n\nচারপাশে যুদ্ধের উত্তেজনা।\n\nআর রাসুলুল্লাহ ﷺ আল্লাহর কাছে গভীরভাবে দোয়া করতে লাগলেন।\n\nতিনি জানতেন—\n\nসংখ্যা কম।\n\nঅস্ত্র কম।\n\nকিন্তু আল্লাহর সাহায্যই প্রকৃত শক্তি।\n\n---\n\n## যুদ্ধের সকাল\n\nসকাল হলো।\n\nদুই বাহিনী মুখোমুখি দাঁড়াল।\n\nএটি ছিল ইসলামের ইতিহাসের এক গুরুত্বপূর্ণ মুহূর্ত।\n\nমুসলমানদের সামনে ছিল মক্কার সেই কুরাইশরা, যারা বছরের পর বছর তাদের ওপর নির্যাতন চালিয়েছিল।\n\nকিন্তু যুদ্ধ শুরু হওয়ার আগে রাসুলুল্লাহ ﷺ সাহাবিদের শৃঙ্খলা বজায় রাখতে নির্দেশ দিলেন।\n\nতারপর যুদ্ধ শুরু হলো।\n\n---\n\n## মুখোমুখি সংঘর্ষ\n\nপ্রথমে কয়েকজন যোদ্ধা দ্বন্দ্বযুদ্ধে এগিয়ে এল।\n\nমুসলমানদের পক্ষ থেকে হামজা ইবন আবদুল মুত্তালিব (রা.), আলী ইবন আবি তালিব (রা.) এবং উবাইদা ইবন আল-হারিস (রা.) অংশ নেন।\n\nএরপর শুরু হলো মূল যুদ্ধ।\n\nবদরের ময়দানে মুসলমানরা নিজেদের সর্বোচ্চ চেষ্টা করলেন।\n\nকুরআনে আল্লাহ মুসলমানদের সেই কঠিন সময়ের কথা স্মরণ করিয়ে দিয়েছেন এবং বলেছেন যে তিনি তাদের সাহায্য করেছিলেন।\n\nসূরা আল-আনফালে বদরের যুদ্ধের ঘটনাগুলো বিস্তারিতভাবে আলোচিত হয়েছে।\n\n---\n\n## আল্লাহর সাহায্য\n\nমুসলমানদের সংখ্যা ছিল কম।\n\nকিন্তু তারা একা ছিল না।\n\nসূরা আল-ইমরানে আল্লাহ বলেন, বদরের যুদ্ধে মুসলমানদের সাহায্য করার জন্য ফেরেশতাদের পাঠানোর কথা।\n\nএই সাহায্য মুসলমানদের মনে সাহস ও দৃঢ়তা সৃষ্টি করেছিল।\n\nরাসুলুল্লাহ ﷺ সাহাবিদের উৎসাহিত করলেন।\n\nতাঁরা সামনে এগিয়ে গেলেন।\n\nঅবশেষে কুরাইশ বাহিনী পরাজিত হলো।\n\n---\n\n## আবু জাহলের পতন\n\nবদরের যুদ্ধে কুরাইশদের অন্যতম প্রধান নেতা ছিল আবু জাহল।\n\nসে ইসলামের সবচেয়ে কঠোর বিরোধীদের একজন ছিল।\n\nযুদ্ধের শেষ পর্যায়ে আবু জাহল গুরুতরভাবে আহত হয়।\n\nআবদুর রহমান ইবন আওফ (রা.)-এর বর্ণনায় এসেছে, দুই তরুণ আনসারি—মু‘আয ইবন আমর ইবন আল-জামুহ এবং মু‘আয ইবন আফরা—আবু জাহলের বিরুদ্ধে লড়াই করেন।\n\nপরে আবদুল্লাহ ইবন মাসউদ (রা.) তাকে মৃত্যুর কাছাকাছি অবস্থায় দেখতে পান।\n\nবদরের ময়দানেই আবু জাহলের পরিণতি ঘটে।\n\n---\n\n## যুদ্ধের পর\n\nবদরের যুদ্ধ মুসলমানদের জন্য একটি বড় বিজয়ে পরিণত হলো।\n\nকুরাইশদের অনেক যোদ্ধা নিহত হলো এবং অনেকে বন্দী হলো।\n\nমুসলমানদের মধ্যেও ১৪ জন সাহাবি শাহাদাতবরণ করেন—ছয়জন মুহাজির এবং আটজন আনসার।\n\nএই বিজয় শুধু একটি যুদ্ধের জয় ছিল না।\n\nএটি ছিল মদিনার ছোট মুসলিম সমাজের জন্য একটি বিশাল পরিবর্তনের মুহূর্ত।\n\nমক্কার কুরাইশ বুঝতে পারল—\n\nমুসলমানদের আর সহজে দুর্বল করে দেওয়া যাবে না।\n\n---\n\n## বিজয়ের প্রকৃত কারণ\n\nবদরের ঘটনা মুসলমানদের একটি গুরুত্বপূর্ণ শিক্ষা দিয়েছিল।\n\nবিজয় শুধু সংখ্যার ওপর নির্ভর করে না।\n\nমুসলমানরা সংখ্যায় কম ছিল।\n\nতবুও তারা বিজয় লাভ করেছিল।\n\nকুরআনে আল্লাহ স্মরণ করিয়ে দিয়েছেন—\n\n“তোমরা যখন দুর্বল ছিলে, তখন আল্লাহ বদরে তোমাদের সাহায্য করেছিলেন।”\n\nঅর্থাৎ মানুষের শক্তির সীমা আছে।\n\nকিন্তু আল্লাহর সাহায্যের কোনো সীমা নেই।\n\n---\n\n## বদর থেকে আমাদের শিক্ষা\n\nবদরের ইতিহাস শুধু অতীতের একটি যুদ্ধের গল্প নয়।\n\nএটি আমাদের জীবনের জন্যও শিক্ষা।\n\n*১. কঠিন পরিস্থিতিতে হতাশ হওয়া যাবে না*\n\n> পরিস্থিতি অসম্ভব মনে হলেও আল্লাহর ওপর ভরসা রাখতে হবে।\n\n*২. চেষ্টা করতে হবে*\n\n> আল্লাহর ওপর ভরসা মানে চেষ্টা ছেড়ে দেওয়া নয়। সাহাবিরা নিজেদের সর্বোচ্চ চেষ্টা করেছিলেন।\n\n*৩. ঐক্য গুরুত্বপূর্ণ*\n\n> বদরের ময়দানে সাহাবিরা রাসুলুল্লাহ ﷺ-এর নেতৃত্বে ঐক্যবদ্ধ ছিলেন।\n\n*৪. বিজয়ের পর অহংকার নয়*\n\n> বিজয় এসেছিল আল্লাহর সাহায্যে—এ বিশ্বাস মুসলমানদের মনে বিনয় সৃষ্টি করেছিল।\n\n*৫. সত্যের পথে ধৈর্য ধরতে হয়*\n\n> বদরের আগে মুসলমানরা বহু বছর নির্যাতন সহ্য করেছিলেন। কিন্তু তারা ঈমান ছেড়ে দেননি।\n\n---\n\n## শেষ কথা\n\nবদরের প্রান্তরে মুসলমানদের সামনে ছিল বিশাল এক বাহিনী।\n\nতাদের হাতে ছিল সীমিত অস্ত্র।\n\nতাদের সংখ্যা ছিল কম।\n\nকিন্তু তাদের হৃদয়ে ছিল অটুট বিশ্বাস।\n\nসেই দিন ইতিহাস প্রমাণ করেছিল—\n\nসংখ্যা সবসময় বিজয় নির্ধারণ করে না।\n\nমানুষের শক্তি সীমিত।\n\nকিন্তু আল্লাহর সাহায্য সীমাহীন।\n\nআর তাই বদরের প্রান্তর আজও মুসলমানদের মনে করিয়ে দেয়—\n\n> সত্যের পথে থাকো, নিজের সাধ্য অনুযায়ী চেষ্টা করো এবং আল্লাহর ওপর ভরসা রাখো।\n\nকারণ যখন মানুষ নিজের দুর্বলতা বুঝতে পারে, তখনই সে সবচেয়ে বেশি উপলব্ধি করতে পারে—\n\n==প্রকৃত শক্তি একমাত্র আল্লাহর কাছ থেকেই আসে।==','\n',char(10)),1,'published',0,'2026-09-10T02:57:46.209Z','2026-09-10T02:57:46.209Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('82db3a9d-40a3-49c7-b1f1-c57504e20340','8fdeb0c7-a09e-4bf2-b6a6-4457817f7a1d','সওর গুহার সেই রাত',replace('## মক্কার শেষ রাত\n\nমক্কার আকাশে তখন গভীর রাত।\n\nশহরটি বাইরে থেকে শান্ত মনে হলেও, সেই নীরবতার আড়ালে চলছিল ভয়ংকর এক ষড়যন্ত্র।\n\nকুরাইশের নেতারা সিদ্ধান্ত নিয়েছিল—মুহাম্মদ ﷺ-কে আর মক্কায় থাকতে দেওয়া হবে না।\n\nতাঁকে হত্যা করার পরিকল্পনা করা হয়েছিল।\n\nকিন্তু আল্লাহ তাঁর রাসুলকে অন্য একটি পথ দেখিয়ে দিয়েছেন।\n\nএটি ছিল মক্কা থেকে মদিনার দিকে হিজরতের সময়।\n\nরাসুলুল্লাহ ﷺ জানতেন, সামনে পথ সহজ নয়।\n\nতবুও তাঁর হৃদয়ে ছিল অটুট বিশ্বাস—\n\n==আল্লাহর সাহায্য অবশ্যই আসবে।==\n\n---\n\n## আবু বকর (রা.)-এর অপেক্ষা\n\nঅন্যদিকে আবু বকর (রা.) দীর্ঘদিন ধরে রাসুলুল্লাহ ﷺ-এর সঙ্গে মদিনায় যাওয়ার প্রত্যাশা করছিলেন।\n\nএকদিন তিনি রাসুলুল্লাহ ﷺ-এর কাছে যাওয়ার অনুমতি চাইলে তাঁকে বলা হয়েছিল অপেক্ষা করতে।\n\nআবু বকর (রা.) বুঝতে পেরেছিলেন—হয়তো সেই দিনটি খুব কাছেই।\n\nএক রাতে রাসুলুল্লাহ ﷺ আবু বকর (রা.)-এর বাড়িতে এলেন।\n\nসময়টা ছিল অস্বাভাবিক।\n\nআবু বকর (রা.) বুঝতে পারলেন, নিশ্চয়ই গুরুত্বপূর্ণ কিছু ঘটেছে।\n\nরাসুলুল্লাহ ﷺ ঘরে প্রবেশ করলেন।\n\nতারপর জানালেন—\n\n**“আমাকে হিজরতের অনুমতি দেওয়া হয়েছে।”**\n\nআবু বকর (রা.)-এর হৃদয় আনন্দে ভরে উঠল।\n\nতিনি বললেন—\n\n**“আমি কি আপনার সঙ্গে থাকব, হে আল্লাহর রাসুল?”**\n\nরাসুলুল্লাহ ﷺ তাঁকে সঙ্গে যাওয়ার অনুমতি দিলেন।\n\nএই কথাটি শুনে আবু বকর (রা.)-এর চোখে আনন্দের অশ্রু চলে এসেছিল—এমন বর্ণনাও আয়িশা (রা.)-এর হাদিসে এসেছে।\n\n---\n\n## প্রস্তুতি\n\nসবকিছু খুব গোপনে প্রস্তুত করা হলো।\n\nদুটি উট প্রস্তুত রাখা হয়েছিল।\n\nখাবার নেওয়া হলো।\n\nআসমা (রা.) খাবারের থলের মুখ বাঁধার জন্য নিজের কোমরের কাপড়ের একটি অংশ কেটে ব্যবহার করেছিলেন। এই ঘটনার কারণে তিনি “জাতুন-নিতাকাইন”—দুই কোমরবন্ধনীর অধিকারী—নামে পরিচিত হন।\n\nবাড়ির সবাই জানত—\n\nএটি শুধু একটি সফর নয়।\n\nএটি ছিল ইতিহাসের সবচেয়ে গুরুত্বপূর্ণ হিজরতগুলোর একটি।\n\n---\n\n## অন্ধকারে যাত্রা\n\nমক্কার রাত আরও গভীর হলো।\n\nরাসুলুল্লাহ ﷺ এবং আবু বকর (রা.) নীরবে বেরিয়ে পড়লেন।\n\nতাঁদের সামনে ছিল অজানা পথ।\n\nপেছনে ছিল মক্কা—তাঁদের জন্মভূমি।\n\nআর সামনে ছিল মদিনা—যেখানে ইসলামের নতুন অধ্যায় শুরু হওয়ার অপেক্ষায়।\n\nকিন্তু তাঁরা সরাসরি মদিনার পথে গেলেন না।\n\nতাঁরা প্রথমে গেলেন **সওর পাহাড়ের দিকে।**\n\nপাহাড়টি ছিল মক্কার দক্ষিণ দিকে।\n\nসেখানে ছিল একটি গুহা।\n\n**সওর গুহা।**\n\n---\n\n## গুহার ভেতর\n\nপাহাড়ের কঠিন পথ পেরিয়ে তাঁরা গুহায় পৌঁছালেন।\n\nচারপাশ অন্ধকার।\n\nবাইরে মক্কার লোকেরা তাঁদের খুঁজছে।\n\nপ্রতিটি মুহূর্ত ছিল ঝুঁকিপূর্ণ।\n\nরাসুলুল্লাহ ﷺ ও আবু বকর (রা.) সেই গুহায় আশ্রয় নিলেন।\n\nতাঁরা সেখানে তিন রাত অবস্থান করবেন।\n\nকিন্তু তাঁরা পুরোপুরি বিচ্ছিন্ন ছিলেন না।\n\nতাদের জন্য খাবার ও সংবাদ পৌঁছানোর ব্যবস্থা করা হয়েছিল।\n\n---\n\n## আবদুল্লাহর রাতের যাত্রা\n\nআবু বকর (রা.)-এর ছেলে আবদুল্লাহ (রা.) দিনের বেলায় মক্কার মানুষের সঙ্গে থাকতেন।\n\nতিনি কুরাইশের কথাবার্তা শুনতেন।\n\nতাঁদের পরিকল্পনা জানতেন।\n\nতারপর রাত হলে গোপনে সওর গুহায় গিয়ে রাসুলুল্লাহ ﷺ ও তাঁর পিতাকে সব খবর জানাতেন।\n\nসহিহ বুখারির বর্ণনা অনুযায়ী, তিনি ভোরের আগে গুহা থেকে চলে যেতেন এবং এমনভাবে মক্কায় ফিরে যেতেন যেন তিনি সারা রাত সেখানেই ছিলেন।\n\n**দৃশ্য**\n\nরাত গভীর।\n\nদূরে মক্কার আলো দেখা যাচ্ছে।\n\nআবদুল্লাহ (রা.) দ্রুত পাহাড়ের পথ ধরে গুহার দিকে এগিয়ে আসছেন।\n\nগুহায় পৌঁছে তিনি নিচু স্বরে বললেন—\n\n— “আব্বা…”\n\nআবু বকর (রা.) এগিয়ে এলেন।\n\n— “কী খবর?”\n\nআবদুল্লাহ কুরাইশের গতিবিধির কথা জানালেন।\n\nরাসুলুল্লাহ ﷺ মনোযোগ দিয়ে শুনলেন।\n\nকেউ উত্তেজিত হলেন না।\n\nকেউ আতঙ্কিত হলেন না।\n\nকারণ তাঁরা জানতেন—\n\n**আল্লাহ সবকিছু দেখছেন।**\n\n---\n\n## আমির ইবন ফুহাইরার দায়িত্ব\n\nআবু বকর (রা.)-এর মুক্তদাস আমির ইবন ফুহাইরা (রা.)-ও এই পরিকল্পনায় গুরুত্বপূর্ণ ভূমিকা পালন করেছিলেন।\n\nতিনি রাতে দুধের পশুগুলো নিয়ে গুহার কাছে আসতেন।\n\nরাসুলুল্লাহ ﷺ ও আবু বকর (রা.) সেখান থেকে দুধ পান করতেন।\n\nতারপর ভোরের আগে তিনি পশুগুলো নিয়ে চলে যেতেন।\n\nএভাবে তিন রাতই ব্যবস্থা চলেছিল।\n\nসেই অন্ধকার রাতগুলোতে পাহাড়ের নীরবতার মধ্যে শুধু বাতাসের শব্দ, পশুর চলার শব্দ আর দূরের মক্কার আবছা আলো—\n\nএর মধ্যেই এগিয়ে চলছিল ইতিহাস।\n\n---\n\n## কুরাইশের অনুসন্ধান\n\nঅন্যদিকে মক্কায় তখন তীব্র অনুসন্ধান শুরু হয়েছে।\n\nকুরাইশ জানতে পেরেছিল—\n\nমুহাম্মদ ﷺ এবং আবু বকর (রা.) মক্কা থেকে বেরিয়ে গেছেন।\n\nতাঁদের ধরতে লোক পাঠানো হলো।\n\nপাহাড়ে পাহাড়ে অনুসন্ধান শুরু হলো।\n\nপদচিহ্ন খোঁজা হলো।\n\nচারদিকে লোক ছড়িয়ে পড়ল।\n\nপ্রত্যেকের উদ্দেশ্য এক—\n\n**তাঁদের খুঁজে বের করা।**\n\n---\n\n## গুহার কাছে\n\nএকসময় অনুসন্ধানকারীরা সওর পাহাড়ের কাছাকাছি পৌঁছে গেল।\n\nআবু বকর (রা.) গুহার ভেতর থেকে তাদের উপস্থিতি টের পেলেন।\n\nতাঁর মনে উদ্বেগ তৈরি হলো।\n\nতিনি ভাবলেন—\n\nযদি তারা নিচের দিকে তাকায়?\n\nযদি তারা গুহার ভেতর দেখতে পায়?\n\nতাহলে কী হবে?\n\nসহিহ বুখারির বর্ণনায় আবু বকর (রা.) বলেছেন, তিনি আশঙ্কা করেছিলেন—তাদের কেউ যদি নিজের পায়ের নিচের দিকে তাকায়, তাহলে তারা দুজনকে দেখে ফেলবে।\n\nদৃশ্য\n\nগুহার ভেতর অন্ধকার।\n\nবাইরে মানুষের পদশব্দ।\n\nআবু বকর (রা.) খুব নিচু স্বরে বললেন—\n\n— “হে আল্লাহর রাসুল, তাদের কেউ যদি নিজের পায়ের নিচে তাকায়, তাহলে তারা আমাদের দেখে ফেলবে।”\n\nপরিস্থিতি ছিল ভয়ংকর।\n\n**কিন্তু রাসুলুল্লাহ ﷺ ছিলেন শান্ত।**\n\nতিনি তাঁর সঙ্গীকে আশ্বস্ত করলেন—\n\n> “হে আবু বকর, এমন দুইজন সম্পর্কে তোমার কী ধারণা, যাদের তৃতীয়জন আল্লাহ?”\n\nআর কুরআন সেই মুহূর্তকে আরও স্পষ্ট করে স্মরণ করিয়ে দিয়েছে:\n\n> “চিন্তা করো না, নিশ্চয়ই আল্লাহ আমাদের সঙ্গে আছেন।”\n\nএকটি ছোট গুহা।\n\nবাইরে শত্রু।\n\nভেতরে মাত্র দুজন মানুষ।\n\nকিন্তু তাঁদের ভরসা ছিল এমন একজনের ওপর—\n\n**যাঁর ক্ষমতার কোনো সীমা নেই।**\n\n---\n\n## তিন রাত\n\nদিন পেরিয়ে রাত হলো।\n\nআবার রাত পেরিয়ে দিন।\n\nতিন রাত তাঁরা সওর গুহায় অবস্থান করলেন।\n\nএই সময় আবদুল্লাহ (রা.) সংবাদ নিয়ে আসতেন।\n\nআমির ইবন ফুহাইরা (রা.) দুধ নিয়ে আসতেন।\n\nসবকিছু পরিকল্পনা অনুযায়ী চলছিল।\n\nঅবশেষে সেই সময় এলো, যখন পরবর্তী যাত্রার প্রস্তুতি সম্পূর্ণ হলো।\n\nরাসুলুল্লাহ ﷺ ও আবু বকর (রা.)-এর জন্য উট প্রস্তুত ছিল।\n\nতাঁরা একজন দক্ষ পথপ্রদর্শকও নিয়োগ করেছিলেন, যিনি প্রচলিত কুরাইশ ধর্মের ওপর থাকলেও পথ সম্পর্কে অভিজ্ঞ ছিলেন এবং তাঁদের বিশ্বাসের যোগ্য বলে বিবেচিত হয়েছিলেন।\n\nএবার শুরু হবে মদিনার পথে প্রকৃত যাত্রা।\n\n---\n\n## মক্কার বাইরে\n\nতাঁরা গুহা থেকে বের হলেন।\n\nপেছনে রয়ে গেল মক্কা।\n\nসেই শহর—\n\nযেখানে রাসুলুল্লাহ ﷺ জন্মেছিলেন।\n\nযেখানে তিনি শৈশব কাটিয়েছিলেন।\n\nযেখানে তিনি মানুষকে আল্লাহর দিকে ডাক দিয়েছিলেন।\n\nসেই শহরই তাঁকে আজ চলে যেতে বাধ্য করেছে।\n\nকিন্তু তাঁর হৃদয়ে প্রতিশোধের আগুন ছিল না।\n\nছিল আল্লাহর ওপর ভরসা।\n\n---\n\n## অজানা পথ\n\nপথপ্রদর্শক তাঁদের এমন পথ দিয়ে নিয়ে যাচ্ছিলেন, যা সাধারণ পথের চেয়ে ভিন্ন ছিল।\n\nলক্ষ্য ছিল কুরাইশের অনুসরণ এড়িয়ে মদিনায় পৌঁছানো।\n\nমরুভূমির পথ।\n\nকঠিন পাহাড়।\n\nগরম বাতাস।\n\nদীর্ঘ সফর।\n\nকিন্তু প্রত্যেকটি পদক্ষেপ তাঁদের নিয়ে যাচ্ছিল একটি নতুন ভবিষ্যতের দিকে।\n\nমদিনায় তাঁদের জন্য অপেক্ষা করছিল আনসাররা।\n\nঅপেক্ষা করছিল ইসলামের নতুন অধ্যায়।\n\n---\n\n## আবু বকর (রা.)-এর ভরসা\n\nএই পুরো যাত্রায় আবু বকর (রা.)-এর ভালোবাসা ও উদ্বেগ ছিল অসাধারণ।\n\nগুহার সেই মুহূর্তে তাঁর ভয় নিজের জন্য ছিল না।\n\nতিনি ভয় পাচ্ছিলেন রাসুলুল্লাহ ﷺ-এর নিরাপত্তার জন্য।\n\nআর রাসুলুল্লাহ ﷺ তাঁকে মনে করিয়ে দিয়েছিলেন—\n\n==আল্লাহ তাঁদের সঙ্গে আছেন।== \n\nএই কথাই হয়ে গেল হিজরতের সবচেয়ে শক্তিশালী বার্তাগুলোর একটি।\n\nকারণ মানুষ যখন চারপাশে শুধু বিপদ দেখতে পায়, তখন ঈমান তাকে এমন কিছু দেখতে শেখায়—\n\nযা চোখে দেখা যায় না।\n\n**আল্লাহর সাহায্য।**\n\n---\n\n## মদিনার পথে নতুন সকাল\n\nঅবশেষে মক্কার সীমানা অনেক দূরে চলে গেল।\n\nসামনে দীর্ঘ পথ।\n\nকিন্তু এবার আর তাঁরা মক্কার বন্দিত্বের মধ্যে নেই।\n\nহিজরত শুরু হয়েছে।\n\nএকটি শহর থেকে আরেকটি শহরের দিকে শুধু যাত্রা নয়—\n\nএটি ছিল ইসলামের ইতিহাসের এক নতুন অধ্যায়ের সূচনা।\n\nমদিনায় গিয়ে রাসুলুল্লাহ ﷺ একটি নতুন সমাজ প্রতিষ্ঠা করবেন।\n\nমসজিদ হবে কেন্দ্র।\n\nমুহাজির ও আনসার পরস্পরের ভাই হবে।\n\nইসলামের দাওয়াত আরও বিস্তৃত হবে।\n\nকিন্তু সেই বিশাল ভবিষ্যতের শুরু হয়েছিল একটি ছোট গুহা থেকে।\n\nসওর গুহার সেই অন্ধকার রাত থেকে।\n\n---\n\n## ইতিহাসের সেই শিক্ষা\n\nসওর গুহার ঘটনা আমাদের একটি গভীর সত্য শেখায়।\n\nআল্লাহর ওপর ভরসা করার অর্থ বিপদকে অস্বীকার করা নয়।\n\nরাসুলুল্লাহ ﷺ ও আবু বকর (রা.) সতর্কতা নিয়েছিলেন।\n\nগোপনে বেরিয়েছেন।\n\nগুহায় আশ্রয় নিয়েছেন।\n\nখাবারের ব্যবস্থা করেছেন।\n\nসংবাদ সংগ্রহ করেছেন।\n\nদক্ষ পথপ্রদর্শক নিয়েছেন।\n\nঅর্থাৎ তাঁরা নিজেদের সাধ্যের সর্বোচ্চ চেষ্টা করেছিলেন।\n\nতারপর ফলাফলের দায়িত্ব আল্লাহর ওপর ছেড়ে দিয়েছিলেন।\n\nএটাই প্রকৃত ==তাওয়াক্কুল।==\n\n---\n\n## শেষ দৃশ্য\n\nমক্কা তখন অনেক দূরে।\n\nসূর্য ধীরে ধীরে মরুভূমির ওপর আলো ছড়াচ্ছে।\n\nরাসুলুল্লাহ ﷺ সামনে এগিয়ে যাচ্ছেন।\n\nআবু বকর (রা.) তাঁর সঙ্গে।\n\nপেছনে ফেলে এসেছেন জন্মভূমি।\n\nসামনে অপেক্ষা করছে মদিনা।\n\nআর ইতিহাসের পাতায় লেখা হয়ে যাচ্ছে এক অমর শিক্ষা—\n\n**মানুষের পথ বন্ধ হয়ে গেলেও আল্লাহর পথ কখনো বন্ধ হয় না।**\n\nসওর গুহা ছিল অন্ধকার।\n\nকিন্তু সেই অন্ধকারের ভেতরেই ছিল আল্লাহর ওপর পূর্ণ ভরসার আলো।\n\nআর সেই রাত আজও আমাদের মনে করিয়ে দেয়—\n\n> “চিন্তা করো না—নিশ্চয়ই আল্লাহ আমাদের সঙ্গে আছেন।”\n\nএই কথাই ছিল সেই রাতের শক্তি।\n\nএই কথাই ছিল হিজরতের সাহস।\n\nআর এই কথাই হয়ে রইল কিয়ামত পর্যন্ত মুমিনদের জন্য এক গভীর শিক্ষা।','\n',char(10)),1,'published',0,'2026-09-10T03:17:24.376Z','2026-09-10T03:17:24.376Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('8d048bd4-e533-4619-a6f1-a98e6efdc1fc','4603dfa0-d90d-4f27-8850-8cb13502c633','কেউই পাগল নয় (No One’s Crazy)',replace('## অধ্যায় ১: কেউই পাগল নয়\n\nটাকা নিয়ে মানুষের আচরণ অনেক সময় আমাদের কাছে অদ্ভুত মনে হতে পারে। কেউ খুব বেশি সঞ্চয় করে, কেউ আবার হাতে টাকা এলেই খরচ করে ফেলে। কেউ বিনিয়োগে বড় ঝুঁকি নিতে প্রস্তুত, আবার কেউ সামান্য ঝুঁকিতেও ভয় পায়।\n\nকিন্তু **কোনো মানুষের আর্থিক সিদ্ধান্তকে শুধু বাইরে থেকে দেখে পাগলামি বা অযৌক্তিকতা বলা যায় না।** কারণ প্রত্যেক মানুষ তার নিজের জীবনের অভিজ্ঞতা থেকে টাকা সম্পর্কে ধারণা তৈরি করে।\n\n## আমাদের অভিজ্ঞতাই আমাদের সিদ্ধান্তকে প্রভাবিত করে\n\nএকজন মানুষ যদি ছোটবেলা থেকেই অর্থের অভাব দেখে বড় হয়, তাহলে তার কাছে টাকা মানে হতে পারে **নিরাপত্তা ও ভবিষ্যতের নিশ্চয়তা।** সে হয়তো বেশি সঞ্চয় করতে চাইবে এবং ঝুঁকিপূর্ণ বিনিয়োগ এড়িয়ে চলবে।\n\nঅন্যদিকে, যে মানুষ আর্থিকভাবে স্বচ্ছল পরিবেশে বড় হয়েছে, তার কাছে ঝুঁকি নেওয়া তুলনামূলকভাবে স্বাভাবিক হতে পারে। সে হয়তো ব্যবসা বা বিনিয়োগে টাকা ব্যবহার করতে বেশি আগ্রহী হবে।\n\nদুজন মানুষের সিদ্ধান্ত সম্পূর্ণ আলাদা হলেও, **দুজনের কাছেই তাদের সিদ্ধান্ত যুক্তিসঙ্গত হতে পারে।** কারণ তারা একই জীবন দেখেনি এবং তাদের অভিজ্ঞতাও এক নয়।\n\n## একই টাকা, ভিন্ন সিদ্ধান্ত\n\nধরুন, দুজন মানুষের হাতে একই পরিমাণ টাকা আছে।\n\nপ্রথম ব্যক্তি ভাবতে পারে, “টাকাটা নিরাপদে রেখে দেওয়াই ভালো। ভবিষ্যতে কী হবে, তা আমি জানি না।”\n\nদ্বিতীয় ব্যক্তি ভাবতে পারে, “টাকাটা বিনিয়োগ করলে ভবিষ্যতে এর মূল্য আরও বাড়তে পারে।”\n\nকে সঠিক?\n\nএর কোনো সহজ উত্তর নেই। কারণ প্রত্যেক মানুষের **আয়, বয়স, পরিবার, লক্ষ্য, অভিজ্ঞতা এবং ঝুঁকি নেওয়ার ক্ষমতা** আলাদা।\n\nতাই অন্য কারও আর্থিক সিদ্ধান্তকে নিজের পরিস্থিতির সঙ্গে তুলনা করে বিচার করা ঠিক নয়।\n\n## সময়ের প্রভাব\n\nআমরা যে সময়ে বড় হই, সেই সময়ের অর্থনৈতিক পরিস্থিতিও আমাদের চিন্তাভাবনাকে গভীরভাবে প্রভাবিত করতে পারে।\n\nঅর্থনৈতিক মন্দা, বেকারত্ব, মূল্যস্ফীতি, বাজারের বড় পতন কিংবা পরিবারের আর্থিক সংকট—এসব ঘটনা মানুষের মনে দীর্ঘস্থায়ী প্রভাব ফেলতে পারে।\n\nযে ব্যক্তি জীবনে বড় ধরনের অর্থনৈতিক সংকট দেখেছে, তার কাছে ঝুঁকি খুব ভয়ের বিষয় হতে পারে। আবার যে ব্যক্তি দীর্ঘ সময় ধরে বাজারের উন্নতি দেখেছে, তার কাছে বিনিয়োগের ঝুঁকি তুলনামূলকভাবে সহজ মনে হতে পারে।\n\n## অন্যকে বিচার করার আগে\n\nআমরা প্রায়ই অন্য মানুষের আর্থিক সিদ্ধান্তকে নিজের অভিজ্ঞতার ভিত্তিতে বিচার করি। কিন্তু **একজন মানুষের কাছে যে সিদ্ধান্তটি ভুল মনে হয়, অন্য একজনের কাছে সেটিই হয়তো সবচেয়ে নিরাপদ সিদ্ধান্ত।**\n\nকারণ আমরা অন্য মানুষের জীবনের সম্পূর্ণ গল্প জানি না।\n\nতার পরিবার কেমন ছিল, সে কী ধরনের অর্থনৈতিক পরিস্থিতির মধ্য দিয়ে গেছে, জীবনে কী হারিয়েছে বা কী অর্জন করেছে—এসব বিষয় তার অর্থনৈতিক আচরণকে প্রভাবিত করতে পারে।\n\n## অধ্যায়ের মূল শিক্ষা\n\n**টাকার ব্যাপারে মানুষের আচরণ শুধু গণিত বা যুক্তি দিয়ে বোঝা যায় না।** মানুষের আবেগ, ভয়, আত্মবিশ্বাস, অতীতের অভিজ্ঞতা এবং ভবিষ্যৎ সম্পর্কে তার ধারণাও আর্থিক সিদ্ধান্তে গুরুত্বপূর্ণ ভূমিকা রাখে।\n\nতাই অন্য কেউ কীভাবে টাকা খরচ করছে, কতটা সঞ্চয় করছে বা কোথায় বিনিয়োগ করছে—তা দেখে দ্রুত তাকে বিচার করা উচিত নয়।\n\n**প্রত্যেক মানুষ তার নিজের জীবনের গল্পের ভিত্তিতে অর্থকে দেখে এবং সিদ্ধান্ত নেয়।**\n\n## মূল কথা\n\n> **কেউই পাগল নয়। আমরা প্রত্যেকে নিজের দেখা পৃথিবী, নিজের অভিজ্ঞতা এবং নিজের পরিস্থিতির ভিত্তিতে অর্থ নিয়ে সিদ্ধান্ত নিই।**','\n',char(10)),1,'published',0,'2026-09-12T08:08:56.744Z','2026-09-12T08:08:56.744Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('99e16e46-4bfd-423a-8ad3-556de5cfda83','4603dfa0-d90d-4f27-8850-8cb13502c633','অধ্যায় ২',replace('## অধ্যায় ২: ভাগ্য ও ঝুঁকি\n\n## Luck & Risk\n\nজীবনে আমরা অনেক সময় কারও সাফল্য দেখে মনে করি, সে নিশ্চয়ই খুব ভালো সিদ্ধান্ত নিয়েছিল। আবার কেউ ব্যর্থ হলে ধরে নিই, সে নিশ্চয়ই ভুল করেছে। কিন্তু বাস্তবতা এতটা সহজ নয়।\n\n**সাফল্য ও ব্যর্থতার পেছনে শুধু দক্ষতা বা সিদ্ধান্ত নয়, ভাগ্য ও ঝুঁকিও গুরুত্বপূর্ণ ভূমিকা পালন করে।**\n\n## ভাগ্য এবং ঝুঁকি\n\nএকজন মানুষ অনেক ভালো পরিকল্পনা করেও ব্যর্থ হতে পারে। আবার অন্য একজন তুলনামূলকভাবে সাধারণ সিদ্ধান্ত নিয়েও অসাধারণ সাফল্য পেতে পারে।\n\nএর কারণ হলো, আমাদের জীবনের সবকিছু আমাদের নিয়ন্ত্রণে থাকে না।\n\nবাজারের পরিস্থিতি, অর্থনৈতিক পরিবর্তন, সময়, সুযোগ, মানুষের সঙ্গে পরিচয় এবং নানা অপ্রত্যাশিত ঘটনা আমাদের ফলাফলকে প্রভাবিত করতে পারে।\n\nতাই কোনো সফল মানুষকে দেখে তার প্রতিটি সিদ্ধান্তকে নিখুঁত মনে করা যেমন ভুল, তেমনি কোনো ব্যর্থ মানুষকে দেখে তার সব সিদ্ধান্তকে ভুল মনে করাও ভুল।\n\n## একই সিদ্ধান্ত, ভিন্ন ফলাফল\n\nদুজন মানুষ একই ধরনের সিদ্ধান্ত নিতে পারে। একজন সফল হতে পারে, অন্যজন ব্যর্থ হতে পারে।\n\nএখানে প্রশ্ন হলো—**সিদ্ধান্তটি ভালো ছিল, নাকি ফলাফল ভালো হয়েছে?**\n\nএই দুটো বিষয় এক নয়।\n\nএকটি ভালো সিদ্ধান্ত থেকেও খারাপ ফলাফল আসতে পারে। আবার একটি খারাপ সিদ্ধান্ত থেকেও কখনো ভালো ফলাফল আসতে পারে।\n\nতাই শুধু ফলাফল দেখে সিদ্ধান্তের মান বিচার করা উচিত নয়।\n\n## সাফল্যের গল্প থেকে সাবধান\n\nআমরা সাধারণত সফল মানুষের গল্প বেশি শুনি। তারা কীভাবে টাকা উপার্জন করেছে, কোথায় বিনিয়োগ করেছে এবং কীভাবে বড় হয়েছে—এসব নিয়ে অনেক আলোচনা হয়।\n\nকিন্তু একই ধরনের সিদ্ধান্ত নিয়ে যারা সফল হতে পারেনি, তাদের গল্প আমরা খুব কম শুনি।\n\nফলে আমাদের মনে হতে পারে, সফল ব্যক্তির পদ্ধতিই সাফল্যের নিশ্চিত সূত্র।\n\n**কিন্তু সাফল্যের গল্পের পাশাপাশি ব্যর্থতার গল্পও দেখা জরুরি।**\n\nকারণ এতে বোঝা যায় কোন অংশটি দক্ষতার ফল এবং কোন অংশটি ভাগ্য বা পরিস্থিতির প্রভাব।\n\n## ঝুঁকি কখনো পুরোপুরি এড়ানো যায় না\n\nঅর্থের জগতে ঝুঁকি সবসময় থাকবে।\n\nআপনি যতই ভালো পরিকল্পনা করুন না কেন, ভবিষ্যৎ সম্পর্কে শতভাগ নিশ্চিত হওয়া সম্ভব নয়।\n\nতাই লক্ষ্য হওয়া উচিত ঝুঁকি পুরোপুরি দূর করা নয়। বরং এমনভাবে সিদ্ধান্ত নেওয়া, যাতে অপ্রত্যাশিত ঘটনা ঘটলেও আপনি টিকে থাকতে পারেন।\n\n**আর্থিক জীবনে টিকে থাকা অনেক সময় সর্বোচ্চ লাভের চেয়ে বেশি গুরুত্বপূর্ণ।**\n\n## নিজের সাফল্যকেও সঠিকভাবে দেখুন\n\nআমরা নিজেদের সফলতার ক্ষেত্রে দক্ষতাকে বেশি গুরুত্ব দিতে পারি এবং ব্যর্থতার ক্ষেত্রে পরিস্থিতি বা ভাগ্যকে দোষ দিতে পারি।\n\nকিন্তু নিজের ক্ষেত্রেও একই দৃষ্টিভঙ্গি প্রয়োগ করা উচিত।\n\nসাফল্যের জন্য নিজের দক্ষতার পাশাপাশি ভাগ্যের ভূমিকা স্বীকার করা দরকার। একইভাবে ব্যর্থতার সময় বুঝতে হবে—সব ব্যর্থতা যে নিজের ভুলের কারণে হয়েছে, এমন নয়।\n\n## অধ্যায়ের মূল শিক্ষা\n\n**সাফল্য মানেই শুধু দক্ষতা নয় এবং ব্যর্থতা মানেই শুধু ভুল নয়।**\n\nভাগ্য ও ঝুঁকি আমাদের আর্থিক জীবনে গুরুত্বপূর্ণ ভূমিকা পালন করে। তাই অন্যের সাফল্য দেখে অতিরিক্ত আত্মবিশ্বাসী হওয়া বা অন্যের ব্যর্থতা দেখে তাকে অবমূল্যায়ন করা উচিত নয়।\n\n## মূল কথা\n\n> **জীবনে আমরা যে ফলাফল পাই, তার পেছনে দক্ষতার পাশাপাশি ভাগ্য ও ঝুঁকিরও ভূমিকা থাকে। তাই সিদ্ধান্তকে শুধু ফলাফল দিয়ে বিচার না করে, সিদ্ধান্ত নেওয়ার সময়কার পরিস্থিতিটাকেও বিবেচনা করা উচিত।**','\n',char(10)),2,'published',0,'2026-09-12T08:10:13.479Z','2026-09-12T08:10:13.479Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('fba00058-fc45-4cb5-bab0-dd3dc9bc5faa','b7d02932-afe2-4a31-b220-95a82c37148c','বৃষ্টিভেজা শহরে তোমার অপেক্ষায়',replace('## বৃষ্টিভেজা শহরে তোমার অপেক্ষায়\n\nবৃষ্টি নামলে নীলার মনটা কেমন যেন হয়ে যেত।\n\n`শহরের ব্যস্ত রাস্তাগুলো যখন বৃষ্টির পানিতে ভিজে চকচক করত, নীলা তখন জানালার পাশে বসে এক কাপ চা হাতে নিয়ে বাইরে তাকিয়ে থাকত।`\n\n> তার একটা অভ্যাস ছিল।\n\nপ্রতিদিন সন্ধ্যা সাতটায় ফোনটা হাতে নিয়ে একটা নামের দিকে তাকানো।\n\nআরিয়ান।\n\nকিন্তু সেই নামের পাশে আর কোনো নতুন মেসেজ আসত না।\n\nআজও না।\n\n---\n\n**প্রথম দেখা**\n\nতিন বছর আগে বিশ্ববিদ্যালয়ের লাইব্রেরিতে তাদের প্রথম দেখা।\n\nনীলা একটা বই খুঁজছিল। অনেকক্ষণ তাকিয়েও বইটা পাচ্ছিল না।\n\nপেছন থেকে একটা কণ্ঠ ভেসে এলো—\n\n— “আপনি কি এই বইটাই খুঁজছেন?”\n\nনীলা ঘুরে তাকাল।\n\nএকজন ছেলে হাতে বইটা ধরে দাঁড়িয়ে আছে।\n\n— “হ্যাঁ।”\n\n— “তাহলে মনে হয় বইটা আপনাকেই খুঁজছিল।”\n\nনীলা ভ্রু কুঁচকে তাকাল।\n\n— “বই আবার কাউকে খোঁজে নাকি?”\n\nআরিয়ান হেসে বলল,\n\n— “ভালো বইয়েরও তো পছন্দ থাকতে পারে।”\n\nনীলা হাসি আটকাতে পারল না।\n\nসেদিনই প্রথম তাদের কথা।\n\nতারপর ধীরে ধীরে লাইব্রেরির টেবিল থেকে শুরু হলো বন্ধুত্ব।\n\nবন্ধুত্ব থেকে অভ্যাস।\n\nআর একসময়—\n\nঅজান্তেই ভালোবাসা।\n\n---\n\n**সেই বিকেল**\n\nএকদিন বিশ্ববিদ্যালয়ের ছাদে দাঁড়িয়ে নীলা আকাশ দেখছিল।\n\nআরিয়ান পাশে এসে দাঁড়াল।\n\n— “কী দেখছ?”\n\n— “মেঘ।”\n\n— “মেঘের মধ্যে কী আছে?”\n\nনীলা একটু চুপ করে বলল,\n\n— “কিছু মানুষ থাকে, যাদের সামনে থাকলে কিছু বলতে হয় না।”\n\nআরিয়ান তার দিকে তাকাল।\n\n— “আমি কি সেই মানুষ?”\n\nনীলা মুখ ঘুরিয়ে ফেলল।\n\n— “জানি না।”\n\nআরিয়ান হেসে বলল,\n\n— “তাহলে একদিন জানাবে।”\n\nনীলা সেদিন কোনো উত্তর দেয়নি।\n\nকিন্তু তার নীরবতাই ছিল উত্তর।\n\n---\n\n**হঠাৎ দূরত্ব**\n\nসবকিছু ঠিকঠাক চলছিল।\n\nতারপর একদিন আরিয়ান হঠাৎ নীলাকে বলল—\n\n— “আমাদের কিছুদিন যোগাযোগ না রাখাই ভালো।”\n\nনীলা অবাক হয়ে গেল।\n\n— “কেন?”\n\n— “কিছু পারিবারিক সমস্যা আছে।”\n\n— “আমি কি জানতে পারি?”\n\nআরিয়ান মাথা নিচু করল।\n\n— “এখন না।”\n\nসেদিন নীলা অনেকক্ষণ চুপ করে ছিল।\n\nতারপর শুধু বলেছিল—\n\n— “ঠিক আছে।”\n\nকিন্তু সেই “ঠিক আছে”-এর ভেতরে কতটা কষ্ট ছিল, আরিয়ান হয়তো বুঝতে পারেনি।\n\nএরপর দিন গেল।\n\nসপ্তাহ গেল।\n\nমাস গেল।\n\nআরিয়ান আর ফোন করল না।\n\nনীলা অপেক্ষা করল।\n\nপ্রথমে প্রতিদিন।\n\nতারপর সপ্তাহে একদিন।\n\nশেষে শুধু বৃষ্টির দিনে।\n\n---\n\n**তিন বছর পর**\n\nএক সন্ধ্যায় প্রচণ্ড বৃষ্টি হচ্ছিল।\n\nনীলা জানালার পাশে বসে ছিল।\n\nহঠাৎ ফোনটা বেজে উঠল।\n\nঅচেনা নম্বর।\n\nসে ফোন ধরল।\n\nওপাশ থেকে কয়েক সেকেন্ড কোনো কথা নেই।\n\nতারপর সেই পরিচিত কণ্ঠ—\n\n— “বৃষ্টি হচ্ছে?”\n\nনীলার হাত কেঁপে উঠল।\n\nসে কিছু বলতে পারল না।\n\nকণ্ঠটা আবার বলল—\n\n— “নীলা?”\n\nনীলার চোখ দিয়ে পানি গড়িয়ে পড়ল।\n\n— “হ্যাঁ।”\n\n— “আমি ফিরে এসেছি।”\n\nনীলা অনেকক্ষণ চুপ করে থেকে বলল,\n\n— “এতদিন কোথায় ছিলে?”\n\nওপাশে নীরবতা।\n\nতারপর আরিয়ান বলল—\n\n— “তোমাকে ছেড়ে যাইনি। তোমাকে হারানোর ভয়েই দূরে গিয়েছিলাম।”\n\n— “তাহলে ফিরে এলে কেন?”\n\nআরিয়ান ধীরে বলল,\n\n— “কারণ বুঝেছি, কিছু মানুষকে হারানোর ভয় যতই থাকুক, তাদের ছাড়া জীবনটা আরও ভয়ংকর।”\n\n---\n\n**আবার দেখা**\n\nপরদিন বিকেলে তারা সেই পুরোনো লাইব্রেরির সামনে দেখা করল।\n\nনীলা দূর থেকে আরিয়ানকে দেখল।\n\nতিন বছর আগের সেই মানুষটা।\n\n==শুধু চোখ দুটো একটু বেশি ক্লান্ত।==\n\nআরিয়ান কাছে এসে দাঁড়াল।\n\n— “অনেক বদলে গেছ।”\n\nনীলা মৃদু হেসে বলল,\n\n— “তুমিও।”\n\n— “রাগ করেছ?”\n\n— “অনেক।”\n\n— “ক্ষমা করবে?”\n\nনীলা কিছুক্ষণ তার দিকে তাকিয়ে রইল।\n\nতারপর বলল—\n\n— “জানি না।”\n\nআরিয়ান মাথা নিচু করল।\n\nনীলা কয়েক পা এগিয়ে গিয়ে আবার থামল।\n\nপেছনে ফিরে বলল—\n\n— “তবে একটা কথা জানি।”\n\n— “কী?”\n\n— “তোমার জন্য অপেক্ষা করা বন্ধ করতে পারিনি।”\n\nআরিয়ান কিছু বলল না।\n\nশুধু মৃদু হাসল।\n\nবাইরে তখন আবার বৃষ্টি শুরু হয়েছে।\n\nতারা দুজন পাশাপাশি হাঁটতে শুরু করল।\n\nকেউ কাউকে হাত ধরে টানেনি।\n\nকোনো বড় প্রতিশ্রুতিও দেওয়া হয়নি।\n\n==শুধু তিন বছর পর==\n\nদুজন মানুষ আবার একই পথে হাঁটছিল।\n\nআর কখনো কখনো ভালোবাসার জন্য এতটুকুই যথেষ্ট।\n\nএকসঙ্গে হাঁটার জন্য একজন মানুষকে আবার ফিরে পাওয়া।','\n',char(10)),1,'published',0,'2026-09-24T15:10:12.044Z','2026-09-24T15:10:12.044Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('1b07b4aa-3861-44b3-8e37-2a8fdfe173aa','ae5710ac-1676-4745-8b19-266661e9d69f','পর্ব নাম্বার - 1',replace('## সেদিন বিকেলটা অন্যরকম ছিল।\n> সকাল থেকেই আকাশটা মেঘলা। মাঝে মাঝে ঠান্ডা বাতাস এসে বিশ্ববিদ্যালয়ের পুরোনো কৃষ্ণচূড়া গাছের পাতাগুলো নাড়িয়ে দিচ্ছিল। মনে হচ্ছিল, যেকোনো মুহূর্তে বৃষ্টি নামবে।\nরায়ান লাইব্রেরির সামনে দাঁড়িয়ে আকাশের দিকে তাকিয়ে ছিল। হাতে একটা বই, অথচ বইটার দিকে তার কোনো মনোযোগ ছিল না।\nপেছন থেকে তানভীর এসে বলল,\n— আবার আকাশ দেখছিস কেন?\nরায়ান ফিরে তাকিয়ে মৃদু হাসল।\n— বৃষ্টি আসবে মনে হচ্ছে।\n— বৃষ্টি আসবে কি না সেটা আবহাওয়া অফিস বলবে। তুই এত চিন্তা করছিস কেন?\n— কিছু না।\nতানভীর কয়েক সেকেন্ড তার দিকে তাকিয়ে থেকে বলল,\n— তোর এই ‘কিছু না’ কথাটার মধ্যেই সবচেয়ে বেশি কিছু থাকে।\nরায়ান আর কিছু বলল না। লাইব্রেরির দরজা ঠেলে ভেতরে ঢুকে গেল।\nপুরোনো বইয়ের গন্ধটা তার ভালো লাগত। বাইরে যতই কোলাহল থাকুক, লাইব্রেরিতে ঢুকলেই মনে হতো পৃথিবীটা একটু ধীরে চলছে।\nসে জানালার পাশের একটা টেবিলে বসে বই খুলল।\nকয়েক মিনিট পর হঠাৎ দরজা খোলার শব্দ হলো।\nএকজন মেয়ে তাড়াহুড়ো করে ভেতরে ঢুকল। তার হাতে বেশ কয়েকটা বই। বৃষ্টির আগে হয়তো দ্রুত বই নিয়ে বের হয়ে যেতে চাইছিল।\nকিন্তু দরজার পাশের ছোট্ট সিঁড়িতে পা আটকে গেল।\nমুহূর্তের মধ্যে বইগুলো মেঝেতে ছড়িয়ে পড়ল।\nমেয়েটা বিরক্ত মুখে বইগুলোর দিকে তাকিয়ে রইল।\nরায়ান উঠে দাঁড়াল।\n— সাবধানে।\nসে নিচু হয়ে বইগুলো তুলে দিতে লাগল।\nমেয়েটাও একই সময়ে একটা বই তুলতে গিয়ে রায়ানের হাতের সঙ্গে হাত ছুঁয়ে ফেলল।\nদুজনেই এক মুহূর্ত থেমে গেল।\nমেয়েটা হাত সরিয়ে নিয়ে বলল,\n— সরি।\n— না, ঠিক আছে।\nরায়ান বইগুলো গুছিয়ে তার হাতে দিল।\nমেয়েটা মৃদু হেসে বলল,\n— ধন্যবাদ।\nতারপর চলে যেতে গিয়েও থেমে গেল।\nরায়ানের চোখ পড়ল তার হাতে থাকা বইটির দিকে।\n— বইটা ভালো।\nমেয়েটা ফিরে তাকাল।\n— আপনি পড়েছেন?\n— অনেক আগে।\n— কেমন লেগেছিল?\nরায়ান একটু ভেবে বলল,\n— শেষ করার পর মনে হয়েছিল, গল্পটা এত তাড়াতাড়ি শেষ হয়ে গেল কেন?\nমেয়েটা হেসে বলল,\n— সব গল্পের তো একটা শেষ থাকে।\nরায়ান তার দিকে তাকিয়ে বলল,\n— সব গল্পের?\nমেয়েটা কয়েক সেকেন্ড চুপ করে থেকে বলল,\n— কিছু গল্পের শেষ হয় না। শুধু মানুষগুলো আলাদা হয়ে যায়।\nকথাটা বলে সে চলে গেল।\nরায়ান কিছুক্ষণ সেদিকেই তাকিয়ে রইল।\nতানভীর কখন তার পাশে এসে দাঁড়িয়েছে, সে খেয়ালই করেনি।\n— কী হলো?\nরায়ান চমকে তাকাল।\n— কিছু না।\nতানভীর হেসে বলল,\n— আবার সেই ‘কিছু না’!\nরায়ান বিরক্ত হয়ে বলল,\n— চুপ কর।\nকিন্তু তার মন আর বইয়ের পাতায় ফিরল না।\nকিছুক্ষণ পর জানালার বাইরে তাকিয়ে দেখল, বৃষ্টি শুরু হয়ে গেছে।\nমেয়েটা লাইব্রেরির দরজার কাছে দাঁড়িয়ে। হাতে একটা ছাতা, কিন্তু ছাতাটা খুলছে না।\nকয়েকবার চেষ্টা করেও ব্যর্থ হয়ে সে বিরক্ত মুখে ছাতাটার দিকে তাকিয়ে আছে।\nরায়ান নিজের ছাতাটা হাতে নিয়ে বাইরে গেল।\n— সাহায্য লাগবে?\nমেয়েটা তাকিয়ে একটু হেসে বলল,\n— মনে হচ্ছে আমার ছাতাটা আজ আমার ওপর রাগ করেছে।\nরায়ান ছাতাটা হাতে নিয়ে একটু নাড়াচাড়া করতেই সেটা খুলে গেল।\nমেয়েটা অবাক হয়ে বলল,\n— বাহ! আপনি তো ছাতা ঠিক করতেও পারেন!\n— আসলে ভাগ্য ভালো ছিল।\n— তাহলে আজ আমার ভাগ্যও ভালো।\nরায়ান হেসে ফেলল।\nমেয়েটা ছাতার নিচে দাঁড়িয়ে বলল,\n— আপনার নামটা জানা হলো না।\n— রায়ান।\n— আমি মেহরিন।\nনামটা শুনে রায়ান কিছুক্ষণ চুপ করে রইল।\nমেহরিন।\nনামটার মধ্যেই যেন একটা অদ্ভুত মায়া ছিল।\nদুজন পাশাপাশি হাঁটতে শুরু করল।\nবৃষ্টির শব্দে চারপাশ ভরে গেছে। রাস্তার পাশে জমে থাকা পানিতে শহরের আলো পড়ে ছোট ছোট ঢেউ তৈরি করছে।\nকিছুদূর যাওয়ার পর মেহরিন বলল,\n— আপনি সবসময় এত চুপচাপ থাকেন?\n— না।\n— তাহলে?\nরায়ান একটু হেসে বলল,\n— আপনার সঙ্গে কথা বলার মতো বিষয় খুঁজে পাচ্ছি না।\nমেহরিন হেসে ফেলল।\n— অথচ বই নিয়ে বেশ ভালো কথা বলছিলেন।\n— বই নিয়ে কথা বলা সহজ।\n— মানুষ নিয়ে কঠিন?\nরায়ান তার দিকে তাকিয়ে বলল,\n— মানুষকে বোঝা কঠিন।\nমেহরিন কিছুক্ষণ চুপ করে রইল।\nতারপর ধীরে বলল,\n— সবাইকে বোঝার দরকার নেই। কিছু মানুষকে শুধু অনুভব করলেই হয়।\nরায়ান কোনো উত্তর দিল না।\nরাস্তার মোড়ে এসে মেহরিন থামল।\n— আমার বাড়ি এই দিকে।\n— আচ্ছা।\n— তাহলে যাই।\n— হুম।\nমেহরিন কয়েক পা এগিয়ে আবার ফিরে তাকাল।\n— কাল লাইব্রেরিতে আসবেন?\nরায়ান একটু অবাক হয়ে বলল,\n— আপনি আসবেন?\nমেহরিন মৃদু হেসে বলল,\n— আপনি থাকলে আসব।\nতারপর সে চলে গেল।\nরায়ান অনেকক্ষণ একই জায়গায় দাঁড়িয়ে রইল।\nবৃষ্টি তখনও পড়ছিল।\nকিন্তু তার মনে হচ্ছিল, আজকের বৃষ্টিটা অন্যরকম।\nসেদিন রাতে ঘুমানোর আগে রায়ান জানালার পাশে বসে ছিল। কেন জানি বারবার একটা নামই মনে পড়ছিল—\nমেহরিন।\nএকজন অচেনা মানুষ।\nমাত্র কয়েক ঘণ্টার পরিচয়।\nতবুও মনে হচ্ছিল, এই পরিচয়টা হয়তো এখানেই শেষ হবে না।\nহয়তো এটাই ছিল কোনো এক দীর্ঘ গল্পের প্রথম পৃষ্ঠা।','\n',char(10)),1,'published',0,'2026-10-05T08:46:40.154Z','2026-10-05T08:46:40.154Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('3014fe77-fe13-4212-80dd-cec6a208d2c5','ae5710ac-1676-4745-8b19-266661e9d69f','পর্ব নাম্বার - 2',replace('পরদিন সকাল থেকেই রায়ানের মনটা অস্থির ছিল।\nকেন অস্থির, সে নিজেও জানত না। ঘুম থেকে ওঠার পর প্রথম যে কথাটা মনে পড়েছিল, সেটা ছিল মেহরিনের শেষ কথাটা\n“আপনি থাকলে আসব।”\nএকটা সাধারণ কথা।\nঅথচ রায়ানের কাছে কথাটা যেন সারাদিনের অপেক্ষা হয়ে দাঁড়িয়েছিল।\nবিশ্ববিদ্যালয়ে পৌঁছে তানভীরকে দেখেই সে জিজ্ঞেস করল,\n==লাইব্রেরিতে যাবি?==\nতানভীর অবাক হয়ে তাকাল।\n— ক্লাসের আগে লাইব্রেরিতে যাওয়ার এত আগ্রহ কবে থেকে হলো?\n— এমনিই।\n— বুঝেছি।\n— কী বুঝেছিস?\n— কিছু না।\nতানভীর ইচ্ছে করেই ‘কিছু না’ কথাটার ওপর জোর দিল।\nরায়ান বিরক্ত হয়ে বলল,\n— তুই একদিন আমার এই কথাটার জন্য মার খাবি।\nদুজনেই হেসে ফেলল।\nক্লাস শেষ হতে না হতেই রায়ান লাইব্রেরির দিকে চলে গেল।\nকিন্তু মেহরিন তখনও আসেনি।\nসে একটা বই নিয়ে জানালার পাশে বসে পড়ার চেষ্টা করল। পাঁচ মিনিট পর ঘড়ির দিকে তাকাল।\nআরও দশ মিনিট।\nআবার ঘড়ি।\nনিজের ওপরই বিরক্ত লাগছিল তার।\nসে মনে মনে বলল, “আমি এখানে ওর জন্য বসে আছি নাকি?”\nঠিক তখনই দরজা খুলল।\nরায়ান মাথা তুলল।\nমেহরিন দাঁড়িয়ে আছে।\nআজ তার পরনে হালকা হলুদ পোশাক। হাতে সেই সাদা ছাতা। চুলগুলো খোলা, মুখে ছোট্ট একটা হাসি।\nরায়ানের চোখের দিকে তাকিয়ে সে বলল,\n— এতক্ষণ ধরে অপেক্ষা করছিলেন?\nরায়ান বইয়ের দিকে তাকিয়ে বলল,\n— না তো।\nমেহরিন তার সামনে এসে দাঁড়াল।\n— সত্যি?\n— হুম।\n— তাহলে ঘড়ির দিকে এতবার তাকাচ্ছিলেন কেন?\nরায়ান কিছু বলল না।\nমেহরিন হেসে পাশের চেয়ারে বসে পড়ল।\n— ঠিক আছে। বিশ্বাস করলাম।\nকিছুক্ষণ দুজনেই চুপ করে রইল।\nতারপর মেহরিন টেবিলের ওপর একটা ছোট্ট কাগজ রাখল।\nরায়ান অবাক হয়ে জিজ্ঞেস করল,\n— এটা কী?\n— আপনার জন্য।\nরায়ান কাগজটা খুলল।\nসেখানে লেখা—\n“গতকাল ছাতাটা ঠিক করে দেওয়ার জন্য ধন্যবাদ। আর বৃষ্টির মধ্যে এত দূর হাঁটার জন্যও।”\nরায়ান কাগজটার দিকে তাকিয়ে মৃদু হাসল।\n— এতটুকু ব্যাপারের জন্য চিঠি?\n— চিঠি না। ধন্যবাদ।\n— মুখে বললেই তো হতো।\n— কিছু কথা লিখে বললে বেশি সুন্দর লাগে।\nরায়ান কাগজটা ভাঁজ করে নিজের বইয়ের ভেতর রেখে দিল।\nমেহরিন সেটা দেখে বলল,\n— রেখে দিলেন?\n— হ্যাঁ।\n— কেন?\n— ফেলে দেওয়ার মতো কিছু মনে হলো না।\nমেহরিন কিছু বলল না।\nতার মুখের হাসিটা একটু গভীর হলো।\nসেদিন তাদের কথার কোনো শেষ ছিল না।\nমেহরিন জানাল, সে বাংলা সাহিত্য নিয়ে পড়ছে। ছোটবেলা থেকেই বই পড়তে ভালোবাসে। তার স্বপ্ন একদিন নিজের একটা ছোট্ট লাইব্রেরি করা।\nরায়ান বলল, তার স্বপ্ন একদিন নিজের একটা প্রকাশনা প্রতিষ্ঠান করার।\nমেহরিন অবাক হয়ে তাকাল।\n— সত্যি?\n— হ্যাঁ।\n— তাহলে আমাদের স্বপ্ন তো কাছাকাছি।\n— হয়তো।\n— হয়তো কেন?\nরায়ান মৃদু হেসে বলল,\n— সব স্বপ্ন তো পূরণ হয় না।\nমেহরিন জানালার বাইরে তাকিয়ে বলল,\n— হয় না। তবে কিছু স্বপ্নের জন্য লড়াই করতে হয়।\nরায়ান তার দিকে তাকিয়ে রইল।\nএই মেয়েটার কথা বলার ধরনটা তার ভালো লাগত।\nকথাগুলো খুব সাধারণ। কিন্তু প্রতিবারই মনে হতো, কথার ভেতরে আরও কিছু লুকিয়ে আছে।\nবিকেল গড়িয়ে সন্ধ্যা হয়ে গেল।\nলাইব্রেরি বন্ধ হওয়ার সময় মেহরিন ব্যাগ গুছিয়ে বলল,\n— কাল একটা জায়গায় যাবেন?\n— কোথায়?\n— নদীর পাড়ে।\n— কেন?\n— সূর্যাস্ত দেখতে।\nরায়ান একটু অবাক হলো।\n— আপনি আমাকে নিয়ে যেতে চান?\nমেহরিন হেসে বলল,\n— আপনি চাইলে যেতে পারেন।\n— আমি যাব।\n— তাহলে কাল বিকেল পাঁচটায়?\n— ঠিক আছে।\nমেহরিন উঠে দাঁড়াল।\nদরজার কাছে গিয়ে আবার ফিরে তাকাল।\n— রায়ান?\n— হুম?\n— আজকে একটা কথা বলিনি।\n— কী?\n— গতকাল আপনাকে প্রথম দেখার পর মনে হয়েছিল, আপনি খুব চুপচাপ মানুষ।\nরায়ান হাসল।\n— এখন কী মনে হয়?\nমেহরিন কয়েক মুহূর্ত তার দিকে তাকিয়ে বলল,\n— এখন মনে হয়, আপনি চুপচাপ নন। শুধু আপনার কথা শোনার মতো মানুষ খুব কম।\nকথাটা বলে সে চলে গেল।\nরায়ান দরজার দিকে তাকিয়ে রইল।\nতারপর ধীরে ধীরে নিজের বইটা বন্ধ করল।\nবইয়ের ভেতরে রাখা ছোট্ট কাগজটা বের করল।\n“কিছু কথা লিখে বললে বেশি সুন্দর লাগে।”\nরায়ান অজান্তেই হাসল।\nতার মনে হলো, মেহরিন শুধু তার বইয়ের পাতায় নয়—\nধীরে ধীরে তার জীবনের পাতাতেও জায়গা করে নিচ্ছে।','\n',char(10)),2,'published',0,'2026-10-05T08:48:19.015Z','2026-10-05T08:48:19.015Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('f09642fc-d980-4e6a-8998-195abca3b856','ae5710ac-1676-4745-8b19-266661e9d69f','পর্ব নাম্বার - 3',replace('- পরদিন বিকেল পাঁচটার অনেক আগেই রায়ান নদীর পাড়ে এসে দাঁড়িয়েছিল।\n\nনিজের ওপরই তার একটু রাগ হচ্ছিল। এত আগে আসার কোনো দরকার ছিল না। তবুও সে এসেছিল।\n\nনদীর ওপরে বিকেলের আলো ধীরে ধীরে নরম হয়ে আসছিল। দূরে নৌকাগুলো ধীর গতিতে এগিয়ে যাচ্ছিল। বাতাসে কেমন একটা শান্ত গন্ধ।\n\nরায়ান বারবার রাস্তার দিকে তাকাচ্ছিল।\n\nপাঁচটা বাজতে আর দশ মিনিট বাকি।\n\nহঠাৎ পেছন থেকে একটা পরিচিত কণ্ঠ ভেসে এল,\n\n— এত তাড়াতাড়ি চলে এসেছেন?\n\nরায়ান ঘুরে তাকাল।\n\nমেহরিন।\n\nআজ তার পরনে সাদা-নীল পোশাক। হাতে একটা ছোট ব্যাগ। মুখে সেই পরিচিত হাসি।\n\nরায়ান বলল,\n\n— আমি সময়ের একটু আগেই চলে এসেছি।\n\nমেহরিন হেসে বলল,\n\n— একটু?\n\n— হ্যাঁ।\n\n— ঘড়িতে তো চারটা ত্রিশ বাজে।\n\nরায়ান ঘড়ির দিকে তাকিয়ে একটু অপ্রস্তুত হয়ে গেল।\n\n— আসলে রাস্তা ফাঁকা ছিল।\n\n— বুঝেছি।\n\nদুজন পাশাপাশি নদীর পাড় ধরে হাঁটতে লাগল।\n\nকিছুক্ষণ কেউ কোনো কথা বলল না।\n\nঅদ্ভুতভাবে এই নীরবতাটাও তাদের কাছে অস্বস্তিকর লাগছিল না।\n\nমেহরিন হঠাৎ বলল,\n\n— তুমি কি কখনো কাউকে খুব মিস করেছ?\n\nরায়ান একটু থেমে গেল।\n\n— কেন?\n\n— এমনি।\n\n— হ্যাঁ। করেছি।\n\n— কাকে?\n\nরায়ান নদীর দিকে তাকাল।\n\n— একজনকে।\n\nমেহরিন মৃদু হেসে বলল,\n\n— সে কি জানত?\n\n— না।\n\n— কেন বলোনি?\n\n— ভয় ছিল।\n\n— কিসের ভয়?\n\nরায়ান এবার মেহরিনের দিকে তাকাল।\n\n— হারিয়ে ফেলার।\n\nমেহরিন কিছু বলল না।\n\nতার মুখের হাসিটা ধীরে ধীরে মিলিয়ে গেল।\n\nকয়েক মুহূর্ত পর সে বলল,\n\n— কাউকে ভালোবাসলে তাকে হারানোর ভয় থাকবেই। কিন্তু না বললে তো মানুষটাকে পাওয়ার সুযোগটাও থাকে না।\n\nরায়ান হেসে বলল,\n\n— তুমি খুব সহজে কথা বলো।\n\n— কারণ আমি এখনো কাউকে ভালোবাসিনি।\n\nকথাটা শুনে রায়ানের বুকের ভেতর কেমন যেন হলো।\n\nসে আর কিছু বলল না।\n\nতারা নদীর ধারে একটা বেঞ্চে বসে পড়ল।\n\nসূর্য তখন ধীরে ধীরে পশ্চিম আকাশে নেমে যাচ্ছে। আকাশের রং বদলে যাচ্ছে—কমলা, লাল আর হালকা বেগুনি।\n\nমেহরিন মুগ্ধ হয়ে তাকিয়ে রইল।\n\n— জানো, সূর্যাস্ত আমার খুব পছন্দ।\n\n— সূর্যোদয় না?\n\n— সূর্যোদয় নতুন শুরুর কথা বলে। আর সূর্যাস্ত মনে করিয়ে দেয়, সুন্দর জিনিসও একদিন শেষ হয়ে যায়।\n\nরায়ান মৃদু হেসে বলল,\n\n— তুমি সবকিছুর মধ্যে এত দুঃখ খুঁজে পাও কেন?\n\nমেহরিন তার দিকে তাকাল।\n\n— কারণ সুখের সময় মানুষ খুব কমই ভাবে, এটা একদিন শেষ হয়ে যাবে।\n\nরায়ান কিছুক্ষণ চুপ করে রইল।\n\nতারপর বলল,\n\n— সবকিছু শেষ হয় না।\n\n— যেমন?\n\n— কিছু মানুষ।\n\nমেহরিন তাকিয়ে রইল তার দিকে।\n\nদুজনের চোখে চোখ আটকে গেল।\n\nকয়েক সেকেন্ড।\n\nতারপর মেহরিন চোখ সরিয়ে নিল।\n\n— চা খাব?\n\nরায়ান হেসে ফেলল।\n\n— এত গভীর কথা থেকে সরাসরি চা?\n\n— গভীর কথা বেশি হয়ে গেলে মাথা ব্যথা করে।\n\nদুজনেই হাসল।\n\nচায়ের দোকানে বসে তারা অনেকক্ষণ গল্প করল।\n\nসেদিন ফেরার সময় মেহরিন হঠাৎ বলল,\n\n— রায়ান?\n\n— হুম?\n\n— তুমি কি আমাকে বন্ধু ভাবো?\n\nপ্রশ্নটা শুনে রায়ান একটু থেমে গেল।\n\n— হ্যাঁ।\n\nমেহরিন মাথা নাড়ল।\n\n— আমিও।\n\nতারপর দুজনেই চুপ করে হাঁটতে লাগল।\n\nকিন্তু সেই ‘বন্ধু’ শব্দটার ভেতরে সেদিন এমন কিছু ছিল, যা তারা কেউ মুখে বলল না।\n\n\n---\n\nদিনগুলো দ্রুত চলে যেতে লাগল।\n\nলাইব্রেরিতে দেখা, একসঙ্গে চা খাওয়া, নদীর পাড়ে হাঁটা—সবকিছু যেন তাদের জীবনের স্বাভাবিক অংশ হয়ে গেল।\n\nরায়ান বুঝতে পারছিল, সে মেহরিনকে আগের চেয়ে অনেক বেশি ভাবছে।\n\nসকালে ঘুম থেকে উঠে প্রথমে তার কথা মনে পড়ে।\n\nরাতে ঘুমানোর আগে শেষবার তার সঙ্গে কথা বলতে ইচ্ছে করে।\n\nমেহরিনও বদলে যাচ্ছিল।\n\nরায়ান একদিন লাইব্রেরিতে না এলে সে বারবার দরজার দিকে তাকিয়ে থাকত।\n\nএকদিন রায়ান জিজ্ঞেস করল,\n\n— আজ এত চুপ কেন?\n\nমেহরিন বলল,\n\n— তুমি কাল আসোনি।\n\n— তাই?\n\n— হ্যাঁ।\n\n— আমাকে মিস করেছিলে?\n\nমেহরিন একটু থেমে বলল,\n\n— হয়তো।\n\nরায়ান হেসে ফেলল।\n\n— ‘হয়তো’ কেন?\n\nমেহরিন বই খুলে বলল,\n\n— বেশি জেনে লাভ নেই।\n\nরায়ান তার পাশে বসে মৃদুস্বরে বলল,\n\n— তাহলে আমিও একটা কথা বলব না।\n\n— কী কথা?\n\n— কাল তোমাকে খুব মিস করেছি।\n\nমেহরিন বইয়ের পাতার দিকে তাকিয়ে রইল।\n\nকিন্তু তার ঠোঁটের কোণে যে হাসিটা ফুটে উঠেছিল, সেটা রায়ানের চোখ এড়াল না।\n\nসেদিন প্রথমবার রায়ানের মনে হলো—\n\nতাদের সম্পর্কটা হয়তো আর শুধু বন্ধুত্বের মধ্যে নেই।\n\nকিন্তু সে তখনো জানত না, এই সুন্দর সময়ের ঠিক পরেই তাদের জীবনে এমন একটা ঝড় আসছে, যা দুজনের পৃথিবীকে একেবারে বদলে দেবে।','\n',char(10)),3,'published',0,'2026-10-05T08:49:44.812Z','2026-10-05T08:49:44.812Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('90e8d47c-48c3-43d9-afcc-3e3d05307ea4','ae5710ac-1676-4745-8b19-266661e9d69f','পর্ব নাম্বার - 4',replace('সেদিন সকাল থেকেই রায়ানের মনটা অদ্ভুত ভালো ছিল।\n\nকারণটা খুব সাধারণ—মেহরিন তাকে সকালে একটা মেসেজ পাঠিয়েছিল।\n\n“আজ বিকেলে দেখা করবে?”\n\nরায়ান শুধু উত্তর দিয়েছিল—\n\n“অবশ্যই।”\n\nকিন্তু এই একটা শব্দ লিখতে গিয়েই তার মুখে হাসি ফুটে উঠেছিল।\n\nবিকেলে বিশ্ববিদ্যালয়ের পেছনের ছোট্ট বাগানে মেহরিন অপেক্ষা করছিল। হাতে একটা বই, চোখে সেই চেনা শান্ত দৃষ্টি।\n\nরায়ান কাছে যেতেই মেহরিন বইটা এগিয়ে দিল।\n\n— এটা তোমার জন্য।\n\n— আমার জন্য?\n\n— হ্যাঁ।\n\nরায়ান বইটা হাতে নিয়ে দেখল, বইটির প্রথম পাতায় ছোট করে লেখা—\n\n“কিছু মানুষ গল্পের মতো আসে, কিন্তু গল্পের চেয়েও বেশি কিছু হয়ে যায়।”\n\nরায়ান লেখাটার দিকে তাকিয়ে চুপ করে রইল।\n\nমেহরিন বলল,\n\n— ভালো লাগেনি?\n\n— খুব ভালো লেগেছে।\n\n— তাহলে এত চুপ কেন?\n\nরায়ান বইটা বন্ধ করে বলল,\n\n— কিছু কথা শুনলে মানুষ চুপ হয়ে যায়।\n\nমেহরিন মৃদু হেসে বলল,\n\n— তুমি আজকাল অনেক বেশি কথা বলতে শিখেছ।\n\n— তোমার সঙ্গে থাকতে থাকতে।\n\nকথাটা শুনে মেহরিন কিছু বলল না।\n\nহঠাৎ বাতাসে তার চুল উড়ে এসে মুখের ওপর পড়ল। রায়ান হাত বাড়িয়ে চুলগুলো সরিয়ে দিতে গিয়েও থেমে গেল।\n\nমেহরিন সেটা লক্ষ্য করল।\n\nদুজনের চোখে চোখ পড়ল।\n\nকয়েক মুহূর্তের নীরবতা।\n\nতারপর মেহরিন আস্তে করে বলল,\n\n— রায়ান...\n\n— হুম?\n\n— তুমি কি আমাকে কিছু বলতে চাও?\n\nরায়ানের বুকের ভেতরটা কেঁপে উঠল।\n\nএই মুহূর্তটার জন্য সে অনেকদিন ধরে অপেক্ষা করছিল।\n\nসে ধীরে বলল,\n\n— হ্যাঁ।\n\nমেহরিন চুপ করে তার দিকে তাকিয়ে রইল।\n\nরায়ান বলল,\n\n— আমি জানি না কথাটা বলার পর আমাদের সম্পর্কটা কী হবে। কিন্তু আর লুকিয়ে রাখতে পারছি না।\n\nমেহরিনের চোখে অদ্ভুত এক অপেক্ষা ফুটে উঠল।\n\nরায়ান গভীর শ্বাস নিয়ে বলল,\n\n— মেহরিন, আমি তোমাকে...\n\nতার কথা শেষ হওয়ার আগেই মেহরিনের ফোন বেজে উঠল।\n\nমেহরিন ফোনের স্ক্রিনের দিকে তাকিয়েই থমকে গেল।\n\nমুখের হাসি মুহূর্তে হারিয়ে গেল।\n\nরায়ান জিজ্ঞেস করল,\n\n— কী হয়েছে?\n\nমেহরিন ফোনটা কানে ধরল।\n\n— হ্যালো, মা?\n\nওপাশ থেকে কী বলা হলো, রায়ান শুনতে পেল না।\n\nকিন্তু মেহরিনের মুখের পরিবর্তনটা স্পষ্ট দেখতে পেল।\n\nকয়েক মুহূর্ত পর সে শুধু বলল,\n\n— আমি আসছি।\n\nফোন কেটে দিল।\n\nরায়ান বলল,\n\n— বাসায় কিছু হয়েছে?\n\nমেহরিন মাথা নাড়ল।\n\n— আমাকে এখন যেতে হবে।\n\n— কিন্তু তুমি...\n\nমেহরিন তার কথার দিকে তাকিয়ে বলল,\n\n— তুমি যে কথাটা বলতে যাচ্ছিলে, সেটা পরে বলো।\n\n— কবে?\n\nমেহরিন একটু থেমে বলল,\n\n— কাল।\n\nতারপর দ্রুত চলে গেল।\n\nরায়ান অনেকক্ষণ দাঁড়িয়ে রইল।\n\nতার মনে হচ্ছিল, আজকের দিনটা হয়তো তার জীবনের সবচেয়ে গুরুত্বপূর্ণ একটা দিন হতে পারত।\n\nকিন্তু সে জানত না, মেহরিনের বাড়িতে তখন অন্য একটা সিদ্ধান্ত নেওয়া হয়ে গেছে।\n\n\n---\n\nসেদিন রাতে মেহরিন নিজের ঘরে বসে ছিল।\n\nতার মা সামনে বসে ছিলেন।\n\n— বাবা তোমার সঙ্গে কথা বলতে চায়।\n\nমেহরিন চুপ করে রইল।\n\n— কী নিয়ে?\n\nতার মা ধীরে বললেন,\n\n— তোমার বিয়ের ব্যাপারে।\n\nমেহরিনের মুখ ফ্যাকাশে হয়ে গেল।\n\n— বিয়ে?\n\n— হ্যাঁ।\n\n— কিন্তু আমি এখন বিয়ে করতে চাই না।\n\n— ছেলে ভালো। পরিবারও ভালো।\n\nমেহরিন মাথা নাড়ল।\n\n— মা, আমি পারব না।\n\n— কেন?\n\nমেহরিন কোনো উত্তর দিল না।\n\nতার মা কিছুক্ষণ তার দিকে তাকিয়ে থেকে বললেন,\n\n— তোমার জীবনে কি কেউ আছে?\n\nমেহরিন চোখ নামিয়ে ফেলল।\n\nনীরবতাই তার উত্তর হয়ে গেল।\n\nতার মা দীর্ঘশ্বাস ফেললেন।\n\n— তোমার বাবা যদি জানতে পারে...\n\nমেহরিন চোখ তুলে বলল,\n\n— আমি রায়ানকে ভালোবাসি।\n\nকথাটা বলার পর তার বুকটা যেন হালকা হয়ে গেল।\n\nকিন্তু মায়ের মুখে ভয়ের ছায়া নেমে এল।\n\n— তোমার বাবা এই সম্পর্ক কখনো মেনে নেবে না।\n\nমেহরিন ধীরে বলল,\n\n— আমি জানি।\n\n— তাহলে?\n\nমেহরিন জানালার বাইরে তাকাল।\n\nবাইরে তখন বৃষ্টি শুরু হয়েছে।\n\nতার মনে পড়ল রায়ানের কথা।\n\n“আমি তোমাকে...”\n\nকথাটা আজও অসম্পূর্ণ রয়ে গেল।\n\nসে জানত না, আগামীকাল রায়ানকে কীভাবে সব বলবে।\n\nআর সে এটাও জানত না—\n\nপরদিন থেকে তাদের জীবনে এমন এক দূরত্ব শুরু হবে, যার শেষ কোথায় কেউ জানে না।','\n',char(10)),4,'published',0,'2026-10-05T08:51:04.909Z','2026-10-05T08:51:04.909Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('ecbd8053-16f5-4e32-9146-909d7cbdb649','ae5710ac-1676-4745-8b19-266661e9d69f','পর্ব নাম্বার - 5',replace('পরদিন সকালটা রায়ানের কাছে অস্বাভাবিক দীর্ঘ মনে হচ্ছিল।\n\nঘড়ির কাঁটা যেন ইচ্ছে করেই ধীরে চলছে। বারবার ফোনের স্ক্রিন দেখছিল সে। মেহরিনের কোনো মেসেজ নেই।\n\nগতকাল যাওয়ার সময় মেহরিন বলেছিল, “কাল।”\n\nসেই একটা কথার ওপর ভরসা করেই রায়ান সকাল থেকে অপেক্ষা করছিল।\n\nদুপুর পেরিয়ে বিকেল হলো।\n\nমেহরিন এল না।\n\nরায়ান নিজেই ফোন করল।\n\nএকবার।\n\nদুবার।\n\nতিনবার।\n\nফোন বন্ধ।\n\nতার বুকের ভেতর অজানা একটা আশঙ্কা জমতে শুরু করল।\n\nশেষ পর্যন্ত বিকেল পাঁচটার দিকে সে লাইব্রেরিতে চলে গেল।\n\nযে টেবিলে মেহরিন প্রায়ই বসত, সেটাই খালি।\n\nরায়ান সেখানে বসে রইল।\n\nএক ঘণ্টা।\n\nদুই ঘণ্টা।\n\nলাইব্রেরি বন্ধ হওয়ার সময় কর্মচারী এসে বলল,\n\n— বাবা, আজ আর কেউ আসবে না। বাড়ি যাও।\n\nরায়ান ধীরে উঠে দাঁড়াল।\n\nবাইরে বেরিয়ে দেখল, আকাশ কালো হয়ে আছে।\n\nহঠাৎ তার ফোনে একটা মেসেজ এল।\n\nমেহরিন।\n\nরায়ানের বুক ধক করে উঠল।\n\nসে দ্রুত মেসেজ খুলল।\n\n“রায়ান, কিছুদিন আমার সঙ্গে যোগাযোগ করার চেষ্টা কোরো না। বাড়িতে অনেক সমস্যা চলছে। আমাকে ভুল বোঝার চেষ্টা কোরো না। সময় হলে সব বলব।”\n\nরায়ান মেসেজটা পড়ে স্থির হয়ে দাঁড়িয়ে রইল।\n\nতারপর কল করল।\n\nফোন বন্ধ।\n\nআবার কল করল।\n\nএকই ফল।\n\nসে জানত না কী হয়েছে।\n\nশুধু বুঝতে পারছিল, মেহরিন তাকে দূরে ঠেলে দিচ্ছে।\n\nকিন্তু কেন?\n\n\n---\n\nপরের কয়েকটা দিন রায়ানের কাছে খুব কঠিন হয়ে উঠল।\n\nমেহরিন বিশ্ববিদ্যালয়ে আসছে না।\n\nলাইব্রেরি খালি।\n\nনদীর পাড়ে গেলে আগের বিকেলগুলো মনে পড়ে।\n\nচায়ের দোকানে গেলে তার হাসিটা কানে বাজে।\n\nতানভীর সব বুঝতে পারছিল।\n\nএকদিন সে বলল,\n\n— তুই ওর সঙ্গে কথা বলেছিস?\n\n— চেষ্টা করেছি।\n\n— কী বলেছে?\n\nরায়ান ফোনটা এগিয়ে দিল।\n\nতানভীর মেসেজটা পড়ে কিছুক্ষণ চুপ করে থাকল।\n\n— মনে হচ্ছে ওর বাসায় সমস্যা হয়েছে।\n\n— তাহলে আমাকে বলছে না কেন?\n\n— হয়তো পারছে না।\n\nরায়ান জানালার বাইরে তাকিয়ে বলল,\n\n— আমি ওকে হারাতে চাই না।\n\nতানভীর তার কাঁধে হাত রাখল।\n\n— তাহলে অপেক্ষা কর।\n\nরায়ান মৃদু হেসে বলল,\n\n— কতদিন?\n\nতানভীর উত্তর দিতে পারল না।\n\n\n---\n\nঅন্যদিকে মেহরিনের জীবনও সহজ ছিল না।\n\nতার বাবা বিয়ের ব্যাপারে সিদ্ধান্ত নিয়ে ফেলেছেন।\n\nছেলেটির নাম আদনান।\n\nভালো পরিবার, ভালো চাকরি, ভালো মানুষ—সবদিক থেকেই পরিবারের কাছে সে উপযুক্ত।\n\nকিন্তু মেহরিনের কাছে একটা জিনিসই গুরুত্বপূর্ণ ছিল।\n\nসে রায়ানকে ভালোবাসে।\n\nএক রাতে সে নিজের ঘরে বসে রায়ানের দেওয়া ডায়েরিটা খুলল।\n\nপ্রথম পাতায় লেখা—\n\n“যে কথাগুলো মুখে বলা যায় না, সেগুলো এখানে লিখে রেখো।”\n\nমেহরিন কলম হাতে নিল।\n\nঅনেকক্ষণ কিছু লিখতে পারল না।\n\nশেষে লিখল—\n\n“রায়ান,\n\nআমি জানি না এই চিঠি কখনো তোমার কাছে পৌঁছাবে কি না।\n\nআমি তোমাকে ছেড়ে যেতে চাই না।\n\nকিন্তু কিছু মানুষ নিজের জীবন নিয়ে সিদ্ধান্ত নেওয়ার অধিকারও সবসময় পায় না।\n\nযদি কোনো দিন তুমি ভাবো আমি তোমাকে ভালোবাসিনি, তাহলে আমাকে ক্ষমা করে দিও।\n\nআমি তোমাকে ভালোবাসি।\n\nহয়তো এই কথাটাই আমার সবচেয়ে বড় অপরাধ।”\n\nচিঠিটা লিখে সে চোখের পানি মুছে ফেলল।\n\nতারপর চিঠিটা ডায়েরির ভেতর রেখে দিল।\n\n\n---\n\nদুই সপ্তাহ কেটে গেল।\n\nরায়ান আর কোনো খবর পেল না।\n\nএকদিন সন্ধ্যায় সে বিশ্ববিদ্যালয়ের গেটের সামনে দাঁড়িয়ে ছিল।\n\nহঠাৎ দূর থেকে একটা গাড়ি এসে থামল।\n\nগাড়ি থেকে একজন মধ্যবয়স্ক লোক নামলেন।\n\nতিনি কিছুক্ষণ রায়ানের দিকে তাকিয়ে বললেন,\n\n— তুমি কি রায়ান?\n\nরায়ান অবাক হয়ে বলল,\n\n— জি।\n\nলোকটি কিছুক্ষণ চুপ থেকে বললেন,\n\n— মেহরিনের সঙ্গে তোমার সম্পর্ক আছে?\n\nরায়ানের বুকের ভেতর কেঁপে উঠল।\n\nসে বুঝতে পারল—\n\nএটাই মেহরিনের বাবা।\n\nরায়ান নিজেকে সামলে বলল,\n\n— জি। আমি মেহরিনকে ভালোবাসি।\n\nলোকটির মুখ শক্ত হয়ে গেল।\n\n— আমার মেয়ের সঙ্গে আর কোনো যোগাযোগ করবে না।\n\nরায়ান চুপ করে রইল।\n\n— তুমি কি জানো, তোমার জন্য আমার মেয়ে কত সমস্যায় পড়েছে?\n\n— আমি তাকে কোনো সমস্যায় ফেলতে চাইনি।\n\n— কিন্তু ফেলেছ।\n\nরায়ান মাথা নিচু করল।\n\nলোকটি বললেন,\n\n— তোমার আর মেহরিনের কোনো ভবিষ্যৎ নেই। এটা মেনে নাও।\n\nতিনি চলে গেলেন।\n\nরায়ান অনেকক্ষণ সেখানে দাঁড়িয়ে রইল।\n\nতার মনে হচ্ছিল, কেউ যেন তার সামনে একটা দরজা বন্ধ করে দিয়েছে।\n\nকিন্তু সে তখনো জানত না—\n\nকিছু দরজা বাইরে থেকে বন্ধ হয়ে গেলেও ভেতর থেকে কেউ না কেউ অপেক্ষা করতে থাকে।\n\nআর মেহরিনও অপেক্ষা করছিল।\n\nএকটা সুযোগের জন্য।\n\nএকটা দেখা করার জন্য।\n\nএকটা অসমাপ্ত কথার জন্য।\n\nআর সেই কথাটাই হয়তো তাদের জীবনের সবচেয়ে বড় সিদ্ধান্ত হয়ে উঠবে।','\n',char(10)),5,'published',0,'2026-10-05T08:53:29.404Z','2026-10-05T08:53:29.404Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('e42483ef-8867-4bde-b842-024772edec17','86682182-fafa-49a1-95a4-92dc4fe371c7','পর্ব নাম্বার - 1',replace('শহরের রাজপথে তখন ট্রাফিকের দীর্ঘ সারি। বাসের হর্ন, রিকশার টুংটাং আর মানুষের কোলাহলে কান পাতা দায়। ট্রাফিক সিগন্যালের লাল বাতিটা যেন অনন্তকাল ধরে জ্বলছে। অরুণাভ বাসের জানালার ধারে বসে একমনে বাইরের দিকে তাকিয়ে ছিল। তার পরনে হালকা নীল রঙের শার্ট আর কাঁধে ঝুলছে একটা কালো ব্যাগ। তার শান্ত চোখজোড়ায় যেন সারা শহরের ক্লান্তি জমা হয়ে আছে। সে এই শহরে নতুন, এই কোলাহল আর ব্যস্ততার সাথে সে এখনও নিজেকে মানিয়ে নিতে পারেনি।\n​সিগন্যাল ছেড়ে বাসটা চলতে শুরু করতেই অরুণাভের নজর পড়ল রাস্তার পাশের এক বইয়ের দোকানে। দোকানের কাঁচের ওপাশে এক তরুণী দাঁড়িয়ে আছে, একমনে বইয়ের পাতা উল্টাচ্ছে। মেয়েটির পরনে সাদা রঙের কুর্তা আর এক কাঁধে ঝুলছে নকশা করা ব্যাগ। তার চঞ্চল চোখ আর মিষ্টি হাসি মুহূর্তেই অরুণাভের ক্লান্তি দূর করে দিল। বাসটা বইয়ের দোকান পেরিয়ে এগিয়ে গেল, কিন্তু সেই মেয়েটির মুখ অরুণাভের মনে গেঁথে রইল।\n​সেদিন বিকেলে অরুণাভ পার্কে হাঁটতে গিয়ে আবারও সেই মেয়েটিকে দেখল। সে পার্কের বেঞ্চে বসে একমনে আঁকিবুঁকি করছে। অরুণাভ দ্বিধাগ্রস্ত হয়ে এগিয়ে গেল।\n​"নমস্কার। আমি অরুণাভ। এই শহরে নতুন।"\n​মেয়েটি মুখ তুলে তাকাল। তার চোখের কালো মণি দুটো মুহূর্তের জন্য অরুণাভের শান্ত চোখের দিকে আটকে রইল। মেয়েটি আলতো হাসল, যে হাসিতে এক অদ্ভুত উষ্ণতা ছিল।\n​"নমস্কার। আমি তিন্নি। এই শহরেরই মেয়ে।"\n​সেদিন বিকেল থেকেই তাদের পরিচয়। অরুণাভের গম্ভীর আর মিতভাষী স্বভাবের সাথে তিন্নির চঞ্চল আর প্রাণবন্ত রূপ যেন এক অদ্ভুত ভারসাম্য তৈরি করল। অরুণাভ তিন্নির কাছে খুঁজে পেয়েছিল এই অচেনা শহরে নিজের অস্তিত্ব, আর তিন্নি অরুণাভের কাছে খুঁজে পেয়েছিল এক শান্ত আশ্রয়।\n​কিন্তু প্রতিটি গভীর প্রেমের গল্পের মতোই, তাদের পথচলাও মসৃণ ছিল না। অরুণাভের পরিবার তার জন্য এক প্রতিষ্ঠিত ডাক্তার মেয়ে পছন্দ করে রাখে। অন্যদিকে, তিন্নির বাবা এক প্রভাবশালী রাজনৈতিক নেতা, যিনি অরুণাভের মতো সাধারণ মধ্যবিত্ত যুবকের সাথে নিজের মেয়ের ভবিষ্যৎ নিশ্চয়তায় ফেলতে রাজি ছিলেন না।\n​সামাজিক বাধা আর আত্মত্যাগের মধ্য দিয়ে তাদের ভালোবাসার বাঁধন আরও শক্ত হতে লাগল। একদিন অরুণাভ তিন্নিকে নিয়ে তার পছন্দের এক পাহাড়ি গ্রামে চলে গেল। সেখানে, মেঘের কোল ঘেঁষে এক ছোট কুটিরে তারা তাদের স্বপ্নের জগত গড়ে তুলল। কিন্তু সেই শান্ত জীবনও দীর্ঘস্থায়ী হলো না। অরুণাভের বাবা হৃদরোগে আক্রান্ত হলে, সে বাধ্য হয়ে শহরে ফিরে আসে।\n​অরুণাভের ফিরে আসার খবর শুনে তিন্নিও শহরে চলে আসে। কিন্তু তাদের দেখা করার কোনো উপায় ছিল না। অরুণাভ তার বাবার চিকিৎসার জন্য দিনরাত এক করে কাজ করতে থাকে। অন্যদিকে, তিন্নির বাবা তাকে অন্য একজনের সাথে বিয়ে দেওয়ার জন্য চাপ দিতে থাকে।\n​জীবনের এই কঠিন সময়ে অরুণাভ আর তিন্নির ভালোবাসা যেন এক নতুন পরীক্ষা দিতে থাকে। একদিন অরুণাভের বাবা সুস্থ হয়ে উঠলে, অরুণাভ সব কথা খুলে বলে। অরুণাভের বাবা তার ছেলের ভালোবাসাকে সম্মান দিয়ে রাজি হয়ে যান। কিন্তু তিন্নির বাবা কিছুতেই রাজি ছিলেন না।\n​শেষ পর্যন্ত, অরুণাভ আর তিন্নি এক রোদজ্বলা বিকেলে পালিয়ে যাওয়ার সিদ্ধান্ত নেয়। তারা এক দূর অচেনা শহরে চলে যায়, যেখানে কেউ তাদের চেনে না। সেখানে তারা নতুন করে তাদের জীবন শুরু করে। তাদের জীবনে নানা ঝড়-ঝাপটা এলেও, তাদের ভালোবাসা কখনও মলিন হয়নি।\n​আজ আবারও এক রোদজ্বলা বিকেলে, অরুণাভ আর তিন্নি পার্কের বেঞ্চে বসে আছে। অরুণাভের হাতে তার নতুন উপন্যাসের কপি। সে তিন্নির দিকে তাকিয়ে উপন্যাসের প্রথম পাতা উল্টাচ্ছে। তিন্নি উপন্যাসের প্রথম লাইনে অরুণাভের পরিচিত হাতের লেখা দেখে হেসে উঠল।','\n',char(10)),1,'published',0,'2026-10-05T15:38:21.896Z','2026-10-05T15:38:21.896Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('0ad2dff1-d64e-4a5c-92d8-2c8153625599','86682182-fafa-49a1-95a4-92dc4fe371c7','পর্ব নাম্বার - 2',replace('পার্কের সেই প্রথম পরিচয়ের পর কেটে গেছে বেশ কয়েকটা সপ্তাহ। ইট-পাথরের ধূসর শহরটা অরুণাভের কাছে আর আগের মতো নিঃসঙ্গ মনে হয় না। প্রতিদিন ঘড়ির কাঁটা যখন চারটা ছুঁইছুঁই করে, তখন অদ্ভুত এক চঞ্চলতা ঘিরে ধরে তাকে। অফিসের কাজের ফাঁকে ফাইলের পাতায় চোখ রাখলেও মন পড়ে থাকে লেকপাড়ের সেই মেহগনি গাছের নিচে।\n​তিন্নি ঠিক সাড়ে চারটায় আসে। আজও তার ব্যতিক্রম হলো না। হালকা হলুদ সুতির কুর্তি, খোলা চুলে হালকা বাতাসের দোলা আর মুখে লেগে থাকা চিরচেনা মিষ্টি হাসি নিয়ে সে এগিয়ে এল। হাতে এক ঠোঙা গরম চিনাবাদাম।\n​"কী মিস্টার লেখক, আজকেও কি পুরো শহরের দুঃখ নিজের কাঁধে নিয়ে বসে আছেন?" তিন্নির গলার আওয়াজে অরুণাভ চমকে তাকাল।\n​অরুণাভ হাসল। ওর শান্ত মুখের সেই মৃদু হাসি যেন তিন্নির সবচেয়ে প্রিয় দৃশ্য। সে পাশে সরে বসে বলল, "দুঃখ নয়, ভাবছিলাম শহরটা আসলে বদলে গেছে, নাকি দেখার চোখটা বদলে গেল।"\n​তিন্নি বাদামের খোসা ছাড়াতে ছাড়াতে চোখ ছোট করে তাকাল, "শহর একই আছে, শুধু আপনার একঘেয়ে জীবনে আমার মতো এক চিমটি রঙের ছোঁয়া লেগেছে, তাই না?"\n​"হতে পারে," অরুণাভের গলার স্বর হঠাৎ গম্ভীর ও নরম হয়ে এল। সে তিন্নির চোখের দিকে সরাসরি তাকাল। তিন্নির চঞ্চল চোখদুটো মুহূর্তে কেমন যেন আড়ষ্ট হয়ে গেল। সচরাচর যে কথার ঝুড়ি নিয়ে তিন্নির উপস্থিতি মুখর থাকে, সেই তিন্নি হঠাৎ চোখ নামিয়ে নিল। বাতাসের ঝাপটায় তার কপালের ওপর উড়ে আসা কয়েক গোছা চুল সরিয়ে নিতে নিতে সে অনুচ্চ স্বরে বলল, "অরুণাভ, তুমি সব কথা এত গভীরভাবে কেন বলো? শুনলে মনের ভেতর কেমন একটা তোলপাড় হয়।"\n​অরুণাভ কিছু না বলে লেকের জলে তাকাল। পড়ন্ত বিকেলের সোনালি রোদ তখন জলের ঢেউয়ে হাজারটা রূপোলি টুকরো হয়ে জ্বলছে। প্রকৃতি যেন দুজনের না-বলা কথাগুলো বুঝতে পেরেই চারপাশটা নিস্তব্ধ করে দিয়েছে।\n​হঠাৎ তিন্নির ফোনের তীক্ষ্ণ রিংটোনে সেই মায়াবী নীরবতা ভেঙে চুরমার হয়ে গেল। স্ক্রিনে ''বাবা'' নামটা ভেসে উঠতেই তিন্নির মুখের সব উজ্জ্বলতা মুহূর্তের মধ্যে মিলিয়ে গেল, সেখানে নেমে এল একরাশ শঙ্কা।\n​কাঁপা কাঁপা হাতে ফোনটা কানে ধরে তিন্নি বলল, "হ্যাঁ, বাবা... আসছি। রাস্তায় আছি।"\n​ফোন রেখেই সে দ্রুত উঠে দাঁড়াল। তার ব্যাগের ফিতাটা কাঁধে তুলতে গিয়ে হাত কাঁপছিল।\n​"কী হয়েছে, তিন্নি? কোনো সমস্যা?" অরুণাভ উদ্বিগ্ন হয়ে উঠে দাঁড়াল।\n​তিন্নি অরুণাভের দিকে তাকাল। তার চোখের কোণে জমে ওঠা জলের বিন্দু বিকেলের শেষ আলোয় চিকচিক করে উঠল। সে নিজেকে সামলে নিয়ে বলল, "আজ বাসায় বিশেষ মেহমান আসবে... বাবার এক ব্যবসায়ী বন্ধুর পরিবার। আমার নাকি থাকা জরুরি।"\n​অরুণাভ বুঝতে পারল কথার পেছনের ইঙ্গিত। বুকের ভেতর এক অজানা আতঙ্কের শীতল স্রোত বয়ে গেল। কিন্তু সে শান্ত থাকার চেষ্টা করে তিন্নির কাঁধে হাত রাখতে গিয়েও সংবরণ করল, "তুমি সাবধানে যাও।"\n​তিন্নি কয়েক পা এগিয়ে গিয়ে হঠাৎ থমকে দাঁড়াল। ফিরে এসে অরুণাভের হাতটা শক্ত করে নিজের দুই হাতের মুঠোয় তুলে নিল। তার আঙুলগুলো কাঁপছিল, কিন্তু স্পর্শে ছিল অসম্ভব এক নির্ভরতা।\n​"অরুণাভ, যাই হয়ে যাক না কেন, আমাকে ভুল বুঝবে না তো? এই রোদজ্বলা বিকেলগুলো শুধু তোমার আর আমার... এটা কোনোদিন বদলে যেতে দিও না।"','\n',char(10)),2,'published',0,'2026-10-05T15:42:01.980Z','2026-10-05T15:42:01.980Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('7c73b745-c2dd-4ca2-a959-fdb8ca010a23','86682182-fafa-49a1-95a4-92dc4fe371c7','পর্ব নাম্বার - 3',replace('সেই বিকেলের পর তিন্নি আর ফোনে ধরা দিল না। অরুণাভ পর পর দুদিন লেকের পাড়ে একই বেঞ্চে বসে রইল, কিন্তু হলুদ কুর্তি পরা চঞ্চল মেয়েটি আর এল না। শহরের চেনা কোলাহল হঠাৎ করেই যেন অসহ্য ভারী ঠেকতে লাগল।\n​তৃতীয় দিন দুপুরে অরুণাভের ফোনে একটি অচেনা নম্বর থেকে বার্তা এল—সংক্ষিপ্ত ও স্পষ্ট: "আজ বিকেল পাঁচটায় সেন্ট্রাল লাইব্রেরির পেছনের ক্যাফেতে আসবে? শেষবারের মতো একটু কথা বলব। —তিন্নি।"\n​অরুণাভ নির্দিষ্ট সময়ের আগেই গিয়ে ক্যাফের একদম কোণের টেবিলটায় বসল। কিছুক্ষণ পরই কাঁচের দরজা ঠেলে তিন্নি ভেতরে ঢুকল। পরনে গাঢ় ধূসর শাড়ি, চোখ দুটো অসম্ভব ফোলা, আর মুখের সেই চঞ্চল হাসিটা যেন কেউ জোর করে মুছে দিয়েছে।\n​সামনে এসে বসার পর তিন্নি কিছুক্ষণ শুধু টেবিলের কাঠের নকশার দিকে তাকিয়ে রইল। অরুণাভ হাত বাড়িয়ে তিন্নির বরফশীতল আঙুলগুলো স্পর্শ করতে গিয়েও নিজেকে থামিয়ে নিল।\n​"কী হয়েছে তিন্নি? বাসায় কী ঘটেছে?" অরুণাভের কণ্ঠস্বর শান্ত রাখার চেষ্টার মধ্যেও কেঁপে উঠল।\n​তিন্নি মুখ তুলে তাকাল। তার চোখে জমে থাকা জল আর বাঁধ মানল না। ধরা গলায় সে বলল, "বাবা সব জেনে গেছেন। তোমার নাম, তুমি কী কাজ করো, আমরা কোথায় দেখা করি—সবকিছু। গত রাতে বাবা স্পষ্ট জানিয়ে দিয়েছেন, ওনার রাজনৈতিক প্রতিপত্তির সামনে তোমার মতো মধ্যবিত্ত লেখকের কোনো জায়গা নেই। আগামী মাসের তেরো তারিখ ওনার ব্যবসায়িক অংশীদারের ছেলের সাথে আমার বিয়ের তারিখ ঠিক করা হয়েছে।"\n​টেবিলের ওপর নীরবতা জমে পাথরের মতো ভারী হয়ে উঠল। ক্যাফের ভেতর মৃদু বাদ্যযন্ত্রের সুর বাজছিল, কিন্তু অরুণাভের কানে তখন কেবল নিজের হৃৎস্পন্দনের তীব্র শব্দ।\n​"তুমি কী চাও, তিন্নি?" অরুণাভ সরাসরি তিন্নির চোখের দিকে তাকাল।\n​"আমি তোমাকে চাই, অরুণাভ!" তিন্নির ঠোঁট কাঁপছিল। "আমি বাবার এই মেকি আভিজাত্যের বন্দিদশা থেকে বাঁচতে চাই। তুমি আমাকে নিয়ে কোথাও দূরে চলে চলো। যেখানে কেউ আমাদের চিনবে না, যেখানে বাবার প্রভাব পৌঁছাবে না।"\n​অরুণাভ দীর্ঘশ্বাস ফেলে জানালার ওপারে তাকাল। বাইরে বিকেলের শেষ রোদ ফিকে হয়ে এক অদ্ভুত ধূসর রূপ নিয়েছে। সে তিন্নির দিকে তাকিয়ে দৃঢ় অথচ ব্যথাতুর কণ্ঠে বলল, "পালিয়ে গিয়ে ঘর বাঁধলে হয়তো কিছুদিন আমরা বাঁচব, কিন্তু বাবার সম্মান ধুলোয় মিশিয়ে দিয়ে তুমি সারা জীবন অপরাধবোধে পুড়বে। আমি তোমার জীবনে সেই অভিশাপ হতে চাই না।"\n​"তার মানে তুমি আমাকে ছেড়ে দিচ্ছ?" তিন্নির গলায় অভিমান আর ক্ষোভ মিশে একাকার হয়ে গেল।\n​"আমি তোমাকে ছেড়ে দিলে তো নিজের অস্তিত্বকেই ছেড়ে দেব," অরুণাভ পকেট থেকে একটি ভাঁজ করা কাগজ বের করে তিন্নির সামনে রাখল। সেখানে লেখা ছিল পাহাড়ি এক ছোট শহরের ঠিকানা। "আমার উত্তরবঙ্গে একটা পুরোনো বাড়ি আছে। আমি সেখানে চলে যাচ্ছি আজ রাতেই। পরিবারকে বুঝিয়ে যদি নিজের অধিকারে কোনোদিন বের হয়ে আসতে পারো, এই রোদজ্বলা বিকেলের শপথ—আমি আজীবন তোমার জন্য সেই দরজায় দাঁড়িয়ে অপেক্ষা করব।"\n​তিন্নি কাগজটি শক্ত করে মুঠোয় আঁকড়ে ধরল। কিছু না বলে শুধু একপলক চেয়ে রইল, তারপর অশ্রুভেজা চোখে ক্যাফে ছেড়ে দ্রুত বেরিয়ে গেল।','\n',char(10)),3,'published',0,'2026-10-05T15:42:15.773Z','2026-10-05T15:42:15.773Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('7024866f-8c0a-4a08-b537-aba26d9cefaf','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 1',replace('দরদর করে ঘামছে ফাহিমা। ক্লান্তিতে শরীর ভেঙে পড়ার উপক্রম। কপালের বিন্দু বিন্দু ঘাম হাতের তালু দিয়ে মুছে শীর্ণ পায়ে হেঁটে একটা চেয়ার টেনে বসতেই তার হাত থেকে লাঠি পড়ে মেঝেতে মৃদু শব্দ তুলল। লাঠি তোলার আগ্রহ কিংবা শক্তি কোনোটাই পেল না সে, চেয়ারে ভার ছেড়ে দিয়ে চোখ বুজল।\n\nফাহিমার অত্যন্ত দক্ষ হাত, শক্তিশালী বাহু। পুরুষের মতো উচ্চতা তার। জিজ্ঞাসাবাদের দায়িত্ব পালনে সে শতভাগ সফল। আসামির মুখ থেকে কথা বের করতে যেকোনো কিছু করতে বদ্ধপরিকর সে। বড় বড় রাঘব বোয়ালরাও তার সামনে টিকতে পারে না। অপরাধীরা তার হাত থেকে বাঁচার জন্য ভেতরের সব কথা উগড়ে দেয়নি এমন ঘটনা কখনো ঘটেনি। অথচ আজ পাঁচদিন দিন যাবৎ এক অল্প বয়সী মেয়ে তার হেফাজতে থাকা সত্ত্বেও মুখ দিয়ে টু শব্দটিও করেনি। শারীরিক, মানসিক-কোনো নির্যাতন বাকি রাখা হয়নি তবুও তার আর্তনাদ কেউ শুনতে পায়নি! যেন একটা পাথরকে লাগাতার পেটানো হচ্ছে, যার জীবন নেই, ব্যথা নেই; একটি জড়বস্তু মাত্র! এই পাথরের রক্ত ঝরে, কিন্তু জবান খোলে না।\n\nফাহিমা দীর্ঘশ্বাস ছেড়ে চাপা আক্রোশ নিয়ে মেয়েটিকে শাসাল, ‘শেষবারের মতো বলছি, মুখ খোল।’\n\nমেয়েটি তার থেকে দুই হাত দূরে চেয়ারে বাঁধা অবস্থায় ঝিমুচ্ছে। এক মিনিট… দুই মিনিট করে দশ মিনিট পার হয়ে গেল কিন্তু মেয়েটির থেকে কোনো জবাব এলো না। ফাহিমা হতাশাবোধ করছে। চারপাশে থমথমে নীরবতা, মেয়েটি কি নিঃশ্বাসও নেয় না?\n\nনীরবতা ভেঙে যায় বুটের ঠকঠক শব্দে। উপস্থিত হয় ইন্সপেক্টর তুষার। তাকে দেখেই ফাহিমা উঠে দাঁড়ায়, স্যালুট করে।\n\nতুষার পেশাদারী কণ্ঠে প্রশ্ন করে, ‘কী অবস্থা?’\n\nফাহিমা নিজের ব্যর্থতা প্রকাশ করার সঙ্গে চারদিনের বর্ণনা দেয় পুঙ্খানুপুঙ্খভাবে। তুষার বহুদর্শী চোখে মেয়েটিকে দেখল তার চারপাশে ঘুরতে ঘুরতে ফাহিমাকে বলল, ‘আপনি আসুন।’\n\nরিমান্ডে আসামিকে বিভিন্ন নির্যাতনের মাধ্যমে জিজ্ঞাসাবাদ করার ব্যাপারটা ফাহিমার কাছে ভীষণ উপভোগ্য। কিন্তু এই প্রথম সে কোনো দায়িত্ব থেকে পালাতে চাচ্ছে। ফাহিমা হাঁফ ছেড়ে বেরিয়ে যায়।\n\nতুষার একটি চেয়ার টেনে মেয়েটির সম্মুখ বরাবর বসে। ঠান্ডা গলায় বলে, ‘আজই আমাদের প্রথম দেখা।’\n\nসামনের মানুষটা যেভাবে ছিল সেভাবেই রইল। কিছু বলল না, তাকালও না।\n\nতুষার বলল, ‘মা-বাবাকে মনে পড়ে?’\n\nমা-বাবা শব্দ দুটি যেন নিস্তব্ধ তীড়ে সমুদ্রের ঢেউ নিয়ে আসে। মেয়েটি নড়ে উঠে, চোখ তুলে তাকায়। তার অপূর্ব গায়ের রং, ঘোলাটে চোখ। কাটা ঠোঁট থেকে রক্ত ঝরছে। চোখের চারপাশে গাঢ় কালো দাগ। এ নতুন নয়, মুখের এমন দশা রিমান্ডে আসা সব আসামিরই হয়।\n\nতুষার মুখের প্রকাশভঙ্গী আগের অবস্থানে রেখে পুনরায় প্রশ্ন করল, ‘মা-বাবাকে মনে পড়ে?’\n\nমেয়েটি বাধ্যের মতো মাথা নাড়ায়। মনে পড়ে। তুষার কিছুটা ঝুঁকে এলো।\n\nমেয়েটির দৃষ্টিজুড়ে নীলচে যন্ত্রণা। তুষার তার হাতের বাঁধন খুলে দিয়ে নির্বিকার ভঙ্গিতে প্রশ্ন ছুঁড়ল, ‘নাম কী?’\n\nমেয়েটির নাম সহ খুঁটিনাটি সবই জানে তুষার, তবুও জিজ্ঞাসা করল। তার মনে হচ্ছে, অপর পক্ষ থেকে উত্তর আসবে।\n\nতার ধারণাকে সত্য প্রমাণ করতে ভারাক্রান্ত কণ্ঠে মেয়েটি নিজের নাম উচ্চারণ করল, ‘পদ্ম…আমি…আমি পদ্মজা।’\n\nপদ্মজা চৈতন্য হারিয়ে হেলে পড়ে তুষারের ওপর। তুষার দ্রুত তাকে বাহুডোরে আটকে ফেলল। উঁচু কণ্ঠে ফাহিমাকে ডাকল, ‘ফাহিমা, দ্রুত আসুন।’\n\n১৯৮৯ সাল।\n\nসকাল সকাল রশিদ ঘটকের আগমনে হেমলতা বিরক্ত হোন। তিনি বহুবার পইপই করে বলেছেন, ‘পদ্মর বিয়ে আমি এখনি দেব না। পদ্মকে অনেক পড়াব।’\n\nতবুও রশিদউদ্দিন প্রতি সপ্তাহে নতুন নতুন প্রস্তাব নিয়ে আসে। হেমলতার কথা হচ্ছে, মেয়ের বয়স আর কতই হলো? মাত্র ষোল। শামসুল আলমের মেয়ের বিয়ে হয়েছে চব্বিশ বছর বয়সে। পদ্মর বিয়েও তখনি হবে, ওর পছন্দমতো।\n\nহেমলতা রশিদকে দেখেও না দেখার ভান ধরে মুরগির খোয়াড়ের দরজা খুলে দিলেন। রশিদ এক দলা থুথু উঠানে ফেলে হেমলতার উদ্দেশ্যে বলল, ‘বুঝছ পদ্মর মা, এইবার যে পাত্র আনছি এক্কেরে খাঁটি হীরা।’\n\nহেমলতা বিরক্ত ভরা কণ্ঠে জবাব দিলেন, ‘আমি কি আমার মেয়ের জন্য আপনার কাছে পাত্র চেয়েছি? তবুও বার বার কেন এসে বিরক্ত করেন?\n\nরশিদউদ্দিন হার মানার লোক নয়, সে হেমলতাকে বুঝানোর চেষ্টা করল, যুবতী মাইয়া ঘরে রাহন ভালা না। কখন কী হইয়া যাইব টের পাইবা না।’\n\n‘মেয়েটা তো আমার। আমাকেই বুঝতে দেন?’ রশিদউদ্দিনের উপস্থিতি যে তিনি নিতে পারছেন না তা স্পষ্ট। তবুও রশিদ নির্লজ্জের মতো নানা কথায় তাকে প্রভাবিত করার চেষ্টা করল কিন্তু সুবিধা করতে পারল না। ব্যর্থ থমথমে মুখ নিয়ে বাড়ি থেকে বেরিয়ে গেল।\n\nতিনি পুনরায় বিছানা ঝাড়তে ঝাড়তে বললেন, পদ্মর শরীর ভালো না। সারারাত পেটে ব্যাথায় কেঁদেছে। থাকুক, আজ ঘুমাক।’\n\nপূর্ণার সদ্য পা দেয়া কিশোরী মন চট করে বুঝে যায় পদ্মজা কীসের ব্যাথায় কেঁদেছে। সে গতকাল রাতে নানাবাড়ি ছিল বলে জানত না। ভোরেই চলে এসেছে। নানাবাড়ি কাছে, হেঁটে যেতে পাঁচ মিনিটও লাগে না।\n\nপূর্ণাকে চুপচাপ দাঁড়িয়ে থাকতে দেখে হেমলতা বললেন, ‘তুই যা। মাথা নিচু করে যাবি মাথা নিচু করে আসবি। কোনো অভিযোগ যেন না শুনি।’\n\n‘আচ্ছা আম্মা।’\n\nপূর্ণা ঘরে এসে আয়নার সামনে দাঁড়িয়ে নিজেকে খুঁটিয়ে খুঁটিয়ে দেখতে থাকে। সবাই বলে তার চুল নাকি খুব সুন্দর। কিন্তু সে নিজেকে পুরোটাই সুন্দর মনে করে। গায়ের রং কালো হতে পারে তবে সে কখনোই সেজন্য নিজেকে অসুন্দরভাবে না। পূর্ণার ইদানীং খুব সাজতে ইচ্ছে করে। কিন্তু হেমলতা সাজগোজ পছন্দ করেন না। তাই সে সতর্ক দৃষ্টিতে মায়ের উপস্থিতি একবার দেখে নিলো। আশপাশে নেই! পূর্ণা দ্রুত গত মাসে মেলা থেকে আনা লাল লিপস্টিক গাঢ় করে ঠোঁটে মাখল। এখন হেমলতা দেখার আগে এক ছুটে বেরিয়ে যাবে।\n\nঘড়ির কাঁটায় সকাল দশটা বাজল। এখনো পদ্মজা ওঠেনি। হেমলতা শব্দহীন পায়ে মেয়েদের ঘরে প্রবেশ করেন। বিশাল বড় বিছানায় পদ্মজা দুই হাত ভাঁজ করে ঘুমাচ্ছে। জানালার পর্দা ভেদ করে আসা আলতো পেলব রোদ্দুরের স্পর্শে পদ্মজার মসৃণ পাতলা ঠোঁট, ফরসা ত্বক চিকচিক করছে। হেমলতা বিসমিল্লাহ বলে দ্রুত পদ্মজার গায়ে তিনবার ফুঁ দিলেন। গুরুজনরা বলে, মায়ের নজর ভালো না। এতে সন্তানের ক্ষতি হয়। তাই সঙ্গে সঙ্গে নজর কাটাতে বিসমিল্লাহ বলে ফুঁ দিয়ে দিলেন\n\nহেমলতার মায়া লাগছে পদ্মজার ঘুম ভাঙাতে।\n\nতবুও আদুরে গলায় ডাকলেন, ‘পদ্ম। এই পদ্ম।’\n\nপদ্মজা চোখ খুলে মাকে দেখে হুড়মুড়িয়ে উঠে বসে। যেদিন ঘুম থেকে উঠতে দেরি হয় সেদিনই তাকে হেমলতা ডেকে তুলেন। পদ্মজা অপরাধী কণ্ঠে প্রশ্ন করল, ‘বেশি দেরি হয়ে গেছে আম্মা?’\n\nহেমলতা হেসে বললেন, ‘না, মুখ ধুয়ে খেতে আয়।’\n\nপদ্মজা দ্রুত কলপাড়ে গিয়ে দাঁত মেজে মুখ ধুয়ে নিল। হেমলতা ঢাকা বিশ্ববিদ্যালয়ে পড়েছেন। তার বাবা ছিল হাই স্কুলের শিক্ষক। তাই তার মধ্যে নিয়ম-নীতির প্রভাব বেশি। মেয়েদের শক্তপোক্ত নিয়মে বড় করছেন। নিয়মের মধ্যে সবকিছু হওয়া চাই।\n\nপদ্মজা রান্নাঘরে ঢুকে দেখে স্টিলের প্লেটে খাবার সাজানো। হেমলতা রান্নাঘরে ঢুকতেই পদ্মজা দ্রুত ওড়না দিয়ে মাথা ঢেকে নিল।\n\nএটি হেমলতার দেওয়া আরেকটি আদেশ, খাওয়ার সময় মাথা ঢেকে খেতে হবে। পদ্মজা খেতে বসতেই হেমলতা মেয়েকে সরল কণ্ঠে বললেন, মুখ ধুতে গিয়ে চুল ভিজিয়ে এসেছিস। খেয়ে রোদে বসে চুলটা শুকিয়ে নিস।’\n\n‘আচ্ছা আম্মা।’ পরক্ষণেই বলল, ‘আম্মা, পূর্ণা, প্রেমা আসেনি?’\n\n‘পূর্ণা স্কুলে। প্রেমা দুপুরে আসবে।’\n\n‘আর আব্বা…আব্বা কবে আসবেন?’ মিনমিন করে বলল পদ্মজা।\n\nএই প্রশ্নে হেমলতা থমকে দাঁড়ালেন। শুকনো গলায় জবাব দিলেন, ‘খাওয়ার সময় কথা বলতে নেই।\n\nপদ্মজার চোখ দুটি জ্বলতে শুরু করে। তার জীবনে জন্মদাতা আছে কিন্তু জন্মদাতার আদর নেই। সে জানে না তার দোষটা কোথায়? কেন নিজের বাবা বাকি বোনদের আদর করলেও তাকে করে না? কথা অবধিও বলেন না। পদ্মজা বহুবার হেমলতাকে জিজ্ঞাসা করেছিল, ‘আমি কি তোমাদের সত্যিকারের মেয়ে আম্মা? নাকি সন্তান হয় না বলে কি দত্তক এনেছিলে? আব্বা কেন আমাকে এত অবহেলা করে? ও আম্মা…আম্মা বলো না?’\n\nহেমলতা নিশ্চুপ থেকে অনেকক্ষণ পর জবাব দেন, ‘তুই আমার গর্ভের সন্তান। আর তোর বাবারই মেয়ে। এখন যা, পড়তে বস। অনেক পড়তে হবে তোর।’\n\nব্যাস এইটুকুই! যতবার প্রশ্ন করেছে একই উত্তর পেয়েছে। কখনো কোনো শব্দের নড়চড় হয়নি।\n\n‘এত কী ভাবছিস? তাড়াতাড়ি খেয়ে উঠ।’\n\nহেমলতার কথায় পদ্মজার ভাবনার সুতো ছিঁড়ে গেল। সে দ্রুত খাওয়া শেষ করে। হঠাৎ তার মনে পড়ে, আজ বড়ই আচার বানানোর কথা ছিল।\n\nসন্ধ্যার পরপরই বিদ্যুৎ চলে যায়। কয়েক মাস হলো গ্রামে বিদ্যুৎ এসেছে। আট গ্রাম মিলিয়ে অলন্দপুর। তাদের গ্রামের নাম আটপাড়া। প্রতিদিন নিয়ম করে সন্ধ্যারাত থেকে তিন ঘণ্টা অন্ধকারে তলিয়ে থাকে গ্রাম। সারাদিন তো বিদ্যুৎ এর নামগন্ধও থাকে না। তাহলে বিদ্যুৎ দিয়ে লাভটা কী হলো? পদ্মজা, পূর্ণা, প্রেমা তিন বোন একসঙ্গে পড়তে বসে। হঠাৎ বিদ্যুৎ সংযোগ বিচ্ছিন্ন হতেই মোড়ল বাড়ি অন্ধকারে তলিয়ে যায়। নয় বছরের প্রেমা খামচে ধরে পদ্মজার ওড়না। পদ্মজা মৃদু স্বরে ডাকল, ‘আম্মা…আম্মা।’\n\nহেমলতা ভেতরের ঘর থেকে বললেন, ‘টর্চ নিয়ে যা।’\n\nহেমলতার ডাকে পদ্মজা উঠে দাঁড়ায়। প্রেমা অন্ধকার খুব ভয় পায়। বড় বোনের ওড়না ছেড়ে পূর্ণার হাত চেপে ধরে। টর্চ নিয়ে ঘরে ঢোকার মুহূর্তে পদ্মজা গেইট খোলার আওয়াজ পায়। উঁকি দিয়ে দেখে হানিফ এসেছে। লোকটা সম্পর্কে তার সৎ মামা। হানিফকে দেখেই সে দৌড়ে ঘরে ঢুকে পড়ে।\n\nহানিফ চেঁচিয়ে বলে, ‘বুবু, বাড়ি আন্ধার ক্যান! বাত্তি-টাত্তি জ্বালাও।’\n\n‘হানিফ নাকি?’ হেমলতা হারিকেন হাতে বারান্দায় এসে দাঁড়ান। হানিফ দাঁত বের করে হাসল। বলল, ‘হ, আমি।’\n\n‘আয়, ভেতরে আয়।’\n\nহানিফ বারান্দা পেরিয়ে বড় ঘরে ঢুকে বলল, ‘তোমার ছেড়িগুলা কই?’\n\n‘ঘরেই আছে, পড়াশোনা করে।’\n\n‘এই আন্ধারেও পড়ে!’ অবাক হয়ে বলল হানিফ।\n\nহেমলতা কিছু বললেন না। হানিফ এই বাড়িতে আসলে কোনো কারণ ছাড়াই অস্বস্তি হয় তার\n\nতিনি প্রসঙ্গ এড়াতে বললেন, ‘ওদের খাওয়ার সময় হয়েছে। তুইও খেয়ে নে।\n\n‘এইহানেই খামু? না তোমার সরাইখানাত যাইতে হইব?’\n\nতার উচ্চারিত শেষ বাক্যে রসিকতা ছিল। গ্রামে থেকেও হেমলতা খাবারের জন্য আলাদা ঘর রেখেছে সেটা হানিফের কাছে রসিকতাই বটে!\n\nহেমলতার স্বাভাবিক সুরে বললেন, ‘খেতে চাইলে খেতে আয়।’\n\nপদ্মজা কিছুতেই রাতের খাবার খেতে আসল না। কেমন জড়োসড়ো হয়ে আছে। মনে হচ্ছে, হানিফকে ভয় পাচ্ছে বা কোনো কারণে অবহেলা করছে। হানিফ ছয় বছর সৌদিতে ছিল। তিন মাস হলো দেশে ফিরেছে। তিন মাসে যতবার হানিফ এই বাড়িতে পা রেখেছে ততবারই পদ্মজা অজুহাত দিয়ে দূরে দূরে থেকেছে। হেমলতার বিচক্ষণ, সন্দেহবাতিক মস্তিষ্ক মুহূর্তে ভেবে নিল অনেক কিছু। আজই এই লুকোচুরির ফয়সালা করবেন তিনি। হানিফ পদ্মজাকে দেখার জন্য অনেক ছলচাতুরী করেও সুযোগ পেল না। বিদ্যুৎ আসার ঘণ্টাখানেক পর হানিফ চলে যায়। পূর্ণা, প্রেমা ঘরে ঢুকতেই পদ্মজা ঝাঁপিয়ে পড়ে তাদের ওপর। রুদ্ধশ্বাস কণ্ঠে বলে, ‘কতবার না করেছি? লোকটার পাশে বেশিক্ষণ না থাকতে? তোরা কেনো শুনিস না আমার কথা?’\n\nপূর্ণা, প্রেমা বিস্ময়ে হতবিহ্বল। পদ্মজা কখনো কিছু নিয়ে এভাবে নিষেধ করে না। তাহলে এখন কেন এমন করছে? হেমলতা রুমে ঢুকতেই পদ্মজা চুপসে গেল।\n\n‘পদ্ম আমার ঘরে আয়।’\n\nমায়ের এমন কাঠকাঠ আদেশ শুনে পদ্মজার কলিজা শুকিয়ে একটুখানি হয়ে যায়। পূর্ণা-প্রেমা নিজেদের মধ্যে চাওয়াচাওয়ি করে। পদ্মজা ধুকধুকানি হৃদস্পন্দর নিয়ে হেমলতার ঘরের দিকে গেল।\n\nহেমলতা মেয়ের দিকে সরু চোখে তাকিয়ে আছেন। পদ্মজা পায়ের আঙুল খিঁচে দাঁড়িয়ে আছে! সুন্দরীরা ভীতু আর বোকা হয় তার দৃষ্টান্ত প্ৰমাণ পদ্মজা। তাকে ছাড়া পদ্মজা কীভাবে চলবে?\n\nপদ্মজার সঙ্গে উঁচুকণ্ঠে কথা বলতে হেমলতার খুব মায়া হয়। কিন্তু আজ বলতেই হবে। আবেগ লুকিয়ে তিনি বজ্রকণ্ঠে প্রশ্ন করলেন, ‘কী লুকোচ্ছিস আমার থেকে? হানিফ কী করেছে?’\n\nপদ্মজা ফোঁপাতে থাকে। হেমলতা সেকেন্ড কয়েক সময় নিয়ে নিজেকে সামলে নিলেন। কণ্ঠ নরম করে বললেন, ‘হানিফ ধড়িবাজ লোক! সৎ ভাই বলে বলছি না। আমি জানি সে কতটা খারাপ। তার ব্যাপারে যেকোনো কথা আমি বিশ্বাস করব। তুই আমাকে বল কী লুকোচ্ছিস? কী করেছে হানিফ?’\n\nমায়ের আদুরে কণ্ঠ শুনে পদ্মজা বাঁধ ভাঙা নদীর মতো হু হু করে কেঁদে উঠল। লুটিয়ে পড়ল মায়ের পায়ে।\n\n','\n',char(10)),1,'published',0,'2026-10-06T06:32:45.950Z','2026-10-06T06:32:45.950Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('d98ed19e-67ae-4f76-b8b5-130f6510c82b','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 2',replace('বাড়িটি মোড়ল বাড়ি নামে পরিচিত। পদ্মজার দাদার নাম ছিল মিয়াফর মোড়ল। তিনি গ্রামের একজন সফল ব্যবসায়ী ছিলেন। চার পুত্রের জন্মের পর তাদের জন্য ছয় কাঠা জমির ওপর টিনের বিশাল বড় বাড়ি বানিয়েছিলেন। টগবগে দুই পুত্র ষোলো বছর আগে ১৯৭১ সালের মুক্তিযুদ্ধে নিহত হয়। ছোট ছেলে আট বছর বয়সে কলেরা রোগে মারা যায়। বাকি থাকে বড় ছেলে মোর্শেদ মোড়ল। বর্তমানে এই বাড়ির উত্তরাধিকার মোর্শেদ। যদিও তিনি সবসময় বাড়িতে থাকেন না, বাউন্ডুলে জীবন তার। স্ত্রী-সন্তানের অধীনেই এখন মোড়ল বাড়ি, তারাই বাড়িটির রক্ষণাবেক্ষণ করে। পুরো বাড়ির চারপাশ জুড়ে গাছগাছালি। বাড়ির পিছনে টলটলে জলের স্রোতস্বিনী। অন্ধকার গাঢ় হতেই পরিবেশ নিশুতি রাতের রূপ ধারণ করে।\n\nরাতের এই নির্জন প্রান্তর ঝিঁঝিঁ পোকার ডাকে ছেয়ে গেছে। ঝিঁঝিঁ পোকার সঙ্গে পদ্মজার ভাঙা কান্না মিলেমিশে ভৌতিক পরিবেশ সৃষ্টি করেছে। মনে হচ্ছে কোনো আত্মা তার ইহজীবনের না পাওয়া কোনো বস্তুর শোকে এমন মরা সুর ধরেছে। হেমলতা পদ্মজাকে টেনে পাশে বসালেন। পদ্মজা ডান হাতের উল্টো পাশ দিয়ে চোখের জল মুছে হেমলতাকে বলতে শুরু করল, ‘মামা সৌদিতে যাওয়ার আগের দিন ওই বাড়িতে খালামণি, ভাই, আফা সবাই এসেছিল। সেদিন ঢাকা থেকে যাত্রাপালার লোকও এসেছিল তাই…’\n\nহেমলতা শিকারি পাখির মতো চেয়ে আছে। পদ্মজা কান্নার দমকে কথা বলতে পারছে না। হাত-পা কাঁপছে, তাকে ভীত দেখাচ্ছে। হেমলতা মেয়ের হাত চেপে ধরেন উৎসাহ দিতে ঠিক তখনই উঠোনে ধপ করে একটা আওয়াজ হয়। পদ্মজা কেঁপে উঠল। পূর্ণা, প্রেমা কথা শোনার জন্য দরজায় কান পেতে রেখেছিল। হুট করে কিছু পতনের আওয়াজ হওয়াতে দুজন ভয় পেয়ে দরজা ঠেলে হুড়মুড়িয়ে ঘরে ঢুকে পড়ে। হেমলতা গোপন বৈঠক ভেঙে দ্রুত পায়ে বারান্দায় এসে দাঁড়ান। উঠানে বিদ্যুৎ নেই। পিছনে তিন মেয়ে এসে দাঁড়িয়েছে। হেমলতা গলা উঁচিয়ে খেঁকিয়ে উঠলেন, ‘কে? কে ওখানে?\n\nভাঙা গলায় কেউ খুব কষ্টে উচ্চারণ করল, ‘আমি।’\n\nচির পরিচিত কণ্ঠটি চিনতে বিড়ম্বনা হলো না তার। তিনি দ্রুত পায়ে উঠানে ছুটে যান। গেইটের পাশে নিথরের মতো পড়ে আছে মোর্শেদ মোড়ল। তার গায়ে শীতের চাদর। হাঁপড়ের মতো উঠা-নামা করছে বুক যেন দম ফুরিয়ে যাচ্ছে। হেমলতা চোখেমুখে ছড়িয়ে পড়ে উদ্বেগ। তিনি দুই হাতে মোর্শেদকে আঁকড়ে ধরেন। পদ্মজা, পূর্ণা, দৌড়ে এলো সাহায্য করতে। মোর্শেদের এমফাইসিমা রোগ আছে। এই রোগে অল্প চলাফেরাতেই শ্বাসটানের উপক্রম হয় এবং দম ফুরিয়ে যায়। শ্বাস নেবার সময় গলার শিরা ভরে যায়। তিন মা-মেয়ে মোর্শেদকে ধরে ঘরে নিয়ে যায়।\n\nমোর্শেদ হুট করে বাড়ি ছাড়ে, হুট করেই বাড়ি ফেরে। কখনো কাকডাকা ভোরে, কখনো নিশুতি রাতে, কখনো কাঠফাটা রোদে তার মনে পড়ে নিজ আলয়ের কথা; ফিরে আসে ক্ষিপ্ত ঘোড়ার মতো।\n\nমোর্শেদের এমফাইসিমা রোগটা ধরা পড়ে সাত বছর আগে। তার অ্যাজমা ছিল আবার ধূমপানেও আসক্ত। ফলে ফুসফুসের এই রোগটি খুব দ্রুত আক্রমণ করে বসে।\n\nমোর্শেদ খানিকটা সুস্থ হয়ে রাত একটার দিকে ঘুমিয়ে পড়েন। পূৰ্ণা, প্রেমা ঘরে গিয়ে শুয়ে পড়েছে। পদ্মজা বারান্দার ঘরে ঝিম মেরে বসে আছে। তার চোখের দৃষ্টি জানালার বাইরে। জ্যোৎস্না গলে গলে পড়ছে! কি সুন্দর দৃশ্য! সেই দৃশ্যের দিকে অপলক নয়নে চেয়ে থেকে পদ্মজা ভাবছে, আম্মা এখনো আসছে না কেন?\n\nসে আজ সব বলতে চায়, হৃদয়ের ক্ষত বয়ে বেড়ানো যাচ্ছে না।\n\nকিছুক্ষণের মধ্যে দরজার পাশে এসে দাঁড়ান হেমলতা। হাতে থাকা হারিকেনের তীব্র আলোয় পদ্মজা গুটিয়ে যায়।\n\nহেমলতা হারিকেনের আগুন নিভিয়ে পদ্মজার পাশে গিয়ে বসেন। পদ্মজা সবকিছু বলার জন্য তৈরি ছিল তবুও অপ্রস্তুত হয়ে পড়ে। ভীষণ অস্বস্তি হচ্ছে।\n\nপদ্মজা তখন চতুর্থ শ্রেণির ছাত্রী। বয়স আর কত হবে, নয় কী দশ। খুব কম বয়সেই তাকে স্কুলে পাঠানো শুরু করেছিলেন হেমলতা। হানিফের সৌদি চলে যাবার উপলক্ষ্যে রবিবারের এক সকালে নানাবাড়িতে সবার দাওয়াত পড়ে। স্কুল মাঠেও সেদিন নাচ-গান অনুষ্ঠিত হচ্ছিল। দুপুরের দিকে বাড়ির সবাই সেখানে চলে যায়। বাড়িতে রয়ে যায় শুধু পদ্মজা, পদ্মজার বৃদ্ধ নানা, আর হানিফ। পদ্মজা ঘুমে ছিল তাই বাকিদের সঙ্গে যেতে পারেনি যখন ঘুম ভাঙল আবিষ্কার করল বাড়িতে কেউ নেই। সেদিন মোর্শেদ হঠাৎ করে অসুস্থ হওয়াতে হেমলতা বাপের বাড়িতে ছিলেন না।\n\nবাড়ি থেকে বের হওয়ার উপক্রম হতেই কানে আসে হানিফের ডাক, ‘পদ্ম নাকি?’\n\nপদ্মজা মিষ্টি করে হেসে মাথা নাড়ায়। হানিফের লোলুপ দৃষ্টি তখন পদ্মজার সারা শরীর ঘুরে বেড়াচ্ছে। ওইটুকু মেয়ের ফরসা চামড়া বিকৃত মস্তিষ্কের হানিফকে বড্ড টানে! উপেক্ষা করতে পারে না।\n\nমিষ্টি সুরে হানিফ বলল, ‘আয়, আমার ঘরে আয়।’\n\nসহজ সরল শিশুসুলভ পদ্মজা মামার ডাকে সাড়া দেয়। সে শুনেছে, মামা-ভাগনে যেখানে আপদ নেই সেখানে। অথচ, সেদিন সে মামাকেই ঘোর বিপদ হিসেবে জানল।\n\nপদ্মজা রুমে ঢুকতেই হানিফ চট করে দরজা বন্ধ করে দিল। তার অদ্ভুত চাহনি আর দরজা লাগানোর গতি দেখে পদ্মজার মন কেমন করে ওঠে। হানিফ কুৎসিত অঙ্গভঙ্গি করতে থাকে। পদ্মজার দেখতে খুব খারাপ লাগছে, গা ঝিমঝিম করছে, ভয় হচ্ছে!\n\nহানিফ বিছানায় বসে পদ্মজাকে কাছে ডাকে, ‘এদিকে আয় তোর লগে গল্প করি।’\n\nপদ্মজা কাছে যেতে সংকোচ বোধ করছে। হানিফ পদ্মজার ডান হাতে ধরে টেনে কোলে বসায়। পদ্মজার বাহুতে গভীরভাবে স্পর্শ করে বলে, ‘তুই জানোস তুই যে সবার থাইকা বেশি সুন্দর?’\n\nহানিফের প্রশ্ন পদ্মজার কানে ঢুকেনি। সে মোচড়াতে থাকে কোল থেকে নামার জন্য। আপত্তিকর স্পর্শগুলো পদ্মজাকে খারাপ অনুভূতি দিচ্ছে। তার কান্না পাচ্ছে, মাথা ভনভন করছে। হানিফ গলার জোর বাড়িয়ে মিষ্টি করে বলল, ‘মোছড়াস ক্যান রে ছেড়ি। শান্তিমত বইয়া থাক। মামা মেলা থাইকা সাজনের জিনিষ কিইন্যা দিমু।’\n\nহানিফ দুই হাতে শক্ত করে ধরে রেখেছে পদ্মজাকে। পদ্মজা কিছুতেই কোল থেকে নামতে পারছে না। সে কাঁদো কাঁদো হয়ে বলল, ‘মামা আমি চলে যাব।’\n\nকই যাবি? মামার ধারে থাক।’ বলল হানিফ।\n\nহানিফের শক্তপোক্ত হাতের স্পর্শগুলো শুধু অস্বস্তি দিচ্ছে না, স্পর্শকাতর জায়গাগুলো ব্যাথায় বিষিয়ে তুলছে। পদ্মজা কান্না আটকে রাখতে পারল না, হঠাৎ কেঁদে ওঠল। বলল, ‘ব্যাথা পাচ্ছি মামা। বাড়ি যাব আমি।’\n\nহানিফ হাতের বাঁধন নরম করে আদুরে গলায় বলল, ‘আচ্ছা আর ব্যাথা দিতাম না। কান্দিস না।’\n\nবাঁধন হালকা হতেই পদ্মজা কোল থেকে নেমে পড়ে। হানিফকে তার আজরাইলের মতো লাগছে। মায়ের কাছে সে আজরাইলের অনেক গল্প শুনেছে। আজরাইল যখন জান নিতে আসবে তখন শরীরে খুব কষ্ট অনুভব হবে। এই মুহূর্তে যেন ঠিক তেমনই অনুভূতি হলো। তাহলে তার হানিফ মামাই আজরাইল? পদ্মজা দরজার দিকে তাকায়, অনেক উঁচুতে ছিটকিনি উচ্চতা কম হওয়াতে সে দরজা খুলতে পারবে না। তাই হানিফকে ভীতকণ্ঠে অনুরোধ করল, ‘মামা দরজা খুলে দাও।’\n\nধমকে উঠল হানিফ, ‘ক্যান? আমি তোরে যাইতে কইছি?’ তার কর্কশ কণ্ঠের ধমকে পদ্মজা ভয়ে কেঁপে ওঠল। তার চোখে নহর বইছে। হানিফ পদ্মজাকে জোর করে কোলে তুলে নেয়। পদ্মজা কাঁদছে। বার বার বলছে, ‘মামা আমি বাড়ি যাব।’\n\nহানিফের তাতে বিন্দুমাত্র ভ্রুক্ষেপ নেই। বাড়িতে কেউ নেই। বৃদ্ধ সৎ বাবা বধির, কানে শুনে না। পদ্মজা হানিফকে কিল, ঘুষি দিতে থাকে। ভয়ে জোরে জোরে কান্না শুরু করেছে। এভাবে কাঁদলে পাশের বাড়ির যে কেউ চলে আসবে। হানিফের রক্ত টগবগ করছে উত্তেজনায়। সে দ্রুত ওড়না দিয়ে পদ্মজার হাত, পা, মুখ বেঁধে ফেলল। পদ্মজার দুই চোখের পানি হানিফের হৃদয়কে ছুঁতে পারছে না। সে ভীষণ আনন্দ পাচ্ছে। পৈশাচিক উল্লাসে ভেসে যাচ্ছে। হানিফ সিগারেট জ্বালায়। খুব আনন্দ হলে তার সিগারেট টানতে ইচ্ছে হয়। সিগারেট টানতে গিয়ে মাথায় এলো নৃশংস বাসনা। তাৎক্ষণিক নাক, মুখ দিয়ে ধোঁয়া উড়িয়ে সিগারেটটি দুই আঙুলের মাঝে রেখে পদ্মজার বাম পায়ের তালুতে জ্বলন্ত সিগারেটটি চেপে ধরল।\n\nস্মৃতিচারণ করতে গিয়ে পদ্মজা হাউমাউ করে কেঁদে ওঠে। হেমলতা দুই হাতে শক্ত করে মেয়েকে বুকের সঙ্গে জড়িয়ে ধরেন। পদ্মজা কাঁদতে কাঁদতে বলল, ‘আম্মা, তখন আমার খুব কষ্ট হচ্ছিল। আমার দমটা বেরিয়ে যাচ্ছিল। আমি তোমাকে খুব ডেকেছি আম্মা। তুমি আসোনি।’\n\nপদ্মজার কথাগুলো হেমলতার বুকে ঝড় তুলে দিয়েছে। লণ্ডভণ্ড হয়ে যাচ্ছে শরীরের প্রতিটি শিরা-উপশিরা। এ যেন ১৯৭১ সালের পাকিস্তানিদের নৃশংসতা। নিজের চোখে তিনি দেখেছেন পাকিস্তানিদের নিষ্ঠুরতা। হানিফ আর তার দেখা অত্যাচারী পাকিস্তানিদের মধ্যে কোনো তফাৎ নেই হেমলতা নির্বাক, বাকরুদ্ধ। শুধু অনুভব হচ্ছে তার বুকে পড়ে আদরের পদ্মজা হাউমাউ করে কাঁদছে। হেমলতার সর্বাঙ্গ জ্বলছে। হানিফকে ক্ষত- বিক্ষত করে দিতে হাত নিশপিশ করছে। সেদিন একটুর জন্য পদ্মজা ধর্ষিতা হয়নি। পোড়া স্থানের যন্ত্রণা আর মানসিক চাপ সহ্য করতে না পেরে চৈতন্য হারায়। তখনই বাড়িতে সবাই ফিরে আসে।\n\nবাকিটুকু আর পদ্মজাকে বলতে হয়নি, হেমলতা জানেন। পদ্মজার গা কাঁপিয়ে জ্বর এসেছিল সেদিন। একুশ দিন বিছানায় ছিল। ততদিনে হানিফ দেশ ছেড়ে চলে যায়। পদ্মজা ভয়ে, লজ্জায় ঘটনাটি কাউকে বলেনি। পায়ের পোড়া দাগ দেখে যখন হেমলতা প্রশ্ন করেছিলেন, ‘পা এমনভাবে পুড়ল কী করে?’\n\nপদ্মজা সহজভাবে জবাব দিয়েছিল, ‘চুলার কাছে গিয়েছিলাম। লাকড়ির আগায় পা লেগে পুড়ে গেছে।’\n\nকথাটা পদ্মজা সাজিয়েই রেখেছিল। সঙ্গে অনেক যুক্তি। তাই মিথ্যে বলতে একটুও কাঁপেনি। পুরো ঘটনাটা পদ্মজার বুকে দগদগে ক্ষত হয়ে রয়ে যায়। এই ছয় বছরে লুকিয়ে কতবার কেঁদেছে সে। মনে হলেই চুপ করে কোথাও বসে থাকে। হেমলতা মেয়ের নিশ্চুপতা দেখে মাথা ঘামাননি কখনো। পদ্মজা ছোট থেকেই চুপচাপ ছিল। কিন্তু আজ হেমলতার খুব আফসোস হচ্ছে। নিজেকে অপরাধী মনে হচ্ছে। তিনি ভেবেছিলেন, তার তিনটা মেয়েই তার কাছে খোলা বইয়ের মতো। চাইলেই পড়া যায়। পদ্মজাকে বাড়ির পিছনের নদীর বুক দিয়ে তরতর করে বয়ে যাওয়া স্বচ্ছ টলটলে পানির মতো মনে হতো। যার জীবনে অস্বচ্ছ বলতে কিছু নেই। সবই সাদামাটা, সহজ সরল। অথচ পদ্মজার জীবনেই কত বড় দাগ জ্বলজ্বল করে জ্বলছে! কতবড় ঘটনা লুকিয়ে ছিল! মেয়েরা কথা লুকিয়ে রাখার সীমাহীন ক্ষমতা নিয়ে জন্মায়। কথাটি নিজের মেয়েদের ক্ষেত্রে মাথায় আসেনি।\n\nঅনেকক্ষণ মায়ের বুকে থাকার পর পদ্মজা শান্ত হয়। তখন হেমলতা ধীর কণ্ঠে বললেন, ‘পা টা দেখি।’\n\nপদ্মজা বাঁ পা বিছানায় তুলল। হেমলতা পদ্মজার পা কোলে নিয়ে পোড়া দাগটা দেখলেন মনোযোগ দিয়ে। বুকের ধুকপুকানি বেড়ে যায়, রক্ত টগবগ করে ওঠে। রন্ধ্রে রন্ধ্রে শুরু হয় প্রতিশোধের স্লোগান। তিনি হঠাৎ বলে উঠলেন, ‘এই পোড়া দাগ হানিফের রক্ত দিয়ে মুছব।’\n\nকথাটি কত সহজ করে বলেছেন হেমলতা। কিন্তু পদ্মজার হৃদয় কাঁপিয়ে তুলল। কী যেন ছিল কথাটিতে! তাকে তাকিয়ে থাকতে দেখে হেমলতা বলেন, ‘এখন যা ঘুমিয়ে পড়। কাল স্কুল আছে।’\n\nপদ্মজাকে ঘরে পাঠিয়ে রান্নাঘর থেকে রামদা, ছুরি হাতে নিয়ে উঠানে গিয়ে বসেন হেমলতা। উঠানের এক পাশে একটা বড় পাথর আছে। তিনি সেখানে গিয়ে পাথরটির পাশে বসে ছুরিটি পাথরে ঘষতে থাকলেন। ঘষতে ঘষতে পাথর গরম হয়ে আগুনের স্ফুলিঙ্গ দেখা দেয়। ধার হয়ে গেছে। পদ্মজা ঘর থেকে লুকিয়ে দেখছে। অজানা আশঙ্কায় তার বুক কাঁপছে। হেমলতা বারান্দা পেরিয়ে ঘরে ঢুকতে যাবে তখন পদ্মজা উৎকণ্ঠিত গলায় ডাকল, ‘আম্মা!’\n\nপদ্মজা কিছু বলার পূর্বেই হেমলতা বললেন, ‘আন্নার চাচার বড় মেয়ে বহুবছর আগে নিখোঁজ হয়েছে শুনেছিস তো? সেই মেয়ের ধর্ষক হানিফ ধর্ষণের পর মেয়েটাকে পুঁতে ফেলেছে। অলন্দপুরের এই একটা মানুষই এতটা বর্বর। আমি তখন ঢাকা পড়তাম। বাড়ি এসে ঘটনাটি শুনি। আম্মার অনুরোধ আর কান্নায় আমি সেদিন মুখ খুলিনি। এত বড় পাপ চেপে যাই। সেই শাস্তি আমি ধীরে ধীরে পাচ্ছিলাম। আজ পুরোপুরি পেয়ে গেলাম। আমার পাপের শাস্তি শেষ হয়েছে।’\n\nহেমলতার মুখ দিয়ে যেন আগুনের স্ফুলিঙ্গ বের হচ্ছে! তিনি কথা শেষ করে জায়গা ত্যাগ করলেন। পদ্মজার মস্তিষ্ক শূন্য হয়ে পড়ে।','\n',char(10)),2,'published',0,'2026-10-06T06:37:57.415Z','2026-10-06T06:37:57.415Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('e6652735-95e7-41c3-8f36-05a6ec5c3c0c','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 3',replace('‘এই আপা, স্কুলে যাবা না?’\n\n‘যাব।’\n\n‘তাড়াতাড়ি করো।’\n\nতাড়া দিয়ে পূর্ণা বাড়ির ভেতর চলে গেল। পদ্মজা বাড়ির পেছনের নদীর ঘাটে উদাসীন হয়ে বসে আছে। এ নদীর নাম—মাদিনী। জলে কানায় কানায় ভরে উঠেছে মাদিনী। জলের একটানা স্রোত বয়ে যায় সাগরের দিকে। উজান থেকে ভেসে আসছে ঘন সবুজ কচুরিপানা। পদ্মজার এই দৃশ্য দেখতে বেশ লাগছে, নিষ্পলক চোখে তাকিয়ে আছে মাদিনীর স্বচ্ছ জলের দিকে। একটা লঞ্চ জল কেটে এগিয়ে যাচ্ছে মাদিনীর বুকের ওপর দিয়ে। লঞ্চ দেখে এক মাস আগেকার ঘটনা মনে পড়ে গেল তার।\n\nসেই রাতে হেমলতা ছুরি ধার দিয়ে নিজ ঘরে চলে যান। পদ্মজা অজানা আশঙ্কায় সেদিন ঘুমোতে পারেনি। চুপচাপ অন্ধকার ঘরে শুয়ে থাকে। শেষরাতে চোখ লেগে আসে। ভোর হতেই হিমেলের চিৎকারে ঘুম ভেঙে যায়। হিমেল তার ছোটো মামা, প্রতিবন্ধী। এক পা বাঁকিয়ে হাঁটে। খুব সরল মনের মানুষ। বয়স বাইশ হলেও, এখনো শিশুদের মতো আচরণ করে; কথায় কথায় খুব কাঁদে।\n\nপদ্মজা ওড়না গায়ে জড়িয়ে দৌড়ে বের হয়। পদ্মজাকে দেখে উত্তেজিত হয়ে পড়ে হিমেল, ‘এই পদ্ম, আপা কই? আপা…আপা।’\n\nপদ্মজা উৎকণ্ঠা নিয়ে প্রশ্ন করল, ‘কী হয়েছে মামা? এমন করছ কেন?’ পদ্মজার প্রশ্ন উপেক্ষা করে হিমেল হেমলতাকে ডাকছে, ‘আপা, এই আপা।’\n\nহেমলতা বাড়ির পেছন থেকে ব্যস্ত পায়ে হেঁটে এলেন। ‘কী হয়েছে?’\n\nহেমলতাকে দেখে হাউমাউ করে কেঁদে উঠল হিমেল।\n\n‘আপা, ভাইজান খুন হইছে। রাইতে কে জানি মাইরা ফেলছেরে আপা…’\n\nহিমেল কাঁদতে কাঁদতে হাঁটু ভেঙে বসে পড়ল। পদ্মজা তাৎক্ষণিক সন্দিহান চোখে মায়ের দিকে তাকাল। হেমলতাকে দেখে মনে হচ্ছে, তিনি চমকে গিয়েছেন। অথচ, তার চমকানোর কথা ছিল না। নাকি হিমেলের সামনে অভিনয় করলেন?\n\nহেমলতা দ্রুত পায়ে বাড়ি থেকে বেরিয়ে যেতে যেতে বললেন, ‘পূৰ্ণা- প্রেমাকে ওদিক যেতে দিস না, পদ্ম। আমি আসছি।’\n\nহেমলতার পিছু পিছু খুঁড়িয়ে খুঁড়িয়ে হেঁটে যায় হিমেল।\n\nপদ্মজা রাতেই ভেবেছিল, এমন ঘটনা ঘটতে পারে। সে তার মাকে সবচেয়ে ভালো জানে। তবুও এখন ভয় পাচ্ছে। পুলিশ কি এসেছে? মাকে ধরে নিয়ে যাবে না তো? ভাবতে গিয়ে ধক করে উঠল পদ্মজার বুক। গ্রামের কাছেই শহর, থানা। পুলিশ নিশ্চয় চলে এসেছে। পদ্ম ধপ করে বসে পড়ল মাটিতে। সে ঘামছে, নাক-মুখ-গলা ঘেমে একাকার হয়ে যাচ্ছে।\n\nখুনের কথা শুনে ভীষণ ভয় পেয়েছে পূর্ণা। আতঙ্কে দম বন্ধ হওয়ার উপক্রম। সে পদ্মজার পাশে এসে হাত চেপে ধরে। পদ্মজা মৃদু কাঁপছে। চোখে ভাসছে, হেমলতাকে পুলিশ শিকল দিয়ে বেঁধে নিয়ে যাচ্ছে। তার খুব কান্না পাচ্ছে। সময় নষ্ট না করে তড়িঘড়ি করে মাথায় ওড়নার আঁচল টেনে নিয়ে পূর্ণার উদ্দেশ্যে বলল, ‘প্রেমাকে দেখে রাখিস।’\n\nবাড়ি ভরতি মানুষ। মানুষ আসছে ঠেলেঠুলে। হেমলতা হানিফের লাশের সামনে গিয়ে দাঁড়ালেন। ঠিক সেই মুহূর্তে ফরসা রঙের দুজন মহিলা ঝাঁপিয়ে পড়ল তার ওপর। আকস্মিক আক্রমণে অপ্রস্তুত হয়ে পড়েন হেমলতা। খেয়াল করে দেখেন, মহিলা দুজন তার মা আর বোন। তারা হাউমাউ করে কাঁদছে। কিন্তু হেমলতার তো কান্না পাচ্ছে না! ব্যাপারটা লোকচক্ষু ঠেকছে? একটু কী কান্নার অভিনয় করা উচিত? হানিফের মৃতদেহ দেখে মনে হচ্ছে কেউ ইচ্ছেমতো কুপিয়েছে। হেমলতার দেখে শান্তি লাগছে! এমন শান্তি অনেকদিন পাওয়া হয়নি। পদ্মজাও সেখানে উপস্থিত হয়। হেমলতার নজরে পড়ে। ভীতু চোখে মায়ের চোখের দিকে তাকাল পদ্মজা। হেমলতা ভ্রু কুঞ্চিত করে আবার স্বাভাবিক করে নিলেন। পদ্মজা চোখ ঘুরিয়ে দেখছে পুলিশ এসেছে কি না! চারিদিকে এত মানুষ। পদ্মজাকে এদিক-ওদিক উঁকি দিতে দেখে হেমলতা মেয়ের দিকে তেড়ে যান। চোখ রাঙিয়ে পদ্মজার মাথা ঢেকে দিলেন ওড়না দিয়ে। পদ্মজা দ্রুত ওড়নার আঁচল মুখে চেপে ধরে গোয়ালঘরে ঢুকে পড়ে। তার মা চায় না সে কখনো এত মানুষের সামনে থাকুক।\n\nহেমলতা ঘাড় ঘুরিয়ে দেখেন, পদ্মজা গোয়ালঘর থেকে উঁকি দিয়ে বাইরের অবস্থা পর্যবেক্ষণ করছে।\n\nকিছুক্ষণের মধ্যে পুলিশের দল আসে। সবাইকে জিজ্ঞাসাবাদ করে হানিফের লাশ নিয়ে যায়। লোকমুখে শোনা যায়, হানিফ খুন হয়েছে শেষ রাতে। সকালে লঞ্চ ঘাটে লাশ ভেসে ওঠে!\n\nহেমলতাকে পুলিশ নিয়ে যায়নি বলে পদ্মজা স্বস্তির নিশ্বাস ছাড়ে। মানুষের ভিড়ও কমে গেছে। হেমলতার মা কাঁদতে কাঁদতে ক্লান্ত হয়ে উঠোনের এক কোণে বসে আছেন। পদ্মজা গুটিপায়ে গোয়ালঘর থেকে বেরিয়ে আসে। পদ্মজার দিকে তাকিয়ে মৃদু হাসেন হেমলতা। সেই হাসি দৃষ্টিগোচর হয় হেমলতার মা মনজুরার। তিনি কিছু একটা ভেবে নিয়ে হেমলতার কাছে এসে কিড়মিড় করে বললে, ‘তুই খুন করছস?’\n\nসঙ্গে সঙ্গে হেমলতা জবাব দিলেন, ‘তোমার এমন মনে হচ্ছে কেন?’\n\nহেমলতার কণ্ঠ স্বাভাবিক। পদ্মজা এই প্রশ্ন শুনে ভয় পেয়ে গেছে।\n\nযদি নানু পুলিশকে বলে দেয়? পুলিশ তো তার মাকে নিয়ে যাবে!\n\n‘কাইল রাইতে তুই আইছিলি হানিফের ঘরে। আমি দেহি নাই?’ রাগে কাঁপছেন মনজুরা।\n\n‘হুম এসেছি।’ হেমলতার নির্বিকার স্বীকারোক্তি।\n\n‘কেন মারলি আমার ছেড়ারে? তোর কী ক্ষতি করছে?’\n\n‘আসছি বলেই আমি খুন করেছি?’\n\n‘এত রাইতে তুই তার কাছে আর কী দরকারে আইবি?’\n\n‘আমি তাকে মারতেই যাব কেন?’\n\nমনজুরা আহত দৃষ্টিতে তাকিয়ে আছেন হেমলতার দিকে। হেমলতার চোখ মুখ শক্ত। নিস্তব্ধতা কাটিয়ে মনজুরা চেঁচিয়ে উঠলেন, ‘পুলিশের কাছে যামু আমি।’\n\nপদ্মজা কেঁদে উঠল। অস্পষ্ট কণ্ঠে বলল, ‘নানু, এমন করো না।’ হেমলতা নিচু স্বরে কঠিন করে বললেন, ‘আমার মেয়েদের থেকে আমাকে দূরে সরানোর চেষ্টা করো না, আম্মা। ফল খুব খারাপ হবে।’\n\nপদ্মজার মনে হলো মনজুরা ভয় পেয়ে গেছেন। তার চোখেমুখে ছড়িয়ে পড়েছে শঙ্কা। তিনি সবসময়ই হেমলতাকে ভয় পেয়ে চুপসে থাকেন। পদ্মজা বুঝে উঠতে পারে না, নানু কেন ভয় পায় মাকে? মায়ের অতীতে কী ঘটেছে? কেন তিনি এমন কাঠখোট্টা? ছেলের খুনিকে কোনো মা ছেড়ে দেয়? নানু কেন ছাড়লেন? মেয়ে বলে? নাকি অন্য কারণ আছে? কোনো উত্তর নেই। এসব ভাবলে ভীষণ মাথা ব্যথা হয়। অন্য আট-দশটা পরিবারের মতো তারা নয় কেন? নাকি গোপনে সব পরিবারেই এমন জটিলতা আছে?\n\nপ্রশ্ন হাজারটা!!\n\nউত্তর কোথায়?\n\nসেদিন রাতে খাওয়ার সময় হেমলতা নিম্নস্বরে পদ্মজাকে ডাকেন, ‘পদ্ম?’\n\n‘জি, আম্মা।’\n\n‘আমি হানিফকে খুন করিনি। কারা করেছে তাও জানি না।\n\nকথাটি শুনে পদ্মজা অবাক হয়। তার মা মিথ্যে বলে না। তাহলে কারা খুন করল? পদ্মজা প্রশ্ন করল, তাহলে শেষ রাতে মামার কাছে কেন গিয়েছিলে আম্মা?’\n\nহেমলতা জবাব না দিয়ে খাওয়া ছেড়ে উঠে গেলেন।\n\nপদ্মজার ভাবনার সুতো কাটল কারো পায়ের আওয়াজ শুনে। ঘাড় ঘুরিয়ে মোর্শেদকে দেখতে পেল। মোর্শেদ পদ্মজাকে ঘাটে বসে থাকতে দেখে বিরক্তিতে কপাল কুঁচকে ফেললেন, ‘এই ছেড়ি, যা এন থাইকা।’\n\nজন্মদাতার এমন দূর দূর ব্যবহারে পদ্মজার কান্না পায়। নিঃশব্দে এক ফোঁটা জল গড়িয়ে পড়ে, তা আড়াল করে ব্যস্ত পায়ে বাড়ির ভেতর চলে যায় সে।\n\nকয়েক মাস পর পদ্মজার মেট্রিক পরীক্ষা। নিয়মিত স্কুলে যেতে হয়। তিন বোন বই নিয়ে সড়কে ওঠে। পদ্মজার কোমর অবধি ওড়না দিয়ে ঢাকা। পূর্ণা একনাগাড়ে বকবক করে যাচ্ছে। স্কুলে যাওয়া অবধি কথা বন্ধ হবে না, মাঝে মাঝে জোরে জোরে হাসছেও! মেয়েটার হাসির রোগ আছে বোধহয়। একবার হাসি শুরু করলে আর থামে না। পদ্মজা বার বার বলেছে, ‘আম্মা\n\nরাস্তায় কথা বলতে আর হাসতে মানা করছে। চুপ কর\n\nতবুও পূর্ণা হাসছে। বাড়ির বাইরে এসে সে মুক্ত পাখির মতো আচরণ করে। তাকে দেখে মনে হয়, খাঁচা থেকে মুক্ত হয়েছে।\n\n‘পদ্ম…ওই, পদ্ম। খাড়া।’\n\nপদ্মজা ক্ষেতের দিকে তাকাল। ক্ষেতের আইল ভেঙে দৌড়ে আসছে লাবণ্য। একই সঙ্গে পড়ে দুজন। কাছে এসে হাঁপাতে লাগল লাবণ্য। শান্ত হওয়ার পর চারজন মিলে স্কুলের উদ্দেশ্যে হাঁটা শুরু করে।\n\n‘বাংলা পড়া শিখে এসেছিস বলল পদ্মজা?’\n\nতার প্রশ্ন অগ্রাহ্য করে লাবণ্য বলল, ‘আরে ছেড়ি, বাড়িত শুদ্ধ ভাষায় কথা কইলে বাইরেও কইতে হইব নাকি?’\n\n‘আমি আঞ্চলিক ভাষায় কথা বলতে পারি না।’\n\nলাবণ্য অসন্তোষ প্রকাশ করল। সে অলন্দপুরের মাতব্বর বাড়ির মেয়ে। তাদের বাড়ির সবাই শিক্ষিত। তবুও তারা আঞ্চলিক ভাষায় কথা বলে, পরিবারের দুই-তিন জন সদস্য ছাড়া। আর পদ্মজার চৌদ্দ গুষ্ঠি মূর্খ, দুই- তিন জন ছাড়া…তবুও এমন ভাব করে! আঞ্চলিক ভাষা নাকি পারে না!\n\n‘সত্যি আমি পারি না। ছোটো থেকে আম্মা শুদ্ধ ভাষা শিখিয়েছেন। উনিও এই ভাষাতেই কথা বলেন। তাই শুদ্ধ ভাষায় কথা বলতেই আরাম পাই।’\n\n‘পূর্ণা তো পারে।’\n\n‘আমার চেষ্টা করতে ইচ্ছে হয় না।’\n\n‘আইচ্ছা বাদ দে। শুন, কাইল আমরার বাড়িত নায়ক-নায়িকারা আইব।’\n\nপূর্ণা বিগলিত হয়ে প্রশ্ন করল, ‘কেন আসবে? কোন নায়ক?\n\n‘শুটিং করতে। ছবির শুটিং।’\n\nপদ্মজা এসবে কোনো আগ্রহ পাচ্ছে না। পূর্ণা খুব আগ্রহবোধ করছে। সপ্তাহে একদিন সুমিদের বাড়িতে গিয়ে সাদাকালো টিভিতে ছায়াছবি দেখে, তাই অভিনয় শিল্পীদের প্রতি তার আগ্রহ আকাশছোঁয়া। পূর্ণা গদগদ হয়ে প্রশ্ন ছুঁড়ল, ‘কোন নায়ক নায়িকা? বলো না লাবণ্য আপা!’\n\n‘দাঁড়া! মনে করি।’\n\nপূর্ণা কৌতূহল নিয়ে তাকিয়ে আছে। লাবণ্য চোখ বুজে মনে করার চেষ্টা করল। এরপর মনে হতেই বলল, ‘লিখন শাহ আর চিত্রা দেবী।’\n\n‘আমি আঞ্চলিক ভাষায় কথা বলতে পারি না।’\n\nলাবণ্য অসন্তোষ প্রকাশ করল। সে অলন্দপুরের মাতব্বর বাড়ির মেয়ে। তাদের বাড়ির সবাই শিক্ষিত। তবুও তারা আঞ্চলিক ভাষায় কথা বলে, পরিবারের দুই-তিন জন সদস্য ছাড়া। আর পদ্মজার চৌদ্দ গুষ্ঠি মূর্খ, দুই- তিন জন ছাড়া…তবুও এমন ভাব করে! আঞ্চলিক ভাষা নাকি পারে না!\n\n‘সত্যি আমি পারি না। ছোটো থেকে আম্মা শুদ্ধ ভাষা শিখিয়েছেন। উনিও এই ভাষাতেই কথা বলেন। তাই শুদ্ধ ভাষায় কথা বলতেই আরাম পাই।’\n\n‘পূর্ণা তো পারে।’\n\n‘আমার চেষ্টা করতে ইচ্ছে হয় না।’\n\n‘আইচ্ছা বাদ দে। শুন, কাইল আমরার বাড়িত নায়ক-নায়িকারা আইব।’\n\nপূর্ণা বিগলিত হয়ে প্রশ্ন করল, ‘কেন আসবে? কোন নায়ক?\n\n‘শুটিং করতে। ছবির শুটিং।’\n\nপদ্মজা এসবে কোনো আগ্রহ পাচ্ছে না। পূর্ণা খুব আগ্রহবোধ করছে। সপ্তাহে একদিন সুমিদের বাড়িতে গিয়ে সাদাকালো টিভিতে ছায়াছবি দেখে, তাই অভিনয় শিল্পীদের প্রতি তার আগ্রহ আকাশছোঁয়া। পূর্ণা গদগদ হয়ে প্রশ্ন ছুঁড়ল, ‘কোন নায়ক নায়িকা? বলো না লাবণ্য আপা!’\n\n‘দাঁড়া! মনে করি।’\n\nপূর্ণা কৌতূহল নিয়ে তাকিয়ে আছে। লাবণ্য চোখ বুজে মনে করার চেষ্টা করল। এরপর মনে হতেই বলল, ‘লিখন শাহ আর চিত্রা দেবী।’\n\n‘তুমি আমার ছবির নায়ক-নায়িকা?’\n\n‘হ।’\n\nস্কুলের যাওয়ার পুরোটা পথ লাবণ্য আর পূর্ণা ছায়াছবি নিয়ে আলোচনা করল। মূল বক্তব্যে ছিল সুদর্শন অভিনেতা—লিখন শাহ।','\n',char(10)),3,'published',0,'2026-10-06T06:41:36.583Z','2026-10-06T06:41:36.583Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('0a16c1ec-1b08-4fe4-9d85-d2352aa5e440','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 4',replace('দিনটিকে বড়ো অলক্ষুণে মনে হচ্ছে পদ্মজার। সকালে উঠে দেখে লাল মুরগিটার একটা বাচ্চা নেই। নিশ্চয় শিয়ালের কারবার! রাতে মুরগির খোপের দরজা লাগানো হয়নি। আর এখন চোখে পড়ল, দেয়াল ঘড়িটার কাঁটা ঘুরছে না। ঘড়িটা রাজধানী থেকে হানি খালামণি দিয়েছিলেন। গ্রামে খুব কম লোকই হাতঘড়ি পরে। দেয়াল ঘড়ি হাতেগোনা দুই-তিনজনের বাড়িতে আছে। পদ্মজা সূর্যের দিকে চেয়ে সময়ের আন্দাজ করার চেষ্টা করল। পূর্ণা-প্রেমা দুপুরের খাবার খেয়েই ঘুমিয়ে পড়েছে। আর আম্মা…পদ্মজা পাশের ঘরে উঁকি দিয়ে দেখে হেমলতা মনোযোগ সহকারে সেলাই মেশিনে কাপড় সেলাই করছেন। আটপাড়ায় একমাত্র তিনিই সেলাই কাজ করেন। প্রতিটি ঘরের কারো না কারো পরনে তার সেলাই করা জামা আছে।\n\n‘লুকিয়ে দেখছিস কেন? ঘরে আয়, হঠাৎ বললেন হেমলতা। পদ্মজা লজ্জা পেয়ে বলল, ‘না, আম্মা। কাজ আছে।’\n\nহেমলতা জগ বাড়িয়ে দিয়ে বললেন, ‘পানি ভরে নিয়ে আয়।’\n\nজগ হাতে নিয়ে পদ্মজা বলল, ‘ছদকা কোন মুরগিটা দেব?’\n\nহেমলতা গতকাল স্বপ্নে দেখেছেন, বাড়িতে আগুন লেগেছে। তাই ছদকা দিবেন বলে মনস্থির করেছেন। দুঃস্বপ্ন দেখলেই তিনি ভীষণ অস্থির হয়ে পড়েন, গরিব-দুঃখীদের ছদকা দেয়ার পরই স্বস্তি পান। তার পূর্ণাঙ্গ বিশ্বাস, গরিব-মিসকিনদের দান করলে তাদের দোয়ায় বিপদ কেটে যায়।\n\n‘সাদা মোরগটা। মুন্না এসেছে?’\n\n‘না। প্রতিদিন বিকেলবেলা পানি নিতে আসে। একটু পরই আসবে।’ হেমলতা আর কথা বাড়ালেন না। পদ্মজা কলপাড় থেকে পানি নিয়ে আসে। আছরের আজানের সঙ্গে সঙ্গে মোড়ল বাড়ির কল থেকে পানি নিতে আসে মুন্না। গ্রামে সচ্ছল পরিবার নেই বললেই চলে। হাতেগোনা যে কয়টা পরিবারে সচ্ছলতা বিদ্যমান শুধু তাদের বাড়িতেই টিউবওয়েল আছে। পুরো আটপাড়াতে টিউবওয়েল মাত্র পাঁচটা। পদ্মজাদের টিউবওয়েল থেকে পানি নিতে প্রতিদিন অনেকেই আসে। তার মধ্যে একজন মুন্না; বয়স বেশি নয়, মাত্র দশ। মা হারা ছেলেটির পঙ্গু বাবা সদরে বসে ভিক্ষা করে। মুন্নাকে দেখে রাখার বা যত্ন করার কেউ নেই। এখানে-ওখানে ঘুরে বেড়ায়, কারো মায়া হলে একবেলা নিয়ে দুমুঠো খেতে দেয়।\n\nপদ্মজা মোরগ নিয়ে কলপাড়ে এসে দেখে—মুন্না নেই। একটু সামনে হেঁটে যেতেই ঘাটে দেখতে পেল ছেলেটিকে। ডাকল, ‘এই, মুন্না।’\n\nমুন্না ফিরে তাকাল, পদ্মজার হাতে সাদা মোরগ দেখে খুশিতে জ্বলজ্বল করে ওঠে তার চোখ-মুখ। পদ্মজা না বললেও সে বুঝে গেল—আজ ছদকা পাবে। দাঁত কেলিয়ে হেসে দ্রুত পায়ে এগিয়ে এরো মুন্না।\n\n‘হাসছিস কেন? এই নে মোরগ। তোর আব্বাকে নিয়ে খাবি।\n\nমুন্না খুশিতে গদগদ হয়ে মোরগটিকে দুই হাতে জড়িয়ে ধরল। কী সুন্দর মুন্নার হাসি! তার খুশিতে পদ্মজাও খুশি হলো। বলল, ‘খুব খুশি?’\n\n‘হ’\n\n‘আমাদের জন্য দোয়া করবি।’\n\n‘করবাম, আপা।’\n\n‘আচার খাবি?’\n\n‘হ, খাইবাম।’ কোনো খাবারে ছেলেটার ‘না’ নেই। সে সব খায়।\n\nপদ্মজা আবার হাসল। খাওয়ার কথা শুনলেই পেটুক মুন্নার চোখ চকচক করে ওঠে। আচার নিয়ে আসে পদ্মজা, মুন্নার সঙ্গে ঘাটের সিঁড়িতে বসে আরাম করে দুজন আচার খায়। মুন্না একটু একটু করে খেতে খেতে বলল, ‘আপা, তুমি খুব ভালা।’\n\n‘তাই?’\n\n‘হ। বড়ো হইয়া আমি তোমারে বিয়া করবাম।’\n\nপদ্মজা বিষম খেল। দ্রুত এদিক-ওদিক তাকিয়ে দেখল, কেউ শুনল নাকি। বিয়ে তার কাছে খুব লজ্জাজনক শব্দ। শব্দটি শুনলেই লজ্জায় লাল হয়ে যায় সে, অন্তর কাঁপে। ফিসফিসিয়ে মুন্নাকে জিজ্ঞাসা করে, ‘বিয়ের কথা কোথায় শিখলি?’\n\n‘আব্বা কইছে।’\n\n‘আর বলবি না এসব। যা, বাড়িতে যা।’\n\nপদ্মজা তড়িঘড়ি করে বাড়ির ভেতর চলে যায়।\n\nরান্নাঘরে ঢুকে দেখে, হেমলতা রাতের রান্নার প্রস্তুতি নিচ্ছেন। সন্ধ্যার পর বিদ্যুৎ থাকে না। হারিকেন জ্বালিয়ে রান্না করতে হয়। প্রতিদিন ঘরে একটা, আবার রান্নাঘরে আরেককটা হারিকেন জ্বালানো অনেক খরচের ব্যাপার। তাই বিকেলে রাতের রান্না সেড়ে ফেলেন তিনি।\n\nপদ্মজা উৎসাহ নিয়ে জিজ্ঞেস করল, ‘আম্মা, আমি রাঁধি?’\n\nলাগবে না। সাহায্য কর শুধু।\n\nপদ্মজা চোখ ঘুরিয়ে খুঁজতে লাগল, কী কাজ করা যায়! কিন্তু এমন কিছু পেল না যেটা করা যায়, কোনো সাহায্যের প্রয়োজনই তো নেই-ই! হেমলতা বললেন, ‘লাউ নিয়ে আয়।’\n\n‘লাহাড়ি ঘর থেকে?’\n\n‘লাহাড়ি ঘরে নেই। ছিঁড়ে নিয়ে আয়।’\n\nপদ্মজা এমনভাবে ছুটে যায় যেন মায়ের আদেশ নয়, চাঁদ পেয়েছে!\n\nলাউ, বরবটি, ঢেঁড়স, কাঁকরোল, করলা, চিচিঙ্গা, পটল, ঝিঙাসহ নানা ধরনের সবজির মেলা বাড়ির চারপাশে। পদ্মজা সাবধানে ঘাসের ওপর দিয়ে লাউ গাছের দিকে এগোয়। বর্ষাকাল হওয়াতে জোঁকের উপদ্রব বেড়েছে। অবশ্য জোঁকের ভয় তার নেই।\n\nপদ্মজার গমনপথের দিকে ঝিম মেরে কতক্ষণ চেয়ে রইলেন হেমলতা। মেয়েটাকে দেখলে মাঝেমধ্যে মন বিষণ্নতায় ভরে ওঠে, বুকের ভেতর কীসের যেন অস্থিরতা অনুভব হয়; যুক্তিহীন কিছু চিন্তা ঘুরে বেড়ায় মস্তিষ্ক জুড়ে। পদ্মজার চুল দেখলে মনে হয়, এই সুন্দর ঘন কালো রেশমি চুল পদ্মজার একেকটা কাল রাত। পদ্মজার ছিমছাম গড়নের দুধে-আলতা দেহের অবয়ব দেখলে মন বলে—এই দেহ পদ্মজার যন্ত্রণা। পদ্মজার ওষ্ঠদ্বয়ের নিম্নে স্থির হয়ে থাকা কালো সূক্ষ্ম তিল দেখলে যেন পদ্মজার এক জীবনের কান্নার কারণ। হেমলতা পদ্মজার রূপের বাহার নিতে পারেন না। কেন কৃষ্ণকলির ঘরে ভুবন মোহিনী রূপসীর জন্ম হলো? জন্ম-মৃত্যু-বিয়ে…এই তিনের ওপর কারো হাত থাকে না। যদি থাকত, হেমলতা মোর্শেদকে বিয়ে করতেন না…কিংবা পদ্মজার মতো রূপসীর জন্মও দিতেন না। ভুলেও আল্লাহর কাছে রূপসী মেয়ে চাইতেন না। হেমলতার বুক চিরে ভারি দীর্ঘশ্বাস বেরিয়ে আসে।\n\nআজ শুক্রবার। স্কুল নেই। ফজরের নামাজ আদায় করে তিন বোন পড়তে বসেছে। প্রেমা নামাজ পড়তে চায় না, ঘুমাতে চায়। হেমলতার মারের ভয়ে পড়ে। সে ঝিমুচ্ছে আর পড়ছে। তা দেখে পদ্মজা আর পূর্ণা ঠোঁট টিপে হাসছে। হেমলতা বিরক্ত হোন। প্রেমার তো পড়া হচ্ছেই না…সেই সঙ্গে পদ্মজা আর পূর্ণার মনোযোগ নষ্ট হচ্ছে। তিনি কর্কশ কণ্ঠে ধমকে উঠলেন, ‘প্রেমা, ঘুমাচ্ছিস কেন? ঠিক হয়ে পড়।’\n\nআচম্বিত ধমকে চমকে উঠল প্রেমা, তাড়াতাড়ি পড়া শুরু করল চোখ খুলে। হেমলতা কিছুক্ষণ প্রেমাকে পর্যবেক্ষণ করে স্বাভাবিক গলায় বললেন, ‘পড়তে হবে না। ঘরে গিয়ে ঘুমা।’\n\nপ্রেমা একটু অবাক হয়। পরমুহূর্তেই খুশি হয়ে ছুটে যায় ঘরে। পূর্ণা মুখ ভার করে ফেলল। তারও তো পড়তে ইচ্ছে করছে না। কিন্তু মা কখনো তাকে ছাড় দেন না। হয়তো ছোটোবেলা ছাড় দিতেন, মনে নেই। সে আবার সব কিছু খুব দ্রুতই ভুলে যায়। ব্রেন ভালো প্রেমার, যা পড়ে মনে থাকে। পদ্মজার অবশ্য সবকিছুই স্বাভাবিক…\n\n…শুধু রূপ বাদে।\n\n.\n\nসূর্য ওঠার সঙ্গে সঙ্গে হাতে ঝাকি জাল আর বড়শি নিয়ে মোর্শেদ বাড়িতে ঢুকলেন, কাঁধে পাটের ব্যাগ ঝুলানো। ভোরে মাছ ধরতে গিয়েছিলেন। তিনি বাড়ি ফিরলে পূর্ণা ও প্রেমা সবচেয়ে বেশি খুশি হয়। মাছ খেতে পারে অনেক! অর্থসংকটের জন্য হেমলতা খুব কম মাছ কেনেন। মোর্শেদ যতদিন বাড়িতে থাকেন, ততদিন মাছের অভাব হয় না। মোর্শেদ কিছু বলার আগেই পূর্ণা\n\nও প্রেমা গামলা নিয়ে ছুটে আসে উঠানে। তিনি কাঁধের ব্যাগ উলটে ধরলেন গামলার ওপর। পুঁটি, ট্যাংড়া, পাবদা, চিংড়ি মাছের ছড়াছড়ি লেগে যায়।\n\nহেমলতা মনে মনে ভারি খুশি হোন। পদ্মজা লতা দিয়ে চিংড়ি খেতে খুব পছন্দ করে। আর প্রেমা-পূর্ণা পছন্দ করে পাবদা মাছের ভুনা। আড়াল থেকে পদ্মজা দেখছে, তার ঠোঁটেও হাসি। মেয়েগুলো খুব খুশি হয়েছে মাছ দেখে। মোর্শেদ বাড়ি থেকে বের হতেই লতা আনতে বাড়ির পেছনে ছুটে যাবে পদ্মজা।\n\nপ্রেমার মাথায় হাত বুলিয়ে হেমলতাকে উদ্দেশ্য করে মোর্শেদ বললেন, হুনো লতা। আমার আম্মারারে পাবদা ভুনা কইরা দিবা। সবজি-টবজি দিয়া রানবা না।’\n\n‘আব্বা, আপনি বাড়িতে থাকবেন? তাইলে তো প্রতিদিনই মাছ খেতে পারি,’ বলল পূর্ণা।\n\nমোর্শেদ আড়চোখে আড়ালে লুকিয়ে থাকা পদ্মজাকে একবার দেখে তীক্ষ্ণ চোখে হেমলতার দিকে তাকিয়ে পূর্ণাকে জবাব দিলেন, ‘কোনো রহম অশান্তি না হইলে তো থাকবামই।’\n\nগামছা নিয়ে কলপাড়ে চলে যান তিনি। জন্মদাতার ইঙ্গিত বুঝতে পেরে পদ্মজার মুখটা ছোটো হয়ে যায়। প্রতিবার বাড়ি ছাড়ার আগে মোর্শেদ পদ্মজাকে কটুকথা শোনান। তখন হেমলতা রেগে গিয়ে জবাব দিলে তর্কা- তর্কি করে তিনি বাড়ি ছাড়েন।\n\n‘মোর্শেদ নাকি? বাড়ি ফিরলা কোনদিন?’\n\nমোর্শেদ গোসল সেরে সকালের মিষ্টি রোদ পোহাচ্ছিলেন। ঘাড় ঘুরিয়ে রশিদ ঘটককে দেখে হেসে বললেন, ‘আরে, মিয়া চাচা। আহেন, আহেন। পূর্ণারে চেয়ার আইননা দে। খবর কী?’\n\nপূর্ণা চেয়ার নিয়ে আসে। রশিদ এক দলা থুতু উঠানে ফেলে চেয়ারে বসল আরাম করে। প্রেমাকে উঠানে খেলতে দেখে খসখসে গলায় ফরমায়েশ দিল, ‘এই মাইয়া, যা পানি লইয়া আয়। অনেকক্ষণ ধইরা দমডা আটকাইয়া আছে।’\n\nপ্রেমা রান্নাঘর থেকে পানি এনে দেয়। রশিদ পানি খেয়ে মোর্শেদকে বলল, ‘খবর তো ভালাই। তো বাবা ছেড়িডারে কী বিয়া দিবা না?’\n\n‘দুই বছর যাক। পড়তাছে যহন মেট্রিকটা পাশ করুক। কী কন?’\n\n‘মেজোডা না। বড়োড়া। তোমার বউ তো মরিচের লাহান। কোনোবায় ও রাজি অয় না। তুমি বোঝাও। পাত্র খাঁড়ি হীরা। বাপ-দাদার জমিদারি আছে।’\n\nমোর্শেদ আড়চোখে হেমলতা এবং পদ্মজার উপস্থিতি পর্যবেক্ষণ করলেন— নেই ওরা। তিনি জানেন পদ্মজার উপর কোনোরকম জোরজবরদস্তি তিনি করতে পারবেন না। হেমলতা তা হতে দেবে না। এসব তো আর বাইরের মানুষের সামনে বলা যায় না। মোর্শেদ রশিদ ঘটককে নরম গলায় বললেন, ‘থাকুক না, পড়ুক। মায়ে যহন চায় ছেড়ি পড়ুক তাইলে পড়ুক।’\n\nরশিদ নিরাশ হয়ে তাকিয়ে রইল। ভেবেছিল, মোর্শেদ হয়তো রাজি হবে। রশিদ এতদিন মেয়ের শ্বশুর বাড়িতে ছিল। এরপর বড়ো অসুখে পড়ে। তাই মোর্শেদ বাড়ি ফিরেছে শুনেও আসতে পারেনি। আজ একটু আরামবোধ হতেই ছুটে এসেছে অনেক আশা নিয়ে। কিন্তু মোর্শেদের জবানবন্দিতে সে আশাহত হলো। কটমটে গলায় বলল, ‘যুবতী ঘরে রাহন ভালা না। যহন বংশে কালি পড়ব তহন বুঝবা। হুনো মোর্শেদ, এই বয়সি মাইয়াদের স্বভাব চরিত্র বেশিদিন ভালা থাহে না। পাপ কাম এদের চারপাশে ঘুরঘুর কর। বেলা থাকতে জামাই ধরাইয়া দেওন লাগে। বুঝছ? তোমার বউরে বোঝাও।’\n\nপাত্রের অনেক প্রশংসা করল রশিদ; জমিজমা, বাড়িঘর—সবকিছুর বাড়াবাড়ি রকমের বর্ণনা দিল। রশিদ ঘটক যেতেই মোর্শেদ হেমলতার পাশে গিয়ে বসেন, পদ্মজার বিয়ের কথা তুলেন ইনিয়েবিনিয়ে। হেমলতা সাফ নাকচ করে জানিয়ে দিলেন—কিছুতেই এখন মেয়ের বিয়ে দিবেন না। আর মোর্শেদকে পদ্মজার ব্যাপারে নাক গলাতেও মানা করে দেন। শেষ কথাটা বেশ কঠিন করেই বললেন, ‘আগে বাপ হও। পরে বাপের কাজ করতে এসো।’\n\nমোর্শেদের তিরিক্ষি মেজাজ। রান্নাঘর ছেড়ে বেরিয়ে যান তিনি। রগে রগে তার রাগ টগবগ করছে। পদ্মজাকে বারান্দায় দেখে তিনি ঝাঁঝালো কণ্ঠে বললেন, ‘ছেড়ি যহন রূপ দিয়া নটি হইব, তহন আমার ঠ্যাংও পাইবা না। এই ছেড়ি মজা বুঝাইব।’\n\nকথাটি শুনে পদ্মজার চোখ বেয়ে জল গড়িয়ে পড়ে। হেমলতা রান্নাঘর থেকে বের হয়ে আসেন মোর্শেদকে কিছু কঠিন কথা শোনাতে। পদ্মজা তখন দৌড়ে আসে। হেমলতার হাতে ধরে রান্নাঘরের ভেতরে নিয়ে যায়। মোর্শেদ যতক্ষণ বাড়িতে থাকে, তারও ততক্ষণ খুব ভালো লাগে। পূর্ণা-প্রেমা কত খুশি হয়। বাড়িটা পরিপূর্ণ লাগে। সে চায় না বাবা ঝগড়া করে রাগ নিয়ে বাড়ি ছেড়ে চলে যাক। হেমলতা রাগে এক ঝটকায় মেয়ের হাত সরিয়ে দেন। তার সহ্য হয় না মোর্শেদকে। মানুষের কথা দ্বারা নিয়ন্ত্রিত হওয়া বদমেজাজি একজন মানুষ মোর্শেদ। ভালোটা কখনো বোঝে না, মানুষের কথায় নাচে। সারাক্ষণ একটা বাক্যই যেন জপ করে, ‘লোকে কী বলবে?’\n\n.\n\nমুষলধারে বৃষ্টি হচ্ছে। মাথার ওপর বৃষ্টি নিয়ে মোর্শেদ বাড়ি ফেরেন। মুখ দেখে বোঝা যাচ্ছে তিনি খুব খুশি। হেমলতাকে ডেকে বললেন, ‘এক মাসের লাইগগা ঘরটা ছাইড়া লাহাড়ি ঘরে উইঠঠা পড়ো।’\n\nহেমলতা কিছু বললেন না। তার প্রশ্নবোধক চাহনি দেখে মোর্শেদ বললেন, ‘শুটিং করার লাইগগা মাতব্বর বাড়িত যারা আইছে হেরার নাকি শুটিংয়ের জন্যি আমার বাড়ি পছন্দ হইছে। বিরাট অংকের টেকা দিব কইছে। আমিও কথা দিয়া আইছি।’\n\nহেমলতা রেগে যেতে গিয়েও পারলেন না। সত্যি, টাকা খুব দরকার। পদ্মজার সামনে মেট্রিক পরীক্ষা। কত খরচ! কলেজে পড়াতে ঢাকা পাঠাতে হবে। পদ্মজা যখন ছোটো ছিল তখনো একবার এই বাড়িতে শুটিং হয়েছিল। তিনি কিছুক্ষণ ভেবে বললেন, ‘টাকার কথা আমার সঙ্গে আলোচনা করতে বলো। নয়তো জায়গা হবে না।’\n\n‘আরে..বলামনে। এখন সব গুছাও। ওরা কালই আইব।’\n\nপূর্ণা আড়াল থেকে সবটা শুনেছে। সাত দিন হয়েছে লিখন শাহ আর চিত্রা দেবী অলন্দপুরে এসেছে। অথচ, সে দেখতে পারল না! হেমলতা যেতে অনুমতি দেননি। পূর্ণা নামাজের পর দোয়ায় খুব অনুনয় করে আল্লাহকে বলেছে, যেন লিখন শাহ আর চিত্রা দেবীকে স্বচক্ষে দেখতে পারে। আর এখন শুনছে তাদের বাড়িতেই নাকি আসছে ওরা! পূর্ণার মনে হচ্ছে খুশিতে সে মারা যাবে! বুকের ভেতর দম আটকে আসছে…\n\n…পানি লাগবে…পানি।\n\n.\n\n‘এই, মগা আমাকে এক কাপ চা দাও তো।’\n\nমগা ঝড়ের গতিতে চা নিয়ে আসে। চিত্রার পাশের চেয়ারটা টেনে তাতে বসল লিখন। এরপর মগাকে বলল, ‘দারুণ চা করো তো তুমি! ‘\n\nকাঁচুমাচু হয়ে হাসল মগা। ভাবে বোঝা গেল, প্রশংসা শুনে ভীষণ লজ্জা পেয়েছে। এদিকে মগার ভাবভঙ্গি দেখে হেসে উঠল চিত্রা। চিত্রার হাসির সেই দৃশ্য মুগ্ধ হয়ে দেখছে মগা। মাতব্বর বাড়ির কামলা সে, চিত্রনায়ক লিখন শাহ এবং চিত্র নায়িকা চিত্রা দেবীর সেবা করার দায়িত্ব তাকে দেয়া হয়েছে। চিত্রার সুন্দর মুখশ্রীর সামনে সবসময় থাকতে পারবে ভেবে মগা ভীষণ খুশি। চিত্রা বলল, ‘তোমার ভাইয়ের নামটা যেন কী?’\n\nচার ফুট উচ্চতার মগা উৎসাহ নিয়ে জবাব দিল, ‘মদন।’\n\nচিত্রার হাসি পায়। অনেক কষ্টে চেপে রাখল।\n\nমগা-মদন…এসবও কারো নাম হয়?\n\nশুটিংয়ের মাঝে হুট করে আকাশ ভেঙে বৃষ্টি নামে। তাই আপাতত শুটিং স্থগিত আছে। বারান্দায় বসে বৃষ্টি দেখছে সবাই, প্রত্যেকের হাতে রং চা। ডিরেক্টর আবুল জাহেদের খিচুড়ির স্বাদ অতুলনীয়। তিনি আজ খিচুড়ি রান্না করছেন, বৃষ্টি দেখেই ঢুকে পড়েছেন রান্নাঘরে।\n\nচিত্রা লাহাড়ি ঘরের দিকে তাকিয়ে বলল, ‘আচ্ছা, এই বাড়ির দুইটা মেয়ে কোথায়? আসার পর একবার এসেছিল। এরপর তো আর এলো না।\n\nমগা বলল, ‘ওই যে লাহাড়ি ঘর। ওইডাত আছে।’\n\n‘লাহাড়ি ঘর…সেটা কী?’\n\nমগার বদলে লিখন জবাব দিল, ‘যে ঘরের অর্ধেক জুড়ে ধান রাখা হয়, আর অর্ধেক জায়গায় চৌকি থাকে কামলাদের জন্য—ওই ঘরকে এখানে লাহাড়ি ঘর বলে। বোঝা গেছে?\n\nচিত্রা চমৎকার করে হাসল, ‘বোঝা গেছে। এই মগা, বৃষ্টি কমলে লাহাড়ি ঘরে যাব। ঠিক আছে?’\n\nচিত্রার ‘এই মগা’ ডাক যেন মুহূর্তে মগার জগৎ-সংসারকে স্বর্গ করে তোলে। সে বাধ্যের মতো মাথা নাড়িয়ে বলল, ‘আইচ্ছা, আপা।’\n\nচিত্রা লিখনের দিকে তাকিয়ে বলল, ‘তুমি যাবা? ওই তো সামনেই আলসেমি করো না।’\n\nমগা হইহই করে উঠল, ‘না না, বেঠা লইয়া যাওন যাইত না। বাড়ির মালিকের মানা আছে।\n\nমগার না করার তীব্রতা দেখে ভীষণ অবাক হলো সবাই। চিত্রা প্রশ্ন করল, ‘মানা কেন?’\n\n‘বাড়ির বড়ো ছেড়িডারে তো আপনেরা দেহেন নাই। আগুন সুন্দরী। এই লিখন ভাইয়ের লাহান বিলাই চোখা। ছেড়িডারে স্কুল ছাড়া আর কোনোহানো যাইতে দেয় না। বাড়ি দিবার আগে কইয়া রাখছে—লাহাড়ি ঘরে বেঠামানুষ না যাইতে। এই ছেড়ি লইয়া বহুত্তা কিচ্ছা আছে।’\n\nচিত্রা বেশ কৌতূহল বোধ করল। লিখন তীক্ষ্ণ ঘোলা চোখে লাহাড়ি ঘরের দিকে তাকাল। দেড় দিন হলো এখানে এসেছে। উঠানের শেষ মাথায় থাকা লাহাড়ি ঘরটা একবারো মনোযোগ দিয়ে দেখা হয়নি।\n\nসামনের দরজাটা বন্ধ। দুটো ছোটো মেয়ে এসেছিল ঘরটার ডান পাশ দিয়ে। ঘরটার ডানে-বাঁয়ে-পেছনে গাছপালা। বাড়িটা পুরনো হলেও দারুণ।\n\nতবে এই মুহূর্তে তার অন্যকিছুর প্রতি তীব্র কৌতূহল কাজ করছে।','\n',char(10)),4,'published',0,'2026-10-06T06:43:52.397Z','2026-10-06T06:43:52.397Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('6433c32a-3ade-4248-b3d0-df5fc3689455','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 5',replace('মধ্যখানে চাদর টানিয়ে দুই ভাগ করা হয়েছে লাহাড়ি ঘরকে। একপাশের চৌকিতে হেমলতা এবং মোর্শেদ থাকেন। অন্যপাশেরটা পদ্মজা, পূর্ণা ও প্রেমার দখলে। লাহাড়ি ঘরের পেছনের দরজাটি আপাতত প্রধান দরজা হিসেবে ব্যবহৃত হচ্ছে।\n\nঘরের পেছনে অসংখ্য কচু গাছ ছিল। হেমলতা মোর্শেদকে নিয়ে সব কচু কেটে জায়গা খালি করে সেখানে তৈরি করেছেন মাটির চুলা। বড়ো সড়কে ওঠার জন্য ঝোপঝাড় কেটে সরু করে পথ করা হয়েছে। এতে অবশ্য মোর্শেদের মত ছিল না। সড়কে ওঠার একটা পথ থাকতে আরেকটা পথ তৈরি করার বিপক্ষে তিনি। হেমলতা দুই মেয়েকে নিয়ে সব ঝোপঝাড় সাফ করেছেন। শুটিং দলে অনেক পুরুষ। পদ্মজাকে ভুলেও তাদের সামনে দিয়ে আসা-যাওয়া করতে দেওয়া যাবে না। হেমলতার মাঝে মাঝে ইচ্ছে করে, পদ্মজার মুখ পুড়িয়ে দিতে। পরক্ষণেই নিজের ওপর ঘৃণা হয়। একজন মায়ের মনে কী করে নিজের মেয়েকে নিয়ে এমন ভাবনা আসতে পারে? পদ্মজার হাতে সূচ ফুটলে তার মনে হয় নিজের শরীরে আঘাত লেগেছে। কেন এত টান পদ্মজার প্রতি? ভেতরে ভেতরে এই প্রশ্নের উত্তর তিনি জানেন। শুধু প্রকাশ পায় না, না জানার ভান ধরে থাকেন।\n\nথাকতে হয় তাকে।\n\n‘আম্মা, আজ আমি রাঁধি?’\n\nপদ্মজার প্রতিদিনকার প্রশ্ন! হেমলতা রাঁধতে দেবেন না জানা সত্ত্বেও পদ্মজা প্রতিদিন অনুরোধ করে। হেমলতা বিপদ-আপদ ছাড়া পদ্মজাকে রান্নাঘরে পাঠান না। সোনার শরীরে পাতিলের কালি লাগুক চান না তিনি। হেমলতা হাসেন, পদ্মজা মুগ্ধ হয়ে দেখে। হেমলতার বয়স ছয়ত্রিশ। শ্যামলা চেহারা, দাঁতগুলো ধবধবে সাদা; চোখের মণি অন্যদের তুলনার বড়ো এবং কালো, চোখ দুটিকে পদ্মজার গভীর পুকুর মনে হয়। ছিমছাম গড়ন। পূৰ্ণা যেনো মায়েরই কিশোরী শরীর। তবে তারা তিন বোনই মায়ের মতো চিকন আর লম্বা হয়েছে।\n\nহেমলতা সম্মতি দিয়ে বললেন, ‘আজ তুই রাঁধবি।’\n\nপদ্মজা ভাবেনি অনুমতি পাবে। সে আদুরে উল্লাসে প্রশ্ন করল, সত্যি আম্মা?’\n\n‘সত্যি। আছরের আজান সেই কবে পড়েছে! দ্রুত যা।’\n\nপদ্মজা রান্নার প্রস্তুতি নিচ্ছে। পূর্ণা-প্রেমা হিজল গাছের নিচে পাটি বিছিয়ে লুডু খেলছে। প্রেমা বার বার বাটপারি করায় এ নিয়ে কিছুকক্ষণ পর পর তর্কও হচ্ছে তাদের মাঝে।\n\nসকালে বৃষ্টি হয়েছিল। রান্না করতে গিয়ে পদ্মজা ভেজা মাটির সোঁদা গন্ধ পেল। মাটির ঘ্রাণ তাকে খুব টানে।\n\nমোর্শেদ বাড়ি ফিরে পদ্মজাকে রাঁধতে দেখে কপাল কুঁচকে ফেলেন। ঘরে ঢুকে হেমলতাকে মেজাজ দেখিয়ে প্রশ্ন ছুঁড়ে দিলেন, ‘এই ছেড়ি রান্ধে ক্যান?’\n\nহেমলতা নির্লিপ্তভাবে জবাব দেন, ‘আমি বলেছি।’\n\n‘কতদিন কইছি—এই ছেড়ির হাতের রান্ধন আমারে না খাওয়াইতে?’\n\nমোর্শেদের কঠিন স্বর পদ্মজার কানে আসে। মায়ের অনুমতি পাওয়ার খুশিটুকু মুহূর্তে ফাটা বেলুনের মতো চুপসে যায়। সে জানে এখন ঝগড়া শুরু হবে। তার আম্মা, আব্বার অনুচিত কথাবার্তা মাটিতে পড়তে দেন না। তার আগেই জবাব ছুঁড়ে দেন।\n\n‘খেতে ইচ্ছে না হলে খাবা না।’\n\nরাইতবেলা না খাইয়া থাকবাম আমি?’\n\n‘খাবার রেখেও যদি না খেতে চাও সেটা তোমার সমস্যা। আমি বা আমার মেয়ে কেউই না করিনি।’\n\nমোর্শেদ কিছু নোংরা কথা শোনাতে প্রস্তুত হোন। হেমলতা সেলাই মেশিন রেখে উঠে দাঁড়ান। তিনি বুঝে গিয়েছেন মোর্শেদ কী বলবেন। আঙুল তুলে শাসিয়ে মোর্শেদকে বললেন, ‘একটা নোংরা কথা উচ্চারণ করলে আমি আজ তোমাকে ছাড় দেব না। পদ্ম তোমার মেয়ে। আল্লাহ সইবে না। নিজের মেয়ে সম্পর্কে এত নোংরা কথা কোনো বাবা বলে না।’\n\nমোর্শেদ নোংরা কথাগুলো হজম করে নিলেন। তবে কিড়মিড় করে বললেন, ‘পদ্ম আমার ছেড়ি না।’\n\n‘পদ্ম তোমার মেয়ে। আর একটা কথাও না। বাড়িতে অনেক মানুষ। নিজের বিকৃত রূপ লুকিয়ে রাখ।’\n\nমোর্শেদ দমে যান। চৌকিতে বসে বড়ো করে নিশ্বাস ছাড়েন। চোখের দৃষ্টি অস্থির। পদ্মজার জন্মের পর থেকেই হেমলতার রূপ পালটে গেছে। কিছুতেই এই নারীর সঙ্গে পারা যায় না। অথচ, একসময় হেমলতাকে কত মেরেছেন! হেমলতার পিঠে, উরুতে, ঘাড়ে এখনো মারের দাগ আছে। সময় কোন যাদুবলে হেমলতাকে পালটে দিল, জানা নেই মোর্শেদের।\n\n.\n\nরাতের একটা শুট করে সবাই বিশ্রাম নিচ্ছিল। চিত্রা তখন কথায় কথায় জানাল, ‘মগা যে মেয়েটার কথা বলেছিল, তাকে দেখতে লাহাড়ি ঘরে গিয়েছিলাম।’\n\nচিত্রার কথায় লিখন আগ্রহ পেল না। মেয়েটা কখনো কোনো মেয়ের প্রশংসা করে না। খুঁত খুঁজে বের করে সেটা নিয়ে আলোচনা করতে তার ভীষণ আগ্রহ। নিজেকে সে খুঁতহীন সেরা সুন্দরী মনে করে। ‘মেয়েটার নাম পদ্মজা। মগা, পুরো নামটা যেন কী?’\n\nচিত্রা ওর সঙ্গে কথা বললে, মগা খুব লজ্জা পায়। এখনো পেল। লাজুক ভঙ্গিতে জবাব দিল, ‘উম্মে পদ্মজা।’\n\n‘হ্যাঁ, উম্মে পদ্মজা।’\n\nচিত্রার পাশ থেকে সেলিনা পারভীন প্রশ্ন করলেন, ‘কী নিয়ে আলাপ হচ্ছে?’\n\nসেলিনা পারভীন চলমান চলচ্চিত্রে চিত্রার মায়ের অভিনয় করছেন। চিত্রা বলল, ‘এই বাড়ির মালিক যিনি, উনার বড়ো মেয়ের কথা বলছি। এমন সুন্দর মুখ আমি দুটি দেখিনি। মেয়েটার মুখ দেখলেই বুকের ভেতর নিকষিত, বিশুদ্ধ ভালো লাগার জন্ম হবে। ভগবান এত শ্রী দিয়েছেন মেয়েটাকে!\n\nহতবাক হয়ে গেল লিখনসহ উপস্থিত প্রত্যেকে। চিত্রার মুখে অন্য নারীর প্রশংসা! অবিশ্বাস্য! সবাইকে অবাক হয়ে তাকাতে দেখে বিব্রতবোধ করল চিত্রা। গলার জোর বাড়িয়ে বলল, ‘সত্যি বলছি! সন্ন্যাসী ছাড়া কোনো পুরুষ এই মেয়েকে উপেক্ষা করতে পারবে না।’\n\nপদ্মজাকে নিয়ে বেশ খানিকক্ষণ আলোচনা চলল তাদের মাঝে। আগ্রহ বেশি দেখাল লিখন। কিন্তু যখন শুনল পদ্মজার ষোলো বছর, তখন দমে গেল। ছোটো মেয়ে! হয়তো এমন বয়সি বেশিরভাগ মেয়েরা স্বামীর ঘরে থাকে, তবুও লিখনের পদ্মজাকে খুব ছোটো মনে হচ্ছে। তার একটা বোন আছে, ষোলো বছরের। এখনো দুই বেণি করে স্কুলে যায়, কত ছোটো দেখতে! নিজের ক্ষণ-সময়ের অভিলাষের কথা ভেবে আনমনে হেসে উঠল লিখন। চিত্রা তখনো পদ্মজার রূপের প্রশংসা করছিল।\n\nহিজল গাছের নিচে দাঁড়িয়ে আছে পদ্মজা। রাতের জোনাকি পোকা চারিদিকে। পদ্মজা প্রায় রাতে মুগ্ধ হয়ে দেখে জোনাকি পোকাদের। মনে হয় দল বেঁধে হারিকেন নিয়ে নাচছে তারা! তবে এই মুহূর্তে রাতের সৌন্দর্যটুকু পদ্মজার মনে দাগ কাটতে পারছে না। ঠোঁট কামড়ে কাঁদছে সে, খুব জ্বলছে চোখ দুটো। রান্না খারাপ হওয়ার অজুহাতে থালা ভরতি ভাত-তরকারি তার মুখে ছুঁড়ে দিয়েছেন মোর্শেদ। চোখে ঝোল পড়েছে, তা নিয়ে হেমলতার সে কী রাগ! মোর্শেদ অবশ্য চুপ ছিলেন। তিনি তো রাগ মিটিয়েই ফেলেছেন। আর তর্ক করে কী হবে?\n\nপেছনে এসে হেমলতা দাঁড়ালেন। ডাকলেন, ‘পদ্ম?’\n\nপদ্মজা তাকাল।\n\nহেমলতা ভেজা কণ্ঠে প্রশ্ন করলেন, ‘খুব জ্বলছে?’\n\nপদ্মজা জবাব দিতে পারল না। ঠোঁট ভেঙে কেঁদে উঠল। মা ছাড়া পৃথিবীতে আর কেউ নেই তার। মা বাদে আর কারো আদরও পাওয়া হয়নি। সবাই তার দোষ খোঁজে। হেমলতার বুক চিরে দীর্ঘশ্বাস বেরোল। পদ্মজা ছিঁচকাঁদুনে। ছোটো থেকে বাবার অনাদর আর অপমানে বিদ্ধ হয়ে কেঁদে চলেছে তবুও চোখের জল ফুরোয় না, মন শক্ত হয় না। এমন হলে তো চলবে না!\n\nপদ্মজার কান্নার বেগ বাড়ল। হেমলতা সদ্য কাটা বড়ো গাছটির গুঁড়িতে বসে, চুপ করে পদ্মজার ফোঁপানো শুনছেন। একটিবারের জন্যও কান্না থামানোর চেষ্টা করলেন না। যখন চাঁদ মাথার উপরে চলে এলো তখন ক্লান্ত হয়ে পদ্মজা নিজেই থেমে গেল। শান্ত হয়ে বসল মায়ের পাশে। হেমলতা উদাস গলায় বললেন, ‘এভাবে চলবে না পদ্ম।\n\nপদ্মজা মায়ের দিকে তাকাল। হেমলতা বললেন, ‘শোন পদ্ম, কেউ আঘাত করলে কাঁদতে নেই। কারণ মানুষ আঘাত করে কাঁদানোর জন্যই। যখন উদ্দেশ্য সফল হয়ে যায় তখন তারা শান্তি পায়। যে তোকে আঘাত করল তাকে কেন তুই শান্তি দিবি? শক্ত থাকবি। বুঝিয়ে দিবি তুই এত দুর্বল না। যাকে তাকে পাত্তা দিস না। হাজার কষ্টেও কাঁদবি না। কান্না সাময়িক সময়ের জন্য মন হালকা করে। পুরোপুরি নয়। যে তোকে আঘাত করবে তাকে তুই তোর চাল-চলন দিয়ে ছিন্নভিন্ন করে দিবি। তখন তার মুখটা দেখে তোর যে শান্তিটা হবে সেটা কান্না করার পর হবে না। এই শান্তি স্থায়ী!’\n\nহেমলতার কথা পদ্মজার ওপর প্রভাব ফেলল না। সে করুণ স্বরে বলল, ‘কিন্তু আব্বার ব্যবহার আমার সহ্য হয় না আম্মা। আমার সঙ্গে কেন এমন করে আব্বা?\n\n‘তাকে কখনো সামনাসামনি আব্বা ডাকার সুযোগ পেয়েছিস? পাসনি! তবুও কেন আব্বা-আব্বা করিস? তুইও তাকে পাত্তা দিবি না।’\n\n‘তুমি খুব কঠিন আম্মা।’\n\n‘তোকেও হতে হবে।’\n\n‘আব্বা কেন এমন করে, আম্মা? আমি কি আব্বার মেয়ে না? আব্বা কেন বার বার বলেন, আমি তার মেয়ে না।’\n\nএহেন প্রশ্নে হেমলতা চোখ সরিয়ে নিলেন। পদ্মজা জানে এই জবাব সে পাবে না। সে দাঁতে দাঁত চেপে কান্না আটকানোর চেষ্টা করল।\n\nহেমলতা পরম স্নেহে একহাত পদ্মজার মাথায় রেখে বললেন, ‘কাঁদিস না আর। মায়ের রং না হয় পাসনি। মায়ের মতো শক্ত হওয়ার তো চেষ্টা করতেই পারিস।’\n\nপদ্মজা নির্লজ্জ হয়ে আবার প্রশ্ন করল, ‘আম্মা, আমি কি আব্বার মেয়ে না? বলো না আম্মা।’\n\nপদ্মজার চোখ বেয়ে জল পড়ছে। মায়া হচ্ছে হেমলতার, বুক ভারি হয়ে আসছে। তিনি আবেগ লুকিয়ে কণ্ঠ কঠিন করার চেষ্টা করলেন, ‘মার খাবি, পদ্ম। কতবার বলব, তুই আমার আর তোর আব্বার মেয়ে!’\n\n‘কী নাম আমার আব্বার?’\n\nকী শান্ত কণ্ঠ পদ্মজার! হেমলতা চমকালেন, তবে তা প্রকাশ করলেন না। মেয়েদের সামনে তিনি কখনো দুর্বল হতে চান না। পদ্মজার দিকে ঝুঁকে কণ্ঠ খাদে নামিয়ে বললেন, ‘তোর আব্বার নাম, মোর্শেদ মোড়ল।’\n\nপদ্মজা হতাশ হয়ে দীর্ঘশ্বাস ছাড়ল। মার ওপর বিরক্তি জন্মাছে, খুব কঠিন করে বলতে ইচ্ছে হচ্ছে, যাও এখান থেকে। আমার কাছে আর আসবে না। কখনো না।’\n\nকিন্তু এমন ব্যবহার কখনো করতে পারবে না সে…কক্ষনো না। রাতের বাতাসে ভেসে আসছে হাসনাহেনা ফুলের ঘ্রাণ, আকাশে থালার মতো চাঁদ; ঝিরিঝিরি মোলায়েম বাতাস চারিদিকে। পদ্মজার চোখের জল শুকিয়ে যায়। হেমলতা ঝিম মেরে বসে আছেন। মা-মেয়ে পাশাপাশি বসে থেকেও যেন কত দূরে! নিজেদের মতো ভেবে যাচ্ছে এটা-সেটা নিয়ে। হঠাৎ নিস্তব্ধতা কাটিয়ে একটা অসহায় কণ্ঠ ভেসে এলো: ‘মায়েরা তাদের জীবনের গোপন গল্প সন্তানদের বলতে পারে নারে পদ্ম।’\n\nপদ্মজা তাকাল। হেমলতা ছলছল চোখে তাকিয়ে আছেন। পদ্মজার বুকের ভেতরটা হু হু করে ওঠে। এই মানুষটাকে এত নরম রূপে মানায় না।\n\nমাকে আশ্বস্ত করে পদ্মজা বলল, ‘আমি আর কখনো জানতে চাইব না আম্মা।’\n\nশুটিং দলের একজনও বাড়িতে নেই। সবাই স্কুল মাঠে গেছে। কয়দিন ধরে নদীর ঘাটে যেতে না পেরে তৃষ্ণার্থ হয়ে উঠেছে পদ্মজা। এই সুযোগ হাতছাড়া করা যায় না। হেমলতার অনুমতি নিয়ে সে ঘাটে চলে যায়, সিঁড়িতে বসে আয়েশ করে। কয়েক মুহূর্ত পর শুনতে পায়, গান বাজছে কোথাও। পদ্মজা গানের সুর অনুসরণ করে নিচের দিকে নামে। ঘাটের বাঁ- পাশে বাঁধা নৌকায় একজন পুরুষ বসে আছে, হাতে রেডিয়ো। গানের উৎস তাহলে এখানেই। পদ্মজা বিব্রতবোধ করে। দ্রুত উলটো দিকে ঘুরে ব্যস্ত পায়ে চলে আসে লাহাড়ি ঘরে। তাকে এত দ্রুত ফিরতে দেখে হেমলতা প্ৰশ্ন করলেন, ‘কেউ ছিল?’\n\nপদ্মজা ওপর-নিচে মাথা নাড়াল। হেমলতা চিন্তিত স্বরে প্রশ্ন ছুঁড়লেন, ‘কিছু বলেছে? দেখতে কেমন?’\n\n‘না, আম্মা, কিছু বলেনি। আমাকে দেখেনি। মাথার চুল ঝাঁকড়া। মুখ খেয়াল করিনি।’\n\nপূর্ণা অংক করছিল। পদ্মজার মুখে আগন্তুকের বর্ণনা শুনে হই হই করে উঠল, ‘এইটাই তো লিখন শাহ, নায়ক।’\n\nহেমলতা আড়চোখে মেয়ের দিকে তাকান। নায়ক-নায়িকাদের প্রতি পূর্ণার যে তীব্র আগ্রহ, তা ভালো লাগে না তার। পূর্ণা মায়ের চাহনি দেখে দমে যায়।\n\nসারাক্ষণ শুটিং দলের আশপাশে ঘুরঘুর করে মেয়েটা। হেমলতা বিরক্ত হয়ে তাকে কড়া নিষেধ দিয়েছেন, আর যেন না যায়; যদি যায়…মার একটাও মাটিতে পড়বে না। পূর্ণা ভয় পেয়েছে। কিন্তু লিখন শাহ আর চিত্রা দেবী জুটিটা এত ভালো লাগে তার যে শুটিং না দেখলে দম বন্ধ হয়ে আসে। তাই সে চুপিসারে টিনে একটা ছিদ্র করেছে। হেমলতা সেলাই মেশিন রেখেছেন লাহাড়ি ঘরের পেছনের বারান্দায়, সারাক্ষণ সেখানেই থাকেন। সেই সময় পূর্ণা ছিদ্র দিয়ে উঁকি দিয়ে শুটিং দেখে।\n\nপূর্ণার এই আচরণ দেখতে দেখতে একদিন পদ্মজারও আগ্রহ জন্মাল। সাত-পাঁচ ভেবে একদিন উঁকি দিয়ে বসল সে-ও।\n\nঝাঁকড়া চুলের মানুষটি একজন অতি সুন্দরী মেয়েকে কোলে তুলে নিয়েছে। মানুষটির দৃষ্টি মোহময়। বাড়ি জুড়ে গানের সুরধ্বনি। কেউ কেউ ক্যামেরা ধরে রেখেছে। গানের শুটিং চলছে বোধহয়! অদ্ভুত ঠেকছে পদ্মজার, লজ্জা পেয়ে চোখ সরিয়ে নিলো সে।','\n',char(10)),5,'published',0,'2026-10-06T06:48:30.165Z','2026-10-06T06:48:30.165Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('be2f7de0-34ef-4bdf-b71b-ebe95ae0d8c5','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 6',replace('রাতে ঝড় উঠেছিল। লণ্ডভণ্ড হয়ে গেছে বহু গাছপালা। লাহাড়ি ঘরের পেছনে তৈরি পথ বন্ধ হয়ে গেছে গাছের ভাঙা ডালপালা পড়ে। মোর্শেদ রাতে বাড়ি ফেরেননি। হেমলতার একার পক্ষে সম্ভব নয় ডালপালা সরানো। তাই পদ্মজা আর পূর্ণা স্কুল থেকে ফিরছিল বাড়ির সামনের পথ দিয়ে। উঠোনে শুটিং দলের সবাই উপস্থিত। পদ্মজার মাথা নত, ঘোমটা টানা লম্বা করে। এত মানুষের সামনে দিয়ে যেতে তার হাঁটু কাঁপছে। আজ যেন পথ শেষই হচ্ছে না। উপস্থিত অনেকের নজরে চলে এলো পদ্মজা। মিলন নামে একজন পূর্ণাকে ডাকল, ‘এই পূৰ্ণা!’\n\nপূর্ণা দাঁড়াল, সঙ্গে পদ্মজা; যদিও মেয়েটা শুটিং দলটির দিকে তাকাচ্ছে না। মিলন পদ্মজার দিকে চোখ স্থির রেখে পূর্ণাকে প্রশ্ন করল, ‘পাশের মেয়েটা কে? প্রথম দেখছি।’\n\n‘আমার বড়ো আপা।’\n\n‘আপন?’\n\nমিলন আশ্চর্য হয়ে বলল। দশ দিন হলো তারা এখানে এসেছে, কখনো পূর্ণা-প্রেমা ছাড়া কোনো মেয়েকে চোখে পড়েনি, কণ্ঠও শোনা যায়নি। তাই বড়ো বোন বলাতে সে খুব অবাক হলো। পূর্ণা হেসে বলল, ‘হুম। আপন। ‘\n\nমিলন বিড়বিড় করে বলল, ‘চেহারায় তো মিল নেই।’\n\n‘সবাই বলে।’\n\n‘আচ্ছা, যাও।’\n\nদুই বোন লাহাড়ি ঘরে চলে যায়, হাঁফ ছেড়ে বাঁচে পদ্মজা। ভেতরটা এত কাঁপছিল! সে অনেক মানুষের পা দেখেছে, তবে চোখ তুলে তাদের মুখ দেখার সাহস হয়নি। কিন্তু হ্যাঁ…ইচ্ছে হয়েছিল বটে! সিনেমায় যারা অভিনয় করে, তারা দেখতে কেমন? সাধারণ মানুষের মতোই?\n\nনাকি অন্যরকম?\n\n.\n\nবিকেলে হাজেরা নামক এক মহিলা আসে মোড়ল বাড়িতে, সে সবুর মিয়ার স্ত্রী। সবুর দিনরাত গাঁজা খেয়ে পড়ে থাকে, বউ-বাচ্চাদের খোঁজ রাখে না। হাজেরা এর-ওর বাড়ি গিয়ে এটা-ওটা চেয়ে নেয়, খায় দুই বাচ্চাকে সঙ্গে নিয়ে। পদ্মজার খুব মায়া হয় হাজেরার জন্য। মহিলা আসতেই হেমলতা পদ্মজাকে প্রশ্ন করলেন, ‘গাছে কয়টা লাউ আছে?’\n\n‘নয়টা, আম্মা।’\n\n‘পূর্ণা কোথায়? ওরে বল দুইটা লাউ হাজেরাকে দিয়ে দিতে। কাঁচামরিচও দিতে বলবি।’\n\nপদ্মজার নীরবতা দেখে হেমলতা বুঝতে পারেন পূর্ণা বাড়িতে নেই। ‘পূর্ণা কী টিভি দেখতে গেছে?’\n\nপদ্মজাকে দ্বিধাগ্রস্ত হতে দেখা গেল। বিব্রতভাবে বলল, ‘আম্মা, আমাকে ব…বলে গেছে।’\n\n‘তুই ওর অভিভাবক? একটু শরীরটা খারাপ লাগছিল বলে শুয়েছিলাম। ওমনি সুযোগ লুফে নিয়েছে!\n\n‘আম্মা, আমার দোষ। পূর্ণাকে কিছু বোলো না।\n\nপদ্মজার ভেজা কণ্ঠ হেমলতার রাগ উড়িয়ে দিল। তিনি অন্য দিকে মুখ করে শুয়ে বললেন, ‘হাজেরাকে নিয়ে যা। ঘোমটা টেনে যাবি। বেগুন বেশি থাকলে কয়টা দিয়ে দিস।’\n\nপদ্মজার মন ভরে গেল। তার মা এত বেশি উদার! কখনো কাউকে ফিরিয়ে দেন না। সামর্থ্যের মধ্যে আরো বেশি কিছু দেওয়ার মতো থাকলে, তিনি কখনো কার্পণ্য করেন না। তবে হাজেরার স্বভাব অভাবে নষ্ট হয়ে গেছে, চুরি করার প্রবণতা আছে তার মাঝে। তাই পদ্মজাকে সঙ্গে যেতে বলেছেন।\n\nউঠোনের এক কোণে, লাহাড়ি ঘরের ডান পাশে লাউয়ের মাচা। নয়টা লাউ ঝুলছে তাতে। চোখের সামনে শুধু তরতাজা, টাটকা সবুজ পাতা। পদ্মজা বাড়ির দিকে তাকাল না। একটা লাউ হাজেরার হাতে দিয়ে বলল, ‘কী দিয়ে রান্না হবে?’\n\n‘জানি না গো পদ্ম। গিয়া দেহি মাছ মিলানো যায়নি।’\n\n‘তোমার ছোটো ছেলের ঠান্ডা কমেছে?’\n\nপদ্মজা কাঁচামরিচ ছিঁড়ে হাজেরার আঁচল ভরে দিল। হাজেরা গুঞ্জন করে কাঁদছে আর বলছে, ‘ছেড়াডা সারাদিন মাডিত পইড়া থাহে একলা একলা। রাইত হইলে জ্বরে কাঁপে। দম ফালাইতে পারে না।’\n\n‘ডাক্তার দেখাচ্ছ না কেন?’\n\n‘টেহা লাগব না? কই পামু?’\n\n‘তুমি মাতব্বর বাড়িতে যাও। শুনছি, উনারা খুব দান-খয়রাত করেন।’\n\nহাজেরা বাধ্যের মতো মাথা নাড়াল। বেগুন গাছ বাড়ির পেছনে। সাবধানে বাড়ির পেছনে গেল পদ্মজা। সে মনে মনে ভাবছে—হাজেরার ছেলে সুস্থই আছে। সকালেই দেখেছে ছেলেটাকে, দিব্যি খেলাধুলা করছিল। দেখে যে কেউ বলবে: সুস্থ। হাজেরা মিথ্যা বলছে।\n\nমানুষের খুব অভাব পড়লে বুঝি এমনই হয়?\n\n‘এতো সবজি আছে! টমেটো নেই? পাওয়া যাবে?\n\nপরিষ্কার সহজ গলায় বলা পুরুষালী কণ্ঠটা পদ্মজাকে মৃদু কাঁপিয়ে তুলল। ঘুরে তাকাল সে, ব্রিত বোধ করল লিখনকে দেখে। কারো সামনে নিজের অস্বস্তি প্রকাশ করা উচিত না—কথাটি হেমলতা বলেছেন। পদ্মজা হাসার চেষ্টা করে জবাব দিল, ‘এই বর্ষাকালে টমেটো কোথায় পাবেন?\n\n‘বর্ষাকালে টমেটো চাষ হয় না?’\n\n‘টমেটো শীতকালীন ফসল।’\n\n‘গ্রীষ্ম-বর্ষাতেও তো পাওয়া যায়।’\n\nপদ্মজা অস্বস্তি লুকিয়ে রাখতে পারছে না। স্কুলের শিক্ষক আর খুব আপন মানুষগুলো ছাড়া কোনো পর-পুরুষের সঙ্গে তার কখনো কথা হয়নি। লিখনের সঙ্গে কথা বলতে গিয়ে জবান বন্ধ হয়ে যাচ্ছে। সে চুপচাপ বেগুন বুঝিয়ে দিল হাজেরাকে। লিখন বলল, ‘আমি তো গতবার বর্ষাকালেও টমেটোর সালাদ তৈরি করেছি!’\n\n‘হয়তো টমেটোর জাত আলাদা ছিল। আমাদের এখানে সাধারণত শীতকালেই টমেটো হয়।’\n\nদ্রুত জবাব দিয়ে লাহাড়ি ঘরে ফিরল পদ্মজা। মনে হচ্ছে পর-পুরুষের সঙ্গে কথা বলে ঘোর পাপ করে ফেলেছে, পাপ মোচন করতে হবে। ঘরে ঢুকে ঢকঢক করে দুই গ্লাস পানি খেল। হেমলতা ঘুমাচ্ছেন। নয়তো পদ্মজার মুখ দেখে নির্ঘাত বুঝে যেতেন, কিছু একটা ঘটেছে। পদ্মজা ভক্তি নিয়ে আল্লাহ তায়ালার প্রতি শুকরিয়া আদায় করল।\n\n.\n\nহেমলতা সালোয়ার-কামিজ সেলাই করছিলেন। তখন বারান্দার সামনে একজন পুরুষ লোক এসে দাঁড়াল। শাড়ির আঁচল মাথায় টেনে নিলেন হেমলতা, জিজ্ঞাসু দৃষ্টি নিয়ে তাকালেন লোকটা দিকে। লোকটি হেসে বলল, ‘আমি শুটিং দলের মিলন।’\n\nহেমলতা জোরপূর্বক হাসার চেষ্টা করলেন। আড়চোখে তাকালেন ঘরের দরজার দিকে। পদ্মজা ঘুমাচ্ছে, দরজাটা লাগানো দরকার। তিনি সোজা প্রশ্নে চলে যান, ‘কোনো দরকার?’\n\n‘না, এমনি দেখতে আসলাম। কতদিন হলো আপনাদের বাড়িতে উঠলাম। এদিকটায় আসা হয়নি।’\n\nহেমলতা পেঁচিয়ে কথা বলা পছন্দ করেন না। সরাসরি বলে উঠলেন, ‘এদিকে আসা নিষেধ। আপনাদের বলা হয়নি?’\n\nমিলনের জ্বলজ্বল করা চোখেমুখে ছায়া নেমে আসে, অপমানিত বোধ করল সে। আমতা আমতা করে বলল, ‘ইয়ে…আচ্ছা, আসছি।’\n\nমিলন স্থান ত্যাগ করল। তবে যাওয়ার পূর্বে তার তীক্ষ্ণ চোখের দৃষ্টি হেমলতার নজর এড়াতে পারল না। হেমলতা চোখ বুজে জীবনের হিসেব কষেন, নরম দৃষ্টিতে তাকান ঘুমন্ত পদ্মজার দিকে। তিনি নিশ্চিত, এই লোক পদ্মজাকেই দেখতে এসেছিল।\n\nএখন পূর্ণার চেয়ে পদ্মজার বেশি আগ্রহ শুটিং দেখার। টিনের ছিদ্র আরো দুটো করেছে। লিখন শাহকে দেখলে তার ঠান্ডা, কোমল অনুভূতি হয়। এই অনুভূতির নাম সে জানে না। শুটিংয়ে লিখন শাহ কত ভালোবাসেন চিত্রা দেবীকে, পদ্মজার দেখতে খুব ভালো লাগে।\n\nপূর্ণা তেলের বোতল নিয়ে বলল, ‘আপা, তেল দিয়ে দাও না।’\n\n‘সোনা বোন, একটু দাঁড়া।’\n\nপদ্মজা ছিদ্র দিয়ে লিখন শাহর হাসি, কথা বলার ভঙ্গী দেখছে। লজ্জাও পাচ্ছে। সময়টাকে থামিয়ে দিতে ইচ্ছে হচ্ছে তার।\n\n‘এই আপা। পরেও তো দেখতে পারবে। দিয়ে দাও না।’\n\n‘আরেকটু। শুটিং শুরু হচ্ছে। একটু…’\n\nপূর্ণার রাগ হয় খুব। কিন্তু সে আপাকে কিছু বলবে না। তার সব ইচ্ছের সঙ্গী, সব গোপন কথার স্বাক্ষী তার আপা। আপাকে খুব ভালোবাসে সে। মাঝে মাঝে মনে হয়…সেই ভালোবাসাটুকু যেন মায়ের প্রতি ভালোবাসার চাইতেও বেশি…কিংবা হয়তো না। পদ্মজা মিটিমিটি হাসছে। পূর্ণা তেল রেখে ছিদ্র দিয়ে উঁকি দিল।\n\nনাহ! তার এখন ভালো লাগছে না এসব দেখতে। চোখ সরিয়ে নিলো সে।\n\n‘কী রে পদ্ম? কী দেখছিস?’\n\nহেমলতার কণ্ঠ শুনে চমকে উঠল পদ্মজা। আরক্ত হয়ে উঠল তার গাল। ডাকাতি করতে গিয়ে বাড়ির মালিকের কাছে ধরা পড়লে যেমন অনুভূতি হয়, তেমন অনুভূতি হচ্ছে তার। উহু, এই অনুভূতি আরও বেশি ভয়ংকর! হেমলতার দৃষ্টি গেল টিনের ছিদ্রের দিকে। সঙ্গে সঙ্গে পদ্মজা অনুভব করল, তঁর পায়ের নিচের মাটি কাঁপছে। পূর্ণা ভয়ার্ত চোখে একবার মাকে একবার বোনকে দেখছে।\n\nছিদ্রের গুরু তো সে! মারও সে খাবে।','\n',char(10)),6,'published',0,'2026-10-06T07:57:18.107Z','2026-10-06T07:57:18.107Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('c91ca802-1138-4b4d-a8c5-2d0f738ba5a0','8caaf332-af80-4e3d-b609-c16e6dd8ec0e','শেষের কবিতা',replace('শেষের কবিতা\n\nরবীন্দ্রনাথ ঠাকুর\n\n১. অমিত-চরিত\n\nশিলং পাহাড়ের পথে একদিন মোটরগাড়ি চালাতে গিয়ে অমিত রায়ের সঙ্গে দুর্ঘটনা ঘটতে বসেছিল। অমিত ছিল শিক্ষিত, বুদ্ধিমান, রসিক এবং নিজের চিন্তাভাবনা নিয়ে অত্যন্ত আত্মবিশ্বাসী এক তরুণ। বিলেতে পড়াশোনা করে সে দেশে ফিরেছে। বই, সাহিত্য, কবিতা আর তর্ক—এসব তার জীবনের বড় অংশ।\n\nঅমিতের স্বভাব ছিল প্রচলিত নিয়মকে সহজে মেনে না নেওয়া। কোনো বিষয় নিয়ে অন্যেরা যে মত পোষণ করে, অমিত তার উল্টো দিকটি নিয়ে তর্ক করতে ভালোবাসত।\n\nশিলংয়ে তার পরিচয় হয় লাবণ্যের সঙ্গে।\n\n২. সংঘাত\n\nলাবণ্য ছিল অমিতের সম্পূর্ণ বিপরীত প্রকৃতির। শান্ত, সংযত, গভীর চিন্তাশীল এবং আত্মমর্যাদাসম্পন্ন। প্রথম পরিচয়েই দুজনের মধ্যে কথার লড়াই শুরু হয়।\n\nতাদের কথোপকথনে ছিল বুদ্ধির ঝিলিক। একজন আরেকজনকে সহজে ছেড়ে দিতে রাজি নয়। কিন্তু সেই তর্কের আড়ালেই জন্ম নিচ্ছিল এক অদ্ভুত আকর্ষণ।\n\nঅমিত বুঝতে পারল, লাবণ্য অন্যদের মতো নয়।\n\n৩. পূর্ব ভূমিকা\n\nঅমিতের অতীত, তার পরিবার এবং তার চিন্তাভাবনার সঙ্গে লাবণ্যের পরিচয় ধীরে ধীরে গভীর হতে থাকে। অমিতের জীবনে যেমন আধুনিকতার প্রভাব ছিল, তেমনি তার মধ্যে ছিল গভীর সাহিত্যপ্রেম।\n\nলাবণ্যও সাধারণ অর্থে শুধু প্রেমের মানুষ ছিল না। তার নিজের চিন্তা, আত্মসম্মান এবং জীবনের প্রতি নিজস্ব দৃষ্টিভঙ্গি ছিল।\n\nএই কারণেই তাদের সম্পর্ক অন্যরকম হয়ে উঠল।\n\n৪. লাবণ্য-পুরাবৃত্ত\n\nলাবণ্যের অতীতেও একটি সম্পর্কের স্মৃতি ছিল। শোভনলাল তার জীবনের সঙ্গে কোনো এক সময়ে যুক্ত ছিল।\n\nকিন্তু অমিতের সঙ্গে পরিচয়ের পর লাবণ্যের মনে নতুন এক অনুভূতির জন্ম হলো।\n\nঅমিতের সঙ্গে তার সম্পর্ক কেবল আকর্ষণের ছিল না—তাদের মধ্যে ছিল সাহিত্য, দর্শন, জীবন ও প্রেম নিয়ে দীর্ঘ আলোচনা।\n\n৫. আলাপের আরম্ভ\n\nঅমিত ও লাবণ্যের আলাপ ক্রমশ গভীর হতে থাকে।\n\nএকদিন কথায় কথায় রবীন্দ্রনাথের কবিতা প্রসঙ্গ আসে। অমিত মজা করে রবীন্দ্রনাথের কবিতা নিয়ে আপত্তি তোলে এবং নিজের পছন্দের কবির কথা বলে।\n\nলাবণ্য তার কথা শুনতে থাকে।\n\nতর্ক করতে করতে কখন যে তাদের মধ্যে দূরত্ব কমে গেছে, তারা নিজেরাও বুঝতে পারে না।\n\n৬. নুতন পরিচয়\n\nএকসময় অমিত নিজের লেখা কবিতা আবৃত্তি করে।\n\nকবিতা শেষ হওয়ার পর অমিত লাবণ্যের হাত ধরে। লাবণ্য হাত সরিয়ে নেয় না।\n\nসেই মুহূর্তে দুজনের সম্পর্কের প্রকৃতি বদলে যায়।\n\nতাদের কথার তর্ক আর কেবল তর্ক থাকে না। তার মধ্যে মিশে যায় প্রেম।\n\n৭. ঘটকালি\n\nযোগমায়া—যিনি লাবণ্যের আশ্রয়দাত্রী—অমিত ও লাবণ্যের সম্পর্ক বুঝতে পারেন।\n\nঅমিতের সঙ্গে লাবণ্যের বিয়ের সম্ভাবনা তৈরি হয়।\n\nদুজনেই একে অপরকে ভালোবাসে। কিন্তু তাদের প্রেমের মধ্যে এমন কিছু আছে যা সাধারণ সংসারী জীবনের নিয়মের সঙ্গে পুরোপুরি মেলে না।\n\nতারা প্রেমকে শুধু দাম্পত্যের মধ্যে সীমাবদ্ধ করতে চায় না।\n\n৮. লাবণ্য-তর্ক\n\nলাবণ্য নিজের মনকে প্রশ্ন করতে থাকে।\n\nসে অমিতকে ভালোবাসে, কিন্তু একই সঙ্গে সে জানে—অমিতের সঙ্গে সংসার করলে তাদের সেই স্বাধীন সম্পর্কটি হয়তো বদলে যাবে।\n\nঅমিতও একই সমস্যার মুখোমুখি হয়।\n\nতাদের প্রেম যত গভীর হয়, ততই তারা বুঝতে পারে—ভালোবাসা এবং বিবাহ সবসময় একই জিনিস নয়।\n\n৯. বাসা-বদল\n\nঅমিত ও লাবণ্যের সম্পর্ক আরও ঘনিষ্ঠ হয়।\n\nশিলংয়ের পাহাড়, প্রকৃতি, নির্জনতা এবং তাদের দীর্ঘ আলাপ তাদের প্রেমকে আরও গভীর করে তোলে।\n\nতারা ভবিষ্যৎ নিয়ে ভাবতে শুরু করে।\n\nকিন্তু ভবিষ্যতের পথ সহজ নয়।\n\n১০. দ্বিতীয় সাধনা\n\nঅমিত ও লাবণ্য নিজেদের প্রেমকে নতুনভাবে বুঝতে চেষ্টা করে।\n\nতাদের কাছে প্রেম মানে শুধু কাছে পাওয়া নয়। বরং কখনো কখনো দূরত্বের মধ্যেও একজন আরেকজনকে সম্পূর্ণভাবে অনুভব করা।\n\nতাদের সম্পর্কের মধ্যে তাই এক ধরনের আত্মিক সাধনা তৈরি হয়।\n\n১১. মিলনতত্ত্ব\n\nঅমিত ও লাবণ্য বুঝতে পারে, মানুষের জীবনে কিছু সম্পর্ক থাকে যেগুলোকে সাধারণ নিয়মে বিচার করা যায় না।\n\nতারা একে অপরের প্রতি গভীরভাবে আকৃষ্ট।\n\nকিন্তু তারা এটাও উপলব্ধি করে যে দৈনন্দিন সংসার, অভ্যাস, দায়িত্ব এবং সামাজিক বাস্তবতা সেই প্রেমকে অন্য রূপ দিতে পারে।\n\nতাই তারা তাদের ভালোবাসার প্রকৃতি নিয়ে সিদ্ধান্ত নিতে শুরু করে।\n\n১২. শেষ সন্ধ্যা\n\nতাদের একসঙ্গে কাটানো সময় শেষের দিকে এগিয়ে যায়।\n\nশিলংয়ের পাহাড়ি সন্ধ্যায় তাদের মনে এক অদ্ভুত বিষণ্ণতা।\n\nতারা জানে—এই মুহূর্তগুলো চিরকাল থাকবে না।\n\nঅমিত লাবণ্যকে ভালোবাসে। লাবণ্যও অমিতকে ভালোবাসে।\n\nতবু তাদের সামনে এমন একটি সিদ্ধান্ত দাঁড়িয়ে যায় যা দুজনকেই আলাদা পথে নিয়ে যাবে।\n\n১৩. আশঙ্কা\n\nঅমিতের জীবনে কেতকীর উপস্থিতি আবার সামনে আসে।\n\nকেতকী অমিতের অতীতের সঙ্গে যুক্ত। অমিতের সঙ্গে তার সম্পর্কও একসময় গভীর ছিল।\n\nলাবণ্য বুঝতে পারে, অমিতের জীবনে শুধু সে একা নয়।\n\nএই পরিস্থিতি তাদের সম্পর্ককে আরও জটিল করে তোলে।\n\n১৪. ধূমকেতু\n\nঅমিত ও লাবণ্যের প্রেম যেন জীবনে হঠাৎ এসে পড়া এক ধূমকেতুর মতো।\n\nঅল্প সময়ের মধ্যে তারা একে অপরের জীবনে গভীর ছাপ রেখে যায়।\n\nকিন্তু সেই সম্পর্ককে চিরস্থায়ী সংসারে পরিণত করার পরিবর্তে তারা অন্য সিদ্ধান্তের দিকে এগিয়ে যায়।\n\n১৫. ব্যাঘাত\n\nকেতকী অমিতের সামনে নিজের অনুভূতি প্রকাশ করে।\n\nঅমিতের সঙ্গে তার পুরোনো সম্পর্কের স্মৃতি আবার সামনে আসে।\n\nএকসময় কেতকী নিজের আংটি অমিতের সামনে রেখে চলে যায়। তার চোখে তখন গভীর অভিমান ও কষ্ট।\n\nঅমিত বুঝতে পারে, মানুষের ভালোবাসার সঙ্গে শুধু নিজের ইচ্ছা জড়িয়ে থাকে না—অন্য মানুষের অনুভূতিও তার সঙ্গে জড়িত।\n\n১৬. মুক্তি\n\nঅমিত ও লাবণ্যের পথ শেষ পর্যন্ত আলাদা হয়ে যায়।\n\nলাবণ্যের জীবনে শোভনলাল আবার ফিরে আসে। শোভনলাল লাবণ্যকে বিয়ের প্রস্তাব দেয়।\n\nলাবণ্য তার প্রস্তাব গ্রহণ করে।\n\nঅমিতের জীবনেও কেতকীর সঙ্গে বিবাহের পথ তৈরি হয়।\n\nএকসময় অমিত শিলং ছেড়ে চলে যায়। যে পাহাড়ে লাবণ্যের সঙ্গে তার প্রেমের জন্ম হয়েছিল, সেই শিলং তার কাছে হঠাৎ অর্থহীন ও শূন্য হয়ে ওঠে।\n\n১৭. শেষের কবিতা\n\nঅনেকটা সময় পরে অমিত লাবণ্যের কাছ থেকে একটি চিঠি পায়।\n\nচিঠিতে লাবণ্য জানায়—শোভনলালের সঙ্গে তার বিয়ে হবে।\n\nকিন্তু চিঠিটি শুধু বিয়ের সংবাদ নয়। সেখানে আছে তাদের অতীতের প্রতি গভীর কৃতজ্ঞতা এবং বিদায়।\n\nলাবণ্য জানে, অমিত তার জীবনে এমন একটি স্মৃতি রেখে গেছে যা কখনো মুছে যাবে না।\n\nঅমিতও জানে, লাবণ্যকে সে হারিয়েছে—কিন্তু তাদের ভালোবাসা সম্পূর্ণ অর্থহীন ছিল না।\n\nতারা একে অপরকে পেয়েছিল, ভালোবেসেছিল, তারপর নিজেদের জীবনকে অন্য পথে নিয়ে গেছে।\n\nলাবণ্যের চিঠির শেষের কবিতায় সেই বিদায়ের অনুভূতি ফুটে ওঠে।\n\nতাদের প্রেম সংসারের সাধারণ পরিণতি পায়নি।\n\nকিন্তু সেই অসম্পূর্ণতাই তাদের ভালোবাসাকে স্মৃতিতে অমর করে রাখে।\n\nএভাবেই শেষ হয় অমিত ও লাবণ্যের প্রেমের গল্প—একটি প্রেম, যা মিলনের চেয়ে বিচ্ছেদের মধ্যেই তার পূর্ণতা খুঁজে পায়।\n\nশেষ।','\n',char(10)),1,'published',0,'2026-09-10T04:15:34.942Z','2026-09-10T04:15:34.942Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('b054e781-d08b-4b87-a607-f471177489e0','4603dfa0-d90d-4f27-8850-8cb13502c633','অধ্যায় ৩',replace('## অধ্যায় ৩: কখনো যথেষ্ট হয় না\n\n## Never Enough\n\nমানুষের একটি স্বাভাবিক প্রবণতা হলো—যা আছে তার চেয়ে একটু বেশি পাওয়ার ইচ্ছা। আজ যে পরিমাণ অর্থ আমাদের জন্য যথেষ্ট মনে হয়, কিছুদিন পর হয়তো সেটিই কম মনে হতে পারে।\n\n**সমস্যা তখনই শুরু হয়, যখন “যথেষ্ট” কথাটার কোনো সীমা থাকে না।**\n\n## আরও বেশি পাওয়ার দৌড়\n\nঅর্থ ও সম্পদের ক্ষেত্রে মানুষ সহজেই তুলনার মধ্যে পড়ে যায়। নিজের প্রয়োজন মেটানোর পরও আমরা অন্যের জীবন, সম্পদ ও সাফল্যের দিকে তাকিয়ে নিজেদের অবস্থাকে বিচার করতে শুরু করি।\n\nকেউ একটি ভালো বাড়ি কিনলে আমরা আরও বড় বাড়ি চাইতে পারি। কেউ দামি গাড়ি কিনলে আমাদের নিজের গাড়িটা হঠাৎ সাধারণ মনে হতে পারে।\n\nএভাবে প্রয়োজন ধীরে ধীরে ইচ্ছায়, আর ইচ্ছা প্রতিযোগিতায় পরিণত হয়।\n\n## “যথেষ্ট” বুঝতে শেখা\n\nআর্থিকভাবে সফল হওয়ার একটি গুরুত্বপূর্ণ অংশ হলো—**কখন থামতে হবে তা জানা।**\n\nআরও অর্থ উপার্জনের সুযোগ সবসময় থাকবে। আরও বড় বিনিয়োগ, আরও বেশি লাভ কিংবা আরও বেশি সম্পদের আকাঙ্ক্ষারও শেষ নেই।\n\nকিন্তু প্রতিটি অতিরিক্ত লাভের জন্য যদি আমরা এমন ঝুঁকি নিই, যা আমাদের ইতিমধ্যে অর্জিত সম্পদকে ধ্বংস করে দিতে পারে, তাহলে সেই ঝুঁকি নেওয়ার মূল্য অনেক বেশি হতে পারে।\n\nতাই নিজের জন্য একটি সীমা নির্ধারণ করা জরুরি।\n\n## তুলনা বিপজ্জনক\n\nঅন্যের সঙ্গে নিজের আর্থিক অবস্থার তুলনা করা আমাদের “যথেষ্ট” শব্দটির অর্থ বদলে দিতে পারে।\n\nআপনার যা আছে তা হয়তো আপনার জীবনকে স্বচ্ছন্দ করার জন্য যথেষ্ট। কিন্তু অন্য কারও কাছে আরও বেশি দেখে আপনি মনে করতে পারেন আপনার কাছে কিছুই নেই।\n\n**অন্যের লক্ষ্যকে নিজের লক্ষ্য বানিয়ে ফেললে নিজের আর্থিক স্বাধীনতা হারানোর ঝুঁকি থাকে।**\n\n## সম্পদের চেয়ে স্বাধীনতা\n\nঅর্থের সবচেয়ে বড় সুবিধা শুধু দামি জিনিস কেনার ক্ষমতা নয়। অর্থ আপনাকে নিজের সময়ের ওপর নিয়ন্ত্রণ দিতে পারে।\n\nআপনি কোথায় কাজ করবেন, কখন কাজ করবেন, কোন সুযোগ গ্রহণ করবেন এবং কোন পরিস্থিতি থেকে বেরিয়ে আসবেন—এসব বিষয়ে স্বাধীনতা তৈরি করা অর্থের অন্যতম গুরুত্বপূর্ণ ব্যবহার।\n\nতাই শুধু বেশি অর্থের পেছনে ছুটে নিজের সময়, সম্পর্ক ও মানসিক শান্তি নষ্ট করার কোনো অর্থ নেই।\n\n## কখন থামবেন?\n\nনিজেকে একটি প্রশ্ন করা যেতে পারে:\n\n**“আমার কাছে কতটা হলে যথেষ্ট?”**\n\nএই প্রশ্নের উত্তর প্রত্যেক মানুষের জন্য আলাদা। কিন্তু উত্তরটি না থাকলে আমরা সারাজীবন আরও বেশি পাওয়ার দৌড়ে থাকতে পারি।\n\nযথেষ্ট থাকা মানে উচ্চাকাঙ্ক্ষা ছেড়ে দেওয়া নয়। এর অর্থ হলো—নিজের প্রয়োজন, লক্ষ্য ও সীমা সম্পর্কে পরিষ্কার থাকা।\n\n## অধ্যায়ের মূল শিক্ষা\n\n**যে দৌড়ের শেষ নেই, সেখানে জয়ী হওয়ার পরও আপনি নিজেকে পরাজিত মনে করতে পারেন।**\n\nঅর্থ উপার্জনের পাশাপাশি কখন থামতে হবে, কতটা ঝুঁকি নেওয়া উচিত এবং নিজের জন্য কী “যথেষ্ট”—তা জানা অত্যন্ত গুরুত্বপূর্ণ।\n\n## মূল কথা\n\n> **“যথেষ্ট” বুঝতে না পারলে আরও বেশি পাওয়ার চেষ্টা শেষ পর্যন্ত এমন ঝুঁকির দিকে নিয়ে যেতে পারে, যা আপনার ইতিমধ্যে অর্জিত সবকিছু হারানোর কারণ হতে পারে।**','\n',char(10)),3,'published',0,'2026-09-12T08:12:13.682Z','2026-09-12T08:12:13.682Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('4eab6e10-cea8-4e04-92df-83afd83c241f','4603dfa0-d90d-4f27-8850-8cb13502c633','অধ্যায় ৪',replace('## চক্রবৃদ্ধির জাদু\n\nঅর্থের জগতে বড় পরিবর্তন সবসময় বড় কোনো সিদ্ধান্তের মাধ্যমে আসে না। অনেক সময় **ছোট ছোট লাভ দীর্ঘ সময় ধরে জমতে জমতে বিশাল সম্পদে পরিণত হয়।** এই ধারণাটিই হলো চক্রবৃদ্ধি।\n\n## সময়ের শক্তি\n\nধরুন, আপনি আজ অল্প পরিমাণ অর্থ বিনিয়োগ করলেন। প্রথম দিকে সেই অর্থ থেকে খুব বেশি পরিবর্তন দেখা যাবে না। কিন্তু আপনি যদি সেই বিনিয়োগকে দীর্ঘ সময় ধরে বাড়তে দেন এবং অর্জিত লাভ আবার বিনিয়োগ করেন, তাহলে ধীরে ধীরে বৃদ্ধির গতি বাড়তে থাকে।\n\nকারণ তখন শুধু আপনার মূল অর্থই লাভ তৈরি করছে না—**আগের লাভও নতুন লাভ তৈরি করছে।**\n\nএটাই চক্রবৃদ্ধির শক্তি।\n\n## বড় লাভের চেয়ে দীর্ঘ সময়\n\nঅনেকেই বিনিয়োগে দ্রুত অনেক বেশি লাভ করতে চান। কিন্তু দীর্ঘমেয়াদে সম্পদ তৈরির ক্ষেত্রে সবচেয়ে গুরুত্বপূর্ণ বিষয়গুলোর একটি হলো **সময়**।\n\nএকটি বিনিয়োগ অল্প সময়ে অসাধারণ ফল না দিলেও, দীর্ঘ সময় ধরে চলতে থাকলে তার ফল অনেক বড় হতে পারে।\n\nতাই সম্পদ তৈরির ক্ষেত্রে শুধু “কত বেশি লাভ হবে?” এই প্রশ্ন নয়, বরং “কতদিন ধরে এই অর্থকে বাড়তে দেওয়া যাবে?”—এই প্রশ্নটিও গুরুত্বপূর্ণ।\n\n## ধৈর্য কেন গুরুত্বপূর্ণ\n\nচক্রবৃদ্ধির শুরুটা সাধারণত খুব আকর্ষণীয় নয়। প্রথম কয়েক বছরে আপনার বিনিয়োগের বৃদ্ধি খুব ধীর মনে হতে পারে।\n\nএই সময় অনেক মানুষ ধৈর্য হারিয়ে ফেলেন। তারা দ্রুত ফলাফল চান এবং এক বিনিয়োগ থেকে অন্য বিনিয়োগে চলে যান।\n\nকিন্তু **চক্রবৃদ্ধির সবচেয়ে বড় শক্তি প্রকাশ পেতে সময় লাগে।**\n\nযে ব্যক্তি দীর্ঘ সময় ধরে ধারাবাহিকভাবে বিনিয়োগ করে যেতে পারে, সে অনেক সময় এমন ফল পেতে পারে যা শুরুতে কল্পনাও করা কঠিন।\n\n## ধারাবাহিকতার মূল্য\n\nসম্পদ তৈরিতে প্রতিদিন অসাধারণ সিদ্ধান্ত নেওয়ার চেয়ে অনেক সময় **দীর্ঘদিন ধরে ভালো সিদ্ধান্ত ধরে রাখা বেশি গুরুত্বপূর্ণ।**\n\nআপনি যদি নিয়মিত সঞ্চয় করেন, অপ্রয়োজনীয় ঝুঁকি এড়িয়ে চলেন এবং আপনার অর্থকে দীর্ঘ সময় ধরে কাজ করার সুযোগ দেন, তাহলে সময় আপনার পক্ষে কাজ করতে পারে।\n\n## চক্রবৃদ্ধির আসল শিক্ষা\n\nচক্রবৃদ্ধি আমাদের শেখায় যে **সময় এবং ধারাবাহিকতা অনেক শক্তিশালী।**\n\nআপনাকে প্রতিদিন বড় কিছু করতে হবে না। বরং ছোট একটি ভালো সিদ্ধান্তকে দীর্ঘ সময় ধরে চালিয়ে যাওয়াই অনেক বড় ফল তৈরি করতে পারে।\n\n### মূল কথা\n\n> **সম্পদ তৈরির ক্ষেত্রে সবচেয়ে শক্তিশালী বিষয়গুলোর একটি হলো সময়। ছোট লাভ যখন দীর্ঘ সময় ধরে আবার বিনিয়োগ হয়, তখন সেই লাভের ওপরও লাভ তৈরি হতে থাকে—এটাই চক্রবৃদ্ধির জাদু।**','\n',char(10)),4,'published',0,'2026-09-12T08:19:24.336Z','2026-09-12T08:19:24.336Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('2be1a306-5f3b-4975-b7cf-e3843d9bac60','4603dfa0-d90d-4f27-8850-8cb13502c633','অধ্যায় ৫',replace('## ধনী হওয়া বনাম ধনী থাকা\n\n## Getting Wealthy vs. Staying Wealthy\n\nঅনেক মানুষ মনে করে, প্রচুর অর্থ উপার্জন করতে পারলেই আর্থিকভাবে সফল হওয়া যায়। কিন্তু **ধনী হওয়া এবং ধনী অবস্থায় টিকে থাকা—এই দুটি সম্পূর্ণ ভিন্ন বিষয়।**\n\nএকজন মানুষ দ্রুত অনেক টাকা উপার্জন করতে পারেন। কিন্তু সেই অর্থ ধরে রাখা, সঠিকভাবে পরিচালনা করা এবং দীর্ঘ সময় ধরে সম্পদ বাড়িয়ে নেওয়ার জন্য ভিন্ন ধরনের মানসিকতা দরকার।\n\n## ধনী হওয়ার জন্য কী দরকার?\n\nসম্পদ তৈরি করার সময় সাহস, ঝুঁকি নেওয়ার ক্ষমতা এবং আশাবাদ গুরুত্বপূর্ণ হতে পারে।\n\nনতুন ব্যবসা শুরু করা, বিনিয়োগ করা কিংবা নতুন সুযোগ গ্রহণ করার জন্য ভবিষ্যৎ সম্পর্কে আশাবাদী হতে হয়।\n\nকিন্তু শুধু বড় ঝুঁকি নিলেই সম্পদ তৈরি হয় না। কারণ **বড় লাভের সুযোগের সঙ্গে বড় ক্ষতির সম্ভাবনাও থাকে।**\n\n## ধনী থাকা আরও কঠিন\n\nআপনি একবার অর্থ উপার্জন করলেই কাজ শেষ হয়ে যায় না।\n\nসম্পদ ধরে রাখতে হলে এমন সিদ্ধান্ত নিতে হয়, যাতে খারাপ সময় এলেও আপনি পুরোপুরি ভেঙে না পড়েন।\n\nএখানে সবচেয়ে গুরুত্বপূর্ণ বিষয়গুলোর একটি হলো **টিকে থাকার ক্ষমতা।**\n\nআপনার বিনিয়োগে সাময়িক ক্ষতি হতে পারে। ব্যবসায় খারাপ সময় আসতে পারে। আয় কমে যেতে পারে। বাজারে বড় পতন হতে পারে।\n\nএই পরিস্থিতিগুলো পার হয়ে যাওয়ার মতো আর্থিক নিরাপত্তা না থাকলে আগের অর্জিত সম্পদ হারিয়ে যেতে পারে।\n\n## নিরাপত্তার জন্য অতিরিক্ত রাখা\n\nসম্পদ ধরে রাখার ক্ষেত্রে সব অর্থ সর্বোচ্চ লাভের জন্য বিনিয়োগ করে ফেলা সবসময় বুদ্ধিমানের কাজ নয়।\n\nকিছু অর্থ এমনভাবে রাখা দরকার, যা আপনাকে অপ্রত্যাশিত পরিস্থিতিতে সাহায্য করবে।\n\n**ভবিষ্যৎ সম্পর্কে অনিশ্চয়তা মেনে নিয়ে কিছুটা নিরাপত্তার ব্যবস্থা রাখা সম্পদ ধরে রাখার গুরুত্বপূর্ণ অংশ।**\n\n## ভুলের সুযোগ রাখা\n\nজীবনে সব সিদ্ধান্ত সঠিক হবে—এমন আশা করা বাস্তবসম্মত নয়।\n\nকিছু বিনিয়োগ ব্যর্থ হতে পারে। কিছু সুযোগ কাজে নাও আসতে পারে। কখনো কখনো আপনার পরিকল্পনাও ভুল হতে পারে।\n\nতাই এমন আর্থিক পরিকল্পনা করা ভালো, যেখানে কিছু ভুল বা খারাপ পরিস্থিতি সামলানোর সুযোগ থাকে।\n\n**একটি ভুল যেন আপনার পুরো আর্থিক ভবিষ্যৎ ধ্বংস করে দিতে না পারে।**\n\n## দীর্ঘমেয়াদে টিকে থাকা\n\nসম্পদ তৈরিতে অনেক সময় একটি বড় সাফল্য গুরুত্বপূর্ণ হতে পারে। কিন্তু সম্পদ ধরে রাখার ক্ষেত্রে ধারাবাহিকতা আরও গুরুত্বপূর্ণ।\n\nআপনার লক্ষ্য শুধু একবার বড় লাভ করা নয়; বরং এমন অবস্থায় থাকা, যাতে আপনি বহু বছর ধরে আপনার অর্থকে বাড়তে দিতে পারেন।\n\n### অধ্যায়ের মূল শিক্ষা\n\n**ধনী হওয়ার জন্য ঝুঁকি নেওয়া দরকার হতে পারে, কিন্তু ধনী থাকার জন্য ঝুঁকি নিয়ন্ত্রণ করা আরও গুরুত্বপূর্ণ।**\n\nসম্পদ তৈরি করার পাশাপাশি সেটিকে রক্ষা করার ব্যবস্থা থাকতে হবে। কারণ আর্থিক জীবনে টিকে থাকাই দীর্ঘমেয়াদে সবচেয়ে গুরুত্বপূর্ণ বিষয়গুলোর একটি।\n\n## মূল কথা\n\n> **ধনী হওয়া একটি ঘটনা হতে পারে, কিন্তু ধনী থাকা একটি দীর্ঘমেয়াদি প্রক্রিয়া। সম্পদ তৈরি করার মতোই সেটিকে রক্ষা করা এবং খারাপ সময়ে টিকে থাকা গুরুত্বপূর্ণ।**','\n',char(10)),5,'published',0,'2026-09-12T08:21:13.039Z','2026-09-12T08:21:13.039Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('50cf4f85-93f1-44b1-9d31-785b7fc3df15','4603dfa0-d90d-4f27-8850-8cb13502c633','অধ্যায় ৬',replace('# লেজের ঘটনা—জয়ীদের কয়েকটি জয়ই সবকিছু নির্ধারণ করে\n\n## Tails, You Win\n\nবিনিয়োগ ও ব্যবসায় সাফল্য অনেক সময় আমরা যেভাবে কল্পনা করি, সেভাবে ধারাবাহিকভাবে আসে না। বরং অনেকগুলো সাধারণ ফলাফলের মধ্যে **কয়েকটি অসাধারণ সাফল্যই মোট ফলাফলকে বড় করে তুলতে পারে।**\n\nএটিই এই অধ্যায়ের গুরুত্বপূর্ণ ধারণা।\n\n## কয়েকটি বড় সাফল্যের শক্তি\n\nধরুন, একজন বিনিয়োগকারী অনেকগুলো বিনিয়োগ করলেন। তার বেশ কিছু বিনিয়োগ খুব ভালো ফল দিল না। কয়েকটিতে ক্ষতিও হলো।\n\nকিন্তু এর মধ্যে একটি বা দুটি বিনিয়োগ অসাধারণভাবে সফল হলো।\n\nসেই কয়েকটি বড় সাফল্য হয়তো আগের অনেক ব্যর্থতা ও ছোট লাভের ক্ষতি পুষিয়ে দিতে পারে।\n\n**অর্থাৎ, প্রতিটি সিদ্ধান্ত সফল হওয়া জরুরি নয়।**\n\n## সব বিনিয়োগ সমান নয়\n\nবিনিয়োগের ফলাফল অনেক সময় অসমভাবে ভাগ হয়ে থাকে।\n\nঅনেক ছোট ফলাফলের তুলনায় একটি বিশাল ফলাফল পুরো চিত্র বদলে দিতে পারে।\n\nএই কারণে সফল বিনিয়োগকারীরাও সব সময় সঠিক হন না। তারা ভুল করতে পারেন, খারাপ বিনিয়োগ করতে পারেন এবং কিছু অর্থ হারাতে পারেন।\n\nতবুও তারা সফল হতে পারেন, কারণ কয়েকটি বড় সাফল্য তাদের সামগ্রিক ফলাফলকে অনেক দূর এগিয়ে দেয়।\n\n## ব্যর্থতা মানেই শেষ নয়\n\nএকটি বিনিয়োগ খারাপ হয়েছে মানেই পুরো পরিকল্পনা ব্যর্থ—এমনটা ভাবা উচিত নয়।\n\nযদি আপনার আর্থিক পরিকল্পনা এমন হয় যে কয়েকটি ভুলের পরও আপনি টিকে থাকতে পারেন, তাহলে ভবিষ্যতের বড় সুযোগগুলো গ্রহণ করার সুযোগ আপনার থাকবে।\n\n**টিকে থাকা গুরুত্বপূর্ণ, কারণ আপনি জানেন না কোন সুযোগটি আপনার সবচেয়ে বড় সাফল্যে পরিণত হবে।**\n\n## দীর্ঘমেয়াদি চিন্তা\n\nকোনো ব্যবসা বা বিনিয়োগের প্রতিটি বছর একই রকম যাবে না।\n\nকখনো ভালো সময় আসবে, কখনো খারাপ সময়। কখনো অনেকগুলো ছোট ব্যর্থতা আসতে পারে, আবার হঠাৎ একটি বড় সাফল্য পুরো ফলাফল বদলে দিতে পারে।\n\nতাই স্বল্পমেয়াদি ফলাফল দেখে হতাশ না হয়ে দীর্ঘমেয়াদি ফলাফলের দিকে তাকানো গুরুত্বপূর্ণ।\n\n## সাফল্যের আসল রহস্য\n\nসফল হতে হলে প্রতিটি সিদ্ধান্তে নিখুঁত হওয়ার প্রয়োজন নেই।\n\nবরং এমন একটি ব্যবস্থা তৈরি করা দরকার, যেখানে **ভুল করার পরও আপনি টিকে থাকতে পারেন এবং বড় সুযোগ এলে সেটি কাজে লাগাতে পারেন।**\n\nকারণ ভবিষ্যতের সবচেয়ে গুরুত্বপূর্ণ সাফল্যটি কোনটি হবে, তা আগে থেকে জানা সম্ভব নয়।\n\n### অধ্যায়ের মূল শিক্ষা\n\n**জীবন, ব্যবসা ও বিনিয়োগে কয়েকটি বড় সাফল্য অনেকগুলো সাধারণ ফলাফলকে ছাপিয়ে যেতে পারে।**\n\nতাই প্রতিটি সিদ্ধান্ত সফল করার চেষ্টা করার পাশাপাশি এমনভাবে চলা উচিত, যাতে ব্যর্থতার পরও আপনি খেলায় টিকে থাকতে পারেন।\n\n## মূল কথা\n\n> **সাফল্যের জন্য প্রতিটি সিদ্ধান্ত সঠিক হওয়া জরুরি নয়। কয়েকটি বড় সাফল্য অনেকগুলো ছোট ব্যর্থতার চেয়েও বেশি গুরুত্বপূর্ণ হয়ে উঠতে পারে।**','\n',char(10)),6,'published',0,'2026-09-12T08:21:57.248Z','2026-09-12T08:21:57.248Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('0ef229c9-3b3e-4bec-8aa2-5609b8252393','d878bb53-dd8d-4818-b498-56f3c884ef3f','মির্জা গালিবের বিখ্যাত উক্তি : ৪০ টি বিখ্যাত উক্তি',replace('১.ধর্মকে বাদ দিয়ে নৈতিক হওয়া সম্ভব নয়\n\n২.পৃথিবীর সব চেয়ে বেশি মিথ্যা বলা হয় ধর্মগ্রন্থ ছুঁয়ে,\nযেটা আদালতে।\nআর সব চেয়ে বেশি সত্য বলা হয় মদ ছুঁয়ে,যেটা পানশালায়।\n\n৩.এই প্রেম গালিবকে নিষ্কর্মা করে দিলো, নয়তো আমিও ছিলাম খুব কাজের মানুষ।\n\n৪.সব সম্পর্ক ছিন্ন করো না, বন্ধু;\nআর যদি কিচ্ছু না থাকে\nতো শত্রুতাই থাক।\n\n৫.অনুকম্পা হলে ডেকে নিও আমায়,\nআমি তো অতীতকাল নই যে ফিরে আসতে পারবো না।\n\n৬.দুনিয়ার এই ভয়ানক উজাড় মজলিসে\nপ্রদীপের মতো আমি প্রেমের শিখাকেই\nআমার সর্বস্ব জ্ঞান করলাম।\n\n৭.আমি কথা বলার শক্তি হারিয়ে ফেলেছি, এদিকে প্রিয় বলে, সে কথা না বললে কি করে বুঝবো তার মনের কথা?\n\n৮.আমি একবারই দুঃসাহস দেখাবো , যখন লোকেরা হেঁটে চলবে আর আমি (মারা যাবার পরে) লোকেদের কাঁধে চাপবো।\n\n৯.এখন অনেক রাত।\nচারদিকে অন্ধকার;\nকোথাও কেউ নেই।\nচলো গালিব! তার বাড়ির দেয়ালে চুমু দিয়ে আসো।\n\n১০.আমার সামনে পৃথিবীটা যেন বাচ্চাদের খেলার মাঠ, প্রতিটা রাত্রি আর দিনে কেবল তামাশাই ঘটে যাচ্ছে।\n\n১১.আমি এখন সেইখানে আছি, যেখান থেকে আমি নিজের খবরই আর পাই না।\n\n১২.তোমার দরজার সামনেই ঘর বানিয়ে নিয়েছি আমি, এবারও কি বলবে আমার ঘরের ঠিকানা জানোনা তুমি।\n\n১৩.নিজের জীবন যখন এমনই বিবর্ণ, গালিব,\nকী করে যে ভাবি, একদা আমাতেই ছিল স্রষ্টার বাস?\n\n১৪.কিছু এমন ভাবে আমার জীবনকে সহজ করে নিয়েছি ,\nকারো কাছে ক্ষমা চেয়ে নিয়েছি , আবার কাউকে ক্ষমা করে দিয়েছি।\n\n১৫.জীবন বড়ই বিচিত্র : সন্ধ্যা কাটেনা অথচ দিব্যি বছর কেটে যাচ্ছে!\n\n১৬.প্রেমে বাঁচা আর মরার মাঝে কোন তফাৎ নেই,\nকেনো তাকে দেখেই বাঁচি? যে অবিশ্বাসীর জন্য মরলাম!\n\n১৭.শরাব ছাড়া আমার হাতের কলম চলছে না। ধোঁয়াহীন আগুন কোথায় তুই?\n\n১৮.সারাজীবন কেবল সেই মানুষটির কথাই মনে রইলো যাকে ভেবেছিলাম ভুলে যাবো আমি।\n\n১৯.লক্ষ্য এক থাকলে সৌন্দর্যও ইবাদতে পরিণত হয়,\nধর্মহীনই শুধু প্রতিদিন তার কিবলা পরিবর্তন করে।\n\n২০.বেশী নুয়ে গেলে পৃথিবী পিঠকে পা’দানি বানিয়ে ফ‍্যালে।\n\n২১.প্রেমে কোনো জোর খাটে না, এ আগুন অনির্বাণ\nএ যায় না লাগানো, তেমনি করা যায় না নির্বাণ।\n\n\n২২.সন্ধ্যার অন্ধকার কতটা ভয়াবহ হতে পারে, তা সেই পাখিকে জিজ্ঞেস করো, যার কোনো ঘর নেই।\n\n২৩.আমি অনেকটা এভাবেই জীবনকে সহজ করে নিয়েছিলাম।\nকারো কাছে ক্ষমা চেয়ে নিয়ে। কাউকে ক্ষমা করে দিয়ে।\n\n২৪.হাতের তালুর রেখায়\nভাগ্য দেখতে যেও না গালিব\nভাগ্য তাদেরও আছে\nযাদের হাত নেই।\n\n\n২৫.আমাকে মদ খেতে দাও\nএই মসজিদে বসেই\nনইলে এমন জায়গা দেখাও\nযেখানে আল্লাহ নেই।\n\n\n২৬.তুমি যেন আমার কাছেই থাকো\nযখন আর কেউ থাকে না।\n\n২৭.হায়রে জুয়া!\nজুয়া খেলি আমি\nজীবনটাই তো জুয়া, রেখেছি বাজি।\nপ্রেম চেয়ে প্রতীক্ষায় ছিলাম\nএলো না সে,এখন চলে যেতে রাজি!\n\n২৮.বন্ধু খুব সাবধানে তুলে রাখো\nনিভে যাওয়া এই প্রদীপটিকে\nঅমাবস্যার গভীর কালো অন্ধকারে\nএই আমাদের আলো দিয়ে ছিলো।\n\n২৯.কেই বা তাকে চিনতে পারে সেই অলঙ্ঘ্য একক একাই\nদুইয়ের ছিটেফোঁটাও থাকলে হয়তো কিছু চেনা হতো।\n\n৩০.কিছুই যখন ছিল না, তো খোদা ছিল।\nকোনো কিছু না হলেও তো খোদা হতো।\nহয়ে যাওয়াই ডুবিয়ে দিল বন্ধু আমায়,\nনাই বা যদি হতাম কী ক্ষতি আর হতো?\n\n৩১.পায়ের এই ফোস্কা দেখে ভয় পেয়ে গিয়েছিলাম। পথ ভর্তি কাঁটা দেখে মন খুশি হয়ে গেল।\n\n৩২.দুনিয়ার এই ভয়ানক উজাড় মজলিসে প্রদীপের মতো আমি প্রেমের শিখাকেই আমার সর্বস্ব জ্ঞান করলাম।\n\n৩৩.যখন দেখেছি তাকে আমি অন্য কারো সাথে, তখনই বুঝেছি খোদা শিরক কেন ক্ষমা করেন না।\n\n৩৪.পৃথিবীতে পোশাকবিহীন এসেছিলে, হে গালিব! একটি কাফনের জন্য এত লম্বা সফর করলে!\n\n৩৫. তুমিও না গালিব খুবই চমৎকার! চাওয়া, পাওয়া, সব রাখলা মানুষের কাছে, আর অভিযোগ করো খোদার কাছে।\n\n৩৬.যিনি আমাকে হিসেব ছাড়া দেন; তাকে কেনো হিসেব করে ডাকবো!\n\n৩৭.মৃত্যু কেন আসে না, গালিব! আর কতদিন বেঁচে থাকার জন্য আফসোস করে যাবো! একদিন মরার জন্য, কতদিন বাঁচতে হয়।\n\n৩৮.জীবন তো এমনি কেটে যেত কেন যে পথে তোমার কথা মনে পড়লো?\n\n৩৯. তসবি রেখে গালিব বলেন, ‘যিনি আমাকে হিসেব ছাড়া দেন তাকে কেন গুনে গুনে ডাকবো?\n\n৪০.হে জীবন, তোমার কাছে প্রচুর অভিযোগ আছে। কিন্তু, তুমি যা দিয়েছো আমাকে, বহুজনের ভাগ্যে সেটাও জোটে না।\n','\n',char(10)),1,'published',0,'2026-09-07T03:13:35.669Z','2026-09-07T03:13:35.669Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('680cb3e5-cfed-42bb-ae65-a64a1418c97d','33db92b5-f86e-4d49-a8d5-8f5057b459b5','গাজা থেকে চিঠি',replace('প্রিয় মুস্তাফা,\n\nএক্ষুনি তোর চিঠি পেলুম, তাতে তুই আমায় লিখেছিস যে স্যাক্রামেন্টোয় তোর ওখানে থাকবার জন্যে যা-যা করা জরুরি ছিল, সব তুই করে ফেলেছিস। আমি এই খবরও পেয়েছি যে ক্যালিফোর্নিয়া বিশ্ববিদ্যালয়ে সিভিল ইনজিনিয়ারিং বিভাগে আমাকে নেয়া হয়েছে। তুই আমার জন্যে যা করেছিস, দোস্ত, সবকিছুর জন্যে তোকে ধন্যবাদ শুকরিয়া।\n\n\nতবে এটা নিশ্চয়ই তোর কাছে একটু অদ্ভুত ঠেকবে যখন আমি এ খবরটা তোকে দেব- আর এ নিয়ে আমার মধ্যে কিন্তু কোনো দ্বিধা নেই, সত্যি-বলতে আমি নিশ্চিত বলতে পারি এখন আমি যেভাবে সবকিছু দেখছি এত স্বচ্ছ প্রাঞ্জলভাবে, এত স্পষ্ট করে, আগে আমি কিছুই দেখিনি। না দোস্ত, আমি আমার মত পালটেছি। আমি তোকে অনুসরণ করে সেই দেশে যাব না, যে দেশ শ্যামল, সজল আর সুশ্রী সুন্দর সব মুখে ভরা’- যেমন তুই লিখেছিস। না, আমি এখানেই থাকব- এবং কোনোদিন এ দেশ ছেড়ে যাব না।\n\nআমি কিন্তু সত্যি বড্ড অস্বস্তিতে আছি, মুস্তাফা – আমাদের জীবন আর কখনোই এক খাতে বয়ে যাবে না। অস্বস্তির কারণ, আমি যেন শুনতে পাচ্ছি তুই আমায় মনে করিয়ে দিচ্ছিস- কী রে, আমরা না কথা দিয়েছিলুম সব সময় এক সঙ্গে থাকব, যেমন আমরা চিরকাল এক সাথে বলে উঠতাম : ‘আমরা বড়লোক হবই! আমাদের অনেক টাকা হবে!’ কিন্তু দোস্ত, কিছুই আর আমার করার নেই। হ্যাঁ, আমার এখনো সেদিনটা মনে পড়ে যেদিন কায়রোর হাওয়াই আড্ডার হলে দাঁড়িয়ে আমি তোর হাত চেপে ধরেছিলুম, তাকিয়েছিলুম ক্ষিপ্ত মোটরটার ঘূর্ণির দিকে। কান-ফাটানো মোটরের আওয়াজে সময়ের মধ্যে সেই মুহূর্তে সবকিছুই ঘুরে যাচ্ছে, আর তুই দাঁড়িয়ে আছিস আমার সামনে, তোর সুগোল মুখখানা স্তব্ধ।\n\nগাজার শাজিয়া মহল্লায় তুই যখন বড় হচ্ছিলি, তখন যেমন ছিল তা থেকে একতিলও বদলায়নি তোর মুখ— শুধু কতগুলি ক্ষীণ ভাঁজ পড়েছে চোখের পাশে। আমরা দু’জনে এক সঙ্গেই বড় হয়েছি, মুস্তাফা পরস্পরকে আমরা পুরোপুরি বুঝি, আর আমরা পরস্পরকে জবানও দিয়েছিলুম যে শেষ অবধি দু’জনে এক সঙ্গেই যাব। কিন্তু …\n\n‘হাওয়াই জাহাজ ছাড়বার আগে আরো পনের মিনিট সময় আছে হাতে। অমনভাবে হাঁ করে আকাশে তাকিয়ে থাকিস না। শোন। পরের বছর তুই কুয়েত যাবি, মাইনে যা পাবি তা থেকে যথেষ্ট টাকা বাঁচাতে পারবি, গাজার মাটি থেকে শেকড় ওপড়াতে তা-ই যথেষ্ট, তারপর ক্যালিফোর্নিয়া গিয়ে নতুন করে শেকড় পুঁতবি। আমরা এক সঙ্গে সব শুরু করেছি, আর এক সঙ্গেই চালিয়ে যেতে হবে আমাদের…’\n\nসেই মুহূর্তে আমি তোর ঠোঁটের দ্রুত নড়াচড়া দেখছিলুম, মুস্তাফা। তোর কথা বলবার ধরনটাই ছিল ও-রকম, দাড়ি-কমা বাদ দিয়ে হড়বড় করে তোড়ে বলে চলা।\n\nকিন্তু আবছাভাবে আমার কেন যেন মনে হচ্ছিল তোর এই পালানোতে তুই পুরোপুরি সুখী নোস। পালাবার তিনটে ভালো কারণ তুই দেখাতে পারিসনি। আমিও সর্বক্ষণ এই আক্ষেপে ভুগেছি, কিন্তু সবচেয়ে স্পষ্ট চিন্তাটা ছিল : এই গাজাকে ছেড়ে রেখে সবাই মিলে পালিয়ে যাই না কেন আমরা? কেন যাই না/ কেন পারি না?\nকেন, তবু আমার মনে হলো এটা যেন কোনো সূচনা। আমার মনে হলো, যে বড় রাস্তাটা ধরে আমি হেঁটে ফিরেছিলুম বাড়ি, সে যেন সাফাদের দিকে ছুটে যাওয়া দীর্ঘ, দীর্ঘ কোনো পথের আরম্ভ। এই গাজায় সবকিছু দপদপ করছে বিষাদে, মনস্তাপে, যা শুধুই কোনো রোদনের মধ্যে আবদ্ধ নয়। যুদ্ধের আহবান এই বিষাদ। তারও বেশি, এ যেন কাটা পা ফিরে পাবার জন্যে একটা প্রচণ্ড নাছোড় দাবি!\n\nগাজার রাস্তায়-রাস্তায় আমি হেঁটে বেড়ালুম, চোখ ধাঁধানো আলোয় ভরা সব রাস্তা। ওরা আমাকে বলেছে- নাদিয়া তার পা হারিয়েছে, যখন সে ঝাঁপিয়ে পড়েছিল তার ছোট-ছোট ভাইবোনদের ওপর, তাদের ঢেকে দিয়েছিল নিজের ছোট্ট শরীরটা দিয়ে, বোমা আর আগুন থেকে তাদের বাঁচাতে, যে-আগুনের হিংস্র থাবা তখন বাড়িটায় পড়েছিল। নাদিয়া নিজেকে বাঁচাতে পারত, সহজেই সে ছুটে পালিয়ে যেতে পারত লম্বা-লম্বা পা ফেলে, রক্ষা করতে পারত তার পা। কিন্তু সে তা করেনি।\n\nকেন?\n\nনা, মুস্তাফা, দোস্ত আমার, আমি স্যাক্রামেন্টো যাব না- আর তাতে আমার কোনো খেদ নেই। না। আর ছেলেবেলায় এক সাথে আমরা যা শুরু করেছিলুম, তা- ও আমরা শেষ করব না। সেই আবছা মতো অনুভূতি যা তুই গাজা ছেড়ে যাবার সময় অনুভব করেছিলি, সেই ছোট্ট বোধটাকে বিশাল হয়ে গড়ে উঠতে দিতে হবে তোর ভেতরে। ছড়িয়ে পড়তে দিতে হবে তাকে, নিজেকে ফিরে পাবার জন্যে হাতড়াতে হবে তোকে, তন্নতন্ন করে তোকে নিজেকে খুঁজতে হবে পরাজয়ের এই ধ্বংসস্তূপে। \nআমি তোর কাছে যাব না, মুস্তাফা। বরং তুই, তুই আমাদের কাছে ফিরে আয়। ফিরে আয়, মুস্তাফা, নাদিয়ার কাটা পা-দু’টি থেকে শিখতে, উরুর ওপর থেকে কাটা, ফিরে আয় জানতে কাকে বলে জীবন, অস্তিত্বের মূল্য কী আর কতটা!\nফিরে আয়, মুস্তাফা, দোস্ত আমার, দোহাই, ফিরে আয়! আমরা সবাই তোর জন্যে উদ্‌গ্রীব, অপেক্ষা করে আছি।','\n',char(10)),1,'published',0,'2026-09-07T04:57:41.513Z','2026-09-07T04:57:41.513Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('a922b028-98ad-41f6-af07-235e97766551','4603dfa0-d90d-4f27-8850-8cb13502c633','অধ্যায় ৭',replace('# স্বাধীনতা\n\n## Freedom\n\nঅনেক মানুষ মনে করে, বেশি টাকা থাকাই আর্থিক সাফল্যের সবচেয়ে বড় প্রমাণ। কিন্তু অর্থের আসল শক্তি শুধু দামি জিনিস কেনার ক্ষমতার মধ্যে নয়। **অর্থের সবচেয়ে মূল্যবান সুবিধাগুলোর একটি হলো নিজের সময়ের ওপর নিয়ন্ত্রণ।**\n\n## নিজের সময়ের মালিক হওয়া\n\nজীবনে আমরা যা চাই, তার অনেক কিছুই আসলে টাকার মাধ্যমে সরাসরি কেনা যায় না। কিন্তু অর্থ আমাদের এমন স্বাধীনতা দিতে পারে, যার মাধ্যমে আমরা নিজের জীবনকে নিজের মতো করে পরিচালনা করার সুযোগ পাই।\n\nকখন কাজ করব, কোথায় কাজ করব, কার সঙ্গে সময় কাটাব এবং কোন কাজটি গ্রহণ করব—এসব বিষয়ে নিজের সিদ্ধান্ত নেওয়ার ক্ষমতা অত্যন্ত মূল্যবান।\n\n**নিজের সময়ের ওপর নিয়ন্ত্রণ মানেই এক ধরনের স্বাধীনতা।**\n\n## টাকা কেন স্বাধীনতা দিতে পারে?\n\nযদি আপনার হাতে পর্যাপ্ত সঞ্চয় থাকে, তাহলে প্রতিটি সিদ্ধান্তের জন্য আপনাকে তাৎক্ষণিক আয়ের ওপর নির্ভর করতে হবে না।\n\nহঠাৎ চাকরি পরিবর্তনের প্রয়োজন হলে কিছু সময় নেওয়া সম্ভব হতে পারে। কোনো সুযোগ গ্রহণ করার জন্য কিছুদিন আয় ছাড়াও চলা সম্ভব হতে পারে।\n\nঅর্থাৎ টাকা শুধু পণ্য বা সেবা কেনার ক্ষমতা দেয় না; এটি **সময় এবং বিকল্প বেছে নেওয়ার সুযোগও তৈরি করে।**\n\n## বেশি অর্থ, বেশি স্বাধীনতা—সবসময় নয়\n\nঅনেক বেশি অর্থ থাকা মানেই যে আপনি স্বাধীন—এমন নয়।\n\nআপনি যদি আরও বেশি অর্থের জন্য এমন জীবন বেছে নেন যেখানে সারাক্ষণ কাজ করতে হয়, নিজের সময়ের ওপর কোনো নিয়ন্ত্রণ থাকে না এবং প্রিয় মানুষদের সঙ্গে সময় কাটানোর সুযোগ কমে যায়, তাহলে সেই অর্থের প্রকৃত মূল্য কোথায়?\n\n**অর্থের উদ্দেশ্য শুধু আরও বেশি অর্থ তৈরি করা নয়; বরং এমন একটি জীবন তৈরি করা, যেখানে আপনি নিজের গুরুত্বপূর্ণ বিষয়গুলোকে সময় দিতে পারেন।**\n\n## নিজের নিয়ন্ত্রণের মূল্য\n\nমানুষ সাধারণত মনে করে সুখের জন্য বড় বাড়ি, দামি গাড়ি বা বিলাসবহুল জীবন দরকার।\n\nকিন্তু অনেক সময় সবচেয়ে মূল্যবান বিষয় হলো—আপনার দিনটি কীভাবে কাটবে, সেটি কিছুটা হলেও নিজের মতো করে ঠিক করার ক্ষমতা।\n\nআপনি যদি নিজের সময় সম্পর্কে সিদ্ধান্ত নিতে পারেন, তাহলে আপনার জীবনের ওপর আপনার নিয়ন্ত্রণ বাড়ে।\n\n## আর্থিক স্বাধীনতা মানে কী?\n\nআর্থিক স্বাধীনতা মানে শুধু এত টাকা থাকা নয় যে আর কখনো কাজ করতে হবে না।\n\nবরং এর অর্থ হলো—**আপনার অর্থনৈতিক পরিস্থিতি যেন আপনাকে প্রতিটি মুহূর্তে বাধ্য হয়ে সিদ্ধান্ত নিতে না হয়।**\n\nআপনার কাছে কিছু সঞ্চয় থাকবে, কিছু নিরাপত্তা থাকবে এবং প্রয়োজন হলে “না” বলার ক্ষমতা থাকবে।\n\n### অধ্যায়ের মূল শিক্ষা\n\n**অর্থের সবচেয়ে বড় সুবিধা হলো এটি আপনাকে নিজের সময়ের ওপর কিছুটা নিয়ন্ত্রণ দিতে পারে।**\n\nদামি জিনিস কেনার আনন্দ সাময়িক হতে পারে, কিন্তু নিজের জীবন ও সময় সম্পর্কে সিদ্ধান্ত নেওয়ার স্বাধীনতার মূল্য দীর্ঘস্থায়ী।\n\n### মূল কথা\n\n> **সম্পদের সবচেয়ে বড় সুবিধা হলো নিজের সময়ের নিয়ন্ত্রণ। টাকা যখন আপনাকে নিজের সময় নিজের মতো ব্যবহার করার স্বাধীনতা দেয়, তখনই তার সবচেয়ে মূল্যবান দিকটি প্রকাশ পায়।**','\n',char(10)),7,'published',0,'2026-09-12T08:23:20.461Z','2026-09-12T08:23:20.461Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('9da12f34-e415-4010-a5be-1430cfb358ab','4603dfa0-d90d-4f27-8850-8cb13502c633','অধ্যায় ৮',replace('# গাড়ির মানুষদের প্যারাডক্স\n\n## The Man in the Car Paradox\n\nআমরা যখন রাস্তায় একটি দামি গাড়ি দেখি, তখন প্রায়ই গাড়িটির মালিক সম্পর্কে কিছু ধারণা তৈরি করি। মনে হতে পারে, তিনি নিশ্চয়ই খুব সফল, ধনী এবং জীবনে অনেক কিছু অর্জন করেছেন।\n\nকিন্তু বাস্তবতা হলো, **আমরা গাড়িটিকে দেখি, গাড়ির মালিকের সম্পদকে নয়।**\n\n## আমরা যা দেখি, সেটাই কি সত্য?\n\nদামি গাড়ি, বড় বাড়ি, সুন্দর পোশাক কিংবা বিলাসবহুল জীবন দেখে আমরা ধরে নিতে পারি যে একজন মানুষ অনেক ধনী।\n\nকিন্তু সেই সম্পদের পেছনে তার কত ঋণ আছে, কত টাকা খরচ হয়েছে বা তার প্রকৃত আর্থিক অবস্থা কী—এসব আমরা জানি না।\n\nএকটি দামি জিনিস একজন মানুষকে ধনী দেখাতে পারে, কিন্তু সেটি তাকে প্রকৃত অর্থে ধনী বানায় না।\n\n## মানুষ আসলে কী চায়?\n\nঅনেক সময় আমরা দামি জিনিস কিনি শুধু নিজের জন্য নয়, অন্য মানুষের দৃষ্টিতে নিজেদের একটি নির্দিষ্ট অবস্থান তৈরি করার জন্য।\n\nএকটি দামি গাড়ি কিনলে আমরা হয়তো চাই অন্যরা আমাদের সফল মনে করুক।\n\nকিন্তু এখানে একটি গুরুত্বপূর্ণ বিষয় আছে—**মানুষ সাধারণত আপনার সম্পদকে যতটা লক্ষ্য করে বলে আপনি ভাবেন, বাস্তবে তারা ততটা লক্ষ্য করে না।**\n\nতারা আপনার গাড়ি দেখে নিজের কথা ভাবতে পারে। আপনার সাফল্য দেখে নিজের জীবনের সঙ্গে তুলনা করতে পারে।\n\n## সম্মান কেনা যায় না\n\nদামি জিনিস দিয়ে অন্যের সম্মান বা প্রশংসা পাওয়ার চেষ্টা অনেক সময় হতাশার কারণ হতে পারে।\n\nআপনি ভাবতে পারেন, “এই গাড়িটি কিনলে মানুষ আমাকে সফল মনে করবে।”\n\nকিন্তু মানুষ হয়তো গাড়িটির দিকে তাকিয়ে নিজের ভবিষ্যতের গাড়ির কথা ভাবছে।\n\nঅর্থাৎ আপনি যে প্রশংসা পাওয়ার জন্য অর্থ ব্যয় করছেন, সেই প্রশংসাটি হয়তো আপনি প্রত্যাশা অনুযায়ী পাচ্ছেনই না।\n\n## সম্পদ এবং প্রদর্শনের পার্থক্য\n\n**ধন-সম্পদ হলো আপনার কাছে যা আছে এবং যা অন্যরা দেখতে পায় না।**\n\nঅন্যদিকে, দামি পোশাক, গাড়ি, বাড়ি বা অন্যান্য বিলাসবহুল জিনিস হলো এমন অর্থ, যা আপনি ইতিমধ্যে খরচ করে ফেলেছেন এবং অন্যরা দেখতে পাচ্ছে।\n\nতাই কাউকে ধনী দেখানো এবং প্রকৃতপক্ষে ধনী হওয়া এক বিষয় নয়।\n\n## প্রকৃত সম্পদ কী?\n\nপ্রকৃত সম্পদের একটি গুরুত্বপূর্ণ অংশ হলো এমন অর্থ, যা আপনি এখনো খরচ করেননি।\n\nসঞ্চয়, বিনিয়োগ এবং ভবিষ্যতের জন্য রাখা অর্থ আপনাকে ভবিষ্যতে সিদ্ধান্ত নেওয়ার সুযোগ দেয়।\n\nআপনি যত বেশি অর্থ শুধু দেখানোর জন্য খরচ করবেন, ভবিষ্যতের জন্য আপনার কাছে তত কম সম্পদ থাকবে।\n\n### অধ্যায়ের মূল শিক্ষা\n\n**দামি জিনিস আপনাকে ধনী দেখাতে পারে, কিন্তু প্রকৃত সম্পদ হলো এমন অর্থ যা আপনি ধরে রেখেছেন এবং ভবিষ্যতের জন্য ব্যবহার করতে পারেন।**\n\nঅন্যের প্রশংসা বা স্বীকৃতি পাওয়ার জন্য অতিরিক্ত অর্থ খরচ করার পরিবর্তে নিজের আর্থিক স্বাধীনতার দিকে মনোযোগ দেওয়া বেশি গুরুত্বপূর্ণ।\n\n## মূল কথা\n\n> **মানুষ আপনার সম্পদ দেখে যতটা মুগ্ধ হবে বলে আপনি ভাবেন, বাস্তবে তারা হয়তো ততটা ভাবেই না। প্রকৃত সম্পদ হলো আপনি যা খরচ করেননি—যা ভবিষ্যতে আপনার স্বাধীনতা তৈরি করতে পারে।**','\n',char(10)),8,'published',0,'2026-09-12T08:24:05.157Z','2026-09-12T08:24:05.157Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('cc3fd766-e210-46e8-95ca-30c386619d9c','e38d44a5-471f-4a34-97c4-379894f45cd9','"একাকীত্বের নীলিমায় পুরুষহৃদয়।"','জীবনের রঙ্গমঞ্চে বহু পুরুষ ভালোবাসার স্বপ্ন বুনে পা রাখতে গিয়ে হোঁচট খায়। তাদের এই অশ্রুসিক্ত ব্যর্থতার কাহিনী কোনো মহাকাব্যের চেয়ে কম নয়, যেখানে প্রতিটি পদক্ষেপে নিহিত থাকে হৃদয়ের গভীর দীর্ঘশ্বাস আর নীরব আর্তনাদ। একাকীত্বের হিমশীতল অন্ধকার গ্রাস করে যখন সেই বহু আকাঙ্ক্ষিত মুহূর্তগুলো ধুলোয় মিশে যায়। তারা তাদের চোখের জলের নোনা সাগরে ভেসে বেড়ায়, যেখানে কোনো কূল-কিনারা নেই। পুরুষদের এই নীরব কান্না কেউ দেখতে পায় না, কেউ শোনে না। তাদের বুকে জমে থাকে না বলা কষ্টের দীর্ঘ পাহাড়। প্রেমে প্রতারিত হয়ে তারা নতুন করে গড়তে চায় এক অন্য জীবন, কিন্তু স্মৃতিগুলো তাদের তাড়া করে ফেরে প্রতি পদক্ষেপে। যেন এক অন্ধকার গুহায় আটকে থাকা এক বন্দী। এই যন্ত্রণার গভীরতা কেবল ভুক্তভোগীই জানে।',1,'published',0,'2026-09-12T12:41:47.595Z','2026-09-12T12:41:47.595Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('d0df634d-e825-46c9-adf3-e7cd7c4ceece','86682182-fafa-49a1-95a4-92dc4fe371c7','পর্ব নাম্বার - 4',replace('উত্তরের পাহাড়ি মফস্বল শহরটায় রোদ আর মেঘের অদ্ভুত লুকোচুরি। চারপাশের পাইন আর ওকের বন যখন বাতাসে মৃদু শব্দ তোলে, অরুণাভের কাঠের ঘরের বারান্দায় বসে থাকে নির্জনতা।\n​শহরের পাট চুকিয়ে অরুণাভ এখানে এসে উঠেছে মাসখানেক হলো। সকাল থেকে দুপুর পর্যন্ত সে স্থানীয় এক পাঠাগারে কাজ করে, আর বিকেল নামলে নিজের ঘরের কাঠের টেবিলে বসে উপন্যাসের পাতায় ফুটিয়ে তোলে তার আর তিন্নির ফেলে আসা মুহূর্তগুলো। তার প্রতিটি অনুচ্ছেদে জড়িয়ে থাকে এক জোড়া চঞ্চল চোখের চাহনি আর পড়ন্ত বিকেলের বিষাদ।\n​পাহাড়ে তখন হালকা শীত নেমেছে। প্রতিদিন গোধূলিলগ্নে অরুণাভ কাঠের বারান্দায় দাঁড়িয়ে নিচে নেমে যাওয়া সরু সর্পিল রাস্তাটার দিকে অপলক দৃষ্টিতে তাকিয়ে থাকে। সে জানে, এই পথটা অসম্ভব কঠিন। বাবার কড়া পাহারা আর সামাজিক প্রাচীর ভেঙে একজন মেয়ের পক্ষে এভাবে একা চলে আসা প্রায় অলীক স্বপ্নের মতো। তবুও মানুষের বুকের ভেতর যে অদ্ভুত আশার চারা বেঁচে থাকে, তা যুক্তি মানতে চায় না।\n​সেদিন ছিল পূর্ণিমা। বিকেলের রোদ যখন ধীরে ধীরে মিলিয়ে গিয়ে পাহাড়ি উপত্যকায় নীলাভ চাঁদের আলো ছড়িয়ে পড়তে শুরু করল, ঠিক তখনই দূর থেকে কাঁচা রাস্তায় এক জোড়া গাড়ির চাকার শব্দ শোনা গেল।\n​মফস্বলের পাহাড়ি রাস্তায় সাধারণত সন্ধ্যার পর গাড়ি চলে না। অরুণাভ চমকে উঠে কাঠের রেলিং ধরে সোজা হয়ে দাঁড়াল। একটি পুরোনো ট্যাক্সি তার ছোট কাঠের কুটিরের গেটের মুখে এসে থামল।\n​গাড়ির দরজা খুলে ধীরপায়ে নেমে এল এক তরুণী। পরনে হালকা নীল সুতির চাদর, হাতে সামান্য একটা কাপড়ের ব্যাগ, আর ধুলোবালি মাখা মুখটিতে ক্লান্তি থাকলেও চোখে জ্বলজ্বল করছে অদম্য এক জেদ।\n​অরুণাভ যেন নিজের চোখকে বিশ্বাস করতে পারছিল না। তার পা দুটো মাটিতে জমে গেছে।\n​গেটের শিকল খুলে তিন্নি উঠোনে পা রাখল। চাদরের নিচ থেকে সে বের করল সেই বিবর্ণ হয়ে যাওয়া কাগজের টুকরোটি, যা ক্যাফের টেবিলে অরুণাভ রেখে এসেছিল। বাতাসে তিন্নির এলোমেলো চুলগুলো উড়ছিল।\n​"বাবার আভিজাত্য আর সম্পদের খাঁচা আমি ভেঙে এসেছি, অরুণাভ," তিন্নির গলা আবেগে কাঁপছিল, কিন্তু তার দৃষ্টি ছিল দ্বিধাহীন। "বাবাকে চিঠি দিয়ে জানিয়ে এসেছি—যে জীবনে আত্মসম্মান আর ভালোবাসা নেই, সে জীবন আমি মেনে নেব না। তুমি বলেছিলে না, নিজের অধিকারে আসতে পারলে তবেই যেন আসি? আমি এসেছি।"\n​অরুণাভ দ্রুত পায়ে সিঁড়ি ভেঙে নিচে নেমে এল। চাঁদের মায়াবী আলো আর কুয়াশার চাদরে ঢাকা সেই রাতে দুটো হারিয়ে যাওয়া হৃদয় একে অপরের খুব কাছাকাছি এসে দাঁড়াল।\n​অরুণাভ তিন্নির হাত দুটো নিজের উষ্ণ হাতের মুঠোয় তুলে নিল। যে মানুষটি সচরাচর নিজের অনুভূতি প্রকাশ করতে ভয় পেত, তার চোখ দিয়ে আজ নীরবে গড়িয়ে পড়ল কৃতজ্ঞতার জল।','\n',char(10)),4,'published',0,'2026-10-05T15:42:29.347Z','2026-10-05T15:42:29.347Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('f9d7fc74-63ee-4385-8716-7cf9d295327b','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 7',replace('হেমলতা তীক্ষ্ণ দৃষ্টিতে দুই মেয়েকে দেখছেন। টিনের গায়ে তৈরি ছিদ্র তিনটের দিকে চোখ রেখে প্রশ্ন করলেন, ‘শুটিং দেখছিলি?’\n\nপদ্মজা বাধ্যের মতো মাথা ঝাঁকায়। হেমলতা চোখ দুটি হঠাৎ শীতল হয়ে এলো।\n\nতিনি চৌকিতে বসে প্রশ্ন ছুঁড়লেন, ‘ছিদ্রের বুদ্ধি পূর্ণার?\n\nপ্রশ্নটা শুনে পূর্ণার গলা শুকিয়ে যায়। এক ফোঁটা পানি দরকার, নয়তো দম বেরিয়ে যাবে। পদ্মজা চকিতে চোখ তুলে তাকাল। অসহায় কণ্ঠে বলল, ‘আম্মা, আর হবে না। পূর্ণাকে কিছু বলো না। ওর দোষ নেই। আমি…’\n\nহেমলতা পদ্মজাকে কথা শেষ করতে দিলেন না। প্রেমাকে ডেকে জিজ্ঞাসা করলেন, ‘প্রেমা, তোর আব্বা কোথায়?’\n\n‘উঠানে আম্মা।’\n\n‘গিয়ে বল, আমি ডাকছি।’\n\nপ্রেমা একছুটে গিয়ে আবার একছুটে ফিরে এলো। হেমলতা বারান্দা পেরিয়ে চুলার কাছে গিয়ে বসেন। তখন মোর্শেদ এসে জানতে চাইলেন, ‘কী হইছে? ডাক ক্যারে?’\n\n‘মেয়েদের চৌকির পাশে একটা জানালা করে দাও। মুরগির খোপের কাছে কাঠ আছে।’\n\n‘কেন?’\n\n‘আমি চেয়েছি তাই, না পারলে না করো; অন্য কাউকে ডাকব।’\n\n‘ত্যাড়া কথা কওন ছাড়ো।’\n\n‘তোমার সঙ্গে ভালো করে কথা বলতে ভালো লাগে না।’\n\n‘লাগব ক্যারে? তোমার তো আমারে পছন্দ না। তোমার পছন্দ বিলাই চোখা ব্যাটা ছ্যাড়ারে।’\n\n‘অহেতুক কথা বোলো না। মাসের পর মাস কোথায় থাকো, তা আমার অজানা নয়। রোগে ধরলেই লতার কথা মনে পড়ে।’\n\nমোর্শেদ মিনিটখানেক রাগ নিয়ে তাকিয়ে রইলেন।\n\n.\n\nমোর্শেদ ঘণ্টাখানেক সময় নিয়ে দুই ফুট উচ্চতার একটি জানালা তৈরি করে দিলেন। পদ্মজা-পূর্ণা হতবাক, সেই সঙ্গে খুশিও। হেমলতা জানালায় ছোটো পর্দা টানিয়ে দিলেন। রুম থেকে বাইরের দৃশ্য দেখা যায়, কিন্তু জানালার ওপাশে কে আছে তা বাহির থেকে বোঝা যায় না।\n\nসন্ধ্যায় শুটিং শুরু হলো। পদ্মজা-পূর্ণা-প্রেমা চৌকিতে বসল চিড়া নিয়ে তাদের চোখেমুখে খুশির ঝিলিক। হেমলতা মৃদু হাসলেন। বড়ো মেয়ে দুটো কখনো মুখ ফুটে শখ-আহ্লাদের কথা বলে না। না বলা সত্ত্বেও অনেকবার তিনি দুই বোনের ইচ্ছে পূরণ করেছেন। আর কিছু ইচ্ছে বুঝতে পারলেও পূরণের সামর্থ্য হয়নি তার। যতটুকু পারেন ততটুকুই করেন।\n\nহেমলতা ঘরের বাইরে যেতেই পূর্ণা বলল, ‘আমাদের মায়ের মতো সেরা মা আর কেউ না। তাই না আপা?’\n\n‘মায়ের মতো কেউ হয় না। সবার কাছে সবার মা সেরা। আমাদের মা আমাদের কাছে সেরা। লাবণ্যর মা লাবণ্যর কাছে সেরা। মনির মা মনির কাছে সেরা।’\n\n‘ওরা বলেছে?’\n\n‘দূর বোকা! এসব বলতে হয় না।’\n\n‘না, আমাদের আম্মাই সবচেয়ে ভালো মা। এমন মা আর একটাও নেই।’\n\nহেমলতার কর্ণকুহরে প্রতিটি কথা আসে। পূর্ণা সবার অনুভূতি অনুভব করতে জানে না। পদ্মজা জানে।\n\nপদ্মজা হেসে বলল, ‘আমাদের আম্মা সত্যি সেরা। আলাদা।’\n\nপূর্ণা জানালার বাইরে চোখ রেখে প্রশ্ন করল, ‘আপা, চিত্রা দিদিকে কেমন লাগে?’\n\nপদ্মজা চিত্রার দিকে তাকাল। ছাইরঙা শাড়ি পরা, হাতে কালো রঙের ঘড়ি। ফুলহাতা ব্লাউজ; শালীন, তবে সর্বাঙ্গে আধুনিকতার ছোঁয়া। নাকে সাদা পাথরের নাকফুল, লম্বা চুল বেণি করে রেখেছে; মুখে খুব মায়া। স্নিগ্ধ একটা মুখ, যেন শরতের শুভ্র এক টুকরো মেঘ। পদ্মজা বলল, ‘আমার দেখা দ্বিতীয় সুন্দর মেয়েমানুষ চিত্ৰা দিদি।’\n\nপূর্ণা আগ্রহ নিয়ে জানতে চাইল, ‘প্রথম কে?’\n\nপদ্মজা কণ্ঠ খাদে নামিয়ে মোহময় কণ্ঠে বলল, ‘আমাদের আম্মা।’\n\nসঙ্গে সঙ্গে হেমলতার বুক শীতল, কোমল অনুভূতিতে ছেয়ে গেল। পদ্মজা এত সুন্দর করে ‘আমাদের আম্মা’ বলেছে! হেমলতা প্রথম…এই প্রথম শুনলেন, তিনি সুন্দর! ভূবন মোহিনী রূপসীর মুখে শুনলেন। এই আনন্দ কোথায় রাখবেন? কেন ছেলেমানুষি অনুভূতিতে তলিয়ে যাচ্ছেন তিনি! প্ৰেমা অবাক স্বরে বলল, ‘আম্মা তো কালো। চিত্রা দিদির চেয়ে সুন্দর কীভাবে?’\n\n‘এভাবে বলছিস কেন প্রেমা? তুই ফরসা হয়ে গেছিস বলে কালোকে ভালো মনে হয় না?’ পূর্ণা গমগম করে উঠল। বোনের কথা শুনে ভয় পেল প্ৰেমা।\n\nপদ্মজা বলল, ‘বকছিস কেন? প্রেমা কত ছোটো। ও কী সুন্দরের গভীরতা বুঝে? ও খালি চোখে কালো-সাদার তফাৎ দেখে।’\n\n‘সুন্দরের গভীরতা তো আমিও বুঝি না।’\n\nপূর্ণার কণ্ঠ ভারী নিষ্পাপ শোনাল। পদ্মজা এদিক-ওদিক তাকিয়ে দেখে নিলো হেমলতার উপস্থিতি। এরপর বলল, ‘আম্মার রং কালো। কিন্তু সৌন্দর্যের কমতি নেই। আম্মাকে কখনো এক মনে দেখিস, বুঝবি। আমাদের আম্মার চোখ দুটি গভীর, বড়ো-বড়ো; পাতলা, মসৃণ ঠোঁট আম্মার ঘন চুলের খোঁপায় এক আকাশ কালো মেঘ। আম্মার শাড়ির কুঁচির ভাজে আভিজাত্য লুকানো। আম্মা যখন তীক্ষ্ণ চোখে আমাদের দিকে তাকান, তখন মনে হয়: প্রকাণ্ড কোনো রাজ্যের রানি তার পূর্বপুরুষের ক্ষমতা প্রকাশ করছেন তীক্ষ্ণ দৃষ্টি নিয়ে। এতকিছু থাকা সত্ত্বেও কি আম্মা আমাদের দেখা প্রথম সুন্দর মানুষ হতে পারেন না?’\n\nপদ্মজার প্রতিটি কথা পূর্ণার ওপর ভীষণ ভাবে প্রভাব ফেলে। ওদিকে প্রেমা চোখ পিটপিট করে কিছু ভাবছে।\n\nপূর্ণা উচ্ছ্বাস নিয়ে বলল, ‘কাল থেকে আমি আম্মাকে মন দিয়ে দেখব।’\n\n‘আমিও,’ প্রেমাও পূর্ণার দলে যোগ দিল।\n\nআবেগের সাইক্লোনে দুই ফোঁটা জল গড়িয়ে পড়ল হেমলতার চোখ বেয়ে, কিছুতেই আটকে রাখতে পারলেন না। এই কালো রঙের জন্য ছোটো থেকে সমাজের তুচ্ছতাচ্ছিল্য পেয়ে এসেছেন! লুকিয়ে কত কেঁদেছেন। কত করে চেয়েছেন, কেউ তাকে সুন্দর বলুক। কিন্তু সেই কপাল কখনো হয়নি। আর আজ, এই বয়সে এসে শুনলেন—তিনি কুৎসিত নন। তার মাঝেও সৌন্দর্য আছে! জন্মদাত্রী মা গায়ের কালো রঙের জন্য গরম চামচ দিয়ে ঘাড়ে পোড়া দাগ বসিয়ে দিয়েছিলেন। আর আজ গর্ভের সন্তান সেই অনুচিত কাজের জবাব দিল! আল্লাহর সৃষ্টি কেউ অসুন্দর নয়। সবার মধ্যেই সৌন্দর্য আছে…\n\n…যা ধরা পড়ে শুধুমাত্র সুন্দর একজোড়া চোখে…পদ্মজার সুন্দর চোখে!\n\n.\n\nনিশুতি রাত। চারিদিকে ঝিঁঝিপোকার ডাক। হুট করে হেমলতার ঘুম ভেঙে গেল। ষষ্ঠ ইন্দ্রিয় ইঙ্গিতে জানান দিচ্ছে ষড়যন্ত্রের। লাহাড়ি ঘরের ডান পাশে দুইজোড়া পায়ের আওয়াজ। হেমলতার বুক কেঁপে উঠল। দ্রুত উঠে বসলেন তিনি, দুই চৌকির মাঝের পর্দা সরিয়ে দেখে নিলেন পদ্মজার অবস্থান। পদ্মজাকে ঘুমাতে দেখে স্বস্তি পেলেন, ছাড়লেন আটকে যাওয়া নিশ্বাস। পায়ের আওয়াজ খুব কাছে শোনা যাচ্ছে। হেমলতা ডান পাশে তাকালেন। গাঢ় অন্ধকার ছাড়া কিছু দেখা যাচ্ছে না। তবুও তিনি তাকিয়ে আছেন। দৃষ্টি দেখে মনে হচ্ছে, টিনের ওপাশে থাকা অদৃশ্য গোপন শত্রুকে তিনি স্পষ্ট দেখতে পাচ্ছেন।\n\n‘কে ওখানে?’\n\nহেমলতার ঝাঁঝালো কণ্ঠে পায়ের আওয়াজ থেমে গেল। কয়েক সেকেন্ড পর ছুটে পালাল দুইজোড়া পা।','\n',char(10)),7,'published',0,'2026-10-06T07:58:46.439Z','2026-10-06T07:58:46.439Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('713784cd-03ce-4881-b13f-8dd844c7d704','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 8',replace('ভোর, বাইরে গুঁড়ি গুঁড়ি বৃষ্টি পড়ছে। সেই সঙ্গে সুন্দর ঠান্ডা একটা হাওয়া বইছে। বৃষ্টি পড়ার কারণে আকাশ মেঘলা, চারপাশটা একটু অন্ধকারাচ্ছন্ন। হালকা আলোতেই মেঝেতে শীতল পাটি বিছিয়ে তিন বোন পড়ছে। ঝমঝম করে বৃষ্টি হয়েছে রাতভর, বর্ষা-স্নানে প্রকৃতি স্নিগ্ধ। এমন সকালে কেউ কেউ ঘুমাতে চায়, আর কেউ-বা বই পড়তে পছন্দ করে…অথবা পছন্দের অন্য যেকোনো কাজ করে। পূর্ণার ঘুমাতে ইচ্ছে করছে, পড়া একদমই সহ্য হচ্ছে না। পদ্মজাকে বলল, ‘আর কতক্ষণ? ঘুমাতে চাই আপা।’\n\nপদ্মজা নিচু গলায় বলল, ‘এইটুকু শেষ করে ঘুমিয়ে পড়িস।’\n\n‘আম্মা তো আরো পড়তে বলল।’\n\n‘কিছু হবে না। এই যে…’ আঙুল দিয়ে দেখিয়ে বলল, ‘এইটুকু পড় ভালো করে, তাহলেই আম্মা ছুটি দিবে।’\n\nপূর্ণা মনের বিরুদ্ধে গিয়েই পড়া শেষ করল। হেমলতা প্রথমে ছুটি দিতে না চাইলেও পদ্মজার অনুরোধে ছেড়ে দিলেন। ছুটি পেয়ে দৌড়ে গিয়ে বিছানায় গা এলিয়ে দিল পূর্ণা, সঙ্গে সঙ্গে তলিয়ে গেল গভীর ঘুমে।\n\nকিছুক্ষণ পর বৃষ্টি থেমে রোদ উঠল। স্কুলের জন্য তৈরি হয়ে পূর্ণাকে অনেক ডাকল পদ্মজা, সাড়া পেল না। এদিকে স্কুলে যাওয়ার সময় হয়েছে। হেমলতা বাইরে থেকে উঁকি দিয়ে প্রশ্ন করলেন, ‘পূর্ণা ঘুমে?’\n\n‘জি, আম্মা।’\n\n‘সে জানে না স্কুল আছে? তবুও কোন আক্কেলে ঘুমাল?’\n\nমায়ের রাগের ফলাফল ভেবে পদ্মজা শঙ্কিত। আজ পূর্ণা নির্ঘাত মার খাবে। সে হেমলতাকে আশ্বস্ত করে বলল, ‘তুমি যাও আম্মা। পূর্ণা কিছুক্ষণের মধ্যে তৈরি হয়ে যাবে।’\n\nহেমলতা জানেন, পূর্ণা এত সহজে ঘুম থেকে উঠবে না। প্রায়ই এমন হয়। যতই আদর করে ডাকা হোক না কেন, বৃষ্টিমাখা সকালে তার ঘুম ভাঙানো যুদ্ধের সমান। বাঁশের কঞ্চিকে পূর্ণা ভীষণ ভয় পায়, অথচ কঞ্চির বাড়ি না খাওয়া অবধি ঘুম তাকে কিছুতেই ছাড়ে না! এ যেন ভূত তাড়ানো। হেমলতা বাঁশের কঞ্চি আনতে বাঁশ বাগানের দিকে চলে যান। এদিকে পদ্মজা ডেকেই যাচ্ছে, ‘পূর্ণা? ওঠ। মারটা খাওয়ার আগে ওঠ। এই পূর্ণা। পূর্ণা রে…পূর্ণা, উঠ।’\n\nপূর্ণা পিটপিট করে চোখ খুলে আবার ঘুমিয়ে যাচ্ছে। প্রেমা এই ব্যাপারটা খুব উপভোগ করে। একটা মানুষ এত ডাকাডাকির পরও কী করে ঘুমিয়ে থাকতে পারে? সে নিষ্কম্প স্থির চোখে তাকিয়ে আছে বড়ো দুই বোনের দিকে। হেমলতা হাতে বাঁশের কঞ্চি নিয়ে ঘরে ঢুকলেন। তা দেখে পদ্মজা পূর্ণাকে জোরে চিমটি কাটে, কিন্তু মুখে বিরক্তিকর আওয়াজ তুলে আবার ঘুমে তলিয়ে যায় পূর্ণা।\n\nতুই সর পদ্ম। ও মারের যোগ্য। পিটিয়ে ওর ঘুম ছুটাতে হবে, হেমলতার রাগান্বিত স্বর।\n\nপদ্মজা মায়ের কথার ওপর কিছু বলার সাহস পেল না, দূরে গিয়ে দাঁড়াল। হেমলতা পূর্ণার পায়ের গোড়ালিতে কঞ্চি দিয়ে বাড়ি দিতেই একটা আওয়াজ হলো প্যাঁচ করে। ভয়ে চোখ বুজে ফেলল পদ্মজা। ইস! পায়ের চামড়া ছিঁড়ে গেছে বোধহয়। ঘুমন্ত পূর্ণার মস্তিষ্ক জানান দেয়, আম্মা এসেছেন এবং তিনি আঘাত করছেন। সে চোখ খোলার আগেই দ্রুত উঠে বসল। চোখ খুলতে খুলতে যদি দেরি হয়ে যায়! বোকাসোকা মুখ করে মায়ের দিকে তাকাল পরিস্থিতি বুঝতে। পদ্মজা ঠোঁট টিপে হাসছে, প্রেমা জোরে হেসে উঠল। হেমলতা কড়া চোখে তাকাতেই থেমে গেল দুই বোনের হাসি। পূর্ণা ভীতু কণ্ঠে বলল, ‘আর হবে না আম্মা।’\n\n‘সে তো প্রতিদিনই বলিস।’\n\n‘আজই শেষ। আম্মা…আম্মা মেরো না।’ সে লাফিয়ে উঠে চৌকির কোণে গিয়ে বসে।\n\nএমন সময় ঘন মেঘে আকাশ ছেয়ে গেল, শোনা গেল বজ্রপাতের আওয়াজ। মনে মনে পূর্ণা-প্রেমা খুশি হলো। আজ আর স্কুলে যেতে হবে না। বাড়ি থেকে দুই ক্রোশ দূরে স্কুল। আম্মা নিশ্চয় যেতে না করবেন। পূৰ্ণা খুশি লুকিয়ে প্রশ্ন করল, ‘মেঘ আসবে মনে হয়। যাব স্কুলে?’\n\n‘মেঘ তোর কী সমস্যা করল? এখনি যাবি স্কুলে। তৈরি হ।\n\nহেমলতা চলে যেতেই পূর্ণা ভ্রুকুঞ্চন করে থম মেরে বসে রইল।\n\nপদ্মজা তাড়া দেয়, ‘বসে আছিস কেন? জলদি কর। নয়তো আবার মার খাবি।’\n\nপূর্ণা তীব্র বিরক্তি নিয়ে স্কুলের জন্য প্রস্তুত হয়।\n\nবর্ষাকাল চলছে। রাতে বিরতিহীনভাবে বৃষ্টি হওয়ায়, কাদা জমেছে রাস্তায়। পথ চলা কষ্টকর।\n\nতিন বোন হাতে জুতা নিয়ে পা টিপে হাঁটছে। তাদের মনে কাজ করছে পিছলে পড়ে বই খাতা নষ্ট হওয়ার ভয়। অর্ধেক পথ যেতে না যেতেই আকাশ ভেঙে বৃষ্টি নামল। পথের পাশ থেকে বড়ো তিনটে কচু পাতা ছিঁড়ল পদ্মজা। পূর্ণা-প্রেমার হাতে দুটো দিয়ে নিজের মাথায় ধরল তৃতীয়টি, তবে তাতে লাভ হলো না। মাথা না ভিজলেও, শরীর ও বই-খাতা ভিজে একাকার হয়ে গেল।\n\nপূর্ণা বিরক্তি প্রকাশ করল, ‘ধ্যাত! ভিজে স্কুলে গিয়ে লাভ কী আপা? দেখো, হাঁটু অবধি পায়জামা কাদা আর বৃষ্টির পানি দিয়ে নষ্ট হয়ে গেছে।’\n\nপদ্মজা চিন্তিত ভঙ্গিতে বলল, ‘বুঝতে পারছি না কী করব! স্কুলে যাব? নাকি বাড়ি ফিরব।’\n\n‘আপা, বাড়ি যাই।’ বলল প্রেমা।\n\nপদ্মজা একটু ভাবল। এরপর দুই বোনকে বলল, ‘ভিজে তো কতবারই গেলাম। আজও যাই। সমস্যা কী?’\n\nঅগত্যা স্কুলেই যেতে হলো। পদ্মজা সম্মতি না দিলে বাড়িতে গিয়েও উঠতে পারবে না তারা। স্কুল ছুটির আগেও বৃষ্টি পুরোপুরি থামেনি। তখন গুড়ি গুড়ি বৃষ্টি পড়ছিল। বৃষ্টিতে ভিজে ভিজেই বাড়ি ফেরার পথ ধরল দুই বোন। প্রেমার এক ঘণ্টা আগে ছুটি হয়েছে। পদ্মজা নিচু কণ্ঠে জিজ্ঞাসা করল, ‘স্কুলে আব্বা এসেছিলেন?’\n\n‘হুম। প্রেমাকে নিয়ে গেছে।’\n\n‘তোর সঙ্গেও তো দেখা হলো।’\n\nপদ্মজার গলাটা করুণ শোনায়। পূর্ণার মন খারাপ হয়। আব্বা কেন তার এত ভালো আপাকে ভালোবাসে না?\n\nবৃষ্টির পানি ও মাটি মিশে কাদায় একাকার হয়ে গেছে পুরো পথ। কাদামাটিতে হাঁটার মতো ভোগান্তি আর নেই। পূর্ণা যেভাবে হেলেদুলে হাঁটছে তাতে পদ্মজার ভয় হচ্ছে, পড়ে না যায়। সে বোনকে ডেকে বলল, ‘পূর্ণা, সাবধানে হাঁট। পড়ে যাবি।’\n\nতার সাবধানী বাণী শেষ হতেই ধপাস করে কাদামাটিতে পড়ে গেল পূর্ণা। আঁতকে উঠে পদ্মজা। পূর্ণার পা নিমিষে ব্যথায় টনটন করে ওঠে। পদ্মজা দুই হাতে আঁকড়ে তোলার চেষ্টা করে। পূর্ণা কিছুতেই ওঠাতে পারছে না। পা যেন ব্যথায় অবশ হয়ে গেল।\n\nকাঁদো কাঁদো হয়ে পদ্মজাকে বলল, ‘আপা, পা ভেঙে গেল মনে হয়। ইস…এত ব্যথা করছে!’\n\n‘মচকেছে বোধহয়। ঠিক হয়ে যাবে। ওঠার চেষ্টা কর। আমার গলা ধরে ওঠ।\n\nগ্রামের পথ, গুড়ি গুড়ি বৃষ্টি হচ্ছে বলে পথে কেউ নেই। গৃহস্থরা ভাতঘুম দিয়েছে। সামনের বিলে থইথই জল, তার পাশে খেত; ডানে-বাঁয়ে কাদামাটির পথ, পেছনে ঝোপঝাড়। পদ্মজা সাহায্য করার মতো আশপাশে কাউকে দেখতে পেল না। এদিকে পা সোজা করার শক্তি পাচ্ছে না পূৰ্ণা, প্রচণ্ড ব্যথা! ঠোঁট কামড়ে কাঁদছে সে। পদ্মজা না পারছে পূর্ণাকে তুলতে, আর না পারছে পূর্ণার কান্না সহ্য করতে। সে মনে মনে আল্লাহর কাছে সাহায্য প্রার্থনা করে, ‘আল্লাহ, কিছু করো। সাহায্য করো।’ একটু পর পূর্ণাকে বলল, ‘বোন আমার, একটু চেষ্টা কর উঠতে।’\n\nপদ্মজার উৎসাহে পূর্ণা পায়ের পাতা মাটিতে ফেলল। কিন্তু সঙ্গে সঙ্গে ব্যথার বিজলি চমকে ওঠল তার পুরো শরীরে। ‘ও মা! আপা রে, পারছি না। আমার পা শেষ। মরে যাব আমি।’\n\n‘এসব বলিস না। পায়ের ব্যথায় কেউ মরে!’\n\nঅল্পক্ষণের মাঝেই আহত পা ফুলে দুই ইঞ্চি উঁচু হয়ে গেছে! তা দেখে আতঙ্কে চোখ-মুখ নীল হয়ে গেল পদ্মজার, কান্না পাচ্ছে তার। পদ্মজা আলতো করে চাপ দিতেই পায়ের ব্যথায় চেঁচিয়ে উঠল পূর্ণা।\n\n‘একটু সাবধানে হাঁটলে কী হতো? ইশ, এখন কী কষ্টটা হচ্ছে।’ পদ্মজার চোখ জলে ভরে উঠেছে।\n\n‘আপা…আপা, ব্যথায় মরে যাচ্ছি।’\n\nপদ্মজা খুব কাছে পায়ের শব্দ পেল। চকিতে চোখ তুলে তাকাল সে খেতের দিকে; পরমুহূর্তে হাসি ফুটে উঠল ঠোঁটে। সে উচ্ছ্বাসে চেঁচিয়ে উঠল, ‘পূর্ণা রে, আম্মা আসছে!’\n\nহেমলতাকে দেখে পূর্ণা কলিজায় পানি প্রায়, মাকে দেখেই যেন ব্যথা অনেকটা কমে গেছে। হেমলতা ছুটে আসেন। পূর্ণার মাথায় হাত বুলিয়ে বললেন, ‘কিছু হয়নি। এসব সামান্য ব্যাপার।\n\nএরপর পদ্মজাকে বললেন, ‘তুই বইগুলো নে।’\n\nহেমলতা এদিকে সেলাই করা কাপড় দিতে এসেছিলেন। যার কাপড় ছিল, সে অসুস্থ। তাই যেতে পারছিল না। বাড়িতেও কোনো কাজে মন টিকছিল না। তাই ছাতা নিয়ে বেরিয়ে পড়েন। ঘরে চুপচাপ বসে থাকার চেয়ে একটা মানুষকে সাহায্য করা ভালো। ফেরার পথে তিনি দূর থেকে দুটো বিপর্যস্ত মেয়েকে দেখতে পেলেন। একটা মেয়ে পথে বসে আছে, আরেকটা মেয়ে তাকে তোলার চেষ্টা করছে। মেয়ে দুটিকে চিনতে পেরে বুক কেঁপে ওঠে তার। পথ দিয়ে আসলে দেরি হবে বলে তিনি খেতের ভেতর দিয়েই ছুটে এসেছেন।\n\nপূর্ণা ব্যথায় যেন নিশ্বাস নেয়ার শক্তি পাচ্ছে না। একটা ভ্যান পাওয়া গেলে খুব উপকার হতো। আশ্চর্যভাবে দুই মিনিটের মাথায় দেখা মিলল ভ্যানের! ভ্যানে চিত্রা, লিখনসহ আরো দুজন, তারা মাতব্বর বাড়িতে গিয়েছিল। আরেকটু এগোতেই পদ্মজা আর তার মা-বোনকে দেখতে পেল চিত্রা, উদ্বিগ্ন কণ্ঠে ভ্যানচালককে বলল, ‘চাচা, ভ্যান থামান।’\n\nচিত্রার দৃষ্টি অনুসরণ করে লিখনের নজরে ব্যাপারটা আসতেই সে তাড়াহুড়ো করে ভ্যান থেকে নেমে আসে, চিত্রাও বসে নেই। চোখে-মুখে ভয় নিয়ে জানতে চাইল, ‘কী হয়েছে? পূর্ণার কী হয়েছে?\n\nপদ্মজা বলল, ‘কাদায় পড়ে পা মচকে গেছে।’\n\nহেমলতা, চিত্রা, পদ্মজা এবং পূর্ণাকে ভ্যানে তুলে দিয়ে লিখনসহ বাকি দুজন সহকর্মী ভ্যান ছেড়ে দিল। তারা মোড়ল বাড়িতে হেঁটেই ফিরবে।\n\n.\n\nঅনেকটা কমেছে পা ব্যথা, দুটি বালিশের ওপর রাখা হয়েছে পা। ব্রেস নেই বলে ব্রেসের মতো কাপড় বেঁধে দিয়েছেন হেমলতা। যে ব্যথা পেয়েছে, তাতে কয়দিন স্বাভাবিক ভাবে হাঁটতেও পারবে না। হেমলতা মেয়েকে খাইয়ে দিতে দিতে বললেন, ‘এবার খুশি? স্কুলে যেতে হবে না। কাজ করতে হবে না। সকালে উঠে পড়তে বসতে হবে না।\n\nপূর্ণা রাজ্যের দুঃখ নিয়ে বলল, ‘সবই ঠিক আছে। কিন্তু এখন টিভি দেখতে যাব কীভাবে?’\n\nসাড়া না পেয়ে পূর্ণা বুঝতে পারল, সে মুখ ফসকে ভুল জায়গায় ভুল কথা বলে ফেলেছে। বিব্রত হয়ে উঠল ও, ঢোক গিলল। এরপর কাঁচুমাচু হয়ে মিইয়ে যাওয়া গলায় বলল, ‘মোটেও খুশি হইনি।’\n\nপূর্ণার অগোচরে হেমলতা ঠোঁট চেপে হাসেন। আড়াল থেকে তা দেখে পদ্মজাও হাসল।\n\nতখন দিনের শেষভাগ। সূর্য মামা আকাশ গাঢ় লাল আভায় রাঙিয়ে বিদায় নিতে চলেছেন। আকাশের সঙ্গে মিশে রয়েছে ঘন মেঘ, সেই মেঘের ফাঁক দিয়ে উঁকি দিচ্ছে দিনান্তের শেষ আলো। ঠিক তখন মগা এসে জানাল, মুন্নার বাপ খুন হয়েছে। কথাটি শোনার সঙ্গে সঙ্গে উপস্থিত সবার মাথায় যেন আছড়ে পড়ল বজ্র। পঙ্গু, ভিক্ষুক অসহায় মানুষটাকে আবার কে মারল? এমন মানুষের শত্রু থাকে? তাও আবার এমনই যে একেবারে মেরে ফেলল! হেমলতা শ্বাসরুদ্ধকর কণ্ঠে প্রশ্ন করলেন, ‘কখনকার ঘটনা?’\n\nমগা জানাল, দুপুরের কথা। দুপুর দুটো কি তিনটায় গ্রামবাসী জানতে পারে ঘটনাটি। আস্তে আস্তে সব গ্রামে খবর যাচ্ছে। লাশ নোয়াপাড়ার ধানখেতে পাওয়া গেছে। সবাই মিলে মুন্নার বাপকে দেখতে যায়। বাড়িতে রয়ে যায় শুধু পদ্মজা, প্রেমা ও পূর্ণা।\n\nপুলিশ লাশ নিয়ে যাওয়ার পর সবাই মুন্নাকে নিয়ে বিপাকে পড়ে। আত্মীয় বলতে তার কেউ নেই। দুঃসম্পর্কের যারা আছে তারা মুন্নার দায়িত্ব নিতে চাইল না। মাতব্বর মুন্নার ভার নিতে চেয়েছিলেন। কিন্তু মুন্না জানাল, সে থাকলে পদ্মজাদের বাড়িতে থাকবে। হেমলতা মাতব্বরের অনুমতি নিয়ে সানন্দে মুন্নাকে নিজের বাড়িতে নিয়ে আসেন। এখন থেকে মুন্না এই বাড়ির ছেলে। পদ্মজা-পূর্ণা খুব খুশি হয়। খুশি হলো না শুধু প্রেমা। মুন্না ও প্রেমা সমবয়সি। প্রেমা ভাবছে, তার আদর এখন ভাগাভাগি হয়ে যাবে।\n\nহেমলতা ব্যাপারটা বুঝতে পেরে পদ্মজাকে বললেন, ‘প্রেমার বোধহয় মুন্নাকে পছন্দ হচ্ছে না। দুজনের মধ্যে সখ্যতা করে দিস, যাতে একজন আরেকজনকে আপন চোখে দেখে।’\n\nপদ্মজা আশ্বস্ত করে বলল, ‘কয়দিন গেলেই মিশবে\n\nমুন্না বেঘোরে ঘুমাচ্ছে। হেমলতা তাকে ঘরে এনেই গরম গরম ভাত খাইয়ে দিয়েছিলেন। খেয়েই ছেলেটা ঘুমিয়ে পড়ে। রাত তো কম হলো না! মা-বোনের বৈঠক দেখে পূর্ণা বলল, ‘আম্মা, মুন্নার নতুন নাম রাখা উচিত।’\n\n‘কেন?’\n\n‘এখন থেকে মুন্না আমাদের ভাই। আমাদের নাম প দিয়ে। তাইলে ওর নাম-ও প দিয়ে হবে। তাই না আপা?’\n\nহেমলতা হেসে বললেন, ‘তুই নাম রাখ তাহলে।’\n\n‘রেখেছি তো। প্রান্ত মোড়ল।’\n\n‘মুন্নাকে আগে ওর নতুন নাম সম্পর্কে জানা, যদি রাজি হয় তখন সবাই এই নামে ডাকব। ওরও তো পছন্দ আছে।’\n\n‘রাজি হবে না মানে? পিটিয়ে রাজি করাব\n\nমেয়ের কথায় হেমলতা হাসলেন। পূর্ণা বলল, শ্বশুরবাড়ি থেকে গিয়ে আনার মতো একটা ভাই হলো আমাদের। আপাকে যখন বিয়ে দেব, আমি আর প্রান্ত গিয়ে আপাকে নিয়ে আসব তাই না আম্মা?’\n\nঅসুস্থ হলে খুব কথা বলে পূর্ণা। মুখ বন্ধ রাখতেই পারে না। অনেক বছর আগের ঘটনা, বা কয়েক বছর পর কী হবে তা নিয়ে অনবরত কথা বলতে থাকে।\n\n.\n\nগহিন অন্ধকার। আজ বোধহয় অমাবস্যা। হেমলতা কালো চাদরের আবরণে ঘাপটি মেরে বারান্দায় বসে আছেন। হাতের কাছে ছুরি, লাঠি। গত তিন দিন ধরে ঘরের পাশে পায়ের আওয়াজ শোনা যাচ্ছে। তখন ঘরে মোর্শেদ ছিলেন, আর যাই হোক—পুরুষ তো, তাই সাহসও ছিল বুকে। আজ মোর্শেদ নেই। মুন্নাকে দত্তক নিয়ে বাড়িতে আনায় তিনি ঝগড়া করে বাড়ি ছেড়েছেন। কবে ফিরবেন ঠিক নেই! আজ কিছুতেই ঘুমানো যাবে না। হাতেনাতে সন্দেহকারীকে ধরে এই বিপদ থেকে মুক্ত হতে হবে। কিন্তু অনেকক্ষণ হলো কেউ আসছে না। চোখ বুজে আসছে হেমলতার। সারাদিন অনেক খাটুনি গেল।\n\nকাদামাটিতে ছপছপ শব্দ তুলে কেউ আসছে। হেমলতা সতর্ক হয়ে ওঠেন, শক্ত করে ধরলেন লাঠি-ছুরি। পায়ের শব্দটা কাছে আসতেই তিনি বেরিয়ে আসেন। অন্ধকারে মুখ পরিষ্কার নয়। আন্দাজে ছুঁড়ে মারেন হাতের লাঠি। লাঠিটা বেশ ভালোভাবেই পড়ল সামনে থাকা ছায়াটির ওপর, হতভাগা আর্তনাদ করে বসে পড়ল মাটিতে; ততক্ষণে পেছনের ছায়াটি দৌড়ে পালাল! প্রথমজনও পালানোর চেষ্টা করল, হেমলতার জন্য পেরে উঠল না। তিনি আরেকটা লাঠি দিয়ে আবার আঘাত করে বসেন, তার দৃষ্টি থেকে যেন আগুন স্ফুরিত হচ্ছে।\n\nআহত ব্যক্তির আর্তচিৎকার শুনে বাড়ির ভেতর থেকে ছুটে আসে সবাই। টর্চের আলোতে চারদিক আলোকিত হয়ে ওঠে। হেমলতা স্বাভাবিক ভঙ্গি নিয়ে দাঁড়িয়ে আছেন। তিনি যেন জানতেন এই ছায়াটিরই আসার কথা ছিল। আজই শুটিং দলকে বাড়ি থেকে বের করবেন। তবেই শান্তি! হই- হুল্লোড় শুনে পদ্মজা, প্রেমা, মুন্না বেরিয়ে আসে। পূর্ণা ঘরেই রইল।\n\nচোখের সামনে ডিরেক্টর আবুল জাহেদকে দেখে চমকে গেল পদ্মজা!\n\nআর ঠিক তখনই কোত্থেকে যেন আগমন ঘটল মোর্শেদের!','\n',char(10)),8,'published',0,'2026-10-06T08:01:00.458Z','2026-10-06T08:01:00.458Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('69d67d0f-8dcd-4a7b-a5b7-8f53f90a42ce','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 9',replace('আবুল জাহেদকে আহত অবস্থায় দেখে সবাই চমকে গেল। তার কপাল বেয়ে রক্ত ঝরছে।\n\nফার্স্ট এইড বক্স আনতে একজন দৌড়ে যায় বাড়ির ভেতর। লিখন কিছু সময়ের জন্য থমকাল। আবুল জাহেদের ক্ষতটা ব্যান্ডেজ করার পর তাকে একটা চেয়ারে বসতে দেয়া হয়। হেমলতা একহাতে লাঠিতে ভর দিয়ে স্বাভাবিক ভঙ্গিতে দাঁড়িয়ে আছেন।\n\nলিখন বিস্ময় নিয়ে প্রশ্ন করল, ‘কী হয়েছিল? আপনি উনাকে আঘাত করেছেন কেন?’\n\nহেমলতা স্বাভাবিক কণ্ঠে বললেন, ‘এই অসভ্য লোক আজ চারদিন ধরে মাঝরাতে এখানে ঘুরঘুর করে। তার উদ্দেশ্য খারাপ।’\n\nলিখন চোখের কোণ দিয়ে পদ্মজাকে দেখে আবুল জাহেদকে প্রশ্ন করল, ‘উনি যা বলছেন, সত্যি?’\n\nআবুল জাহেদ গমগম করে উঠল, ‘এখানে আমি আজই প্রথম এসেছি। ঘুম আসছিল না তাই হাঁটতে হাঁটতে চলে এসেছি। বলা নেই, কওয়া নেই হুট করেই উনি আক্রমণ করে বসলেন। কী ব্যথা!’ কপালে হাত রাখল সে।\n\nহেমলতা প্রতিবাদ করলেন দৃঢ় স্বরে, ভুলেও মিথ্যে বলবেন না।’\n\nআবুল জাহেদ কিছুতেই তার উদ্দেশ্য স্বীকার করল না। তর্কে-তর্কে ভোরের আলো ফুটল। হেমলতা কঠিন করে জানিয়ে দিয়েছেন, আজই এই বাড়ি ছাড়তে হবে। হেমলতার সিদ্ধান্ত শুনে দলটির মধ্যে আতঙ্ক ছড়িয়ে পড়ে। তীরে এসে নৌকা ডুববে নাকি! সিনেমার শেষ অংশটুকু এখনো বাকি। শর্ত অনুযায়ী আরো দশদিন সময় আছে। দলের একজন বয়স্ক অভিনেতা এই সিদ্ধান্তের প্রতিবাদ করলে হেমলতা জবাব দিলেন, ‘আমার তিনটা মেয়ের নিরাপত্তা দিতে পারবেন? একটা পুরুষ মানুষ রাতের আঁধারে যুবতী মেয়েদের ঘরের পাশ দিয়ে ঘুরঘুর কেন করবে? কীসের ভিত্তিতে?’\n\nকাউকে কথা বলার সুযোগ না দিয়ে সবাইকে এড়িয়ে লাহাড়ি ঘরে চলে গেলেন হেমলতা। এদের সঙ্গে তর্ক করে শুধু সময়ই নষ্ট হবে। আবুল জাহেদের ধূর্ত চাহনি তার নজরে এসেছে বারংবার। প্রথম রাতে পায়ের আওয়াজ শুনে চিনতে পারেননি। পরদিন সন্দেহ তালিকায় থাকা চার-পাঁচ জনকে অনুসরণ করে তিনি নিশ্চিত হোন: রাতে কে লাহাড়ি ঘরের পাশে হেঁটেছিল। ঘরের ডান পাশে পলিথিন কাগজ দিয়ে ঢাকা তুষের স্তূপ রাখা আছে। অসাবধানতায় আবুল জাহেদের কাদা-মাখা জুতা তুষের স্তূপে পড়ে যায়, তাই তুষ লেগে যায় জুতায়। হেমলতা বাড়ির বারান্দায় সেই জুতাজোড়া দেখতে পান। তুষ বাড়ির আর কোথাও নেই, তাই ব্যস্ত হয়ে তুষের স্তূপের কাছে এসে দেখেন; একজোড়া জুতার ছাপ! সেই জুতা যখন আবুল জাহেদ পরল তখন তিনি পুরোপুরিভাবে নিশ্চিত হলেন, শেয়ালটা আসলে কে!\n\nশুটিং দলটার মধ্যে একটা হাহাকার লেগে গেছে। বেশ কিছুকক্ষণ তারা নিজেদের মধ্যে আলোচনা চলল। হেমলতাকে কিছু বলে লাভ নেই, তা প্রত্যেকে বুঝে গেছে; তাই সবাই মোর্শেদকে ধরল। বিনিময়ে তারা আরো টাকা দিতে রাজি আছে। হেমলতার ধমকের ভারে তখন চুপ হয়ে গেলেও, টাকার কথা শুনে মোর্শেদের চোখ দুটি জ্বলজ্বল করে ওঠে। ঘরে এসে হেমলতার সঙ্গে ধুন্ধুমার ঝগড়া লাগিয়ে দেন। হেমলতা প্রথমে কিছুতেই রাজি হোননি। তবে শেষ অবধি নিজের সিদ্ধান্তে অনড় থাকতে পারলেন না। দলের কিছু ভালো মানুষের অনুরোধ ফেলতে বেশ অস্বস্তিবোধ করছিলেন। দশদিনের বদলে পাঁচ দিনের সময় দিলেন। যতক্ষণ এরা বাড়ি না ছাড়বে তিনি শান্তি পাবেন না। তবে একটা স্বস্তির নিশ্বাসও ফেললেন।\n\nভাগ্যিস কোনো ঘটনা ঘটার আগে ব্যাপারটা সামলানো গেছে।\n\nবেশ গরম পড়েছে আজ। পদ্মজা পাটিতে বসে মনোযোগ দিয়ে মুন্নাকে শেখাচ্ছে; কাকে কী ডাকতে হবে।\n\n‘আমায় ডাকবি বড়ো আপা। পূর্ণাকে ছোটো আপা। আর প্রেমা তো তোর সমান। তাই প্রেমা ডাকবি। দুজন মিলেমিশে থাকবি। বুঝেছিস?’\n\n‘হ, বুঝছি।’\n\n‘আম্মাকে তুইও আম্মা ডাকবি। আমাদের আম্মা-আব্বা এখন থেকে তোরও আম্মা-আব্বা, বুঝেছিস?\n\nমুন্না বিজ্ঞ স্বরে বলল, ‘হ, বুঝছি।’\n\nহেমলতা রান্না রেখে উঠে আসেন। মুন্নাকে বললেন, ‘শুদ্ধ ভাষায় কথা বলবি। তোর পদ্ম আপা যেভাবে বলে।’\n\nমুন্নার সরল স্বীকারোক্তি, ‘কইয়ামনে।’\n\nপদ্মজা বলল, কইয়ামনে না। বল, আচ্ছা বলব।’\n\nমুন্না বাধ্য ছেলের মতো হেসে বলল, ‘আচ্ছা, বলব।’\n\nহেমলতা হেসে চলে যান। পূর্ণা রুম থেকে মুন্নাকে ডাকল, ‘মুন্না রে?’\n\n‘হ, ছুডু আপা।’\n\nপদ্মজা মুন্নার গালে আলতো করে থাপ্পড় দিয়ে বলল, বল—জি, ছোটো আপা।’\n\nমুন্না পদ্মজার মতো করেই বলল, ‘জি ছোটো আপা।’\n\nপদ্মজা হাসল। পূর্ণা বলল, ‘তোর নাম পালটাতে হবে। আমি তোর নতুন নাম রেখেছি।\n\n‘কেরে? নাম পালডাইতাম কেরে?’ পদ্মজা কিছু বলার আগে মুন্না প্ৰশ্ন করল, ‘আইচ্ছা এই কথাডা কেমনে কইতাম?’\n\nপদ্মজা হেসে কপাল চাপড়ায়, এই ছেলে তো আঞ্চলিক ভাষায় বুঁদ হয়ে আছে। পূর্ণা বলল, ‘তুই এখন আমাদের ভাই। আমাদের নামের সঙ্গে মিলিয়ে তোর নাম রাখা উচিত। উচিত না?’\n\nমুন্না দাঁত কেলিয়ে হেসে সায় দিল, ‘হ।’\n\n‘এজন্যই তোর নাম পালটাতে হবে। আজ থেকে তোর নাম প্রান্ত মোড়ল। সবাইকে বলবি এটা। মনে থাকবে?’\n\n‘হ, মনে রাহাম।’\n\n‘বল, আচ্ছা মনে রাখব।’\n\n‘আচ্ছা, মনে রাখব।’\n\nদুপুর গড়াতেই হাজেরা এলো। সঙ্গে নিয়ে এসেছে বানোয়াট গল্প আর বিলাপ। ইশারা-ইঙ্গিতে সে লাউ চাইছে। মোর্শেদ গতকাল সব লাউ বাজারে তুলেছেন, গাছে আর একটা ছিল। এদিকে ঘরে চিংড়ি মাছ আছে, প্ৰান্ত লাউ দিয়ে চিংড়ি খাওয়ার ইচ্ছে প্রকাশ করেছে বলে হেমলতা ছেলের ইচ্ছে পূরণ করতে হাসিমুখে শেষ লাউটা ছিঁড়ে এনে ঘরে রেখেছেন। এখন আবার হাজেরারও লাউ চাই! কেউ কিছু চাইলে হাতে থাকা সত্ত্বেও হেমলতা ফিরিয়ে দেননি। আজও দিলেন না। তিনি হাজেরাকে হাসিমুখে লাউ দিয়ে দিলেন। হাজেরা সন্তুষ্টি প্রকাশ করে চলে গেল। পদ্মজা মায়ের দিকে অসহায় চোখে তাকাল। প্রান্ত এই বাড়িতে এসে প্রথম যা চাইল, তাই পেল না। মনের ওপর নেতিবাচক প্রভাব পড়বে না তো! হেমলতা পদ্মজার দৃষ্টি বুঝেও কিছু বললেন না। প্রান্তকে ডেকে কোলে বসালেন। ছেলেটাকে দেখতে বেশ লাগছে। দুপুরে তিনি গোসল করিয়েছেন। মনে হচ্ছিল, কোনো ময়লার স্তূপ পরিষ্কার করা হচ্ছে। জন্মদাতার মৃত্যু প্রান্তের উপর বিন্দুমাত্র প্রভাব ফেলল না। এজন্য কেউই অবাক হয়নি। বাপ-ছেলের শুধু রাতেই একসঙ্গে থাকা হতো। অনেক রাত প্রান্ত একা থেকেছে। এইটুকু ছেলে কত রাত ভয় নিয়ে কাটিয়েছে! হেমলতা আদুরে কণ্ঠে বললেন, ‘একটা গল্প শোনাই। শুনবি?’\n\n‘হুনাও।’\n\nপদ্মজা প্রান্তের ভাষার ভুল ধরিয়ে দিল, ‘হুনাও না। বল, শোনাও, আম্মা।’\n\nপ্রান্ত মাথা কাত করে হেমলতাকে বলল, ‘শোনাও, আম্মা।’\n\nআম্মা ডাকটা শুনে হেমলতা বুক বিশুদ্ধ ভালোলাগায় ছেয়ে গেল। তিনি কণ্ঠে ভালোবাসা ঢেলে বললেন, ‘আমাদের একদিন মরতে হবে জানিস তো?’\n\n‘হ।’\n\n‘জান্নাত-জাহান্নামের কথা কখনো কেউ বলেছে?’\n\nপ্রান্ত মাথা দুই পাশে নাড়াল, কেউ শোনায়নি। হেমলতা এমনটাই সন্দেহ করেছিলেন। প্রান্ত এ সম্পর্কে জানে না। তিনি ধৈর্য নিয়ে সুন্দর করে জান্নাত-জাহান্নামের বর্ণনা দিলেন। জান্নাতের বর্ণনা শুনে প্রান্তের চোখ দুটি জ্বলজ্বল করে উঠল। প্রশ্ন করল হাজারটা। হেমলতাকে জানাল, সে জান্নাতে যেতে চায়; জাহান্নামে যেতে চায় না। হেমলতা বললেন, ‘আচ্ছা, এখন গল্পটা বলি। মন দিয়ে শুনবি।’\n\nপ্রান্ত মাথা কাত করে হ্যাঁ সূচক সম্মতি দিল। হেমলতা বলতে শুরু করলেন, ‘একজন মহিলা একা থাকত বাড়িতে। না, দুটি ছেলেমেয়ে থাকত তার সঙ্গে, খুব ছোটো ছোটো; খুব অভাব তাদের। ছোটো একটা জায়গায় মাটির ঘর। ঘরের সামনে শখ করে একটা লাউ-চারা লাগায়। লাউ গাছ বড়ো হয়, পাতা হয় অনেক। এই লাউ পাতা দিয়ে দিন চলে তাদের। কখনো সিদ্ধ করে খায়। নুন-মরিচ পেলে শাক রেঁধে খায়। তো একদিন একজন ভিক্ষুক এলো। ভিক্ষুকটি খায় না দুই দিন ধরে। লাউ গাছে পাতা দেখে তার ভীষণ খেতে ইচ্ছে করে। লাউ গাছের মালিককে ভিক্ষুক বলে, লাউ পাতা দিতে, রেঁধে খাবে। খুব অনুনয় করে বলে। মহিলাটির মায়া হয়। ভিক্ষুক মহিলাকে কথা শোনাতে শোনাতে কয়েকটা লাউ পাতা ছিঁড়ে দেয়। তার কয়দিন পর লাউ গাছের মালিক মারা গেল। গ্রামবাসীসহ মসজিদের ইমাম মিলে দাফন করে তাকে। বুঝতে পেরেছিস প্রান্ত?’\n\n‘হ।’\n\nপ্রান্ত মনোযোগ দিয়ে শুনছে, মনোযোগী শ্রোতা সে। হেমলতা বাকিটা শুরু করলেন, ‘গ্রামের ইমাম একদিন স্বপ্ন দেখেন, যে মহিলাটিকে তিনি দাফন করেছেন তার চারপাশে আগুন দাউদাউ করে জ্বলছে। কিন্তু তার গায়ে আঁচ অবধি লাগছে না। মহিলাটিকে ঘিরে রেখেছে লাউ পাতা! তাই আগুন কাছে ঘেঁষতে পারছে না। ওই যে সে এক ভিক্ষুককে নিজের একবেলা খাবারের লাউ পাতা দান করেছিল? সেই লাউ পাতা এখন তাকে কবরের শাস্তি থেকে বাঁচাচ্ছে। জাহান্নাম থেকে বাঁচতে আমাদের অনেক ইবাদত করা উচিত। তার মধ্যে একটি হলো দান। সামর্থ্য অনুযায়ী দান করা উচিত। কাউকে ফিরিয়ে দেয়া উচিত না। বোঝা গেছে?’\n\n‘হ, বুঝছি। আমিও অনেক দান করাম।’\n\n‘হুম। করবি। অনেক বড়ো হবি জীবনে। আর অনেক দান-খয়রাত করবি। আচ্ছা, প্রান্ত এখন যদি কোনো অভাবী এসে বলে, তোর লাউটা দিতে। তুই কী করবি?’\n\nপ্রান্ত গম্ভীর হয়ে ভেবে বলল, ‘দিয়া দিয়াম।’\n\n‘একটু আগে একজন মহিলা এসেছিল, দেখেছিস?’\n\n‘হ, দেখছি।’\n\n‘সে খুব গরিব। বাড়িতে ছোটো ছোটো বাচ্চা আছে। এসে বলল, লাউ দিতে। তাই তোর লাউটা দিয়েছি। এজন্য কী এখন তোর মন খারাপ হবে?’\n\n‘লাউড়া তো তুমি দিছো। তাইলে তোমারে আগুন থাইকা বাঁচাইব লাউডা?’\n\n‘লাউটা আমি দিলেও, তোর জন্য ছিল। তুই এখন খুশি মনে মেনে নিলে লাউটা তোকে আগুন থেকে বাঁচাবে।’\n\nহেমলতার কথায় প্রান্তর চোখেমুখে দীপ্তি ছড়ায়। পরপরই মুখ গম্ভীর করে প্রশ্ন করল, ‘একটা লাউ কেমনে বাঁচাইব আমারে?’\n\nপ্রান্তর নিষ্পাপ কণ্ঠে প্রশ্নটা শুনে হেমলতা-পদ্মজা-পূর্ণা হেসে উঠল পদ্মজা বলল, ‘কয়টা পাতা অনেকগুলো হয়ে মহিলাটাকে বাঁচিয়েছিল। তেমন একটা লাউ অনেকগুলো হয়ে তোকে বাঁচাবে।’\n\nপ্রান্ত একটার পর একটা প্রশ্ন করেই যাচ্ছে। হেমলতা হেসে হেসে তার উত্তর দিচ্ছেন। পদ্মজার হুট করেই প্রান্তের থেকে চোখ সরে হেমলতার ওপর পড়ে।\n\nমা হাসলে সন্তানদের বুকে যে আনন্দের ঢেউ উঠে তা কী মায়েরা জানেন? পদ্মজার আদর্শ তার মা। সে তার মায়ের মতো হতে চায়। হুবহু মায়ের মতো!\n\nপাঁচদিন শেষ। শুটিং দলের মধ্যে খুব ব্যস্ততা। সবকিছু গোছানো হচ্ছে। তাড়াহুড়ো করে পাঁচ দিনে শেষ করা হয়েছে শুট। লিখন উঠানে চেয়ার নিয়ে বসে আছে। চিত্রা এসে তার পাশে বসল, কাশির মতো শব্দ করল লিখনের মনোযোগ পেতে। তাকাল লিখন, ম্লানমুখে প্রশ্ন করল, ‘সব গোছানো শেষ?’\n\nহুম, শেষ। তুমি তো কিছুই গুছাওনি!’\n\n‘বিকেলে রওনা দেব। আমার আর কী আছে গোছানোর? দুপুরেই শেষ করে ফেলব।’\n\n‘মন খারাপ?’\n\nলিখন কিছু বলল না, তাকাল লাহাড়ি ঘরের দিকে; দৃষ্টিতে শূন্যতা, কিছু ফেলে যাওয়ার বেদনা। বুকের বাঁ পাশে চিনচিন করা ব্যথাটা আর সহ্য হচ্ছে না। চিত্রা হাতঘড়ি পরতে পরতে বলল, ‘ছোটো বোনের সমান বলে ঠোঁট বাঁকিয়ে ছিলে। এখন তার প্রেমেই পড়লে।’\n\nলিখন কিছু বলল না, তবে দীর্ঘশ্বাস ছাড়ল একটা। চিত্রা বলল, ‘পদ্মজা কিন্তু অনেক বড়োই। শুনেছি, আগামী মাসে ওর সতেরো হবে। এই গ্রামে সতেরো বছর বয়সি অবিবাহিত মেয়ে হাতেগোনা কয়টা। পদ্মজার নব্বই ভাগ সহপাঠী বিবাহিত। তাছাড়া খুব কম মেয়েই স্কুলে পড়ে।’\n\nচিত্রার কথা অগ্রাহ্য করে লিখন বলল, ‘তোমার বিয়েটা কবে হচ্ছে?’\n\n‘ভগবান চাইলে বছরের শেষ দিকে।’\n\nকিছুক্ষণের মধ্যে সবাই ঢাকা রওনা দেবে। হেমলতা-মোর্শেদ বিদায় দিতে এসেছেন। দলটার তিন-চার জনের চরিত্রে সমস্যা থাকলেও, বাকিরা খুব ভালো। তারা হেমলতার সঙ্গে মিশে গিয়েছিল। নিজের বাড়ি মনে করে থেকেছে, বাড়ির দেখাশোনা করেছে। লিখন হেমলতার আড়ালে একটি সাহসিকতার কাজ করে ফেলল। ব্যস্ত পায়ে চলে গেল লাহাড়ি ঘরের দিকে\n\nবারান্দায় বসেছিল পদ্মজা। লিখনকে দেখে ভয়ে কেঁপে উঠল তার বুক। পদ্মজাকে কিছু বলতে দিল না লিখন। সে দ্রুত বারান্দায় উঠে পদ্মজার হাতে একটা চিঠি গুঁজে দিয়ে জায়গা ত্যাগ করল।\n\nপ্রবলভাবে কাঁপছে পদ্মজা। এমনকি পূর্ণাও চৌকি থেকে ব্যাপারটা খেয়াল করে হতভম্ব। খোঁড়ার মতো ধীর পায়ে হেঁটে এলো সে। ততক্ষণে পদ্মজার সারা শরীর বেয়ে ঘাম ছুটছে, হিতাহিত জ্ঞান শূন্য হয়ে গেছে। হাত থেকে পড়ে গেল চিঠি, সেই চিঠিটি দ্রুত কুড়িয়ে নিলো পূর্ণা।\n\nপদ্মজার মনে হচ্ছে—এখনই সে মাথা ঘুরে পড়ে যাবে! হেমলতা এসে দেখেন পদ্মজা হাঁটুতে থুতনি ঠেকিয়ে বসে আছে। কেমন দেখাচ্ছে যেন। তিনি উৎকণ্ঠা নিয়ে প্রশ্ন করলেন, ‘পদ্ম? শরীর খারাপ?\n\nমায়ের কণ্ঠ শুনে পদ্মজা ভয় পেল। বাতাসে অস্বস্তি, নিশ্বাসে অস্বস্তি; চোখ দুটি স্থির রাখা যাচ্ছে না, নিশ্বাস এলোমেলো। পূর্ণা পরিস্থিতি সামলাতে বলল, ‘আম্মা, আপার মাথাব্যথা।’\n\n‘হুট করে এমন মাথাব্যথা উঠল কেন? পদ্ম রে, খুব ব্যথা?’\n\nপদ্মজা অসহায় চোখে পূর্ণার দিকে তাকাল। আকস্মিক ঘটনায় সে ভেঙে পড়েছে। ডান হাত কাঁপছে অনবরত। হেমলতা চোখ ঘুরিয়ে দুই মেয়েকে দেখলেন। এদের হাবভাব হঠাৎ সন্দেহজনক লাগছে। তিনি কঠিন স্বরে প্রশ্ন করলেন, ‘কী লুকোচ্ছিস দুজন? কেউ এসেছিল?’\n\nমায়ের প্রশ্নে পদ্মজার চেয়ে পূর্ণা বেশি ভয় পেল। হাতের চিঠিটা আরো শক্ত করে চেপে ধরল সে।\n\nকী লেখা আছে না পড়ে এই চিঠি হাতছাড়া করবে না সে।','\n',char(10)),9,'published',0,'2026-10-06T08:04:03.815Z','2026-10-06T08:04:03.815Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('9e1424ae-3359-43d7-a8e5-3f31fa7e10f8','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 10',replace('হেমলতার ধারাল দৃষ্টি তিরের ফলার মতো পদ্মজার গায়ে বিঁধছে। সে কাঁপা স্বরে জানিয়ে দিল, ‘শুটিং দলের একজন এসেছিল।’\n\nহেমলতার ঠোঁট দুটো ফুলে উঠল প্রচণ্ড আক্রোশে। পদ্মজা সবাইকে চেনে না। তাই তিনি পূর্ণাকে প্রশ্ন করলেন, ‘পূর্ণা, কে এসেছিল?’\n\nপূর্ণা দুই সেকেন্ড ভাবল। এরপর নতমুখে বলল, ‘কালো দেখতে যে… মিলন।’\n\nপদ্মজা আড়চোখে পূর্ণার দিকে তাকাল। তার ভয় হচ্ছে: মা যদি এখন বলে, মিলন তো তার সামনেই ছিল…তাহলে কী হবে? পূর্ণা মিথ্যে বলল কেন! সত্য বললেই পারত। হেমলতা বিশ্বাস করেছেন নাকি করেননি সেটা দৃষ্টি দেখে বোঝা গেল না। পূর্ণা মাথা নত করে দাঁড়িয়ে রইল অপরাধীর মতো। হেমলতা বারান্দা অবধি এসে আবার ঘুরে তাকালেন। মনটা খচখচ করছে। মনে হচ্ছে, ঘাপলা আছে। নাকি তার সন্দেহবাতিক মনের ভুল ভাবনা? কে জানে!\n\n.\n\nরাতে পদ্মজা খেতে চাইল না। বিকেলের ঘটে যাওয়া ঘটনা তাকে ঘোরে রেখেছে। চিঠিটা পড়তে বিন্দুমাত্র ইচ্ছে হচ্ছে না। তবুও কেমন-কেমন একটা অনুভূতি হচ্ছে। অচেনা, অজানা অনুভূতি। পদ্মজার হাব-ভাব হেমলতার বিচক্ষণ দৃষ্টি এড়াতে পারল না, তিনি ঠিকই খেয়াল করেছেন। কিন্তু মেয়েরা স্বয়ং আল্লাহ ছাড়া অন্য সবার থেকে কথা লুকোনোর ক্ষমতা নিয়ে যে জন্মায় তা তো অস্বীকার করা যায় না। যেমন তিনি এই ক্ষমতা ভালো করেই রপ্ত করতে পেরেছেন। পদ্মজাকে জোর করে খাইয়ে দিলেন। কোনো প্রশ্ন করলেন না।\n\nরাতের মধ্যভাগে মোর্শেদ হেমলতাকে জড়িয়ে ধরতে চাইলে হেমলতা এক ঝটকায় সরিয়ে দেন। চাপা স্বরে ক্রোধ নিয়ে বললেন, ‘তোমার বাসন্তীর কী হয়েছে? সে কী তোমাকে ত্যাগ করেছে? সেদিন ফিরে এলে কেন?’\n\nমোর্শেদ চমকালেন, অপ্রস্তুত হয়ে গেলেন যেন। হেমলতা বাসন্তীকে চিনল কী করে? এই নাম তার গোপন অধ্যায়। অবশ্য হেমলতার মতো মহিলা না জানলেই বোধহয় বেমানান লাগত। মোর্শেদ বিব্রত কণ্ঠে বললেন, ‘হে আমারে কী ত্যাগ করব। আমি হেরে ছাইড়া দিছি।’\n\nহেমলতা বাঁকা হাসলেন। অন্ধকারে তা নজরে এলো না মোর্শেদের।\n\n‘বিশ বছরের সংসার এমন আচমকা ভেঙে গেল যে!’\n\nহেমলতার কণ্ঠে ঠাট্টা স্পষ্ট, তবে চাপা দীর্ঘশ্বাস রয়ে গেল গোপনে। মোর্শেদের শরীরের পশম দাঁড়িয়ে পড়ে। এ খবরও হেমলতা জানে? এতকিছু…কীভাবে? হেমলতার চোখের কোণে জল চিকচিক করে উঠেছে, তিনি চাদর গায়ে দিয়ে চলে গেলেন বারান্দায়। রাতে বেশ ঠান্ডা পড়ে মোর্শেদের কোনো কৈফিয়ত তিনি শুনতে চান না। তাই বারান্দার ঘরে এসে বসলেন।\n\nকতদিন পর রাতের আঁধারে বারান্দার ঘরে এসেছেন! বিয়ের এক বছর পরই জানতে পেরেছিলেন, মোর্শেদ তাকে বিয়ে করার ছয় মাস আগে বাসন্তী নামে এক অপরূপ সুন্দরী মেয়েকে বিয়ে করেছেন। স্বামীর ঘর ছাড়া আর পথ ছিল না বলে এত বড়ো সত্য হজম করে নিয়েছিলেন।\n\nবাসন্তীর মা বারনারী। আর একজন বারনারীর মেয়েকে সমাজ কিছুতেই মানবে না। মোর্শেদের বাবা মিয়াফর মোড়ল টাকার বিনিময়ে দেহ বিলিয়ে দেওয়া একজন বারনারীর মেয়েকে ছেলের বউ হিসেবে মানতে আপত্তি করেন। ততদিনে মোর্শেদ বিয়ে করে ফেলেছে, যদিও সে খবর মিয়াফর মোড়ল পাননি। তিনি মোর্শেদের মন ফেরাতে শিক্ষিত এবং ঠান্ডা স্বভাবের হেমলতাকে বেছে নিলেন। কুরবান হলো হেমলতার! তখন কলেজে ওঠার সাত মাস চলছিল! এরপর পড়াটাও আর এগোল না। জীবনের মোড় করুণ- রূপে পালটে গেল।\n\n.\n\nপরদিন সকাল সকাল স্কুলে রওনা হলো দুই বোন। পূর্ণা পথে চিঠিটা পড়ার পরিকল্পনা করেছিল। পদ্মজা হতে দিল না। সেয়ানা দুইটা মেয়ের হাতে কেউ চিঠি দেখে ফেললে? ইজ্জত যাবে। পদ্মজার প্রতি বিরক্তবোধ করছে পূর্ণা। চিঠিটা তার কাছে। পথে নতুন করে পরিকল্পনা করল সে, ক্লাসে বইয়ের চিপায় রেখে চিঠি পড়বে। কিন্তু তাও হলো না। পর পর দুই দিন কেটে গেল। সুযোগ পেলেও পড়তে দিতে চাইত না পদ্মজা, সারাক্ষণ যেন হাতে জান নিয়ে থাকে। এই বুঝি মা এলো! দুই দিন পর পূর্ণা মোক্ষম সুযোগ পেল। প্রান্ত ও প্রেমাকে নিয়ে হেমলতা বাপের বাড়ি গিয়েছেন। যদিও কয়েক মিনিটের পথ, দ্রুতই ফিরবেন।\n\nচিঠি পড়ায় পদ্মজার চেয়ে পূর্ণার আগ্রহ বেশি। সে চিঠি খোলার অপেক্ষায় ছিল। আজ খুলতে গিয়ে মনে হলো, যার চিঠি তার খোলা উচিত এবং আগে তারই পড়া উচিত। তাই পদ্মজার দিকে বাড়িয়ে দিল চিঠিটা I\n\nপদ্মজা চিঠি খুলতে দেরি করছিল বলে পূর্ণা তাড়া দিল, ‘এই আপা, খোলো না। লজ্জা পাচ্ছো কেন? জিনিসটা চিঠি, কারো গায়ের কাপড় না।’\n\nপদ্মজা বিস্মিত নয়নে তাকাল, যেন পূর্ণা কাউকে খুন করার কথা বলেছে। বলল, ‘কীসব বলছিস পূর্ণা?’\n\nআচ্ছা, মাফ চাই। আর বলব না।’\n\nপদ্মজা ভাঁজ করা সাদা কাগজটা মেলে ধরল চোখের সামনে। প্রথমেই বড়ো করে লেখা ‘প্রিয় পদ্ম ফুল’।\n\nপূর্ণা পাশে এসে বসল। চিঠিতে দুজনের পূর্ণ মনোযোগ:\n\nপ্রিয় পদ্ম ফুল,\n\nআমি কীভাবে শুরু করব বুঝতে পারছি না, অনুগ্রহ করে এই চিঠিটি একবার পড়ো। জানো পদ্ম, হঠাৎ করে নিজেকে চিনতে পারছি না। আমার হৃদয়-মস্তিষ্ক যেন অন্য কেউ নিয়ন্ত্রণ করছে। আজ চলে যাব ভাবতেই বুকের ভেতর তোলপাড় হয়ে যাচ্ছে। তার কারণ—তুমি। যেদিন তোমাকে প্রথম দেখি, থমকে গিয়েছিল আমার নিশ্বাস ও কণ্ঠনালী। এতটুকুও মিথ্যে বলিনি। সেদিন শুটিংয়ে সংলাপ বলতে গিয়ে ভুল করেছি বারংবার। না চাইতেও বার বার চোখ ছুটে যাচ্ছিল লাহাড়ি ঘরের দিকে। বুকে থাকা হৃদপিণ্ডটায় শিরশিরে অনুভূতি শুরু হয় সেই প্রথম দেখা থেকেই। তোমাকে দ্বিতীয় বার দেখার আশায় প্রতিটা ক্ষণ গুণেছি। দ্বিতীয় বার দেখা পাই যখন বেগুন নিতে আসো। সেদিন কথা বলার লোভ সামলাতে পারিনি। টমেটোর অজুহাতে শ্রবণ করি পদ্ম ফুলের কণ্ঠ। মনে হচ্ছিল, এমন রিনরিনে গলার স্বর এই ইহজীবনে আর কখনো শুনিনি। রাতের ঘুম আড়ি করে বসে। তোমায় প্রতিনিয়ত দেখার একমাত্র পন্থা তোমার স্কুল। সবার অগোচরে কতবার তোমার পিছু নিয়েছি। তুমি বোকা, ধরতে পারোনি একবারও। সুন্দরীরা বোকা হয় আবার প্রমাণ হলো। এই, বোকা বলেছি বলে রাগ কোরো না যেন।\n\nএরই মধ্যে জানতে পারি, তোমার মায়ের ইচ্ছে তুমি অনেক পড়বে। তোমার জন্য অনেক উঁচু বংশ থেকে বিয়ের প্রস্তাব এসেছে। তাও তিনি ফিরিয়ে দিয়েছেন। সেখানে আমি অতি সামান্য, অযোগ্য পাত্র। তবুও সাহস করে তোমার বাবার কাছে বিয়ের প্রস্তাব দিয়েছি। পদ্ম ফুলটাকে যে আমার চাই। তিনি রাজি হয়নি। সিনেমায় অভিনয় করা নায়কের সঙ্গে আত্মীয়তা নাকি করবেন না। এটাও বললেন, তোমার অনেক পড়া বাকি। তোমার মা কিছুতেই রাজি হবেন না। আহত মনে দু-পা পিছিয়ে আসি। ভেবেছি, তোমার কলেজ পড়া শেষ হলে পরিবার সঙ্গে করে বিয়ের প্রস্তাব নিয়ে আসব। তোমার মা সম্পর্কে যা জেনেছি- বুঝেছি, তাতে এতটুকু বিশ্বাস আছে, তিনি অভিনেতা বলে আমাকে এড়াবেন না। তিনি বিচক্ষণ মানুষ।\n\nসময় নেই আর। যা এতদিন বলতে চেয়েছি কিন্তু সুযোগ পাইনি আজ বলতে চাই—আমি তোমায় ভালোবাসি পদ্ম ফুল। আমার ভালোবাসা বর্ণনা করার জন্য শব্দগুলো কম হতে পারে তবুও আমি বলছি, যদি আমি আকাশ হই তুমি সেই সূর্যের রশ্মি, যে রশ্মি থেকে নতুন করে আলোকিত হয়েছি আমি।\n\nইতি\n\nলিখন শাহ্\n\n> পদ্মজার মিশ্র অনুভূতি হচ্ছে। পূর্ণা হাসছে। ভ্রু উঁচিয়ে পদ্মজাকে বলল, ‘আপা রে, লিখন ভাইয়ার সঙ্গে তোমাকে যা মানাবে! কী সুন্দর করে লিখেছে।’\n\nপদ্মজা লজ্জায় চোখ তুলতে পারছে না। পূর্ণা বলল, ‘আল্লাহ! একদম বিয়ের প্রস্তাব দিয়ে দিয়েছে! আপা, তুমি কিন্তু বিয়ে করলে লিখন ভাইয়াকেই করবে।’\n\n‘আর কিছু বলিস না।’ পদ্মজা মিনমিনে গলায় বলল।\n\nপূর্ণা শুনল না। সে অনবরত কথা বলে যাচ্ছে, ‘আমার ভাবতেই কী যে খুশি লাগছে আপা। নায়ক লিখন শাহ আমার বোনের প্রেমে হাবুডুবু খাচ্ছে! একদিন বিয়ে হবে।’\n\n‘চুপ কর না।’\n\n‘এই আপা, লিখন ভাইয়াকে ফেরত চিঠি দিবে না?’\n\nপদ্মজা চোখ বড়ো করে তাকাল। অবাক স্বরে বলল, ‘কীভাবে? ঠিকানা কোথায় পাব? আর আম্মা জানলে? না, না।’\n\nপূর্ণা আর কিছু বলতে পারল না। হেমলতার উপস্তিতি টের পেয়ে চুপ হয়ে গেল। পদ্মজা দ্রুত চিঠিটা ভাঁজ করে বালিশের তলায় রাখল…\n\n…বুক ধুকপুক করছে।','\n',char(10)),10,'published',0,'2026-10-06T08:07:08.462Z','2026-10-06T08:07:08.462Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('fffbc5bb-8826-418c-9e55-caee1c51261a','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 11',replace('মাঘ মাস চলছে। কেটে গেছে চার মাস। শুষ্ক চেহারা আর হিমশীতল মন নিয়ে পদ্মজা বসে আছে নদীর ঘাটে, গুনে গুনে তিন নম্বর সিঁড়িতে। নাকের ডগায় মেট্রিক পরীক্ষা, দিনরাত পড়তে হচ্ছে। সে নিয়ম করে প্রতিদিন ভোরে পড়া শেষ করে ঘাটে এসে বসে, নিজের অনুভূতিদের সঙ্গে বোঝাপড়া করার জন্য। কখনো উদাস হয়ে আবার কখনো লাজুক মুখশ্রী নিয়ে ভাবে কারো কথা। সেই যে চিঠি দিয়ে হারাল, আর সাক্ষাৎ মিলল না তার। কখনো কি মিলবে? তিনি কি আসবেন? এক চিঠি প্রতিদিন নিয়ম করে পড়ে পদ্মজা। ধীরে ধীরে অনুভব করে তার মধ্যে আছে অন্য আরেক সত্তা…যে সত্তা প্রতিটি মেয়ের অন্তঃসালের গভীরে জেঁকে বসে থাকে ভালোবাসার অনুভূতি নিয়ে। পূর্ণা শীতের চাদর মুড়ি দিয়ে পদ্মজাকে খুঁজছে। দুই দিন আগে তার অষ্টম শ্রেণির চূড়ান্ত পরীক্ষা শেষ হয়েছে। হিমেল হাওয়ার হাড় কাঁপানো শীতে থেমে থেমে কাঁপছে সে।\n\nপদ্মজাকে ঘাটে বসে থাকতে দেখে পেছন থেকে ডাকল, ‘আপা?’\n\nপদ্মজা তাকাল। বলল, ‘কী?’ পরপরই উৎকণ্ঠা নিয়ে বলল, ‘আম্মা আবার অসুস্থ হয়ে পড়েছে?’\n\nপূর্ণা পদ্মজার পাশ ঘেঁষে বলল, ‘না, আম্মার কিছু হয়নি।’\n\nপদ্মজা হাঁফ ছেড়ে বলল, ‘আম্মা সারাদিন সেলাই কাজ করে। একদিকে তাকিয়ে থাকে, এক জায়গায় বসে থাকে। এজন্যই শরীরে এত অশান্তি। দুর্বল হয়ে পড়েছে। আব্বাকে বলিস, আম্মারে নিয়ে সদরে যেতে। আমার কথা তো শুনবে না।\n\n‘আচ্ছা।’\n\nদুজন নদীর ওপারে তাকাল। অতিথি পাখির মেলা সেখানে। রোমাঞ্চকর আকর্ষণ। এত পাখি দেখে মন ভরে গেল। পাখিদের কলকাকলিতে এলাকা মুখরিত। এপার থেকেও শোনা যাচ্ছে। কোত্থেকে দৌড়ে আসে প্রান্ত। সে চার মাসে শুদ্ধ ভাষা রপ্ত করে নিয়েছে ভালোভাবে। এসেই বলল, ‘আপারা, কী করো?’\n\nপূর্ণা বলল, ‘পাখি দেখি। আয়, তুইও দেখ।’\n\nপ্রান্ত দূরে চোখ রাখল। সকালের ঘন কুয়াশার ধবল চাদরে ঢাকা নদীর ওপার। পাখিদের ভালো করে চোখে ভাসছে না। শীতের দাপটে প্রকৃতি নীরব। তাই পাখির কলকাকলি শোনা যাচ্ছে দারুণভাবে। প্রান্ত বলল, ‘বড়ো আপা, একটা ধরে আনি?’\n\n‘একদম না। পাখি ধরা ভালো না। অতিথি পাখিদের তো ভুলেও ধরা উচিত না। ওরা আমাদের দেশে অতিথি হয়ে এসেছে।’\n\nপ্রান্ত চুপসে গেল। ঠোঁট উলটে বলল, ‘আচ্ছা।’\n\n‘তোরা এইহানে কী করস?’\n\nমোর্শেদের কণ্ঠস্বর শুনে তিনজন ঘুরে তাকাল। প্রান্ত হাসিমুখে ছুটে এসে বলল, ‘আব্বা, আমি আজ তোমার সঙ্গে মাছ ধরতে যাব।’\n\nমোর্শেদ প্রান্তকে কোলে তুলে নিয়ে বললেন, ‘তোর মায় আমার লগে কাইজ্জা করব।’\n\n‘আম্মাকে আমি বলব।’\n\n‘আইচ্ছা যা, তুই রাজি করাইতে পারলে লইয়া যামু।’\n\nমোর্শেদ গত দুই মাস ধরে প্রান্তকে চোখে চোখে রাখছেন। ছেলে নেই বলেই হয়তো! প্রতিটা বাবা-মায়েরই একটি ছেলের আশা থাকে।\n\nহেমলতা পর পর তিনটা মেয়ে জন্ম দিলেন। এ নিয়ে মোর্শেদ কখনো অভিযোগ করেননি। তবে মনে মনে খুব করে একটা ছেলে চাইতেন। প্রান্তকে যখন প্রথম আনা হলো, ভিক্ষুকের ছেলে বলে তার খুব রাগ হয়। সময়ের সঙ্গে সঙ্গে প্রান্তকে চোখের সামনে ঝাঁপাতে-লাফাতে দেখে ছেলের জন্য রাখা মনের শূন্যস্থানটা নাড়া দিয়ে ওঠে। মোর্শেদ দুই হাত বাড়িয়ে দেন অনাথ ছেলেটির দিকে। এখন দেখে আর বোঝার উপায় নেই, মোর্শেদ আর প্রান্তের মধ্যে রক্তের কোনো সম্পর্ক নেই। মোর্শেদ কাঠখোট্টা গলায় দুই মেয়েকে বললেন, ‘সদরে যাইয়াম। তোদের দুজনের লাইগা চাদর আনতাম না সুইডার?’\n\nকথাটি শুনে পদ্মজা দারুণভাবে চমকাল। অনাকাঙ্ক্ষিত কিছু পেলে মানুষ কিছুক্ষণের জন্য স্তব্ধ হয়ে যায়। পদ্মজার অবস্থাও তাই হলো। খুশি প্রকাশ করার মতো পথ খুঁজে পাচ্ছে না, স্নায়ু কোষ থমকে গেছে। শীতের তাণ্ডবে প্রকৃতি বিবর্ণ, অথচ তার মনে হচ্ছে, বসন্তকাল চলছে। ঢোক গিলে ঝটপট উত্তর দিল, ‘আব্বা, তোমার যা পছন্দ তাই এনো।’\n\nখুশিতে পদ্মজার গলা কাঁপছে। মোর্শেদ অনুভব করলেন সেই কাঁপা গলা। গত সপ্তাহের ঘটনা, মধ্যরাতে রমিজের মেয়ে এক ছেলের সঙ্গে ধরা পড়ে। অলন্দপুরে সে কী তুলকালাম তাণ্ডব! ছেলেটিকে ন্যাড়া করে জুতার মালা পরিয়ে পুরো অলন্দপুর ঘুরানো হয়েছে। আর মেয়ের পরিবারকে মাতব্বর সমাজ থেকে বিচ্যুত করেছেন। পদ্মজা অপূর্ব সুন্দর হওয়া সত্ত্বেও আজও কোনো চারিত্রিক দোষ কেউ দিতে পারেনি। মেয়েটার দ্বারা কোনো অনৈতিক কাজ হয়নি। তার ঘরে যেন সত্যি একটা পদ্মফুলের বাস! ইদানীং মোর্শেদ পদ্মজাকে নিয়ে দোটানায় ভোগেন। খারাপ ব্যবহারটা আগের মতো আসে না। তিনি দ্রুত জায়গা ছেড়ে চলে যান।\n\nসকাল সকাল কলস ভরে খেজুরের মিষ্টি রস নিয়ে এলেন মোর্শেদ প্রেমা খেজুরের রস দেখেই বলল, ‘আম্মা, পায়েস খাব।\n\nহেমলতা সমর্থন করলেন, ‘আচ্ছা, খাবি।’\n\nসূর্য অনেক দেরিতে উঠল। প্রকৃতির ওপর সূর্যের নির্মল আলো ছড়িয়ে পড়েছে। আলোতে তেজ নেই। চার ভাই-বোন কাঁচা খেজুরের রস নিয়ে উঠানে বসল পাটি বিছিয়ে। খেজুরের কাঁচা রস রোদে বসে খাওয়াটাই যেন একটা আলাদা স্বাদ, আলাদা আনন্দের। পায়েসের জন্য তো নারিকেল দরকার তাই মোর্শেদ নারিকেল গাছে উঠেছেন।\n\nআচমকা পদ্মজা প্রশ্ন করল, ‘আজ কী সোমবার?’\n\nপূর্ণা কথা বলার পূর্বে হেমলতা বারান্দা থেকে বললেন, ‘আজ তো সোমবারই। কেন?’\n\nপদ্মজা খেজুরের বাটি রেখে ছুটে যায় বারান্দায়।\n\n‘আজ স্কুলে যাওয়ার কথা ছিল আম্মা। ঝুমা ম্যাডাম বলেছিলেন, গুরুত্বপূর্ণ কথা আছে। সবাইকে যেতে বলেছেন।’\n\n‘আমায় বলে রাখতি। সামনে পরীক্ষা। গুরুত্বপূর্ণ দেখে পড়া দিবে বোধহয়, এজন্যই ডেকেছে। তাড়াতাড়ি যা। এই পূর্ণা, তুইও যা।’\n\nদুই বোন তাড়াহুড়ো করে বাড়ি থেকে দ্রুত বের হয়। সূর্য উঠলেও কনকনে শীতটা রয়ে গেছে। দুজনের গায়ে মোর্শেদের আনা নতুন সোয়েটার। পদ্মজা যখন মোর্শেদের হাত থেকে সোয়েটার পেল তখন আর আবেগ লুকিয়ে রাখতে পারেনি। মোর্শেদের সামনেই হাউমাউ কেঁদে দিল! তার কান্না মোর্শেদের হৃদয় স্পর্শ করে। কিন্তু মোর্শেদ নিজের অহংবোধের তাড়নায় দুর্বলতা প্রকাশ করেন না, পরিস্থিতি থেকে বাঁচতে বাড়ি থেকে বেরিয়ে যান, ফেরেন অনেক রাতে। পূর্ণা হাঁটার মাঝে বলল, ‘আব্বার পছন্দ ভালো তাই না আপা?’\n\n‘কীসের পছন্দ?’\n\n‘সোয়েটারগুলো কী সুন্দর।’\n\nধান\n\nপদ্মজা হাসতেই সামনের দাঁতগুলো ঝিলিক দিল। হাতের ডান পাশে ধানখেত। ধান গাছের ডগায় থাকা বিন্দু বিন্দু জমে থাকা শিশির রোদের আলোয় ঝিকমিক করছে। অনেকে হাতে কাঁচি নিয়ে প্রস্তুতি নিচ্ছে ধ কাটার। বাতাসে নতুন ধানের গন্ধ। হঠাৎ পূর্ণা চেঁচিয়ে উঠল, ‘আপারে, লিখন ভাই।’\n\nপদ্মজার নিশ্বাস এলোমেলো হয়ে পড়ে। মুহূর্তে বুকের মাঝে তাণ্ডব শুরু হয়। পূর্ণার দৃষ্টি অনুসরণ করে পেছনে তাকাল সে। লিখন ব্যস্ত পায়ে এদিকেই আসছে। তার পাশে চার ফুট উচ্চতার মগা।\n\nপদ্মজা অজানা আশঙ্কায় চোখ ফিরিয়ে নিলো। রুদ্ধশ্বাসে পূর্ণাকে বলল, ‘এখানে আর এক মুহূর্তও না।\n\nকথা শেষ করেই সে স্কুলের দিকে হাঁটা শুরু করে। পূর্ণা অবাক হয়। কিন্তু, এ নিয়ে রা করল না। লিখন পেছন পেছন আসছে। পদ্মজার বুক কাঁপছে বিরতিহীন ভাবে। তার চাহনি বিক্ষিপ্ত, হৃদয় অশান্ত।\n\n','\n',char(10)),11,'published',0,'2026-10-06T08:08:57.495Z','2026-10-06T08:08:57.495Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('02ce425c-3c4a-4928-b59b-652fa67c48bd','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 12',replace('বট গাছের সামনে চিন্তিত ভঙ্গিতে দাঁড়িয়ে আছে লিখন। শীতের শুষ্কতায় বটগাছের অধিকাংশ পাতা ঝরে পড়েছে। লিখনের কাছে শীতকাল খুবই অপছন্দের ঋতু। শীত চরম শুষ্কতার রূপ নিয়ে প্রকৃতির ওপর জেঁকে বসে থাকে যা সহ্য হয় না লিখনের। ঠান্ডা লেগেই থাকে। ছোটো থেকে কয়েকবার নিউমোনিয়ায় ভুগেছে। সে মনেপ্রাণে বিশ্বাস করে রুক্ষতা, তিক্ততা ও বিষাদের প্রতিমূর্তি শীতকাল।\n\nলিখন এক হাতের তালু দিয়ে আরেক হাতের তালু ঘষে উত্তপ্ততা সৃষ্টি করে। ভীষণ ঠান্ডা লাগছে। তখন পদ্মজা এত দ্রুত হাঁটছিল যে মনে হচ্ছিল, সে পালাতে চাইছে। লিখন আর এগোয়নি। পালাতে দিল পদ্মজাকে। মগা বলেছে, পদ্মজার লোকসমাজের ভয় খুব। তাই লিখন এই নির্জন মাঠের পাশে বটগাছের নিচে দাঁড়িয়ে আছে। পদ্মজা এ পথ দিয়েই বাড়ি ফিরবে। তখন যদি একটু কথা বলা যায়।\n\nপদ্মজা জড়োসড়ো হয়ে হাঁটছে। ভয়ে ঠোঁট শুকিয়ে কাঠ। বার বার জিহবা দিয়ে ঠোঁট ভিজিয়ে নিচ্ছে।\n\nপদ্মজা মিনমিনে গলায় পূর্ণাকে ডাকল, ‘পূর্ণা রে…’\n\nপূর্ণা তাকাল। পদ্মজা এদিক-ওদিক তাকিয়ে বলল, ‘আমার ভয় হচ্ছে। উনি মাঝপথে দাঁড়িয়ে নেই তো?’\n\nপূর্ণা চরম বিরক্তি নিয়ে বলল, ‘থাকলে কী হয়েছে? খেয়ে ফেলবে?’\n\nপদ্মজা আর কথা বলল না। পূর্ণার সঙ্গে কথা বলে লাভ নেই। তখন লিখন শাহকে পাত্তা না দেয়ার জন্য পূর্ণার খুব রাগ হয়েছে। পদ্মজা বরাবরই মাথা নিচু করে হাঁটে। তাই লিখন শাহকে দেখতে পেল না। পূর্ণা দূর থেকে দেখতে পায়। কিন্তু এইবার আর পদ্মজাকে আগে থেকে বলল না। সে উত্তেজিত হয়ে ভাবছে, লিখন শাহ্ যখন আপার সামনে এসে দাঁড়াবে কী যে হবে!\n\n.\n\nলিখন-পদ্মজার দূরত্ব মাত্র কয়েক হাত…তখন পদ্মজা আবিষ্কার করল লিখনের উপস্থিতি। সে দ্রুত ওড়নার ঘোমটা চোখ অবধি টেনে নিলো। ভয়ে- লজ্জায় তার সর্বাঙ্গে কাঁপন ধরে গেছে। লিখনের পাশ কাটার সময় পুরুষালি কণ্ঠটি ডেকে উঠল, ‘পদ্ম।’\n\nপদ্মজা দাঁড়াতে চায়নি। তবুও কেন যেন দাঁড়িয়ে গেল। লিখন দুয়েক পা এগিয়ে আসে। পূর্ণা ঠোঁট টিপে সেই দৃশ্য গিলছে। লিখন উসখুস করতে শুরু করে, কথা গুলিয়ে ফেলেছে। পদ্মজা লিখনকে পেছনে ফেলে সামনে এগিয়ে যায়। লিখন হতভম্ব হয়ে অবাক চোখে শুধু চেয়ে রইল।\n\nপূর্ণা বলল, ‘আমাকে বলুন, আমি বলে দেব।’\n\nলিখন পকেট থেকে একটা চিঠি বের করে অনুরোধ স্বরে বলল, দয়া করে, তোমার বোনকে দিয়ো। আমি কাল বিকেলে ঢাকা চলে যাব।’\n\nপূর্ণা হাসিমুখে চিঠিটি হাতে নিয়ে বলল, ‘আপা আপনার আগের চিঠিটা প্রতিদিন পড়ে।’\n\nকথাটি শুনে লিখনের ঠোঁটে হাসি ফুটে উঠে। পূর্ণা চিঠি নিয়ে দৌড়ে ছুটে যায় পদ্মজার দিকে। লিখন আর পিছু নিলো না। পূর্ণা আসতেই পদ্মজা ধমকে উঠল, ‘কী কথা বলছিলি এত? কেউ দেখলে কী হতো? তুই আম্মার কথা কেন ভাবছিস না?’\n\nপদ্মজার কাঁদো-কাঁদো স্বরে পূর্ণা চুপসে গেল। সত্যি কী সে বেশি করে ফেলল? পূর্ণা আশপাশে তাকিয়ে দেখে, কেউ আছে নাকি। সত্যি কেউ দেখে থাকলে কেলেঙ্কারি হয়ে যাবে। পূর্ণা চোখ নামিয়ে চুপচাপ হেঁটে বাড়ি চলে আসে। হঠাৎ সৃষ্টি আতঙ্কের কারণে চিঠির কথা আর পদ্মজাকে বলা হয়ে উঠে না।\n\n.\n\nগোধূলি বিকেল। হেমলতা পদ্মজাকে ফরমায়েশ দেন, ‘পদ্ম, কয়টা টমেটো নিয়ে আয়।\n\n‘আচ্ছা, আম্মা।’\n\nপদ্মজা লাহাড়ি ঘরের ডান দিকে যায়। দুমাস আগে মোর্শেদ এদিকের সব ঝোপজঙ্গল সাফ করে টমেটোর ছোটোখাটো খেত করেছেন। লাল টকটকে টমেটো। হেমলতা রান্নার ফাঁকে বারান্দার দিকে উঁকি দিলেন। মোর্শেদ আর প্রান্ত কিছু নিয়ে বৈঠক করছেন।\n\nহেমলতা ফোঁস করে নিশ্বাস ছাড়লেন। বাসন্তী নামক মানুষটিকে কী কারণে ত্যাগ করলেন মোর্শেদ? জানতে ইচ্ছে করলেও হেমলতা এই বিষয়ে কোনো প্রশ্ন করলেন না। তবু এতটুকু বুঝেছেন মোর্শেদের বাইরের ঘোর কেটে গেছে, যার ফলস্বরূপ সংসারে তার মন পড়েছে। হেমলতাকে খুব সমীহ করে চলেন। তবে হেমলতা জানেন, মোর্শেদ পদ্মজাকে নিজের মেয়ে হিসেবে এখনো মেনে নেননি। তা নিয়ে মাঝেমধ্যেই খোঁচা দেন। এত অবিশ্বাস মানুষটার!\n\nপদ্মজা সাবধানে খেতের মধ্যখানে গেল। টমেটো ছিঁড়তে গিয়ে মনে পড়ে গেল তার লিখনের কথা। মনে মনে ভাবল, কেন এসেছেন উনি? কী-ই বা বলতে চেয়েছিলেন?\n\nজানার জন্য ব্যকুল হয়ে হয়ে ওঠে পদ্মজার মনটা 1\n\n‘আপা, একটা কথা বলি?’\n\nপদ্মজা চমকে পেছনে তাকাল, হঠাৎ পূর্ণার আগমনে ভয় পেয়েছে। বুকে ফুঁ দিয়ে বলল, ‘বল।’\n\nরাগ করবে না তো?’\n\nপদ্মজা চোখ ছোটো ছোটো করে তাকাল। বলল, ‘করব না।’\n\nপূর্ণা লিখনের দেয়া চিঠিটি দেখিয়ে বলল, ‘লিখন ভাইয়ার চিঠি।’\n\nপদ্মজা ছোঁ মেরে চিঠিটি নিলো। তার এহেন ব্যবহারে পূর্ণা অবাক হলো বটে, সেই সঙ্গে মনে মনে খুশি হলো বোনের আকুলতা দেখে। পদ্মজা দ্রুত চিঠির ভাঁজ খুলল। পূর্ণা বাড়ির দিকে তাকিয়ে দেখছে, কেউ আসছে নাকি পদ্মজা পড়া শুরু করল।\n\nপ্রিয় পদ্ম ফুল,\n\nচার মাস কেটে গেল। চার মাসে একটুও অবসর মেলেনি। কিন্তু মনে ছিল এক আকাশ ছটফটানি। তোমার মনের কথা তো জানাই হলো না। তোমাদের অলন্দপুরের প্রায় প্রতিটি বাড়ির ছেলের স্বপ্ন তোমাকে ঘরে তোলার। তাই সারাক্ষণ ভয়ে ছিলাম। আমার অনুপস্থিতিতে কেউ তুলে নেয়নি তো! তিন দিনের সময় নিয়ে চলে এসেছি। শুধু একবার দেখতে আর জানতে, তুমি কি আমার জন্য অপেক্ষা করবে? মেট্রিক পরীক্ষা অবধি অপেক্ষা করলেই হবে। এরপর আমি মা আর বাবাকে নিয়ে তোমার মায়ের কাছে আসব। উনার কাছে অনুরোধ করব, তোমার পড়া শেষ হলে যেন আমার সঙ্গেই বিয়ে দেন। উনি কথা দিলে অনেকটা নিশ্চিন্ত হতে পারব। এখন অনিশ্চয়তায় ভুগছি। আমি গুছিয়ে লিখতে পারছি না আজ। কয়েকটা চিঠি লিখেছি। একটাও মনমতো হয়নি। অনুগ্রহ করে তুমি মানিয়ে নিয়ো। ভুলত্রুটি মার্জনা কোরো।\n\nইতি\nলিখন শাহ্\n\n- বাড়ির সবাই ঘুমে। পদ্মজা চুপিচুপি উঠে বসে পড়ার টেবিলে। রাত অনেক, গাছের পাতায় নিশ্চয় শিশির বিন্দু জমছে। এরপর ভোররাতে টিনের চালে শিশিরকণা বড়ো বড়ো ফোঁটায় বৃষ্টির মতো ঝরবে। গাঁ হিম করা ঠান্ডা, তা উপেক্ষা করে পদ্মজা হাতে কলম তুলে নিলো। সাদা কাগজে লিখল, অপেক্ষা করব। এরপর কাগজটা ভাঁজ করে বালিশের তলায় রেখে শুয়ে পড়ল।\n\nফজরের নামাজ আদায় করে চার ভাইবোন পড়তে বসে। পড়ায় মন টিকছে না পদ্মজার। বই আনার ছুতোয় পদ্মজা ঘরের ভেতর চলে গেল। রাতের লেখা কাগজটা ছিঁড়ে কুটিকুটি করে ফেলে দিল জানালার বাইরে। এরপর আবার নতুন করে লিখল: আমার আম্মা যা চান তাই হবে।\n\nপড়াশেষে অভ্যাসবশত ঘাটে যায় পদ্মজা। হাতের মুঠোয় তিনটে চিঠি—দুটো লিখনের, একটা তার লেখা। পূর্ণাও পাশে। প্রেমা- প্ৰান্ত বাড়িজুড়ে ছুটাছুটি করছে। সামনের কোনোকিছু ঠিকমতো দেখা যাচ্ছে না। সবকিছুই অস্পষ্ট। কুয়াশার স্তর এত ঘন যে, দেখে মনে হচ্ছে সামনে কুয়াশার পাহাড় দাঁড়িয়ে আছে। সেই পাহাড় ভেদ করে একটা নৌকা এসে ঘাটে ভেরে। নৌকায় লিখন আর মগা। আকস্মিক ঘটনায় পিলে চমকে উঠল পদ্মজার। পালানোর মতো শক্তিটুকু পেল না।\n\nলিখন মায়াভরা কণ্ঠে পদ্মজার উদ্দেশ্যে বলল, ‘আমি বাধ্য হয়ে এসেছি। আজ বিকেলে চলে যাব। মগা বলল, প্রতিদিন সকালে নাকি তুমি ঘাটে বসো। তাই এসেছি।’\n\nপদ্মজা মনে মনে দোয়া ইউনুস পড়ছে। ভয়ে বুক দুরুদুরু করছে। মা দেখে ফেললে কী হবে? বা অন্য কেউ? একটু সাহস জড়ো হতেই নিজের লেখা চিঠি সিঁড়িতে রেখে পদ্মজা ছুটে চলে গেল বাড়ির ভেতর। পূর্ণা বড়ো বড়ো চোখে শুধু দেখল। লিখন নৌকা থেকে নেমে চিঠিটা হাতে তুলে নেয়। ভাঁজ খুলে একটা লাইন পেল শুধু। বিষাদের ছায়া নেমে আসে লিখনের মুখে।\n\nপূর্ণার কৌতূহল হলো চিঠিতে কী আছে জানার জন্য। তবে তা প্রকাশ বল না। শুধু বলল, ‘আপা আপনার কথা প্রতিদিন ভাবে।’\n\n.\n\n১৯৯৬ সাল। পদ্মজা থেমে থেমে কাঁপছে। মুখ লুকিয়ে রেখেছে হাঁটুর ওপর। তুষার কালো চাদর টেনে দিল তার গায়ে। পদ্মজা চোখ তুলে তাকাল। বিষাদভরা কণ্ঠে বলল, ‘সেদিন আমার লেখা প্রথম চিঠিটা কুটিকুটি কেন করেছি জানি না। ইচ্ছে হয়েছিল তাই করেছি। তবে জানেন, আমি একদম ঠিক করেছিলাম। সেদিন যদি আমি কথা দিয়ে দিতাম। আমার কথা ভঙ্গ হতো।’\n\nপদ্মজা হাসল। তুষার একদৃষ্টিতে তাকিয়ে রইল পদ্মজার দিকে।\n\nবলল, ‘লিখনের সঙ্গে আর দেখা হয়নি?’\n\nপদ্মজা হাতের কাটা জায়গায় ফুঁ দিয়ে বলল, ‘হয়েছিল।’\n\n‘তাহলে কথা ভঙ্গ হতো কেন বললেন?’\n\nতুষারের দিকে তাকাল পদ্মজা, এরপর হাঁটুতে মুখ লুকালো। এক মিনিট, দুই মিনিট, তিন মিনিট করে…কেটে গেল দশ মিনিট। পদ্মজার সাড়া নেই। তুষার ডাকল, ‘পদ্মজা? শুনতে পাচ্ছেন?’\n\n‘পাচ্ছি।’\n\n‘আপনার কী কষ্ট হচ্ছে?’\n\n‘হচ্ছে।’\n\n‘মুখ তুলে তাকান।’\n\nপদ্মজা ছলছল চোখে তাকাল। তুষার উদ্বিগ্ন হয়ে বলল, ‘কোনো সমস্যা হচ্ছে?’\n\nতুষারের প্রশ্ন অগ্রাহ্য করে পদ্মজা ভেজা কণ্ঠে বলল, ‘আমার আম্মা আমার সঙ্গে বিশ্বাসঘাতকতা কেন করল?’\n\nতুষার ভেতরে ভেতরে চমকাল। হেমলতা নামে মানুষটার সম্পর্কে যা জানে এবং জানল, তাতে তার সঙ্গে বিশ্বাসঘাতকতা শব্দটা যায় না পরপরই নিজেকে সামলে নিলো।\n\nভালো মানুষের খারাপ রূপ—এমন কেইস শত শত আছে।\n\nতুষার সাবধানে প্রশ্ন করল, ‘কী করেছেন তিনি?’\n\nপদ্মজা উত্তর দিল না। মেঝেতে শুয়ে চোখ বুজল। তুষার গোপনে দীর্ঘশ্বাস ছাড়ল। পদ্মজা এখন আর কিছু বলবে না, সে ক্লান্ত; অতীত হাতড়াতে গিয়ে মনের অসুস্থতা বেড়ে গেছে। তুষার তাকাল মেয়েটার মুখের দিকে। আঁচল সরে গেছে তার বুকের ওপর থেকে, চাদরের অংশ পড়ে আছে মেঝেতে। তুষার চাদরটা টেনে দিতে গিয়ে আবিষ্কার করল, পদ্মজার গলায় কালো-খয়েরি মিশ্রণে কয়টা দাগ। কেউ শক্ত হাতে চেপে ধরেছিল গলা! হুংকার ছাড়ল সে, ‘ফাহিমা?’\n\nফাহিমা কাছেই ছিল, তাই ছুটে এলো। তুষার বলল, আপনি আসামির গলা টিপে ধরেছেন?’\n\nফাহিমা চট করে বলল, ‘না, স্যার। প্রথম থেকেই গলায় দাগগুলো দেখছি। প্রশ্নও করেছি। মেয়েটা উত্তর দিল না।’\n\nকপাল ভাঁজ করে ফেলল তুষার। হাজারটা প্রশ্ন মাথায় ভনভন করছে, মস্তিষ্ক শূন্য প্রায়। পদ্মজা যতটুকু বলেছে, তার পরের সাত বছরের কাহিনি জানা পর্যন্ত শান্তি মিলবে না। মাথা কাজ না করলে তুষার সিগারেট টানে। তাই সে বেরিয়ে গেল।','\n',char(10)),12,'published',0,'2026-10-06T08:12:06.886Z','2026-10-06T08:12:06.886Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('a6ce0c60-636d-4cf0-a4c7-ad62f7f53809','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 13',replace('বাড়ির গিন্নির মতো কোমরে ওড়নার আঁচল গুঁজে রান্নাবান্না করছে পদ্মজা। হেমলতার কোমরে ব্যথা। তিনি রান্না করতে চাইলেও পদ্মজা রাঁধতে দিল না। মোর্শেদও বললেন, ‘বেদনা লইয়া রান্ধা লাগব না। তোমার মাইয়া যহন রানতে পারে তে হেই রান্ধক।’\n\nশেষ অবধি হেমলতা হার মানলেন। পদ্মজা মাটির চুলায় মুরগি গোশত রান্না করছে। খড়ি বা লাকড়ি হিসেবে আছে বাঁশের মুড়ো। আগুনের শিখার রং নীলচে। শীতের মাঝে রান্নার করার শান্তি আলাদা। মুরগি গোশত রান্না হওয়ার কারণ—আজ এতিম-মিসকিন খাওয়ানো হবে। হেমলতা বলেন, সামর্থ্য থাকলে মাসে একবার হলেও এতিম-মিসকিনদের খাওয়ানো উচিত, নয়তো ঘরে রহমত থাকে না। রান্না শেষ করে পদ্মজা হেমলতার কাছে এলো। বলল, ‘আম্মা রান্না শেষ।’\n\nহেমলতা দৌর্বল্যমাখা কণ্ঠে বললেন, ‘তোর আব্বারে গিয়ে বল—আলী, মুমিন, আর ময়নাকে নিয়ে আসতে।’\n\nপদ্মজা কিছু না বলে মাথা নিচু করে ফেলল। মোর্শেদের সঙ্গে আগবাড়িয়ে কথা বলতে তার ভয় হয়। অনেকদিন বাজে ব্যবহার করেন না। হুট করে যদি করে ফেলেন তো খুব কষ্ট হবে। হেমলতা মৃদু হাসলেন। বললেন, ‘কিছু বলবে না। যা তুই।’\n\nপদ্মজা ধীর কণ্ঠে বলল, ‘সত্যি যাব?’\n\nহেমলতা সামনে-পেছনে মাথা ঝাকিয়ে ইঙ্গিত করলেন যেতে। পদ্মজা মোর্শেদকে উঠানেই পেল, চেয়ারে বসে রোদ পোহাচ্ছেন। পদ্মজা গুটিগুটি পায়ে হেঁটে গেল। আব্বা ডাকতে গিয়ে গলা ধরে আসছে তার। ঢোক গিলে ডাকল, ‘আব্বা?’\n\nমোর্শেদ ঘাড় ঘুরাতেই পদ্মজার মনে হলো বুকে কিছু ধপাস করে পড়ল। পদ্মজা দৃষ্টি অস্থির রেখে মিনমিনে গলায় বলল, ‘আম্মা বলেছে আলীদের নিয়ে আসতে।’\n\n‘রান্ধন শেষ?’\n\n‘জি, আব্বা।’\n\nমোর্শেদ গলায় গামছা বেঁধে বেরিয়ে যান। পদ্মজা মোর্শেদের যাওয়ার পানে তাকিয়ে থাকল বেশ কিছুক্ষণ। অনুভূতিগুলো থমকে গেছে, ঝাপসা হয়ে আসছে পদ্মজার চোখ দুটো। অল্পতেই তার কান্না চলে আসে। সে তাড়াতাড়ি ডান হাতের উলটো পাশ দিয়ে চোখের জল মুছল। গাছ থেকে পাখির কিচিরমিচির শব্দ আসছে। পদ্মজা সেদিকে তাকাল। তখনি হেমলতা ডাকলেন, ‘পদ্ম।’\n\nপদ্মজা ছুটে যায়, ‘কিছু লাগবে আম্মা?’\n\n‘না। পূর্ণারা কোথায় গেল?\n\n‘ঘাটে।’\n\n‘কী করে?’\n\n‘মাছ ধরে।’\n\n‘বড়শি দিয়ে?’\n\n‘জালি দিয়ে।’\n\n‘এত বড়ো মেয়ে নদীতে নেমে জাল দিয়ে মাছ ধরে!’ কী মনে করে যেন আবার মেনে নিলেন, ‘আচ্ছা, থাক। তুই আয়। বস আমার পাশে।’\n\nপদ্মজা হেমলতার পায়ের কাছে বসে পায়ে হাত দিল টিপে দেওয়ার জন্য। হেমলতা পা সরিয়ে নিতে নিতে বললেন, ‘লাগবে না।’ শাড়ির আঁচল দিয়ে পদ্মজার কপালের ঘাম মুছে দিয়ে বললেন, ‘কোমরের ব্যথাটা কমেছে চিন্তা করিস না। তোর আব্বা কিছু বলেছে?’\n\n‘না, আম্মা। আচ্ছা আম্মা, আব্বা এত পালটাল কীভাবে?’ পদ্মজা নিজের আগ্রহ দমে রাখতে পারল না।\n\nহেমলতা মৃদু হাসলেন। উদাস হয়ে টিনের দেয়ালে তাকিয়ে বললেন, ‘শুনেছিলাম তোর বাপ ভালো মানুষ। কিন্তু বিয়ের পর তার ভালোমানুষি ভুলেও দেখিনি। কারণ, তার কানে-মগজে মন্ত্র দেয়ার মানুষ ছিল। অন্যের নিয়ন্ত্রণে ছিল। এখন আর কেউ নিয়ন্ত্রণ করে না তাই পালটাচ্ছে। তোর বাপের ব্যক্তিত্ব নেই। নিজস্ব স্বকীয়তা নাই। অন্যের কথায় নাচে ভালো।’\n\nশেষ কথাটা হেমলতা হেসে বললেন। পদ্মজা কিছু বলল না। হেমলতা শুয়ে পড়লেন। আজ সারাদিন বিশ্রাম নিবেন। আগামীকাল অনেক কাজ। অনেকগুলো কাপড় জমেছে।\n\n‘রূপ ক্ষণিকের, গুণ চিরস্থায়ী। এটা আব্বা শেষ বয়েসে এসে বুঝেছে।’\n\nপদ্মজার শীতল কণ্ঠ এবং কথার তিরে হেমলতা ভীষণভাবে বিস্মিত হলেন। তিনি সেকেন্ড কয়েক কথা বলতে পারলেন না। পদ্মজা চলে যাওয়ার জন্য উঠতেই, হেমলতা অবিশ্বাস্য স্বরে প্রশ্ন ছুঁড়লেন, ‘এই খবর তুই কোথায় পেলি?’\n\nপদ্মজা ঘাড় ঘুরিয়ে বলল, ‘আমি তো তোমারই মেয়ে, আম্মা। তোমার এত বড়ো দুঃখ আমি জানব না?’\n\nপদ্মজা চলে গেল। পেছনে রেখে গেল হেমলতার অবিশ্বাস্য চাহনি।\n\n.\n\nবিকেলবেলা হেমলতা ঘর থেকে বের হলেন। শরীরে কিছুটা আরাম এসেছে। পূর্ণা বরই ভর্তা করছে, পাশে প্রেমা। পদ্মজাকে দেখা গেল না। নিশ্চয়ই ঘাটে বসে আছে। প্রান্তও তো নেই।\n\nতিনি পূর্ণাকে জিজ্ঞাসা করলেন, ‘প্রান্ত কোথায়?’\n\nপূর্ণা কয়েক সেকেন্ড ভাবল কী উত্তর দিবে। এরপর ভয়ার্ত কণ্ঠে বলল, ‘জানি না, আম্মা।’\n\n‘জানিস না কী?’ তিনি এবার প্রেমাকে ধরলেন, ‘প্রান্ত কোথায় রে প্রেমা?’ প্রেমা সহজ স্বরে বলল, ‘আমরা সবাই ঘাটে ছিলাম। প্রান্ত উঠানে ছিল। এরপর এসে দেখি নেই।’\n\nহেমলতা গলা উঁচিয়ে বললেন, ‘কোন মুখে বলছিস জানি না? একসঙ্গে নিয়ে থাকতে পারিস না। একা ছাড়িস কেন? কোথায় গেছে ছেলেটা।’\n\nহেমলতার ধমক ঘাট অবধি পৌঁছে যায়। পদ্মজা বাড়ির পেছন থেকে ছুটে এসে প্রশ্ন করে, ‘কী হয়েছে আম্মা?’\n\n‘প্রান্ত বাড়ি নেই সেটা আমাকে কেউ বলল না! দেখ দুটোকে, বসে বসে বরই ভর্তা গিলছে। দিন দিন অবাধ্য হচ্ছে মেয়েগুলো।’\n\nপূর্ণা ভয়ে জড়োসড়ো হয়ে বসে আছে। প্রেমা হেমলতার ধমকে ভয় পাচ্ছে, কিন্তু অতটা না। হেমলতার মন কু গাইছে।\n\nতিনি নিজ ঘরে যেতে যেতে পদ্মজাকে বললেন, ‘বের হচ্ছি আমি। সাবধানে থাকবি।\n\nতখন দুজন লোক প্রান্তকে নিয়ে বাড়িতে ঢুকল। প্রান্তর কপাল বেয়ে রক্ত ঝরছে। পদ্মজা উদগ্রীব হয়ে হেমলতাকে ডাকল, ‘আম্মা।’ এরপর দৌড়ে গেল উঠানে। প্রান্ত কাঁদছে। হেমলতা ব্যস্ত পায়ে বেরিয়ে আসেন। প্রান্তকে আহত অবস্থায় দেখে ভড়কে যান। বুকটা হাহাকার করে উঠে তার। ছুটে গিয়ে প্রান্তকে দুই হাতে জড়িয়ে ধরে লোক দুটিকে জিজ্ঞাসা করলেন, ‘আমার ছেলের কী হয়েছে?’\n\nএকজন লোক বলল, ‘পলাশ মিয়ার ছেড়ার লগে মাইর লাগছিল। হেই ছেড়ায় পাথথর দিয়া ইডা মারছে কপালে আর ফাইট্টা গেছে।’\n\nমোর্শেদ লাহাড়ি ঘরের সামনে গাছ কাটছিলেন। চেঁচামেচি শুনে চলে আসেন। প্রান্তকে এমতাবস্থায় দেখে লোক দুটিকে তেজ নিয়ে বললেন, ‘কোন কুত্তার বাচ্চায় আমার ছেড়ারে মারছে? কোন বান্দির ছেড়ার এত বড়ো সাহস?’\n\nমোর্শেদ উত্তরের অপেক্ষা করলেন না। প্রান্তকে নিয়ে ছুটে চলে যান বাজারে। হেমলতা রয়ে গেলেন বাড়িতে। বাজারে আজ হাট বসেছে। মোর্শেদ হেমলতাকে নিষেধ করেছেন সঙ্গে যেতে। বাড়িতে থেকে হেমলতা হাঁসফাঁস করছেন। প্রান্ত একা বড়ো হয়েছে। কতবার কতরকম আঘাত পেয়েছে, দেখার কেউ ছিল না; সবসময় মিনমিনিয়ে কেঁদেছে। এমন বাচ্চা ছেলের এত বড়ো আঘাত পেয়ে চেঁচিয়ে কাঁদার কথা। কষ্ট তো আর কম পায়নি! দাঁতে দাঁত চেপে সহ্য করেছে। হেমলতার ভীষণ কষ্ট হচ্ছে। পদ্মজা ঘরে লুকিয়ে কাঁদছে। পূর্ণা-প্রেমা বাড়ির বাইরে বার বার উঁকি দিয়ে দেখছে, তাদের আব্বা প্রান্তকে নিয়ে ফিরল কি না!\n\n.\n\nদেখতে দেখতে চলে এসেছে মেট্রিক পরীক্ষা। কেন্দ্র শহরে, যেতে লাগে ছয় ঘণ্টা। বাড়িতে থেকে পরীক্ষা দেয়া সম্ভব না। এদিকে কেন্দ্রের পাশেই মোর্শেদের মামা বাড়ি; মামা নেই, তবে মামাতো ভাইয়েরা আছে। কথাবার্তা বলে সেখানেই দেড় মাসের জন্য হেমলতা আর পদ্মজা উঠল। মোর্শেদ বাকি দুই মেয়ে আর প্রান্তকে নিয়ে বাড়িতে রয়ে গেছেন। হেমলতা পদ্মজাকে নিয়ে আসার পূর্বে নিজে এসে দেখে গেছেন, পরিবেশ কেমন। মোর্শেদের দুই মামাতো ভাইয়ের মধ্যে একজন রাজধানীতে থাকে। আরেকজনের বয়স হয়েছে অনেক। ছেলে-মেয়েদের বিয়ে দিয়ে বউ নিয়ে একাই থাকেন। ছেলেরা শহরে চাকরি করে। পদ্মজার জন্য উপযুক্ত স্থান। তাই আর অমত করলেন না।\n\nমোর্শেদের যে ভাইটি বাড়িতে আছেন তার নাম—আকবর হোসেন। বয়স ষাটের বেশি হবে। তবে আকবর হোসেনের স্ত্রী জয়নবের বয়স খুব কম, হেমলতার বয়সি। হেমলতা আকবর হোসেনকে ভাইজান বলে সম্বোধন করেন। দালান বাড়ি, বেশিরভাগ সময় বিদ্যুৎ থাকে। ফলে পদ্মজা মন দিয়ে পড়তে পারছে। পরীক্ষাও ভালো করে দিচ্ছে।\n\nহেমলতা অবশ্য আকবর হোসেনকে চোখে চোখে রেখেছেন। শীতল প্রকৃতির লোক, তবে বিশ্বাসী। রাতের খাবার আকবর হোসেনের সঙ্গেই খেতে হয়। হেমলতা দেড় মাসের খাওয়ার খরচ নিয়ে এসেছেন। আকবর হোসেন কিছুতেই আলাদা রাঁধতে দিচ্ছেন না। এভাবে অন্যের বোঝা হয়ে থাকতে হেমলতার আত্মসম্মানে লাগে। তিনি কথায় কথায় জানতে পারলেন, আকবর হোসেন এবং জয়নবের নকশিকাঁথা খুব পছন্দ। তাই তিনি কিছুদিন যাবৎ নকশিকাঁথা সেলাই করছেন। যতক্ষণ পদ্মজা পরীক্ষা দেয়, ততক্ষণ হেমলতা কেন্দ্রের বাইরে কোথাও বসে বা দাঁড়িয়ে অপেক্ষা করেন।\n\nঅনেক রাত অবধি পদ্মজা পড়ে, আজ অনেকক্ষণ ধরে কী যেন ভাবছে। হেমলতা ব্যাপারটা খেয়াল করে পদ্মজার পাশে বসে জিজ্ঞাসা করলেন, ‘কী ভাবছিস?’\n\nপদ্মজা এক নজর হেমলতাকে দেখে চোখ ফিরিয়ে নিলো। হেমলতা তাকিয়ে রইলেন জানার জন্য। পদ্মজা দ্বিধা নিয়ে বলল, ‘রাগ করবে না তো?’\n\nহেমলতা পদ্মজাকে পরখ করে নিলেন। বললেন, ‘কী জানতে চাস?’\n\nপদ্মজা এদিক-ওদিক চোখ বুলায়। কীভাবে শুরু করবে বুঝে উঠতে পারছে না। দুই মিনিট পর নীরবতা ভেঙে বলল, ‘দুপুর থেকে আমার খুব জানতে ইচ্ছে হচ্ছে, হানিফ মামাকে কে মারল? তোমার সঙ্গে মামার কী কথা হয়েছিল? হানিফ মামাকে… মানে তুমি তো অন্য কারণে গিয়েছিলে কিন্তু ফিরে এলে। খুনও হলো। আমি সবসময় এটা ভাবি। কখনো উত্তর পাই না। মনে মনে অনেক যুক্তি সাজাই। কিন্তু যুক্তিগুলো মিলে না। সব যুক্তিই খাপছাড়া, এলোমেলো।’\n\n‘কাল পরীক্ষা। আর আজ এসব ভেবে সময় নষ্ট করছিস!’\n\nহেমলতার কণ্ঠ স্বাভাবিক। তবুও পদ্মজা ভয় পেয়ে গেল। তবে কিঞ্চিৎ আশা মনে ভীষণভাবে উঁকি দিচ্ছে।','\n',char(10)),13,'published',0,'2026-10-06T08:14:39.046Z','2026-10-06T08:14:39.046Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('5e8ba7f0-a2d6-4f95-affa-e907f09e2ac7','5022b4f1-a115-4976-8e8f-cc6bf8d09c35','পর্ব নাম্বার - 14',replace('কিছুটা দূরেই রেলস্টেশন। সেখান থেকে হুইসেলের শব্দ ভেসে আসছে। গভীর রাতের ট্রেন ছুটে যাচ্ছে নিজ গন্তব্যের দিকে। কাছে কোথাও নেড়ি কুকুরের দল ঘেউঘেউ করছে। হেমলতা জানালাগুলো বন্ধ করে দিলেন যাতে কুকুরের ডাকাডাকির আওয়াজে পদ্মজার পড়াশোনায় সমস্যা না হয়।\n\nপদ্মজা ইংরেজি বইয়ের দিকে চোখ রেখে মিনমিনে স্বরে বলল, ‘পরীক্ষা তো পরশু।\n\nহেমলতা খোলা চুল মুঠোয় নিয়ে হাত খোঁপা করে বললেন, ‘কাল আর পরশুর মাঝে তো খুব একটা পার্থক্য নেই।’\n\nপদ্মজা কিছু বলল না। বইয়ের দিকে তাকিয়ে এমন ভান ধরল যেন পড়ায় তার ভীষণ একাগ্ৰতা।\n\nহেমলতা চোখ ছোটো ছোটো করে পদ্মজাকে দেখছেন। মেয়েটা পড়ায় মনোযোগ দেয়ার আপ্রাণ চেষ্টা করছে, কিন্তু সফল হতে পারছে না। বার বার নিচের ঠোঁট কামড়াচ্ছে। তিনি হঠাৎই বললেন, ‘ছাদে যাবি?’\n\nএহেন প্রস্তাবে পদ্মজা বিস্মিত হলো, নাকের পাটা হয়ে গেল লাল। যদিও এই কথাই নাক লাল কেন হলো, তা জানা নেই। সে হাঁ করে তাকিয়ে রইল মায়ের দিকে। হেমলতা আবার বললেন, ‘যাবি?’\n\nপদ্মজা প্রফুল্লচিত্তে বলল, ‘যাব…যাব আম্মা।’\n\nআকবর হোসেনের বাড়িটির নাম সিংহাসনকুঞ্জ। এই অদ্ভুত নামের হেতু ছাদে উঠলেই জানা যায়। মা-মেয়ে সিঁড়ি বেয়ে ছাদের দিকে উঠছে। তাদের পায়ের শব্দ মোহময় ছন্দ তুলে হারিয়ে যাচ্ছে গহিন অন্ধকারে। ছাদের ঠিক মধ্যিখানে দাঁড়িয়ে আছে বিশাল সিংহাসন। তা দেখে পদ্মজার চক্ষু চড়কগাছ!\n\nবিষ্ময় নিয়ে প্রশ্ন করল, ‘আম্মা! এই সিংহাসন কার?’\n\nহেমলতা পদ্মজার মুখের ভাব দেখে বেশ আনন্দ পাচ্ছেন। তিনি নিজেও দুইদিন আগে সিংহাসনটি দেখে খুব অবাক হয়ে আকবর হোসেনের কাছে একই ভাবে করেছিলেন প্রশ্নটা। তাই আকবর হোসেনের উত্তর পুনরাবৃত্তি করলেন, ‘তোর আকবর কাকার বাবা বিশ্ববিদ্যালয়ে বাংলা সাহিত্যের অধ্যাপক ছিলেন। উনার ইচ্ছে ছিল নিজের বাড়ির ছাদে একটা সিংহাসন তৈরি করার। শেষ বয়সে এসে নিজের মনের ইচ্ছে পূরণ করেছেন। দিনরাত নাকি রাজকীয় ভঙ্গীতে সিংহাসনে বসে থাকতেন। মৃত্যুও হয় এই সিংহাসনে, ঘুমানো অবস্থায়।’\n\nপদ্মজা হাঁ করে কিছুক্ষণ স্থির হয়ে রইল। তারপর খুঁটিয়ে খুঁটিয়ে দেখতে লাগল সিংহাসনটি—ময়ূর সিংহাসন! ইট-সিমেন্টের তৈরি আসনটি যেন পেখম মেলে দাঁড়িয়ে আছে। অনেক বড়ো, দৈর্ঘ্যে পাঁচ ফুট বা আরো বেশি হবে। পদ্মজা প্রশ্ন করল, ‘আম্মা, এটা মোঘল সম্রাট শাহজাহানের সিংহাসনের মতো না?’\n\nহেমলতা বললেন, ‘অনেকটাই তেমন। সম্রাট শাহজাহানের সিংহাসনের মতো করে বানানোর স্বপ্নই বোধহয় তিনি দেখতেন। অর্থের জন্য পারেননি।’ পদ্মজা ভিন্ন প্রসঙ্গে চলে গেল। অনুরোধ করে বলল, ‘আম্মা তুমি সিংহাসনে বসো।’\n\n‘আমাকে মানাবে না। তুই বস, তোকে রাজরানি লাগবে।’\n\n‘তুমি আগে বসো। আম্মা একটু বসো…একটু?’\n\nপদ্মজার অনুরোধে হেমলতা সিংহাসনে বসলেন। পদ্মজাকে ডেকে\n\nবললেন, ‘তুইও আয়, পাশে বস।’\n\nপদ্মজা এলো না। দূর থেকে বলল, ‘মাঝে বসো আম্মা।’\n\n‘কী শুরু করেছিস!’\n\n‘বসো না।’\n\nহেমলতা কপাল কুঁচকে সিংহাসনের মাঝে বসেন। পদ্মজার ঠোঁটে হাসি ফুটে আবার হারিয়ে গেল। বলল, ‘আরেকটু বাকি।’\n\n‘কী বাকি?’\n\nবাঁ-পায়ের উপর ডান পা তুলে রানিদের মতো বসো।’\n\nহেমলতা বিরক্তি নিয়ে উঠে পড়েন। পদ্মজাকে বললেন, ‘পাগলের প্রলাপ শুরু করেছিস!’\n\nপদ্মজা নাছোড়বান্দা হয়ে দৃঢ়ভাবে বলল, ‘আম্মা, বসো। নয়তো আমি কাঁদব।’\n\nপদ্মজার ছেলেমানুষি দেখে হেমলতা হাসবেন না রাগবেন—ঠাওর করতে পারলেন না।\n\nরাতের সৌন্দর্য আর তার মায়াবী রূপকে, প্রতিটি মানুষের ভেতরের আহ্লাদ-ইচ্ছে-কষ্টকে ঠেলেঠুলে বের করে আনার ক্ষমতা বোধহয় আল্লাহ নিজ হাতে দিয়েছেন। তাই হেমলতা তার নিজের শক্ত খোলসে ফিরতে পারলেন না। পদ্মজার পাগলামোর সুরে সুর মিলিয়ে তিনি সিংহাসনে রাজকীয় ভঙ্গীতে বসলেন। পদ্মজার কেমন অদ্ভুত একটা অনুভূতি হয়, বুকের ভেতর ঝিরিঝিরি কাঁপন। এই তো তার কল্পনার রাজ্যের রাজরানি—হেমলতা…এবং তার কন্যা সে পদ্মজা। চোখের মণিকোঠায় ভেসে উঠল একটি অসাধারণ দৃশ্য। হেমলতার সর্বাঙ্গে হীরামণি-মুক্তার অলংকার। অসম্ভব সুন্দর শ্যামবর্ণের এই সাহসী নারীকে দেখতে কতশত দেশ থেকে মানুষ ভিড় জমিয়েছে। আর সে হেমলতার পাশে বসে আছে। চারিদিকে ঢাকঢোল পিটানো হচ্ছে। হাতিশাল থেকে হাতির হুংকার আসছে। তারাও যেন খুশি এমন রানি পেয়ে।\n\n‘তোর পাগলামি শেষ হয়েছে?\n\nপদ্মজা জবাব না দিয়ে হেমলতার পাশে এসে বসল। কোলে মাথা রেখে গুটিসুটি মেরে শুয়ে আক্ষেপের স্বরে বলল, ‘আম্মা, তুমি রানি আর আমি রাজকন্যা কেন হলাম না? সবাই আমাদের ভালোবাসত। সম্মান করত। মুগ্ধ হয়ে দেখত।\n\nহেমলতার বুক চিরে দীর্ঘশ্বাস বেরিয়ে আসে। সমাজ কেন তার প্রতিকূলে থাকল? কেন পদ্মজা ছোটো থেকে সমাজের অন্য কারো মেয়ের সঙ্গে মেশার অধিকার পেল না? তিনি বললেন, ‘জন্ম যেভাবেই হোক। জীবনে সফলতা না এনে মৃত্যুতে ঢলে পড়া ব্যক্তির ব্যর্থতা। তুই এমন জায়গায় যাওয়ার চেষ্টা কর যাতে মানুষ সম্মান করে। সম্মান করতে বাধ্য হয়। চোখ তুলে তাকাতেও যেন ভয় করে। যারা দূরছাই করেছে তাদের যেন বিবেকে বাঁধে।’\n\n‘পারব আমি?’\n\n‘কেনো পারবি না? পুরো জীবন তো দুঃখে-অবহেলায় যায় না।’\n\n‘তোমার জীবনের অনেকগুলো বছর দুঃখ আর অবহেলাতেই তো গেছে। কিছুই পাওনি।’\n\nহেমলতা তাৎক্ষণিক পালটা জবাব দিতে পারলেন না। তিনি দুঃখকষ্ট- অবহেলা-অপমান আর একাকীত্ব ছাড়া জীবনে কী পেয়েছেন? উত্তরটাও চট করে পেয়ে গেলেন।\n\nপদ্মজাকে বললেন, ‘তিনটে মেয়ে পেয়েছি। আমার মেয়েরা আমার সফলতা। আমার অহংকার। প্রেমা তো ছোটো। তোরা দুইজন নিজেদের মতো থাকিস, পড়িস; কোনো দুর্নাম নাই। যখন মানুষ বলে—এই যে, এরা হচ্ছে হেমলতার মেয়ে…তখন আমার অনেক কিছু পাওয়া হয়ে যায়। গর্বে বুকটা ভরে উঠে।’\n\nপদ্মজা আশ্বস্ত করে বলল, ‘কখনো ভুল কাজ করব না। তোমার সম্মান আমাদের জন্য একটুও নষ্ট হতে দেব না।’\n\nহেমলতা পদ্মজার ডান হাত নিয়ে তার উলটোপাশে চুমু দিয়ে বললেন, ‘আমি জানি পদ্ম। আমার মেয়েরা কখনো আমার অসম্মান হতে দিবে না।’\n\nনিস্তব্ধতা ভেঙে ভেঙে মাঝে মাঝে পাতার ফাঁকে ফাঁকে পাখ-পাখালির ডানা নাড়ার শব্দ ভেসে আসছে। পদ্মজা চোখ তুলে আকাশের দিকে তাকাল। আকাশে একটা চাঁদ, অগণিত তারা। আকাশকে তারায় পরিপূর্ণ একটি কালো গালিচার মতো লাগছে। হেমলতা বিভ্রম নিয়ে বললেন, ‘গায়ের কালো রংয়ের দোষে সমাজের সঙ্গে আমার সখ্যতা কখনো হয়ে উঠেনি। প্রকৃতির মতিগতি অবস্থা দেখে দেখে আমার সময় কাটত। আব্বা শিক্ষক ছিলেন বলে কালো হয়েও পড়াশোনা করার সুযোগ পেয়েছিলাম। অবশ্য আব্বার সামর্থ্যও ছিল। আমাদের সব ভাই-বোনকে পড়িয়েছেন। আম্মা আমাকে পড়ানোতে বেশি আগ্রহ দেখিয়েছিলেন। রং কালো, কেউ বিয়ে করবে না। একটু পড়ালেখা থাকলে হয়তো করবে সেই আশায়। যখন আমি তোর বয়সি ছিলাম, তখন বড়ো আপার মেয়ে হয়। মেয়েটার গায়ের রং কালো। শ্বশুর বাড়িতে তুলকালাম কাণ্ড। বংশের সবাই ফরসা। বাচ্চা কেন কালো হলো। আপাকে বের করে দিল! বাড়ি ফিরল আপা, সমাজের কত কটুক্তি হজম করেছে! তখন আমি নামাজের দোয়ায় আকুতি করে চাইতাম একটা সুন্দর মেয়ের। আমার বিয়ে হলে মেয়েটা যেন পরির মতো সুন্দর হয়, আমার মতো অবহেলার পাত্রী যেন না হয়; বড়ো আপার মতো কালো মেয়ে নিয়ে শ্বশুর বাড়ি থেকে বিতাড়িত হতে যেন না হয়। তুই যখন পেটে তখন নফল নামাজ-রোজা বাড়িয়ে দেই। পাঁচ ওয়াক্ত নামাজ বাদে সময় পেলেই সেজদায় লুটিয়ে আল্লাহকে একই কথা বলতাম। আমার পরির মতো মেয়ে চাই। দোয়াও কবুল হয়ে গেল। তোর যেদিন জন্ম হয়, সবাই অবাক হয়ে শুধু তাকিয়েই ছিল। আমি তো খুশিতে কেঁদেই দিয়েছিলাম। এত সুন্দর বাচ্চা এই গ্রামে কেন, পুরো দেশেও বোধহয় ছিল না। চোখের পাপড়ি যেন ভ্রুতে এসে ঠেকছিল। ঠোঁট এত লাল ছিল যেন ঠোঁট বেয়ে রক্ত ঝরছে। সদ্য জন্মানো শিশুর মাথা ভরতি ঘন কালো রেশমি চুল। অলন্দপুরের সবার কাছে ছড়িয়ে পড়ে এই কথা। দল বেঁধে দেখতে আসে। এক সপ্তাহ বেশ তোড়জোড় চলে। কী খুশি ছিলাম আমি! সারাক্ষণ তোকে চুমো খেতাম। রাতেও ঘুমাতে ইচ্ছে করত না। মনে হতো, এই বুঝি আমার পরির মতো মেয়ে চুরি হয়ে গেল! তোর আব্বা সারাক্ষণ খুশিতে বাকবাকম করত। বাইরে থেকে এসে গোসল ছাড়া কোলে নিত না। যখন কোলে নিত বার বার আমাকে বলত, ‘ও লতা। ছেড়িড়া মানুষ না শিমুল তুলা।’\n\nহেমলতা থামলেন। তার চোখের তারায় জল ছলছল করছে। পদ্মজা আগ্রহ নিয়ে শুনছিল। সে বলল, তারপর?\n\n‘কেউ বা কারা রটিয়ে দিল তুই তোর বাপের মেয়ে না। যুক্তি দাঁড় করাল: বাপ-মা কালো মেয়ে এত সুন্দর হয় কী করে? গ্রামের প্রায় সব মানুষ অশিক্ষিত, কুসংস্কারে বিশ্বাসী। তাই বিবেচনা ছাড়াই বিশ্বাস করে নিলো।’\n\nহেমলতা থামলেন। পদ্মজার মনে হতে থাকে, হেমলতা কিছু একটা লুকিয়েছেন। শুধু গ্রামের মানুষ বললেই এত বড়ো দাগ লেগে যায় না। অন্য কোনো কারণ আছে, যা যুক্তি হিসেবে শক্ত ছিল। হেমলতা দম নিয়ে বললেন, ‘আমায় একা করে দিয়ে তোর বাপ সরে গেল। সমাজ সরে গেল। আঁতুড়ঘরে তোকে নিয়ে একা পড়ে রইলাম। তোকে দেখলেই মনে হতো, আল্লাহ কোনো মূল্যবান সম্পদ আমাকে দেখে রাখতে দিয়েছেন। তোকে দেখে রাখা আর বড়ো করাটাই জীবনের লক্ষ্য মনে হতে থাকে। নিজেকে শক্ত করে আমি অন্য-আমি হয়ে যাই, খোলসটা পালটে যেতে থাকে; রাত জেগে স্বপ্ন সাজাই। তোর সঙ্গে ফুল কুড়ানোর স্বপ্ন দেখে ফুল গাছ লাগাই। যখন তোর চার বছর হয় বাড়ি ভরে যায় ফুলগাছে। ছোটো শাড়ি পরিয়ে প্রতিদিন মা-মেয়ে মিলে ফুল তুলে মালা গাঁথতাম। নিশুতি রাতে পাকা ছাদে জোছনা পোহানোর স্বপ্ন ছিল। আজ পূরণ হলো। আর দুইটা ইচ্ছে বাকি, সাগর জলে মা-মেয়ে পা ডুবিয়ে পুরো একটা বিকেল কাটাব। আর, শেষ বয়সে নাতি-নাতনিদের নিয়ে তাদের মায়ের জীবনী বলব।’\n\nপদ্মজা দুই হাতে শক্ত করে জড়িয়ে ধরে হেমলতার কোমর। তিনি টের পান পদ্মজা ফোপাচ্ছে।\n\nউৎকণ্ঠা নিয়ে বললেন, ‘পদ্ম… কাঁদছিস কেন?\n\nপদ্মজা বাচ্চাদের মতো কাঁদতে থাকল। কাঁদতে কাঁদতে বলল, ‘আমাকে কখনো একা থাকতে দিয়ো না আম্মা। আমি তোমাকে ছাড়া থাকতে পারব না। তোমার মতো কেউ হয় না।’\n\n‘এজন্য কাঁদতে হয়? আমি সবসময় তোর সঙ্গে আছি। কান্না থামা। কী মেয়ে হয়েছে দেখো! কেমন করে কাঁদছে। পদ্ম, চুপ…আর না…মারব এবার…পদ্ম।’\n\nপদ্মজা থামল। কিন্তু ভেতরের ছটফটানি পীড়া দিচ্ছে। কেন এমন হচ্ছে জানে না, কিন্তু হচ্ছে; কান্না পাচ্ছে। ভয় হচ্ছে আকাশ ভরা রাতের দিকে তাকিয়ে। একটু আগেই সুন্দর লাগছিল এই আকাশ। আচমকা ভয়ংকর মনে হচ্ছে। মায়ের কোল ছাড়তে ইচ্ছে হচ্ছে না। মনে হচ্ছে, চারিদিকে অশরীরীদের ভিড়। তাদের কোলাহলে মস্তিষ্ক ফেটে যাচ্ছে। পদ্মজা মায়ের কোলে মুখ লুকাল। মেয়েকে অনেকক্ষণ কথা বলতে না দেখে হেমলতা বললেন, ‘পদ্ম, ঘুমিয়ে পড়েছিস?’\n\n‘না আম্মা।’\n\nহেমলতা একটা দীর্ঘশ্বাস ছেড়ে বললেন, ‘সেদিন মাঝ রাত্রিরে ছুরি নিয়ে বের হয়েছিলাম। হানিফের ঘরটা আব্বা-আম্মার ঘর থেকে দূরে হওয়াতে সুবিধা ছিল। ঘরের পাশে গিয়ে দেখি, মদনও ঘরে। আমার পক্ষে দুজন পুরুষকে সামলানো সম্ভব না। তাই মদনের চলে যাবার অপেক্ষা করতে থাকি। এরপর আরেকজন লোক আসে। একটু দূরে সরে যাই, গোয়ালঘরের পেছনে। মিনিট কয়েক পর উঁকি দিয়ে দেখি দরজা লাগানো, সাড়াশব্দ নেই। সাবধানে দরজা ঠেলে ঘরে ঢুকে দেখি হানিফ নেই। তখন হয়তো আম্মা দেখেছে। তাই ভাবছে আমি খুন করেছি।’\n\n‘নানু কেন এমন ভাবল? হানিফ মামা তো তোমারই ভাই।’\n\nহেমলতা তাৎক্ষণিক জবাব দিলেন না। সময় নিয়ে একটা গোপন সত্যি বললেন, ‘আমি তোর নানুর ভাইকে খুন করেছি। তাই তিনি আমাকে ঘৃণা করেন, ভয় পান; সন্দেহ করেন।’\n\nহেমলতার কণ্ঠ স্বাভাবিক। পদ্মজা চমকে উঠে বসল। মুখখানা হাঁ অবস্থায় স্থির হয়ে গেল তার, দৃষ্টি গেল থমকে। পদ্মজা যাতে নিজেকে সামলে নিতে পারে সেই সময়টুকু দিতে হেমলতা দূরের আকাশে চোখ রাখেন। পদ্মজা নিজেকে ধাতস্থ করে নিয়ে বলল, ‘তিনি কি হানিফ মামার মতো ছিলেন?’\n\nহেমলতা সম্মতিসূচক মাথা নাড়ালেন। সিঁড়িতে কারো পায়ের আওয়াজ শোনা যাচ্ছে।\n\nহেমলতা সাবধান হয়ে পদ্মজাকে আড়াল করে দাঁড়ান। সেকেন্ড কয়েক পর একটা ছেলের দেখা মিলল, অচেনা মুখ। হেমলতা আগে কখনো দেখেননি। ছেলেটিও তাদের দেখে ভড়কে গেল।','\n',char(10)),14,'published',0,'2026-10-06T08:16:20.629Z','2026-10-06T08:16:20.629Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('a30027b9-342e-4a4f-a4cd-d7bb8276ac94','33481f0a-425e-4f80-9491-90e3bc35a50b','পর্ব নাম্বার - 1',replace('উপন্যাস :  গিরগিটির প্রেমে মায়াবতী পাগল\nলিখিকা : সুমাইয়া শেখ \nপর্ব : ১ \n\n\nপুড়ান ঢাকার এক কোনে জন্ম সুমাইয়া শেখের \nতারা ৩ বোন ছিলো বড় দু বোনের বিয়ে হয়ে গেছে অনেক আগেই তাদের বাচ্চা গাচাও হয়ে গেছে বড় বোনের দুই টা মেয়ে মেজো বোনের এক টা ছেলে \nতাদের সাথে সুমাইয়ার কোন সম্পর্ক নেই \nনা থাকার কারণ এক টাই  সুমাইয়া যখন ৭ বছর বয়স ছিলো তখন তার বাবা অন্য এক টি মেয়ে কে ভালোবেসে তাকে বিয়ে করে ফেলে এবং তার মা কে ছেড়ে চলে যায় সুমাইয়ার মা ও আরেক টি বিয়ে করে সুমাইয়া কে ছেড়ে চলে যায় সুমাইয়ার তখন ৯ বছর বয়স ছিলো তখন সে ক্লাস 5 এ পড়তো, মার বিয়ে হবে যেনে সুমাইয়া অনেক আটকানোর চেষ্টা করে ছিলো কিন্তু কাজ হয় নি সুমাইয়া প্রচুর কান্না করে ছিলো সে দিন এক পর্যায় সুমাইয়া সেন্সলেস হয়ে যায় তবুও তার মা র পাষান মন টি গলে নাই,,  সুমাইয়া ছোট থেকে টম বয় ছিলো,, মানে সে মেয়ে ছিলো ঠিকি কিন্তু ছেলেদের মতো চলা ফেরা ছেলেদের মতো আচরণ ছেলেদের মতো অনুভতি ছেলের মতো নজর,,  সুমাইয়া তখন যানতো নাহ যে সে যে লেসবিয়ান এন্ড টম বয় \nসুমাইয়া দেখতে ছিলো শ্যামবর্ণ কিন্তু তাকে শ্যামবর্ণ বললেও ভুল হবে,,  কারণ সুমাইয়া যখন গোসল করতো তখন তাকে ফর্সা দেখা তো৷  যখন বাহিরে বেড় হতো তখন তাকে কালো দেখা তো আবার যখন ঘরে থাকতো তখন তাকে শ্যামবর্ণ লাগতো রোদে গেলে তার চেহারা টা রোদের আলোতে চিকচিক করতো এক টা মানুষের যে কতো প্রকার রং থাকে তা সুমাইয়া কে নাহ দেখলে বুঝা যাবে নাহ |  \nসুমাইয়া ছোট থেকে একাই বড় হতে শুরু করলো সে বুঝে গেছে এই স্বার্থের দুনিয়ায় কেউ কারোর নয়!  দাদার রেখে যাওয়ার বাড়ি টাই তার জীবনের শেষ সম্বল রয়েছে | সুমাইয়ার এক টা চাচাতো বোন রয়েছে চাচাতো বলতে নিজের চাচাতো নয়!  সুমাইয়ার দাদার ফুফাতো বোনের ছেলে!  \nমেয়ে টির নাম পাপিয়া পিউ সওদাগর \nতার বাবা ব্যাবসাই ছিলেন তার বাবা কে সওদাগর  সাহেব হিসাবেই চিনেন \nপাপিয়া কে আদর করে সবাই পুচে পিউ নামে ডাকে পুচে পিউ দেখতে যেমন ছিলো!  তার গায়ের রং ছিলো উজ্জ্বল ফর্সা লাবণ্য সুন্দর তার চোখ দুটো ছিলো হরিণ চোখ তার চুল গুলো ছিলো কমর ছাড়িয়ে হাঁটু পর্যন্ত!  তার চুল গুলো দিঘন কালো চুল একে বারে সোজাও নাহ আবার কোকরাও নাহ  \nতার চুল গুলো ঢেউ খেলানো চুল!  যে কেউ দেখলে মাতাল হয়ে যাবে তার রুপে তার রুপে এ প্রকার অদ্ভুত মায়া ছিলো পুচে পিউর অনেক ছেলেরাই পুচে পিউর জন্য পাগল কিন্তু তাদের সাহস হয় নাহ তার কে কিছু বলার ও তার দিকে তাকানোর \nএক বার এক টি ছেলে পুচে পিউর কে বলেছিলো আমি তোমাকে ভালোবাসি আমি তোমাকে বিয়ে করতে চাই পুচে পিউ ওই ছেলে টা কে কিছু নাহ বলেই চলে আসে বাড়ি এসে তার মা কে এই কথা বলে সেই কথা সুমাইয়া শুনে ফেলে তখন পুচে পিউ কে যেয়ে বলছে কে বলছে পুচে পিউ বললো আমি চিনি নাহ সুমাইয়া বললো কোথায় বলছে পুচে পিউ বলো কেনো সুমাইয়া রাগি কন্ঠে ঝাড়ি দিয়ে বললো বলতে বলছি বল এতো কথা বলিস কেন ছোট মানুষ ছোট দের মতো থাকবি পুচে পিউ ভয়ে কাপা কাপা কন্ঠে তুমি কিছু করবে নাহ তো তখন সুমাইয়া রাগি কন্ঠে বললো বলবি নাকি মাইর খাবি পুচে পিউ কান্না করে দিলো সুমাইয়া রাগের মাথায় পাশে থাকা গ্লাস টা আছার দিয়ে বললো জানু*য়ার মাথা গরম হওয়ার আগে বল কে বলছে না হলে থাপ্পড়াইয়া গাল লাল করে ফেলবো!  গ্লাস ভাঙ্গার শব্দ পেয়ে নুরজাহান সওদাগর উপরের ঘরে গেলেলো নুরজাহান সওদাগর ছিলো পাপিয়া পিউ সওদাগরের মা!  নুরজাহান ঘরের বেতর ডুকে বললো কি হয়ে ছে এতো চেঁচামেচি কিসের আর কিসের শব্দ হইলো পুচে পিউ তার মা কে দেখে এক দৌড়ে জড়িয়ে দরলো জড়িয়ে দরে কান্না করেতেছে তার পর সে সুমাইয়া কে বললো কি হইছে পুচে কান্না করে কেন সুমাইয়া রাগীশরে বললো কোন ছেলে ওকে প্রপোজ করছে আমি জানতে চেয়েছি!  তারপর ও আমাকে উল্টো প্রশ্ন করতেছে!  নুরজাহান বললো তোকে কত বার বলবো ওর সাথে জোরে কথা বলবি নাহ ও তোকে দেখে এমনি তেই অনেক ভয় পায় | ভয় পাওয়ার কি আছে আমি বাঘ নাকি ভাল্লুক যে আমাকে ভয় পেতে হবে নুরজাহান বললো বাঘ ভাল্লুক ও ভালো আছে তোর থেকে!  সুমাইয়া বললো আমি কি করছি আমাকে দেখে এতো ভয় পাওয়ার কি আছে \nনুরজাহান বললো সারাদিন নেশা পানি করোস মাস্তানি করোস আবার জিজ্ঞাস কি করছি | \nবাপ চাচা যেমন হইছে সেই রকমি হইছে তোরে দেখে কেউকি বলবো তুই যে এক টা মাইয়া | \nসুমাইয়া বললো আমার যেবাবে চলার ইচ্ছে আমি সেইভাবে চলবো তাতে তোমার কী | নুরজাহান বললো তোর চললা ফেরা নিয়েতো সমস্যা নাহ সমস্যা তো তোমার এই গুন্ডামি নিয়ে যারে ইচ্ছে তারেই মারোস চাচাদের মতো এক নাম্বারে খু*নি হইছো কত মানুষ যে মারছোস এক আল্লাহ জানে আর তোরাই জানিস মাইয়া মানুষ হয়ে এমন করোস নাহ জানি ছেলে হলে কি করতি আর ছেলে হওয়ারি কি দরকার ছেলেদের মতে এক টা শরিল বানাইছে পোশাক গাছাক চুলের কাটিং সবি তো ছেলে তোরে দেখে কেউ কি বলবে তুই যে এক টা মাইয়া মানুষ সুমাইয়ার রাগ আরো বেড়ে গেলো রেগে বলবো কে কি বলতো তাতে আমার কি এক দিন না খেয়ে থাকলে কোনো শালায় খাওন দিয়া যাবোনি এতো কথা বুঝি নাহ তোমার মাইয়ারে বলো কে কি কইছে বলতে | নুরজাহান বললো আমি কিছু জানি নাহ ও স্কুল থেকে আসার সময় কোন ছেলে কি কইছে জানি নাহ তোর এতো দরত তুই যেয়ে খুজে নে!  সুমাইয়া কিছু নাহ বলেই তার বাসার বাসার থেকে বাইকের চাবি নিয়ে চলে গেলো পুচে পিউর স্কুলে দিকে!  \nএদিকে পুচে পিউ এখনো তার মার বুকে মুখ গুজে ফুপিয়ে কান্না করতেছে!  নুরজাহান তার মেয়ের অস্ত্র ভেজা মুখটি উঠিয়ে আলতো করে তার শাড়ির আঁচল দিয়ে মুখটি মুছে দিলো আর বললো আম্মু কান্না করে নাহ আমার লক্ষী মেয়ে আমার সোনামণি ওকে বকে দিছি তো আর কান্না করে নাহ \nতোমার আব্বু কে আসার সময় চকলেট নিয়াস তে বলবো কান্না করে নাহ আমার কলিজা টুকরা পুচে পিউ কান্না থামিয়ে বললো ও আমার সাথে সব সময় এমন করে কথা বলে কেন তখন ওর আম্মু বললো ও তো পচা দুষ্টু বেয়াদব এক টা!  তুমি যাও ফ্রেশ হয়ে নাও খাবার আমি খাবার বারতেছি পুচে বললো আচ্ছা যাও আমি আসতেছি নুরজাহান বললো আচ্ছা তারাতারি আসো নুরজাহান নিচে চলে গেলো আর পুচে পিউ ফ্রেশ হতে চলে গেলো | অন্য দিকে সুমাইয়া পুচে পিউর স্কুল মাঠে গিয়ে বললো কোন খান*কি মা*গির পোলা আমার বোনের দিকে তাকাইছে এক বাপের বেডা হলে সামনে আর তোর কলিজা কতো বড় আজ দেখে ছাড়বো | যে ছেলে টি পুচে কে প্রপোজ করছে তার বন্ধু কে যেয়ে বলছে কোন মাঙ্গির*পোলা আমার বোনের দিকে তাকাইছে ক নয় তো তোরে সহ চান্দের টিকিট কাটিয়ে দিবো,  ছেলেটি ভয়ে বলে দিছে পাশের গলিতেই বসে আছে ওই কথা টা শুনার পর সুমাইয়া আর এক মুহূর্ত না দারিয়ে সোজা চলে গেলো ওই ছেলের কাছে যেয়ে বললো \nতুই আমার বোনের দিকে কোন সাহসে তাকাইছোস তোর এতো সাহাস কে দিছে ছেলে টা বললো আমি শুধু বলছি আমার তোমাকে ভালোলাগে আমি তোমাকে বিয়ে করতে চাই সুমাইয়া বলে উথলো ওর বয়স দেখছোস আর বিয়ের কথা বলবি তা ওর কাছে কেন ওর কি বাপ মা নাই!  ছেলে টা বলে উথলো হু আছে!  \nসুমাইয়া বললো তাহলে তুই ওরে কেন বলছোস \nছেলে টা বললো এমনি ও যদি রাজি থাকে তাহলেই তো কোর বো!  \nসুমাইয়া বলে উথলো তোর বয়স কতো!  \nছেলেটা বললো! ১৭ \nসুমাইয়া বললো,  কাজ কাম কি করিস \nছেলেটা বললো এখন কিছু করি নাহ "\nসুমাইয়া বললো কিছু করিস নাহ তাহলে বিয়ের প্রস্তাব দেশ কেমনে,  আর ওকে বিয়ে করে তুই কি খাওয়াবি "\nছেলেটা বললো,  এখন কিছু করি নাহ পড়াশোনা শেষ করে কাজ শুরু করবো,  \nসুমাইয়া বললো তুই পড়াশোনা শেষ করবি কবে কাজ করবি কবে সেটা তোর ব্যক্তিগত ব্যাপার বর্তমানে কি করিস সেটা বল,  \nবউ পালাকি মুখের কথা বললি আর হয়ে গেলো ''\nছেলে টা বললো কাজ করি নাহ তো কি হইছে আমার যা আছে তা দিয়ে তোমার বোনের মতো ১০০ টা কে পালতে পারবো,  \nসুমাইয়া,  রহস্যময় হাসি দিয়ে বলল টাকার গরম দেখাতে আসবি নাহ৷ তোর মতো ছেলে আমার বোনের পা চাটার যোগ্যতা ও নাই,  \nছেলে টা বললো সুন্দর চেহারা থাকলেই যে সে তার যোগ্যতায় থাকবো না কোনটা নয় সুন্দর নারী তো বাজারেও পাওয়া যায়,  \nসুমাইয়ার হাত মুথ করে নিলো রাগে গজ গজ করতে ছে তার চোখ দুই টা লাল হয়ে গেছে \nতার পর শান্ত কন্ঠে বললো টাকা দিয়া মা*গি পাবি নারী নাহ  নারী যদি টাকার কাছে বিক্রি হত তাহলে ওই টাকার টানে কিন্তু তোর মাও আসছিল তোর বাপের কাছে!  \nছেলে টা রাগের মাথা বললো তোর বোনের সাথে আমার মা র তুলনা করিস তোর বোন কে ১০ টাকার চকলেট কিনে দিলেই দেহ দিতে রাজি আসছিস তুই আমার মার সাথে তোর বোনের তুলো নাহ করতে,  \nসুমাইয়া রাগ আর কন্ট্রোল করতে পারলো নাহ, \nছেলে টাকে তার শক্ত বাহু দিয়ে তুলে এক আছরে তার শরীরে মাংস পিশি ঘায়েল করে ফেলেছে \nতার পকেট থেকে রুমাল বের করে সুমাইয়া হাতে শক্ত করে বেঁধে নিছে তার পর ছেলে টার মুখ বরাবর এক টা ঘুসি দিয়ে বলল তোর কলিজা অনেক বড় হয়ে গেছে তুই আমার বোনের দিকে তাকাইছোস তার উপর তুই বাজে কথা বলছোস তোকে আজ মেরে তোর গোস্ত কুত্তারে দিয়ে খাওয়াবো,  \nআশেপাশে অনেক লোকজন জড়ো হয়ে গেল কিন্তু কেউ ছেলেটাকে বাঁচাতে আসলো না! আর আসবেও নাহ সুমাইয়া ছিলো এক জন মাফিয়া গ্যাংর লিডার ওর উপর কথা বললার সাহস কারোর নেই পুলিশ দের পযন্ত নাচায় সে  সুমাইয়ার বয়স ১৫ কিন্তু তার পাওয়ার এবং শক্তির কাছে প্রাপ্তবয়স্ক ছেলে মেয়ে রাউ হার মান বে সুমাইয়া বাবা চলে যাওয়ার পর থেকে সুমাইয়া প্রতিদিন এক্সারসাইজ করতো আর বর্তমানে তার শরিলের গঠন এক টা প্রাপ্তবয়স্ক ছেলেদের মতো সিক্স প্যাক অ্যাবস (Six-pack abs)\nতার চুলের কাটিং Taper Wolf Cut \nপ্রথম দেখায় কেউ বলবে নাহ সে যে একজন মেয়ে \nসে যদি নিজ থেকে নাহ বললে বা আর কন্ঠ নাহ শুনে তাহলে কেউ বলতে পারবে নাহ সে যে এক টা মেয়ে !  \nসুমাইয়া ছেলে টাকে এমন মার মারছে যে ছেলে টা সেন্সলেস হয়ে গেছে এমন কী তার শরীর অনেক জায়গা থেকে রক্ত বের হছে প্রচুর পরিমানে!  \nসুমাইয়া আর কিছু না করে ছেলে টা কে এক লাথি দিয়ে চলে আসলো বাড়ির দিকে বাসা এসে সুমাইয়া গোসল করে এক টা ঢোলা বব্ল্যা কালারের টাউজার আর এক টা ব্ল্যাক কালারের টি শার্ট \nপড়ে মাথা চুল মুছতে মুছতে ডাইনিং টেবিলের দিকে যাছে,  পুচে পিউ সুমাইয়ার বাইকের শব্দ শুনে খাবার নিয়াসছে সুমাইয়ার বাসার কাজের মেয়েটি ছুটি তে গেছে কিছু দিনের জন্য তাই তার চাচি বাসায় খাবার খায় সুমাইয়া আবার রান্না করতে পারে নাহ তার জন্য সে রান্নার জন্য আলাদা একটি লোক রেখেছে,  পুচে পিউ খাবার রেখে চলে যাবে এই সময়,  সুমাইয়া পিছন থেকে ডাক দিয়ে বললো এই পিচ্চি দাড়া সোফার উপর তোর জন্য আনা চকলেট টা নিয়ে যা, সুমাইয়ার কথা শুনে পুচে পিউ এক বার পিছে তাকারলো সুমাইয়া দিকে একবার তাকিয়ে সোজা সোফার উপর রাখা চকলেট টা নিতে চলে গেলো! \nসুমাইয়া পিছন থেকে বললো আস্তে দোড় দে পড়ে যাবি তো, পুচে পিউর ওই দিকে কোন খেয়ালি নেই সে এক দৌড়ে চকলেটের কাছে চলে গেলো, \nচকলেট টা নিয়ে পুচে পিউ আরেক টা দৌড়ে সোজা বাসায় চলে গেলো!  \nসুমাইয়া ওর কান্ড গুলো দেখলো!  \nতার পর মুচকি এক টা হাসি,  দিয়ে বললো পাগলী এক টা,,! \nপুচে পিউ নাচতে নাচতে বাসা গেলো,  মা নুরজাহান ডাক দিয়ে বললো কি হইছে নাচতে নাচতে আসতেছেন কেনো মহারানী,,!  \nপুচে পিউ হাসি দিয়ে বললো অপ্পা চকলেট দিছে! \nনুরজাহান বললো একটু আগেই তো অপ্পাকে কত কিছু বললাহ এখন আবার অপ্পা দেওয়া চকলেট নিনালহ,  পুচে পিউ হাসি দিয়ে বললো হা হা হা \nআমি আমার অপ্পার চকলেট নিছি তাতে কি হইছে,  আমি আরো নিবো এটা বলে পুচে পিউ এক দোরে তার রুমে চলে গেলো,!  \nসুমাইয়া খাবার শেষ করে নিজের রুমে গেলো \nতার ফোন টা হাতে নিয়ে কিছু কখন দেখছিলো \nএরি মধ্যে এক টা কল আসলো আননোন নাম্বার \nসুমাইয়া  ব্রু কুঁচকে বললো এই সময় আননোন নাম্বার থেকে কে কল করবে সুমাইয়া ভাবতে ভাবতে কল টা কেটে গেলো পরে আবার কল দিলো ওই পাস থেকে বেসে উঠল এক পুরুষাআলি কন্ঠ\nপুরুষ টি বলে উঠল কি হইছে,  \nসুমাইয়া বললো কথায় কিছু তো হয় নাই \nপুরুষ টি আবার বলে উঠলো, \nআরাফ চৌধুরী ছেলে মাহিম চৌধুরী কে তুই নাকি \nমারছিস, \nসুমাইয়া উত্তরে বললো, হুম,,\nপুরুষ টি বললো কেন, \nসুমাইয়া বললো ও পুচে পিউ দিকে নজর দিছে আর ও অনেক উল্টাপাল্টা কথা বলছে পিউ কে নিয়ে, \nপুরুষ টি বলে উঠলো ছেলে টি কি বেঁচে আছে, \nসুমাইয়া বললো হুম সেন্সলেস হয়ে গেছে শরীর দিয়ে অনাকাঙ্ক্ষিত রক্ত বয়ে গেছে তাই ছেড়ে দিছি, \nপুরুষ টি বলে উঠলো,  ওরে বাঁচিয়ে রাখছিস কোন সাহসে রাগে উম্মত হয়ে বললো ২৪ ঘন্টার মধ্যে আমি ওর লাশ চাই ও কার মেয়ের দিয়ে নজর দিছে সেটা আমি দেখে ছাড়বো \nসুমাইয়া বলে উঠলো শান্ত হও আমি দেখতেছি ও যদি মাটির নিচেও থাকে ওই খান দেকে হলেও ওকে তুলে নিয়াস বো,, \nসুমাইয়া আবার বলে উঠলো এই নাম্বার টি কার \nউত্তরে বলল : এটা নতুন সিম সেফ করে রাখ \nসুমাইয়া বললো ঠিক আছে \nপুরুষ টি ছিলো পুচে পিউর বাবা পিয়াস সওদাগর, \nউনি ব্যবসার কাজে দেশের বাহিরে আছেন বর্তমান \nসুমাইয়া ফোন টা রেখে,  ফোন দিলো তার ডেরাই \nসুমাইয়া ছিলো নাম করা মাফিয়া লিডার,\nমেয়ে টা খুব অল্প বয়স থেকে কষ্ট পেতে পেতে \nভয়ংকর এক টা জানো*য়ারের রুপ নিছে, \nএতে তার চাচা তাকে কিছু বলে নাহ কারণ \nতাদের বংশ টা জুরে মাফিয়া গুন্ডায় ভরপুর,\nকিন্তু তাদের সব গ্যাং গের থেকে, \nসুমাইয়ার গ্যাং গের পাওয়ার সব থেকে বেশি, \nথাকার কারণ হলো,  \nতাদের গ্যাং গের সাথে পুলিশ পাওয়ার আছে \nতাদের নিজের পার্সোনাল জস উকিল রয়েছে, \nতাদের টাকার দিক দিয়েও পাওয়ার আছে, \nআর সে কারণে পিয়াস সওদাগর শুধু সুমাইয়ার \nগ্যাং গের সাথেই হাত মিলিয়েছে পিয়াস সওদাগর \nসাদা মাঠা ভাবে চললেও তারা ছিলো অত্যন্ত ধনী \nসুমাইয়া তার পিস্ত*ল  টি বের করে নিয়ে সোজা চলে গেলো নিচে,,,, \nনিচে গিয়ে সে সোফা থেকে বাইকের চাবি টা নিলো \nনিয়ে সে আর এক মুহূর্ত অপেক্ষা না করে চলে গেলো \nমাহিম চৌধুরী কে খুজতে,, \nমাহিম চৌধুরী ছিলো \nচৌধুরী বংশের মেজো ছেলে,, \nতার বাবা ছিলো একজন শিল্পপতি\nমাহিম চৌধুরীর চরিত্র ভালো নয় \nসে হাজার হাজার মেয়ের সাথে \nফার্টিং করে মেয়ে দের দেহ৷ ভোগ করে ছেড়ে দেয় \nসে প্রথমে বিয়ের প্রস্তাব দেয় তার পর মেয়ের সাথে \nমিষ্টি মিষ্টি কথা বলে তাদের কে ঘায়েল করে \nসে এমন ভাবে কথা বলে যে কোন মেয়েই গলে যেতে বাধ্য,, \nএক টা কথায় আছে,, দুষ্টু লোকের মিষ্টি কথা, ঠিক \nতেমন,, \nসে মেয়েদের কে বলে আর কয় দিন পর তো তোমাকেই বিয়ে করবো তাহলে দিলে সমস্যা টা কই\nএই ভাবে ও হাজার মেয়ের জীবন নষ্ট করছে,, \nওর বয়স টা কম হলেও ওর চরিত্র খাদের থেকেও জঘন্য \n\n\nচলবে,,,!\n\n','\n',char(10)),1,'published',0,'2026-10-22T11:59:22.710Z','2026-10-22T11:59:22.710Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('7f915edb-4744-4d05-8741-37c95091a219','33481f0a-425e-4f80-9491-90e3bc35a50b','পর্ব নাম্বার - 2',replace('উপন্যাস :  গিরগিটির প্রেমে মায়াবতী পাগল\nলিখিকা : সুমাইয়া শেখ \nপর্ব : ২\n\n\n\n\nসুমাইয়া মাহিম চৌধুরী কে খুজতে চলে গেলো \nকিন্তু আরাফ চৌধুরী তা আগে থেকে টের পেয়ে যায়,  আর মাহিম চৌধুরী কে দেশের থেকে সরিয়ে দেয়, সুমাইয়া তার দলের লোকেদের কে বললো ওর কোন খোজ পেয়েছিস, \nতারা বলে উঠললো নাহ এখনো পাইনি কিন্তু খোঁজ নিতেছি, সুমাইয়া রাগান্বিত হয়ে বললো, \nতোরা আমার, সাউ*য়ার খোঁজ নিতেছোস, \n\nসুমাইয়া আরো রাগান্বিত হয়ে বললো \nআমার ২৪ ঘন্টার মধ্যে চাই, \nনা হলে তোদের এক টা ও জীবিত থাকবি নাহ \nঠিক ওই মুহূর্তে পিছন থেকে আয়রা বলে উঠলো \nমাহিম পালিয়ে গেছে, \nসুমাইয়া ভ্রু কুঁচকে পিছনের দিকে তাকিয়ে বললো \nকোথায় গেছে,,! \nআয়রা বললে উঠলো ও বাবা অগে থেকে টের পেয়ে গেছে তাই ওকে সরিয়ে দিছে দেশের বাহিরে, \nসুমাইয়া রাগে তার হাত টি মুথ করে সজোরে পাশে থাকা দেওয়ালে এক টা গুসি দিলো বললো ডেভিলস,,,,\nতোদের দিয়ে কোন কাজ হবে নাহ,, \nসুমাইয়া লম্বা একটি শ্বাস নিয়ে,, \nতার পকেট থেকে এক টি সিগারেট বের করে \nলম্বা একটি টান দিয়ে,  উপরের দিকে ধোঁয়া টি ছাড়তে ছাড়তে বললো যাবেই বা আর কই,\nঠিক এক দিন, নাহ এক দিন দড়া দিতেই হবে,\nসুমাইয়ার গালের কোনে এক ফুটা হাসি,\nসেটা কোন খুশির নয় সেটা হলো, \nধ্বংসের হাসি, \nসুমাইয়া ওই খান থেকে বাসায় চলে আসলো, \nএর পর সুমাইয়া ফ্রেশ হয়ে, \nবিছানায় গিয়ে শরীর টি ছেড়ে শুয়ে পরলো, \nএরি মধ্যে সুমাইয়া ফোনে কল বাজলো,\nসুমাইয়া ফোন টা নিয়ে দেখলো সেই নাম্বার টি যে টা দিয়ে কিছুক্ষণ আগে তার চাচা কল দিয়ে ছিলো\nসুমাইয়া কল টি দরে কিছু বলতেই যাবে তার আগে ওই পাশ থেকে ভেসে আসলো পালিয়েছে, \nসুমাইয়া একটু খানি অবাক ভঙ্গিতে বলল \nতুমি কিভাবে যানলে, \nসে বললে উঠলো দেশের বাহিরে থাকি বললে কী কিছু জানবো নাহ, \nসুমাইয়া কিছু বললো নাহ শুধু চুপ করে তার চাচার কথা শুনছে,\nপিয়াস সওদাগর বলে উঠলো,\nপিউ আর তোর চাচি কে দেখে রাখিস, \nআরাফ চৌধুরী কিন্তু ছেড়ে দেওয়ার পাত্র নাহ, \nতার সাথে অনেক আগেই পুরনো একটি বিষয় নিয়ে শত্রু আমি রয়েছে, \nআরাফ চৌধুরী তার শোধ কিন্তু যে কোন মূলে নিবে, \nসুমাইয়া বলে উঠলো,\nও,  নিয়ে তুমি চিন্তা করো নাহ, \nওর মতো হাজার চৌধুরী দেখছি,\nকোন টাও, বা"ল লো ছিড়তে পারে নাই,,!\nপিয়াস সওদাগর বলো, তুই আসিস দেখেই তো, \nনিশ্চিন্তে আছি,,!  \nতবুও বিপদ তো আর বলে কয়ে আসে নাহ,,! \nএটা বলার পর বললো আচ্ছা আল্লাহ হাফেজ,,! \nআগামী মাস বাড়ি আসবো তার পর কিছু কথা আছে তোর সাথে,,! \nসুমাইয়া বললো ওকে আল্লাহ হাফেজ,,! \nনিজের খেয়াল রেখো,,! \nএই কথা বলে ফোন টা রেখে দিয়ে,,! \nবিছানায় বসে লম্বা একটি শ্বাস নিল,,! \nহায় তুলতে তুলতে রুমের বাহিরে গেলো,,! \nএর নিচে গিয়ে কিচেন রুম থেকে পানি খেতে যাবে ঠিক ওই সময় মনে পড়লো পিচ্চি টার তো সামনে পরীক্ষা আমি তো ওর রং পেন্সিল এনেছি ওই টা কি আমি ওকে দিছি,,!\nসুমাইয়া ভাবতে ভাবতে আবার উপরে চলে গেল \nজাওয়ার পর টেবিলের বক্সটি খুলল খুলে দেখে যে এখোনো তার জিনিস গুলো দেওয়া হয় নাই ,,! \nতাই সুমাইয়া রং পেন্সিল | গুলো নিয়ে ওর বাড়ির দিকে হাঁটা দিলো,,! \nযেতে যেতে বললো,,!\nকিছু নিয়ে যাই সাকালে তো অনেক বকা দিছি নাহ জানি কি করতেছে,,!\nএই কথা বললে দোকান থেকে মজা কিনে নিয়ে নিলো,,! \nও যা যা পছন্দ করে তা তা নিয়ে নিলো,\nএর পর বললো চকলেট নিবে কি নিবে নাহ,,! \nসকালে তো চকলেট খাইছে এখন নেওয়ার কোন দরকার নাই,,! \nএর থেকে ভালো অন্য কিছু নিয়ে যাই,,!\nপরে পিউর জন্য মজা আর কাকির জন্য চিকেন বল নিয়ে বাসায় গেলো, \nযাওয়ার পর,  \nসুমাইয়া চাচি কে বললো, পিচ্চি টা কই,\nনুরজাহান বলে উঠলো ওর ঘরে, \nসুমাইয়া তার চাচির হাতে, \nচিকেন বল দিয়ে সোজা পুচে পিউ রুমের দিকে চলে গেলো, \nগিয়ে দেখে পুচে পিউ, \nফোন দেখতেছে,,!\nসুমাইয়া এক টা কাশি দিয়ে বললো সারাদিন ফোন টিপা টিপি পড়াশোনা,,!  \nনাই নাকি,,! \nপিউ সুমাইয়ার কে দেখে বললো অপ্পা তুমি,,! \n\n\nসুমাইয়া বললো হুম কেনো,,! \n\nপিউ বললো বসো বসো,,!\n\nসুমাইয়া বললো তোর তো সামনে পরিক্ষা,,! \nতাই তোর পরিক্ষার জন্য সব নিয়া আসছি যা যা লাগবে তোর,,!\nআর কিছু লাগলে বলিস নিয়ে আসবোনি,,! \nপিউ মুচকি হাসি দিয়ে চোখ গুলো মিট মিট করে সুমাইয়া দিকে তাকালো, \n\nসুমাইয়া এক ঠোঁট উরের দিকে নিয়ে বললো,,! \nবাচ্চা তো বাচ্চা ই হয় ,,! \nপিউ বেটকায়া দিলো তার কথা শুনে,,! \nসুমাইয়া ওর মুখের দিকে তাকায়া বললো \nমুখ বেঁকানো মতো কিছু কই নাই, \nসুমাইয়ার হাতে থাকা মজার টি পুচে পিউর দিকে বাড়িয়ে দিলো, \nদিয়ে বললো, \nএই নে এটা তোর জন্য, \nপিউ মজা দেখে এক জটকায় ওর হাত থেকে প্যাকেটটা নিয়ে নিলো,,! \nসুমাইয়া ওর এই কান্ড দেখে মুচকি এক টা হাসি দিলো,, ! \nসুমাইয়া চলে যাবে এই সময় পিউ বলে উঠলো,,! \nআচ্ছা অপ্পা তুমি বিয়ে করবা কবে,,! \nসুমাইয়া হতভম্ব  হয়ে গেলো পিউ যে এই রকম এক টা প্রশ্ন করবে ভাবতেও পারে নাই,,!\nসুমাইয়া চুপ করে থেকে ভাবতেছে সত্যি তো আমার জীবন কি এভাবেই চলবে নাকি আমার জীবনে কেউ আসবে, \nসুমাইয়া আবার ভেবে উঠলো আমি তো টম বয় (Tom boy) \nআমার আবার কিসের জীবন, \nএক টা মেয়ে হয়ে অন্য আরেক টা মেয়ের প্রতি আসক্ত,  লোকে কী বলবে, \nআর আমাদের লেসবিয়ান দেরিবা কিসের জীবন,\nআমাদের এই রকম জীবন কে লোকে ছি ছি করে ঘৃণ্য করে অথচ আমরাও যে মানুষ এটা কী তারা একবারো মনে করে তারা তো নিজের মতো সবাইকে ভাবে, \nকাউকে কিছু বললে বলে তোমাদের আবেগ তোমাদের কাছে রাখো,\nঅথচ এই আবেগি আল্লাহ লেসবিয়ান জীবনে বেশি দিয়েছে, \nআল্লাহ বানাইলো নারী করে অনূভুতি দিলো পুরুষের যদি এই সম্পর্ক টা হারামি হয়, তাহলে এই অনুভূতি দিয়ে কেন সৃষ্টি করলো, \nআল্লাহ কেন এই সম্পর্ক থেকে বাঁচার কোন আমল দেন নাই নিজ ইচ্ছে  তো আর লেসবিয়ান হই নাই, \nআমরা লেসবিয়ান রা কি এতো টাই খারাপ যে মানুষ আমাদের কে দেখে ছি ছি করবে,, \nএ কথা ভাবতে ভাবতে সুমাইয়ার চোখের কোনে পানি এসে পরে,,! \nপিউ বুঝতে পেরে,  বলে সরি, অপ্পা আমি বুঝতে পারি নাই তুমি যে কান্না করে দিবা,,! বেরি বেরি সরি,\nসুমাইয়া মুচকি হাসি দিয়ে বললো দুর পাগলি,,! \nকে বললে আমি কান্না করতেছি কখনো কি দেখছোস তোর অপ্পা কান্না করতে তোর অপ্পা \nঅনেক স্ট্রং তোর অপ্পা কখনোই কান্না করে নাহ, \nএই কথা বলে সুমাইয়া পিউর দিকে এক টা হাসি দিলো,,!\nপিউ, চিপসের প্যাকেট টি পাশে রেখে সুমাইয়া কে জড়িয়ে দরলো, সুমাইয়া একটু হতভম্ব হয়ে গেলো, \nসুমাইয়া বলে উঠলো কি হইছে,\nএইভাবে জড়িয়ে দরছোস কেন,,!\nসুমাইয়া কথার উওরে পিউ জবাব দিলো \nএক টা কথা বললো রাগ করবা নাহ, তো \nআর  কাউকে বলবা নাহ তো,,! \nসুমাইয়া বলে উঠলো কি কথা বল,,!\nপিউ বললো নাহ আগে পিংকি প্রমিত করো তার পর বলবো,! \nসুমাইয়া বললো ওকে পিংকি প্রমিস  এখন বল,,! \nপিউ বললো আমার নাহ এক জন কে অনেক ভালো লাগে মানে আমি ওকে ভালোবাসি,,! \nপিউর এই কথা শুনে সুমাইয়া পুরোপুরি স্তব্ধ হয়ে যায়,,! \nতবুও নিজের সামলিয়ে বললো what the f*** \nমানে কী, \nআর তোর বয়স কতো হু এই বয়সে এতো পেকেগেছোস,\nআর ভালোবাসা মানে কী জানিস তুই,,!\nপিউ ছল ছল চোখে তাকিয়ে বললো,,! \nভালোবাসা বুঝি নাহ কিন্তু তাকে অনেক ভালো লাগে,,! \nসুমাইয়া রাগান্বিত কন্ঠে বললো ছেলে টা কে,,! \nআর কি করে,,! \nপিউ বললো তুমি ওকে ভালোভাবেই চিলো, \nসুমাইয়া what \nI know ''em,\nপিউ বললো ইয়া জী অপ্পা তুমি ভালোভাবেই চিনো,\nএরি মধ্যে পুচে পিউর মা নুরজাহান সওদাগর চলে এলো, \nএসে বললো পিউ,\nপিউ উওরে বললো, হুম মা বলো, \nনুরজাহান বললো,,! \nতোমার পাপ্পা কল দিছে তোমার সাথে কথা বলবে\nপাপ্পার কথা শুনে পিউ এক লাফে, \nবিছানা থেকে উথে ফোন নিয়ে বারান্দায় চলে যায়,,\nসুমাইয়া পিউর চলে যাওয়া দেখে ওও, ওর চলে যেতে নেয় পিছন থেকে, নুরজাহান বললো চলে জাস,, \n\nসুমাইয়া : হুম \n\nনুরজাহান : খাবার খেয়ে যা, \n\nসুমাইয়া : নাহ এখন খাবার খেতে মন চাইতাছে নাহ\n\nনুরজাহান : কেনো কি হইছে \n\nসুমাইয়া : এমনি কিছু হয় নাই, \n\nএই কথা বলে সুমাইয়া বাসা  থেকে বের হয়ে গেলো,\nবাসা থেকে বের হয়ে এক টা সিগারেট জ্বালালো,\nসুমাইয়া সিগারেট খেতে খেতে বাসায় চলে গেলো,\nবাসায় গিয়ে এ পাশ ও পাশ হতেই আছে। \nসুমাইয়ার কানে শুধু এক টা শব্দই ভাসতেছে, \nও কাউকে ভালোবাসে, \nভাবতে ভাবতে রাত হয়ে গেলো, \nএরি মধ্যে পিউ বাসায় আসলো \nপিউ বললো অপ্পা আজ কিছু ইউনিক জিনিস ট্রাই করো, \nসুমাইয়া বলতেই জাবে যে তুই আসলে কাকে ভালোবাসোত,  \nপরক্ষণে মনে এলো ও কাকে ভালোবাসবে নাহ বাসবে ,, \nসে টা যেনে আমার কী আর আমি বা র জন্য এতো ভাবছি কেন, \nএটা বলে নিজের মন কে শান্তনা দেওয়ার চেষ্টা করলো কিন্তু সান্ত্বনা দিতে পারলো নাহ তবুও \nনিজেকে সামলিয়ে বললো, \nকি খাবি আজকে, \nপিউ বললো,\nবাকরখানি, \nআর মালায় \nআর : লাডু\n\nসুমাইয়া : আচ্ছা তুই বস আমি ফোন দিয়ে বলে দিতেছি \n\nপিউ সোফা উপর বসে  টিভি টা অন করে \nহানি বানি কার্টুন দেখতেছে সুমাইয়া ফোন দিয়ে বলে দিছে যেনো পাঠায় দেয়, \nকার্টুনের শব্দ পেয় এক টা ডিগবাজি দিয়ে সোজা, \nসোফা উপর গিয়ে বসলো \nOMG \nMy favourite cartoon,, \nউম্মা হানি আর বানি, \n\nচলবে,,,!\n\n\n\n\n\n','\n',char(10)),2,'published',0,'2026-10-22T12:00:53.464Z','2026-10-22T12:00:53.464Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('1367db67-a805-4a4b-a67c-ef5dd547a308','33481f0a-425e-4f80-9491-90e3bc35a50b','পর্ব নাম্বার - 3',replace('উপন্যাস :  গিরগিটির প্রেমে মায়াবতী পাগল\nলিখিকা : সুমাইয়া শেখ \nপর্ব : ৩\n\n\n\nহানি বানি কার্টুন দেখতে, দেখতে! \nখাবার চলে আসছে,! \nখাবার গুলো পিউ কে দিয়ে বললো যা এই গুলো বেড়ে নিয়ে আয়,,! \nপিউ বললো আচ্ছা,,  \n\nপিউ খাবার গুলো নিয়ে কিচেন রুমে চলে গেলো,,!\nতার পর বললো অপ্পা তো, জিম করে এখন যদি না খাওয়া যাই তাহলে তো আর খাবেও নাহ,, \n\nএই কথা বলে পিউ, সুমাইয়ার জন্য,  সালাদ আর ডিম পোজ করছে,\n\nএই গুলো নিয়ে খাবার লিভিং রুমের দিকে যায় \nলিভিং রুমে গিয়ে বলে এই নাও, \nসুমাইয়া প্লেটের দিকে তাকিয়ে বলে,\nএগুলো আবার করছে কে,,\n\nসুমাইয়ার এমন কথায় পিউ একটু তেরা ভাবে উত্তর দিয়ে বললো,,\n\nবাসার ভিতরে ভূত-পেত্নী আছে তো ওই গুলো এসে করে দিয়ে গেছে,, \nসুমাইয়া উপরে ঠোঁট এক পাশে বেটকাইয়া শুকনা এক টা ঢোক গিলো, \n\nআর মনে মনে বল টাছে যতসব, ,  \n\nপিউ সুমাইয়ার রিয়েকশন দেখে ভ্রু কুচকে বললো,\nনাটক বাদ দিয়ে খাবার খাও, \n\nসুমাইয়া বললো নাটক কই করলাম আমি তো কিছু বললামি নাহ, \nপিউ বললো কিছু বলতে হবে নাহ, \nখাবার দিছি আগে খাবার খেয়ে নাও, \n\nসুমাইয়া বললো খামু নাহ কি করবি,,!\nপিউ বললো খেতে হবে নাহ,, \nআর খাবাই কেন আমি কি তোমার কিছু লাগি নাকি, \nযে আমার রান্না করা খাবার খেতে হবে,,!\n\nসুমাইয়া বললো,,!\nএ এ এ কিসের ভিতর কিসের কথা বলোস,  হুম,!\nআর আমি কি তোরে বলছি তুই আমার কিছু হস নাহ,,! \n\nপিউ বললো হইছে হইছে, \nআর নাটক করতে হবে নাহ, \nসরো আমি বাসায় যাবো,,\n\nসুমাইয়া বললো,  বাসায় জাবি মানে, আর খাবার গুলো খাবি নাহ,,! \nপিউ বললো তোমার খাবার তুমি খাও আমার খেতে হবে নাহ,,!\n\nসুমাইয়ার এখন পচুর রাগ উঠতেছে,, \nআর বললো আমি তোকে কি বললাম আর তুই আমাকে কি জবাব দিলি, \n\nপিউ বললো কিছুর জবাব দিতে হবে নাহ,,! \nসরো আমি বাসায় জাবো,,! \nপিউ উঠতেই যাবে এই সময়, \nসুমাইয়া পিউর হাত দরে টান দিয়ে তার বুকের, \nসাথে মিশিয়ে নেয় আর বলে \nকি হইছে তোর এমন করতেছিস কেন, \n\nআর আমি তোরে কিছু বলি নাই এমন রাগ করছিস কেন, \nপিউ বললো কিছু নাহ বাসায় যাবো, \nসুমাইয়া বললো যাবি তো, \nখাবার খাবি নাহ,,! \n\nপিউ বললো, নাহ,,!\n\nসুমাইয়া বললো,  কেনো,,! \n\nপিউ: এমনি \n\nসুমাইয়া : এমনি মানে কি,, হু \nফাইজলামি মারাস এক আছার \nদিয়া, \nছাগলামি,, ছুটাইয়া দিমু, \n\nপিউ কাদুকাদু কন্ঠে বললো তুমি এক টা বদমাশ \nতুমি সব সময় আমার সাথে রাগ দেখাও,\n\nসুমাইয়া বললো, রাগ দেখানোর কাজ করলে তো, \nরাগ দেখাবোই, \n\nপিউ বললো কেন দেখাবা, \nআমার এইগুলো একদমি ভালো লাগে নাহ,\n\nসুমাইয়া বললো তোর ভালো লাগা,,  আর না লাগা তে আমার কি যায় আসে,\n\nপিউ বললো এই জন্য ই তো বলছি তুমি আমাকে পর ভাবো,, আপন কেউ হলে কি এমন করতে,,\n\nসুমাইয়া বললো এখানে আপন পরের কি আছে,\n\nপিউ বললো অনেক কিছু আছে,,!\nসুমাইয়া বললো কি আছে বল শুনি,,!\n\nপিউ বললো পারবো নাহ,  তুমি এখনো বাচ্চা নাহ যে তোমাকে সব কিছু খুলে বলতে হবে,,!\n\nসুমাইয়া বললো এতো কিছু বাদ দিয়া খাবার খেয়ে, \ngood girl লের  মতো বাসায় গিয়ে ঘুমা, \n\nপিউ বললো : খাবো নাহ বলছি তো,\n\nসুমাইয়া পিউর হাত শক্ত করে দরে  খাবার গুলো ওর মুখে তুলে খাওয়া দিবে কিন্তু পিউর মুখ, \nখুলতে চায়তাছে নাহ,, \n\nতা দেখে সুমাইয়া বলতাছে তুই আমার সাথে, \nজেদ দেখাস দাড়া তুই,,\nএই বলে সুমাইয়া পাশে থাকা কাটা চামচ নিয়ে \nতার পিছনের দিক দিয়ে \nপিউর মুখে ডুকিয়ে দিলো, \n\nদেওয়ার পর আস্তে আস্তে দাঁতের সাথে ঘোষা দিলো,,\n\nপিউ ব্যথায় চিৎকার দিয়ে বললো what the f**ah\n\nসুমাইয়া পিউর মুখ খুলা দেখে মুখের ভিতর, \nএক সাথে ৩ টা সরমালাই গুঁজে দিল,, \nপিউর মুখ ফুলে উঠলো,, \nসরমালাইয়ের কারণে,  পিউ কথা বলতে পারছে নাহ \n\nপিউ অনেক কষ্টে সরমালাই গুলো খায়,,! \nতা দেখা সুমাইয়া,,!\nখিল খিল করে হাসতেছিলো,, \n\nপিউর গাল দুটো পুরো লাল হয়ে গেছে পুরাই,, \nস্ট্রবেরি মত, \n\nপিউ  রাগে সুমাইয়া চুল দরে টান দিয়ে ওর পিঠে \nকিল ঘুসি  অঝোরে মারতেছে,, \n\nসুমাইয়া পিউর হাত দরে বলে,,  আরে হইছে তো আর কতো মারবে,, \n\nপিউ বলে জানু*য়ার \n\nসুমাইয়া মিটমিট হাসি দিয়ে বলতাছে \n\nই হি আমার সাথে লাগতে আসছো পাখি ইইই,,\nএমন তো হবেই,, হা হা হা,,\n\nপিউ রাগে ফুসরাইতেছে, \n\nসুমাইয়া এ দেখে বলে ওলে তুলু বুলু মুলু,, \nআরে বাবা রাগ করে নাহ অপ্পা ভয় পাইছে,,! \n\nপিউ রাগে কান্না করে দেয়,,! \n\nসুমাইয়া মাথায় হাত বুলিয়ে বলে,\nরাগ করে নাহ সরি সরি,,! \nকান্না করে পাখি,, \nকান দরছি কলিজা সরি,, \nআপু নাহ ভালো,, \nরাগ করে নাহ, \n\nপিউ কান্না থামিয়ে বলে তুমি আমার সাথে কথা বলবা নাহ,,! \n\nসুমাইয়া বলে আচ্ছা বলবো নাহ,, \nখাবার গুলো খেয়ে নাও প্লিজ,, \nপিউ ওর মাথা থেকে সুমাইয়া হাত ঝাড়ি দিয়ে ফেলে,,! \n\nকাটুন ছেড়ে খাবার খাইতেছে,,\nসুমাইয়াও ওর খাবার খাওয়া দেখে,\nও নিজের খাওয়া শুরু করছে,,!\n\nপিউর খাবার খাওয়া শেষে থালা বাসন, \nদুতে যাবে এই সময়,। \nসুমাইয়া পিছন থেকে বলে ধুইতে হবে নাহ, \n\nকাল রহিমা খালা আসবে, সে ধুয়বোনি, \nপিউ কোনো কথা নাহ বলে সোজা কিচেন রুমে \nগিয়ে থালা বাসন ধুয়ে রেখে বাসায় চলে যায় \nসুমাইয়া ঘুমতে চলে যায়,,! \n\nকিন্তু সুমাইয়া চোখে কোন ঘুম নেই,,\nশুধু পিউর ওই কথা টাই বারবার মনে পড়তেছে,,!\nও আসলে কাকে ভালোবাসে,, \nসুমাইয়া নিজেকে শান্ত করার চেষ্টা করতেছিলো,,\n\nও কাকে ভালোবাসে সেটা যেনে সে কি করভে আর এক জন আরেক জন কে ভালোবাস তেই পারে, \nএতে আমি কেন এতো অস্থির হয়ে পড়তেছি,,\n\nকিন্তু তার মন কে কোন মতেই শান্ত করতে পারতেছে নাহ,,!\n\nসুমাইয়া মনে পড়লো ও বলছে আমি নাকি ওকে চিনি,  \nকে সে, \nযে আমি তাকে চিনবো,,,!\nমাহিম,,,!\nনাহ মাহিম কে ভালোবাসলে তো বাসায় বিচার দিতো নাহ,,,! \nতাহলে কে,, \n\nএই গুলো ভাবতে আর এ পাশ হছে,\nসুমাইয়া মাথা নষ্ট হয়ে গেছে,, \n\nএক লাফে সোয়া থেকে বসে উঠলো,,\nউঠে এক টা সিগারেট জ্বালাইলো,\nসে একের পর এক টান দিয়েয় যাচ্ছে কিন্তু, \nতার কানে ওই এক টা শব্দই ভাসতেছে,,\n\n4 টা সিগারেট শেষ করার পর সুমাইয়া এক পাশ হয়ে জোরো মোরো হয়ে কানের উপর বালিশ চাপ দিয়ে ঘুমিয়ে পড়লো,,!\n\nপরের দিন সকাল বেলা, সুমাইয়া সকাল সকাল ঘুম থেকে উঠে ফ্রেশ হয়ে নিছে, \nফ্রেশ হওয়ার পর, \nসুমাইয়া জগিং করতে চলে গেছে, \n\nজগিং করতে গিয়ে সুমাইয়া যা দেখছে,, \nতা দেখার জন্য সুমাইয়া এক দমি প্রস্তুত ছিলো নাহ,, \nসুমাইয়া হতবঙ্গ হয়ে যায় \n\n\n\nচলবে,,,!\n','\n',char(10)),3,'published',0,'2026-10-22T12:34:34.301Z','2026-10-22T12:34:34.301Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('135edada-e94d-416c-bb79-01af2438b7e9','4603dfa0-d90d-4f27-8850-8cb13502c633','অধ্যায় ১',replace('## অধ্যায় ১: কেউই পাগল নয়\n\nটাকা নিয়ে মানুষের আচরণ অনেক সময় আমাদের কাছে অদ্ভুত মনে হতে পারে। কেউ খুব বেশি সঞ্চয় করে, কেউ আবার হাতে টাকা এলেই খরচ করে ফেলে। কেউ বিনিয়োগে বড় ঝুঁকি নিতে প্রস্তুত, আবার কেউ সামান্য ঝুঁকিতেও ভয় পায়।\n\nকিন্তু **কোনো মানুষের আর্থিক সিদ্ধান্তকে শুধু বাইরে থেকে দেখে পাগলামি বা অযৌক্তিকতা বলা যায় না।** কারণ প্রত্যেক মানুষ তার নিজের জীবনের অভিজ্ঞতা থেকে টাকা সম্পর্কে ধারণা তৈরি করে।\n\n## আমাদের অভিজ্ঞতাই আমাদের সিদ্ধান্তকে প্রভাবিত করে\n\nএকজন মানুষ যদি ছোটবেলা থেকেই অর্থের অভাব দেখে বড় হয়, তাহলে তার কাছে টাকা মানে হতে পারে **নিরাপত্তা ও ভবিষ্যতের নিশ্চয়তা।** সে হয়তো বেশি সঞ্চয় করতে চাইবে এবং ঝুঁকিপূর্ণ বিনিয়োগ এড়িয়ে চলবে।\n\nঅন্যদিকে, যে মানুষ আর্থিকভাবে স্বচ্ছল পরিবেশে বড় হয়েছে, তার কাছে ঝুঁকি নেওয়া তুলনামূলকভাবে স্বাভাবিক হতে পারে। সে হয়তো ব্যবসা বা বিনিয়োগে টাকা ব্যবহার করতে বেশি আগ্রহী হবে।\n\nদুজন মানুষের সিদ্ধান্ত সম্পূর্ণ আলাদা হলেও, **দুজনের কাছেই তাদের সিদ্ধান্ত যুক্তিসঙ্গত হতে পারে।** কারণ তারা একই জীবন দেখেনি এবং তাদের অভিজ্ঞতাও এক নয়।\n\n## একই টাকা, ভিন্ন সিদ্ধান্ত\n\nধরুন, দুজন মানুষের হাতে একই পরিমাণ টাকা আছে।\n\nপ্রথম ব্যক্তি ভাবতে পারে, “টাকাটা নিরাপদে রেখে দেওয়াই ভালো। ভবিষ্যতে কী হবে, তা আমি জানি না।”\n\nদ্বিতীয় ব্যক্তি ভাবতে পারে, “টাকাটা বিনিয়োগ করলে ভবিষ্যতে এর মূল্য আরও বাড়তে পারে।”\n\nকে সঠিক?\n\nএর কোনো সহজ উত্তর নেই। কারণ প্রত্যেক মানুষের **আয়, বয়স, পরিবার, লক্ষ্য, অভিজ্ঞতা এবং ঝুঁকি নেওয়ার ক্ষমতা** আলাদা।\n\nতাই অন্য কারও আর্থিক সিদ্ধান্তকে নিজের পরিস্থিতির সঙ্গে তুলনা করে বিচার করা ঠিক নয়।\n\n## সময়ের প্রভাব\n\nআমরা যে সময়ে বড় হই, সেই সময়ের অর্থনৈতিক পরিস্থিতিও আমাদের চিন্তাভাবনাকে গভীরভাবে প্রভাবিত করতে পারে।\n\nঅর্থনৈতিক মন্দা, বেকারত্ব, মূল্যস্ফীতি, বাজারের বড় পতন কিংবা পরিবারের আর্থিক সংকট—এসব ঘটনা মানুষের মনে দীর্ঘস্থায়ী প্রভাব ফেলতে পারে।\n\nযে ব্যক্তি জীবনে বড় ধরনের অর্থনৈতিক সংকট দেখেছে, তার কাছে ঝুঁকি খুব ভয়ের বিষয় হতে পারে। আবার যে ব্যক্তি দীর্ঘ সময় ধরে বাজারের উন্নতি দেখেছে, তার কাছে বিনিয়োগের ঝুঁকি তুলনামূলকভাবে সহজ মনে হতে পারে।\n\n## অন্যকে বিচার করার আগে\n\nআমরা প্রায়ই অন্য মানুষের আর্থিক সিদ্ধান্তকে নিজের অভিজ্ঞতার ভিত্তিতে বিচার করি। কিন্তু **একজন মানুষের কাছে যে সিদ্ধান্তটি ভুল মনে হয়, অন্য একজনের কাছে সেটিই হয়তো সবচেয়ে নিরাপদ সিদ্ধান্ত।**\n\nকারণ আমরা অন্য মানুষের জীবনের সম্পূর্ণ গল্প জানি না।\n\nতার পরিবার কেমন ছিল, সে কী ধরনের অর্থনৈতিক পরিস্থিতির মধ্য দিয়ে গেছে, জীবনে কী হারিয়েছে বা কী অর্জন করেছে—এসব বিষয় তার অর্থনৈতিক আচরণকে প্রভাবিত করতে পারে।\n\n## অধ্যায়ের মূল শিক্ষা\n\n**টাকার ব্যাপারে মানুষের আচরণ শুধু গণিত বা যুক্তি দিয়ে বোঝা যায় না।** মানুষের আবেগ, ভয়, আত্মবিশ্বাস, অতীতের অভিজ্ঞতা এবং ভবিষ্যৎ সম্পর্কে তার ধারণাও আর্থিক সিদ্ধান্তে গুরুত্বপূর্ণ ভূমিকা রাখে।\n\nতাই অন্য কেউ কীভাবে টাকা খরচ করছে, কতটা সঞ্চয় করছে বা কোথায় বিনিয়োগ করছে—তা দেখে দ্রুত তাকে বিচার করা উচিত নয়।\n\n**প্রত্যেক মানুষ তার নিজের জীবনের গল্পের ভিত্তিতে অর্থকে দেখে এবং সিদ্ধান্ত নেয়।**\n\n## মূল কথা\n\n> **কেউই পাগল নয়। আমরা প্রত্যেকে নিজের দেখা পৃথিবী, নিজের অভিজ্ঞতা এবং নিজের পরিস্থিতির ভিত্তিতে অর্থ নিয়ে সিদ্ধান্ত নিই।**','\n',char(10)),1,'published',0,'2026-10-23T14:36:19.499Z','2026-10-23T14:36:19.499Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('45d347c0-7b28-48b5-8fee-bcf0d9b04d74','21089d4d-66d4-44f0-9c07-c7d401bed631','পর্ব ২',replace('গল্প : আমার একমুঠো সুখ\nলিখিকা : মারুফ \nপর্ব : ২\n\nরাতের আঁধার পেরিয়ে দিনের আলো ফুটলো। সুজ্জি মামা সেই ভোরেই মেঘের আড়াল থেকে বেরিয়ে গোটা ধরণীতে নিজের তেজ ছড়িয়ে দিচ্ছে। বেশ গরম আজ, এসি চলছে। বিছানায় ঘুমিয়ে আছে সুব্রতা। এই নিয়ে বেশ ক’বার এলার্ম বেজেছে। বারবার বন্ধ করে বালিশে মুখ গুজে ঘুমিয়েছে সুব্রতা। সকাল ৭টা বেজে ৫২ মিনিট, ফের এলার্ম বাজছে। এলার্মের শব্দে ঘুম ভাঙলো সুব্রতার। এক চোখ মেলে দেওয়াল ঘড়িতে সময় দেখে নিলো। হাত বাড়িয়ে এলার্ম ঘড়িটা বন্ধ করে উঠে বসলো সে। এবার না উঠলে ভার্সিটি যেতে দেরি হয়ে যাবে। হাই তুলতে তুলতে নেমে দাঁড়ালো বিছানা থেকে। বালিশের পাশ থেকে অ্যালবামটা নিয়ে বুকশেলফে রেখে এল। একেবারে ভার্সিটি যাওয়ার জন্য তৈরি হয়ে ডাইনিং-এ এল। ফারহানা চৌধুরী, আলিনা, সাদাব সবাই আছে। ওর বাবা আরীজ চৌধুরী বাড়িতে নেই। জরুরি কাজে কোথায় যেন গিয়েছেন।\nচেয়ার টেনে বসতেই সাদাবের গমগমে কণ্ঠস্বর কানে এল— ‘তোক নাকি কোন ছেলে বিরক্ত করে সুব্রতা? আজ ভার্সিটিতে যাবো তোর সাথে। ওই ছেলের চোখ দুটো উপরে দিয়ে আসবো।’\nকণ্ঠে রাগ স্পষ্ট। সাদাব রেগে আছে, যার ফলে চোখজোড়াও লাল বর্ণ ধারণ করেছে।\nসুব্রতা বলে উঠলো— ‘তার প্রয়োজন নেই ভাইয়া। এখানেই আছি তো আমি ক’দিন। এক্সাম শেষেই তো দেশে চলে যাবো। শুধু শুধু ঝামেলা করার দরকার নেই।’\nসাদাব কিছু বলবে কিন্তু তার আগেই ফারহানা চৌধুরীর চোখে ইশারায় থেমে গেল সে। সুব্রতা দ্রুত খাওয়া শেষ করে আলিনাকে বললো— ‘ভাবী চা দাও তো। চা না খেলে একটা ক্লাসেও ঠিকমতো মনোযোগ দিতে পারবো না।’\nআলিনা কেটলি থেকে চা ঢেলে এগিয়ে দিল। সুব্রতা আয়েশ করে চায়ের কাপে চুমুক দিতেই সাদাব ফের বলে উঠলো— ‘আজ সন্ধ্যায় আয়াদের সঙ্গে দেখা করতে যাবো আমরা। রেডি হয়ে থাকিস।’\nসুব্রতা ছোট ছোট চোখে চাইল সাদাবের দিকে। অবাক স্বরে বলে উঠলো— ‘উনি দেখা করবেন? উনি নিজেও তো এতদিন চায়নি। আর আমিও চাই না এখনই এসব নিয়ে ভাবতে। এক্সাম শেষ হলে দেশে ফিরে ওনার সঙ্গে দেখা করবো ভাইয়া।’\nসাদাব প্রশ্ন ছুড়লো— ‘তুই আদৌ আয়াজকে বিয়ে করতে রাজি তো মন থেকে? নাকি পরিবারের কথায়?’\nজীবনের সবচেয়ে বড় সেই সিদ্ধান্তটা সুব্রতা নিজে ভেবে-চিন্তেই নিয়েছে ভাইয়া। সুব্রতা অন্য মেয়েদের মতো নয়। সে যথেষ্ট বোঝে, তাই এ নিয়ে তোমাদের ভাবতে হবে না। কথাটা বলেই সুব্রতা বেরিয়ে গেল বাসা থেকে।\nআর তো কয়েকটা দিন। তারপর থেকে আর ওই ছেলের মুখদর্শন আর করতে হবে না। আর না ওই ছেলের ওর সামনে এসে ভালোবাসার কথা বলতে পারবে। বেশ শিক্ষা হবে ছেলেটার। কথাগুলো ভাবতে ভাবতেই সুব্রতা এগিয়ে চললো ভার্সিটির দিকে।\nঅফিসে নিজের কেবিনে বসে কাজ করছে আয়াজ। কিবোর্ডে টাইপিং করতে করতে হঠাৎ আঙুল নেমে গেল। আয়াজ চেয়ারে মাথা এলিয়ে দিল। ভালো লাগছে না কিছুই। বাবা সকাল থেকে আরও বেশ ক’বার কল দিয়েছে। আয়াজ ধরেনি। ওর বিয়ে নিয়ে বেশ সিরিয়াস মানহাস চৌধুরী। মনে হচ্ছে এবার ওর ইচ্ছার বিরুদ্ধে বিয়ে দিয়ে ছাড়বে বাবা-মা।\n[এখন একটি অ্যাড চলবে। আপনারা চাইলে স্কিপ করতে পারেন। আজকে আমি আপনাদেরকে সবচেয়ে বিশ্বস্ত বুকমেকার 1XBET সম্পর্কে বলতে চাচ্ছি, যেটি পিএসজি এবং সিরিয়ার অফিশিয়াল পার্টনার। ফিফা বিশ্বকাপ শুরু হয়ে গিয়েছে, এটিই হতে পারে সবচেয়ে বড় সুযোগ আপনার প্রিয় দলকে সমর্থন করেন। এই অ্যাপে আপনি ক্রিকেট ফুটবল টেনিস লাইভ ম্যাচ দেখতে এবং তাদের স্কোর ভবিষ্যৎবাণী করেই সহজেই অর্থ উপার্জন করতে পারবেন। সেই সাথে বিএমডব্লিউ গাড়ি আইফোন ল্যাপটপ এবং আরো অনেক নগদ পুরস্কার জেতার সুযোগ রয়েছে। এই অ্যাপটিতে আপনি ক্র্যাশ ক্রিস্টাল আন্ডার এন্ড ওভার টোয়েন্টি ওয়ান ইত্যাদি গেম খেলে সহজেই আয় করতে পারবেন। সাইনআপ করার সময় আমার প্রচার কোড 1XMARU ব্যবহার করে আপনার প্রথম জমাতে 24 হাজার টাকা পর্যন্ত পান। আপনি বিকাশ নগদ রকেট উপায় ব্যাংক ক্রিপ্টো পেপল এবং অন্যান্য সহজ পদ্ধতির মাধ্যমে সহজেই আপনার জেতা টাকা তুলতে পারবেন। এখানে আপনি 24 ঘন্টা সাত দিন গ্রাহক সহায়তা পাবেন তাই গুগলে 1X সার্চ করে অফিশিয়াল ওয়েবসাইটটিতে গিয়ে রেজিস্ট্রেশন করুন আর রেজিস্ট্রেশনের সময় অবশ্যই আমার প্রচার কোড 1XMARU ব্যবহার করে প্রথমবার ডিপোজিটে 24 হাজার টাকা পর্যন্ত পান।]\nআয়াজ চোখ বুঝে নিল। চোখের সামনে ভেসে উঠলো প্রিয় রমণীর মুখখানা। মেয়েটাকে ভুলে অন্য কাউকে বিয়ে করা আয়াজের পক্ষে সম্ভব নয়। দু’বছরে মেয়েটা ওর মন-মস্তিষ্ক সবটা দখল করে নিয়েছে। আয়াজের ভীষণ ইচ্ছা করছে একটাবার সুব্রতাকে দেখতে। চোখ মেলে ঘড়িতে সময় দেখে উঠে দাঁড়ালো আয়াজ। বেরিয়ে গেল কেবিন থেকে। গাড়ি নিয়ে রওনা হলো সুব্রতার ভার্সিটির দিকে।\nভার্সিটির রাস্তার অপর পাশের রাস্তায় গাড়ি পার্ক করে একটা গাছের সাথে হেলান দিয়ে দাঁড়ালো। সুব্রতা একটু পরেই বেরোবে। ওর ভার্সিটির সময় জানে আয়াজ। এ দু’বছর ধরেই এখানেই ওকে দেখতে আসে। তাছাড়া এক-দু’বার অনাকাঙ্ক্ষিতভাবে অন্যান্য জায়গা দেখা হয়ে গেছে। তবে আয়াজ কখনোই সুব্রতাকে ফলো করেনি কিংবা ওকে বিরক্ত করেনি।\nআয়াজ দাঁড়িয়ে চেয়ে আছে ভার্সিটির গেটের দিকে। প্রায় ১০ মিনিট পর সুব্রতা বেরিয়ে এল। আয়াজকে দূর থেকেই দেখেই সুব্রতার ঠোঁটের কোণে বাঁকা হাসি টেনে এগিয়ে আসে। সুব্রতাকে নিজের দিকে এগিয়ে আসতে দেখে ভুরু কুচকে যায় আয়াজের। যে-মেয়ে সবসময় ওকে দেখলেই বিরক্ত হয়ে চলে যায় দ্রুত, সে-মেয়ে ওর কাছে আসছে? এটা যেন বিশ্বাস হচ্ছে না আয়াজের।\nআয়াজ দেখেই যাচ্ছে সুব্রতাকে। সাদা রঙের থ্রি-পিস পরিহিত মেয়েটা ধীরে-সুস্থে রাস্তা পেরিয়ে এদিকটায় এল। ওর মুখোমুখি দাঁড়িয়ে বা হাতের অনামিকা আঙুলটা ওর সামনে ধরে বললো— ‘দেখুন তো তানভীর, এটা কি?’\nআয়াজ তাকালো। হীরার একটা আংটি জ্বলমল করছে সুব্রতার আঙুলে। কিছু বললো না। সুব্রতা ফের বলে উঠলো— ‘এটা কিসের আংটি জানেন? আমার এনগেজমেন্টের। আমার বিয়ে কিছুদিন পর। সুতরাং আমার পিছু ঘুরে আপনাদের লাভ নেই।’\nআয়াজ দু’সেকেন্ডের জন্য থেমে গেল। নিজেকে স্বাভাবিক রেখে বললো— ‘এসব বলে লাভ নেই, ভালোবাসি আপনাকে আমি। সারাজীবন আপনাকেই ভালোবাসবো। আর আপনি আমারই হবেন।’\nসুব্রতা উচ্চস্বরে হেসে উঠলো। ‘শুধু শুধু এসব ভেবে নিজের লাইফটা একটা মেয়ের পেছনে নষ্ট করছেন। আমি কখনোই আপনার হব না। কারণ আমি আমার কাজিনকে ভালোবাসি। তার সাথে আমার এনগেজমেন্ট হয়ে গেছে। কিছুদিন পর আমাদের বিয়ে। আপনি চাইলেও কিছু করতে পারবেন না। তাই আমায় নিয়ে স্বপ্ন দেখা বাদ দিন তানভীর।’\nআয়াজ চুপ করে রইলো। সুব্রতা ওর কাজিনকে ভালোবাসে? এনগেজমেন্টও হয়ে গেছে? কিন্তু কখন? গতকাল?\nআয়াজকে ভাবতে দেখে সুব্রতা ফের বলে উঠলো— ‘কি ভাবছেন? কখন এনগেজমেন্ট হয়েছে? গতকাল সন্ধ্যায়। আমাদের দুই পরিবারের সবাই হ্যাপি। সবচেয়ে বেশি হ্যাপি আমি। কারণ যাকে ভালোবাসি, তাকে নিজের করে পাবো।’\nআয়াজের চেহারায় আঁধার নেমে এল। বুকটায় যেন অদৃশ্য ফাটল ধরেছে। ভালোবাসার মানুষটার কণ্ঠে অন্য কারোর নাম শুনতেই প্রচ- কষ্ট হচ্ছে। আয়াজের ব্যাপারটা বুঝতে পেরে মনে মনে ভীষণ হাসি পেল সুব্রতার।\nসে আর কিছু না বলেই ঠোঁটের কোণে গাজালানো হাসিটা ঝুলিয়ে আয়াজের সামনে থেকে চলে এল। আয়াজ একদৃষ্টিতে তাকিয়ে আছে সুব্রতার দিকে। মনের ভেতর বিষণ্ণতার ঝড় উঠেছে। তোলপাড় হয়ে যাচ্ছে সবকিছু। এক পা দু’পা করে পিছিয়ে গেল আয়াজ। গাড়িতে উঠেই ফুল স্পিডে স্টার্ট দিল। নিজের ফ্ল্যাটে এসে গায়ে শার্টটা খুলে ছুড়ে ফেললো বিছানায়। ফর্সা চেহারা লাল হয়ে আছে। চোখ টলমল করছে। অসহ্য লাগছে সবকিছু। ভীষণ যন্ত্রণা হচ্ছে বুকের ভেতরটায়। ভালোবাসার মানুষটার বিয়ে হয়ে যাবে অন্য কারোর সাথে! এতগুলো দিন ধরে যাকে নিয়ে সংসার করার স্বপ্ন বুনেছিল, সে-মানুষটা অন্য একজনের হয়ে যাবে? এটা কিছুতেই মেনে নিতে পারছে না আয়াজ।\nফোন বেজে উঠতেই পকেট থেকে বের করলো আননোন নাম্বার। রিসিভ করলো আয়াজ। ওপাস থেকে ভেসে এল একজনের কণ্ঠস্বর— ‘হ্যালো! সাদাব চৌধুরী বলছি। তোমার কাজিন?’\nআয়াজ নড়েচড়ে বসলো। আরীজ চৌধুরীরা বিদেশে আসার পর থেকে মানহাস চৌধুরী দের সঙ্গে কথা হলেও আয়াজের সঙ্গে সাদাবের কথা হয়নি। দূরত্বের কারণে ওদের কাজিনদের মধ্যে তেমন কথপোকথন হয় না বললেই চলে। তাছাড়া আয়াজ অন্যরকম। সবসময় নিজের পড়াশোনা, ক্যারিয়ার এসবেই ব্যস্ত থাকত। তবে সাদাবের নাম শুনে মনে পড়লো। গলা স্বাভাবিক করে বললো— ‘জি আলহামদুলিল্লাহ ভালো। আপনি কেমন আছেন ভাইয়া?’\n‘ভালো। তুমি তো আমাদের সঙ্গে দেখাও করতে চাচ্ছো না আয়াজ। অথচ কিছুদিন পর আমার বোনের সাথে তোমার বিয়ে। আসলে আমি ভীষণ ব্যস্ত ভাইয়া। আজ যদি ফ্রি থাকো তবে সন্ধ্যায় দেখা করি।’\n‘সরি ভাইয়া, আজ তো পারব না। অফিসের কাজে ব্যস্ত।’\n‘আচ্ছা, ফ্রি হয়ে জানিও আমায়।’\nআয়াজ হ্যা বলে ফোন কেটে ফোনটা ছুড়ে মারলো বিছানায়।\nঅসহ্য লাগছে সবকিছু। যাকে চিনি না জানি না, তার সাথেই ওর বিয়ে দিতে চাইছে পরিবারের সবাই। অথচ যাকে ভালোবাসে সে-মানুষটা তাকে বুঝলোই না! উল্টো তার বিয়ে হয়ে যাবে অন্য একজনের সাথে! আয়াজের ভীষণ বিরক্ত লাগছে। একদিকে ওর কাজিনের সাথে বিয়ের কথা ভেবে রাগে মাথা ফেটে যাচ্ছে, অন্যদিকে সুব্রতাকে না পাওয়ার যন্ত্রণায় ভেতরটা ছটফট করছে। আয়াজের ভীষণ ক্লান্ত লাগছে। সুব্রতার বলা প্রত্যেকটা কথা কানে বাজছে। যন্ত্রণা হচ্ছে ভেতরটায়। মাথা চেপে ধরে আয়াজ ওশরুমের দিকে পা বাড়ালো।\nশাওয়ার অন করে বসে পড়লো। পানির ধারাটা ভিজিয়ে দিতে লাগল যন্ত্রণায় ছটফট করতে থাকা একলা প্রেমিককে। সুব্রতা বাড়ি ফিরে এসেই দুপুরের খাওয়া-দাওয়া শেষ করলো। আয়াজকে কথাগুলো বলতে পেরে মনটা আজ বেশ ফুরফুরে। তখন বিকেল, রুমে পড়ার টেবিলে বসে কিছু লিখছিল সুব্রতা। দরজায় করা নাড়ার আওয়াজে উঠে গিয়ে দরজা খুলে দিল। আলিনা এসেছে। হাতের ছোট ট্রেতে করে দু’জনের জন্য চা নিয়ে। সুব্রতা হাসি-হাসি মুখ করে ধন্যবাদ জানিয়ে চায়ের কাপে চুমুক দিল। আলিনা বিছানায় বসতে বসতে জিজ্ঞেস করলো— ‘তোমায় আজ বেশ হাসিখুশি দেখাচ্ছে। কোনো ভালো খবর আছে কি সুব্রতা?’\nসুব্রতা হাসতে হাসতে বললো— ‘আজকে ওই ছেলেকে একদম উচিত শিক্ষা দিয়ে এসেছি ভাবি। আশা করি এবার আমার পিছু ছেড়ে দিবে।’\n‘কি করেছ?’\nসুব্রতা হাতের আংটিটা দেখিয়ে বললো— ‘জন্মদিনে ভাইয়ার দেওয়া এই আংটিটা দেখিয়ে বলেছি, আমার এনগেজমেন্ট হয়ে গেছে। আমার কাজিনকে ভালোবাসি আমি আর তাকেই বিয়ে করব। জানো ভাবি, তখন ওই ছেলের চেহারাটা জাস্ট দেখার মতো ছিল। বেচারা নিশ্চয়ই আমার শোকে এখন অশ্রু বিসর্জন দিচ্ছে।’\nসুব্রতার কথাগুলো শুনেই আলিনা হেসে উঠলো। ‘বাপরে! তুমি তো দেখছি সেই লেভেলের চাল খাটিয়েছ। যাকে এখনো অব্দি দেখোইনি, তাকে ডিরেক্ট ভালোবাসো বলে এসেছ? ইউ আর গ্রেট সুব্রতা!’ বলেই হাত মেলালো দু’জন।\nআলিনা আর সুব্রতা খুব ক্লোজ। বয়সের পার্থক্যও বেশি নাই। সুব্রতা অল্পভাষী, খুব কম কথা বলে। অপরিচিতদের সাথে প্রয়োজন ছাড়া একটা বাক্যও ব্যয় করে না। তবে পরিচিত কাছের মানুষদের সাথে সে খুবই ক্লোজ। স্বভাবে কিছুটা রাগিও। ওর রাগ সম্পর্কে বাড়ির সবারই ধারণা আছে। তাই তো আয়াজের সাথে বিয়ে ঠিক করার পর এ ব্যাপারে তেমন একটা আগ্রহ প্রকাশ না করার ফলে সবাই ভেবেছিল সুব্রতা এ বিয়ে নিয়ে রাজি নয়। আয়াজের মুখোমুখি হলে যদি রাগ দেখে বিয়ে ভেঙে দেয়, তবে তো অসম্মান হবে ওনাদের। এ কথা ভেবে ফারহানা চৌধুরী ভেবেছিলেন বাংলাদেশ যাওয়ার আগে ভালোভাবে সুব্রতাকে জিজ্ঞেস করে তবেই নিয়ে যাবেন। কিন্তু কাল সুব্রতা নিজেই বলে দিয়েছে আয়াজকে বিয়ে করতে ওর কোনো আপত্তি নেই। এটা শোনার পর সবাই স্বস্তির নিঃশ্বাস ফেলেছে।\n\nচলবে...!','\n',char(10)),2,'published',0,'2026-10-26T09:54:07.293Z','2026-10-26T09:54:07.293Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('fea89caa-40a6-4147-8bea-5eb1efddb953','21089d4d-66d4-44f0-9c07-c7d401bed631','পর্ব ১',replace('গল্প : আমার একমুঠো সুখ\nলিখিকা : মারুফ \nপর্ব : ১ \n\nআমি কিছুতেই ওই মেয়েটাকে বিয়ে করতে পারব না বাবা। আমি একটা মেয়েকে ভালোবাসি, সেইটা আর কতবার বলবো তোমাদের? একই কথা প্রতি বছর বলেই যাচ্ছো তুমি। প্লিজ, এবার এসব বন্ধ করো।\nরাগী গলায় কথাটা বলে থামলো এক যুবক। ফোনের অপর পাশ থেকে ওর বাবা মানহাস চৌধুরী বলে উঠলেন, "তুমি শুধু শুধুই চ্যাঁচামেচি করছো আয়াজ, তোমাকে সে কবে থেকেই বলে যাচ্ছি, একটা বার মেয়ের ছবি তো দেখো! সেই কোন ছোটবেলায় তুমি ওকে দেখেছো, তারপর তো ওরা দেশের বাইরেই চলে গেল। তোমাকে কতদিন ধরে বলছি, ওর সাথে একটাবার মিট করতে। যেহেতু একই দেশে থাকছো তোমরা, তাই একটা বার দেখাই করতেই পারো। কিন্তু তুমি নিজের ইচ্ছেটাকেই উপরে রেখেছো। তবে একটা কথা কান খুলে শুনে রাখো, আগামী মাসে তোমার জেঠুরা সবাই দেশে আসবে, তোমাকেও আসতে হবে, বিয়ে হবে তোমাদের! এন্ড এটাই আমার ফাইনাল ডিসিশন।"\nকিন্তু বাবা, কোনো কিন্তু না। তুমি যেমন চেয়েছ তেমনটাই হয়েছে। বাইরে গিয়ে পড়াশোনা করবে বলেছিলে, তোমাকে বাইরেও পাঠিয়েছি। সেখানে বিজনেস স্টার্ট করতে চেয়েছিলে, সেটার পারমিশনও দিয়েছি। সব আবদার রেখেছি তোমার। এবার তোমাকেও আমার কথা শুনতে হবে।\nকথাটা বলেই ফোন কেটে দিলেন মানহাস চৌধুরী। বিরক্ত ভঙ্গিতে সোফায় হ্যালান দিয়ে বসলেন। পাশেই ওনার স্ত্রী নাসরিন চৌধুরী ওনার মুখপানে চেয়ে আছেন। স্ত্রীর দিকে তাকিয়ে তিনি বলে উঠলেন, "নাসরিন, চিন্তা করছো কেন এত? এবার আয়াজকে আমাদের কথা শুনতেই হবে। তারপরেও যদি দেশে না আসে, তাহলে আমি গিয়ে ওকে ওখান থেকে হিরহির করে টেনে নিয়ে আসবো। কথাটা মাথায় রেখো।"\nনাসরিন চৌধুরী বলে উঠলেন, "আমার দিকে এভাবে তাকাচ্ছো কেন? কথাগুলো এমনভাবে আমাকে বলছো, যেন আমি দেশের বাইরে আর আমি ওখান থেকে ফিরতে চাচ্ছি না। অদ্ভুত!"\nকথাটুকু বলেই বিরক্ত হয়ে তিনি চলে গেলেন। মানহাস চৌধুরী হাঁক ছেড়ে ডাকলেন, "নাসরিন, একটা কাপ চা দিও তো আমাকে! মাথাটা ভীষণ ধরে আছে আমার।"\nক্যালিফোর্নিয়ার নামকরা একটা প্রাইভেট ইউনিভার্সিটি। ইউনিভার্সিটির বাইরে দাঁড়িয়ে আছে একটা মেয়ে—পরনে জিন্স আর কমলা রঙের কুর্তি, গলায় স্কার্ফ পেঁচানো, চুলগুলো সুন্দর করে বাঁধা, গোলগাল চেহারাটা ভীষণ মায়াবী। প্রথম দেখাতে যে কেউ প্রেমে পড়তে বাধ্য। চেহারায় বিরক্তির ছাপ স্পষ্ট মেয়েটার। বিরক্তির কারণ অবশ্য তার সামনে দাঁড়িয়ে থাকা মানুষটা, কিন্তু সেই মানুষটার চেহারায় নির্লিপ্ত ভাব—এই যে এতক্ষণ ধরে পথ আটকে দাঁড়িয়ে আছে আর সে বিরক্ত হচ্ছে, অথচ সামনে দাঁড়িয়ে থাকা মানুষটার মাঝে বিন্দু মাত্র বিরক্তি কিংবা রাগ দেখা যাচ্ছে না, বরং সে মেয়েটার দিকে মুগ্ধতা ভরা দৃষ্টিতে তাকিয়ে আছে।\nভার্সিটি থেকে ক্লাস শেষ করে বেরোতেই মেয়েটির সামনে পথ আটকে দাঁড়ায়। ধৈর্যের সীমা অতিক্রম করে এক প্রকার বিরক্তির স্বরে মেয়েটিকে বলে উঠল, "আপনি কি সরবেন সামনে থেকে, নাকি আমি লোকজন ডেকে জড়ো করবো মিস্টার তানভীর?"\nমেয়েটার এমন ঝাঁজালো সরের কথায় বিন্দু মাত্র পার্থক্য দেখা গেল না তার চেহারায়। ৩০ বছর বয়সী যুবকটি এক দৃষ্টিতে মেয়েটির মুখপানে তাকিয়ে আছে। ফরমাল গেটআপের লোকটার চেহারার দিকে একবার তাকিয়ে মেয়েটা ফের বলে উঠল, "আমার ধৈর্যের সীমানা ছাড়িয়ে যাচ্ছে মিস্টার তানভীর, আমি আর কতবার বলব আমি আপনাকে ভালোবাসি না। শুধু শুধু এভাবে এসে আমাকে বিরক্ত করবেন না।"\nমেয়েটার কথা শুনে যুবকটা বিরক্ত হলো এবার।\nআজকে আমি তোমাদেরকে সবচেয়ে বিশ্বস্ত বুকমেকার ওয়ানএক্স সম্পর্কে বলতে চাই, যেটি পিজিডি এবং সিরিয়ার অফিসিয়াল পার্টনার। ফিফা বিশ্বকাপ শুরু হয়ে গিয়েছে, এটি হতে পারে সবচেয়ে বড় সুযোগ আপনার প্রিয় দলকে সমর্থন করেন। এই অ্যাপে আপনি ক্রিকেট, ফুটবল, টেনিস লাইভ ম্যাচ দেখতে এবং তাদের স্কোর ভবিষ্যদ্বাণী করে সহজেই অর্থ উপার্জন করতে পারবেন। সেই সাথে বিএমডব্লিউ গাড়ি, আইফোন, ল্যাপটপ এবং আরও অনেক নগদ পুরস্কার জেতার সুযোগ রয়েছে।\nএই অ্যাপটিতে আপনি ক্র্যাশ, ক্রিস্টাল, আন্ডার অ্যান্ড ওভার ২১ ইত্যাদি গেম খেলে সহজেই আয় করতে পারবেন। সাইনআপ করার সময় আমার প্রচার কোড ONEMARU ব্যবহার করে আপনার প্রথম জমাতে ২৪,০০০ টাকা পর্যন্ত পান। আপনি বিকাশ, নগদ, রকেট, উপায়, ব্যাংক, ক্রিপ্টো, পেপাল এবং অন্যান্য সহজ পদ্ধতির মাধ্যমে সহজেই আপনার জেতা টাকা তুলতে পারবেন।\nএখানে আপনি ২৪ ঘণ্টা ৭ দিন গ্রাহক সহায়তা পাবেন। তাই গুগলে ওয়ানএক্স সার্চ করে অফিসিয়াল ওয়েবসাইটে গিয়ে রেজিস্ট্রেশন করুন আর রেজিস্ট্রেশনের সময় অবশ্যই আমার প্রচার কোড ONEMARU ব্যবহার করে প্রথম ডিপোজিটে ২৪,০০০ টাকা পর্যন্ত পান।\nবিরক্তিসূচক একটা শব্দ অটোমেটিক বের হলো মুখ দিয়ে। একটু আগে বাবার কথাগুলো শুনে মাথা গরম হয়ে গিয়েছিল, এজন্যই মাথাটা ঠান্ডা করতে এসেছিল ভার্সিটির সামনে একটাবার মেয়েটাকে দেখবে বলে।\nকিন্তু মেয়েটা প্যান্টের পকেটে দু হাত গুজে সোজা হয়ে দাঁড়াল আয়াজ। কিন্তু মেয়েটা প্যান্টের পকেটে দু হাত গুজে সোজা হয়ে দাঁড়ালেও আয়াজ শান্ত দৃষ্টিতে মেয়েটার মুখপানে চেয়ে বলে উঠল, "সমস্যা কী আপনার শুভ্রতা? আপনি নাই ভালোবাসলেন আমায়, আমায় তো বাঁচতে দিন, দেখতে দিন আপনাকে।"\nসঙ্গে সঙ্গেই শুভ্রতার মাথায় রাগ চড়ে গেল। খানিকটা চেচিয়ে বলে উঠল, "ভীষণ অসভ্য লোক তো আপনি! একটা মেয়ে ভালোবাসে না আপনাকে। দিনের পর দিন আপনাকে ইগনোর করেই যাচ্ছে, আর আপনি সেই মেয়েটার পেছনে এখনো পড়ে আছেন? কেন ভালোবাসেন আমায়? ভালোবাসতে তো কোনো কারণ লাগে না শুভ্রতা।\nআপনাকে আমি আজ একদিন দুদিন নয়, গত দুটো বছর ধরে ভালোবাসি। সেটা তো আমিও জানি, এই দুটো বছর ধরে আমার জীবনটাকে শেষ করে দিচ্ছেন আপনি।"\nশুভ্রতার কথায় বিন্দুমাত্র চেহারার এক্সপ্রেশন পাল্টালো না আয়াজের। উল্টো কণ্ঠে দ্বিগুণ মুগ্ধতা নিয়ে বলল, "আপনি জানেন, আপনার এই রাগী কণ্ঠ শুনতে কতটা ভালো লাগে আমার! রাগ করলে ভীষণ সুন্দর লাগে আপনাকে। আপনার এই সব আজেবাজে কথা শোনার একটুও ইচ্ছে নেই আমার। আমার পিছু ছেড়ে দিন তানভীর।"\nকথাটা বলেই আয়াজকে ধাক্কা দিয়ে গডগড করে হেঁটে চলে গেল শুভ্রতা। ওর যাওয়ার পানে মুগ্ধ দৃষ্টিতে তাকিয়ে হাসলো আয়াজ। খানিকটা হেঁটে গিয়ে গাড়িতে বসে স্টার্ট দিতে দিতে আপন মনেই বলে উঠল, "যত খুশি ইগনোর করুন, যত খুশি এড়িয়ে যান, ভালো তো আমি আপনাকেই বাসবো শুভ্রতা। আপনার পিছু ছাড়া যে আমার পক্ষে সম্ভব নয়।"\nবাড়ির সামনে এসে কলিং বেল বাজাতে লাগল শুভ্রতা। দারোয়ান লোকটা এসে গেট খুলে দিতেই গডগড করে হেঁটে চলে গেল বাড়ির ভেতরে। আজ মেজাজটা ভীষণ গরম হয়ে আছে ওর। বাড়িতে ঢুকেই শুভ্রতা হাঁক ছাড়ল, "বাবা! ও বাবা! মা, কোথায় তোমরা? দ্রুত দেশে ব্যাক করার ব্যবস্থা করো তো। আমি আর এখানে এক মুহূর্তও থাকতে চাই না।"\nভেতরের রুম থেকে বেরিয়ে এলেন আরিস চৌধুরী। শুভ্রতা ততক্ষণে বসে পড়েছে লিভিং রুমের সোফায়। আরিস চৌধুরী এগিয়ে এসে জিজ্ঞেস করলেন, "কী ব্যাপার? টেম্পারেচার এত গরম কেন? তোমার এক্সাম আগামী কাল শুরু হবে, এক্সাম শেষ হলেই তো আমরা দেশে ফিরব।"\n"হুম, সেটাই করো। আমার আর এসব ভালো লাগছে না। দেশে ফিরে আয়াজ ভাইয়ের সাথে বিয়ের ব্যবস্থা করবে দ্রুত।"\nভেতরের রুম থেকে শুভ্রতার মা ফারহানা চৌধুরী বেরিয়ে এসে বললেন, "বাব্বা! সূর্য কোন দিকে উঠল আজ? সবসময় বিয়ের কথা শুনলে যে মেয়ে কোনো সাড়া-শব্দও করে না, সেই মেয়ে নিজে আজ আয়াজের নাম মুখে আনছে, আবার বিয়ের কথাও বলছে।"\nশুভ্রতা খানিকটা রেগে গিয়ে বলল, "আরে অদ্ভুত তো! আমি কি কখনো আয়াজ ভাইয়ের সঙ্গে বিয়ের ব্যাপারে অমত করেছি নাকি? আমি তো আপনাদের সিদ্ধান্তে রাজি, আমি ওনাকেই বিয়ে করব।"\nআলিনা একটা ট্রেতে করে খাবার নিয়ে ওর রুমে প্রবেশ করতে করতেই বলে উঠল, "তাহলে আয়াজের ছবি দেখতে চাও না কেন? সবসময়ই তো এড়িয়েই যাও।"\nশুভ্রতা ট্রে থেকে চায়ের কাপটা তুলে নিয়ে বলল, "ভাবী, উনি নিজেও তো একই দেশে থাকা সত্ত্বেও আমার সঙ্গে দেখা করতে চাইছে না। সেইজন্য আমি ঠিক করেছি দেশে ফিরে একেবারে ওনাকে দেখব।"\nআরিস চৌধুরী আর ফারহানা চৌধুরী শুভ্রতাকে ফ্রেস হয়ে রেস্ট নিতে বলে চলে গেলেন। আলিনা শুভ্রতার পাশে বসে বলে উঠল, "কী ব্যাপার বলতো ননদিনী, কী হয়েছে?"\nশুভ্রতা চায়ের কাপে চুমুক দিয়ে বলে উঠল, "একটা ছেলে আমায় প্রচুর ডিস্টার্ব করে, ভালোবাসে। কিন্তু আমি ওই ছেলেটাকে ভালোবাসি না ভাবী, তাই চাচ্ছি যত তাড়াতাড়ি সম্ভব দেশে ফিরে আয়াজ ভাইকে বিয়ে করতে। তাছাড়া আমার নিজেরও অ্যারেঞ্জ ম্যারেজের ইচ্ছা ছিল। প্রেমের বিয়ে পছন্দ নয় আমার, তাই ঠিক করেছি দেশে ফিরে ওনাকেই দেখব।"\nআলিনা মুচকি হেসে বলল, "বুঝলাম।"\nচা শেষ করে শুভ্রতা আলিনাকে জড়িয়ে ধরে বলল, "চাটা বেশ ভালো বানাও তুমি, সবসময় আমার জন্য তুমি চা বানিয়ে দেবে, ঠিক আছে?"\nআলিনা শুভ্রতার মাথার চুলগুলো এলোমেলো করে দিয়ে বলল, "অবশ্যই! একমাত্র ননদের জন্য প্রতিবেলায় চা করে দেওয়ার কোনো ব্যাপার নাকি! সবচেয়ে মজার ব্যাপার কি জানো, আমিও চা খেতে খেতে তোমার মতোই চা-খোর হয়ে যাচ্ছি শুভ্রতা। দিনে কয়েক কাপ চা না খেলে এখন আর চলেই না।"\nশুভ্রতা হেসে বলল, "ভালোই তো! কিন্তু ভাইয়া যেন না জানে।"\nসিঁড়ি দিয়ে ফরমাল গেটে নামতে নামতে একজন গম্ভীর গলায় বলল, "আমাকে না জানিয়ে কী করা হচ্ছে?"\nশুভ্রতা উঠে দাঁড়িয়ে বলল, "তেমন কিছুই না ভাইয়া, আমি শুধু বলছিলাম দেশে ব্যাক করার কথা।"\nআলিনা এগিয়ে গিয়ে বলল, "কোথায় যাচ্ছো সাদাব?"\nসাদা বেরিয়ে যেতে যেতেই জবাব দিল, "একটু কাজ আছে, আসছি আমি।"\nআলিনা দরজা পর্যন্ত এগিয়ে গিয়ে বলল, "আল্লাহ হাফেজ, সাবধানে যেও।"\nশুভ্রতার রুমে এসে ফ্রেস হলো। জামাকাপড় পাল্টে বিছানায় শরীর এলিয়ে দিয়ে ভাবতে লাগল আয়াজের কথা—ওর অনেকদিনের স্বপ্ন, যাকে বিয়ে করবে তাকে সপ্ন দিয়ে ভালোবাসবে। বিয়ের আগে এসব প্রেম-ভালোবাসা মোটেও পছন্দ নয় শুভ্রতার। তাই তো এতদিন সমস্ত প্রেমের প্রস্তাব প্রত্যাখ্যান করে এসেছে। এসব মনে হতেই হঠাৎ তানভীরের কথা মনে পড়ে গেল।\nছেলেটা যদিও আট-দশটা ছেলের মতো ওকে ইভটিজিং করে না, কিংবা বাজে কোনো মন্তব্য করে না, তবুও তাকে ভালো লাগে না শুভ্রতার। ছেলেটা ওকে দু বছর যাবত ভালোবাসে, সবসময় সামনে না এলেও দূর থেকে ওকে দেখে। যে জিনিসটা মোটেও পছন্দ নয় শুভ্রতার। তানভীরের কথা মাথা থেকে ঝেড়ে ফেলতে উঠে পড়ল শুভ্রতা।\nএই ছেলেকে নিয়ে কিছুতেই ভাবতে চায় না সে। রুম থেকে বেরিয়ে পাশের ছোট রুমটাতে গেল শুভ্রতা। এই রুমটাকে এক প্রকার লাইব্রেরি বলা চলে। শুভ্রতা বই পড়তে ভীষণ ভালোবাসে। বই কিনে কিনে এখানটায় একটা ছোটখাটো লাইব্রেরি বানিয়ে ফেলেছে। রুমের বাদিকের বড় বুকশেলফটা থেকে ওদের পারিবারিক অ্যালবামটা নামিয়ে আনল। অতঃপর রুমে এসে বিছানায় বসে ছবিগুলো দেখতে লাগল।\nওর বাবা আর চাচা—দুই পরিবারের একসঙ্গে ছবি। বাবার কোলে শুভ্রতা, তখন ওর বয়স দুই বছর। একপাশে ওর বড় ভাই সাদাব আর শুভ্রতার পাশেই দাঁড়ানো ছয়-সাত বছর বয়সী একটা ছেলে। ছেলেটা হাসিমুখে ছোট শুভ্রতার দিকে তাকিয়ে আছে। ছেলেটার ছবির উপর হাত রেখেই শুভ্রতা মুচকি হাসল। বিড়বিড় করে বলল, "আপনার সঙ্গে খুব শীঘ্রই দেখা হচ্ছে।"\n\n\nচলবে...!','\n',char(10)),1,'published',0,'2026-10-26T09:53:41.295Z','2026-10-26T09:53:41.295Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('a5d2ef78-e381-4b68-af0a-d2febb635230','1df7c77d-8240-40f9-afc8-dd3d55cd850b','পর্ব ১',replace('বিকেলের আকাশটা হঠাৎ করেই কালো হয়ে এল। চারদিকে ঠান্ডা বাতাস, আর কিছুক্ষণের মধ্যেই শুরু হলো ঝুম বৃষ্টি।\n\nআরিফ কলেজ থেকে বাড়ি ফিরছিল। বৃষ্টি দেখে রাস্তার পাশের একটি চায়ের দোকানে আশ্রয় নিল সে। হাতে ফোন, কানে হেডফোন—মনে মনে একটি গান শুনছিল।\n\nঠিক তখনই একটি মেয়ে দৌড়ে এসে দোকানের ছাউনির নিচে দাঁড়াল। মেয়েটির নাম নীলাঞ্জনা। তার লম্বা চুলগুলো বৃষ্টিতে ভিজে গিয়েছিল।\n\nআরিফ একবার তাকিয়েই থমকে গেল।\n\nমেয়েটি বিরক্ত হয়ে বলল, “উফ! আজকেই বৃষ্টি হতে হলো!”\n\nআরিফ হেসে বলল, “বৃষ্টি না হলে তো আপনার সঙ্গে দেখাই হতো না!”\n\nনীলাঞ্জনা তার দিকে তাকিয়ে বলল, “আপনি কি সবার সঙ্গেই এভাবে কথা বলেন?”\n\n“না,” আরিফ মুচকি হেসে উত্তর দিল, “শুধু যাদের দেখলে কথা বলতে ইচ্ছে করে, তাদের সঙ্গে।”\n\nনীলাঞ্জনা মুখ ঘুরিয়ে হাসল। সেই হাসিটা আরিফের মনে অদ্ভুত এক অনুভূতি তৈরি করল।\n\nকিছুক্ষণ পর বৃষ্টি আরও বেড়ে গেল। নীলাঞ্জনা বারবার রাস্তার দিকে তাকাচ্ছিল। আরিফ জিজ্ঞেস করল, “কাউকে অপেক্ষা করছেন?”\n\n“না, বাড়ি যাব। কিন্তু বৃষ্টি থামছে না।”\n\nআরিফ নিজের ছাতাটা এগিয়ে দিয়ে বলল, “চলুন, আপনাকে একটু এগিয়ে দিই।”\n\nনীলাঞ্জনা প্রথমে রাজি হচ্ছিল না। পরে ছাতার নিচে দুজন পাশাপাশি হাঁটতে শুরু করল। তাদের হাত দুটো মাঝে মাঝে ছুঁয়ে যাচ্ছিল। দুজনেই চুপ, অথচ মনে হচ্ছিল কত কথা জমে আছে!\n\nবাড়ির সামনে এসে নীলাঞ্জনা বলল, “আপনার নামটা তো জানা হলো না!”\n\n“আরিফ। আপনার?”\n\n“নীলাঞ্জনা।”\n\nআরিফ হেসে বলল, “নামটা আপনার মতোই সুন্দর।”\n\nনীলাঞ্জনা লজ্জা পেয়ে বলল, “আচ্ছা, আর কথা বলতে হবে না। এবার যান!”\n\nযাওয়ার আগে আরিফ সাহস করে জিজ্ঞেস করল, “আবার কি দেখা হবে?”\n\nনীলাঞ্জনা মিষ্টি করে হেসে বলল, “হয়তো… যদি আবার বৃষ্টি হয়!”\n\nসেদিন রাতে আরিফের চোখে ঘুম এল না। বারবার তার মনে পড়ছিল নীলাঞ্জনার হাসিটা। অন্যদিকে নীলাঞ্জনাও জানালার পাশে বসে বৃষ্টির শব্দ শুনছিল, আর ভাবছিল—ছেলেটা সত্যিই অদ্ভুত!\n\nহঠাৎ তার ফোনে একটি অচেনা নম্বর থেকে মেসেজ এল।\n\n“বৃষ্টি থেমে গেছে, কিন্তু আপনাকে নিয়ে ভাবনাটা থামছে না। —আরিফ ❤️”\n\nনীলাঞ্জনার মুখে হাসি ফুটে উঠল।\n\nসে উত্তর দিল, “এত তাড়াতাড়ি কাউকে নিয়ে ভাবা কি ঠিক?”\n\nআরিফ লিখল, “জানি না ঠিক কি না, তবে আপনার সঙ্গে আবার কথা বলতে খুব ইচ্ছে করছে।”\n\nনীলাঞ্জনা কিছুক্ষণ চুপ করে থেকে লিখল—\n\n“তাহলে কাল কলেজের সামনে দেখা হবে। তবে একটা শর্ত আছে!”\n\nআরিফ অবাক হয়ে লিখল, “কী শর্ত?”\n\nউত্তর এল—\n\n“কাল কিন্তু চা খাওয়াতে হবে! ❤️”\n\nআরিফ ফোনের দিকে তাকিয়ে হাসল। সে জানত না, এই ছোট্ট পরিচয় একদিন তার জীবনের সবচেয়ে গভীর ভালোবাসায় পরিণত হবে।\n\nচলবে… 💕','\n',char(10)),1,'published',0,'2026-10-26T13:58:27.958Z','2026-10-26T13:58:27.958Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('738081a5-6180-4d83-87a5-27d6e0d286a2','1df7c77d-8240-40f9-afc8-dd3d55cd850b','পর্ব ২',replace('সকালের সূর্যটা তখন ধীরে ধীরে উঁকি দিচ্ছে। আরিফ আজ অন্য দিনের চেয়ে অনেক আগেই ঘুম থেকে উঠেছে। কারণ আজ তার নীলাঞ্জনার সঙ্গে দেখা হবে!\n\nআয়নার সামনে দাঁড়িয়ে চুল ঠিক করতে করতে সে নিজেই হেসে ফেলল।\n\nনিজেকে বলল, “আরে বোকা, শুধু এক কাপ চা খেতে যাবি, নাকি বিয়ে করতে যাচ্ছিস?”\n\nকিন্তু মনের ভেতর যে ঝড় চলছে, সেটা সে নিজেও বুঝতে পারছিল না।\n\nঅন্যদিকে নীলাঞ্জনাও আজ একটু বেশি যত্ন করে তৈরি হয়েছে। বান্ধবী মিতু তাকে দেখে বলল, “কিরে, আজ এত সাজগোজ কেন? কারও সঙ্গে দেখা আছে নাকি?”\n\nনীলাঞ্জনা লজ্জা পেয়ে বলল, “না রে! এমনিই।”\n\nমিতু হেসে বলল, “আচ্ছা, এমনিই বুঝলাম। তোর গালের লাল রংটাই সব বলে দিচ্ছে!”\n\nদুপুরে কলেজের সামনে আরিফ দাঁড়িয়ে ছিল। নীলাঞ্জনাকে দেখেই তার মুখে হাসি ফুটে উঠল।\n\n“আপনি দেরি করেছেন,” আরিফ বলল।\n\nনীলাঞ্জনা ভ্রু কুঁচকে বলল, “মাত্র পাঁচ মিনিট! আর আপনি কতক্ষণ ধরে দাঁড়িয়ে আছেন?”\n\n“আপনার জন্য অপেক্ষা করতে করতে পাঁচ মিনিটও পাঁচ ঘণ্টা মনে হয়েছে।”\n\nনীলাঞ্জনা হেসে ফেলল।\n\nদুজন রাস্তার পাশের ছোট্ট একটি চায়ের দোকানে গেল। আরিফ দুই কাপ চা অর্ডার করল। চায়ের কাপ হাতে নিয়ে নীলাঞ্জনা বলল, “আচ্ছা, আপনি সবার সঙ্গে এত সুন্দর করে কথা বলেন কেন?”\n\nআরিফ একটু চুপ করে থেকে বলল, “সবার সঙ্গে তো কথা বলি, কিন্তু সবার কথা সারাদিন মনে পড়ে না।”\n\nনীলাঞ্জনা তার দিকে তাকাল। কথাটা শুনে তার বুকের ভেতর কেমন যেন হলো।\n\n“আমার কথা কি আপনার মনে পড়ে?” সে আস্তে করে জিজ্ঞেস করল।\n\nআরিফ মুচকি হেসে বলল, “গতকাল রাতে আপনার মেসেজের অপেক্ষায় কতবার যে ফোন দেখেছি, সেটা যদি বলি, আপনি হাসবেন।”\n\nনীলাঞ্জনা কিছু বলল না। শুধু চায়ের কাপে চুমুক দিল। তার ঠোঁটের কোণে ছোট্ট একটা হাসি লেগে রইল।\n\nচা খাওয়ার পর দুজন হাঁটতে বের হলো। রাস্তার পাশের কৃষ্ণচূড়া গাছের নিচে এসে নীলাঞ্জনা থামল।\n\n“আরিফ, একটা কথা জিজ্ঞেস করব?”\n\n“অবশ্যই।”\n\n“আপনি কি আমাকে সত্যিই পছন্দ করেন, নাকি শুধু মজা করছেন?”\n\nআরিফের মুখের হাসি মিলিয়ে গেল। সে কিছুক্ষণ নীরব থেকে বলল, “নীলাঞ্জনা, আমি জানি না ভালোবাসা কতটা সুন্দর করে প্রকাশ করতে হয়। কিন্তু একটা কথা জানি—আপনার সঙ্গে কথা বললে আমার মন ভালো হয়ে যায়। আপনার মন খারাপ থাকলে আমারও খারাপ লাগে। আমি আপনার হাসির কারণ হতে চাই, কষ্টের কারণ নয়।”\n\nনীলাঞ্জনার চোখ দুটো ভিজে উঠল।\n\n“কেউ আগে কখনো আমাকে এভাবে বলেনি,” সে ফিসফিস করে বলল।\n\nআরিফ নরম গলায় বলল, “তাহলে আজ থেকে মনে রাখবেন।”\n\nফেরার সময় নীলাঞ্জনা হঠাৎ বলল, “আরিফ?”\n\n“হ্যাঁ?”\n\n“কালও কি দেখা হবে?”\n\nআরিফ হেসে বলল, “আপনি চাইলে প্রতিদিনই হবে।”\n\nনীলাঞ্জনা মিষ্টি করে হাসল। তারপর চলে যাওয়ার আগে বলল, “তাহলে কাল আমাকে একটা সুন্দর জায়গায় নিয়ে যাবেন।”\n\nসেদিন রাতে দুজনেরই ঘুম আসতে দেরি হলো। দুজনেই ভাবছিল, এই অনুভূতিটা কি শুধু বন্ধুত্ব, নাকি এর নাম ভালোবাসা?\n\nহঠাৎ আরিফের ফোনে নীলাঞ্জনার মেসেজ এল।\n\n“শুনুন, আজ আপনাকে একটা কথা বলতে ইচ্ছে করছে।”\n\nআরিফ দ্রুত উত্তর দিল, “বলুন, শুনছি।”\n\nকিছুক্ষণ পর মেসেজ এল—\n\n“আপনার সঙ্গে থাকলে আমার খুব ভালো লাগে। জানি না কেন, কিন্তু আপনার সঙ্গে কথা না বললে দিনটা অসম্পূর্ণ মনে হয়। ❤️”\n\nআরিফের হৃদয়টা যেন আনন্দে ভরে উঠল।\n\nসে লিখল, “নীলাঞ্জনা, আমারও ঠিক একই রকম লাগে।”\n\nকিন্তু ঠিক তখনই নীলাঞ্জনার ফোনে আরেকটি কল এল। স্ক্রিনে একটি নাম ভেসে উঠল—রাহুল।\n\nকলটি দেখে নীলাঞ্জনার মুখটা হঠাৎ গম্ভীর হয়ে গেল।\n\nরাহুল কে? তার সঙ্গে নীলাঞ্জনার কী সম্পর্ক?\n\nআরিফ তখনও জানত না, তাদের নতুন ভালোবাসার গল্পে এমন একজন আসতে চলেছে, যে সবকিছু বদলে দিতে পারে।\n\nচলবে… ❤️','\n',char(10)),2,'published',0,'2026-10-26T14:01:18.591Z','2026-10-26T14:01:18.591Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('7545f902-484d-4126-8cb0-9d0af9724ef3','1df7c77d-8240-40f9-afc8-dd3d55cd850b','পর্ব ৩',replace('রাত তখন প্রায় এগারোটা। আরিফ ফোন হাতে নিয়ে বসে আছে। নীলাঞ্জনার সঙ্গে কথা বলতে বলতে হঠাৎ সে চুপ হয়ে গেছে। কারণ কিছুক্ষণ আগে নীলাঞ্জনার ফোনে রাহুলের কল এসেছিল।\n\nআরিফের মনে হাজারটা প্রশ্ন ঘুরপাক খাচ্ছিল।\n\nরাহুল কে? নীলাঞ্জনার জীবনে কি আগে থেকেই কেউ আছে?\n\nঅনেকক্ষণ পর সে সাহস করে মেসেজ দিল।\n\nআরিফ: আচ্ছা, রাহুল কে?\n\nনীলাঞ্জনা: কেন? হঠাৎ রাহুলের কথা জিজ্ঞেস করছেন কেন?\n\nআরিফ: না, এমনি। আপনার ফোনে ওর নাম দেখলাম, তাই জানতে চাইলাম।\n\nকিছুক্ষণ কোনো উত্তর এল না। তারপর নীলাঞ্জনা লিখল—\n\nনীলাঞ্জনা: রাহুল আমার ছোটবেলার বন্ধু। কিন্তু ও আমাকে শুধু বন্ধু ভাবে কি না, সেটা আমি জানি না।\n\nমেসেজটা পড়ে আরিফের বুকের ভেতরটা কেমন যেন করে উঠল।\n\nআরিফ: ও কি আপনাকে ভালোবাসে?\n\nনীলাঞ্জনা: একসময় বলেছিল। কিন্তু আমি ওকে কখনো সেই চোখে দেখিনি।\n\nআরিফ দীর্ঘশ্বাস ফেলল। তবুও মনের ভেতরের ভয়টা দূর হলো না।\n\nপরদিন বিকেলে নীলাঞ্জনা আরিফকে পার্কে দেখা করতে বলল। আরিফ পৌঁছে দেখল, নীলাঞ্জনা একটি বেঞ্চে বসে আছে। তার মুখটা আজ অন্য দিনের মতো হাসিখুশি নয়।\n\nআরিফ পাশে বসে জিজ্ঞেস করল, “কী হয়েছে? মন খারাপ?”\n\nনীলাঞ্জনা মাথা নিচু করে বলল, “রাহুল গতকাল আমাকে বলেছে, আমি যেন আপনার সঙ্গে আর কথা না বলি।”\n\nআরিফ চুপ করে রইল।\n\nনীলাঞ্জনা আবার বলল, “ও বলেছে, আমি নাকি ভুল করছি। আপনি নাকি একদিন আমাকে ছেড়ে চলে যাবেন।”\n\nআরিফের চোখে কষ্ট ফুটে উঠল। সে ধীরে ধীরে বলল, “আপনি কি ওর কথা বিশ্বাস করেন?”\n\nনীলাঞ্জনা সঙ্গে সঙ্গে তার দিকে তাকাল।\n\n“না! কিন্তু একটা কথা আমাকে ভয় দেখায়।”\n\n“কী কথা?”\n\nনীলাঞ্জনা কাঁপা কণ্ঠে বলল, “যদি কোনো দিন আপনিও আমাকে ছেড়ে চলে যান?”\n\nআরিফ কিছুক্ষণ তার দিকে তাকিয়ে রইল। তারপর বলল, “নীলাঞ্জনা, আমি ভবিষ্যৎ দেখতে পারি না। জীবনে কী হবে, সেটাও জানি না। কিন্তু আজ আমি আপনার পাশে আছি, আর আপনার বিশ্বাসের মর্যাদা রাখতে চাই।”\n\nনীলাঞ্জনার চোখ বেয়ে এক ফোঁটা জল গড়িয়ে পড়ল।\n\nআরিফ আস্তে করে বলল, “একটা সম্পর্ক শুধু মিষ্টি কথা দিয়ে টিকে থাকে না। বিশ্বাস, সম্মান আর দুজনের চেষ্টা লাগে। আপনি যদি আমাকে বিশ্বাস করেন, তাহলে আমরা একসঙ্গে সব সমস্যার মুখোমুখি হব।”\n\nনীলাঞ্জনা মৃদু হেসে বলল, “আমি আপনাকে বিশ্বাস করতে চাই, আরিফ।”\n\nআরিফও হাসল।\n\nসেদিন বিকেলে তারা অনেকক্ষণ পার্কে বসে গল্প করল। সূর্য ডুবে গেল, আকাশে সন্ধ্যা নামল, তবুও কেউ বাড়ি ফিরতে চাইছিল না।\n\nবাড়ি ফেরার আগে নীলাঞ্জনা বলল, “আরিফ, একটা কথা বলব?”\n\n“বলুন।”\n\n“আপনাকে হারাতে চাই না আমি।”\n\nআরিফের ঠোঁটে হাসি ফুটে উঠল। “তাহলে আমাকে দূরে ঠেলে দেবেন না কখনো।”\n\nনীলাঞ্জনা মাথা নাড়ল।\n\nকিন্তু তাদের অজান্তেই দূরে দাঁড়িয়ে কেউ একজন সবকিছু দেখছিল।\n\nসে রাহুল।\n\nতার চোখে রাগ, আর মনে জমে থাকা অভিমান। সে ফোন বের করে কাউকে কল করল।\n\n“হ্যালো, একটা কাজ করতে হবে তোমাকে। আরিফ নামের ছেলেটাকে একটু খোঁজ নিয়ে দেখো।”\n\nকল কেটে রাহুল ঠান্ডা গলায় বলল, “দেখি, নীলাঞ্জনা… তোমার এই ভালোবাসা কত দিন টেকে।”\n\nচলবে… 💔❤️\n\nপরের পর্বে রাহুল কি আরিফের জীবনে নতুন বিপদ নিয়ে আসবে, নাকি নীলাঞ্জনার ভালোবাসা সব বাধা জয় করবে?','\n',char(10)),3,'published',0,'2026-10-26T14:03:28.017Z','2026-10-26T14:03:28.017Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('c1ebed35-2575-477a-8fa6-e0edecdce0cf','95b4cdd4-4d37-4bb2-ba1c-996e967b1061','পর্ব 1',replace('বিকেলের আকাশটা আজ অদ্ভুত সুন্দর। পশ্চিম আকাশে সূর্যটা ধীরে ধীরে ডুবে যাচ্ছে। চারপাশে হালকা বাতাস, গাছের পাতায় পাতায় এক অদ্ভুত মায়াবী শব্দ। রাস্তার পাশে কৃষ্ণচূড়া গাছের নিচে দাঁড়িয়ে আছে একটি মেয়ে। পরনে সাদা সালোয়ার-কামিজ, কাঁধে গোলাপি ওড়না, আর চোখে একরাশ স্বপ্ন।\n\nমেয়েটির নাম মায়া।\n\nমায়া খুব সাধারণ একটি মেয়ে। তার জীবনে বড় কোনো চাওয়া নেই। ছোট্ট একটি পরিবার, কিছু আপন মানুষ আর একটুখানি ভালোবাসা—এই নিয়েই তার পৃথিবী। সে বিশ্বাস করে, সত্যিকারের ভালোবাসা কখনো সৌন্দর্য কিংবা অর্থের হিসাব করে না। ভালোবাসা শুধু মনের ভাষা বোঝে।\n\nকিন্তু মায়া জানে না, আজকের এই বিকেলটাই তার জীবনের গল্প বদলে দিতে চলেছে।\n\nহঠাৎ করেই আকাশ কালো হয়ে এল। কয়েক মুহূর্তের মধ্যেই শুরু হলো বৃষ্টি। রাস্তার মানুষজন যে যার মতো আশ্রয় খুঁজতে ব্যস্ত হয়ে পড়ল। মায়াও দ্রুত পাশের একটি দোকানের ছাউনির নিচে গিয়ে দাঁড়াল।\n\nঠিক তখনই তার পাশে এসে দাঁড়াল একটি ছেলে।\n\nছেলেটির পরনে কালো শার্ট, হাতে একটি ঘড়ি। মুখে গম্ভীর ভাব, চোখে অদ্ভুত এক গভীরতা। বৃষ্টির পানিতে তার চুল ভিজে কপালের ওপর এসে পড়েছে।\n\nমায়া একবার ছেলেটির দিকে তাকিয়ে আবার চোখ ফিরিয়ে নিল।\n\nছেলেটিও মেয়েটির দিকে তাকাল। কিছুক্ষণ চুপ করে থাকার পর বলল,\n\n“আপনি কি সব সময় এভাবে বৃষ্টির মধ্যে একা দাঁড়িয়ে থাকেন?”\n\nমায়া একটু অবাক হয়ে তাকাল।\n\n“কেন? বৃষ্টিতে দাঁড়ানো কি অপরাধ?”\n\nছেলেটি মৃদু হাসল।\n\n“অপরাধ নয়। তবে বৃষ্টি থামার অপেক্ষায় থাকতে থাকতে যদি ঠান্ডা লেগে যায়, তখন কিন্তু বৃষ্টিকে দোষ দিয়ে লাভ হবে না।”\n\nমায়া মুখ ঘুরিয়ে বলল,\n\n“আপনাকে আমার চিন্তা করতে হবে না।”\n\nছেলেটি আর কিছু বলল না। শুধু মৃদু হেসে সামনের দিকে তাকিয়ে রইল।\n\nকয়েক মিনিট পর বৃষ্টি একটু কমে এল। মায়া রাস্তা পার হওয়ার জন্য এগিয়ে যেতেই একটি দ্রুতগতির গাড়ি পাশ দিয়ে চলে গেল। রাস্তার জমে থাকা পানি ছিটকে তার সাদা পোশাকে লাগল।\n\nমায়া বিরক্ত হয়ে দাঁড়িয়ে পড়ল।\n\n“আজকের দিনটাই খারাপ!”\n\nপাশ থেকে ছেলেটির হাসির শব্দ শোনা গেল।\n\nমায়া চোখ বড় করে বলল,\n\n“আপনি হাসছেন কেন?”\n\n“না, মানে আপনার রাগ করার ধরনটা একটু অন্য রকম।”\n\n“আপনি কি আমাকে নিয়ে মজা করছেন?”\n\n“একদমই না। তবে আপনার রাগী মুখটা বেশ সুন্দর।”\n\nকথাটা শুনে মায়া কয়েক মুহূর্ত চুপ করে রইল। জীবনে অনেক প্রশংসা সে শুনেছে, কিন্তু এই অচেনা ছেলেটির মুখে কথাটা শুনে কেন যেন তার বুকের ভেতর অদ্ভুত একটা অনুভূতি হলো।\n\nসে দ্রুত চোখ ফিরিয়ে বলল,\n\n“আপনি অপরিচিত মানুষের সঙ্গে একটু বেশিই কথা বলেন।”\n\nছেলেটি এবার গম্ভীর হয়ে বলল,\n\n“হতে পারে। তবে সব অপরিচিত মানুষই যে সারাজীবন অপরিচিত থাকে, তা তো নয়।”\n\nমায়া কথাটার উত্তর খুঁজে পেল না।\n\nঠিক তখনই তার ফোন বেজে উঠল।\n\nফোনের ওপাশ থেকে মায়ার বান্ধবী নীলা বলল,\n\n“কোথায় তুই? কতক্ষণ ধরে অপেক্ষা করছি!”\n\nমায়া বলল,\n\n“এই তো, আসছি। একটু বৃষ্টিতে আটকে গিয়েছিলাম।”\n\nকথা শেষ করে ফোনটা ব্যাগে রাখতেই ছেলেটি জিজ্ঞেস করল,\n\n“আপনার নামটা কি জানতে পারি?”\n\nমায়া কিছুক্ষণ তার দিকে তাকিয়ে থেকে বলল,\n\n“মায়া।”\n\nছেলেটি নামটা একবার মনে মনে উচ্চারণ করল।\n\n“মায়া! সুন্দর নাম।”\n\nমায়া হালকা হেসে বলল,\n\n“ধন্যবাদ। আপনার নাম?”\n\nছেলেটি উত্তর দিল,\n\n“আরিশ।”\n\nনামটা বলেই সে একটু থামল। তারপর বলল,\n\n“আশা করি আবার দেখা হবে, মায়া।”\n\nমায়া মৃদু হেসে চলে গেল। যাওয়ার আগে একবার পেছনে ফিরে তাকিয়েছিল কি না, সেটা সে নিজেও ঠিক বুঝতে পারেনি।\n\nকিন্তু আরিশ তাকিয়ে ছিল।\n\nমেয়েটি যতক্ষণ দেখা গেল, ততক্ষণ সে সেদিকেই তাকিয়ে রইল। তারপর নিজের অজান্তেই ঠোঁটের কোণে হাসি ফুটে উঠল।\n\nকেন এমন হলো, সে জানে না।\n\nশুধু মনে হলো, আজকের বিকেলটা অন্য রকম।\n\nঅন্যদিকে, কিছুটা দূরে গিয়ে মায়া নিজের মনকে প্রশ্ন করল,\n\n“ছেলেটা এমন অদ্ভুত কেন?”\n\nপরক্ষণেই নিজেকে ধমক দিয়ে বলল,\n\n“ধুর! একটা অপরিচিত ছেলে। আর কখনো দেখা হবে কি না, তারই ঠিক নেই।”\n\nকিন্তু মানুষের জীবনে কিছু কিছু দেখা হয়, যেগুলোকে সামান্য ঘটনা ভেবে ভুল করা যায়।\n\nঅথচ সেই ঘটনাই একদিন জীবনের সবচেয়ে গুরুত্বপূর্ণ অধ্যায় হয়ে ওঠে।\n\nসন্ধ্যায় বাড়ি ফিরে মায়া জানালার পাশে বসে ছিল। বাইরে তখনো হালকা বৃষ্টি পড়ছে। তার হাতে এক কাপ চা, চোখ জানালার ওপারে।\n\nহঠাৎ করেই মনে পড়ল ছেলেটির কথা।\n\n“সব অপরিচিত মানুষই যে সারাজীবন অপরিচিত থাকে, তা তো নয়।”\n\nকথাটা মনে পড়তেই মায়া নিজের অজান্তে হেসে ফেলল।\n\nঠিক তখনই নীলা ফোন করল।\n\n“কী রে, তোর গলায় এত হাসি কেন? কাউকে পেয়েছিস নাকি?”\n\nমায়া চমকে উঠল।\n\n“কী সব বলিস! তেমন কিছু না।”\n\nনীলা দুষ্টুমি করে বলল,\n\n“তেমন কিছু না হলে এত লজ্জা পাচ্ছিস কেন?”\n\n“আমি লজ্জা পাচ্ছি না!”\n\n“আচ্ছা, আচ্ছা। বিশ্বাস করলাম। এবার বল, ঘটনাটা কী?”\n\nমায়া কিছুক্ষণ চুপ থেকে বলল,\n\n“আজ একটা ছেলের সঙ্গে দেখা হয়েছিল। বৃষ্টির সময়।”\n\nনীলা সঙ্গে সঙ্গে উত্তেজিত হয়ে উঠল।\n\n“তারপর? দেখতে কেমন? নাম কী? কথা হয়েছে?”\n\nমায়া হেসে বলল,\n\n“এত প্রশ্ন একসঙ্গে করিস না। নাম আরিশ।”\n\nনীলা একটু থেমে বলল,\n\n“আরিশ! নামটা তো সুন্দর। আবার দেখা হলে আমাকে কিন্তু সব বলবি।”\n\nমায়া কথাটা হেসে উড়িয়ে দিল।\n\nসে তখনো জানত না, আরিশ নামের সেই ছেলেটি খুব শিগগিরই তার জীবনের এমন একজন হয়ে উঠবে, যাকে ভুলে থাকার চেষ্টা করেও ভুলতে পারবে না।\n\nআর শহরের অন্য প্রান্তে, নিজের ঘরের জানালার পাশে দাঁড়িয়ে আরিশও বৃষ্টি দেখছিল।\n\nতার ফোনে একের পর এক কল আসছিল, কিন্তু সেদিকে তার কোনো মনোযোগ ছিল না।\n\nতার মনে শুধু একটি নাম ঘুরছিল।\n\nমায়া।\n\nহঠাৎ পেছন থেকে একটি কণ্ঠ ভেসে এল,\n\n“ভাইয়া, কী হয়েছে তোমার? আজ এত চুপচাপ কেন?”\n\nআরিশ ফিরে তাকাল। তার ছোট বোন রাইসা দরজায় দাঁড়িয়ে আছে।\n\nআরিশ স্বাভাবিক হওয়ার চেষ্টা করে বলল,\n\n“কিছু হয়নি। তুই এখানে কী করছিস?”\n\nরাইসা চোখ ছোট করে তাকাল।\n\n“কিছু হয়নি? তোমার মুখ দেখে তো মনে হচ্ছে জীবনে প্রথমবার কারও প্রেমে পড়েছ!”\n\nআরিশ হেসে উঠল।\n\n“তোর মাথায় সব সময় এসবই ঘোরে?”\n\nরাইসা দুষ্টুমি করে বলল,\n\n“তাহলে সত্যিই কেউ আছে?”\n\nআরিশ উত্তর দিল না। আবার জানালার বাইরে তাকাল।\n\nসে নিজেও জানত না, মায়ার সঙ্গে দেখা হওয়াটা নিছক কাকতালীয়, নাকি তার জীবনের নতুন কোনো গল্পের শুরু।\n\nকিন্তু একটা বিষয় সে বুঝতে পারছিল।\n\nমেয়েটির চোখে এমন কিছু ছিল, যা তাকে বারবার সেই চোখ দুটির কথা মনে করিয়ে দিচ্ছিল।\n\nআর এই প্রথমবার, কোনো অচেনা মানুষের সঙ্গে আবার দেখা হওয়ার অপেক্ষা করতে ইচ্ছে করছিল তার।\n\nকিন্তু ভাগ্য কি এত সহজে তাদের আবার দেখা করাবে?\n\nনাকি তাদের গল্পের শুরুতেই অপেক্ষা করছে এমন কোনো রহস্য, যা তাদের দুজনের জীবন বদলে দেবে?\n\nসেই উত্তর লুকিয়ে আছে আগামী দিনের পাতায়।\n\nচলবে...','\n',char(10)),1,'published',0,'2026-10-26T14:28:13.946Z','2026-10-26T14:28:13.946Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('a3e8cedc-7aac-42f0-98cb-7737c5c67002','95b4cdd4-4d37-4bb2-ba1c-996e967b1061','পর্ব 2',replace('সকালের মিষ্টি রোদ জানালার পর্দা ভেদ করে ঘরের ভেতরে এসে পড়েছে। পাখির ডাক আর মায়ের রান্নাঘরের শব্দে ঘুম ভাঙল মায়ার।\n\nমায়া চোখ খুলে কিছুক্ষণ ছাদের দিকে তাকিয়ে রইল। তারপর হঠাৎ করেই গতকালের বিকেলের কথা মনে পড়ে গেল।\n\nকালো শার্ট পরা ছেলেটা, তার মৃদু হাসি আর সেই অদ্ভুত কথাটা।\n\n“সব অপরিচিত মানুষই যে সারাজীবন অপরিচিত থাকে, তা তো নয়।”\n\nমায়া নিজের মনেই বিড়বিড় করল,\n\n“কী যে বলেছিল ছেলেটা! আর আমি কিনা এখনো কথাটা মনে রেখেছি!”\n\nঠিক তখনই দরজার বাইরে থেকে মায়ের ডাক এল।\n\n“মায়া, আর কত ঘুমাবি? সকাল হয়ে গেছে। আজ না তোর কলেজে যেতে হবে?”\n\nমায়া তাড়াতাড়ি বিছানা ছেড়ে উঠে পড়ল।\n\n“হ্যাঁ মা, উঠছি!”\n\nকিছুক্ষণের মধ্যেই তৈরি হয়ে নিচে নেমে এল সে। নাশতার টেবিলে বসে রুটি খেতে খেতে মায়ের দিকে তাকিয়ে বলল,\n\n“মা, আজ একটু তাড়াতাড়ি বের হব।”\n\nমা অবাক হয়ে জিজ্ঞেস করলেন,\n\n“কেন? আজ আবার কী হলো?”\n\n“কিছু না মা। নীলার সঙ্গে একটা কাজ আছে।”\n\nমা হেসে বললেন,\n\n“আচ্ছা, সাবধানে যাস।”\n\nমায়া ব্যাগ কাঁধে নিয়ে বাড়ি থেকে বেরিয়ে পড়ল।\n\nকিন্তু সে জানত না, আজকের দিনটা তার জন্য আরও বড় একটা চমক নিয়ে অপেক্ষা করছে।\n\nকলেজের সামনে পৌঁছাতেই নীলা দৌড়ে এসে তার হাত ধরল।\n\n“এই যে মহারানি! কাল রাতে তো তোর ঘুমই হয়নি, তাই না?”\n\nমায়া চোখ পাকিয়ে বলল,\n\n“আবার শুরু করলি?”\n\nনীলা হাসতে হাসতে বলল,\n\n“আচ্ছা, আর কিছু বলব না। শুধু একটা প্রশ্নের উত্তর দে।”\n\n“কী প্রশ্ন?”\n\n“কালকের সেই আরিশ নামের ছেলেটার কথা এখনো মনে আছে?”\n\nমায়া মুখ ঘুরিয়ে বলল,\n\n“না।”\n\nনীলা ভ্রু উঁচু করল।\n\n“সত্যি?”\n\n“হ্যাঁ, সত্যি!”\n\n“তাহলে তোর মুখটা লাল হয়ে গেল কেন?”\n\nমায়া কিছু বলার আগেই নীলা হেসে উঠল।\n\n“বুঝেছি, বুঝেছি! আমার বান্ধবীর মনে বসন্ত এসে গেছে!”\n\nমায়া নীলার হাত থেকে নিজের হাত ছাড়িয়ে বলল,\n\n“আর একটা কথা বললে তোর সঙ্গে কথা বন্ধ!”\n\nদুজন হাসতে হাসতে কলেজের ভেতরে ঢুকে গেল।\n\nক্লাস শুরু হতে তখনো কিছুটা সময় বাকি। মায়া আর নীলা কলেজের বাগানের পাশে বসে গল্প করছিল।\n\nহঠাৎ নীলার চোখ গেটের দিকে পড়ল।\n\nসে মায়ার হাত চেপে ধরে ফিসফিস করে বলল,\n\n“এই, ওই ছেলেটা কে রে?”\n\nমায়া অন্যমনস্কভাবে জিজ্ঞেস করল,\n\n“কোন ছেলেটা?”\n\n“ওই যে কালো শার্ট পরে আসছে!”\n\nকথাটা শুনে মায়ার বুকের ভেতরটা কেমন যেন করে উঠল।\n\nসে ধীরে ধীরে মুখ তুলে তাকাল।\n\nতারপরই থমকে গেল।\n\nছেলেটা আর কেউ নয়।\n\nআরিশ!\n\nমায়া নিজের চোখকেই বিশ্বাস করতে পারছিল না।\n\nগতকাল যার সঙ্গে বৃষ্টির মধ্যে দেখা হয়েছিল, আজ সে তাদের কলেজে কেন?\n\nআরিশ গেট দিয়ে ঢুকে চারপাশে তাকাচ্ছিল। একসময় তার চোখ গিয়ে থামল মায়ার ওপর।\n\nদুজনের চোখাচোখি হলো।\n\nআরিশের ঠোঁটে পরিচিত সেই মৃদু হাসি ফুটে উঠল।\n\nসে সোজা মায়াদের দিকে এগিয়ে এল।\n\nনীলা মায়ার কানের কাছে মুখ নিয়ে ফিসফিস করে বলল,\n\n“ওরে বাবা! ছেলেটা তো সরাসরি তোর দিকেই আসছে!”\n\nমায়া নিচু গলায় বলল,\n\n“চুপ কর তো!”\n\nআরিশ তাদের সামনে এসে দাঁড়াল।\n\n“আসসালামু আলাইকুম।”\n\nনীলা সঙ্গে সঙ্গে উত্তর দিল,\n\n“ওয়ালাইকুম আসসালাম।”\n\nমায়া একটু দেরি করে উত্তর দিল,\n\n“ওয়ালাইকুম আসসালাম।”\n\nআরিশ মায়ার দিকে তাকিয়ে বলল,\n\n“কেমন আছেন, মায়া?”\n\nমায়া অবাক হয়ে বলল,\n\n“আপনি এখানে?”\n\nআরিশ মৃদু হেসে উত্তর দিল,\n\n“কেন? এখানে আসা কি নিষেধ?”\n\n“না, মানে... আপনি আমাদের কলেজে কী করছেন?”\n\nআরিশ কিছু বলার আগেই নীলা আগ্রহ নিয়ে জিজ্ঞেস করল,\n\n“আপনি কি এই কলেজে পড়েন?”\n\nআরিশ মাথা নাড়ল।\n\n“জি। আজ থেকে এই কলেজেই আমার ক্লাস শুরু।”\n\nমায়া অবাক হয়ে তাকিয়ে রইল।\n\n“আপনি নতুন ভর্তি হয়েছেন?”\n\n“ঠিক তাই।”\n\nনীলা হাসিমুখে বলল,\n\n“তাহলে তো খুব ভালো হলো! মায়া, দেখেছিস? তোর পরিচিত মানুষ এখন আমাদের কলেজেও!”\n\nমায়া নীলার দিকে এমনভাবে তাকাল যে নীলা হাসি চেপে রাখতে পারল না।\n\nআরিশ দুজনের কথোপকথন দেখে হেসে বলল,\n\n“আপনারা কি সব সময় এভাবেই ঝগড়া করেন?”\n\nনীলা উত্তর দিল,\n\n“ঝগড়া নয়, ভাইয়া। এটা আমাদের ভালোবাসা!”\n\nআরিশ হেসে ফেলল।\n\nকিন্তু মায়া চুপচাপ বসে রইল।\n\nতার মনে তখন একটাই প্রশ্ন।\n\nআরিশ কি সত্যিই কাকতালীয়ভাবে এই কলেজে এসেছে?\n\nনাকি এর পেছনে অন্য কোনো কারণ আছে?\n\nকিছুক্ষণ পর আরিশ বলল,\n\n“আচ্ছা, আপনাদের ডিপার্টমেন্ট কোনটা?”\n\nনীলা উত্তর দিল,\n\n“বাংলা বিভাগ।”\n\nআরিশ একটু অবাক হয়ে বলল,\n\n“সত্যি? আমিও বাংলা বিভাগেই ভর্তি হয়েছি।”\n\nনীলা খুশি হয়ে বলল,\n\n“তাহলে তো আমাদের প্রায়ই দেখা হবে!”\n\nআরিশ এবার মায়ার দিকে তাকাল।\n\n“সেটাই তো ভালো।”\n\nকথাটা শুনে মায়া কিছু বলল না। তবে তার বুকের ভেতরটা অকারণেই কেঁপে উঠল।\n\nঠিক তখনই কলেজের ঘণ্টা বেজে উঠল।\n\nনীলা উঠে দাঁড়িয়ে বলল,\n\n“চল, ক্লাসে যাই। নাহলে আজ আবার স্যারের বকা খেতে হবে।”\n\nমায়াও উঠে দাঁড়াল।\n\nআরিশ পাশে দাঁড়িয়ে বলল,\n\n“আপনারা যান। আমার ক্লাসরুমটা খুঁজে নিতে হবে।”\n\nনীলা বলল,\n\n“চলুন, দেখিয়ে দিচ্ছি।”\n\nতিনজন একসঙ্গে হাঁটতে শুরু করল।\n\nক্লাসরুমের সামনে পৌঁছে নীলা আর মায়া ভেতরে ঢুকে গেল। আরিশ যাওয়ার আগে একবার মায়ার দিকে তাকাল।\n\n“মায়া?”\n\nমায়া ফিরে তাকাল।\n\n“জি?”\n\nআরিশ মৃদু হেসে বলল,\n\n“আজ কিন্তু বৃষ্টি হচ্ছে না। তাই পালিয়ে যাওয়ার অজুহাতও নেই।”\n\nমায়া কিছুক্ষণ তার দিকে তাকিয়ে থেকে বলল,\n\n“আপনি সব সময় এমন কথা বলেন?”\n\n“কেমন কথা?”\n\n“যে কথার উত্তর দেওয়া কঠিন!”\n\nআরিশ হেসে বলল,\n\n“তাহলে উত্তর দেওয়ার জন্য সময় নিন।”\n\nএই বলে সে চলে গেল।\n\nমায়া দরজার কাছে দাঁড়িয়ে তার চলে যাওয়া দেখল।\n\nপেছন থেকে নীলা এসে কাঁধে হাত রাখল।\n\n“কী রে? ছেলেটা কিন্তু মন্দ না!”\n\nমায়া বিরক্তির ভান করে বলল,\n\n“তুই কি একটু চুপ থাকতে পারিস না?”\n\nনীলা হেসে বলল,\n\n“পারব। তবে একটা কথা মনে রাখিস, মায়া—কিছু মানুষ আমাদের জীবনে আসে হঠাৎ করে, কিন্তু তাদের জন্যই একদিন আমাদের পুরো পৃথিবীটা বদলে যায়।”\n\nমায়া কথাটার কোনো উত্তর দিল না।\n\nকিন্তু তার মনে হলো, নীলা হয়তো মজা করে এমন একটা কথা বলেছে, যার সত্যতা সে একদিন নিজেই বুঝতে পারবে।\n\nসেদিনের ক্লাসগুলো কেমন করে কেটে গেল, মায়া বুঝতেই পারল না।\n\nবারবার তার চোখ চলে যাচ্ছিল ক্লাসের দরজার দিকে।\n\nকেন?\n\nসে নিজেও জানত না।\n\nকলেজ ছুটির পর মায়া আর নীলা গেটের দিকে এগিয়ে যাচ্ছিল। ঠিক তখনই পেছন থেকে কেউ ডাকল,\n\n“মায়া, একটু দাঁড়াবেন?”\n\nপরিচিত কণ্ঠস্বর।\n\nমায়া ফিরে তাকাল।\n\nআরিশ দাঁড়িয়ে আছে।\n\nনীলা সঙ্গে সঙ্গে বলল,\n\n“আমি একটু সামনে যাচ্ছি। তোরা কথা বল।”\n\nমায়া কিছু বলার আগেই নীলা চলে গেল।\n\nমায়া বিরক্ত হয়ে বলল,\n\n“আপনি কি আমার বান্ধবীকেও আপনার দলে নিয়ে নিলেন?”\n\nআরিশ হেসে বলল,\n\n“আমি তো কিছুই করিনি। উনি নিজেই চলে গেলেন।”\n\n“আচ্ছা, বলুন। কী বলবেন?”\n\nআরিশ কিছুক্ষণ চুপ করে থেকে বলল,\n\n“একটা কথা জিজ্ঞেস করব?”\n\n“করুন।”\n\n“আপনি কি আমাকে অপছন্দ করেন?”\n\nপ্রশ্নটা শুনে মায়া অবাক হয়ে গেল।\n\n“হঠাৎ এমন প্রশ্ন কেন?”\n\nআরিশ শান্ত গলায় বলল,\n\n“কারণ, আমি যখনই আপনার সঙ্গে কথা বলতে আসি, আপনি এমনভাবে তাকান যেন আমি খুব বিরক্তিকর একজন মানুষ।”\n\nমায়া একটু থেমে বলল,\n\n“আমি আসলে অপরিচিত মানুষের সঙ্গে বেশি কথা বলি না।”\n\nআরিশ মৃদু হেসে বলল,\n\n“তাহলে এখন তো আমরা আর অপরিচিত নই। তাই না?”\n\nমায়া উত্তর দেওয়ার আগেই আরিশ আবার বলল,\n\n“আপনি চাইলে আমরা বন্ধু হতে পারি।”\n\nমায়া কিছুক্ষণ চুপ করে রইল।\n\nতারপর মৃদু স্বরে বলল,\n\n“বন্ধু হতে তো কোনো সমস্যা নেই।”\n\nআরিশের মুখে হাসি ফুটে উঠল।\n\n“তাহলে আজ থেকে আমরা বন্ধু?”\n\nমায়া মাথা নাড়ল।\n\n“জি, বন্ধু।”\n\nআরিশ হাত বাড়িয়ে বলল,\n\n“বন্ধুত্বের শুরুটা তাহলে এখান থেকেই হোক।”\n\nমায়া তার বাড়িয়ে দেওয়া হাতের দিকে তাকাল। তারপর হেসে হাত মেলাল।\n\nসেদিন তারা দুজনেই ভেবেছিল, তাদের সম্পর্কের শুরুটা শুধু বন্ধুত্বের।\n\nকিন্তু কেউ জানত না, এই বন্ধুত্বের আড়ালেই ধীরে ধীরে জন্ম নিতে চলেছে এমন এক অনুভূতি, যার নাম ভালোবাসা।\n\nআর সেই ভালোবাসার পথেই অপেক্ষা করছে কিছু আনন্দ, কিছু অভিমান, কিছু অশ্রু আর এমন কিছু সত্য, যা জানার পর হয়তো তাদের দুজনকেই নতুন করে নিজেদের চিনতে হবে।\n\nসন্ধ্যায় বাড়ি ফেরার পথে মায়ার ফোনে একটি নতুন বার্তা এল।\n\nঅপরিচিত নম্বর থেকে লেখা—\n\n“বাসায় ঠিকমতো পৌঁছেছেন তো, বন্ধু?”\n\nমায়া বার্তাটা পড়ে মৃদু হাসল।\n\nতারপর লিখল,\n\n“জি, পৌঁছে গেছি। কিন্তু আমার নম্বর পেলেন কোথায়?”\n\nকয়েক সেকেন্ড পর উত্তর এল—\n\n“সেটা একটা রহস্য। সব রহস্য কি একদিনে বলে দিতে হয়?”\n\nমায়া হেসে ফেলল।\n\n“আপনি সত্যিই খুব অদ্ভুত!”\n\nআরিশ লিখল,\n\n“আর আপনি?”\n\nমায়া উত্তর দিল,\n\n“আমি আবার কী?”\n\nআরিশের উত্তর আসতে একটু সময় লাগল।\n\n“আপনি এমন একজন, যার সঙ্গে কথা বলতে ইচ্ছে করে, অথচ কথা শেষ হয়ে গেলে মনে হয়, আরও কিছুক্ষণ কথা বললে ভালো হতো।”\n\nবার্তাটা পড়ে মায়ার হাসি ধীরে ধীরে মিলিয়ে গেল।\n\nতার বুকের ভেতর অচেনা এক অনুভূতি জন্ম নিল।\n\nসে ফোনটা বুকে চেপে ধরল না, কোনো বড় স্বপ্নও দেখল না। শুধু জানালার বাইরে তাকিয়ে কিছুক্ষণ চুপ করে রইল।\n\nতারপর নিজের মনেই বলল,\n\n“আরিশ, তুমি কি সত্যিই শুধু আমার বন্ধু হয়ে থাকবে?”\n\nকিন্তু এই প্রশ্নের উত্তর দেওয়ার সময় তখনো আসেনি।\n\nকারণ, ভালোবাসার গল্পে সবচেয়ে কঠিন বিষয়টি ভালোবাসা শুরু হওয়া নয়।\n\nসবচেয়ে কঠিন হলো, সেই ভালোবাসাকে শেষ পর্যন্ত ধরে রাখা।\n\nচলবে...\n\nপরবর্তী পর্বে: আরিশের জীবনে এমন একজনের আগমন ঘটবে, যার উপস্থিতি মায়ার মনে প্রথমবারের মতো অদ্ভুত এক প্রশ্ন জাগিয়ে তুলবে—আরিশ কি শুধু তার বন্ধু, নাকি তার চেয়েও বেশি কিছু?','\n',char(10)),2,'published',0,'2026-10-26T14:29:24.428Z','2026-10-26T14:29:24.428Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('fc79ff8a-0a56-4e06-9fba-39d0f4b503ff','95b4cdd4-4d37-4bb2-ba1c-996e967b1061','পর্ব ৩',replace('তিথির ফিরে আসা\nসকালের নরম রোদ জানালার কাচ ভেদ করে মায়ার ঘরে এসে পড়েছে। বিছানায় শুয়ে শুয়ে ফোনের পর্দার দিকে তাকিয়ে আছে সে। গত রাতের আরিশের কথাগুলো বারবার মনে পড়ছে।\n“আপনার সঙ্গে পরিচয় হওয়ার পর থেকে আমার প্রতিদিনের মধ্যে একটা নতুন অপেক্ষা তৈরি হয়েছে।”\nকথাটা মনে পড়তেই মায়ার ঠোঁটের কোণে হাসি ফুটে উঠল।\nকিন্তু পরক্ষণেই সে নিজেকে সামলে নিল।\n“ধুর! একটা ছেলে দুটো ভালো কথা বলেছে, আর আমি কিনা সেগুলো নিয়েই ভাবছি!”\nফোনটা পাশে রেখে উঠে পড়ল সে।\nআজ কলেজে যাওয়ার জন্য একটু তাড়াতাড়ি তৈরি হলো মায়া। সাদা পোশাকের সঙ্গে নীল ওড়নাটা কাঁধে জড়িয়ে আয়নার সামনে দাঁড়াল। নিজের প্রতিবিম্বের দিকে তাকিয়ে মনে মনে বলল,\n“আমি কিন্তু আরিশের জন্য তৈরি হচ্ছি না!”\nকথাটা বলেই নিজে নিজে হেসে ফেলল।\nকলেজে পৌঁছাতেই নীলা ছুটে এসে তার হাত ধরল।\n“এই মেয়ে, তোর মুখে এত হাসি কেন?”\nমায়া স্বাভাবিক থাকার চেষ্টা করে বলল,\n“এমনিই।”\nনীলা চোখ ছোট করে তাকাল।\n“আরিশের সঙ্গে কথা হয়েছে?”\nমায়া একটু থেমে বলল,\n“হ্যাঁ, গত রাতে।”\n“কী কথা হয়েছে?”\n“সাধারণ কথা।”\n“সাধারণ কথায় কেউ এত হাসে?”\nমায়া নীলার হাত ছাড়িয়ে বলল,\n“তুই না একদিন আমার মাথা খারাপ করে দিবি!”\nনীলা হেসে বলল,\n“তোর মাথা খারাপ করার দরকার নেই। মনে হচ্ছে সেটা অন্য কেউ ইতিমধ্যেই করে ফেলেছে!”\nদুজন কথা বলতে বলতে ক্লাসরুমের দিকে এগিয়ে গেল।\nকিন্তু ক্লাসে ঢুকেই মায়ার চোখ আটকে গেল সামনের বেঞ্চে বসে থাকা দুজন মানুষের দিকে।\nআরিশ বসে আছে। তার পাশের চেয়ারে বসে আছে তিথি।\nতিথি কিছু একটা বলছে, আর আরিশ মনোযোগ দিয়ে শুনছে। একসময় তিথি হেসে আরিশের হাতের ওপর নিজের হাত রাখল।\nমায়ার পা যেন মুহূর্তের জন্য থেমে গেল।\nকেন জানি দৃশ্যটা তার ভালো লাগল না।\nনিজেকে বোঝাল, আরিশ তার বন্ধু। আর বন্ধুর জীবনে অন্য বন্ধু থাকতেই পারে।\nতাহলে তার এত খারাপ লাগছে কেন?\nনীলা মায়ার মুখের দিকে তাকিয়ে সব বুঝে গেল।\nসে আস্তে করে বলল,\n“কী হয়েছে?”\nমায়া চোখ সরিয়ে বলল,\n“কিছু হয়নি।”\n“তাহলে তুই ওদের দিকে এভাবে তাকিয়ে আছিস কেন?”\n“আমি তাকাচ্ছি না।”\nনীলা দীর্ঘশ্বাস ফেলে বলল,\n“আচ্ছা, ঠিক আছে। তুই তাকাচ্ছিস না। এবার চল, বসি।”\nমায়া গিয়ে পেছনের বেঞ্চে বসল।\nকিছুক্ষণ পর আরিশ পেছনে ফিরে তাকাল। মায়াকে দেখে হাসল।\n“এই যে, এখানে বসেছেন কেন? সামনে আসুন।”\nমায়া মুখ ফিরিয়ে বলল,\n“এখানেই ভালো আছি।”\nআরিশ একটু অবাক হলো।\n“কী হয়েছে আপনার?”\n“কিছু না।”\n“আমার ওপর রাগ করেছেন?”\n“না।”\n“তাহলে আমার দিকে তাকাচ্ছেন না কেন?”\nমায়া এবার বিরক্ত হয়ে বলল,\n“আপনি কি সবার সঙ্গে এমন করে প্রশ্ন করেন?”\nআরিশ কয়েক সেকেন্ড চুপ করে রইল।\nতারপর মৃদু হেসে বলল,\n“না। শুধু আপনার সঙ্গেই করি।”\nকথাটা শুনে মায়ার বুকের ভেতরটা কেঁপে উঠল। কিন্তু সে মুখে কিছু প্রকাশ করল না।\nঠিক তখনই তিথি পেছনে ফিরে তাকাল।\n“আরিশ, তুমি কার সঙ্গে কথা বলছ?”\nআরিশ বলল,\n“আমার বন্ধু মায়া।”\nতিথি মায়ার দিকে তাকিয়ে মিষ্টি করে হাসল।\n“ওহ! তুমিই তাহলে মায়া! আরিশের মুখে তোমার কথা শুনেছি।”\nমায়া অবাক হয়ে তাকাল।\n“আমার কথা?”\nতিথি মাথা নাড়ল।\n“হ্যাঁ। গতকালও তোমার কথা বলছিল।”\nআরিশ তাড়াতাড়ি বলে উঠল,\n“তিথি, এবার থামবি?”\nতিথি হেসে বলল,\n“আচ্ছা বাবা, আর বলছি না!”\nমায়ার বুকের ভেতর জমে থাকা অস্বস্তিটা একটু কমে এল।\nঅন্তত এটুকু বুঝল, আরিশ তার কথা অন্যদের কাছেও বলে।\nকিন্তু তিথির সঙ্গে আরিশের সম্পর্কটা ঠিক কী, সেই প্রশ্নটা তখনো তার মনে রয়ে গেল।\nক্লাস শুরু হওয়ায় আর কথা হলো না।\nদুপুরের বিরতিতে মায়া আর নীলা কলেজের ক্যানটিনে গেল। কিছুক্ষণ পর আরিশও সেখানে এসে তাদের টেবিলে বসল।\n“কী খাচ্ছেন?”\nমায়া উত্তর দিল,\n“কিছু না।”\nআরিশ অবাক হয়ে বলল,\n“কিছু না আবার কী খাবার?”\nনীলা হেসে বলল,\n“ওর মন খারাপ। তাই খিদেও নেই।”\nমায়া সঙ্গে সঙ্গে নীলার দিকে তাকাল।\n“আমি তোকে বলেছি আমার মন খারাপ?”\nনীলা নির্বিকারভাবে বলল,\n“না বললেও বোঝা যায়।”\nআরিশ এবার মায়ার দিকে তাকিয়ে নরম গলায় বলল,\n“আপনি চাইলে আমাকে বলতে পারেন। আমি শুনব।”\nমায়া কিছুক্ষণ চুপ করে থেকে বলল,\n“সব কথা কি সবাইকে বলা যায়?”\nআরিশের মুখের হাসি একটু ম্লান হয়ে গেল।\n“না। সব কথা সবাইকে বলা যায় না। তবে কিছু মানুষ থাকে, যাদের কাছে না বলেও মনের কথাগুলো বলতে ইচ্ছে করে।”\nমায়া তার চোখের দিকে তাকাল।\nদুজনের মধ্যে কয়েক মুহূর্ত নীরবতা নেমে এল।\nহঠাৎ তিথি এসে আরিশের পাশে দাঁড়াল।\n“আরিশ, তোমার সঙ্গে আমার একটু কথা আছে।”\nআরিশ উঠে দাঁড়াল।\n“কী কথা?”\nতিথি মায়া আর নীলার দিকে তাকিয়ে বলল,\n“একটু ব্যক্তিগত কথা।”\nআরিশ মায়ার দিকে তাকিয়ে বলল,\n“আমি একটু আসছি।”\nমায়া মাথা নাড়ল।\nআরিশ তিথির সঙ্গে চলে গেল।\nতাদের চলে যাওয়ার দিকে তাকিয়ে মায়া চুপ করে বসে রইল।\nনীলা এবার আর মজা করল না।\nসে মায়ার হাত ধরে বলল,\n“তুই কি আরিশকে পছন্দ করতে শুরু করেছিস?”\nমায়া দীর্ঘশ্বাস ফেলল।\n“জানি না, নীলা।”\n“তাহলে ওকে নিয়ে এত ভাবছিস কেন?”\nমায়া নিচু গলায় বলল,\n“যখন ও আমার সঙ্গে কথা বলে, তখন মনে হয় আমি ওর কাছে গুরুত্বপূর্ণ। কিন্তু যখন অন্য কারও সঙ্গে ওকে দেখি, তখন মনে হয় আমি হয়তো ওর জীবনে তেমন কেউই না।”\nনীলা কিছুক্ষণ চুপ করে রইল।\nতারপর বলল,\n“মায়া, কাউকে ভালো লাগতে শুরু করলে এমন অনুভূতি হওয়া অস্বাভাবিক নয়। কিন্তু তুই নিজের মনে কোনো সিদ্ধান্ত নেওয়ার আগে আরিশকে ভালো করে চিনে নে।”\nমায়া মাথা নাড়ল।\nকিন্তু তার মনটা তখনো অস্থির।\nকারণ, সে বুঝতে পারছিল—আরিশ তার কাছে আর শুধুই একজন বন্ধু নেই।\nবিকেলে কলেজ ছুটির পর মায়া একাই গেটের দিকে হাঁটছিল। নীলা আগেই চলে গেছে।\nহঠাৎ পেছন থেকে আরিশের ডাক এল।\n“মায়া, দাঁড়ান!”\nমায়া থামল।\nআরিশ দ্রুত তার কাছে এসে দাঁড়াল।\n“আপনি আমার জন্য অপেক্ষা না করেই চলে যাচ্ছিলেন?”\nমায়া শান্ত গলায় বলল,\n“আপনি তো তিথির সঙ্গে ব্যস্ত ছিলেন।”\nআরিশ কয়েক মুহূর্ত তার দিকে তাকিয়ে রইল।\nতারপর মৃদু হেসে বলল,\n“তাহলে ব্যাপারটা এই?”\nমায়া ভ্রু কুঁচকে বলল,\n“কোন ব্যাপার?”\n“আপনি কি তিথিকে নিয়ে কিছু ভাবছেন?”\nমায়া সঙ্গে সঙ্গে উত্তর দিল,\n“না! আমি কেন ভাবতে যাব?”\nআরিশ হাসল না। বরং একটু গম্ভীর হয়ে বলল,\n“মায়া, তিথি আমার ছোটবেলার বন্ধু। ওর সঙ্গে আমার অনেক স্মৃতি আছে। কিন্তু তার মানে এই নয় যে আমার জীবনের সব সম্পর্ক একই রকম।”\nমায়া চুপ করে রইল।\nআরিশ আবার বলল,\n“আপনি আমার বন্ধু। আর আপনার সঙ্গে আমার বন্ধুত্বটা আমার কাছে গুরুত্বপূর্ণ।”\nমায়ার মনে হলো, কেউ যেন তার বুকের ভেতর জমে থাকা অস্থিরতার ওপর ধীরে ধীরে হাত বুলিয়ে দিল।\nসে নিচু গলায় বলল,\n“আমি তো কিছু জিজ্ঞেস করিনি।”\nআরিশ মৃদু হেসে বলল,\n“জানি। কিন্তু আপনার চোখে কিছু প্রশ্ন দেখেছিলাম।”\nমায়া আর কোনো উত্তর খুঁজে পেল না।\nদুজন পাশাপাশি হাঁটতে শুরু করল।\nরাস্তার পাশে কৃষ্ণচূড়া গাছের নিচে এসে আরিশ হঠাৎ থামল।\n“মায়া?”\n“জি?”\n“একটা কথা বলবেন?”\n“কী কথা?”\nআরিশ কিছুক্ষণ চুপ থেকে বলল,\n“কখনো কি এমন হয়েছে, কাউকে হারানোর ভয় পাওয়ার আগেই তাকে হারানোর কথা ভেবে আপনার মন খারাপ হয়েছে?”\nমায়া ধীরে ধীরে তার দিকে তাকাল।\nপ্রশ্নটা যেন তার নিজের মনের কথাই বলে দিল।\nসে মৃদু স্বরে বলল,\n“হয়তো হয়েছে।”\nআরিশ তার চোখের দিকে তাকিয়ে রইল।\n“সেই মানুষটা কে?”\nমায়া উত্তর দিল না।\nশুধু আকাশের দিকে তাকিয়ে বলল,\n“সব প্রশ্নের উত্তর একদিনে দিতে নেই।”\nআরিশ হেসে ফেলল।\n“এই কথাটা তো আমার বলার কথা ছিল!”\nমায়াও হেসে উঠল।\nসেদিন প্রথমবার তাদের হাসির মধ্যে কোনো অস্বস্তি ছিল না। ছিল না কোনো অভিমান।\nছিল শুধু দুজন মানুষের মধ্যে তৈরি হতে থাকা এক অদ্ভুত বোঝাপড়া।\nকিন্তু তারা কেউই জানত না, এই শান্ত বিকেলের পরই তাদের গল্পে এমন একটি অধ্যায় শুরু হবে, যা তাদের সম্পর্ককে নতুন এক পরীক্ষার সামনে দাঁড় করাবে।\nরাত সাড়ে নয়টা।\nমায়া পড়ার টেবিলে বসে বই পড়ছিল। হঠাৎ ফোনে তিথির একটি বার্তা এল।\nমায়া অবাক হয়ে বার্তাটি খুলল।\nতিথি লিখেছে,\n“মায়া, তোমার সঙ্গে আমার একটা কথা ছিল। আশা করি ভুল বুঝবে না।”\nমায়া উত্তর দিল,\n“বলো।”\nকয়েক মিনিট পর তিথির উত্তর এল।\n“আরিশকে তুমি কতটা চেনো?”\nপ্রশ্নটা পড়ে মায়ার বুকের ভেতরটা ধক করে উঠল।\nসে লিখল,\n“কেন?”\nতিথি এবার যে কথাটা লিখল, সেটা পড়ে মায়ার মুখের হাসি মুহূর্তেই মিলিয়ে গেল।\n“আরিশকে নিয়ে কোনো স্বপ্ন দেখার আগে ওর অতীতটা তোমার জানা উচিত।”\nমায়ার হাত থেমে গেল।\nসে কাঁপা আঙুলে লিখল,\n“কী হয়েছে আরিশের?”\nতিথি উত্তর দিল,\n“সব কথা মেসেজে বলা সম্ভব নয়। কাল কলেজে দেখা করো। তোমাকে এমন একটা কথা বলব, যা হয়তো তোমার আর আরিশের সম্পর্কটা বদলে দিতে পারে।”\nমায়া ফোনের পর্দার দিকে তাকিয়ে রইল।\nতার মনে হাজারো প্রশ্ন ঘুরপাক খেতে লাগল।\nআরিশের অতীতে কী আছে?\nতিথি কেন তাকে এসব বলছে?\nআর সবচেয়ে বড় কথা, আরিশ কি তার কাছ থেকে কোনো সত্য লুকিয়ে রেখেছে?\nমায়া জানালার বাইরে তাকাল। রাতের আকাশে চাঁদ মেঘের আড়ালে লুকিয়ে গেছে।\nতার মনে হলো, কিছুক্ষণ আগেও যে পৃথিবীটা সুন্দর লাগছিল, সেই পৃথিবীর কোথাও যেন অদৃশ্য একটা ছায়া নেমে এসেছে।\nসে শুধু একবার নিজের মনকে প্রশ্ন করল,\n“আরিশ, তোমার জীবনে এমন কী আছে, যা আমাকে জানাতে তুমি ভয় পাচ্ছ?”\nকিন্তু সেই প্রশ্নের উত্তর দেওয়ার মতো কেউ তখন তার পাশে ছিল না।\nআরিশ তখন নিজের ঘরে বসে পুরোনো একটি ছবি দেখছিল।\nছবিতে তার পাশে দাঁড়িয়ে আছে একটি মেয়ে।\nছবিটার পেছনে লেখা একটি তারিখ দেখে আরিশের চোখ স্থির হয়ে গেল।\nতারপর সে খুব ধীরে ছবিটা ড্রয়ারে রেখে দিল।\nমৃদু স্বরে বলল,\n“অতীত কখনো কখনো মানুষকে ছেড়ে যায় না। শুধু সঠিক সময়ের অপেক্ষা করে।”\nআর সেই অপেক্ষার শেষ যে খুব কাছে, তা সে নিজেও বুঝতে পারেনি।\nপরবর্তী পর্ব: তিথি মায়াকে আরিশের অতীতের এমন একটি অধ্যায় জানাবে, যা শুনে মায়ার মনে জন্ম নেবে নতুন এক দ্বিধা। সত্যিটা কি তাদের আরও কাছে আনবে, নাকি দূরে সরিয়ে দেবে?','\n',char(10)),3,'published',0,'2026-10-26T15:06:43.547Z','2026-10-26T15:06:43.547Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('37120f72-1d3c-4ce5-ba70-1af7612d967a','95b4cdd4-4d37-4bb2-ba1c-996e967b1061','পর্ব ৪',replace('সকাল থেকেই মায়ার মনটা অস্থির।\nগত রাতে তিথির পাঠানো মেসেজটা বারবার মনে পড়ছে তার।\n“আরিশকে নিয়ে কোনো স্বপ্ন দেখার আগে ওর অতীতটা তোমার জানা উচিত।”\nকথাটা কি শুধু সতর্ক করার জন্য বলা, নাকি এর পেছনে অন্য কোনো কারণ আছে?\nমায়া নিজেকে বোঝানোর চেষ্টা করল, আরিশ তার বন্ধু। তার অতীতে যা-ই থাকুক, সেটা জানার অধিকার তার হয়তো নেই। কিন্তু মনের ভেতর জন্ম নেওয়া প্রশ্নগুলোকে সে কিছুতেই থামাতে পারছিল না।\nসকালে কলেজে যাওয়ার সময় মা জিজ্ঞেস করলেন,\n“কী হয়েছে রে? আজ তোকে এত চিন্তিত লাগছে কেন?”\nমায়া মৃদু হেসে বলল,\n“কিছু হয়নি মা। একটু মাথা ধরেছে।”\nমা স্নেহভরে মাথায় হাত বুলিয়ে দিলেন।\n“নিজের যত্ন নিবি। সবকিছু নিয়ে এত ভাবতে নেই।”\nমায়া মায়ের দিকে তাকিয়ে মুচকি হাসল। কিন্তু নিজের মনকে কীভাবে বোঝাবে, সেই উত্তর তার জানা ছিল না।\nকলেজে পৌঁছানোর পর নীলাকে দেখতে পেল সে। নীলা তাকে দেখেই কাছে এসে বলল,\n“কী রে, তোর মুখ এমন শুকনো কেন?”\nমায়া বলল,\n“তোর সঙ্গে একটা কথা আছে।”\nনীলা গম্ভীর হয়ে গেল।\n“কী হয়েছে?”\nমায়া চারপাশে তাকিয়ে নিচু গলায় বলল,\n“তিথি আমাকে একটা মেসেজ দিয়েছে।”\n“কী মেসেজ?”\n“বলেছে, আরিশের অতীত সম্পর্কে আমার কিছু জানা উচিত।”\nনীলা কিছুক্ষণ চুপ করে রইল।\nতারপর বলল,\n“তুই কী ভাবছিস?”\nমায়া দীর্ঘশ্বাস ফেলল।\n“জানি না। আরিশের সঙ্গে কথা বললে আমার ভালো লাগে। ওকে দেখলে অকারণেই হাসি পায়। কিন্তু আমি এটাও জানি না, ও আমাকে শুধু বন্ধু ভাবে, নাকি অন্য কিছু।”\nনীলা মায়ার হাত ধরে বলল,\n“একটা কথা মনে রাখিস, মায়া। কারও অতীত জানার আগে তাকে নিজের মুখে কথা বলার সুযোগ দেওয়া উচিত। তিথি কী বলবে, সেটা শোনার পাশাপাশি আরিশের কথাটাও শুনবি।”\nমায়া মাথা নাড়ল।\nঠিক তখনই পেছন থেকে একটি পরিচিত কণ্ঠ ভেসে এল।\n“কী নিয়ে এত গোপন আলোচনা হচ্ছে?”\nদুজন ফিরে তাকাল।\nআরিশ দাঁড়িয়ে আছে।\nনীলা হেসে বলল,\n“মেয়েদের গোপন কথা। তোমাকে বলা যাবে না।”\nআরিশ মায়ার দিকে তাকিয়ে বলল,\n“আপনিও কি আমাকে কিছু বলবেন না?”\nমায়া চোখ নামিয়ে বলল,\n“সব কথা কি আপনাকে বলতে হবে?”\nআরিশ একটু হেসে বলল,\n“না। তবে আপনি কিছু লুকালে আমার কেমন যেন লাগে।”\nকথাটা শুনে মায়া তার দিকে তাকাল।\nআরিশের চোখে কোনো অভিযোগ ছিল না। ছিল শুধু একরাশ আন্তরিকতা।\nমায়ার হঠাৎ ইচ্ছে হলো, সবকিছু খুলে জিজ্ঞেস করে।\nকিন্তু সে কিছুই বলল না।\nশুধু বলল,\n“ক্লাসে যাবেন না?”\nআরিশ মৃদু হেসে বলল,\n“যাব। তবে আজ আপনার সঙ্গে একটা কথা ছিল।”\n“কী কথা?”\n“ক্লাস শেষে বলব।”\nএই বলে আরিশ চলে গেল।\nমায়া তার চলে যাওয়ার দিকে তাকিয়ে রইল।\nআজ যেন প্রতিটি কথার আড়ালেই লুকিয়ে আছে আরও অনেক কথা।\nদুপুরে ক্লাস শেষ হওয়ার পর তিথি মায়ার কাছে এল।\n“তোমার সঙ্গে একটু কথা বলতে পারি?”\nমায়া মাথা নাড়ল।\nদুজন কলেজের পেছনের বাগানের দিকে এগিয়ে গেল। সেখানে একটা বেঞ্চে বসে তিথি কিছুক্ষণ চুপ করে রইল।\nতারপর বলল,\n“মায়া, একটা কথা জিজ্ঞেস করি? তুমি কি আরিশকে পছন্দ করো?”\nপ্রশ্নটা শুনে মায়া অপ্রস্তুত হয়ে গেল।\n“হঠাৎ এমন প্রশ্ন কেন?”\nতিথি মৃদু হেসে বলল,\n“তোমার চোখে দেখেছি। আরিশের দিকে তাকালে তোমার চোখের ভাষা বদলে যায়।”\nমায়া কিছু বলল না।\nতিথি আবার বলল,\n“আমি তোমাকে দোষ দিচ্ছি না। আরিশকে পছন্দ করার অনেক কারণ আছে। ও ভীষণ ভালো একটা মানুষ।”\nমায়া এবার জিজ্ঞেস করল,\n“তাহলে তুমি আমাকে ওর অতীত সম্পর্কে জানতে বলছ কেন?”\nতিথির মুখের হাসি মিলিয়ে গেল।\nকিছুক্ষণ চুপ করে থেকে সে বলল,\n“কারণ, আমি চাই না তুমি এমন কোনো স্বপ্ন দেখো, যেটা একদিন তোমাকে কষ্ট দেবে।”\nমায়ার বুকের ভেতরটা কেঁপে উঠল।\n“আরিশের কী হয়েছে?”\nতিথি ধীরে ধীরে বলতে শুরু করল।\n“কয়েক বছর আগে আরিশের জীবনে একজন মানুষ ছিল। মেয়েটার নাম ছিল নওরিন।”\nমায়া স্থির হয়ে বসে রইল।\nতিথি বলল,\n“ওরা একে অপরকে খুব ভালোবাসত। আরিশ তখন একেবারে অন্য রকম ছিল। সব সময় হাসত, সবার সঙ্গে মিশত। ওর জীবনে অনেক স্বপ্ন ছিল।”\nএকটু থেমে তিথি আবার বলল,\n“কিন্তু একসময় তাদের সম্পর্কটা ভেঙে যায়। নওরিন হঠাৎ করেই আরিশের জীবন থেকে চলে যায়। কেন চলে গিয়েছিল, সেটা আরিশ কখনো কাউকে ঠিকমতো বলেনি।”\nমায়া নিচু গলায় জিজ্ঞেস করল,\n“তারপর?”\n“তারপর থেকে আরিশ অনেক বদলে যায়। আগের মতো কাউকে সহজে বিশ্বাস করে না। নিজের মনের কথা কাউকে বলে না। বাইরে থেকে হাসিখুশি থাকলেও ভেতরে অনেক কিছু চেপে রাখে।”\nমায়া কিছুক্ষণ নীরব রইল।\nতারপর ধীরে ধীরে বলল,\n“কিন্তু এসব তো ওর অতীত। অতীতে কারও ভালোবাসা ছিল বলে কি সে আবার নতুন করে কাউকে ভালোবাসতে পারবে না?”\nতিথি অবাক হয়ে মায়ার দিকে তাকাল।\n“তুমি কি সত্যিই এমনটা ভাবো?”\nমায়া শান্ত গলায় বলল,\n“হ্যাঁ। প্রত্যেক মানুষেরই একটা অতীত থাকে। অতীতের জন্য কাউকে সারাজীবন একা থাকতে হবে, এমন তো কোনো কথা নেই।”\nতিথির চোখে অদ্ভুত একটা দৃষ্টি ফুটে উঠল।\nসে মৃদু হেসে বলল,\n“তুমি আর দশজনের মতো নও, মায়া।”\nমায়া জিজ্ঞেস করল,\n“কেন?”\nতিথি উত্তর দিল না।\nশুধু বলল,\n“আমি চাই, আরিশ আবার আগের মতো হাসুক। ওর জীবনে এমন কেউ আসুক, যে ওকে বুঝবে। তবে একটা কথা মনে রেখো—আরিশ নিজের অতীত নিয়ে এখনো কষ্ট পায়। ওকে সময় দিও।”\nমায়া মাথা নাড়ল।\nকিন্তু তার মনে একটা প্রশ্ন তখনো রয়ে গেল।\nতিথি কি শুধু আরিশের বন্ধু?\nনাকি তার নিজের মনেও আরিশের জন্য কোনো অনুভূতি লুকিয়ে আছে?\nমায়া প্রশ্নটা করতে চেয়েও করল না।\nকারণ, সব প্রশ্নের উত্তর জানতে চাওয়া যায় না।\nকিছু উত্তর সময়ের হাতে ছেড়ে দিতে হয়।\nবাগান থেকে বেরিয়ে মায়া কলেজের গেটের দিকে হাঁটছিল। হঠাৎ দেখতে পেল, আরিশ একটি গাছের নিচে দাঁড়িয়ে আছে।\nতাকে দেখেই আরিশ এগিয়ে এল।\n“কোথায় ছিলেন এতক্ষণ?”\nমায়া বলল,\n“তিথির সঙ্গে কথা বলছিলাম।”\nআরিশের মুখের অভিব্যক্তি মুহূর্তেই বদলে গেল।\n“তিথি আপনাকে কিছু বলেছে?”\nমায়া তার চোখের দিকে তাকাল।\n“হ্যাঁ।”\nআরিশ কিছুক্ষণ চুপ করে থেকে বলল,\n“কী বলেছে?”\nমায়া ধীরে ধীরে উত্তর দিল,\n“আপনার অতীতের কথা।”\nআরিশের মুখটা গম্ভীর হয়ে গেল।\nসে অন্যদিকে তাকিয়ে বলল,\n“তাহলে নিশ্চয়ই অনেক কিছু জেনেছেন।”\nমায়া শান্ত গলায় বলল,\n“কিছুটা জেনেছি। কিন্তু আপনার মুখ থেকে শুনতে চাই।”\nআরিশ তার দিকে তাকাল।\n“কেন?”\nমায়া একটু থেমে বলল,\n“কারণ, আমি চাই না অন্য কারও কথার ওপর ভিত্তি করে আপনাকে বিচার করতে।”\nআরিশ কিছুক্ষণ কোনো কথা বলল না।\nতারপর খুব ধীরে বলল,\n“মায়া, আপনি জানেন না, আমার অতীতটা কতটা জটিল।”\nমায়া মৃদু হেসে বলল,\n“আপনার অতীত যতই জটিল হোক, আপনি আজ যে মানুষ, আমি সেই মানুষটাকেই জানতে চাই।”\nকথাটা শুনে আরিশের চোখে যেন এক মুহূর্তের জন্য অন্য রকম আলো ফুটে উঠল।\nসে ধীরে ধীরে বলল,\n“সবাই এমন কথা বলে না।”\nমায়া উত্তর দিল,\n“সবাই তো এক রকম হয় না।”\nআরিশ কিছুক্ষণ মায়ার দিকে তাকিয়ে রইল।\nতারপর বলল,\n“একদিন আপনাকে সব বলব। তবে আজ নয়।”\nমায়া মাথা নাড়ল।\n“ঠিক আছে। আমি অপেক্ষা করব।”\nআরিশ অবাক হয়ে বলল,\n“আপনি অপেক্ষা করবেন?”\nমায়া মৃদু হেসে বলল,\n“বন্ধুর জন্য অপেক্ষা করা যায় না?”\nআরিশও হাসল।\n“যায়। অবশ্যই যায়।”\nকিন্তু দুজনের কেউই মুখে স্বীকার করল না, এই অপেক্ষাটা আর শুধু বন্ধুত্বের মধ্যে সীমাবদ্ধ নেই।\nসন্ধ্যায় বাড়ি ফিরে মায়া নিজের ঘরে বসে ছিল।\nতিথির বলা কথাগুলো তার মনে ঘুরছিল।\nআরিশ একসময় কাউকে ভালোবাসত।\nসেই ভালোবাসা ভেঙে যাওয়ার পর সে বদলে গিয়েছিল।\nকথাগুলো ভাবতে ভাবতে মায়ার মনে অদ্ভুত এক অনুভূতি হলো।\nআরিশের অতীতের জন্য তার মন খারাপ হচ্ছিল। অথচ সেই অতীতের একটি অংশ সম্পর্কে সে কিছুই জানে না।\nঠিক তখনই ফোনে আরিশের মেসেজ এল।\n“কী করছেন?”\nমায়া উত্তর দিল,\n“আপনার কথা ভাবছি।”\nমেসেজটা পাঠিয়েই সে থমকে গেল।\nএটা কি সত্যিই লিখে ফেলল সে?\nকয়েক সেকেন্ড পর আরিশের উত্তর এল।\n“সত্যি?”\nমায়া তাড়াতাড়ি লিখল,\n“মানে, আজকের কথাগুলো ভাবছি।”\nআরিশ লিখল,\n“বুঝলাম। তাহলে আমিও একটা কথা বলি?”\n“বলুন।”\n“আজ আপনি যখন বললেন, আমার অতীত দিয়ে আমাকে বিচার করবেন না, তখন কেন জানি মনে হলো, হয়তো আমি আবার কাউকে বিশ্বাস করতে পারব।”\nমায়ার চোখের কোণে অজান্তেই হাসি ফুটে উঠল।\nসে লিখল,\n“বিশ্বাস করতে শিখুন। সবাই আপনার অতীতের মানুষটির মতো হবে না।”\nআরিশের উত্তর এল,\n“সবাইকে বিশ্বাস করতে পারি না। তবে আপনাকে বিশ্বাস করতে ইচ্ছে করে।”\nমায়া ফোনের দিকে তাকিয়ে রইল।\nতারপর খুব ধীরে লিখল,\n“আমি আপনার বিশ্বাস ভাঙব না, আরিশ।”\nবার্তাটা পাঠিয়ে সে জানালার পাশে গিয়ে দাঁড়াল।\nবাইরে রাতের আকাশে চাঁদ উঠেছে।\nমায়ার মনে হচ্ছিল, তাদের গল্পটা হয়তো সত্যিই অন্য রকম হতে চলেছে।\nকিন্তু সে জানত না, ঠিক সেই সময় আরিশের ফোনেও একটি বার্তা এসেছে।\nএকটি অপরিচিত নম্বর থেকে।\nবার্তায় লেখা—\n“আরিশ, অনেক দিন তো হলো। এবার কি আমাদের আবার দেখা হতে পারে?”\nবার্তাটার নিচে লেখা নামটি দেখে আরিশের মুখের হাসি মিলিয়ে গেল।\nনওরিন।\nতার অতীতের সেই মানুষটি, যাকে সে এত বছরেও পুরোপুরি ভুলতে পারেনি।\nআরিশ অনেকক্ষণ ফোনের পর্দার দিকে তাকিয়ে রইল।\nতারপর জানালার বাইরে তাকিয়ে ফিসফিস করে বলল,\n“এত দিন পর আবার কেন ফিরে এলে, নওরিন?”\nঅন্যদিকে মায়া তখনো জানত না, তার জীবনে প্রথমবারের মতো ভালোবাসার অনুভূতি জন্ম নেওয়ার ঠিক সেই মুহূর্তে আরিশের অতীত ফিরে আসার দরজায় কড়া নাড়ছে।\nএই ফিরে আসা কি তাদের সম্পর্ককে আরও গভীর করবে?\nনাকি এমন এক দূরত্ব তৈরি করবে, যেখান থেকে ফিরে আসা আর সহজ হবে না?\nতা জানতে হলে অপেক্ষা করতে হবে পরবর্তী পর্বের জন্য।\nচলবে...\nপরবর্তী পর্ব: নওরিনের ফিরে আসা। আরিশ কি তার অতীতকে নতুন করে সুযোগ দেবে, নাকি মায়ার উপস্থিতি তাকে জীবনের অন্য এক সত্যের মুখোমুখি দাঁড় করাবে?','\n',char(10)),4,'published',0,'2026-10-26T15:13:32.482Z','2026-10-26T15:13:32.482Z',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('60a93419-3032-429e-9955-6fda29335254','71e59a9a-70fc-47e7-84cd-cf9406c3e3d7','Toxic Lover',replace('রাত ১১টা ৪৭ মিনিট।\n\nলুইস ম্যানশনের বিশাল কক্ষটিতে তখন পিনপতন নীরবতা।\n\nকাঁচের দেয়ালের ওপারে ঝলমল করছে জুরিখ শহর। হাতে থাকা হুইস্কির গ্লাসটি টেবিলে নামিয়ে রাখল রাইভেন লুইস। কালো শার্টের হাতা কনুই পর্যন্ত গোটানো, মুখে বিরক্তির ছাপ, আর ধূসর চোখজোড়ায় এমন এক শীতলতা—যেন পৃথিবীর কোনো কিছুই তাকে স্পর্শ করতে পারে না।\n\nঠিক তখনই দরজায় কড়া নাড়ার শব্দ হলো।\n\n“Come in.”\n\nঅনুমতি পেয়ে ঘরে প্রবেশ করল তার ব্যক্তিগত সহকারী।\n\n“Sir, the girl you''re looking for has been found.”\n\nরাইভেনের আঙুলের নড়াচড়া থেমে গেল।\n\n“Name?”\n\n“Mirabel Kyra, sir.”\n\nমেয়েটির নামটি শোনার পর কয়েক সেকেন্ড নীরব রইল সে। তারপর টেবিলের ওপর রাখা ফাইলটি নিজের দিকে টেনে নিল।\n\nফাইলের প্রথম পাতায় একটি ছবি।\n\nমিরাবেল কায়রা।\n\nসাধারণ একটি ছবি। অথচ রাইভেনের দৃষ্টি সেখান থেকে সরল না।\n\n“Arrange a meeting.”\n\n“Sir, may I ask why?”\n\nধীরে ধীরে মুখ তুলল রাইভেন। তার ঠোঁটে ফুটে উঠল ক্ষীণ এক হাসি।\n\n“Did I ask you to question me?”\n\n“No, sir. I''m sorry.”\n\n“Then do your job.”\n\nসহকারী ঘর থেকে বেরিয়ে যেতেই রাইভেন আবার ছবিটির দিকে তাকাল।\n\nমেয়েটি জানত না, তার নামটি ইতিমধ্যেই পৌঁছে গেছে এমন একজন মানুষের কাছে, যে কোনো কিছুর পেছনে কারণ না জেনে থেমে থাকার মানুষ নয়।\n\nকিন্তু রাইভেনের কাছে মিরাবেল কেন এত গুরুত্বপূর্ণ?\n\nছবির পেছনে লেখা তারিখটির দিকে তাকিয়ে হঠাৎ থমকে গেল সে।\n\nতারপর বহুদিন পর এমন একটি হাসি হাসল, যার অর্থ একমাত্র সে নিজেই জানত।\n\n“Finally, Mirabel.”\n\nএকটু থেমে নিচু স্বরে যোগ করল—\n\n“You have no idea what your name means to me.”\n\nচলবে…','\n',char(10)),1,'published',0,'2026-10-27 09:20:19','2026-10-27 09:20:19',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('ed87040e-1249-4dee-9c0d-bb1a46be2170','95b4cdd4-4d37-4bb2-ba1c-996e967b1061','পর্ব ৫',replace('রাত তখন প্রায় এগারোটা।\nনিজের ঘরের জানালার পাশে বসে আছে আরিশ। হাতে ফোন, আর ফোনের পর্দায় ভেসে আছে একটি নাম—নওরিন।\n\nযে নামটা একসময় তার মুখে হাসি ফুটিয়ে তুলত, আজ সেই নামটাই তার মনে হাজারো প্রশ্ন জাগিয়ে তুলেছে।\n\nএত দিন পর নওরিন কেন ফিরে এসেছে?\n\nযে মানুষটা একদিন কোনো ব্যাখ্যা না দিয়েই তার জীবন থেকে চলে গিয়েছিল, আজ আবার সেই মানুষটাই কেন তার জীবনে ফিরে আসতে চাইছে?\n\nআরিশ ফোনটা হাতে নিয়ে অনেকক্ষণ বসে রইল। উত্তর দেওয়ার জন্য বারবার মেসেজের ঘর খুলল, আবার বন্ধ করল।\n\nশেষ পর্যন্ত সে শুধু লিখল,\n\n“এত দিন পর আমার কথা মনে পড়ল?”\n\nকয়েক সেকেন্ডের মধ্যেই উত্তর এল।\n\n“তোমাকে কি কোনো দিন ভুলতে পেরেছি, আরিশ?”\n\nবার্তাটা পড়ে আরিশের বুকের ভেতরটা কেমন যেন করে উঠল।\n\nকিছু স্মৃতি মানুষ ভুলে যেতে চাইলেও পারে না। তারা মনের কোনো এক কোণে চুপচাপ বসে থাকে। আর হঠাৎ কোনো এক রাতে ফিরে এসে সবকিছু এলোমেলো করে দেয়।\n\nআরিশের জীবনেও ঠিক সেটাই ঘটছিল।\n\nসে লিখল,\n\n“যে মানুষটা একদিন আমাকে একা রেখে চলে গিয়েছিল, সে আজ আবার ফিরে আসতে চাইছে কেন?”\n\nএবার উত্তর আসতে একটু সময় লাগল।\n\nতারপর নওরিন লিখল,\n\n“তোমাকে অনেক কিছু বলার আছে। শুধু একবার দেখা করো আমার সঙ্গে। তারপর তুমি যা সিদ্ধান্ত নেবে, আমি মেনে নেব।”\n\nআরিশ ফোনটা নামিয়ে রাখল।\n\nতার চোখের সামনে ভেসে উঠল কয়েক বছর আগের সেই দিনগুলো। নওরিনের সঙ্গে কাটানো মুহূর্তগুলো, একসঙ্গে দেখা স্বপ্নগুলো, আর হঠাৎ করেই সবকিছু ভেঙে যাওয়ার সেই সময়টা।\n\nসেদিনের কষ্ট সে কাউকে বুঝতে দেয়নি।\n\nকিন্তু আজও সেই স্মৃতিগুলো তার মনকে ভারী করে তোলে।\n\nঠিক তখনই ফোনে আরেকটি মেসেজ এল।\n\nমায়া লিখেছে,\n\n“ঘুমিয়ে পড়েছেন?”\n\nআরিশ মেসেজটা পড়ে কিছুক্ষণ চুপ করে রইল।\n\nএই মেয়েটার সঙ্গে পরিচয় হয়েছে খুব অল্প দিন। অথচ তার একটি ছোট্ট বার্তাও আরিশের মুখে হাসি এনে দিতে পারে।\n\nসে উত্তর দিল,\n\n“না। আপনি ঘুমাননি কেন?”\n\nমায়া লিখল,\n\n“এমনিই। আজ আপনার কথা মনে পড়ছিল।”\n\nবার্তাটা পড়ে আরিশের ঠোঁটের কোণে মৃদু হাসি ফুটে উঠল।\n\nসে লিখল,\n\n“আমার কথা মনে পড়ছিল, নাকি আমাকে মিস করছিলেন?”\n\nমায়া সঙ্গে সঙ্গে উত্তর দিল,\n\n“নিজেকে এত গুরুত্বপূর্ণ ভাবেন কেন?”\n\nআরিশ হেসে ফেলল।\n\n“ঠিক আছে, আর বলব না। তবে একটা কথা বলি?”\n\n“কী কথা?”\n\n“আপনার সঙ্গে কথা বললে আমার মনটা ভালো হয়ে যায়।”\n\nমায়া কিছুক্ষণ চুপ করে রইল।\n\nতারপর লিখল,\n\n“আমারও।”\n\nএই দুটি শব্দ পড়ে আরিশের মনে হলো, পৃথিবীতে কিছু অনুভূতি আছে, যেগুলোর জন্য বড় বড় বাক্যের প্রয়োজন হয় না।\n\nদুটি ছোট্ট শব্দও কখনো কখনো মনের অনেক কথা বলে দেয়।\n\nকিন্তু পরক্ষণেই তার চোখ চলে গেল নওরিনের মেসেজের দিকে।\n\nমুখের হাসিটা ধীরে ধীরে মিলিয়ে গেল।\n\nসে বুঝতে পারছিল না, তার জীবনের এই নতুন সম্পর্কটাকে কোন দিকে নিয়ে যাওয়া উচিত।\n\nসে কি অতীতের মুখোমুখি হবে?\n\nনাকি অতীতকে পেছনে ফেলে নতুন করে বাঁচতে শিখবে?\n\nকোনো উত্তরই তখন তার কাছে পরিষ্কার ছিল না।\n\nপরদিন সকাল।\n\nকলেজের গেটের সামনে দাঁড়িয়ে নীলার জন্য অপেক্ষা করছিল মায়া। হঠাৎ তার ফোনে আরিশের মেসেজ এল।\n\n“আজ আপনার সঙ্গে একটা কথা আছে।”\n\nমায়া লিখল,\n\n“কী কথা?”\n\nআরিশ উত্তর দিল,\n\n“সামনাসামনি বলব। একটু সময় দেবেন?”\n\nমায়ার মনে কৌতূহল জাগল।\n\n“আচ্ছা। ক্লাসের পর কথা হবে।”\n\nকিছুক্ষণ পর নীলা এসে হাজির হলো।\n\nমায়াকে দেখে বলল,\n\n“কী রে, আজ এত চুপচাপ কেন?”\n\nমায়া বলল,\n\n“আরিশ বলেছে, আজ আমার সঙ্গে কিছু কথা আছে।”\n\nনীলা হেসে বলল,\n\n“তাহলে তো ভালোই। হয়তো অবশেষে মনের কথাটা বলবে!”\n\nমায়া তাড়াতাড়ি বলল,\n\n“কী সব বলিস! এমন কিছু না।”\n\nনীলা মুচকি হেসে বলল,\n\n“ঠিক আছে। আমি আর কিছু বললাম না।”\n\nকিন্তু মায়ার মনটা আজ অদ্ভুতভাবে অপেক্ষা করছিল।\n\nসে জানত না, আরিশ কী বলতে চায়। শুধু মনে হচ্ছিল, আজকের কথোপকথন তাদের সম্পর্কের জন্য গুরুত্বপূর্ণ হতে পারে।\n\nক্লাস শেষে মায়া কলেজের বাগানে এসে দাঁড়াল।\n\nকিছুক্ষণ পর আরিশ এল।\n\nকিন্তু আজ তাকে অন্য রকম লাগছিল। মুখে সেই পরিচিত হাসিটা নেই। চোখে যেন অনেক রাত না ঘুমানোর ক্লান্তি।\n\nমায়া চিন্তিত হয়ে জিজ্ঞেস করল,\n\n“কী হয়েছে আপনার? আপনাকে এমন লাগছে কেন?”\n\nআরিশ কিছুক্ষণ চুপ করে থেকে বলল,\n\n“মায়া, একটা কথা বলব। আপনি মন খারাপ করবেন না তো?”\n\nমায়ার বুকের ভেতরটা ধক করে উঠল।\n\n“আগে বলুন, কী হয়েছে।”\n\nআরিশ দীর্ঘশ্বাস ফেলে বলল,\n\n“আমার অতীতের একজন মানুষ আবার ফিরে এসেছে।”\n\nমায়া চুপ করে গেল।\n\nতার মনে সঙ্গে সঙ্গে তিথির বলা কথাগুলো ভেসে উঠল।\n\nনওরিন।\n\nআরিশের অতীতের সেই মানুষটি।\n\nমায়া নিজেকে সামলে নিয়ে জিজ্ঞেস করল,\n\n“আপনি কি তার সঙ্গে দেখা করবেন?”\n\nআরিশ বলল,\n\n“জানি না। আমার অনেক প্রশ্নের উত্তর বাকি আছে।”\n\nমায়া কিছুক্ষণ নিচের দিকে তাকিয়ে রইল।\n\nতারপর ধীরে ধীরে বলল,\n\n“আপনার মনে যদি কোনো প্রশ্ন থেকে থাকে, তাহলে উত্তরগুলো জেনে নেওয়া উচিত।”\n\nআরিশ অবাক হয়ে তার দিকে তাকাল।\n\n“আপনার খারাপ লাগছে না?”\n\nমায়া মৃদু হেসে বলল,\n\n“আপনার অতীত সম্পর্কে জানার অধিকার আমার নেই। আপনি কী করবেন, সেটা আপনার সিদ্ধান্ত।”\n\nআরিশ একটু কাছে এসে বলল,\n\n“কিন্তু আপনার অনুভূতিগুলোও আমার কাছে গুরুত্বপূর্ণ।”\n\nকথাটা শুনে মায়ার চোখ স্থির হয়ে গেল।\n\nসে আস্তে করে বলল,\n\n“আমি চাই না, আমার জন্য আপনি আপনার অতীতের কোনো প্রশ্নের উত্তর না জেনে থাকুন।”\n\nআরিশ কিছুক্ষণ তার দিকে তাকিয়ে রইল।\n\nতারপর বলল,\n\n“আপনি জানেন, আপনার এই কথাগুলোই আমাকে সবচেয়ে বেশি ভাবায়?”\n\nমায়া জিজ্ঞেস করল,\n\n“কেন?”\n\nআরিশ উত্তর দিল না।\n\nশুধু মৃদু হেসে বলল,\n\n“একদিন বুঝবেন।”\n\nসেদিন বিকেলে আরিশ নওরিনের সঙ্গে দেখা করতে রাজি হলো।\n\nশহরের একটি ছোট্ট ক্যাফেতে বসে ছিল নওরিন। আরিশকে দেখেই সে উঠে দাঁড়াল।\n\nঅনেক দিন পর দুজন মুখোমুখি হলো।\n\nকিন্তু এই দেখা হওয়ার মধ্যে আগের মতো কোনো উচ্ছ্বাস ছিল না। ছিল অস্বস্তি, দ্বিধা আর অনেক না বলা কথা।\n\nনওরিন ধীরে বলল,\n\n“কেমন আছ, আরিশ?”\n\nআরিশ চেয়ারে বসে শান্ত গলায় বলল,\n\n“ভালো আছি। তুমি কেমন আছ?”\n\n“ভালো থাকার চেষ্টা করছি।”\n\nকিছুক্ষণ নীরবতা নেমে এল।\n\nঅবশেষে আরিশই প্রশ্ন করল,\n\n“কেন এসেছ, নওরিন?”\n\nনওরিন মাথা নিচু করল।\n\n“তোমার কাছে ক্ষমা চাইতে।”\n\nআরিশের মুখে কোনো পরিবর্তন দেখা গেল না।\n\n“কিসের জন্য?”\n\nনওরিনের চোখ ভিজে উঠল।\n\n“তোমাকে কিছু না বলে চলে যাওয়ার জন্য। তোমাকে কষ্ট দেওয়ার জন্য। আর তোমাকে এমন কিছু বিশ্বাস করতে বাধ্য করার জন্য, যেটা হয়তো সত্যি ছিল না।”\n\nআরিশ এবার তার দিকে তাকাল।\n\n“হয়তো সত্যি ছিল না মানে?”\n\nনওরিন কিছুক্ষণ চুপ করে থেকে বলল,\n\n“আমি তোমাকে সব বলব। কিন্তু তার আগে একটা কথা জানতে চাই।”\n\n“কী কথা?”\n\nনওরিন ধীরে ধীরে প্রশ্ন করল,\n\n“তোমার জীবনে কি এখন অন্য কেউ আছে?”\n\nআরিশের মনে সঙ্গে সঙ্গে মায়ার মুখটা ভেসে উঠল।\n\nতার হাসি, অভিমান, ছোট ছোট প্রশ্ন আর তার বলা সেই কথাটা—\n\n“আমি আপনার বিশ্বাস ভাঙব না, আরিশ।”\n\nআরিশ কিছুক্ষণ চুপ করে রইল।\n\nতারপর বলল,\n\n“একজন আছে, যার সঙ্গে কথা বলতে আমার ভালো লাগে। যার মন খারাপ দেখলে আমারও খারাপ লাগে। তবে আমাদের সম্পর্কের নাম কী, সেটা এখনো আমি নিজেও বুঝে উঠতে পারিনি।”\n\nনওরিনের মুখটা মলিন হয়ে গেল।\n\nসে নিচু গলায় বলল,\n\n“তাহলে তুমি আবার কাউকে ভালোবাসতে শুরু করেছ?”\n\nআরিশ শান্তভাবে উত্তর দিল,\n\n“আমি জানি না ভালোবাসা কি না। তবে এটুকু জানি, তার সঙ্গে পরিচয় হওয়ার পর আমার জীবনটা একটু অন্য রকম লাগছে।”\n\nনওরিন চোখের পানি মুছে বলল,\n\n“আমি কি তোমাকে একটা সুযোগ চাইতে পারি?”\n\nআরিশ চুপ করে রইল।\n\nনওরিন আবার বলল,\n\n“আমি জানি, আমার ফিরে আসার কোনো অধিকার নেই। তবুও যদি পারো, আমাকে একবার আমার কথাগুলো বলার সুযোগ দিও।”\n\nআরিশ জানালার বাইরে তাকাল।\n\nতার মনে হচ্ছিল, অতীতের সব প্রশ্ন যেন আবার তার সামনে এসে দাঁড়িয়েছে।\n\nঅবশেষে সে বলল,\n\n“তোমার কথা আমি শুনব। কিন্তু তার মানে এই নয় যে সবকিছু আগের মতো হয়ে যাবে।”\n\nনওরিন মাথা নাড়ল।\n\n“আমি বুঝতে পারছি।”\n\nদুজন ক্যাফে থেকে বেরিয়ে এল।\n\nকিন্তু তাদের এই কথোপকথনের শেষটা কেউ জানত না।\n\nআরিশও জানত না, নওরিনের বলা সেই সত্য তার নিজের জীবন সম্পর্কে অনেক পুরোনো ধারণা বদলে দিতে পারে।\n\nঅন্যদিকে, বাড়ি ফিরে মায়া ফোন হাতে বসে ছিল।\n\nসে জানত, আজ আরিশ নওরিনের সঙ্গে দেখা করতে গেছে।\n\nনিজেকে বারবার বোঝাচ্ছিল, তার মন খারাপ করার কোনো কারণ নেই।\n\nতবুও কেন যেন মনে হচ্ছিল, তার জীবনের সবচেয়ে সুন্দর একটা অনুভূতি হয়তো এখনো জন্ম নেওয়ার আগেই হারিয়ে যেতে বসেছে।\n\nঠিক তখনই ফোনে আরিশের মেসেজ এল।\n\n“মায়া, আপনি জেগে আছেন?”\n\nমায়া সঙ্গে সঙ্গে উত্তর দিল,\n\n“জি। কী হয়েছে?”\n\nআরিশ লিখল,\n\n“আজ আপনার সঙ্গে কথা বলতে খুব ইচ্ছে করছে।”\n\nমায়ার চোখে অজান্তেই মমতা ফুটে উঠল।\n\nসে লিখল,\n\n“বলুন। আমি শুনছি।”\n\nঅনেকক্ষণ কোনো উত্তর এল না।\n\nতারপর আরিশ লিখল,\n\n“কখনো কখনো মানুষ অতীতকে ভুলতে পারে না। কিন্তু তার মানে এই নয় যে সে নতুন করে সুখী হতে চায় না। তাই না?”\n\nমায়া বার্তাটা পড়ে ধীরে ধীরে উত্তর দিল,\n\n“হ্যাঁ, আরিশ। মানুষ আবারও নতুন করে শুরু করতে পারে। তবে তার জন্য নিজের মনের কাছে সৎ থাকতে হয়।”\n\nআরিশ লিখল,\n\n“আপনি কি মনে করেন, আমি আবার কাউকে বিশ্বাস করতে পারব?”\n\nমায়া উত্তর দিল,\n\n“আমি বিশ্বাস করি, আপনি পারবেন।”\n\nকিছুক্ষণ পর আরিশ লিখল,\n\n“আর আপনি? আপনি কি আমাকে বিশ্বাস করেন?”\n\nমায়া অনেকক্ষণ ফোনের দিকে তাকিয়ে রইল।\n\nতারপর লিখল,\n\n“হ্যাঁ, করি।”\n\nএই ছোট্ট উত্তরটা পড়ে আরিশের মুখে মৃদু হাসি ফুটে উঠল।\n\nকিন্তু সেই হাসির আড়ালেও একটা প্রশ্ন রয়ে গেল।\n\nসে কি সত্যিই অতীতের সবকিছু পেছনে ফেলে মায়ার দিকে এগিয়ে যেতে পারবে?\n\nনাকি নওরিনের ফিরে আসা তার জীবনে এমন এক ঝড় নিয়ে আসবে, যা মায়ার সঙ্গে তার তৈরি হতে থাকা সম্পর্কটাকেও বদলে দেবে?\n\nরাত গভীর হলো।\n\nমায়া জানালার পাশে দাঁড়িয়ে আকাশ দেখছিল।\n\nতার ফোনে আরিশের শেষ মেসেজটা তখনো খোলা।\n\n“আপনি আমার জীবনে এসেছেন বলে হয়তো আবার নতুন করে সবকিছু ভাবতে শিখছি।”\n\nমায়া মৃদু হাসল।\n\nসে জানত না, আরিশের এই কথার অর্থ ঠিক কতটা গভীর।\n\nশুধু মনে মনে বলল,\n\n“আমি জানি না আমাদের গল্পের শেষ কোথায়, আরিশ। তবে আমি চাই, আপনার জীবনে যদি কখনো ভালোবাসা ফিরে আসে, সেই ভালোবাসার মধ্যে যেন আর কোনো মিথ্যা না থাকে।”\n\nকিন্তু ভাগ্য তখন অন্য এক গল্প লিখছিল।\n\nপরদিন সকালে আরিশের ফোনে নওরিনের একটি মেসেজ এল।\n\n“আরিশ, তোমাকে একটা সত্য জানাতে হবে। এত দিন আমি তোমার কাছ থেকে যে কথাটা লুকিয়ে রেখেছিলাম, সেটাই আমাদের বিচ্ছেদের আসল কারণ।”\n\nআরিশ মেসেজটা পড়ে স্থির হয়ে গেল।\n\nনওরিন আবার লিখল,\n\n“আজ তোমাকে সব বলব। তারপর তুমি বুঝতে পারবে, কেন আমাকে সেদিন চলে যেতে হয়েছিল।”\n\nআরিশ ফোনটা শক্ত করে ধরে রইল।\n\nতার অতীতের যে অধ্যায়টাকে সে এত দিন শেষ বলে ভেবেছিল, সেই অধ্যায়ের শেষ পাতায় হয়তো এখনো কিছু লেখা বাকি।\n\nআর সেই সত্য জানার পর তার জীবনে কী বদলে যাবে, তা কেউ জানত না।\n\nচলবে...\n\nপরবর্তী পর্ব: ষষ্ঠ পর্বে নওরিন প্রকাশ করবে তাদের বিচ্ছেদের পেছনে লুকিয়ে থাকা সত্য। আর সেই সত্য জানার পর আরিশকে সিদ্ধান্ত নিতে হবে—সে কি অতীতের কাছে ফিরে যাবে, নাকি নতুন করে গড়ে ওঠা অনুভূতিকে একটা সুযোগ দেবে?','\n',char(10)),5,'published',0,'2026-10-27 15:14:57','2026-10-27 15:14:57',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('7fb511aa-9ca7-4715-b372-81fab0038331','70315848-fc25-4b07-8e69-adb1ac9c5483','হেরে গিয়েও যে হাড় মানেনি',replace('রাফি ছিল সাধারণ একটি ছেলে। তার স্বপ্ন ছিল একদিন নিজের পায়ে দাঁড়িয়ে পরিবারের মুখে হাসি ফোটাবে। কিন্তু জীবন তার জন্য সহজ ছিল না। বাবার সামান্য আয়ে সংসার চলত, আর অভাবের কারণে অনেক ইচ্ছাই অপূর্ণ থেকে যেত।\nএকদিন পরীক্ষায় খারাপ ফল করল রাফি। বন্ধুরা তাকে নিয়ে হাসাহাসি করল। কেউ বলল, “তোর দ্বারা জীবনে কিছুই হবে না!”\nকথাগুলো তার হৃদয়ে গভীর দাগ কাটল। সেদিন রাতে একা বসে সে ভাবল, সত্যিই কি সে ব্যর্থ?\nপরদিন সকালে রাফি দেখল, একজন বৃদ্ধ রাস্তার পাশে ছোট্ট দোকান খুলছেন। দোকানটি সাজাতে সাজাতে বৃদ্ধ বললেন, “বাবা, জানো তো? একটা গাছ একদিনে বড় হয় না। তাকে প্রতিদিন একটু একটু করে বেড়ে উঠতে হয়।”📖 গল্পের নাম: অন্ধকার পেরিয়ে আলো\nপাঠ ১: হেরে গিয়েও যে হার মানেনি\nরাফি ছিল সাধারণ একটি ছেলে। তার স্বপ্ন ছিল একদিন নিজের পায়ে দাঁড়িয়ে পরিবারের মুখে হাসি ফোটাবে। কিন্তু জীবন তার জন্য সহজ ছিল না। বাবার সামান্য আয়ে সংসার চলত, আর অভাবের কারণে অনেক ইচ্ছাই অপূর্ণ থেকে যেত।\nএকদিন পরীক্ষায় খারাপ ফল করল রাফি। বন্ধুরা তাকে নিয়ে হাসাহাসি করল। কেউ বলল, “তোর দ্বারা জীবনে কিছুই হবে না!”\nকথাগুলো তার হৃদয়ে গভীর দাগ কাটল। সেদিন রাতে একা বসে সে ভাবল, সত্যিই কি সে ব্যর্থ?\nপরদিন সকালে রাফি দেখল, একজন বৃদ্ধ রাস্তার পাশে ছোট্ট দোকান খুলছেন। দোকানটি সাজাতে সাজাতে বৃদ্ধ বললেন, “বাবা, জানো তো? একটা গাছ একদিনে বড় হয় না। তাকে প্রতিদিন একটু একটু করে বেড়ে উঠতে হয়।”','\n',char(10)),1,'published',0,'2026-10-27 16:31:59','2026-10-27 16:31:59',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('91758965-6b6e-4b05-a956-31683abc5122','f8eb53fa-f24b-4c87-b3d4-b504eeebf8b2','পর্ব ১: কালো চাঁদের রহস্য',replace('নীলশৈল গ্রামের কিশোর আরিন জানত না, তার জীবনে এক ভয়ংকর রহস্য লুকিয়ে আছে। নিজের ষোলোতম জন্মদিনের রাতে আকাশের চাঁদ কালো হয়ে গেল। একই সঙ্গে তার হাতে জ্বলে উঠল একটি নীল চিহ্ন।\n\nতার বাবা রায়ান ছুটে এসে বললেন, “আরিন, যদি আমাকে হারিয়ে ফেলিস, উত্তরের বনে যাবি। এই চাবি দিয়ে পাথরের দরজাটা খুলবি।”\n\nহঠাৎ অন্ধকার থেকে বেরিয়ে এল কালো পোশাক পরা এক রহস্যময় ব্যক্তি।\n\n“অবশেষে শেষ উত্তরাধিকারীকে খুঁজে পেলাম!”\n\nরায়ান ছেলেকে আড়াল করতেই নীল আলোয় ঘর কেঁপে উঠল। পরমুহূর্তে আরিনের বাবা অদৃশ্য হয়ে গেলেন।\n\nআরিন চিৎকার করে বলল, “আমার বাবাকে কোথায় নিয়ে গেছিস?”\n\nলোকটি হেসে বলল, “তুই কোনো সাধারণ ছেলে নস! তোর শরীরে ঘুমিয়ে আছে এক হারানো সাম্রাজ্যের শক্তি।”\n\nলোকটি অদৃশ্য হয়ে গেল। আরিনের হাতে থাকা চাবিটি জ্বলে উঠল। দূরের বনে খুলে গেল এক বিশাল পাথরের দরজা।\n\nদরজার ওপাশ থেকে ভেসে এল একটি কণ্ঠ—\n\n“স্বাগতম, শেষ রাজপুত্র! হাজার বছরের অপেক্ষা আজ শেষ হলো!”\n\nআরিন বুঝতে পারল, তার জীবনের সবচেয়ে বড় রহস্যের শুরু মাত্র।\n\nচলবে...\nআগামী পর্ব৷ চাইলে অবশ্যই পাশে থেকে সাহায্য করবেন আমি নতুন লেখক তাই সাহায্য ও সহযোগিতা করবেন','\n',char(10)),1,'published',0,'2026-10-27 16:32:14','2026-10-27 16:32:14',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('5fe06bde-e335-43d5-ac6c-2070b009d484','aca31ba8-956d-4587-8c86-eec72cc2d6be','পর্ব : ১',replace('সালটা ১৯৯৪,  \n\nনভেম্বরের মাঝামাঝি সময় চলছে। গোধুলি বিকেলে দিনের শেষ আলোক রশ্মি চারদিক ছড়িয়ে পড়ছে। গাছের পাতার ফাক দিয়ে মৃদু শীতল বাতাস বয়ে যাচ্ছে। আকাশে হালকা কমলা রঙের আভা দেখা যাচ্ছে।  সবমিলিয়ে প্রকৃতি  যেন নিজেই শীত আগমনের বার্তা দিচ্ছে। সব মিলিয়ে এক অপূর্ব সুন্দর শান্ত পরিবেশ তৈরি করেছে প্রকুতি।\n\nএমনই এর  গোধূলি বিকেলে মোহনগঞ্জ সরকারি কলেজের মাঠে বসে আছে আদনান চৌধুরী।  হাতে তার একটা ছোট নোট খাতা আর কলম। সেই খাতার  পাতায় সে লিখে চলেছে একের পর এক মনোমুগ্ধকর কবিতার লাইন, যেন তার নিজের সব অনুভুতি শব্দ হয়ে কবিতার  মাধ্যমে ফুটে উঠছে।  গভীর মনোযোগ দিয়ে লিখছে আদনান। একটু পর পর আকাশের দিকে তাকিয়ে নতুন উদ্যমে লেখা শুরু করে।  এরকম এক গোধূলি বিকেল যেন কবিতা লেখার জন্য মোক্ষম সময়।  প্রকৃতির অপরূপ সৌন্দর্য নিজেই কবিতা হয়ে খাতার পাতায় ফুটে উঠে। আদনানও ঠিক তেমনই হারিয়ে গিয়েছে প্রকৃতির অপরুপ সৌন্দর্যে আর লিখে যাচ্ছো তার কবিতার লাইন। এমন সময় কারো পায়ের আওয়াজে তার ধ্যান ভেঙ্গে গেলো। কেউ যেন আদনানের দিকেই এগিয়ে আসছে। তার ভাবনার ধ্যান ভেঙে যাওয়ার কিছু বিরক্তি নিয়ে পিছনে তাকালো দেখলো কৃষ্ণবর্নের  একটি মেয়ে অবয়ব তার দিকে এগোচ্ছে। গোধুলির ম্লান আলোয় মৃদু বাতাসে মেয়েটির লম্বা চুল গুলো দুলছে, পড়নে একটি হালকা নীল রংয়ের একটি জামা আর বুকের উপর আড়াআড়ি ভাবে ওড়না রয়েছে। বিকেলের কমলা রংয়ের আভায় মেয়েটার মুখ যেন আরো মায়াবী লাগছিল। কৃষ্ণবর্ণের হওয়া শর্তেও  মেয়েটার মুখে যেন আলাদা এক ধরনের কমল মায়া আছে। কিন্তু আদনান আর সে দিকে মন দিলো না সে আবার নিজের কবিতা লেখা মন দিকে যাবে সেই সময় মেয়েটা আদনানকে ডেকে জিজ্ঞেস করলো,  \n\n- একি আপনি এখনও এখানে বসে আছেন বাড়িতে যাবেন না? আর কিছুক্ষন পর সন্ধ্যা নেমে আসবে। তারউপর কলেজের গেট বন্ধ করে দেবে দারোয়ান  কাকা। পড়ে বের হবেন কিভাবে আপনি?\n\nমেয়েটার উপর কিছুটা বিরক্তি আসলো আদনানের কিছুটা না বরং অনেকটাই। কি সুন্দর মন দিয়ে কবিতা লিখছিলো মেয়েটা এসে সব নষ্ট করে দিলো৷ কিন্তু মেয়েটা তো ঠিকই বলেছে সন্ধ্যা প্রায় হয়ে এলো কখন সময় চলে যেছে তার কোনো খোজই নেই আদনানের হয়তো মেয়েটা ডাক না দিলে দারোয়ান গেট বন্ধ করে দিতো আর ভেতর আদনান আটকা পড়ে থাকতো। মেয়েটার উপর বিরক্ত হলেও তাকে ধন্যবাদ দেওয়ার জন্য কিছু বলবে তার আগে মেয়েটা আবার বলা শুরু করলো, \n\n- আরে কি হলো কখন থেকে চুপ করে আছেন কিছু বলছেন না কেন? যান যান বাড়িতে যান পরে গেট বন্ধ করে দিলে রাতে এখানেই থাকতে হবে আপানাকে।\n\nএবার মেয়েটা থামতে আদনান হালকা হাসি দিয়ে বললো, \n\n- আসলে কখন যে সময় চলে গেছে বুজতে পারি নি।  আর ধন্যবাদ আপনাকে নয়তো আজকের রাতটা হয়তো এখানেই কাটাতে হতো। \n\nএই বলে আদনান দারিয়ে তার খাতা আর কলমটা পেন্টের পকেটে রেখে দিলো।  মেয়ে টাও আর দারালো না হাটা ধরলো বাড়ির পথে৷ মেয়েটার চলে যাওয়ার পানে আদনানের মনে হলো মেয়েটাকে কোথাও দেখেছে তাই মেয়েটাকে পেছন থেকে ডাকলো ,\n\n- এই যে ম্যাডাম শুনছেন! \n\nআতনানের ডাকে মেয়েটা পেছন ফিরে তাকালো দেখলো। মেয়েটা অবাক হয়ে বললো, \n\n- আপনি কি আমাকে ডাকছেন? \n\nআদনান মাথার মাধ্যমে হ্যাঁ জানালো।মেয়েটা সেখানেই দারালো আদনান মেয়েটার সামনে এসে কৌতুহল হয়ে জিজ্ঞেস করলো,\n\n- আপনাকে হয়তো আমি কোথাও দেখেছি?  \n\nতারপড় আদনান কিছু একটা মনে করে নিজেই বলা শুরু করলো, \n\n- তুমি এই কলেজেই ইন্টার প্রথম বর্ষের ছাত্রী তাই না? \n\nমেয়েটা কিছু না বলে শুধু উপর নিচ মাথা নাড়িয়ে হ্যাঁ বললো।  আদনান ঠিকই ধরেছে মেয়েটা এই কলেজেই পড়ে। কিছুক্ষন পর মেয়েটাই আদনানকে কৌতুহলী হয়ে জিজ্ঞেস  করলো,\n\n- এই আপনি আমাকে কিভাবে চিনেন? আমি কোন ক্লাসে পড়ি সেটাও জানেন দেখছি। তা আমার বিষয়ে এতকিছু কিভাবে জানলেন?\n\nমেয়েটার কথা শুনে আদনান বিরক্ত স্বরে  বললো, \n\n- না আপনাকে এই কলেজের ক্যামপাসে দেখেছি তাই জিজ্ঞেস করলাম। আমিও এই কলেজেই পড়ি অনার্স ৩য় বর্ষে।  চেনা চেনা লাগলো তাই ডেকেছিলাম। আপনার যদি খারাপ লেগে থাকে তাহলে মাফ করবেন!\n\nমেয়েটা কিছুক্ষন আদনানকে পরখ করে শান্ত স্বরে বলা শুরু করলো,\n\n- না না খারাপ লাগবে কেন! তারউপড় আপনি তো আমার সিনিয়র। আচ্ছা যাই হোক, আমি নীলাঞ্জনা রহমান।  আর আপনি? \n\nআদনানও সাবলীলভাবে জবাব দিলো, \n\n- আমি আদনান চৌধুরী।\n\nআদনান বা নিলাঞ্জনা তখনও জানত না, এই সাধারণ পরিচয়টাই একদিন তার জীবনের সবচেয়ে গুরুত্বপূর্ণ গল্প হয়ে উঠবে।\n\n************ \n\nধরনীতে বিকেল গড়িয়ে সন্ধ্যা নেমেছে বহুক্ষন হলো। মাগরিবের আজান এখনও শোনা যাচ্ছে কিছু মসজিদের মাইকে। ঝোপঝাড় থেকে ঝিঝি পোকার ডাক শোনা যাচ্ছে। নভেম্বর  মাস হওয়ায় এই সময়টাতে ভালোই ঠান্ডা পড়া শুরু হয়ে গিয়েছে৷ হালকা শীতল হাওয়ায় যেন শরীরে কম্পন বয়ে যায়। পাখীরা তাদের নিজ নিজ ঘরে ফিরেছে গিয়েছে। গ্রামের মানুষজন তাদের দৈনন্দিনের কাজ শেষ করে বাড়ির পথে হাটা ধরেছে। চায়ের দোকান গুলোতে মুরুব্বিরা মিলে গরম চায়ের কাপে চুমুক দিতে দিতে রেডিওতে দেশের খবর শুনছেন আর নিজেদের মধ্যেই  আলোচনা করছেন। \n\n***\n\n- সন্ধ্যা হয়ে রাত হতে চললো তাও মেয়েটার কোনো খোজ নেই। কে জানে কোথায় ঘুরে বেড়াচ্ছে? আমার কি কোনো কথা শুনবে! শুনবে না তো। \n\nরান্না ঘর থেকে নিলার মা সালনা বেগমের রাগান্বিত কন্ঠ শোনা যাচ্ছে৷ অন্দর মহলেই বসে চা আর বিস্কুট খাচ্ছেন সাথে রেডিওতে খবর শুনছেন জমিদার মাহবুবুর রহমান। সালমা বেগমের চিৎকার চেঁচামেচি শুনে রেডিওটা বন্ধ করলেন।  আর মাহবুবুর আর মনে মনে বিরবির করে বললেন\n\n- সত্যিই তো মেয়েটা তো এত দেরি করে না কখনও। আজ হঠাৎ এত দেরি হচ্ছে কেন? ওর প্রাইভেট তো শেষ হয়েছে আরো ১ ঘন্টা আগে তাহলে কোথায় গেলো মেয়েটা।\n\nমাহবুবুর দুশ্চিন্তা করতে লাগলেন মেয়ের জন্য। আর ওইদিকে রান্না ঘর থেকে সালমা বেগমের চিৎকার  চেঁচামেচি যেন থামছেই না। সব মিলিয়ে মাহবুবুল রহমানের মাথা ধরে এলো। শেষে তিনি সালমা বেগমেকে বিরক্ত স্বরে বললেন,\n\n- আহ সালমা থামো এবার! দেখছো মেয়েটা এখনও বাড়ি ফেরে নি। মেয়েটার জন্য চিন্তা না করে চিৎকার চেচামেচি শুরু করে দিয়েছো। \n\nমাহবুবুর রহমানের কথা শুনে যেন আরো তেঁতে উঠলেন। সালমা এবার রান্না ঘর থেকে বেড়িয়ে মাহবুবুর  রহমানের উপর রাগ দেখিয়ে বলতে লাগলেন,\n\n- চিৎকার চেচামেচি করবো না তো কি করবো?  সময় দেখেছেন একবার? রাত হতে চললো। অথচ বাড়ির মেয়ে এখন বাড়ির বাহিরে ঘুরে বেড়াচ্ছে।  গ্রামের লোক দেখলে তো আপনারই সম্মান যাবে। বলবে- জমিদার বাড়ির মেয়েদের ভালো শিক্ষা দেন নি।  এত রাতেও জমিদারের মেয়ে রাস্তায় ঘুরে বেড়াচ্ছে। তখন তো সবাই আপনাকে কথা শোনাবে। এজন্যই বলি মেয়েকে একটু শাসন করুন। কিন্তু কে শোনে কার কথা? মেয়েকে আশকারা দিয়ে দিয়ে মাথায় তুলছেন। তাই এখন আর কোনো কথা শোনে না আমার।\n\nএক নিঃশ্বাসে কথা গুলো বলে দম নিলেন সালমা। এদিকে মাহবুবুর রহমান চেয়ারের সাথে হেলান দিয়ে বসে রয়েছেন। কারন এখন তিনি যাই বলবেন সালমা তত বেশি কথা বাড়াবে। তাই মাহবুবুর কিছু না বলে চুপচাপ বসে রয়েছেন। এরইমধ্যে সালমার কথা শুনে ঘর থেকে বেরিয়ে এলেন নীলার দাদি জোহরা বেগম৷ বয়স ৬৯ পেরিয়েছে। বয়সের ভারে মেরুদণ্ডের বাঁকা হয়ে গিয়েছে যার ফলে লাঠি দিয়ে হাটা ছাড়া উপায় নেই।  লাঠির উপর ভর দিয়ে অন্দরের দিকে আসচ্ছেন জোহরা।  এসে সালমা কে বিরক্ত হয়ে বললেন,\n\n- কিগো বউ কি হইছে? ভর সন্ধ্যা বেলা এত চিৎকার চেচামেচি করতাছো কে? শান্তি মতো ঘরে বইসাও থাকতে পারতাছি না তুমাগো লাইগা। \n\nজোহরা বেগম আসতেই তার কাছেও নীলাঞ্জনার কথা বলতে শুরু করলেন৷ সালমার কথা শুনে তো জোহরা বেগম রাগে দাতে দাত পিষে মাহবুবরকে বললেন,\n\n- কিরে মাহবুব তোর মাইয়া কি কোনোদিন আমাগো কথা হুনবো না? মাইয়া মানুষ হইয়া রাত বিরাতে রাস্তায় রাস্তায় ঘুরতাছে এইডা কি ঠিক? গ্রামের মানুষ দেখলে কি কইবো ভাবছোস একবার। \n\nজোহরার কথায় সায় দিয়ে সালমাও বললেন,\n\n- আমিও সেটাইই বলছি মা। গ্রামের মানুষ কেমন সেটা সবার জানা। একটা ছোট কথাকে তারা টেনে কত বড় বানায়! তার উপর জমিদার বাড়ির নিয়ে কথা হলে তো আর কথাই নেই। পুরো গ্রাম জুরে কানাঘুষা শুরু হয়ে যায় । \n\nমাহবুবুর রহমান এখনও নিশ্চুপ।  কোনো কথা বলছেন না তিনি। এমন সময় সদর দরজায় কেউ কড়া দিলো। কেউ এসেছে ভেবে জোহরা আর সালমা দুজনে চুপ হয়ে গেল। মাহবুবুর রহমান উঠে বসলেন। সালমা বেগম গিয়ে দরজা খুলে দিলেন।\n\n************\n\nচলবে....','\n',char(10)),1,'published',0,'2026-10-27 16:52:39','2026-10-27 18:51:38',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('e348044e-2596-4cf4-bd19-ca626eb4f80c','f8eb53fa-f24b-4c87-b3d4-b504eeebf8b2','অন্ধকারের প্রথম দরজা',replace('ছায়াসাম্রাজ্য — পর্ব ২\n\nঅন্ধকারের প্রথম দরজা\n\nরাত যত গভীর হচ্ছিল, আরিনের হাতে থাকা কালো পাথরটি ততই উজ্জ্বল হয়ে উঠছিল। পাথরটির ভেতর থেকে ভেসে আসছিল অদ্ভুত এক ফিসফিসানি।\n\n“অবশেষে তুমি ফিরে এসেছ, শেষ উত্তরাধিকারী…”\n\nআরিন ভয়ে পাথরটি ছুড়ে ফেলতে চাইল, কিন্তু সেটি তার হাতের সঙ্গে আটকে গেল। হঠাৎ চারপাশের বাতাস ঠান্ডা হয়ে এল। ঘরের দেয়ালে ফুটে উঠল একটি অচেনা চিহ্ন—একটি কালো মুকুট, যার মাঝখানে জ্বলছে লাল আগুন।\n\nঠিক তখনই দরজায় তিনবার আঘাত পড়ল।\n\nঠক! ঠক! ঠক!\n\nবাইরে থেকে এক বৃদ্ধের কণ্ঠ ভেসে এল, “আরিন, দরজা খোলো! তোমার হাতে যা আছে, সেটা নিয়ে তারা আসছে!”\n\n“কারা?” আরিন কাঁপা গলায় জিজ্ঞেস করল।\n\nবৃদ্ধ উত্তর দিলেন, “যারা তোমার পরিবারকে শেষ করেছিল।”\n\nআরিনের বুকের ভেতরটা কেঁপে উঠল। এতদিন সে জানত, তার বাবা-মা এক দুর্ঘটনায় মারা গিয়েছিলেন। কিন্তু আজ প্রথমবার কেউ বলল, সেটা দুর্ঘটনা ছিল না।\n\nদরজা খুলতেই সে দেখল, বৃদ্ধের মুখে গভীর আতঙ্ক। তাঁর হাতে পুরোনো একটি বই, আর বইয়ের প্রচ্ছদে আঁকা সেই একই কালো মুকুট।\n\nবৃদ্ধ ধীরে বললেন, “তোমার বাবা ছিলেন ছায়াসাম্রাজ্যের শেষ সম্রাট। আর এখন… তারা তোমাকে খুঁজছে।”\n\nদূরে হঠাৎ শিঙার শব্দ শোনা গেল। জানালার বাইরে কালো পোশাক পরা কয়েকজন অশ্বারোহী এগিয়ে আসছে।\n\nবৃদ্ধ বইটি আরিনের হাতে দিয়ে বললেন, “পালাও! আজ রাতেই তোমাকে জানতে হবে, তুমি আসলে কে!”\n\nচলবে…','\n',char(10)),2,'published',0,'2026-10-27 17:09:55','2026-10-27 17:09:55',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('58145030-f8fe-4ebb-84cf-c170ef0d6242','8127d88d-b42f-479f-a0e9-91c75925f0d4','যেএ রাতে বদলে গেল সবকিছু',replace('মার্চ, ১৯৭১। পূর্ব পাকিস্তানের এক ছোট্ট গ্রাম।\n\nসন্ধ্যার আকাশে কালো মেঘ জমেছে। গ্রামের মেঠোপথ দিয়ে গরুগুলো বাড়ি ফিরছে। পুকুরঘাটে নারীরা কলসি ভরছে। অথচ সবার চোখেমুখে অজানা এক ভয়।\n\nসতেরো বছরের রায়হান উঠোনে বসে বই পড়ছিল। তার বাবা আবদুল কাদের ছিলেন গ্রামের একজন স্কুলশিক্ষক। মা আমেনা বেগম রান্নাঘরে রাতের খাবার তৈরি করছিলেন।\n\nহঠাৎ রায়হান বাবাকে প্রশ্ন করল,\n— বাবা, আমাদের দেশ কি কখনো স্বাধীন হবে?\n\nকাদের সাহেব ছেলের দিকে তাকালেন। তারপর শান্ত গলায় বললেন,\n— হবে বাবা। একদিন এই দেশের মানুষ নিজের অধিকার নিয়ে বাঁচবে। তবে স্বাধীনতার জন্য অনেক ত্যাগ স্বীকার করতে হয়।\n\nঠিক তখনই রায়হানের বন্ধু জামাল দৌড়ে এসে উঠোনে দাঁড়াল।\n\n— রায়হান! ঢাকায় খুব খারাপ অবস্থা। সবাই স্বাধীনতার কথা বলছে!\n\nকাদের সাহেব চিন্তিত হয়ে উঠলেন। ৭ মার্চ বঙ্গবন্ধু শেখ মুজিবুর রহমানের ঐতিহাসিক ভাষণ মানুষের মনে স্বাধীনতার স্বপ্ন জাগিয়ে তুলেছিল। বাংলার মানুষ তখন পরিবর্তনের অপেক্ষায়।\n\nরাত বাড়তে লাগল। খাওয়া শেষে রায়হান ঘুমাতে গেলেও তার চোখে ঘুম এল না। জানালার পাশে বসে সে আকাশের দিকে তাকিয়ে ভাবছিল, সত্যিই কি একদিন বাংলাদেশ স্বাধীন হবে?\n\nহঠাৎ দূর থেকে কয়েকজন মানুষের চিৎকার শোনা গেল।\n\n— যুদ্ধ শুরু হয়ে গেছে! পাকিস্তানি সেনারা ঢাকায় আক্রমণ করেছে!\n\nকাদের সাহেব দ্রুত বাইরে বেরিয়ে গেলেন। তাঁর মুখ ফ্যাকাশে হয়ে গেছে। আমেনা বেগম ছেলেকে বুকের কাছে টেনে নিলেন।\n\nসেই রাতে কেউ জানত না, আগামী দিনগুলো তাদের জন্য কত কঠিন হতে চলেছে।\n\nরায়হানও জানত না, যে বাবা তাকে সাহসের কথা শোনাতেন, সেই বাবার জীবনেই লুকিয়ে আছে এক গোপন সত্য।\n\nচলবে…','\n',char(10)),1,'published',0,'2026-10-27 18:06:27','2026-10-27 18:06:27',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('fa8be0a7-dc5f-4335-ad2a-d6a365cfcd89','4ae3989f-dbe0-4018-b9e3-cd2d44b85b0c','পৃষ্ঠা ১',replace('শিরোনাম: অন্য কারো উপন্যাসের মায়াবতী\n\nবয়সটা ছিল ষোলো, তারিখটা ছিল রবিবার। হাতে ছিল এক রক্তিম লাল গোলাপ, আর বুকভরা স্বপ্ন নিয়ে বের হয়েছিলাম এক মায়াবতীর খোঁজে।\n\nসারাটা দিন খুঁজেছি তাকে, হাজারো মুখের ভিড়ে খুঁজেছি তার মায়াভরা মুখ। সময় গড়িয়ে বিকেল হলো, সূর্যটাও ডুবে যাওয়ার অপেক্ষায়, তবুও আমার খোঁজ শেষ হয়নি।\n\nঅবশেষে দিনশেষে খুঁজে পেলাম তাকে, যার খোঁজে এতটা পথ পাড়ি দেওয়া। তাকে দেখে মনে হয়েছিল, আমার গল্পের নায়িকাকে বুঝি অবশেষে খুঁজে পেলাম।\n\nহাতে ছিল গোলাপ, মনে ছিল হাজারো না-বলা কথা। ইচ্ছে ছিল তাকে বলব, তোমাকে নিয়েই আমার সব কল্পনা।\n\nকিন্তু আফসোস! সে তো অন্য কারো গল্পের নায়িকা। আমি তাকে আমার উপন্যাসে লিখতে চেয়েছিলাম, অথচ সে অন্য কারো উপন্যাসে লেখা ছিল।\n\nসৃষ্টিকর্তা তাকে আমার নসিবে লেখেননি, লিখে রেখেছিলেন অন্য কারো ভাগ্যে।\n\nতাই তাকে খুঁজে পেয়েও নিজের করে পাওয়ার সৌভাগ্য হলো না। হাতে থাকা গোলাপটা আর দেওয়া হলো না, বুকের ভেতর জমে থাকা কথাগুলোও কখনো তার কাছে পৌঁছাল না।\n\nসেদিন বুঝেছিলাম, সব খোঁজের শেষ ঠিকানা পাওয়া নয়, কিছু খোঁজের শেষ হয় একটা অসমাপ্ত গল্পের মাধ্যমে।\n\nযে মায়াবতীকে খুঁজতে বের হয়েছিলাম, তাকে পেয়েছিলাম ঠিকই, শুধু আমার গল্পের নায়িকা হিসেবে নয়— অন্য কারো উপন্যাসের মায়াবতী হিসেবে। 🥀📖','\n',char(10)),1,'published',0,'2026-10-27 18:50:24','2026-10-27 18:50:24',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('9ee9b9fd-c9cc-405f-b8b5-d8d6d34a1f4f','3cd9c22b-ae96-4503-8d89-f3ee32cb2c07','বন্ধ দরজার অপাসে',replace('রাত তখন ১২টা ১৭ মিনিট। চারদিকে নিস্তব্ধতা, আকাশে কালো মেঘ। গ্রামের শেষ প্রান্তে দাঁড়িয়ে থাকা লাল বাড়িটির ভেতর থেকে হঠাৎ ভেসে এল একটি গুলির শব্দ!\n\nপরদিন সকালে বাড়িটির সামনে জড়ো হলো পুরো গ্রামের মানুষ। বাড়ির মালিক জমিদার রাশেদ চৌধুরীকে তাঁর নিজের ঘরে মৃত অবস্থায় পাওয়া গেছে। আশ্চর্যের বিষয়, ঘরের দরজা ভেতর থেকে বন্ধ ছিল। জানালাগুলোও আটকানো। অথচ ঘরের মেঝেতে পড়ে ছিল রক্তমাখা একটি ছুরি আর দেয়ালে লেখা তিনটি শব্দ—\n\n“খুনি এখনো এখানে!”\n\nপুলিশ এসে তদন্ত শুরু করল। কিন্তু কোনো দরজা ভাঙার চিহ্ন নেই, কোনো পায়ের ছাপ নেই। যেন খুনিটি বাতাসে মিলিয়ে গেছে!\n\nএই রহস্যের সমাধানের দায়িত্ব পেল ঢাকার তরুণ গোয়েন্দা আরিয়ান রহমান। ঘটনাস্থলে পৌঁছে সে প্রথমেই লক্ষ করল, ঘরের দেয়ালে ঝোলানো একটি পুরোনো ঘড়ি বন্ধ হয়ে আছে ঠিক ১২টা ১৭ মিনিটে।\n\nআরিয়ান ঘড়িটি নামিয়ে পেছনে হাত দিতেই বেরিয়ে এল একটি ছোট চাবি। চাবির সঙ্গে জড়িয়ে থাকা কাগজে লেখা—\n\n“যদি সত্য জানতে চাও, বাড়ির নিচতলার বন্ধ ঘরটি খোলো।”\n\nরাত নামতেই আরিয়ান একা নিচতলায় গেল। বহু বছরের পুরোনো দরজাটি খুলতেই ভেতর থেকে ভেসে এল পচা কাঠের গন্ধ। ঘরের মাঝখানে পড়ে ছিল একটি পুরোনো ছবি।\n\nছবিতে জমিদার রাশেদ চৌধুরীর পাশে দাঁড়িয়ে থাকা লোকটিকে দেখে আরিয়ান থমকে গেল।\n\nলোকটি আর কেউ নয়—আরিয়ানের নিজের বাবা, যিনি দশ বছর আগে নিখোঁজ হয়েছিলেন!\n\nঠিক তখনই পেছন থেকে দরজা বন্ধ হওয়ার শব্দ এল।\n\nঅন্ধকারের ভেতর কেউ একজন ফিসফিস করে বলল—\n\n“অবশেষে তুমি এসেছ, গোয়েন্দা সাহেব। এবার তোমার বাবার মতো তুমিও হারিয়ে যাবে!”','\n',char(10)),1,'published',0,'2026-10-27 18:52:46','2026-10-27 18:52:46',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('750d0f8a-f5ca-48c3-9847-36a64af96b95','4ae3989f-dbe0-4018-b9e3-cd2d44b85b0c','পৃষ্ঠা ২',replace('শিরোনাম: যেদিন বুঝবে, সেদিন আমি থাকব না\n\nতুমি হয়তো জানো না, অথবা জেনেও অজানা হয়ে আছো, যে আমি তোমাকে কতটা ভালোবাসি।\n\nহয়তো আজ তুমি আমার ভালোবাসার মূল্য বুঝতে পারছো না, অথবা বুঝেও না বোঝার ভান করে আছো। কিন্তু আমার বিশ্বাস, একদিন তুমি ঠিকই আমার ভালোবাসার গভীরতা বুঝবে।\n\nকিন্তু জানো, সেদিন একটা আফসোস থেকে যাবে।\n\nযেদিন তুমি বুঝবে, একটা ছেলে তোমাকে কতটা নিঃস্বার্থভাবে ভালোবেসেছিল, যেদিন তুমি আমার ভালোবাসার মূল্য বুঝে আমাকে খুঁজতে আসবে, আমার সামনে দাঁড়িয়ে বলবে, ‘আমিও তোমাকে ভালোবাসি।’\n\nসেদিন হয়তো তোমার বলার মতো অনেক কথা থাকবে, থাকবে বুকভরা অনুভূতি, থাকবে আমাকে আপন করে পাওয়ার ইচ্ছে।\n\nকিন্তু আফসোস, সেদিন তোমার সেই কথাগুলো শোনার জন্য আমি আর তোমার সামনে থাকব না।\n\nকারণ ততদিনে আমি পাড়ি দেব এক দীর্ঘ পথ, যে পথের কোনো শেষ নেই, যে পথে ফিরে আসার কোনো ঠিকানা নেই।\n\nতুমি হয়তো তখন আমার পুরোনো কথাগুলো পড়বে, আমার লেখা প্রতিটি লাইনে খুঁজবে নিজের নাম, আর বুঝতে পারবে, কেউ একজন সত্যিই তোমাকে কতটা ভালোবেসেছিল।\n\nকিন্তু তখন তোমার ভালোবাসা প্রকাশ করার সময় থাকলেও, আমার কাছে ফিরে আসার সময়টা আর থাকবে না।\n\nসব ভালোবাসার গল্পে মিলন লেখা থাকে না। কিছু ভালোবাসা শুধু আফসোস হয়ে থেকে যায়— একজনের মনে, অন্যজনের দেরিতে বুঝতে পারা অনুভূতিতে। 🥀','\n',char(10)),1,'published',0,'2026-10-27 20:36:06','2026-10-27 20:36:06',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('6323b055-5fd2-4f52-928c-5f8f34d8fdbd','3cd9c22b-ae96-4503-8d89-f3ee32cb2c07','অন্ধকারে বন্ধী',replace('🔴 লাল বাড়ির রহস্য\n\nলেখক: নিবিড় আহমেদ\n\nদরজা বন্ধ হওয়ার শব্দে আরিয়ান ঘুরে দাঁড়াল। চারদিকে ঘুটঘুটে অন্ধকার। পকেট থেকে টর্চ বের করে সে আলো ফেলতেই দেখতে পেল, দরজার সামনে কেউ একজন দাঁড়িয়ে আছে।\n\n“কে আপনি? সামনে আসুন!” আরিয়ান চিৎকার করল।\n\nকিন্তু লোকটি কোনো উত্তর দিল না। কয়েক সেকেন্ড পর তার পায়ের শব্দ ধীরে ধীরে মিলিয়ে গেল।\n\nআরিয়ান দরজা খোলার চেষ্টা করল। দরজাটি বাইরে থেকে আটকে দেওয়া হয়েছে। ঘরের ভেতরে আটকে পড়ে সে আবার ছবিটির দিকে তাকাল। ছবির পেছনে আগে চোখে না পড়া কয়েকটি শব্দ লেখা ছিল—\n\n“রাশেদকে যে মেরেছে, সে তার সবচেয়ে কাছের মানুষ।”\n\nহঠাৎ ঘরের এক কোণে মৃদু শব্দ হলো। আরিয়ান টর্চের আলো ফেলতেই দেখতে পেল, দেয়ালের পাশে একটি কাঠের বাক্স। বাক্সটি খুলে পাওয়া গেল কিছু পুরোনো চিঠি, একটি রক্তমাখা রুমাল আর একটি ডায়েরি।\n\nডায়েরির প্রথম পাতায় লেখা— “আমার মৃত্যুর পর এই ডায়েরি যে পড়বে, সে যেন কাউকে বিশ্বাস না করে।”\n\nআরিয়ান দ্রুত পাতা উল্টাতে লাগল। এক জায়গায় এসে তার চোখ আটকে গেল। সেখানে লেখা ছিল, দশ বছর আগে এই বাড়িতে একটি খুন হয়েছিল। সেই ঘটনার সঙ্গে জড়িয়ে ছিল আরিয়ানের বাবা, জমিদার রাশেদ এবং গ্রামের আরও একজন প্রভাবশালী ব্যক্তি।\n\nঠিক তখনই বাইরে থেকে দরজা খোলার শব্দ হলো।\n\nএকজন বৃদ্ধ ঘরে ঢুকে কাঁপা গলায় বললেন, “বাবা, তুমি এখানে কী করছ? এই ঘরে কেউ ঢুকলে সে আর জীবিত বের হয় না!”\n\nআরিয়ান বৃদ্ধকে চিনতে পারল। তিনি এই বাড়ির পুরোনো দারোয়ান, করিম চাচা।\n\n“আমার বাবাকে আপনি চিনতেন?” আরিয়ান প্রশ্ন করল।\n\nবৃদ্ধের মুখ ফ্যাকাশে হয়ে গেল। তিনি কিছুক্ষণ চুপ থেকে বললেন, “শুধু চিনতাম না, বাবার শেষ রাতেও আমি তাঁর সঙ্গে ছিলাম।”\n\n“তাহলে তিনি কোথায়?”\n\nকরিম চাচা উত্তর দেওয়ার আগেই বাড়ির ওপরতলা থেকে আরেকটি গুলির শব্দ ভেসে এল!\n\nদুজনেই দৌড়ে ওপরে গেল। সেখানে পড়ে ছিল গ্রামের চেয়ারম্যানের ছেলে সাদমান। তার পাশে পড়ে থাকা কাগজে লেখা—\n\n“প্রথম খুন ছিল সতর্কবার্তা। এবার পালা গোয়েন্দার!”\n\nআরিয়ান কাগজটি হাতে নিয়ে বুঝতে পারল, খুনি শুধু এই বাড়ির ভেতরেই নেই—সে আরিয়ানের প্রতিটি পদক্ষেপের খবর জানে।\n\nকিন্তু সবচেয়ে ভয়ংকর বিষয়টি তখনও তার অজানা ছিল।\n\nকরিম চাচা আড়ালে গিয়ে ফোন বের করলেন। ওপাশ থেকে কেউ কথা বলতেই তিনি ফিসফিস করে বললেন—\n\n“স্যার, আরিয়ান সব জেনে যাচ্ছে। এবার কি ওকেও সরিয়ে দেব?”\n\nফোনের ওপাশ থেকে উত্তর এল—\n\n“না। ওকে বাঁচতে দাও। কারণ ওর বাবার আসল পরিচয় ও এখনো জানে না!”','\n',char(10)),2,'published',0,'2026-10-28 04:03:33','2026-10-28 04:03:33',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('321b011c-e385-463a-b1ae-d3c0e0321898','3cd9c22b-ae96-4503-8d89-f3ee32cb2c07','রক্তমাখা ডাইরি',replace('লাল বাড়ির রহস্য\n\nতৃতীয় পর্ব\n\nলেখক: নিবিড় আহমেদ\n\nচেয়ারম্যানের ছেলেকে হাসপাতালে পাঠানোর পর আরিয়ান আবার সেই গোপন ঘরে ফিরে এল। তার মাথায় তখন একটাই প্রশ্ন—দশ বছর আগে ঠিক কী ঘটেছিল এই বাড়িতে?\n\nকরিম চাচাকে সামনে বসিয়ে সে বলল, “আপনি সব জানেন। এবার সত্যিটা বলুন।”\n\nবৃদ্ধ দীর্ঘশ্বাস ফেলে বললেন, “দশ বছর আগে এই বাড়ির মালিক ছিলেন রাশেদ চৌধুরীর বড় ভাই, মাহবুব চৌধুরী। এক রাতে তিনি নিখোঁজ হন। সবাই বলেছিল, তিনি বিদেশে পালিয়েছেন। কিন্তু আমি জানতাম, তাঁর নিখোঁজ হওয়ার পেছনে খুনের রহস্য রয়েছে।”\n\n“আমার বাবা কোথায় জড়িত ছিলেন?”\n\nকরিম চাচা উত্তর দেওয়ার আগেই বাইরে গাড়ির শব্দ শোনা গেল। জানালা দিয়ে আরিয়ান দেখল, কালো পোশাক পরা দুজন লোক বাড়িতে ঢুকছে।\n\nসে দ্রুত ডায়েরিটি নিজের ব্যাগে রাখল। দুজন লোক ঘরে ঢুকেই করিম চাচাকে ধরে ফেলল। একজন পিস্তল দেখিয়ে বলল, “ডায়েরিটা কোথায়?”\n\nআরিয়ান বুঝল, ডায়েরির ভেতরেই এমন প্রমাণ আছে, যা খুনিকে বিপদে ফেলতে পারে। সে পেছনের গোপন দরজা দিয়ে বেরিয়ে গ্রামের পুরোনো মসজিদের কাছে পৌঁছাল।\n\nনিরাপদ জায়গায় গিয়ে ডায়েরি খুলতেই একটি ভাঁজ করা চিঠি বেরিয়ে এল। চিঠিতে লেখা—\n\n“আরিয়ান, যদি তুমি এই চিঠি পড়ো, তবে জেনে রেখো, তোমার বাবা বিশ্বাসঘাতক ছিলেন না। তাঁকে ফাঁসানো হয়েছিল।”\n\nনিচে স্বাক্ষর—মাহবুব চৌধুরী!\n\nআরিয়ান অবাক হয়ে গেল। মাহবুব যদি সত্যিই বেঁচে থাকেন, তবে তিনি কোথায়?\n\nঠিক তখনই অচেনা নম্বর থেকে ফোন এল।\n\nওপাশের কণ্ঠ বলল, “তোমার বাবাকে খুঁজতে চাইলে আগামীকাল পুরোনো রেলস্টেশনে এসো। কিন্তু পুলিশ নিয়ে এলে আর কোনো সত্য জানতে পারবে না।”\n\nফোন কেটে গেল।\n\nআরিয়ান জানত, এটি ফাঁদও হতে পারে। তবু সে সিদ্ধান্ত নিল, রহস্যের শেষ পর্যন্ত যেতেই হবে।','\n',char(10)),3,'published',0,'2026-10-28 04:50:38','2026-10-28 04:50:38',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('eb149278-bdca-4159-b539-c865cdb402cd','3cd9c22b-ae96-4503-8d89-f3ee32cb2c07','শেষ ট্রেনের যাত্রি',replace('লাল বাড়ির রহস্য\n\nচতুর্থ পর্ব\n\nলেখক: নিবিড় আহমেদ\n\nপরদিন রাত সাড়ে দশটায় আরিয়ান পৌঁছাল গ্রামের পরিত্যক্ত রেলস্টেশনে। বহু বছর ধরে এখানে কোনো ট্রেন থামে না। চারদিকে ঝোপঝাড় আর অন্ধকার।\n\nপ্ল্যাটফর্মের শেষ প্রান্তে একজন লোক দাঁড়িয়ে ছিল। মুখে কালো কাপড়, হাতে একটি পুরোনো ব্যাগ।\n\n“আপনি কি আমার বাবাকে চেনেন?” আরিয়ান জিজ্ঞেস করল।\n\nলোকটি মাথা নাড়ল। “তোমার বাবা বেঁচে আছেন। কিন্তু তাঁকে খুঁজে পেতে হলে জানতে হবে, রাশেদ চৌধুরী কেন খুন হয়েছিল।”\n\n“খুনি কে?”\n\nলোকটি ব্যাগ থেকে একটি ছবি বের করল। ছবিতে রাশেদ, চেয়ারম্যানের বাবা এবং আরিয়ানের বাবা একসঙ্গে দাঁড়িয়ে আছেন। পেছনে লেখা একটি তারিখ—বারো বছর আগের।\n\nলোকটি বলল, “ওই রাতে তারা একটি জমির দলিল নিয়ে ঝগড়া করেছিল। দলিলটি প্রমাণ করত, লাল বাড়ি আর আশপাশের জমি আসলে মাহবুব চৌধুরীর।”\n\nআরিয়ান ছবিটি হাতে নিতেই দূর থেকে গাড়ির আলো দেখা গেল। লোকটি তাড়াতাড়ি বলল, “ওরা চলে এসেছে! ছবিটা নিয়ে পালাও!”\n\nহঠাৎ একটি গুলির শব্দ হলো। লোকটি মাটিতে পড়ে গেল। আরিয়ান তাকে সাহায্য করতে এগিয়ে গেল, কিন্তু লোকটি তার হাত চেপে ধরে ফিসফিস করল, “চেয়ারম্যানকে বিশ্বাস কোরো না। সে শুধু সহযোগী। আসল খুনি তোমার খুব কাছের মানুষ।”\n\nএরপর লোকটির চোখ বন্ধ হয়ে গেল।\n\nআরিয়ান দ্রুত সেখান থেকে সরে পড়ল। বাড়ি ফিরে ছবিটি পরীক্ষা করতে গিয়ে সে ছবির পেছনে আরেকটি লেখা দেখতে পেল—\n\n“বিশ্বাসঘাতককে চিনতে হলে নিজের পরিবারের ইতিহাস পড়ো।”\n\nঠিক তখনই তার ফোনে একটি বার্তা এল। প্রেরকের নাম দেখে সে স্তব্ধ হয়ে গেল।\n\nবার্তাটি পাঠিয়েছে তার নিখোঁজ বাবা!\n\nবার্তায় লেখা, “আরিয়ান, আমাকে খুঁজো না। তোমার নিজের জীবন বিপদে।”','\n',char(10)),4,'published',0,'2026-10-28 04:51:39','2026-10-28 04:51:39',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('28fe43d5-10ad-4322-b3cb-9f8606cb795c','3cd9c22b-ae96-4503-8d89-f3ee32cb2c07','বাবার গোপন পরিচয়',replace('লাল বাড়ির রহস্য\n\nপঞ্চম পর্ব\n\nলেখক: নিবিড় আহমেদ\n\nবাবার বার্তাটি বারবার পড়ছিল আরিয়ান। দশ বছর ধরে যাঁকে মৃত অথবা নিখোঁজ ভেবে এসেছে, তিনি কীভাবে এখনো বেঁচে আছেন?\n\nসে পুরোনো পারিবারিক কাগজপত্র খুঁজতে বাড়িতে গেল। মায়ের আলমারির নিচে একটি লোহার বাক্স পেল। বাক্সে ছিল কিছু ছবি, জন্মনিবন্ধনের পুরোনো কাগজ এবং একটি চিঠি।\n\nচিঠিতে তার বাবা লিখেছিলেন, “আমি যদি কোনো দিন ফিরে না আসি, আরিয়ান যেন জানতে পারে—আমি অপরাধী নই। মাহবুবের হত্যার সত্য প্রকাশ করতে গিয়ে আমাকে পালিয়ে থাকতে হয়েছে।”\n\nচিঠির সঙ্গে একটি ঠিকানা ছিল। আরিয়ান সেখানে পৌঁছে দেখল, ছোট্ট একটি বাড়িতে একজন অসুস্থ বৃদ্ধ থাকেন। বৃদ্ধ তাকে দেখে কেঁদে ফেললেন।\n\n“বাবা, তুমি বড় হয়ে গেছ!”\n\nআরিয়ান অবিশ্বাসে তাকিয়ে রইল। “আপনি আমার বাবা?”\n\nবৃদ্ধ মাথা নাড়লেন। তিনি জানালেন, তাঁর নাম আবদুল কাদের। একসময় তিনি লাল বাড়ির হিসাবরক্ষক ছিলেন। মাহবুবের হত্যার রাতে তিনি এমন একটি দলিল দেখেছিলেন, যা রাশেদের পরিবারের অপরাধ প্রকাশ করে দিতে পারত। সেই দলিলের জন্যই তাঁকে মিথ্যা মামলায় ফাঁসানো হয়। প্রাণ বাঁচাতে তিনি পালিয়ে যান।\n\n“কিন্তু রাশেদকে কে খুন করল?” আরিয়ান প্রশ্ন করল।\n\nবাবা উত্তর দিলেন, “আমি জানি না। তবে আমার কাছে খুনের রাতের একটি রেকর্ডিং আছে।”\n\nতিনি পুরোনো একটি রেকর্ডার চালু করলেন। প্রথমে অস্পষ্ট শব্দ, তারপর রাশেদের কণ্ঠ শোনা গেল—\n\n“আমি সব জানি! তুমি মাহবুবকে মেরেছিলে!”\n\nএরপর আরেকটি কণ্ঠ উত্তর দিল, “তাহলে আজ তোমাকেও চুপ করাতে হবে।”\n\nআরিয়ান কণ্ঠটি চিনতে পেরে স্তব্ধ হয়ে গেল।\n\nসেটি ছিল গ্রামের চেয়ারম্যানের!\n\nকিন্তু রেকর্ডিংয়ের শেষ অংশে আরেকটি শব্দ শোনা গেল—একটি দরজা খোলার শব্দ, তারপর তৃতীয় একজনের কণ্ঠ।\n\n“চেয়ারম্যান, সরে দাঁড়ান। আসল কাজটা আমাকে করতে দিন।”','\n',char(10)),5,'published',0,'2026-10-28 04:52:23','2026-10-28 04:52:23',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('c98dbc4f-252e-469f-a264-cd2679000581','3cd9c22b-ae96-4503-8d89-f3ee32cb2c07','খুনির মুখোশ',replace('লাল বাড়ির রহস্য\n\nষষ্ঠ পর্ব\n\nলেখক: নিবিড় আহমেদ\n\nরেকর্ডিং শুনে আরিয়ান বুঝল, চেয়ারম্যান একা এই ষড়যন্ত্রের সঙ্গে জড়িত নন। তৃতীয় ব্যক্তির কণ্ঠটি চিনতে তার বেশি সময় লাগল না—এটি ছিল সাদমানের কাকা, আইনজীবী ফারুকের।\n\nফারুক বহু বছর ধরে চৌধুরী পরিবারের সম্পত্তির কাগজপত্র দেখাশোনা করতেন। আরিয়ান সিদ্ধান্ত নিল, তাঁকে সরাসরি জিজ্ঞাসাবাদ করবে।\n\nপরদিন সে চেয়ারম্যানের বাড়িতে গেল। চেয়ারম্যান প্রথমে সব অস্বীকার করলেন। কিন্তু আরিয়ান রেকর্ডিংয়ের কথা বলতেই তাঁর মুখের রং বদলে গেল।\n\n“তুমি বুঝতে পারছ না, আরিয়ান,” চেয়ারম্যান বললেন। “আমি শুধু নিজের পরিবারকে বাঁচাতে চেয়েছিলাম। মাহবুবের মৃত্যুর সঙ্গে আমার সম্পর্ক নেই।”\n\n“তাহলে ফারুকের সম্পর্ক কী?”\n\nচেয়ারম্যান চুপ করে রইলেন।\n\nঠিক তখনই সাদমান এসে জানাল, তার জ্ঞান ফিরেছে। হাসপাতালে সে একজন লোককে দেখেছে, যে তাকে গুলি করার আগে বলেছিল, “ফারুক সাহেবের আদেশ।”\n\nআরিয়ান পুলিশের সাহায্যে ফারুকের অফিসে গেল। কিন্তু অফিস খালি। টেবিলের ওপর পড়ে ছিল লাল বাড়ির মূল দলিল এবং একটি চিরকুট—\n\n“সত্য জানতে চাইলে আজ মধ্যরাতে বাড়িতে এসো। একা।”\n\nআরিয়ান বুঝল, ফারুক পালানোর আগে শেষ চাল দিতে চাইছেন। সে গোপনে পুলিশকে খবর দিয়ে লাল বাড়ির দিকে রওনা দিল।\n\nমধ্যরাতে বাড়িতে ঢুকে সে দেখল, ফারুক একটি পুরোনো আলমারি খুলছেন। আরিয়ানের উপস্থিতি টের পেয়ে তিনি ঘুরে দাঁড়ালেন।\n\n“অবশেষে এসেছ,” ফারুক বললেন। “তোমার বাবার জীবন বাঁচাতে চাইলে ডায়েরি আর রেকর্ডিং আমাকে দাও।”\n\n“আপনি রাশেদকে খুন করেছেন?”\n\nফারুক হেসে বললেন, “রাশেদকে আমি খুন করিনি। তবে খুনিকে আমি চিনি।”\n\nতিনি দেয়ালের একটি গোপন সুইচ চাপতেই মেঝের নিচে দরজা খুলে গেল।\n\nসিঁড়ির নিচে অন্ধকারে একজন মানুষ বসে ছিলেন। আরিয়ান আলো ফেলতেই তাঁর বুক কেঁপে উঠল।\n\nসেখানে বসে ছিলেন দশ বছর আগে নিখোঁজ হওয়া মাহবুব চৌধুরী—যাঁকে সবাই মৃত বলে জানত!','\n',char(10)),6,'published',0,'2026-10-28 04:52:56','2026-10-28 04:52:56',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('fa52456f-e800-49a7-a199-7e53dc6a4392','3cd9c22b-ae96-4503-8d89-f3ee32cb2c07','লাল বাড়ির শেষ সত্য',replace('লাল বাড়ির রহস্য\n\nসপ্তম পর্ব\n\nলেখক: নিবিড় আহমেদ\n\nমাহবুব চৌধুরীকে দেখে আরিয়ান হতবাক হয়ে গেল। ফারুক এত বছর ধরে তাঁকে গোপন ঘরে আটকে রেখেছিলেন, যাতে সম্পত্তির আসল মালিকানা কখনো প্রকাশ না পায়।\n\nআরিয়ান বলল, “তাহলে রাশেদকে কে খুন করেছে?”\n\nফারুক পালানোর চেষ্টা করলেন। কিন্তু ঠিক তখনই পুলিশ বাড়ির ভেতরে ঢুকে তাঁকে ঘিরে ফেলল। আরিয়ানের দেওয়া আগাম খবরের কারণে বাড়িটি আগেই ঘিরে রাখা হয়েছিল।\n\nপ্রমাণের মুখে ফারুক ভেঙে পড়লেন। তিনি স্বীকার করলেন, বহু বছর আগে সম্পত্তি দখলের জন্য মাহবুবকে বন্দি করেছিলেন। রাশেদ সত্য প্রকাশ করতে চাইলে তাঁকেও খুন করেন। চেয়ারম্যান অপরাধটি জানতেন, কিন্তু নিজের ছেলেকে বিপদে পড়তে না দেওয়ার জন্য সত্য গোপন করেছিলেন।\n\nপুলিশ ফারুক ও চেয়ারম্যানকে গ্রেপ্তার করল। মাহবুবকে উদ্ধার করে হাসপাতালে নেওয়া হলো। আরিয়ানের বাবার বিরুদ্ধেও মিথ্যা অভিযোগের প্রমাণ পাওয়া গেল, ফলে তাঁর নাম পরিষ্কার হলো।\n\nসব রহস্যের সমাধান হয়ে গেছে ভেবে আরিয়ান বাড়ি থেকে বেরিয়ে আসছিল। তখন মাহবুব তাকে ডেকে বললেন, “তুমি সাহস করে সত্য খুঁজেছ। কিন্তু এই বাড়িতে আরও একটি গোপন কথা আছে।”\n\nতিনি আরিয়ানকে একটি ছোট বাক্স দিলেন। বাক্সের ভেতরে ছিল তার মায়ের পুরোনো ছবি এবং একটি চিঠি।\n\nচিঠিতে লেখা—\n\n“আরিয়ান, তোমার বাবা তোমাকে বাঁচানোর জন্যই দূরে চলে গিয়েছিলেন। তোমার জন্মের আগেই তিনি জানতেন, এই বাড়ির লোভী মানুষগুলো একদিন তোমাদের পরিবারকে ধ্বংস করতে চাইবে।”\n\nআরিয়ান চোখের পানি মুছে বাবার হাত ধরল। দশ বছরের অপেক্ষার অবসান হলো।\n\nকয়েক মাস পর লাল বাড়িটি আর পরিত্যক্ত রইল না। সেটিকে মাহবুব গ্রামের মানুষের জন্য একটি পাঠাগার বানিয়ে দিলেন।\n\nতবে বাড়ির পুরোনো ঘড়িটি আর কখনো মেরামত করা হয়নি। সেটি এখনো থেমে আছে রাত ১২টা ১৭ মিনিটে—যে সময়ে শুরু হয়েছিল এক ভয়ংকর রহস্যের ইতিহাস।\n\nসমাপ্ত।','\n',char(10)),7,'published',0,'2026-10-28 04:53:37','2026-10-28 04:53:37',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('b550e63d-6819-4586-b8d0-ce815b95e674','767cb584-4f32-47e3-b976-2e77450aa511','পর্ব ১: প্রথম দেখাতেই তুমি',replace('১. অচেনা সেই মেয়েটি\n\nসকাল ৮টা ৩০ মিনিট।\n\nঢাকা শহরের রাস্তায় তখন প্রচণ্ড ব্যস্ততা। কেউ অফিসে যাচ্ছে, কেউ স্কুল-কলেজে, আবার কেউ ছুটছে নিজের স্বপ্নের পেছনে।\n\nরাস্তায় বাসের জন্য দাঁড়িয়ে ছিল ২১ বছর বয়সী আরিয়ান। ছেলেটি দেখতে বেশ সুদর্শন। চোখে একরাশ স্বপ্ন, মুখে সবসময় একটা মিষ্টি হাসি। তবে তার জীবনে একটা অভাব ছিল—এমন একজন মানুষের অভাব, যার কাছে সে নিজের সমস্ত দুঃখ-কষ্ট নির্দ্বিধায় বলতে পারবে।\n\nআরিয়ান ফোন বের করে সময় দেখল।\n\n— ধুর! আজও মনে হয় ক্লাসে দেরি হয়ে যাবে।\n\nঠিক তখনই পেছন থেকে একটা মেয়ের কণ্ঠ ভেসে এল।\n\n— এই যে ভাইয়া, একটু শুনবেন?\n\nআরিয়ান পেছনে ফিরে তাকাল।\n\nএকটা মেয়ে দাঁড়িয়ে আছে। পরনে নীল রঙের সালোয়ার-কামিজ, কাঁধে একটা ব্যাগ, আর মুখে বিরক্তির ছাপ।\n\nমেয়েটি বলল,\n— এই বাসটা কি ভার্সিটির দিকে যাবে?\n\nআরিয়ান কয়েক সেকেন্ড চুপ করে থেকে বলল,\n— জি, যাবে। আপনিও কি ভার্সিটিতে পড়েন?\n\n— না, আমি তো বাসের হেল্পার! তাই বাসের রাস্তা জিজ্ঞেস করছি!\n\nকথাটা বলেই মেয়েটি চোখ বড় বড় করে তাকাল।\n\nআরিয়ান কিছুক্ষণ অবাক হয়ে থেকে হেসে ফেলল।\n\n— আচ্ছা, বুঝেছি। আপনি রাগী মানুষ!\n\n— আর আপনি একটু বেশি কথা বলেন!\n\nকথাটা বলে মেয়েটি অন্যদিকে তাকাল।\n\nআরিয়ান মনে মনে বলল,\n''বাহ! সকাল সকাল বেশ মজার একটা মানুষের সঙ্গে দেখা হলো!''\n\nকিন্তু তখনো সে জানত না, এই অচেনা মেয়েটিই একদিন তার পুরো পৃথিবী হয়ে উঠবে।\n\n২. আবার দেখা\n\nভার্সিটিতে পৌঁছে আরিয়ান বন্ধু রাফির সঙ্গে দেখা করল।\n\nরাফি বলল,\n— দোস্ত, আজ এত হাসিখুশি কেন? সকালে কি লটারি পেয়েছিস?\n\nআরিয়ান হেসে বলল,\n— আরে না, রাস্তায় একটা মেয়ের সঙ্গে দেখা হয়েছে।\n\n— ওহ! বুঝেছি! প্রেম হয়ে গেছে!\n\n— ধুর! একটা কথাও ঠিকমতো বলতে পারিস না!\n\n— আচ্ছা, নাম কী মেয়েটার?\n\nআরিয়ান থমকে গেল।\n\nসত্যিই তো! মেয়েটির নাম জিজ্ঞেস করাই হয়নি।\n\nরাফি হেসে বলল,\n— বাহ! নাম জানিস না, ঠিকানা জানিস না, কিন্তু মুখে প্রেমের হাসি!\n\nআরিয়ান বন্ধুকে ধাক্কা দিয়ে ক্লাসে চলে গেল।\n\nক্লাসে ঢুকে নিজের জায়গায় বসতেই পেছন থেকে একটা পরিচিত কণ্ঠ শোনা গেল।\n\n— এই যে, আপনি এখানে?\n\nআরিয়ান ঘুরে তাকাল।\n\nসেই মেয়েটি!\n\nমেয়েটি অবাক হয়ে বলল,\n— আপনি এই ভার্সিটিতেই পড়েন?\n\nআরিয়ান মুচকি হেসে উত্তর দিল,\n— জি। আর আপনি?\n\n— আমিও। আমার নাম নীলা।\n\nআরিয়ান কিছুক্ষণ নীলার দিকে তাকিয়ে থেকে বলল,\n— আমি আরিয়ান।\n\nনীলা নিজের আসনে বসতে বসতে বলল,\n— আপনার সঙ্গে আবার দেখা হবে, ভাবিনি।\n\nআরিয়ান হেসে উত্তর দিল,\n— আমিও ভাবিনি। তবে দেখা হয়ে ভালোই হয়েছে।\n\nনীলা কথাটার উত্তর দিল না। শুধু জানালার বাইরে তাকিয়ে মৃদু হাসল।\n\nআরিয়ান সেই হাসির দিকে তাকিয়ে রইল।\n\nকেন জানি তার মনে হচ্ছিল, আজকের দিনটা অন্য দিনের মতো নয়।\n\n৩. বন্ধুত্বের শুরু\n\nদিন যেতে লাগল।\n\nকখনো লাইব্রেরিতে, কখনো ক্যাম্পাসের মাঠে, আবার কখনো ক্যান্টিনে আরিয়ান আর নীলার দেখা হতো।\n\nধীরে ধীরে তাদের মধ্যে বন্ধুত্ব গড়ে উঠল।\n\nনীলা খুব সাধারণ একটা মেয়ে। অল্পতেই খুশি হয়, আবার ছোটখাটো বিষয়েও অভিমান করে বসে।\n\nঅন্যদিকে আরিয়ান সবসময় নীলাকে হাসানোর চেষ্টা করত।\n\nএকদিন বিকেলে ক্যাম্পাসের বেঞ্চে বসে নীলা বলল,\n— আচ্ছা, আরিয়ান, তুমি সবাইকে এত হাসাও কেন?\n\nআরিয়ান একটু চুপ করে থেকে বলল,\n— কারণ আমি চাই না, আমার আশেপাশের মানুষগুলো কষ্ট পাক।\n\nনীলা তার দিকে তাকাল।\n\n— কিন্তু তুমি নিজে কষ্ট পেলে কী করো?\n\nআরিয়ান মৃদু হাসল।\n\n— তখন কাউকে বুঝতে দিই না।\n\nনীলার মুখটা হঠাৎ গম্ভীর হয়ে গেল।\n\n— এটা ঠিক না। সবসময় অন্যদের ভালো রাখতে গিয়ে নিজের কষ্ট লুকিয়ে রাখা উচিত না।\n\nআরিয়ান অবাক হয়ে নীলার দিকে তাকাল।\n\nএত সাধারণ একটা কথা, অথচ কথাটা তার হৃদয়ে গিয়ে লাগল।\n\nসে মনে মনে ভাবল,\n''মেয়েটা শুধু সুন্দর নয়, তার মনটাও সুন্দর।''\n\nসেদিন বাড়ি ফেরার সময় আরিয়ান বুঝতে পারল, নীলার সঙ্গে কথা না বললে তার দিনটা যেন অসম্পূর্ণ থেকে যায়।\n\nএটাই কি ভালো লাগা?\n\nনাকি ভালোবাসার শুরু?\n\nসে উত্তরটা জানত না।\n\nকিন্তু তার হৃদয় ধীরে ধীরে নীলার দিকে ঝুঁকে পড়ছিল।\n\n৪. প্রথম অভিমান\n\nএক শুক্রবার সকালে আরিয়ান নীলাকে ফোন করল।\n\n— হ্যালো, মিস রাগী!\n\nওপাশ থেকে নীলার কণ্ঠ শোনা গেল।\n\n— কী হয়েছে?\n\n— আজ বিকেলে একটু দেখা করবে?\n\n— কেন?\n\n— এমনিই। তোমার সঙ্গে কিছু কথা ছিল।\n\nনীলা একটু চুপ করে থেকে বলল,\n— আচ্ছা, বিকেল পাঁচটায় ক্যাম্পাসে এসো।\n\nআরিয়ান খুশি হয়ে বলল,\n— ঠিক আছে। কিন্তু একটা কথা—\n\n— কী?\n\n— আজ রাগ করবে না তো?\n\nনীলা হেসে বলল,\n— সেটা তোমার ব্যবহারের ওপর নির্ভর করছে!\n\nবিকেল পাঁচটা।\n\nআরিয়ান ক্যাম্পাসের সেই পরিচিত বেঞ্চে বসে অপেক্ষা করতে লাগল।\n\nপাঁচটা পনেরো মিনিট।\n\nপাঁচটা ত্রিশ মিনিট।\n\nকিন্তু নীলা এল না।\n\nআরিয়ান কয়েকবার ফোন করল। কোনো উত্তর পেল না।\n\nশেষ পর্যন্ত সন্ধ্যা হয়ে গেল। মন খারাপ করে বাড়ি ফিরে এল সে।\n\nরাতে ফোনের স্ক্রিনে নীলার একটা মেসেজ ভেসে উঠল।\n\n''সরি, আরিয়ান। আজ আসতে পারিনি।''\n\nআরিয়ান লিখল,\n''সমস্যা নেই। তুমি ভালো আছ তো?''\n\nনীলা উত্তর দিল,\n''হ্যাঁ, ভালো আছি।''\n\nআরিয়ান আবার লিখল,\n''তাহলে ফোন ধরোনি কেন?''\n\nকিছুক্ষণ পর নীলা লিখল,\n''সব কথা কি ফোনে বলা যায়?''\n\nআরিয়ান মেসেজটা পড়ে চুপ করে রইল।\n\nমেয়েটার কী হয়েছে, সে বুঝতে পারল না।\n\nতবে তার মনে একটা অজানা ভয় জন্ম নিল।\n\nনীলা কি তার কাছ থেকে দূরে সরে যাচ্ছে?\n\nনাকি এমন কোনো কষ্ট আছে, যার কথা নীলা কাউকে বলতে পারছে না?\n\nসেই রাতে আরিয়ানের ঘুম হলো না।\n\nবারবার শুধু একটা কথাই মনে পড়ছিল—\n\n''সব কথা কি ফোনে বলা যায়?''\n\n৫. যে সত্যটা অজানা\n\nপরের দিন ভার্সিটিতে গিয়ে আরিয়ান নীলাকে খুঁজতে লাগল।\n\nকিন্তু নীলা ক্লাসে এল না।\n\nদুপুরে ক্যান্টিনের সামনে হঠাৎ রাফি তাকে ডাকল।\n\n— দোস্ত, তোর সঙ্গে একটা কথা আছে।\n\n— কী কথা?\n\nরাফি কিছুক্ষণ ইতস্তত করে বলল,\n— নীলার ব্যাপারে একটা কথা শুনেছি।\n\nআরিয়ানের বুকটা ধক করে উঠল।\n\n— কী হয়েছে নীলার?\n\nরাফি নিচু গলায় বলল,\n— জানি না কথাটা কতটা সত্যি। তবে শুনেছি, নীলার পরিবার ওর বিয়ে ঠিক করার কথা ভাবছে।\n\nআরিয়ান যেন নিজের কানকে বিশ্বাস করতে পারল না।\n\n— কী বলছিস তুই?\n\n— আমি শুধু যা শুনেছি, তাই বললাম।\n\nআরিয়ান কিছু বলল না।\n\nতার মনে হাজারটা প্রশ্ন ঘুরপাক খেতে লাগল।\n\nনীলা কি সব জানে?\n\nতাহলে কি সে আরিয়ানকে কিছু বলতে চায়?\n\nআর সবচেয়ে বড় প্রশ্ন—\n\nনীলা কি অন্য কাউকে ভালোবাসে?\n\nসেদিন সন্ধ্যায় আরিয়ান একা ক্যাম্পাসের সেই বেঞ্চে বসে রইল, যেখানে বসে তারা একসঙ্গে কত গল্প করেছিল।\n\nপকেট থেকে ফোন বের করে নীলাকে একটা মেসেজ পাঠাল।\n\n''নীলা, তোমার সঙ্গে জরুরি কথা আছে। কাল দেখা করবে?''\n\nকয়েক মিনিট পর উত্তর এল।\n\n''ঠিক আছে। কাল দেখা হবে।''\n\nআরিয়ান ফোনটা হাতে নিয়ে আকাশের দিকে তাকাল।\n\nসে জানত না, পরের দিন তার জীবনে কী অপেক্ষা করছে।\n\nশুধু জানত, নীলাকে হারানোর কথা ভাবতেই তার বুকের ভেতরটা কেমন শূন্য হয়ে যাচ্ছে।\n\nকিন্তু সে কি কখনো নীলাকে নিজের মনের কথাটা বলতে পারবে?\n\nনাকি তাদের বন্ধুত্বের আড়ালেই চাপা পড়ে যাবে তার প্রথম ভালোবাসা?\n\nচলবে... ❤️\n\nপরবর্তী পর্ব: পর্ব ২ — ভালোবাসা, নাকি বিচ্ছেদ?','\n',char(10)),1,'published',0,'2026-10-28 08:02:14','2026-10-28 08:02:14',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('7c1d27c0-4528-42cd-8560-041a1352ea3d','4ae3989f-dbe0-4018-b9e3-cd2d44b85b0c','পৃষ্ঠা ৩',replace('শিরোনাম: তুমি যদি জানতে!\n\n\nআমার এই ক্লান্ত জীবনে, তোমায় রেখেছি গোপনে। তুমি যদি জানতে, তোমায় কতটা ভালোবেসেছি!\n\nআমার সকল স্বপ্নগুলো, তোমায় নিয়েই দেখা হলো। তুমি যদি দেখতে, তোমায় কতটা ভালোবেসেছি!\n\nআমার গাওয়া প্রতিটি গানের সুরে, তোমারই কথা লেখা থাকে। তুমি যদি বুঝতে, তোমায় কতটা চেয়েছি!\n\nতোমার মুখের হাসিটুকু দেখে, আমার মনে প্রশান্তির স্রোত বয়ে যায়। তুমি যদি জানতে, তোমার হাসিতেই আমার পৃথিবীটা সুন্দর হয়ে যায়!\n\nতোমায় নিয়ে দেখা স্বপ্নগুলো, কী কখনো সত্যি হবে? নাকি আমার কল্পনাতেই, আমাদের গল্পটা অসমাপ্ত রয়ে যাবে?\n\nতোমার কাছে হয়তো আমি, সাধারণ একজন মানুষ। কিন্তু আমার কাছে তুমি, হাজারো অনুভূতির মাঝে সবচেয়ে প্রিয় এক অনুভূতি।\n\nকত রাত কেটে যায় তোমার কথা ভেবে, কত কথা জমে থাকে তোমায় বলব বলে। অথচ তোমার সামনে গেলে, সব কথাই হারিয়ে যায় নীরবতার আড়ালে।\n\nতুমি যদি একবার আমার চোখে দেখতে, তাহলে হয়তো বুঝতে পারতে— এই চোখে তোমাকে নিয়ে কত স্বপ্ন, আর হৃদয়ে তোমার জন্য কতটা ভালোবাসা জমে আছে!\n\nতুমি যদি জানতে, তোমায় কতটা ভালোবেসেছি! হয়তো আমার না-বলা কথাগুলো বুঝতে, হয়তো আমার নীরবতার ভাষা পড়তে।\n\nকিন্তু তুমি তো জানো না, আমার প্রতিটি অসমাপ্ত কবিতার পেছনে তুমি আছো, আমার প্রতিটি দীর্ঘশ্বাসের আড়ালে তুমি আছো, আর আমার প্রতিটি স্বপ্নের শেষ পাতায় আজও শুধু তোমারই নাম লেখা আছে! 🥀❤️‍🩹','\n',char(10)),2,'published',0,'2026-10-28 08:17:26','2026-10-28 08:17:26',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('01f63e65-53b5-4794-be4a-762725a2664b','c4867502-b7f2-4c77-b704-eba7e96e8b8d','পর্ব - ১',replace('~ তোমার অন্ধকারে আমার বসন্ত ~\n\nWriter : Noor Islam.\n\nপর্ব ১: অচেনা অন্ধকার\n\nকিছু মানুষের আগমন জীবনে বসন্ত নিয়ে আসে। আর কিছু মানুষের চোখে জমে থাকে এমন অন্ধকার, যেখানে আলো পৌঁছাতেও দুবার ভাবতে হয়।\n\nআরিশা রহমান জানত না, প্রথম দেখায় যে মানুষটিকে তার অসহ্য মনে হবে, একদিন সেই মানুষটিই তার জীবনের সবচেয়ে বড় রহস্য হয়ে উঠবে।\n\nআর সেই রহস্যের শুরুটা হয়েছিল এক বৃষ্টিভেজা সন্ধ্যায়।\n\n১. মির্জা গ্রুপের উত্তরাধিকারী\n\nঢাকার সবচেয়ে অভিজাত এলাকার মাঝখানে দাঁড়িয়ে থাকা বিশাল কাচঘেরা ভবনটির নাম—মির্জা টাওয়ার।\n\nশহরের বড় বড় ব্যবসায়ীদের কাছে এই নামের অর্থ ক্ষমতা। আর সাধারণ মানুষের কাছে এর অর্থ—আদ্রিয়ান মির্জা।\n\nমাত্র তেইশ বছর বয়সেই দেশের অন্যতম প্রভাবশালী ব্যবসায়ী হয়ে উঠেছে সে। তার সৌন্দর্য নিয়ে মানুষের কৌতূহলের শেষ নেই। নিখুঁত চেহারা, গম্ভীর চোখ, দামি কালো স্যুট আর ঠোঁটের কোণে লেগে থাকা চিরস্থায়ী শীতলতা—সব মিলিয়ে তাকে দেখলে দ্বিতীয়বার তাকাতে বাধ্য হয় মানুষ।\n\nবিশেষ করে মেয়েরা।\n\nকেউ তার সঙ্গে একবার কথা বলার সুযোগ খোঁজে, কেউ দূর থেকে ছবি তোলে, আবার কেউ সরাসরি নিজের ভালো লাগার কথা জানিয়ে দেয়।\n\nকিন্তু আদ্রিয়ান মির্জার কাছে এসবের কোনো মূল্য নেই।\n\nতার ব্যক্তিগত সহকারী রায়ান ফাইল হাতে দাঁড়িয়ে বলল,\n\n— স্যার, আজকের পার্টিতে কয়েকজন গুরুত্বপূর্ণ অতিথি আসবেন। মিসেস সায়রা কবিরও আসছেন। উনি আপনার সঙ্গে আলাদা করে কথা বলতে চেয়েছেন।\n\nল্যাপটপ থেকে চোখ না তুলেই আদ্রিয়ান বলল,\n\n— ব্যবসার কথা হলে সময় দাও। অন্য কিছু হলে প্রয়োজন নেই।\n\n— স্যার, উনি কিন্তু আপনার সঙ্গে কফি খেতে চেয়েছেন।\n\nএবার আদ্রিয়ান ধীরে ধীরে চোখ তুলল।\n\nশীতল দৃষ্টিতে তাকিয়ে বলল,\n\n— রায়ান, আমি কি তোমাকে আমার ব্যক্তিগত জীবনের দায়িত্ব দিয়েছি?\n\n— না, স্যার।\n\n— তাহলে আমার কফির হিসাব রাখার দরকার নেই।\n\nরায়ান চুপ করে গেল।\n\nআদ্রিয়ান আবার কাজে মন দিল। তার কাছে পৃথিবীর সবচেয়ে গুরুত্বপূর্ণ বিষয় ছিল একটি—মির্জা পরিবারের পতনের পেছনে থাকা মানুষটিকে খুঁজে বের করা।\n\nপাঁচ বছর আগে এক রাতেই সবকিছু বদলে গিয়েছিল। তার পরিবার হারিয়েছিল সম্মান, সম্পদ, আর এমন একজন মানুষকে—যাকে আদ্রিয়ান নিজের পৃথিবী বলে জানত।\n\nসেদিনের পর থেকে সে আর আগের মানুষটি ছিল না।\n\nতার কাছে ভালোবাসা ছিল দুর্বলতা। বিশ্বাস ছিল বিপজ্জনক। আর ক্ষমা?\n\nক্ষমা করার মতো উদারতা সে নিজের ভেতরে বহু আগেই মেরে ফেলেছিল।\n\nঅন্তত সে নিজেকে তা-ই বোঝাত।\n\nডেস্কের ডান পাশের ড্রয়ার খুলে সে একটি পুরোনো কালো ফাইল বের করল।\n\nফাইলের প্রথম পাতায় লেখা—\n\nরহমান পরিবার।\n\nনামটির দিকে কয়েক সেকেন্ড তাকিয়ে রইল আদ্রিয়ান। তারপর পাতাটি উল্টাতেই একটি মেয়ের ছবি বেরিয়ে এল।\n\nছবিতে মেয়েটির চোখে অদ্ভুত এক আত্মবিশ্বাস। ঠোঁটে হালকা হাসি। যেন পৃথিবীর কোনো কিছুই তাকে ভয় দেখাতে পারে না।\n\nছবিটির নিচে লেখা—\n\nআরিশা রহমান।\n\nআদ্রিয়ানের আঙুল ছবিটির ওপর স্থির হয়ে গেল।\n\nতার চোখে ফুটে উঠল এমন এক দৃষ্টি, যার অর্থ বোঝার সাধ্য সাধারণ মানুষের নেই।\n\n— অবশেষে তোমাকে খুঁজে পেয়েছি, আরিশা রহমান।\n\nকণ্ঠটা এতটাই নিচু ছিল যে কথাগুলো যেন ঘরের অন্ধকারেই হারিয়ে গেল।\n\nতারপর সে ফাইলটি বন্ধ করে দিল।\n\nকিন্তু ছবির মেয়েটি যে তার জীবনে ঝড় হয়ে আসতে চলেছে, সেটা কি আদ্রিয়ান জানত?\n\nনাকি সে নিজেই সেই ঝড়কে ডেকে আনছিল?\n\n২. বেপরোয়া মেয়েটি\n\n— আরিশাআআ! তুই কি ঘুমের মধ্যে বিশ্ববিদ্যালয়ে যাবি নাকি? ঘড়ির দিকে একবার তাকিয়ে দেখ!\n\nবন্ধু নীলার চিৎকারে আরিশা রহমান আয়নার সামনে দাঁড়িয়ে চুল ঠিক করতে করতে বলল,\n\n— চিৎকার করিস না। আমার কানের পর্দা এখনো বেঁচে আছে।\n\n— তোর জন্য আমার মাথার পর্দা বেঁচে থাকবে কি না, সেটাই চিন্তা!\n\nআরিশা হেসে ব্যাগ কাঁধে তুলে নিল।\n\nবিশ বছর বয়সী মেয়েটিকে দেখে কেউ সহজে বুঝতে পারবে না, তার ভেতরে কতটা জেদ লুকিয়ে আছে। হাসিখুশি, দুষ্টু, কথায় কথায় তর্ক করা আর অন্যায়ের সামনে একচুলও পিছিয়ে না আসা—এই ছিল তার স্বভাব।\n\nকেউ তাকে ভয় দেখালে সে ভয় পাওয়ার বদলে উল্টো প্রশ্ন করে বসে।\n\nআর কেউ তার আত্মসম্মানে আঘাত করলে, সেই মানুষকে সহজে ক্ষমা করার অভ্যাস তার নেই।\n\n— শোন, আজ কিন্তু তুই আমার সঙ্গে লাইব্রেরিতে যাবি, নীলা বলল।\n\n— কেন?\n\n— একটা অ্যাসাইনমেন্ট জমা দিতে হবে।\n\n— নিজের অ্যাসাইনমেন্ট নিজে কর। আমি কি তোর ব্যক্তিগত কর্মচারী?\n\n— আল্লাহ, এই মেয়েকে কে যে সহ্য করবে!\n\nআরিশা ব্যাগের চেইন বন্ধ করে মুচকি হাসল।\n\n— যে আমাকে সহ্য করতে পারবে, সে নিশ্চয়ই অনেক ধৈর্যশীল হবে।\n\n— তোর ভবিষ্যৎ স্বামীকে আমার জন্য আগেই সমবেদনা জানিয়ে রাখিস।\n\nআরিশা হেসে বলল,\n\n— আগে তাকে খুঁজে বের কর। তারপর সমবেদনা জানাস।\n\nদুজনের হাসিতে ঘরটা ভরে উঠল।\n\nসেই মুহূর্তে আরিশার ধারণাও ছিল না, তার নাম লেখা একটি ফাইল ঢাকার অন্য প্রান্তে কোনো এক মানুষের প্রতিশোধের অপেক্ষায় পড়ে আছে।\n\n৩. প্রথম মুখোমুখি\n\nবিকেল গড়িয়ে সন্ধ্যা নামছিল।\n\nবিশ্ববিদ্যালয়ের সামনে এসে আরিশা দেখল, বৃষ্টির কারণে রাস্তায় ভিড় জমেছে। নীলা আগেই চলে গেছে। আরিশা ফোনে রাইড খুঁজছিল, ঠিক তখনই তার সামনে এসে থামল একটি কালো গাড়ি।\n\nগাড়ির কাচ ধীরে ধীরে নেমে গেল।\n\nভেতরে বসে থাকা মানুষটিকে দেখে আরিশা কয়েক মুহূর্তের জন্য থমকে গেল।\n\nকালো শার্ট, হাতঘড়ি, গম্ভীর মুখ আর এমন এক জোড়া চোখ—যেন সেই চোখের সামনে মিথ্যা বলার সাহস কারও নেই।\n\nলোকটি তার দিকে তাকিয়ে বলল,\n\n— গাড়িতে ওঠো।\n\nআরিশা ভ্রু কুঁচকে তাকাল।\n\n— জি? আপনাকে কি আমি চিনি?\n\n— না।\n\n— তাহলে অপরিচিত মানুষকে এভাবে গাড়িতে উঠতে বলেন কীভাবে?\n\nলোকটির চোয়াল শক্ত হয়ে উঠল।\n\n— বৃষ্টি বাড়ছে। তোমাকে বাড়ি পৌঁছে দেব।\n\n— ধন্যবাদ। কিন্তু আমি নিজেই যেতে পারব।\n\nকথাটা বলেই আরিশা অন্যদিকে হাঁটতে শুরু করল।\n\nসাধারণত তার একটি কথাতেই মানুষ থেমে যায়। অথচ এই মেয়েটি তাকে দ্বিতীয়বার তাকানোরও প্রয়োজন মনে করল না!\n\nআদ্রিয়ানের চোখ সরু হয়ে এল।\n\n— আরিশা রহমান!\n\nনিজের নাম শুনে আরিশা থেমে গেল।\n\nধীরে ধীরে পেছনে ফিরে তাকাল।\n\n— আমার নাম জানেন কীভাবে?\n\nআদ্রিয়ান গাড়ির দরজা খুলে বাইরে নামল। তার উপস্থিতিতে আশপাশের কয়েকজনের কথাবার্তাও যেন থেমে গেল।\n\nসে আরিশার সামনে এসে দাঁড়াল।\n\n— তোমার সম্পর্কে জানার মতো অনেক কিছুই আমি জানি।\n\nআরিশা এবার বিরক্ত হলো।\n\n— দেখুন, আপনি কে আমি জানি না। কিন্তু আমার ব্যক্তিগত জীবন নিয়ে এত আগ্রহ দেখানোর প্রয়োজন নেই।\n\n— তোমার ব্যক্তিগত জীবন?\n\nআদ্রিয়ানের ঠোঁটে ক্ষীণ, অর্থহীন হাসি ফুটল।\n\n— তুমি জানোই না, তোমার জীবন কতটা অন্যের সিদ্ধান্তের সঙ্গে জড়িয়ে আছে।\n\n— ধাঁধা না বলে পরিষ্কার করে কথা বলুন।\n\n— সব কথা সবার জানার প্রয়োজন হয় না।\n\nআরিশা এবার এক পা এগিয়ে গেল।\n\n— আর সবাইকে ভয় দেখানোর অধিকারও আপনার নেই!\n\nকথাটা শুনে আদ্রিয়ান কিছুক্ষণ চুপ করে রইল।\n\nতার জীবনে অনেক মানুষ এসেছে। কেউ তার ক্ষমতা দেখে মাথা নত করেছে, কেউ তার অর্থের জন্য কাছে এসেছে, কেউ তার সৌন্দর্যে মুগ্ধ হয়ে নিজের আত্মসম্মানটুকুও ভুলে গেছে।\n\nকিন্তু এই মেয়েটি?\n\nসে ভয় পাচ্ছে না।\n\nবরং চোখে চোখ রেখে তর্ক করছে!\n\nআদ্রিয়ান নিচু স্বরে বলল,\n\n— নিজের সাহসটা একটু কমাও, আরিশা। সব মানুষের সঙ্গে তর্ক করা যায় না।\n\nআরিশা ঠোঁট বাঁকিয়ে উত্তর দিল,\n\n— আর সব মানুষকে নিজের ইচ্ছামতো চালানোও যায় না, মিস্টার!\n\nকথাটা বলে সে চলে গেল।\n\nআদ্রিয়ান স্থির হয়ে দাঁড়িয়ে রইল।\n\nতার চোখ অনুসরণ করল মেয়েটিকে, যতক্ষণ না সে ভিড়ের মধ্যে হারিয়ে গেল।\n\nরায়ান গাড়ি থেকে নেমে এসে বলল,\n\n— স্যার, মেয়েটা আপনার সঙ্গে এভাবে কথা বলল!\n\nআদ্রিয়ান কোনো উত্তর দিল না।\n\nতার চোখে তখন অদ্ভুত এক অনুভূতি—রাগ, বিস্ময়, নাকি এমন কিছু, যার নাম সে নিজেও জানে না।\n\nকয়েক সেকেন্ড পর সে বলল,\n\n— ওর ওপর নজর রাখবে। তবে এমন কিছু করবে না, যাতে ওর কোনো ক্ষতি হয়।\n\nরায়ান অবাক হয়ে তাকাল।\n\n— জি, স্যার?\n\nআদ্রিয়ান এবার তার দিকে তাকাল।\n\n— কথা কি দুবার বলতে হবে?\n\n— না, স্যার।\n\nরায়ান দ্রুত সরে গেল।\n\nআদ্রিয়ান আবার গাড়িতে উঠে বসল। জানালার বাইরে তাকিয়ে তার মনে পড়ল সেই পুরোনো রাতের কথা, যেদিন তার বাবার জীবনের সবকিছু ভেঙে পড়েছিল।\n\nআর সেই রাতের সঙ্গে জড়িয়ে ছিল একটি নাম।\n\nরহমান।\n\n৪. পুরোনো ফাইলের নতুন রহস্য\n\nরাত সাড়ে দশটা।\n\nমির্জা ম্যানশনের দোতলার ঘরটিতে কোনো আলো জ্বলছিল না। শুধু জানালার পাশের টেবিল ল্যাম্পের ক্ষীণ আলোয় ঘরের একাংশ দৃশ্যমান।\n\nআদ্রিয়ান একা বসে ছিল।\n\nসামনে সেই কালো ফাইল। পাশে একটি পুরোনো ছবি, যার প্রান্তগুলো সময়ের সঙ্গে বিবর্ণ হয়ে গেছে।\n\nছবিতে দুজন মানুষ দাঁড়িয়ে আছে—একজন আদ্রিয়ানের বাবা, আর অন্যজন আরিশার বাবা, মাহমুদ রহমান।\n\nদুজনের মুখেই হাসি।\n\nঅথচ আজ তাদের পরিবারের মধ্যে এমন এক অদৃশ্য দেয়াল দাঁড়িয়ে গেছে, যার ওপাশে রয়েছে অপমান, ক্ষতি আর বহু বছরের জমে থাকা প্রশ্ন।\n\nআদ্রিয়ান ছবিটা হাতে তুলে নিল।\n\n— আপনি যদি সত্যিই নির্দোষ হয়ে থাকেন, বাবা, তাহলে সেদিন আমাদের সঙ্গে এমনটা হলো কেন?\n\nকোনো উত্তর এল না।\n\nশুধু জানালার কাচে বৃষ্টির শব্দ।\n\nঠিক তখনই তার ফোন বেজে উঠল।\n\nঅপরিচিত নম্বর।\n\nআদ্রিয়ান কল রিসিভ করতেই ওপাশ থেকে চাপা, অপরিচিত একটি কণ্ঠ ভেসে এল।\n\n— মির্জা পরিবারের পুরোনো হিসাব ঘাঁটাঘাঁটি করা বন্ধ করো।\n\nআদ্রিয়ানের চোখ মুহূর্তে কঠিন হয়ে উঠল।\n\n— কে বলছেন?\n\n— যাদের খুঁজছ, তারা তোমার ধারণার চেয়েও কাছে আছে।\n\n— নাম বলো।\n\nওপাশের মানুষটি কয়েক সেকেন্ড নীরব থেকে বলল,\n\n— রহমান পরিবারের মেয়েটার কাছ থেকে দূরে থাকো। মেয়েটা কিছুই জানে না। কিন্তু ওর নামের সঙ্গে যে সত্যিটা জড়িয়ে আছে, সেটা জানলে তুমিও আর আগের মানুষ থাকবে না।\n\nকলটি কেটে গেল।\n\nআদ্রিয়ান কিছুক্ষণ ফোনের দিকে তাকিয়ে রইল।\n\nতারপর ধীরে ধীরে কালো ফাইলটি খুলল।\n\nআরিশার ছবির পেছনে একটি কাগজ রাখা ছিল, যা সে আগে খেয়াল করেনি।\n\nকাগজটিতে কয়েকটি লাইন লেখা—\n\n“যদি কখনো মির্জা পরিবারের সত্য প্রকাশ করতে চাও, তাহলে আরিশা রহমানকে বিশ্বাস কোরো না। কারণ এই মেয়েটিই তোমার সব প্রশ্নের উত্তর—আবার তোমার ধ্বংসের কারণও হতে পারে।”\n\nআদ্রিয়ানের চোখ স্থির হয়ে গেল।\n\nবাইরে তখন বৃষ্টি আরও জোরে নামছে।\n\nসে কাগজটি মুঠোয় চেপে ধরল।\n\nতারপর ঠান্ডা কণ্ঠে বলল,\n\n— দেখা যাক, আরিশা রহমান। তুমি আমার শত্রুর মেয়ে, নাকি এমন এক সত্যের চাবি, যা থেকে সবাই আমাকে দূরে রাখতে চায়?\n\nসেই রাতেই আদ্রিয়ান একটি সিদ্ধান্ত নিল।\n\nআরিশা রহমানের জীবনে তাকে প্রবেশ করতেই হবে।\n\nপ্রতিশোধ নেওয়ার জন্য।\n\nসত্য জানার জন্য।\n\nকিন্তু সে জানত না, যে মেয়েটিকে সে নিজের শত্রু বলে মনে করছে, একদিন সেই মেয়েটির কাছেই তার সবচেয়ে গোপন দুর্বলতা হয়ে উঠবে তার নিজের হৃদয়।\n\nআরিশাও জানত না, অচেনা সেই মানুষটির সঙ্গে তার দেখা হওয়া নিছক কাকতালীয় ছিল না।\n\nকারণ তাদের গল্প শুরু হয়েছিল আজ থেকে নয়।\n\nশুরু হয়েছিল পাঁচ বছর আগে—একটি রাতের অন্ধকারে।\n\nআর সেই রাতের সত্য এখনো মাটির নিচে চাপা পড়ে আছে।\n\nচলবে... 🥀🖤','\n',char(10)),1,'published',0,'2026-10-28 10:12:58','2026-10-28 10:12:58',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('76232b0d-3245-492d-8a56-8bd7fd2aad2c','4f94b40b-3163-4e82-be86-71aae1de626d','পব ১',replace('তোমাতেই আমার পূর্ণতা ❤️\n\nপ্রথম পর্ব: অচেনা মায়া\n\n“কিছু মানুষ জীবনে আসে হঠাৎ করে, অথচ একসময় তারাই হয়ে ওঠে জীবনের সবচেয়ে প্রিয় মানুষ।” 🌸\n\nসেদিন আকাশটা ছিল মেঘলা। হালকা বাতাসে গাছের পাতাগুলো দুলছিল। কলেজের বারান্দায় দাঁড়িয়ে বৃষ্টির দিকে তাকিয়ে ছিল মেয়েটি।\n\nমেয়েটির নাম মায়া।\n\nশান্ত স্বভাবের মেয়ে মায়া। খুব বেশি কথা বলে না, কিন্তু তার হাসির মধ্যে লুকিয়ে থাকে একরাশ মায়া। সে বিশ্বাস করে, ভালোবাসা মানে শুধু কাউকে কাছে পাওয়া নয়, বরং তার মুখের হাসির কারণ হয়ে ওঠা।\n\nসেদিনই প্রথম দেখা হয় আরশের সঙ্গে।\n\nমায়া তাড়াহুড়ো করে ক্লাসে ঢুকতে গিয়ে কারও সঙ্গে ধাক্কা খেল। হাতে থাকা বইগুলো মেঝেতে ছড়িয়ে পড়ল।\n\n— চোখে দেখো না? — একটু বিরক্ত হয়ে বলল মায়া।\n\nছেলেটি নিচু হয়ে বইগুলো তুলতে তুলতে মুচকি হেসে বলল,\n\n— সরি! তবে একটা কথা বলি?\n\n— কী?\n\n— রাগ করলে তোমাকে বেশ ভয়ংকর লাগে!\n\nমায়া চোখ বড় বড় করে তাকাল।\n\n— আপনি কি সব সময় এমন বিরক্তিকর কথা বলেন?\n\n— না, শুধু যাদের সঙ্গে প্রথম দেখা হয়, তাদের সঙ্গেই!\n\nকথাটা বলে ছেলেটি হেসে চলে গেল।\n\nমায়া বিড়বিড় করে বলল,\n\n— অদ্ভুত একটা ছেলে!\n\nকিন্তু কেন জানি, ছেলেটির হাসিটা তার মনে থেকে গেল।\n\nপরের দিন ক্লাসে গিয়ে মায়া অবাক হয়ে দেখল, ছেলেটি তার পাশের বেঞ্চে বসে আছে।\n\nছেলেটি তাকিয়ে বলল,\n\n— সুপ্রভাত, রাগী মেয়ে!\n\n— আমার নাম মায়া।\n\n— জানি।\n\n— কীভাবে জানেন?\n\n— কাল তোমার বইয়ের ওপর নাম লেখা দেখেছিলাম। আর আমার নাম আরশ।\n\nমায়া মুখ ঘুরিয়ে নিল। কিন্তু ঠোঁটের কোণে ছোট্ট একটা হাসি ফুটে উঠল।\n\nদিন যেতে লাগল। কখনো আরশ মায়ার জন্য লাইব্রেরি থেকে বই নিয়ে আসত, কখনো মায়া আরশের অসমাপ্ত নোটগুলো গুছিয়ে দিত। ছোট ছোট খুনসুটি থেকে তৈরি হতে লাগল এক অদ্ভুত বন্ধুত্ব।\n\nএকদিন বৃষ্টি হচ্ছিল খুব।\n\nকলেজ ছুটির পর মায়া গেটের সামনে দাঁড়িয়ে ছিল। তার কাছে ছাতা ছিল না।\n\nহঠাৎ মাথার ওপর একটা ছাতা এসে থামল।\n\nপাশে দাঁড়িয়ে আরশ বলল,\n\n— চলবে?\n\nমায়া অবাক হয়ে তাকাল।\n\n— আপনি যাবেন কোন দিকে?\n\n— যেদিকে আমার বন্ধুটি যাবে।\n\nমায়া মুচকি হেসে বলল,\n\n— আমি তো আপনার বন্ধু কবে হলাম?\n\nআরশ একটু থেমে তার দিকে তাকাল।\n\n— জানি না। তবে তোমাকে বন্ধু ভাবতে আমার ভালো লাগে।\n\nকথাটা শুনে মায়ার বুকের ভেতর কেমন যেন করে উঠল।\n\nসে আর কিছু বলল না। শুধু ছাতার নিচে আরশের পাশে হাঁটতে লাগল।\n\nবৃষ্টির শব্দের মাঝখানে দুজনের নীরবতাও যেন কথা বলছিল।\n\nকিন্তু মায়া তখনও জানত না, এই ছেলেটিই একদিন তার সবচেয়ে বড় আনন্দ হবে, আবার সবচেয়ে গভীর কষ্টের কারণও হবে।\n\nআরশও জানত না, এই শান্ত মেয়েটির অভিমান একদিন তার পুরো পৃথিবী বদলে দেবে।\n\nচলবে... ❤️\n\nপরের পর্বে: বন্ধুত্বের আড়ালে জন্ম নেবে এক নতুন অনুভূতি। কিন্তু সেই অনুভূতি কি দুজনের কেউ স্বীকার করতে পারবে? 🌷','\n',char(10)),1,'published',0,'2026-10-28 10:38:58','2026-10-28 10:38:58',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('3b0c34c5-243c-404d-8701-ff9a694f70db','aa546f2b-ffcb-4db9-941f-4d47a14da9b2','তুমি আমার শেষ ঠিকানা লেখিকা তাবাস্সুম',replace('💕 পর্ব ১: তাবাস্সুমের পরিবার\nতাবাস্সুম বাবা-মায়ের একমাত্র মেয়ে। তার বাবা আব্দুল করিম, মা নাসরিন বেগম আর বড় ভাই তামিম। তামিম বোনকে খুব ভালোবাসে, তবে সব সময় বোনের সঙ্গে মজা করে।\nসকালে তাবাস্সুম রান্নাঘরে মাকে সাহায্য করছিল।\nমা বললেন, “তাবাস্সুম, তোর বাবা বলছিলেন, তোর জন্য একটা ভালো সম্বন্ধ এসেছে।”\nতাবাস্সুমের হাত থেমে গেল।\n“কার সম্বন্ধ, মা?”\nমা হেসে বললেন, “তোরই তো! আর কার?”\nতাবাস্সুম লজ্জা পেয়ে বলল, “মা, আবার শুরু করলে!”\nপাশ থেকে তামিম বলে উঠল, “আমার বোনের বিয়ে হবে, আর আমি বরকে আগে জেরা করব!”\nতাবাস্সুম একটা বালিশ তুলে ভাইয়ের দিকে ছুড়ে মারল।“ভাইয়া! তোমাকে কে বলেছে আমার বিয়ে হচ্ছে?”\nতামিম হেসে বলল, “বিয়ের কথা শুনেই তো তোর মুখ লাল হয়ে গেছে!”\nসবাই হেসে উঠল। কিন্তু তাবাস্সুমের মনে তখন একটাই প্রশ্ন—যদি সেই ছেলেটা তিহান হয়?\nকারণ তিহানের কথা সে কাউকে কখনো বলেনি।\n💙 পর্ব ২: তিহানের পরিবার\nতিহানদের পরিবারও বেশ বড়।\nতার বাবা মাহমুদ সাহেব, মা শায়লা বেগম, বড় বোন তানিয়া আর ছোট ভাই তূর্য।\nতিহান পরিবারের বড় ছেলে। বাবা চান, ছেলে নিজের ব্যবসার দায়িত্ব নিক। মা চান, ছেলের বিয়ে দিয়ে সংসারী করতে।\nএকদিন রাতের খাবারের টেবিলে শায়লা বেগম বললেন, “তিহান, একটা কথা বলব?”, “তিহান, একটা কথা বলব?”\nতিহান খাবার খেতে খেতে বলল, “বলো, মা।”\n“তোর বিয়ের কথা ভাবছি।”\nতূর্য সঙ্গে সঙ্গে বলে উঠল, “বাহ! ভাইয়ার বিয়ে! ভাবি এলে আমি আর ভাইয়াকে বিরক্ত করব না!”\nতানিয়া হেসে বলল, “তুই আবার ভাইকে বিরক্ত করিস না? সারাদিন তো ভাইয়ের পেছনেই ঘুরিস!”\nতিহান বিরক্তির ভান করে বলল, “তোমরা খাওয়া শেষ করবে, নাকি আমার বিয়ে এখানেই দিয়ে দেবে?”\nমাহমুদ সাহেব গম্ভীরভাবে বললেন, “আমরা চাই, তুই নিজের পছন্দ থাকলে আমাদের জানাস।”\nতিহান চুপ হয়ে গেল।\nতার চোখের সামনে ভেসে উঠল একটি মুখ।','\n',char(10)),1,'published',0,'2026-10-28 10:39:02','2026-10-28 10:39:02',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('1ae83c91-bb39-4bb2-84a4-1eca1ab4b31d','c4867502-b7f2-4c77-b704-eba7e96e8b8d','পর্ব - ২',replace('~ তোমার অন্ধকারে আমার বসন্ত ~\n\nWriter : Noor Islam.\n\nপর্ব ২: যে রহস্যের শুরু তোমাকে দিয়ে\n\nকিছু মানুষকে প্রথমবার দেখেই অচেনা মনে হয়। অথচ তাদের সঙ্গে আমাদের পরিচয় হয়তো বহু বছর আগেই হয়ে গেছে—কোনো এক অন্ধকার অধ্যায়ে, যার কথা আমাদের মনে নেই।\n\nআরিশা রহমান জানত না, তার জীবনের সবচেয়ে বড় ঝড়টা ইতিমধ্যেই তার দিকে এগিয়ে আসছে।\n\nআর সেই ঝড়ের নাম—আদ্রিয়ান মির্জা।\n\n১. মির্জা ভিলার অন্ধকার ঘর\n\nরাত তখন প্রায় এগারোটা।\n\nশহরের ব্যস্ততা ধীরে ধীরে কমে এসেছে। অথচ মির্জা ভিলার তৃতীয় তলার একটি ঘরে তখনও আলো জ্বলছে।\n\nঘরটির চারপাশে কালো কাঠের আসবাব, দেয়ালজুড়ে বইয়ের তাক আর বিশাল জানালার ওপাশে বৃষ্টিভেজা শহর। ঘরের মাঝখানে বসে থাকা মানুষটির মুখে কোনো অনুভূতি নেই।\n\nআদ্রিয়ান মির্জা।\n\nকালো শার্টের হাতা কনুই পর্যন্ত গোটানো। এক হাতে কফির কাপ, অন্য হাতে একটি পুরোনো ফাইল।\n\nফাইলটির ওপরে লাল কালিতে লেখা—\n\nARISHA RAHMAN.\n\nনামটির দিকে তাকিয়ে আদ্রিয়ানের চোখের দৃষ্টি বদলে গেল।\n\nপৃথিবীর কাছে সে একজন নির্দয় ব্যবসায়ী। যার একটি সিদ্ধান্তে শত কোটি টাকার চুক্তি হয়, আবার একটি কথায় বহু মানুষের ক্যারিয়ার শেষ হয়ে যেতে পারে।\n\nকিন্তু এই মেয়েটির নাম সামনে এলেই তার বহু বছরের সাজানো হিসাব এলোমেলো হয়ে যায়।\n\nআদ্রিয়ান ফাইলটি খুলল।\n\nভেতরে আরিশার বিশ্ববিদ্যালয়ের পরিচয়পত্রের একটি কপি, তার পরিবারের কিছু তথ্য এবং একটি পুরোনো ছবি।\n\nছবিটিতে দুজন পুরুষ পাশাপাশি দাঁড়িয়ে আছে।\n\nএকজন আদ্রিয়ানের বাবা, আর অন্যজন আরিশার বাবা।\n\nদুজনের মুখেই হাসি।\n\nকিন্তু ছবিটির পেছনে কালো কালিতে লেখা একটি বাক্য আদ্রিয়ানের চোখ আটকে দিল।\n\n“যে সত্য প্রকাশ পাবে, সে সত্যই দুই পরিবারকে ধ্বংস করবে।”\n\nআদ্রিয়ানের চোয়াল শক্ত হয়ে উঠল।\n\n— এত বছর পরেও তুমি আমাকে তাড়া করে বেড়াচ্ছ, বাবা?\n\nতার কণ্ঠে জমে থাকা ক্ষোভ যেন ঘরের বাতাসকেও ভারী করে তুলল।\n\nঠিক তখনই দরজায় টোকা পড়ল।\n\n— স্যার, ভেতরে আসতে পারি?\n\nআদ্রিয়ানের বিশ্বস্ত সহকারী রায়ান।\n\n— এসো।\n\nরায়ান ঘরে ঢুকে টেবিলের ওপর রাখা ছবিটির দিকে তাকাল। তারপর সতর্ক কণ্ঠে বলল,\n\n— স্যার, মেয়েটার ব্যাপারে আরেকটা তথ্য পেয়েছি।\n\nআদ্রিয়ান চোখ তুলল।\n\n— বলো।\n\n— আরিশা রহমানের বাবা আগামী সপ্তাহে ঢাকায় ফিরছেন। আর সবচেয়ে অদ্ভুত ব্যাপার হলো, গত কয়েক দিন ধরে কেউ একজন তাদের পরিবারের পুরোনো বাড়ির খোঁজ করছে।\n\nআদ্রিয়ান ধীরে ধীরে চেয়ার ছেড়ে উঠে দাঁড়াল।\n\n— কে?\n\n— এখনও নিশ্চিত হওয়া যায়নি।\n\nকয়েক মুহূর্ত নীরব থেকে আদ্রিয়ান বলল,\n\n— খুঁজে বের করো। আমার আগে কেউ যেন ওই সত্যের কাছে পৌঁছাতে না পারে।\n\nরায়ান চলে যাওয়ার আগে থেমে গেল।\n\n— স্যার, একটা কথা বলব?\n\n— বলো।\n\n— আপনি কি নিশ্চিত, আরিশা ম্যাডামকে এই ব্যাপারে জড়ানো ঠিক হবে?\n\nআদ্রিয়ানের চোখে এবার এমন এক শীতলতা ফুটে উঠল, যা দেখে রায়ানও চুপ হয়ে গেল।\n\n— ওকে আমি এই গল্পে জড়াইনি, রায়ান। ওর পরিবার অনেক আগেই ওকে এর মধ্যে নিয়ে এসেছে।\n\nএকটু থেমে সে আবার বলল,\n\n— আর ওর কোনো ক্ষতি হলে, তার জবাব আমি নিজে দেব।\n\n২. যে মেয়েটি ভয় পেতে জানে না\n\nপরদিন সকাল।\n\nবিশ্ববিদ্যালয়ের ক্যাম্পাসে রীতিমতো হইচই পড়ে গেছে।\n\nকারণ একটাই—গতকাল যে রহস্যময় পুরুষটিকে ক্যাম্পাসের সামনে দেখা গিয়েছিল, আজ তার কালো গাড়িটা আবারও সেখানে দাঁড়িয়ে আছে।\n\nআরিশা বান্ধবী মেহরার সঙ্গে গেট দিয়ে ঢুকছিল। হাতে কয়েকটা বই, কাঁধে ব্যাগ। কথা বলতে বলতে হঠাৎ তার চোখ পড়ল গাড়িটার দিকে।\n\nমেহরা ফিসফিস করে বলল,\n\n— ওই যে! কালকের সেই হ্যান্ডসাম লোকটা আবার এসেছে!\n\nআরিশা একবার তাকিয়ে ভ্রু কুঁচকে ফেলল।\n\n— তো?\n\n— তো মানে? মানুষটা দেখতে কেমন দেখেছিস? একেবারে সিনেমার নায়ক!\n\nআরিশা চোখ ঘুরিয়ে বলল,\n\n— দেখতে ভালো হলেই কি মানুষ ভালো হয়? মুখ দেখে কাউকে বিচার করা আমার কাজ না।\n\nমেহরা হেসে ফেলল।\n\n— তোর জীবনে যদি কোনোদিন প্রেম আসে, আমি সবার আগে অবাক হব।\n\n— আমার জীবনে প্রেম আসার আগে তুই বিয়ে করে সংসার শুরু করে ফেলবি। এবার চল।\n\nকথাটা বলেই আরিশা এগিয়ে গেল।\n\nকিন্তু সে জানত না, গাড়ির কালো কাচের ওপাশ থেকে একজোড়া চোখ তার প্রতিটি পদক্ষেপ অনুসরণ করছে।\n\nআদ্রিয়ান ফোনটা নামিয়ে রাখল।\n\n— রায়ান।\n\n— জি, স্যার?\n\n— মেয়েটার ক্লাস কখন শেষ হয়?\n\nরায়ান একটু থেমে বলল,\n\n— বিকেল তিনটায়।\n\n— ভালো।\n\n— আপনি কি ওনার সঙ্গে দেখা করবেন?\n\nআদ্রিয়ান জানালার ওপাশে তাকাল।\n\n— দেখা তো অনেক আগেই হয়ে গেছে। এবার ওকে কিছু প্রশ্নের উত্তর দিতে হবে।\n\n৩. প্রথম সংঘর্ষ\n\nবিকেল তিনটা পনেরো।\n\nক্লাস শেষ করে আরিশা যখন বিশ্ববিদ্যালয়ের গেট দিয়ে বের হলো, তখন বৃষ্টি শুরু হয়েছে।\n\nআকাশের অবস্থা দেখে সে বিরক্ত হয়ে বলল,\n\n— বাহ! ছাতা আনিনি, আর আজই বৃষ্টি হতে হলো!\n\nমেহরা ইতিমধ্যে তার ভাইয়ের গাড়িতে উঠে পড়েছে। আরিশা একা দাঁড়িয়ে ব্যাগের ভেতর ছাতা খুঁজছিল।\n\nঠিক তখনই তার সামনে একটি কালো গাড়ি এসে থামল।\n\nদরজা খুলে নেমে এল সেই মানুষটি।\n\nকালো শার্ট, গম্ভীর মুখ, চোখে অদ্ভুত এক শীতলতা।\n\nআদ্রিয়ান মির্জা।\n\nআরিশা একবার তার দিকে তাকিয়ে আবার নিজের ব্যাগে মন দিল।\n\nআদ্রিয়ান সামনে এসে দাঁড়াতেই সে বিরক্ত হয়ে বলল,\n\n— এক্সকিউজ মি, একটু সাইড দেবেন?\n\nআদ্রিয়ান নড়ল না।\n\n— তোমার সঙ্গে কথা আছে।\n\nআরিশা এবার পুরোপুরি তার দিকে তাকাল।\n\n— আমার?\n\n— হ্যাঁ।\n\n— কিন্তু আমার আপনার সঙ্গে কোনো কথা নেই।\n\nআদ্রিয়ানের ঠোঁটের কোণে ক্ষীণ হাসি ফুটল।\n\n— কথা না থাকলেও কিছু প্রশ্নের উত্তর তোমাকে দিতে হবে।\n\nআরিশা ভ্রু কুঁচকে বলল,\n\n— আপনি কি সবসময় এভাবেই মানুষের সঙ্গে কথা বলেন?\n\n— কেমনভাবে?\n\n— এমনভাবে, যেন পৃথিবীর সবাই আপনার কর্মচারী!\n\nআদ্রিয়ান কয়েক সেকেন্ড তার দিকে তাকিয়ে রইল।\n\nএই মেয়েটা সত্যিই জানে না সে কার সামনে দাঁড়িয়ে আছে।\n\nঅথবা জানলেও ভয় পাওয়ার অভ্যাস তার নেই।\n\n— তোমার নাম আরিশা রহমান, তাই না?\n\nআরিশার মুখের হাসিটা মিলিয়ে গেল।\n\n— আপনি আমার নাম জানেন কীভাবে?\n\n— তোমার নাম জানাটা কি অপরাধ?\n\n— না। কিন্তু একজন অপরিচিত মানুষ আমার নাম জানে, আমার জন্য অপেক্ষা করে আছে, আর আমাকে প্রশ্নের উত্তর দিতে বলছে—ব্যাপারটা স্বাভাবিক না।\n\nআদ্রিয়ান এবার একটু ঝুঁকে নিচু স্বরে বলল,\n\n— তাহলে অপরিচিত মানুষটার পরিচয় জেনে নাও।\n\nসে পকেট থেকে একটি কার্ড বের করে আরিশার দিকে বাড়িয়ে দিল।\n\nকার্ডটিতে লেখা—\n\nADRIAN MIRZA\nCHAIRMAN & CEO, MIRZA GROUP.\n\nনামটা পড়েই আরিশার চোখ বড় হয়ে গেল।\n\nআদ্রিয়ান মির্জা!\n\nযে মানুষটির নাম সে বিভিন্ন ব্যবসায়িক সংবাদে দেখেছে। যার সম্পর্কে শোনা যায়, তিনি নাকি নিজের সিদ্ধান্তের ব্যাপারে কখনো আপস করেন না।\n\nআর সেই মানুষটি আজ তার সামনে দাঁড়িয়ে!\n\nতবুও আরিশা নিজেকে সামলে নিয়ে বলল,\n\n— পরিচয় জানলাম। এবার বলুন, আমার সঙ্গে কী কথা?\n\nআদ্রিয়ান সরাসরি তার চোখের দিকে তাকাল।\n\n— তোমার বাবা কোথায়?\n\nপ্রশ্নটা শুনে আরিশার মুখের ভাব বদলে গেল।\n\n— কেন?\n\n— একটা পুরোনো ব্যাপারে কথা বলতে চাই।\n\n— কী ব্যাপার?\n\n— সেটা তোমার বাবাকেই বলব।\n\nআরিশা কার্ডটা তার দিকে ফিরিয়ে দিল।\n\n— তাহলে আমার বাবার সঙ্গে যোগাযোগ করুন। আমাকে মাঝখানে টানছেন কেন?\n\nআদ্রিয়ান কার্ডটা নিল না।\n\n— কারণ তোমার বাবাকে খুঁজে পাওয়া যাচ্ছে না।\n\nআরিশার বুকের ভেতর অস্বস্তি জমল।\n\n— আপনি কী বলতে চাইছেন?\n\n— আমি যা বলছি, সেটাই।\n\n— দেখুন, মিস্টার মির্জা। আপনার টাকা আছে, ক্ষমতা আছে, আপনি যা ইচ্ছা করতে পারেন। কিন্তু তাই বলে সবাইকে নিজের মতো চালাতে পারবেন না।\n\nকথাটা বলে সে পাশ কাটিয়ে চলে যেতে চাইল।\n\nআদ্রিয়ান এবার তার পথ আটকায়নি।\n\nশুধু পেছন থেকে বলল,\n\n— তোমার বাবা যদি তোমাকে এমন কোনো সত্যের সামনে দাঁড় করান, যেটা তুমি সহ্য করতে পারবে না, তখনও কি তুমি এভাবেই কথা বলবে?\n\nআরিশা থেমে গেল।\n\nধীরে ধীরে পেছনে ফিরে তাকাল।\n\n— আমার বাবাকে নিয়ে আর একটা কথাও বলবেন না।\n\nপ্রথমবারের মতো তার চোখে রাগের পাশাপাশি ভয়ও দেখা গেল।\n\nআদ্রিয়ান সেটা লক্ষ করল।\n\nআর সেই মুহূর্তে তার মনে হলো, এই মেয়েটিকে সত্য জানানো যতটা কঠিন, সত্য থেকে দূরে রাখাও ততটাই অসম্ভব।\n\n৪. একটি ফোনকল, একটি অজানা বিপদ\n\nসেদিন সন্ধ্যায় বাড়ি ফিরে আরিশা দেখল, তার মা ড্রয়িংরুমে বসে আছেন। মুখটা অস্বাভাবিক গম্ভীর।\n\n— মা, কী হয়েছে?\n\nতার মা তাড়াতাড়ি মুখ তুলে তাকালেন।\n\n— তোর বাবার সঙ্গে কথা হয়েছে?\n\n— না তো। কেন?\n\n— সকাল থেকে ফোন বন্ধ। কোথায় আছে, কিছুই বুঝতে পারছি না।\n\nআরিশা মায়ের পাশে বসে তাঁর হাত ধরল।\n\n— চিন্তা কোরো না, মা। হয়তো কোনো কাজে ব্যস্ত আছেন।\n\nকথাটা বললেও নিজের মনের অস্বস্তিটা সে লুকাতে পারল না।\n\nতার ফোনে হঠাৎ একটি অচেনা নম্বর থেকে মেসেজ এল।\n\n“তোমার বাবাকে খুঁজতে চাইলে আজ রাত দশটায় পুরোনো রহমান বাড়িতে এসো। একা।”\n\nআরিশার হাত ঠান্ডা হয়ে গেল।\n\nসে সঙ্গে সঙ্গে নম্বরটিতে কল করল।\n\nফোন বন্ধ।\n\nঠিক তখনই আরেকটি মেসেজ এল।\n\n“আদ্রিয়ান মির্জাকে বিশ্বাস কোরো না। তোমার পরিবারের ধ্বংসের পেছনে তার পরিবারের হাত রয়েছে।”\n\nআরিশা স্থির হয়ে বসে রইল।\n\nআদ্রিয়ান মির্জা!\n\nতার বাবার নিখোঁজ হওয়া, অচেনা নম্বরের মেসেজ আর সেই রহস্যময় মানুষটির প্রশ্ন—সবকিছু কি কোনোভাবে একে অপরের সঙ্গে জড়িত?\n\nসে জানত না।\n\nকিন্তু একটা বিষয় সে নিশ্চিতভাবে জানত—তার বাবার কিছু একটা হয়েছে।\n\nআর সে চুপ করে বসে থাকবে না।\n\n৫. রাত দশটার প্রতিশ্রুতি\n\nরাত নয়টা পঞ্চান্ন।\n\nপুরোনো রহমান বাড়ির সামনে এসে দাঁড়াল আরিশা।\n\nবাড়িটা বহু বছর ধরে পরিত্যক্ত। চারপাশে বড় বড় গাছ, দেয়ালে শ্যাওলা আর জানালার কাচে ধুলোর স্তর। ছোটবেলায় একবার বাবার সঙ্গে এখানে এসেছিল সে। তারপর আর কখনো নয়।\n\nবাড়িটার দিকে তাকাতেই তার মনে পড়ল বাবার বলা একটি কথা—\n\n“আরিশা, পৃথিবীতে এমন কিছু দরজা থাকে, যেগুলো বন্ধ থাকাই ভালো। কারণ সব সত্য মানুষের জীবন সুন্দর করে না।”\n\nতখন কথাটার অর্থ বুঝতে পারেনি সে।\n\nআজ কেন যেন মনে হচ্ছে, বাবা এই বাড়ির কথাই বলেছিলেন।\n\nসে দরজার কাছে এগিয়ে গেল।\n\nদরজাটা সামান্য খোলা।\n\nভেতর থেকে ক্ষীণ আলো আসছে।\n\n— কেউ আছেন?\n\nকোনো উত্তর এল না।\n\nআরিশা ধীরে ধীরে ভেতরে ঢুকল।\n\nঘরের মাঝখানে একটি টেবিল। তার ওপর ধুলোমাখা কিছু কাগজ আর একটি পুরোনো কাঠের বাক্স।\n\nবাক্সটার ওপরে রাখা একটি ছবি দেখে আরিশা থমকে গেল।\n\nছবিতে তার বাবা, আদ্রিয়ানের বাবা এবং আরও একজন নারী দাঁড়িয়ে আছেন।\n\nনারীটির মুখে গভীর বিষণ্ণতা।\n\nছবির পেছনে লেখা—\n\n“আমাদের সন্তানদের যেন আমাদের পাপের মূল্য দিতে না হয়।”\n\nআরিশার বুক কেঁপে উঠল।\n\nআমাদের সন্তানদের?\n\nকোন পাপ?\n\nঠিক তখনই পেছনের দরজাটা বন্ধ হয়ে গেল।\n\nধড়াম!\n\nআরিশা চমকে পেছনে ফিরল।\n\nঅন্ধকারের ভেতর থেকে একটি কণ্ঠ ভেসে এল।\n\n— বলেছিলাম না, একা আসতে?\n\nআরিশা আতঙ্কিত হলেও নিজেকে সামলে বলল,\n\n— আপনি কে? সামনে আসুন!\n\nকোনো উত্তর এল না।\n\nতারপর হঠাৎ ঘরের আলো নিভে গেল।\n\nঅন্ধকারে আরিশা কারও পায়ের শব্দ শুনতে পেল।\n\nএক পা।\n\nদুই পা।\n\nতারপর খুব কাছে এসে কেউ বলল,\n\n— তোমার বাবাকে বাঁচাতে চাইলে আদ্রিয়ান মির্জার কাছ থেকে দূরে থাকো।\n\nআরিশা কিছু বলার আগেই একটি হাত তার হাতের মুঠোয় ছোট্ট কাগজ গুঁজে দিল।\n\nপরের মুহূর্তেই সামনের দরজায় জোরে আঘাত পড়ল।\n\n— আরিশা!\n\nকণ্ঠটা চিনতে তার এক মুহূর্তও লাগল না।\n\nআদ্রিয়ান!\n\nদরজাটা খুলে গেল। বাইরে থেকে আসা আলোয় ঘরটা আবার কিছুটা দৃশ্যমান হলো।\n\nআদ্রিয়ান দ্রুত ভেতরে ঢুকে চারপাশে তাকাল। তারপর আরিশার সামনে এসে দাঁড়াল।\n\n— তুমি এখানে কী করছ?\n\nআরিশা রাগে কাঁপতে কাঁপতে বলল,\n\n— সেটা আপনাকে বলতে হবে না!\n\n— তুমি কি বুঝতে পারছ, এখানে কী হতে পারত?\n\n— আমার বাবাকে খুঁজতে এসেছি!\n\n— আর তার জন্য নিজের বিপদ ডেকে এনেছ?\n\n— আমার বাবার কী হয়েছে, আপনি জানেন?\n\nপ্রশ্নটা শুনে আদ্রিয়ান চুপ হয়ে গেল।\n\nসেই নীরবতাই আরিশার সন্দেহ আরও বাড়িয়ে দিল।\n\nসে এক পা এগিয়ে এসে বলল,\n\n— আপনি আমার বাবাকে চেনেন, তাই না? আমাদের পরিবারের ব্যাপারে কিছু জানেন?\n\nআদ্রিয়ান তার চোখের দিকে তাকাল।\n\n— হ্যাঁ।\n\nএকটি মাত্র শব্দ।\n\nকিন্তু সেই শব্দে যেন আরিশার পায়ের নিচের মাটি সরে গেল।\n\n— তাহলে এতক্ষণ আমাকে বলেননি কেন?\n\n— কারণ সত্যিটা তুমি যত সহজে শুনতে চাইছ, তত সহজে মেনে নিতে পারবে না।\n\nআরিশার চোখ ভিজে উঠল।\n\n— সেটা আমার ব্যাপার। সত্য জানার অধিকার আমার আছে!\n\nআদ্রিয়ান কিছুক্ষণ তার দিকে তাকিয়ে রইল। তারপর নিজের কোট খুলে তার কাঁধের ওপর দিয়ে দিল।\n\n— চলো। এখানে থাকা নিরাপদ নয়।\n\nআরিশা কোটটা সরিয়ে দিতে গিয়েও থেমে গেল।\n\n— আমি আপনার সঙ্গে কোথাও যাব না।\n\nআদ্রিয়ান দীর্ঘশ্বাস ফেলল।\n\n— ঠিক আছে। কিন্তু একটা কথা মনে রেখো, আরিশা রহমান—আজ রাতে যে মানুষটা তোমাকে এখানে ডেকেছে, সে তোমার বাবার শুভাকাঙ্ক্ষী নয়।\n\n— আর আপনি?\n\nপ্রশ্নটা শুনে আদ্রিয়ানের চোখে এক মুহূর্তের জন্য অদ্ভুত কষ্ট ফুটে উঠল।\n\n— আমি কে, সেটা জানার পর হয়তো তুমিও আমাকে ঘৃণা করবে।\n\nসে ঘুরে দরজার দিকে এগিয়ে গেল।\n\nআরিশা তার পেছনে তাকিয়ে রইল।\n\nতারপর হঠাৎ নিজের মুঠোয় ধরা কাগজটার কথা মনে পড়ল।\n\nকাগজটা খুলতেই তার চোখ স্থির হয়ে গেল।\n\nসেখানে মাত্র একটি লাইন লেখা—\n\n“আদ্রিয়ান মির্জার জন্মের সত্য জানো, তারপর সিদ্ধান্ত নিয়ো—সে তোমার শত্রু, নাকি তোমার সবচেয়ে বড় আশ্রয়।”\n\nআরিশা ধীরে ধীরে মাথা তুলে দরজার দিকে তাকাল।\n\nআদ্রিয়ান তখনও সেখানে দাঁড়িয়ে।\n\nযেন সে জানে, আরিশা ঠিক কী পড়েছে।\n\nদুজনের চোখাচোখি হলো।\n\nআদ্রিয়ান শান্ত কণ্ঠে বলল,\n\n— এবার বুঝতে পারছ, আরিশা? আমাদের গল্পটা তোমার ধারণার চেয়েও অনেক পুরোনো।\n\nবাইরে আবার বৃষ্টি শুরু হলো।\n\nআর সেই বৃষ্টির শব্দের আড়ালে চাপা পড়ে গেল এমন এক সত্যের প্রথম পদধ্বনি, যা একদিন বদলে দেবে দুটি পরিবারের ভাগ্য।\n\nচলবে...🥀🖤','\n',char(10)),2,'published',0,'2026-10-28 13:47:53','2026-10-28 13:47:53',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('f8e52a9f-59d9-405b-b77a-38c841731215','1ac803b2-41a1-4776-8e00-c04cfaabe4af','পর্ব:০১',replace('#অনিচ্ছায় তুমি, অনুভবে তুমি \n#লেখিকা: হুমাইরা জান্নাত\n#পর্ব: ০১\n\nচৌধুরী পরিবারের বড় ছেলে আরহাম চৌধুরী। পরিবারের সবার আদরের ছেলে হলেও তার স্বভাব ছিল ভীষণ গম্ভীর, রাগী আর জেদি। নিজের সিদ্ধান্তের বাইরে অন্য কারও কথা শুনতে সে পছন্দ করত না। তার চোখের দিকে তাকিয়ে কথা বলার সাহস পরিবারের অনেকেরই হতো না। অথচ এই মানুষটিই একসময় পরিবারের সবার সঙ্গে হাসিখুশি থাকত। সময়ের সঙ্গে সঙ্গে তার স্বভাব বদলেছে, বেড়েছে গম্ভীরতা, আর নিজের অনুভূতিগুলো লুকিয়ে রাখার অভ্যাস হয়েছে আরও গভীর।\n\nআজ দীর্ঘ তিন বছর পর লন্ডন থেকে নিজের দেশে ফিরছে আরহাম চৌধুরী।\n\nতিন বছর আগে যে মানুষটা বিয়ের রাতেই নিজের স্ত্রীকে একা ফেলে বিদেশে চলে গিয়েছিল, আজ সে আবার ফিরে আসছে সেই বাড়িতে। যে বাড়িতে তার শৈশব কেটেছে, যে বাড়িতে তার জন্য অপেক্ষা করে আছেন মা-বাবা, দাদি এবং পরিবারের অন্য সদস্যরা। আর সেই বাড়িতেই রয়েছে তার স্ত্রী—মাহিরা চৌধুরী।\n\nকিন্তু আরহাম কি কখনো মাহিরাকে নিজের স্ত্রী হিসেবে মেনে নিয়েছে?\n\nনাকি তিন বছর আগের মতো আজও তার মনে জমে আছে সেই একই অভিমান?\n\nসেই উত্তর সময়ই দেবে।\n\nঅন্যদিকে, চৌধুরী বাড়িতে আজ সকাল থেকেই আনন্দের আমেজ।\n\nবিশাল বাড়িটার প্রতিটি কোণে যেন খুশির ছোঁয়া লেগেছে। কাজের লোকেরা সকাল থেকেই ব্যস্ত। কেউ ঘর গোছাচ্ছে, কেউ রান্নাঘরে খাবার তৈরিতে ব্যস্ত, আবার কেউ বসার ঘর সাজানোর কাজে লেগেছে। বাড়ির বড় ছেলের ফেরার খবর পেয়ে আত্মীয়স্বজনের মধ্যেও আনন্দ ছড়িয়ে পড়েছে।\n\nচৌধুরী পরিবারের গৃহকর্ত্রী মেহেরিমা বেগম সকাল থেকেই এক মুহূর্তের জন্যও বসতে পারছেন না।\n\nকখনো রান্নাঘরে গিয়ে খাবারের খোঁজ নিচ্ছেন, কখনো আবার কাজের লোকদের নির্দেশ দিচ্ছেন।\n\n— শোনো, আরহামের পছন্দের খাবারগুলো ঠিকমতো তৈরি করবে। ও এত দিন পর বাড়ি ফিরছে। কোনো কিছুতে যেন কমতি না থাকে।\n\nরান্নাঘরের একজন কর্মী হেসে বলল,\n\n— জি, বড় ম্যাডাম। আপনি চিন্তা করবেন না। সবকিছু ঠিকঠাক হয়ে যাবে।\n\nমেহেরিমা বেগম মৃদু হেসে বললেন,\n\n— আমার ছেলেটা তিন বছর পর বাড়ি ফিরছে। মা হয়ে একটু চিন্তা তো হবেই।\n\nকথাটা বলতে বলতে তাঁর চোখেমুখে আনন্দ ফুটে উঠল।\n\nতিন বছর ধরে ছেলেকে কাছে পাননি তিনি। ফোনে কথা হয়েছে, ভিডিও কলে মুখ দেখেছেন, কিন্তু নিজের হাতে ছেলেকে খাবার পরিবেশন করা কিংবা মাথায় হাত বুলিয়ে দেওয়ার যে আনন্দ, সেটা তো আর দূর থেকে পাওয়া যায় না।\n\nআজ সেই অপেক্ষার অবসান হতে চলেছে।\n\nবসার ঘরে বসে ছিলেন চৌধুরী পরিবারের প্রবীণ সদস্য জাহানারা বেগম। বয়সের ভারে শরীরটা আগের মতো শক্ত নেই, কিন্তু নাতির দেশে ফেরার খবর শুনে তাঁর মুখে যে আনন্দ ফুটেছে, তা ভাষায় প্রকাশ করার মতো নয়।\n\nতিনি পাশে বসা মাহির চৌধুরীকে বললেন,\n\n— মাহির, তোর ছেলেটা আজ বাড়ি ফিরছে। কত দিন পর নিজের চোখে দেখব ওকে!\n\nমাহির চৌধুরী মায়ের দিকে তাকিয়ে হেসে বললেন,\n\n— হ্যাঁ, মা। আমিও তো অপেক্ষা করে আছি। ছেলেটা বাড়িতে থাকলে বাড়িটা অন্য রকম লাগে।\n\nজাহানারা বেগম দীর্ঘশ্বাস ফেলে বললেন,\n\n— তা তো লাগবেই। আরহাম ছোটবেলায় কী দুষ্টুই না ছিল! সারাক্ষণ বাড়িময় ঘুরে বেড়াত। আর এখন ফোন করলেও কথার উত্তর দিতে চায় না।\n\nমাহির চৌধুরী হেসে ফেললেন।\n\n— মা, তোমার নাতি এখন বড় হয়েছে। ব্যবসা সামলায়, কাজের চাপ আছে।\n\n— তাই বলে নিজের দাদির সঙ্গে একটু বেশি কথা বলা যায় না?\n\n— এবার সামনে পেলে যত খুশি কথা বলে নিয়ো।\n\nদাদিও মৃদু হেসে উঠলেন।\n\nঠিক তখনই পাশ থেকে মেহেরিমা বেগম বলে উঠলেন,\n\n— তোমরা শুধু আরহামের কথাই বলছ! আমার ছেলেটা আসার পর ওকে নিয়ে একটু শান্তিতে বসতেও দেবে না দেখছি।\n\nমাহির চৌধুরী হেসে বললেন,\n\n— ভাবি, আপনার ছেলেকে তো আমরা তিন বছর পর দেখব। একটু আদর করার অধিকার আমাদেরও আছে।\n\n— আদর করবে, তাতে আপত্তি কী? কিন্তু সবাই মিলে ওকে ঘিরে ধরলে আবার রেগে যাবে।\n\nকথাটা শুনে সবাই হেসে উঠলেন।\n\nচৌধুরী বাড়িতে আজ সত্যিই উৎসবের পরিবেশ।\n\nকিন্তু এই আনন্দের মাঝেও একজনের অনুপস্থিতি যেন সবার চোখে পড়ছিল।\n\nমাহিরা এখনো বাড়ি ফেরেনি।\n\nআর এই মাহিরাই জানে না, তার জীবনের সবচেয়ে অস্বস্তিকর মানুষটি আজ আবার তার সামনে এসে দাঁড়াতে চলেছে।\n\n\n---\n\nঅন্যদিকে, বিশ্ববিদ্যালয়ের ক্লাস শেষ করে বান্ধবী তানিয়ার সঙ্গে বের হচ্ছিল মাহিরা চৌধুরী।\n\nমাহিরা দেখতে মিষ্টি, স্বভাবে চঞ্চল, আর কথাবার্তায় ভীষণ প্রাণবন্ত। তার মুখে হাসি লেগেই থাকে। সে যেখানে যায়, সেখানে নিজের দুষ্টুমি আর মিষ্টি কথায় পরিবেশটা প্রাণবন্ত করে তোলে।\n\nতবে তার হাসিখুশি স্বভাবের আড়ালেও কিছু কষ্ট লুকিয়ে আছে। এমন কিছু কষ্ট, যেগুলো সে কাউকে বুঝতে দিতে চায় না।\n\nতানিয়া মাহিরার কাঁধে হাত রেখে বলল,\n\n— এই যে ম্যাডাম, আজ ক্লাসে এত চুপচাপ ছিলে কেন? তোমার শরীর খারাপ নাকি?\n\nমাহিরা চোখ বড় বড় করে তাকাল।\n\n— আমি চুপচাপ ছিলাম? তোর কি মাথা খারাপ হয়ে গেছে?\n\n— হ্যাঁ, তুই চুপচাপ ছিলি। সাধারণত তুই ক্লাসে যত কথা বলিস, আজ তার অর্ধেকও বলিসনি।\n\nমাহিরা হেসে বলল,\n\n— তাহলে বুঝে নে, আজ তোর ভাগ্য ভালো ছিল। আমার কথা কম শুনতে হয়েছে।\n\nতানিয়া মুখ বাঁকিয়ে বলল,\n\n— বাহ! নিজের প্রশংসা নিজেই করছিস?\n\n— অবশ্যই! নিজের প্রশংসা নিজে না করলে অন্য কেউ করবে নাকি?\n\nদুজনেই হেসে উঠল।\n\nকিছুক্ষণ পর তানিয়া বলল,\n\n— আচ্ছা, আজ তাড়াতাড়ি বাড়ি যাচ্ছিস কেন? কোথাও যাওয়ার পরিকল্পনা আছে নাকি?\n\nমাহিরা ব্যাগের ফিতা ঠিক করতে করতে বলল,\n\n— না রে। বাসায় যাব। মা নিশ্চয়ই আমার জন্য অপেক্ষা করছে।\n\n— তাহলে ঠিক আছে। কাল দেখা হবে।\n\n— হুম। আর শোন, কাল কিন্তু অ্যাসাইনমেন্টটা করে নিয়ে আসবি। পরে আবার আমার পেছনে পড়বি না!\n\n— আচ্ছা, মা! এবার যা!\n\nবান্ধবীকে বিদায় জানিয়ে মাহিরা বাড়ির উদ্দেশে রওনা দিল।\n\nগাড়িতে বসে সে জানালার বাইরে তাকিয়ে রইল। রাস্তার দুপাশের পরিচিত দৃশ্যগুলো দেখতে দেখতে কখন যে বাড়ির সামনে এসে পৌঁছেছে, বুঝতেই পারেনি।\n\nগাড়ি থেকে নেমে বাড়ির ভেতরে ঢুকতেই তার কানে এল হাসির শব্দ।\n\nমাহিরা ভ্রু কুঁচকে চারদিকে তাকাল।\n\n— বাহ! আজ বাড়িতে এত আনন্দ কিসের? কারও জন্মদিন নাকি? নাকি সবাই মিলে আমার বিয়ে ভেঙে দেওয়ার অনুষ্ঠান করছে?\n\nনিজের কথায় নিজেই হেসে ফেলল সে।\n\nব্যাগটা হাতে নিয়ে বসার ঘরের দিকে এগিয়ে গেল মাহিরা।\n\nসেখানে ঢুকতেই দেখল, পরিবারের সবাই একসঙ্গে বসে আছেন। মায়ের মুখে হাসি, বাবার মুখেও আনন্দ, আর দাদি তো যেন খুশিতে আত্মহারা।\n\nমাহিরা অবাক হয়ে বলল,\n\n— কী ব্যাপার? আমাকে বাদ দিয়ে এত আনন্দ কিসের? আমি কি এই বাড়ির কেউ না?\n\nমেহেরিমা বেগম হেসে বললেন,\n\n— আরে, তুই এসে গেছিস? আয়, এখানে বস।\n\nমাহিরা ব্যাগটা সোফায় রেখে দাদির পাশে গিয়ে বসল।\n\n— বলো তো দাদি, কী হয়েছে? সবাই এমন খুশি কেন?\n\nজাহানারা বেগম স্নেহভরা চোখে নাতনির দিকে তাকালেন।\n\n— মা, তোর জন্য একটা খবর আছে।\n\nমাহিরা কৌতূহলী হয়ে উঠল।\n\n— কী খবর? আমার জন্য আবার কী খবর?\n\nমাহির চৌধুরী মেয়ের দিকে তাকিয়ে মৃদু হেসে বললেন,\n\n— আরহাম দেশে ফিরেছে, মা।\n\nকথাটা শুনেই মাহিরার মুখের হাসি ধীরে ধীরে মিলিয়ে গেল।\n\nমনে হলো, চারপাশের সব শব্দ হঠাৎ থেমে গেছে।\n\nসে কয়েক মুহূর্ত বাবার দিকে তাকিয়ে রইল।\n\nতারপর খুব স্বাভাবিক থাকার চেষ্টা করে বলল,\n\n— ওহ্! কবে ফিরেছে?\n\nমেহেরিমা বেগম বললেন,\n\n— আজই। তিন বছর পর বাড়ি ফিরল ছেলেটা।\n\nমাহিরা নিজের আঙুলগুলো শক্ত করে চেপে ধরল।\n\nতিন বছর!\n\nপুরো তিন বছর পর!\n\nযে মানুষটা তার বিয়ের রাতেই তাকে একা ফেলে চলে গিয়েছিল, সেই মানুষটা আবার দেশে ফিরেছে।\n\nমাহিরা ঠোঁটে হাসি টেনে বলল,\n\n— ভালো তো। এত দিন পর বাড়ি ফিরেছে, সবাই নিশ্চয়ই খুব খুশি।\n\nজাহানারা বেগম নাতনির হাত ধরে বললেন,\n\n— তুই খুশি হোসনি, মা?\n\nপ্রশ্নটা শুনে মাহিরা এক মুহূর্তের জন্য থমকে গেল।\n\nতারপর হেসে বলল,\n\n— আমি আবার কেন খুশি হব, দাদি? ও তো আমার সঙ্গে কোনো যোগাযোগ রাখেনি। দেশে ফিরেছে, ভালো কথা। এতে আমার কী?\n\nকথাগুলো বলার সময় সে যথাসম্ভব স্বাভাবিক থাকার চেষ্টা করছিল।\n\nকিন্তু তার বুকের ভেতরে যে ঝড় উঠেছে, তা কেউ দেখতে পাচ্ছিল না।\n\nমেহেরিমা বেগম বললেন,\n\n— আরে, এমন করে বলছিস কেন? আরহাম তোর স্বামী। ও বাড়ি ফিরেছে, তুই অন্তত ওর সঙ্গে ভালোভাবে কথা বলিস।\n\nমাহিরা এবার একটু বিরক্ত হয়ে বলল,\n\n— মা, প্লিজ! এই মুহূর্তে এসব কথা বলতে ইচ্ছা করছে না।\n\nকথাটা বলেই সে উঠে দাঁড়াল।\n\n— আমার মাথাটা একটু ধরেছে। আমি উপরে যাচ্ছি।\n\nজাহানারা বেগম কিছু বলতে গিয়েও থেমে গেলেন।\n\nতিনি জানেন, মাহিরার মনে অনেক কষ্ট জমে আছে। কিন্তু সেই কষ্টের কথা মুখ ফুটে কাউকে বলে না মেয়েটা।\n\nমাহিরা দ্রুত সিঁড়ি বেয়ে উপরে উঠে নিজের ঘরে ঢুকে দরজা বন্ধ করে দিল।\n\nতারপর ব্যাগটা এক পাশে রেখে বিছানায় বসে পড়ল।\n\nকিছুক্ষণ চুপ করে থাকার পর নিজের মনেই ফিসফিস করে বলল,\n\n— আরহাম চৌধুরী দেশে ফিরেছে!\n\nতার ঠোঁটে তিক্ত হাসি ফুটে উঠল।\n\n— তিন বছর পর মনে পড়ল এই বাড়ির কথা? মনে পড়ল নিজের পরিবারের কথা? নাকি এবারও কিছুদিন থেকে আবার চলে যাবে?\n\nকথাগুলো বলতে বলতে তার চোখের কোণে পানি জমে উঠল।\n\nমাহিরা দ্রুত চোখ মুছে ফেলল।\n\n— না, মাহিরা। তুই আর কাঁদবি না। যে মানুষটা তোর চোখের পানির মূল্য দেয়নি, তার জন্য আর এক ফোঁটা পানিও ফেলবি না।\n\nকিন্তু মন কি আর এত সহজে কথা শোনে?\n\nমাহিরা বিছানায় শুয়ে চোখ বন্ধ করল।\n\nআর ঠিক তখনই তার মনে পড়ে গেল তিন বছর আগের সেই দিনটার কথা।\n\nযে দিনটা তার জীবনের সবচেয়ে বড় আনন্দ হওয়ার কথা ছিল।\n\nঅথচ সেই দিনটাই তার জীবনের সবচেয়ে কষ্টের স্মৃতিতে পরিণত হয়েছিল।\n\n\n---\n\nতিন বছর আগে।\n\nচৌধুরী বাড়িতে তখন বিয়ের প্রস্তুতি চলছিল।\n\nসকাল থেকেই বাড়িতে আত্মীয়স্বজনের আনাগোনা। কেউ বিয়ের কেনাকাটা নিয়ে ব্যস্ত, কেউ অতিথিদের থাকার ব্যবস্থা করছে, আবার কেউ রান্নাঘরে খাবার তৈরির কাজে সাহায্য করছে।\n\nবাড়ির সবাই খুব খুশি।\n\nকারণ, পরিবারের বড় ছেলে আরহাম চৌধুরীর বিয়ে ঠিক হয়েছে।\n\nআর পাত্রী?\n\nনিজের চাচাতো বোন মাহিরা চৌধুরী।\n\nছোটবেলা থেকেই মাহিরা আর আরহাম একই বাড়িতে বড় হয়েছে। মাহিরা সব সময় আরহামের পেছনে ঘুরত। কখনো তার ঘরে গিয়ে বিরক্ত করত, কখনো তার বই লুকিয়ে রাখত, আবার কখনো সামান্য কারণে তার সঙ্গে ঝগড়া করত।\n\nআরহাম বেশির ভাগ সময় বিরক্ত হলেও মাহিরার দুষ্টুমিগুলো নীরবে সহ্য করত।\n\nমাহিরার কাছে আরহাম ছিল তার সবচেয়ে প্রিয় মানুষ।\n\nসে কখনো মুখ ফুটে নিজের অনুভূতি প্রকাশ করেনি। কিন্তু পরিবারের অনেকেই বুঝতে পারতেন, মাহিরার মনে আরহামকে নিয়ে আলাদা একটা জায়গা রয়েছে।\n\nঅন্যদিকে, আরহাম ছিল সম্পূর্ণ আলাদা।\n\nসে মাহিরাকে ছোট বোনের মতো দেখত কি না, নাকি তার অনুভূতিগুলো অন্য রকম ছিল, তা কেউ নিশ্চিতভাবে জানত না। তবে বিয়ের প্রসঙ্গ উঠতেই সে স্পষ্ট জানিয়ে দিয়েছিল, সে এই বিয়ে করতে চায় না।\n\nসেদিন চৌধুরী পরিবারের সবাই বসার ঘরে একত্রিত হয়েছিলেন।\n\nআরহাম গম্ভীর মুখে দাঁড়িয়ে বলল,\n\n— আমি আগেও বলেছি, এই বিয়েতে আমার মত নেই। আমি মাহিরাকে বিয়ে করব না।\n\nমাহির চৌধুরী কঠিন গলায় বললেন,\n\n— আরহাম, সব সিদ্ধান্ত নিজের ইচ্ছামতো নেওয়া যায় না। পরিবারের কথাও ভাবতে হয়।\n\nআরহাম সঙ্গে সঙ্গে উত্তর দিল,\n\n— নিজের জীবন নিয়ে সিদ্ধান্ত নেওয়ার অধিকার কি আমার নেই?\n\n— অধিকার আছে। কিন্তু তোর পরিবারের প্রতিও দায়িত্ব আছে।\n\nআরহাম বিরক্ত হয়ে বলল,\n\n— দায়িত্বের কথা বলে আমাকে এমন একটা সম্পর্কে জড়িয়ে দেবেন না, যেটা আমি চাই না।\n\nঘরের পরিবেশ ভারী হয়ে উঠল।\n\nপাশে বসে থাকা জাহানারা বেগম ধীরে ধীরে উঠে দাঁড়ালেন।\n\n— আরহাম, বাবা, আমার কাছে আয়।\n\nআরহাম দাদির কাছে এগিয়ে গেল।\n\n— বলুন, দাদি।\n\nজাহানারা বেগম নাতির হাত ধরে বললেন,\n\n— তোর দাদু বেঁচে থাকতে একটা ইচ্ছা করেছিল। সে চেয়েছিল, এই দুই পরিবারের সম্পর্ক আরও গভীর হোক। তোর আর মাহিরার বিয়ে দেখে যেতে চেয়েছিল সে।\n\nআরহাম মুখ ফিরিয়ে নিল।\n\n— দাদু এখন আর নেই, দাদি।\n\n— জানি, বাবা। কিন্তু আমি তো আছি।\n\nবৃদ্ধার চোখে পানি জমে উঠল।\n\n— আমার বয়স হয়েছে। জীবনে আর কত দিন আছি জানি না। আমার শেষ ইচ্ছেটুকু কি তুই পূরণ করতে পারবি না?\n\nআরহাম চুপ করে রইল।\n\nজাহানারা বেগম আবার বললেন,\n\n— আমি তোকে জোর করতে চাই না। শুধু চাই, তুই একবার ভেবে দেখিস। মাহিরা তোকে অনেক ভালোবাসে। তুই ওকে বিয়ে করলে হয়তো একদিন তোদের মধ্যে ভালো বোঝাপড়া তৈরি হবে।\n\nআরহাম বিরক্ত গলায় বলল,\n\n— ভালোবাসা কি জোর করে হয়, দাদি?\n\n— না, বাবা। ভালোবাসা জোর করে হয় না। কিন্তু একটা সম্পর্ককে সময় দেওয়া যায়।\n\nকিছুক্ষণ নীরব থাকার পর আরহাম দীর্ঘশ্বাস ফেলল।\n\nদাদির চোখের পানি সে সহ্য করতে পারত না। ছোটবেলা থেকে এই মানুষটাই তাকে সবচেয়ে বেশি আদর করেছেন।\n\nশেষ পর্যন্ত দাদির ইচ্ছার কাছে হার মেনে সে বলল,\n\n— ঠিক আছে। আপনার ইচ্ছা পূরণ হবে। আমি বিয়ে করতে রাজি।\n\nজাহানারা বেগমের মুখে আনন্দ ফুটে উঠল।\n\nকিন্তু আরহাম সঙ্গে সঙ্গেই বলল,\n\n— তবে একটা কথা মনে রাখবেন, আমি এই বিয়ে করছি শুধু আপনার জন্য। আমার কাছ থেকে ভালোবাসা আশা করবেন না।\n\nকথাটা বলেই সে সেখান থেকে চলে গেল।\n\nআর পাশের ঘরে দাঁড়িয়ে থাকা মাহিরা কথাগুলো শুনে ফেলেছিল।\n\nতার চোখে পানি এলেও ঠোঁটে হাসি ফুটে উঠল।\n\nসে নিজের মনকে বোঝাল,\n\n— সমস্যা নেই। বিয়ের পর সব ঠিক হয়ে যাবে। একদিন না একদিন আরহাম আমাকে বুঝবে।\n\nকিন্তু সে জানত না, ভালোবাসার স্বপ্ন দেখা যত সহজ, সেই স্বপ্ন ভেঙে গেলে নিজেকে সামলানো ততটাই কঠিন।\n\n\n---\n\nবিয়ের দিনটি এসে গেল।\n\nচারদিকে সাজসজ্জা, আত্মীয়স্বজনের ভিড়, হাসি-আনন্দ আর শুভেচ্ছায় ভরে উঠল চৌধুরী বাড়ি।\n\nমাহিরাকে লাল বেনারসি আর গয়নায় অপরূপ লাগছিল।\n\nতার মুখে লাজুক হাসি, চোখে নতুন জীবনের স্বপ্ন।\n\nবিয়ের অনুষ্ঠান সম্পন্ন হলো।\n\nসবাই নবদম্পতিকে আশীর্বাদ করলেন। মাহিরার বান্ধবীরা তাকে নিয়ে মজা করল, হাসাহাসি করল।\n\nকিন্তু আরহাম পুরো সময়টা গম্ভীর হয়ে বসে রইল।\n\nমাহিরা কয়েকবার তার দিকে তাকিয়েছিল। প্রতিবারই মনে মনে ভেবেছিল, হয়তো আরহাম একটু হাসবে, হয়তো তার দিকে তাকিয়ে কিছু বলবে।\n\nকিন্তু আরহামের মুখে কোনো পরিবর্তন দেখা গেল না।\n\nরাত বাড়ল।\n\nঅতিথিরা একে একে বিদায় নিলেন।\n\nমাহিরাকে বাসরঘরে বসিয়ে দিয়ে পরিবারের নারীরা নানা রকম মজা করে ঘর থেকে বেরিয়ে গেলেন।\n\nঘরটা ফুল দিয়ে সাজানো। বিছানার ওপর গোলাপের পাপড়ি ছড়ানো। চারদিকে মিষ্টি সুবাস।\n\nমাহিরা বিছানার এক পাশে বসে অপেক্ষা করছিল।\n\nতার বুকের ভেতরে অদ্ভুত এক অনুভূতি কাজ করছিল। লজ্জা, আনন্দ, ভয় আর অজানা প্রত্যাশা—সব মিলিয়ে মনটা অস্থির হয়ে উঠেছিল।\n\nসে ভাবছিল, আরহাম ঘরে এলে কী বলবে?\n\nকীভাবে তার সঙ্গে কথা শুরু করবে?\n\nহয়তো আরহাম তাকে বলবে, নতুন জীবনটা তারা একসঙ্গে শুরু করবে।\n\nহয়তো বলবে, অতীতের সব অভিমান ভুলে যেতে।\n\nমাহিরা নিজের মনেই হেসে ফেলল।\n\nঠিক তখনই দরজা খোলার শব্দ হলো।\n\nআরহাম ঘরে ঢুকল।\n\nমাহিরা লজ্জায় মাথা নিচু করে ফেলল।\n\n— আপনি এসেছেন?\n\nআরহাম কোনো উত্তর দিল না।\n\nসে ঘরের এক পাশে রাখা আলমারির কাছে গিয়ে সেটি খুলল।\n\nমাহিরা অবাক হয়ে তাকাল।\n\nআরহাম আলমারি থেকে একটি ব্যাগ বের করল। তারপর নিজের পাসপোর্ট, ভিসার কাগজপত্র ও প্রয়োজনীয় জিনিসপত্র ব্যাগে রাখতে শুরু করল।\n\nমাহিরা এবার বিছানা থেকে উঠে দাঁড়াল।\n\n— আপনি কী করছেন?\n\nআরহাম শান্ত অথচ কঠিন গলায় বলল,\n\n— তোমার সঙ্গে আমার কিছু কথা আছে।\n\nমাহিরা ধীরে ধীরে তার কাছে এগিয়ে গেল।\n\n— কী কথা?\n\nআরহাম ব্যাগটা পাশে রেখে তার দিকে তাকাল।\n\n— প্রথমেই একটা কথা পরিষ্কার করে দিই। আমি এই বিয়ে মেনে নিতে পারিনি।\n\nমাহিরার মুখের হাসি মিলিয়ে গেল।\n\nআরহাম আবার বলল,\n\n— আমি এই বিয়ে করেছি শুধু দাদির ইচ্ছার জন্য। তোমাকে স্ত্রী হিসেবে মেনে নেওয়ার কোনো প্রতিশ্রুতি আমি তোমাকে দিচ্ছি না।\n\nমাহিরা অবিশ্বাসের চোখে তার দিকে তাকিয়ে রইল।\n\n— কিন্তু এখন তো আমাদের বিয়ে হয়ে গেছে!\n\n— বিয়ে হয়েছে পরিবারের ইচ্ছায়। আমার ইচ্ছায় নয়।\n\n— তাহলে আপনি বিয়েতে রাজি হলেন কেন?\n\nআরহাম বিরক্ত হয়ে বলল,\n\n— দাদির কথা ফেলতে পারিনি। কিন্তু তার মানে এই নয় যে আমার অনুভূতিগুলো বদলে গেছে।\n\nমাহিরার চোখ ভিজে উঠল।\n\nতবু সে কাঁপা গলায় বলল,\n\n— আমি আপনার কাছে কিছু চাইব না। আপনাকে ভালোবাসতে হবে, এমন কোনো শর্তও দেব না। শুধু আমাকে একটু সময় দিন। আমরা ধীরে ধীরে একে অপরকে বুঝতে পারি।\n\nআরহাম মাথা নাড়ল।\n\n— না, মাহিরা। তুমি আমার কাছ থেকে কোনো আশা রেখো না। আমি তোমাকে ভালোবাসি না। আর এই মুহূর্তে তোমাকে ভালোবাসার কোনো ইচ্ছাও আমার নেই।\n\nকথাগুলো মাহিরার বুকের ভেতরটা ভেঙে দিল।\n\nসে চোখের পানি আটকে বলল,\n\n— আমি কি এতটাই খারাপ?\n\nআরহাম কিছুক্ষণ চুপ করে রইল।\n\nমাহিরা আবার বলল,\n\n— আমি কি এমন কিছু করেছি, যার জন্য আপনি আমাকে এতটা অপছন্দ করেন?\n\nআরহাম দীর্ঘশ্বাস ফেলল।\n\n— বিষয়টা তোমার ভালো-মন্দের নয়। আমি এই বিয়ে চাইনি। তুমি আমার কাছ থেকে ভালোবাসা আশা করবে না। আমার জন্য নিজের জীবন থামিয়ে রাখবে না।\n\nমাহিরা এবার আর কোনো কথা খুঁজে পেল না।\n\nআরহাম ব্যাগটা হাতে তুলে নিল।\n\nমাহিরা অবাক হয়ে বলল,\n\n— আপনি কোথায় যাচ্ছেন?\n\n— লন্ডনে।\n\n— এখন?\n\n— হ্যাঁ। আমার যাওয়ার ব্যবস্থা করা আছে।\n\nমাহিরা যেন নিজের কানকে বিশ্বাস করতে পারছিল না।\n\n— আজ আমাদের বিয়ে হয়েছে। আর আপনি আজ রাতেই চলে যাবেন?\n\nআরহাম গম্ভীর গলায় বলল,\n\n— আমি এখানে থাকলে কোনো কিছু বদলে যাবে না। তাই চলে যাওয়াই ভালো।\n\nমাহিরা তার সামনে এসে দাঁড়াল।\n\n— অন্তত আজ রাতটা থাকুন। সকালে চলে যাবেন। সবাই কী ভাববে?\n\nআরহাম ঠান্ডা গলায় বলল,\n\n— অন্যরা কী ভাববে, সেটা নিয়ে আমি চিন্তা করি না।\n\nমাহিরার চোখ বেয়ে পানি গড়িয়ে পড়ল।\n\n— আর আমি? আমার কী হবে?\n\nপ্রশ্নটা শুনে আরহাম কয়েক মুহূর্ত চুপ করে রইল।\n\nকিন্তু সে কোনো উত্তর দিল না।\n\nশুধু বলল,\n\n— সময়ের সঙ্গে সবকিছু মেনে নিতে শিখে যাবে।\n\nকথাটা বলে সে দরজার দিকে এগিয়ে গেল।\n\nমাহিরা পেছন থেকে ডাকল,\n\n— আরহাম!\n\nসে থামল, কিন্তু পেছনে তাকাল না।\n\nমাহিরা কাঁপা গলায় বলল,\n\n— একটা কথা বলবেন? কোনো দিন কি আমার প্রতি আপনার একটু হলেও মায়া হবে?\n\nআরহাম কিছুক্ষণ নীরব থাকার পর বলল,\n\n— আমাকে নিয়ে কোনো স্বপ্ন দেখো না, মাহিরা। তাহলে তোমার কষ্ট কম হবে।\n\nএরপর দরজাটা খুলে সে ঘর থেকে বেরিয়ে গেল।\n\nদরজা বন্ধ হওয়ার শব্দে মাহিরা যেন বাস্তবে ফিরে এল।\n\nসে ধীরে ধীরে বিছানায় বসে পড়ল।\n\nচারপাশে ফুলের সুবাস, সাজানো ঘর, বিয়ের পোশাক আর হাতে মেহেদি।\n\nকিন্তু যার সঙ্গে নতুন জীবন শুরু করার স্বপ্ন দেখেছিল, সেই মানুষটাই তাকে একা ফেলে চলে গেল।\n\nসেই রাতে মাহিরা অনেক কেঁদেছিল।\n\nতবু ভোর হওয়ার আগেই নিজের চোখের পানি মুছে নিয়েছিল সে।\n\nনিজের মনকে বলেছিল,\n\n— তুমি চলে যান, আরহাম চৌধুরী। কিন্তু মনে রাখবেন, আমি আপনাকে ভালোবেসেছি বলে নিজের আত্মসম্মান হারাব না। আপনি আমাকে স্ত্রী হিসেবে মেনে না নিলেও আমি নিজের জীবনটা নষ্ট করব না।\n\nসেই রাতেই আরহাম বিদেশে চলে গেল।\n\nআর মাহিরা থেকে গেল চৌধুরী বাড়িতে—একটি সম্পর্কের নাম নিয়ে, অথচ সেই সম্পর্কের ভালোবাসা ছাড়াই।\n\n\n---\n\nবর্তমান।\n\nমাহিরা চোখ খুলতেই বুঝতে পারল, তার গাল বেয়ে পানি গড়িয়ে পড়ছে।\n\nসে দ্রুত চোখ মুছে উঠে বসল।\n\nতিন বছর আগের সেই রাতটা আজও তার মনে স্পষ্ট। আর আজ সেই মানুষটাই আবার এই বাড়িতে ফিরে এসেছে।\n\nমাহিরা আয়নার সামনে গিয়ে দাঁড়াল।\n\nনিজের প্রতিবিম্বের দিকে তাকিয়ে বলল,\n\n— আর না, মাহিরা। অনেক হয়েছে। আর কত দিন পুরোনো কথা মনে করে কাঁদবি? সে তোকে ভালোবাসেনি, আজও হয়তো বাসে না। তাহলে তার ফিরে আসায় তোর এত অস্থির হওয়ার কী আছে?\n\nকথাগুলো বলে সে গভীর শ্বাস নিল।\n\nঠিক তখনই দরজায় টোকা পড়ল।\n\n— মাহিরা, মা! দরজা খোল।\n\nমায়ের কণ্ঠ শুনে মাহিরা চোখ মুছে দরজা খুলল।\n\nরোকেয়া বেগম মেয়ের মুখের দিকে তাকিয়ে বললেন,\n\n— তুই কাঁদছিলি?\n\nমাহিরা জোর করে হেসে বলল,\n\n— না তো, মা। চোখে একটু পানি এসেছিল।\n\nমা মেয়ের মাথায় হাত বুলিয়ে দিলেন।\n\n— আরহাম নিচে আছে। সবাই একসঙ্গে বসেছে। তুইও নিচে আয়।\n\nমাহিরা কিছুক্ষণ চুপ করে থেকে বলল,\n\n— মা, ও কি আমার সঙ্গে কথা বলতে চায়?\n\nরোকেয়া বেগম দীর্ঘশ্বাস ফেললেন।\n\n— সেটা জানি না, মা। তবে তিন বছর পর ফিরেছে। তুই চাইলে স্বাভাবিকভাবে কথা বলিস।\n\nমাহিরা মৃদু হেসে বলল,\n\n— ঠিক আছে, মা। আমি আসছি।\n\nমা চলে যাওয়ার পর মাহিরা নিজের পোশাক ঠিক করে নিল।\n\nতারপর ধীরে ধীরে সিঁড়ি বেয়ে নিচে নামতে লাগল।\n\nড্রয়িংরুমে ঢুকতেই তার চোখ পড়ল আরহামের ওপর।\n\nসে সোফায় বসে ফোন দেখছিল।\n\nমাহিরার উপস্থিতি টের পেয়ে আরহাম একবার মুখ তুলে তাকাল।\n\nতাদের চোখাচোখি হলো।\n\nতিন বছর পর আবার মুখোমুখি তারা।\n\nমাহিরা কয়েক মুহূর্ত তাকিয়ে থেকে চোখ সরিয়ে নিল।\n\nআরহামও কোনো কথা বলল না।\n\nপরিবারের সবাই তাদের দিকে তাকিয়ে ছিলেন। জাহানারা বেগম মুচকি হেসে বললেন,\n\n— আরহাম, দেখ তো কে এসেছে!\n\nআরহাম ফোনটা পাশে রেখে স্বাভাবিক গলায় বলল,\n\n— দেখেছি।\n\nমাহিরা কথাটা শুনে মনে মনে তিক্ত হাসল।\n\nতিন বছর পর ফিরে এসেও সেই একই ব্যবহার!\n\nমেহেরিমা বেগম বললেন,\n\n— মাহিরা, তুই বস। আরহাম এত দিন পর ফিরেছে। তোরা একটু কথা বল।\n\nমাহিরা সোফার অন্য পাশে বসে পড়ল।\n\nকিছুক্ষণ কেউ কোনো কথা বলল না।\n\nঅবশেষে মাহিরা নিজেই বলল,\n\n— কেমন আছেন?\n\nআরহাম তার দিকে তাকিয়ে সংক্ষিপ্ত উত্তর দিল,\n\n— ভালো।\n\n— লন্ডনে সব ঠিক ছিল?\n\n— হ্যাঁ।\n\nএরপর আবার নীরবতা।\n\nমাহিরা আর কোনো প্রশ্ন করল না।\n\nসে বুঝে গেল, তিন বছর আগে যে দূরত্ব তৈরি হয়েছিল, তা এখনো রয়ে গেছে।\n\nকিন্তু এবার সে আর সেই দূরত্ব কমানোর জন্য নিজে থেকে চেষ্টা করবে না।\n\nমাহিরা মনে মনে সিদ্ধান্ত নিল, আরহাম তার জীবনে ফিরে এসেছে বলে সে নিজের স্বাভাবিক জীবন থামিয়ে রাখবে না।\n\nসে হাসবে, নিজের পড়াশোনা করবে, বন্ধুদের সঙ্গে সময় কাটাবে। পরিবারের সঙ্গে আনন্দ করবে।\n\nআরহাম তাকে ভালোবাসুক বা না বাসুক, নিজের আত্মসম্মান নিয়ে সে বাঁচবে।\n\nঅন্যদিকে, আরহামও বুঝতে পারল, মাহিরা আর আগের মতো তার পেছনে ঘুরে বেড়ায় না। তার চোখে সেই পুরোনো উচ্ছ্বাস নেই, কথায় নেই আগের মতো আবদার।\n\nকিন্তু এই পরিবর্তন নিয়ে সে বিশেষ কিছু ভাবল না।\n\nঅন্তত নিজেকে সেটাই বোঝাল।\n\nসে জানত না, এই বাড়িতে ফিরে আসার পর থেকে তাদের দুজনের জীবনে ধীরে ধীরে কত পরিবর্তন আসতে চলেছে।\n\nযে মেয়েটিকে সে তিন বছর আগে নিজের কাছ থেকে দূরে সরিয়ে দিয়েছিল, সেই মেয়েটির সঙ্গেই একদিন তার জীবনের সবচেয়ে গভীর অনুভূতিগুলো জড়িয়ে যাবে।\n\nকিন্তু সেই দিন আসতে এখনো অনেক দেরি।\n\nআপাতত একই বাড়িতে ফিরে এসেছে দুজন মানুষ—একজন নিজের অনুভূতি লুকিয়ে রাখতে অভ্যস্ত, অন্যজন নিজের কষ্টকে হাসির আড়ালে ঢেকে রাখতে শিখেছে।\n\nতাদের সম্পর্কের নাম স্বামী-স্ত্রী।\n\nকিন্তু তাদের মধ্যে এখনো ভালোবাসার শুরু হয়নি।\n\nচলবে… 🖤\n\nপর্বটি ভালো লাগলে লাইক দিয়ে কমেন্টে জানিয়ো, পরের পর্বে আরহাম ও মাহিরার সম্পর্ক কোন দিকে এগোবে, তা জানতে চাও কি না।','\n',char(10)),1,'published',0,'2026-10-28 14:11:49','2026-10-28 14:11:49',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('38b94ba6-1d3c-483f-a474-aeed7de4fe62','aa2b05b1-1bce-43a3-b2fe-ffe564d42279','লাল শাড়ি',replace('- “তোর স্বামী কি আজকেও....”\n - “আজকেও আমার গায়ে হাত তুলেছে।”\n - “তুই চলে আসছিস না কেনো? বিয়ের পরের দিন থেকে তোর গায়ে হাত তোলে। তুই কষ্ট সহ্য করছিস কেনো?”\n - “ভাইয়ার সম্মান নষ্ট করতে চায়না।”\n - “মিষ্টি তোর ভাইয়া কোনদিনও চাইবে না তুই কষ্ট পা। তুই একবার তোর ভাইয়াকে সত্যি কথা বলে দে।”\n - “কেউ একজন আমার ভাইয়ের জন্য আমায় ছেড়েছিল। তার ত্যাগকে মিথ্যা করতে পারবো না।”\n - “ভালোবাসিস এখনো? ভুলতে পারবি না ওকে?”\n - “নিজের জীবনের একমাত্র অপরাধী কে ভোলা কী এত সহজ?”\n - “সে যদি অপরাধী হয় তবে তার খারাপ চাস না কেন?”\n - “আমায় অপরাধী বানিয়ে সে যদি অন্য একজনকে বুকে নিয়ে ভালো থাকে তবে ‘ভালো থাকুক ভালোবাসা, অন্য কাউকে ভালোবেসে’। আমি তার আর খারাপ চাইবো না।”\n\nএটা বলে মিষ্টি স্মিত হাসলো। তবে তা ছিল তাচ্ছিল্যের হাসি। এরপর সে উঠে রান্নাঘর থেকে চা নিয়ে এসে আবার অন্তরার কাছে বসে।\n এরপর অন্তরা আবার জিজ্ঞেস করে-\n - “শাড়িটা কোথায়?”\n - “ওই বাড়ি থেকে আনা অপ্রয়োজনীয় জিনিসগুলো যে সুটকেসে রেখেছি ওখানে।”\n - “আমায় একবার দেখাবি না?”\n - “ছূঁতে চায় না ওটা কে। যেদিন পৃথিবী ছেড়ে চলে যাব সেদিন ওটাকে ছোঁবো। আমার মৃত্যু ওই শাড়ি পড়েই হবে।”\n - “এসব কি বলছিস তুই। তার মানে কি তুই সুইসা....”\n - “ভয় নেই আমার ধৈর্যের বাঁধ এখনো ভাঙেনি। তবে ভাঙতে আর বেশি দেরি নেই। ওয়েল তোর ফ্লাইট এর সময় হয়ে যাচ্ছে তোর বেরোনো উচিত।”\n\nঅন্তরা অবাক হলেও সে কিছু বলে না।কিছুক্ষণের মধ্যে অন্তরা নিজের গন্তব্যস্থলে চলে যায়। মিষ্টি আবারো একা থেকে যায় এই অন্ধ কুঠিরে। হ্যাঁ তার শ্বশুরবাড়ি তার জন্য অন্ধ কুঠিরের থেকে বড়ো কিছু না। যেদিন বিয়ে হয়ে এ বাড়িতে এসেছিল ঠিক তার পরের দিন থেকেই তার স্বামী তার গায়ে হাত তোলে। যতদিন তার শ্বশুর শাশুড়ি বাড়িতে ছিল ততদিন অত্যাচার কম হলেও তারা গ্রামের বাড়ি চলে যাওয়ায় অত্যাচার বেড়ে যায়। এমন কোনো নেশা নেই যা তার স্বামী করে না। গত এক সপ্তাহ হল মিষ্টি জানতে পেরেছে তার স্বামীর নাকি একটা গার্লফ্রেন্ড আছে। কিন্তু এতসব ঘটনার মধ্যেও মিষ্টির কোনো ভ্রুক্ষেপ নেই। কারণ তার মনে তার স্বামীর জন্য কোনো জায়গা নেই। তার সবটা জুড়ে শুধুমাত্র একজন মানুষেরই বাস অতীত, বর্তমান, ভবিষ্যৎ সব সেই মানুষটারই দখলে।\n\nঅন্তরা চলে যাওয়ার পরে মিষ্টি তার ঘরে গেল। না এই ঘরে সে থাকলেও তার স্বামী তার সাথে থাকে না সে আলাদা থাকে। মিষ্টি ঘরের একটা কোণে দেয়ালে হেলান দিয়ে বসে এরপর চোখ বুজে ছয় মাস আগের কথা মনে করতে থাকে-\n - “আপনি ভাইয়াকে কিছু বলবেন না? ওরা কাল আমায় দেখতে আসবে।”\n - “বিয়েটা করে নাও মিষ্টি।”\n - “মানেটা কি, বিয়ে করে নেবো মানে? ফারাজ আমি আপনাকে ভালোবাসি। তাহলে অন্য কাউকে বিয়ে আমি কেনো করবো?”\n - “কিন্তু আমি তোমার ভাইকে কিছু বলতে পারবো না। আমি কোনো কিছুর জন্যই ওর আমার বন্ধুত্ব নষ্ট করতে পারবো না। ”\n - “আচ্ছা, যদি বলতেই না পারেন তাহলে ভালোবাসলেন কেনো? বন্ধুর বোনকে এতগুলো স্বপ্ন দেখানোর কি মানে?”\n - “তুমি আমার অপরাধী মিষ্টি। আমি যখন ভালোবেসে ছিলাম আমি তো জানতাম না তুমি আয়ানের বোন। কিন্তু এখন যখন জানতে পেরেছি আমি কিছুতেই আয়ানকে বলতে পারবো না।”\n - “বেশ আমি আপনার অপরাধী তো। সমস্যা নাই, সারা জীবন এটাই সহ্য করবো।”\n এই বলে মিষ্টি পুকুর ঘাট থেকে চলে আসতে চাই। ঠিক তখনই ফারাজ তাকে আটকাই। তারপর তার হাতে একটা প্যাকেট তুলে দেয়। \n - “এটা রাখো মিষ্টি। তোমায় বিয়ে করার পর এটা প্রথম উপহার দেবো ভেবেছিলাম, কিন্তু সেটা সম্ভব না। আর যেহেতু শাড়িটা তোমার জন্য কিনেছি তাই অন্য কাউকে দিতেও পারবোনা। আমি তোমার বিয়েতে থাকছি না এটা তোমার বিয়ের উপহার। প্রাক্তন হিসেবে না তোমার ভাইয়ার বন্ধু হিসেবে দিলাম।”\nএই বলে ফারাজ সেখান থেকে চলে যায়। মিষ্টি প্যাকেট টা খুলে দেখে তাতে একটা লাল রঙের বেনারসী শাড়ি। এরপরে মিষ্টির বিয়ে ঠিক হয়। যথারীতি বিয়েও হয়, মিষ্টি সেই শাড়িটা পড়েই বিয়ে করেছিল যেটা তাকে ফারাজ দিয়েছিল। বিয়ের পর মিষ্টিকে যখন শ্বশুর বাড়ি নিয়ে যাওয়া হচ্ছিল ঠিক তখনই পালকিতে ওঠার সময় মিষ্টির দূরে গাছের আড়ালে কারোর একটা ছায়া দেখতে পায়। তার একবারও বুঝতে অসুবিধা হয় না এটা ফারাজ। সে তাছ্যিল্যের একটা হাসি দেয় আর গেয়ে ওঠে-\n\n  “ তোমার দেওয়া লাল শাড়িটা \n   পইরা আমি বিদায় নিলাম,\n    একবারও দেখলা না আমারে। \n   তোমার নামে আলতা পরে \n   বসেছিলাম অপেক্ষাতে,\n     তবু দোষী বানাইলা আমারে......।”\n\nআগের কথাগুলো ভাবতে ভাবতে মিষ্টির চোখে জল চলে আসে। সে তৎক্ষণাৎ সেই জল মুছে নিয়ে হাসতে শুরু করে। আর ঠিক তখনই তার ঘরে মাতাল অবস্থায় প্রবেশ করে তার স্বামী। \n - “পাগলের মতো হাসছিস কেনো? নতুন ভা*** পাইছোস? লজ্জা করে না জামাই থাকতে অন্যের দিকে নজর দিতে? কিরে মুখ খোল?”\nএইটা বলে প্যান্ট থেকে বেল্ট খুলে মিষ্টিকে মারতে শুরু করে। না মিষ্টি একটাও চিৎকার করেনি, এই মার তার সহ্য হয়ে গেছে। \n\nদীর্ঘ আধঘন্টা মিষ্টির উপর অত্যাচার করার পর তার স্বামী ঘর থেকে চলে যায় নিজের ঘরে। আর মিষ্টি বিনা আওয়াজে নিজের অশ্রু বিসর্জন দিতে থাকে। তখনই তার চোখ যায় মাথার উপরে ঘুরতে থাকা ফ্যানের দিকে, আর সেই ফ্যানের দিকে তাকিয়ে সে হাসতে শুরু করে। মিষ্টি বাঙ্কার থেকে নিজের সুটকেস গুলো নামায় আর সেখান থেকে বেরিয়ে আসে একটা লাল বেনারসী। \n***************************************\n\n - “হ্যালো হ্যা..হ্যালো ফারাজ তুই কোথায়?”\n - “আমি তো অফিসে। তোর গলা এরকম লাগছে কেনো, কি হয়েছে?”\n - “ফা..ফারাজ আমার বোন”\n ‘আমার বোন’ শব্দ টা শুনতে ফারাজের বুকটা কেমন হু হু করে ওঠে। সে আয়ানকে শান্ত হতে বলে জিজ্ঞেস করে কি হয়েছে। আর আয়ান বলে-\n - “আমার মিষ্টি আর এই দুনিয়াতে নেই ফারাজ। নিজের স্বামীর নির্যাতন সহ্য না করতে পেরে আমার বোন সুইসাইড করেছে। তুই আমার সাথে যাবি ফারাজ।”\nফারাজের দুনিয়া যেন থমকে যায়। সে নিজের কানকে বিশ্বাস করতে পারে না। তার কানে শুধু একটাই কথা বাজতে থাকে-\n - “নিজের স্বামীর নির্যাতন সহ্য না করতে পেরে আমার বোন সুইসাইড করেছে।”\nফারাজ না থাকতে পেরে তখনই গাড়ি নিয়ে বেরিয়ে যাই। প্রায় ১৫ মিনিট পর ফারাজ আর আয়ান পৌঁছায় মিষ্টির শ্বশুরবাড়ি। মিষ্টির দেহটা পড়ে আছে নিথর অবস্থাই। আয়ান ছুটে যায় তার বোনের কাছে। তোর বোনকে জড়িয়ে কাঁদতে থাকে। ফারাজ এগিয়ে যেতে পারে না। এরপর আয়ান উঠে গিয়ে মিষ্টির স্বামীর কলার ধরে চিৎকার করতে শুরু করে। আর উল্টো দিকে ফারাজ মিষ্টির কাছে যায়। \n - “কেনো করলি এরকম আমার বোনটাকে কেনো কেড়ে নিলি। তোর পছন্দ না হলে বলে দিতি পাঠাতাম না আমার বোনকে। আমার বোনকে রাখার মতো ক্ষমতা আমার ছিল। কেনো করলি এমন স্কাউন্ড্রেল।”\n - “ওকে ছেড়ে দে আয়ান। দোষ ওর না আমার।”\n - “তুই এইসব কি বলছিস ফারাজ?”\nফারাজ উত্তর দিল না সে মিষ্টির দিকে তাকিয়ে আছে। মিষ্টি পড়নে আজকে সেই লাল শাড়িটা। কত সুন্দর করে সেজেছে মেয়েটা। কার জন্য সেজেছে ফারাজের জন্য? হয়তো। ফারাজ তো দেখেনি এই শাড়িটা পড়ে মিষ্টি কে। সেদিন গাছের ফাঁক থেকে কিছু দেখতে পায়নি সে। তাই হয়তো দেখিয়ে দিল। তার এই রুপ যার আগুনে ফারাজ কবেই শেষ হয়ে গিয়েছিল। ঠিক তখনই মিষ্টির হাতে ফারাজ একটা চিরকুট দেখতে পাই। আর তাতে লেখা ছিল- \n      “চার বেহারার পালকি কইরা\n         যাব আবার কাধে চইরা\n        শেষ দেখা দেখো দাঁড়িয়ে\n         চাইলেও তুমি পাবেনা আর\n        ফিরে এই আমাকে\n     ফুল দিয়ে দিও গো সাজিয়ে....”','\n',char(10)),1,'published',0,'2026-10-28 15:11:22','2026-10-28 15:11:22',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('b0eb62c2-866a-4c83-8053-0833c470897b','767cb584-4f32-47e3-b976-2e77450aa511','পর্ব ২: ভালোবাসা, নাকি বিচ্ছেদ?',replace('১. অপেক্ষার শেষ প্রহর\n\nসকাল ১০টা।\n\nভার্সিটির সেই পুরোনো বটগাছের নিচে দাঁড়িয়ে আছে আরিয়ান। হাতে ফোন, চোখ দুটো বারবার গেটের দিকে চলে যাচ্ছে। গত রাত থেকে তার মাথায় শুধু একটা কথাই ঘুরছে—নীলার বিয়ে কি সত্যিই ঠিক হয়ে গেছে?\n\nগতকাল রাতে ঠিকমতো ঘুমাতে পারেনি সে। বারবার নীলার সঙ্গে কাটানো মুহূর্তগুলো মনে পড়েছে। নীলার হাসি, তার রাগ, ছোট ছোট অভিমান—সবকিছু যেন আরিয়ানের জীবনের অংশ হয়ে গেছে।\n\nকিন্তু একটা প্রশ্নের উত্তর সে জানে না।\n\nনীলা কি কখনো আরিয়ানকে নিজের মানুষ হিসেবে ভেবেছে?\n\nহঠাৎ পেছন থেকে পরিচিত কণ্ঠ ভেসে এল।\n\n— কতক্ষণ ধরে দাঁড়িয়ে আছ?\n\nআরিয়ান ফিরে তাকাল। নীলা দাঁড়িয়ে আছে। পরনে সাদা পোশাক, খোলা চুল, চোখেমুখে অদ্ভুত একটা বিষণ্নতা।\n\nআরিয়ান কিছুক্ষণ চুপ থেকে বলল,\n\n— অনেকক্ষণ।\n\n— আমাকে কিছু বলবে?\n\nআরিয়ান দীর্ঘশ্বাস ফেলল।\n\n— হ্যাঁ। তোমার বিয়ের কথা শুনলাম। ব্যাপারটা কি সত্যি?\n\nনীলার মুখের হাসিটা মুহূর্তেই মিলিয়ে গেল।\n\nসে নিচের দিকে তাকিয়ে বলল,\n\n— হ্যাঁ, সত্যি।\n\nকথাটা শুনে আরিয়ানের বুকের ভেতরটা কেমন যেন করে উঠল।\n\n— তুমি রাজি?\n\nনীলা কোনো উত্তর দিল না।\n\nআরিয়ান আবার জিজ্ঞেস করল,\n\n— নীলা, আমি তোমাকে একটা কথা জিজ্ঞেস করছি। তুমি কি এই বিয়েতে রাজি?\n\nনীলা ধীরে ধীরে বলল,\n\n— আমার রাজি হওয়া বা না হওয়াতে কিছু যায় আসে না, আরিয়ান। পরিবার যা সিদ্ধান্ত নেবে, আমাকে সেটাই মেনে নিতে হবে।\n\nআরিয়ান অবাক হয়ে তাকিয়ে রইল।\n\n— নিজের জীবনের সিদ্ধান্তও তুমি নিতে পারবে না?\n\nনীলার চোখ দুটো ভিজে উঠল।\n\n— সব মানুষের জীবন তোমার মতো সহজ হয় না, আরিয়ান।\n\nকথাটা বলে নীলা চলে গেল।\n\nআরিয়ান দাঁড়িয়ে রইল সেই বটগাছের নিচে।\n\nতার মনে হলো, নীলার চোখের আড়ালে এমন কোনো কষ্ট লুকিয়ে আছে, যার কথা সে জানে না।\n\n২. বন্ধুর কাছে স্বীকারোক্তি\n\nদুপুরে ক্যান্টিনে বসে ছিল আরিয়ান। সামনে এক কাপ চা, কিন্তু চায়ের দিকে তার কোনো মনোযোগ নেই।\n\nরাফি এসে পাশে বসে বলল,\n\n— কী রে, মুখটা এমন শুকনো কেন?\n\nআরিয়ান চুপ।\n\n— নীলার সঙ্গে কথা হয়েছে?\n\n— হয়েছে।\n\n— কী বলল?\n\nআরিয়ান কিছুক্ষণ পর উত্তর দিল,\n\n— ওর বিয়ে ঠিক হয়েছে। আর ও বলছে, পরিবারের সিদ্ধান্ত মেনে নিতে হবে।\n\nরাফি দীর্ঘশ্বাস ফেলে বলল,\n\n— তুই কি ওকে ভালোবাসিস?\n\nপ্রশ্নটা শুনে আরিয়ান থমকে গেল।\n\nসে এত দিন নিজের মনকে এই প্রশ্নটা করেনি। অথবা করলেও উত্তরটা স্বীকার করতে চায়নি।\n\nকিছুক্ষণ নীরব থাকার পর সে বলল,\n\n— হ্যাঁ, দোস্ত। ভালোবাসি।\n\nরাফি মুচকি হেসে বলল,\n\n— তাহলে ওকে বলিসনি কেন?\n\n— ভয় লাগে।\n\n— কীসের ভয়?\n\nআরিয়ান জানালার বাইরে তাকাল।\n\n— যদি ও আমাকে শুধু বন্ধু ভাবে? যদি আমার কথা শুনে আমাদের বন্ধুত্বটাও শেষ হয়ে যায়?\n\nরাফি এবার গম্ভীর হয়ে বলল,\n\n— একটা কথা মনে রাখিস। মনের কথা না বললে মানুষ কখনো কখনো উত্তর না পাওয়ার কষ্টেই আটকে থাকে। কিন্তু ভালোবাসা মানে কাউকে নিজের করে পাওয়ার জেদ নয়। ভালোবাসা মানে তার অনুভূতিকেও সম্মান করা।\n\nআরিয়ান বন্ধুর কথাগুলো মন দিয়ে শুনল।\n\nসেদিন সে একটা সিদ্ধান্ত নিল।\n\nনীলাকে নিজের মনের কথা বলবে।\n\nকিন্তু তার আগে জানতে হবে, নীলার হৃদয়ে অন্য কেউ আছে কি না।\n\n৩. নীলার ডায়েরি\n\nসন্ধ্যা ৭টা।\n\nনিজের ঘরে জানালার পাশে বসে আছে নীলা। বাইরে হালকা বৃষ্টি হচ্ছে। টেবিলের ওপর খোলা একটা ডায়েরি।\n\nনীলা কলম হাতে নিয়ে লিখতে শুরু করল—\n\n“প্রিয় ডায়েরি,\n\nআজ আরিয়ান আমাকে জিজ্ঞেস করেছিল, আমি বিয়েতে রাজি কি না। কীভাবে ওকে বোঝাব, আমার জীবনে কত কিছুই না আছে, যা আমি চাইলেও নিজের ইচ্ছেমতো করতে পারি না?\n\nআরিয়ান যখন আমার দিকে তাকিয়ে প্রশ্ন করছিল, তখন খুব ইচ্ছে হচ্ছিল ওকে সবকিছু বলে দিই। বলে দিই, ওর সঙ্গে কথা বলতে আমার ভালো লাগে। ওর সঙ্গে দেখা না হলে আমার দিনটা অসম্পূর্ণ মনে হয়। ও হাসলে আমারও হাসি পায়, আর ও মন খারাপ করে থাকলে আমারও ভালো লাগে না।\n\nকিন্তু আমি কীভাবে বলব, আরিয়ান?\n\nযদি ও আমার অনুভূতি বুঝতে না পারে? যদি আমাকে শুধু বন্ধু ভেবে থাকে?\n\nআমি জানি না, ওর মনে আমার জন্য কী আছে। শুধু জানি, ওকে হারানোর কথা ভাবলে আমার ভীষণ কষ্ট হয়।”\n\nলেখা শেষ করে নীলা ডায়েরিটা বন্ধ করল।\n\nঠিক তখনই তার ফোন বেজে উঠল।\n\nমায়ের ফোন।\n\n— হ্যালো, মা?\n\nওপাশ থেকে মা বললেন,\n\n— নীলা, আগামী শুক্রবার ছেলেপক্ষ তোমাকে দেখতে আসবে। তুমি যেন কোনো আপত্তি না করো।\n\nনীলা কিছুক্ষণ চুপ থেকে বলল,\n\n— মা, আমি কি তোমার সঙ্গে একটু কথা বলতে পারি?\n\n— কী কথা?\n\n— আমার বিয়ে নিয়ে। আমি এখনই বিয়ে করতে চাই না।\n\nওপাশে কয়েক সেকেন্ড নীরবতা।\n\nতারপর মা বললেন,\n\n— তোমার বাবার অনেক আশা এই বিয়ে নিয়ে। আমাদের কথা একটু ভাবো, মা।\n\nফোনটা কেটে গেল।\n\nনীলা ডায়েরিটা বুকে জড়িয়ে ধরল।\n\nতার চোখ বেয়ে কয়েক ফোঁটা জল গড়িয়ে পড়ল।\n\nসে ফিসফিস করে বলল,\n\n— আরিয়ান, তুমি যদি একবার বলতে... আমার জীবনে তোমার কোনো জায়গা আছে কি না!\n\n৪. বৃষ্টিভেজা সন্ধ্যায় ভালোবাসার প্রশ্ন\n\nপরের দিন বিকেলে আরিয়ান নীলাকে মেসেজ করল।\n\nআরিয়ান: নীলা, আজ একটু দেখা করবে?\n\nনীলা: কেন?\n\nআরিয়ান: একটা কথা বলার আছে।\n\nনীলা: কী কথা?\n\nআরিয়ান: সামনে বসে বলব।\n\nকিছুক্ষণ পর নীলার উত্তর এল।\n\nনীলা: ঠিক আছে। বিকেল পাঁচটায় ক্যাম্পাসে এসো।\n\nবিকেল পাঁচটা।\n\nআকাশজুড়ে কালো মেঘ। বাতাসে বৃষ্টির গন্ধ।\n\nনীলা এসে দেখল, আরিয়ান বটগাছের নিচে দাঁড়িয়ে আছে।\n\n— কী বলবে বলেছিলে?\n\nআরিয়ান একটু ইতস্তত করে বলল,\n\n— নীলা, তুমি কি আমাকে বিশ্বাস করো?\n\nনীলা অবাক হয়ে বলল,\n\n— হঠাৎ এই প্রশ্ন কেন?\n\n— আগে উত্তর দাও।\n\n— হ্যাঁ, করি।\n\nআরিয়ান গভীর শ্বাস নিল।\n\n— তাহলে একটা কথা মন দিয়ে শোনো। আমি জানি না, তুমি কীভাবে নেবে। কিন্তু অনেক দিন ধরে কথাটা তোমাকে বলতে চেয়েছি।\n\nনীলা চুপ করে তার দিকে তাকিয়ে রইল।\n\nআরিয়ান বলল,\n\n— তোমার সঙ্গে প্রথম যেদিন দেখা হয়েছিল, সেদিন ভাবিনি তুমি আমার জীবনে এতটা গুরুত্বপূর্ণ হয়ে উঠবে। প্রথমে তোমার সঙ্গে কথা বলতে ভালো লাগত। তারপর তোমার সঙ্গে দেখা না হলে খারাপ লাগতে শুরু করল। তুমি হাসলে আমার ভালো লাগত, তুমি মন খারাপ করলে আমারও মন খারাপ হতো।\n\nনীলার চোখে বিস্ময়।\n\nআরিয়ান এবার সরাসরি তার চোখের দিকে তাকাল।\n\n— নীলা, আমি তোমাকে ভালোবেসে ফেলেছি।\n\nচারপাশটা যেন মুহূর্তের জন্য নীরব হয়ে গেল।\n\nনীলা কোনো কথা বলতে পারল না।\n\nআরিয়ান ধীরে ধীরে বলল,\n\n— আমি তোমার কাছে কোনো উত্তর জোর করে চাইছি না। তুমি আমাকে ভালো না বাসলে সেটাও মেনে নেব। শুধু চেয়েছিলাম, তুমি আমার মনের কথাটা জানো।\n\nনীলা মুখ ফিরিয়ে নিল।\n\nতার চোখে জল চিকচিক করছে।\n\nআরিয়ান ব্যস্ত হয়ে বলল,\n\n— নীলা, তুমি কাঁদছ কেন? আমি কি ভুল কিছু বলেছি?\n\nনীলা মাথা নাড়ল।\n\n— না, আরিয়ান।\n\n— তাহলে?\n\nনীলা চোখের জল মুছে বলল,\n\n— তুমি এত দেরি করে বললে কেন?\n\nআরিয়ান অবাক হয়ে তাকিয়ে রইল।\n\n— মানে?\n\nনীলা কাঁপা কণ্ঠে বলল,\n\n— তুমি যদি আরও আগে বলতে, তাহলে হয়তো আমার এত ভয় লাগত না।\n\nআরিয়ানের বুকের ভেতরটা কেঁপে উঠল।\n\n— তার মানে... তুমিও?\n\nনীলা চোখ নামিয়ে মৃদু স্বরে বলল,\n\n— হ্যাঁ, আরিয়ান। আমিও তোমাকে ভালোবাসি।\n\nআরিয়ান যেন নিজের কানকে বিশ্বাস করতে পারছিল না।\n\n— সত্যি বলছ?\n\nনীলা হালকা হেসে বলল,\n\n— না, মিথ্যা বলছি! এতক্ষণ ধরে বৃষ্টিতে দাঁড়িয়ে মজা করছি!\n\nআরিয়ান হেসে ফেলল।\n\n— এই মেয়েটা কোনো দিনও ঠিক হবে না!\n\nদুজনেই হেসে উঠল।\n\nকিন্তু সেই হাসির মাঝেই নীলা ধীরে ধীরে বলল,\n\n— আরিয়ান, আমাদের ভালোবাসার পথটা সহজ হবে না।\n\nআরিয়ানের হাসি থেমে গেল।\n\n— কেন?\n\nনীলা উত্তর দেওয়ার আগেই আকাশ থেকে বৃষ্টি নামতে শুরু করল।\n\nবৃষ্টির শব্দের মাঝে নীলা বলল,\n\n— কারণ আমার বিয়ে আগামী শুক্রবার।\n\nআরিয়ান স্তব্ধ হয়ে গেল।\n\n৫. শেষ আশার আলো\n\nবৃষ্টি তখন আরও জোরে পড়ছে।\n\nআরিয়ান আর নীলা একটা ছাউনির নিচে দাঁড়িয়ে আছে। দুজনের কেউই কথা বলছে না।\n\nঅবশেষে আরিয়ান বলল,\n\n— তুমি কি আমাকে আগে বলতে পারতে না?\n\nনীলা চোখ মুছে বলল,\n\n— কী বলতাম? যে আমি তোমাকে ভালোবাসি, অথচ আমার পরিবার অন্য কোথাও আমার বিয়ে ঠিক করছে? আমি নিজেই তো জানতাম না কী করব।\n\nআরিয়ান কিছুক্ষণ চুপ থেকে বলল,\n\n— তুমি কি এই বিয়ে করতে চাও?\n\nনীলা মাথা নাড়ল।\n\n— না।\n\n— তাহলে তোমার পরিবারের সঙ্গে কথা বলো। তাদের বোঝাও।\n\nনীলা বিষণ্নভাবে হেসে বলল,\n\n— তুমি আমার পরিবারকে চেনো না, আরিয়ান। আমার বাবা খুব রাগী মানুষ। তিনি যা সিদ্ধান্ত নেন, তা সহজে বদলান না। আর আমাদের পরিবারের আর্থিক অবস্থাও ভালো নয়। বাবা মনে করেন, এই বিয়ে হলে আমার ভবিষ্যৎ নিরাপদ হবে।\n\nআরিয়ান শান্ত গলায় বলল,\n\n— আমি তোমাকে কোনো মিথ্যা প্রতিশ্রুতি দিতে চাই না। আমার এখনো পড়াশোনা শেষ হয়নি, নিজের পায়ে দাঁড়াতেও সময় লাগবে। কিন্তু আমি চেষ্টা করতে পারি। তোমার পরিবারকে সম্মানের সঙ্গে বোঝানোর চেষ্টা করতে পারি।\n\nনীলা তার দিকে তাকাল।\n\n— আর যদি তারা না মানে?\n\nআরিয়ান একটু থেমে বলল,\n\n— তাহলে আমরা ধৈর্য ধরব। তোমার ইচ্ছার বিরুদ্ধে কোনো সিদ্ধান্ত নেওয়া উচিত নয়। আমরা দুজন মিলে একটা সঠিক পথ খুঁজব।\n\nনীলা ধীরে ধীরে আরিয়ানের হাতটা ধরল।\n\n— আমি তোমাকে হারাতে চাই না।\n\nআরিয়ান বলল,\n\n— আমিও না।\n\nসেদিন বৃষ্টিভেজা সন্ধ্যায় তারা একে অপরকে কোনো বড় প্রতিশ্রুতি দেয়নি। শুধু ঠিক করেছিল, নিজেদের অনুভূতি নিয়ে সত্যি থাকবে এবং তাড়াহুড়ো করে কোনো সিদ্ধান্ত নেবে না।\n\nকিন্তু তাদের অজান্তেই অন্য কোথাও তৈরি হচ্ছিল এক নতুন ঝড়।\n\nরাত ৯টা।\n\nনীলার বাবা ফোনে কারও সঙ্গে কথা বলছেন।\n\n— জি, আগামী শুক্রবারই সব ঠিকঠাক হয়ে যাবে। মেয়েকে আমি বুঝিয়ে বলেছি। আপনারা নিশ্চিন্ত থাকুন।\n\nকথা শেষ করে তিনি নীলার ঘরের দিকে তাকালেন।\n\nতারপর নিচু স্বরে বললেন,\n\n— নীলা, তুমি জানো না, তোমার জন্য আমি কী সিদ্ধান্ত নিয়েছি।\n\nঅন্যদিকে আরিয়ান নিজের ঘরে বসে নীলার পাঠানো শেষ মেসেজটা পড়ছিল।\n\nনীলা: “আরিয়ান, যত কঠিন পরিস্থিতিই আসুক, আমার কথাটা মনে রেখো—আমি তোমাকে ভালোবাসি।”\n\nআরিয়ান মেসেজটার দিকে তাকিয়ে মৃদু হাসল।\n\nসে জানত না, আগামী কয়েকটা দিন তাদের জীবনের সবচেয়ে কঠিন সময় হয়ে উঠতে চলেছে।\n\nকারণ শুক্রবারের বিয়েটা শুধু একটা বিয়ের আয়োজন ছিল না।\n\nএর পেছনে লুকিয়ে ছিল এমন এক সত্য, যা জানার পর নীলার পুরো পৃথিবী বদলে যেতে পারে।\n\nচলবে... ❤️\n\nপরবর্তী পর্ব: পর্ব ৩ — এক গোপন সত্যের ছায়া\n\nআরিয়ান কি নীলার পরিবারকে বোঝাতে পারবে? নীলার বিয়ে কি সত্যিই হয়ে যাবে? আর নীলার বাবার লুকানো সিদ্ধান্তের পেছনে কী রহস্য রয়েছে?\n\nউত্তর মিলবে পরের পর্বে।','\n',char(10)),2,'published',0,'2026-10-28 15:46:58','2026-10-28 15:46:58',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('3d559adf-d8e1-4baf-9487-1a4495d317cd','26cb6db9-27be-4121-8301-f19e3f6e0dec','সাম্রাজ্যের শুরু',replace('THE BLACK BILLIONAIRE\n\nপর্ব ১: সাম্রাজ্যের শুরু\n\nঢাকা শহরের ব্যস্ত রাস্তায় প্রতিদিন হাজার হাজার মানুষ ছুটে চলে। কেউ চাকরির পেছনে, কেউ জীবিকার জন্য, আবার কেউ এমন এক স্বপ্নের পেছনে, যার মূল্য কোটি টাকা।\n\nআরিয়ান রহমান ছিল তেমনই একজন।\n\nমধ্যবিত্ত পরিবারের ছেলে আরিয়ানের কাছে বড় কোনো সম্পদ ছিল না। ছিল সামান্য পুঁজি, ব্যবসা সম্পর্কে কিছু বাস্তব অভিজ্ঞতা এবং একটা জেদ—একদিন সে নিজের কোম্পানি গড়বে। এমন কোম্পানি, যার নাম শুনলে দেশের বড় ব্যবসায়ীরাও তাকে চিনবে।\n\nমাত্র পঞ্চাশ হাজার টাকা দিয়ে সে অফিসের স্টেশনারি ও বিভিন্ন পণ্য সরবরাহের ব্যবসা শুরু করেছিল। প্রথম দিকে লাভ খুব সামান্য হতো। কখনো ক্রেতারা সময়মতো টাকা দিত না, কখনো পণ্যের দাম বেড়ে যেত। তবু আরিয়ান প্রতিদিন আয়-ব্যয়ের হিসাব লিখে রাখত।\n\nদুই বছরের মধ্যে তার ব্যবসা একটু বড় হলো। কয়েকটি বেসরকারি প্রতিষ্ঠান নিয়মিত তার কাছ থেকে পণ্য কিনতে শুরু করল। সে বুঝতে শিখল, ব্যবসায় শুধু বেশি বিক্রি করলেই ধনী হওয়া যায় না। নগদ টাকা, পাওনা, খরচ এবং সঠিক সিদ্ধান্ত—সবকিছুর হিসাব রাখতে হয়।\n\nএকদিন সকালে তার ছোট অফিসে একটি কালো গাড়ি এসে থামল।\n\nগাড়ি থেকে নামলেন রাশেদ করিম। দেশের পরিচিত ব্যবসায়ীদের একজন। তার মালিকানায় একাধিক প্রতিষ্ঠান, বিশাল অফিস এবং বহু কর্মচারী।\n\nরাশেদ অফিসে ঢুকে চারপাশ দেখে বললেন, “তোমার ব্যবসা ছোট, কিন্তু তোমার হিসাব রাখার পদ্ধতি ভালো। কখনো বড় কোম্পানির সঙ্গে কাজ করার কথা ভেবেছ?”\n\nআরিয়ান কিছুটা অবাক হলো।\n\n“অবশ্যই ভেবেছি, স্যার। কিন্তু বড় অর্ডার নেওয়ার মতো পুঁজি এখনো নেই।”\n\nরাশেদ চেয়ারে বসে একটি ফাইল খুললেন।\n\n“আমার কোম্পানির কয়েকটি প্রতিষ্ঠানের জন্য পণ্য সরবরাহকারী দরকার। তুমি কাজটা পেতে পারো। তবে আমাদের সঙ্গে দীর্ঘমেয়াদি চুক্তি করতে হবে।”\n\nআরিয়ানের চোখে নতুন স্বপ্ন জ্বলে উঠল। এই চুক্তি পেলে তার ব্যবসার আকার কয়েক গুণ বেড়ে যেতে পারে।\n\nকিন্তু রাশেদ ফাইলটি এগিয়ে দেওয়ার সময় একটি শর্ত যোগ করলেন।\n\n“কিছু আর্থিক দায়িত্বও তোমাকে নিতে হবে। সবকিছু চুক্তিতে লেখা আছে। ভালো করে পড়ে তারপর সিদ্ধান্ত নেবে।”\n\nআরিয়ান ফাইলটি হাতে নিল। প্রথম কয়েকটি পৃষ্ঠা স্বাভাবিক মনে হলেও শেষের দিকে কিছু শর্ত তার কাছে পরিষ্কার হলো না।\n\nসে বলল, “স্যার, চুক্তিটা আমার হিসাবরক্ষক ও আইনজীবীকে দেখিয়ে নিতে চাই।”\n\nরাশেদের মুখের হাসি মুহূর্তের জন্য থেমে গেল।\n\n“ব্যবসায় বিশ্বাস খুব গুরুত্বপূর্ণ, আরিয়ান। তবে তুমি চাইলে দেখে নিতে পারো।”\n\nকথাটি স্বাভাবিক শোনালেও রাশেদের চোখে যেন অন্য কিছু লুকিয়ে ছিল।\n\nআরিয়ান তখনো জানত না, এই চুক্তিই একদিন তার জীবনের সবচেয়ে বড় পরীক্ষার কারণ হবে।\n\nসেদিন রাতে অফিসে একা বসে সে ফাইলটি আবার খুলল। শেষ পৃষ্ঠার নিচে একটি প্রতিষ্ঠানের নাম দেখতে পেল, যার সঙ্গে তার কোনো পরিচয় ছিল না।\n\nনামটি ছিল—ব্ল্যাকস্টোন হোল্ডিংস।\n\nপ্রতিষ্ঠানটির ঠিকানা ঢাকার একটি অভিজাত বাণিজ্যিক ভবন। কিন্তু অদ্ভুত ব্যাপার হলো, কাগজপত্রে এর আর্থিক দায়িত্ব সম্পর্কে এমন কিছু উল্লেখ ছিল, যা পুরোপুরি বুঝতে আরিয়ানের আরও সময় দরকার।\n\nসে ফাইল বন্ধ করে নিজের খাতায় লিখল—\n\n“বড় সুযোগ মানেই বড় লাভ নয়। আগে বুঝতে হবে, আমি আসলে কীসের সঙ্গে চুক্তি করতে যাচ্ছি।”\n\nতারপর সে ফোন হাতে নিয়ে হিসাবরক্ষককে কল করল।\n\nপরদিন সকালেই চুক্তির প্রতিটি পৃষ্ঠা পরীক্ষা করা হবে।\n\nআর অন্যদিকে, নিজের বিলাসবহুল অফিসে বসে রাশেদ করিম কাউকে ফোন করে বললেন—\n\n“ছেলেটা চুক্তিটা পড়ছে। দেখি, কত দূর পর্যন্ত বুঝতে পারে।”\n\nফোনের ওপাশ থেকে একটি কণ্ঠ উত্তর দিল,\n\n“আর যদি সব বুঝে ফেলে?”\n\nরাশেদ জানালার বাইরে তাকিয়ে শান্ত গলায় বললেন,\n\n“তাহলে পরিকল্পনা বদলাতে হবে।”\n\nচলবে…\n\nপরবর্তী পর্ব: বিশ্বাসের চুক্তি','\n',char(10)),1,'published',0,'2026-10-28 17:01:55','2026-10-28 17:01:55',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('f9ef34ff-3cc8-4db1-bcfd-5ce6e4ad7bc5','00d9903c-89d1-45e0-8054-e9bf65f7337d','রাত বারোটার ডাক',replace('১৩ নম্বর ঘর\n\nপর্ব ১: রাত বারোটার ডাক\n\nগ্রামটির নাম শালিখাপুর। দিনের বেলায় গ্রামটা আর দশটা গ্রামের মতোই সাধারণ। পুকুর, বাঁশঝাড়, মাটির রাস্তা আর দূরে ধানখেত। কিন্তু সূর্য ডুবে যাওয়ার পর গ্রামটির চেহারা বদলে যায়।\n\nসন্ধ্যার পর গ্রামের মানুষ একটি নির্দিষ্ট রাস্তা এড়িয়ে চলে। রাস্তাটির শেষ মাথায় দাঁড়িয়ে আছে বহু বছরের পুরোনো একটি জমিদারবাড়ি। বাড়িটির দেয়ালে শ্যাওলা, জানালায় মরচে ধরা শিকল আর ছাদে বুনো গাছ জন্মেছে।\n\nস্থানীয় লোকেরা বাড়িটিকে বলে—তেরো নম্বর বাড়ি।\n\nকেন এই নাম, তা কেউ স্পষ্ট করে বলতে চায় না।\n\nশহর থেকে গ্রামে বেড়াতে এসেছিল নীলয়। বয়স বাইশ। ছোটবেলা থেকেই ভূতের গল্প শুনতে তার ভালো লাগত, কিন্তু সে এসব বিশ্বাস করত না।\n\nএক সন্ধ্যায় চায়ের দোকানে বসে সে বাড়িটির কথা শুনল।\n\nএক বৃদ্ধ চায়ের কাপ নামিয়ে বললেন, “বাবা, ওই বাড়ির কাছে রাতের বেলা যাস না।”\n\nনীলয় হেসে বলল, “কেন? ভূত আছে নাকি?”\n\nবৃদ্ধ তার দিকে স্থির চোখে তাকালেন।\n\n“ভূত আছে কি নেই জানি না। কিন্তু ওই বাড়িতে ঢোকার পর যারা রাত বারোটায় নিজের নাম শুনেছে, তারা আর আগের মতো থাকেনি।”\n\nকথাটা শুনে নীলয়ের কৌতূহল বেড়ে গেল।\n\nসেই রাতেই সে একটি টর্চ আর মোবাইল নিয়ে বাড়িটির দিকে রওনা হলো।\n\nবাড়ির লোহার ফটক ঠেলে খুলতেই দীর্ঘ একটা কর্কশ শব্দ হলো। ভেতরে পা রাখার সঙ্গে সঙ্গে তার মনে হলো, বাইরের ঝিঁঝিঁ পোকার ডাক হঠাৎ থেমে গেছে।\n\nবাড়ির ভেতরে ঢুকে সে দেখল, মেঝেতে ধুলোর পুরু স্তর। দেয়ালে কয়েকটি পুরোনো ছবি ঝুলছে। ছবিগুলোর মানুষগুলোর মুখ সময়ের সঙ্গে ঝাপসা হয়ে গেছে।\n\nদোতলায় উঠে নীলয় একটি লম্বা করিডর দেখতে পেল। করিডরের শেষে পাশাপাশি বারোটি দরজা। অথচ করিডরের দেয়ালে ঝোলানো একটি পুরোনো নকশায় তেরোটি ঘরের চিহ্ন আঁকা।\n\nশেষ দরজাটির অবস্থান নকশায় স্পষ্ট, কিন্তু বাস্তবে সেখানে শুধু একটি ফাঁকা দেয়াল।\n\nনীলয় মোবাইলের ক্যামেরায় ছবি তুলল।\n\nঠিক তখনই তার পেছন থেকে একটি মেয়ের কণ্ঠ ভেসে এল—\n\n“আমার ঘর খুঁজছ?”\n\nনীলয় দ্রুত ঘুরে দাঁড়াল।\n\nকেউ নেই।\n\nসে নিজেকে বোঝাল, হয়তো বাইরের বাতাসে কোনো শব্দ হয়েছে। কিন্তু পরক্ষণেই করিডরের একেবারে শেষ প্রান্তে একটি দরজা দেখা গেল।\n\nদরজাটিতে মরচে ধরা অক্ষরে লেখা—\n\n১৩।\n\nনীলয় ধীরে ধীরে দরজার কাছে গেল। দরজার নিচ দিয়ে বেরিয়ে আসছিল ঠান্ডা বাতাস। সে হাত বাড়িয়ে দরজার হাতল ধরল।\n\nভেতর থেকে কেউ ফিসফিস করে বলল, “নীলয়, এত দেরি করলে কেন?”\n\nতার শরীর ঠান্ডা হয়ে গেল।\n\nসে কাউকে নিজের নাম বলেনি। এমনকি গ্রামের কেউ জানত না যে সে এই বাড়িতে এসেছে।\n\nঠিক তখনই তার মোবাইল বেজে উঠল। স্ক্রিনে মায়ের ফোন।\n\nফোন ধরতেই মা কাঁপা গলায় বললেন, “নীলয়, তুই কোথায়?”\n\n“জমিদারবাড়িতে। কেন?”\n\nওপাশে কয়েক সেকেন্ড নীরবতা।\n\nতারপর মা বললেন, “তুই এখনই বাড়ি ফিরে আয়। আমি স্বপ্নে দেখেছি, তুই একটা বন্ধ ঘরের সামনে দাঁড়িয়ে আছিস। আর ঘরের ভেতর থেকে কেউ তোকে ডাকছে।”\n\nনীলয় কিছু বলার আগেই ফোনের সংযোগ বিচ্ছিন্ন হয়ে গেল।\n\nসে দরজার দিকে তাকাল।\n\nএবার ভেতর থেকে তিনবার টোকা পড়ল।\n\nঠক।\n\nঠক।\n\nঠক।\n\nতারপর একটি শিশুর কণ্ঠ বলল—\n\n“এবার তুমি এসেছ। এবার আমরা বের হতে পারব।”\n\nনীলয় এক পা পিছিয়ে গেল।\n\nকারণ ঠিক সেই মুহূর্তে তার পেছনের করিডরের সব দরজা একসঙ্গে বন্ধ হয়ে গেল।\n\nআর দেয়ালে ঝুলে থাকা ছবিগুলোর মধ্যে একটি ছবিতে সে দেখতে পেল নিজের মুখ।\n\nছবির নিচে লেখা তারিখটি ছিল—\n\n১৭ অক্টোবর, ১৯৯৮।\n\nঅথচ নীলয়ের জন্ম তারও তিন বছর পরে।\n\nচলবে…','\n',char(10)),1,'published',0,'2026-10-28 17:08:44','2026-10-28 17:08:44',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('622e8c1c-c038-435a-878d-2dba9935b630','aa546f2b-ffcb-4db9-941f-4d47a14da9b2','তুমি আমার শেষ ঠিকানা২',replace('💙 ১. তিহান আহমেদ — নায়ক\nবয়স: ২৫ বছর\nবাবা: মাহমুদ আহমেদ\nমা: শায়লা বেগম\nবড় বোন: তানিয়া আহমেদ\nছোট ভাই: তূর্য আহমেদ\nবর্ণনা: তিহান একজন সুদর্শন, ব্যক্তিত্বসম্পন্ন ও গম্ভীর স্বভাবের ছেলে। সে একজন প্রতিষ্ঠিত ব্যবসায়ী। পরিবারের বড় ছেলে হওয়ায় তার কাঁধে অনেক দায়িত্ব। বাইরে থেকে তাকে খুব রাগী মনে হলেও, ভেতরে সে অনেক কোমল মনের মানুষ। সহজে কাউকে বিশ্বাস করে না, কিন্তু একবার কাউকে আপন করে নিলে তাকে কখনো অবহেলা করতে চায় না।\nতিহান নিজের অনুভূতি মুখে প্রকাশ করতে পারে না। তার ভালোবাসার ভাষা হলো যত্ন, দায়িত্ব আর নীরবে পাশে থাকা। ২. তাবাস্সুম রহমান — নায়িকা\nবয়স: ২১ বছর\nবাবা: আব্দুল করিম রহমান\nমা: নাসরিন বেগম\nবড় ভাই: তামিম রহমান\nবর্ণনা: তাবাস্সুম একজন মায়াবী, সুন্দর মনের ও হাসিখুশি মেয়ে। সে পরিবারের সবার আদরের রাজকন্যা। তার হাসিতে সহজেই মানুষের মন ভালো হয়ে যায়। তবে সে খুব অভিমানী; নিজের কষ্টগুলো কাউকে বুঝতে দিতে চায় না।\nতাবাস্সুম পরিবারকে ভীষণ ভালোবাসে। সে চায়, তার জীবনে এমন একজন মানুষ আসুক, যে তার নীরবতাও বুঝবে, তার চোখের ভাষা পড়তে পারবে এবং তার অনুভূতিকে সম্মান করবে।\n🏡 তিহানের পরিবারের পরিচয়\n১. মাহমুদ আহমেদ: তিহানের বাবা। একজন প্রতিষ্ঠিত ব্যবসায়ী। তিনি গম্ভীর হলেও পরিবারের সবার ভবিষ্যৎ নিয়ে চিন্তা করেন।\n২. শায়লা বেগম: তিহানের মা। স্নেহশীল একজন নারী। তিনি চান, তার ছেলের জীবনে এমন একজন আসুক, যে তাদের পরিবারকে আপন করে নেবে।\n৩. তানিয়া আহমেদ: তিহানের বড় বোন। বিবাহিত, বুদ্ধিমতী ও মিশুক। ভাইকে খুব ভালোবাসে এবং তার মনের কথা বোঝার চেষ্টা করে।\n৪. তূর্য আহমেদ: তিহানের ছোট ভাই। দুষ্টু, হাসিখুশি ও মজার মানুষ। সে সব সময় বড় ভাইকে খেপাতে ভালোবাসে।\n🌺 তাবাস্সুমের পরিবারের পরিচয়\n১. আব্দুল করিম রহমান: তাবাস্সুমের বাবা। শান্ত, দায়িত্বশীল ও পরিবারের প্রতি যত্নশীল একজন মানুষ।\n২. নাসরিন বেগম: তাবাস্সুমের মা। মেয়ের সুখই তার কাছে সবচেয়ে গুরুত্বপূর্ণ। তিনি মেয়েকে ভালোভাবে বুঝতে চান।\n৩. তামিম রহমান: তাবাস্সুমের বড় ভাই। বোনের প্রতি ভীষণ স্নেহশীল। বোনকে কেউ কষ্ট দিলে সে চুপ করে থাকতে পারে না। তবে বোনকে খেপানোও তার প্রিয় কাজ।','\n',char(10)),2,'published',0,'2026-10-29 02:08:56','2026-10-29 02:08:56',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('fa229931-c8a1-404f-ae55-30aafef66bfc','c4867502-b7f2-4c77-b704-eba7e96e8b8d','পর্ব - ৩',replace('~ তোমার অন্ধকারে আমার বসন্ত ~\n\nWriter : Noor Islam.\n\nপর্ব ৩: যে চোখে লুকানো হাজারো প্রশ্ন\n\nসকালটা অন্য দিনের মতোই শুরু হয়েছিল।\n\nজানালার বাইরে সূর্যের আলো, পাখির ডাক আর শহরের ব্যস্ততা—সবকিছু স্বাভাবিক। অথচ আরিশা রহমানের ভেতরটা যেন অদ্ভুত এক অস্থিরতায় ভরে ছিল।\n\nগত রাতের ছবিটা সে এখনো ভুলতে পারেনি।\n\nছবিতে তার বাবার পাশে দাঁড়িয়ে থাকা তরুণ ছেলেটি আর কেউ নয়, আদ্রিয়ান মির্জা।\n\nআর ছবির পেছনে লেখা কথাগুলো যেন বারবার তার মাথার ভেতর প্রতিধ্বনিত হচ্ছিল।\n\n“যে মানুষটিকে তুমি বিশ্বাস করতে শিখছ, তার পরিবারই তোমার বাবার শেষ রাতের সত্য জানে।”\n\n—কিন্তু বাবার সঙ্গে আদ্রিয়ানের পরিবারের সম্পর্ক কী?\n\nপ্রশ্নটা যতবার মনে আসছিল, ততবারই বুকের ভেতরটা ভারী হয়ে উঠছিল।\n\nআরিশা ছবিটা ব্যাগে রেখে আয়নার সামনে দাঁড়াল। নিজেকে দেখে নিজেই বিড়বিড় করে বলল,\n\n—আরিশা রহমান, তুই কিন্তু সহজে হার মানার মেয়ে না। সত্যিটা বের করেই ছাড়বি। আর ওই রাগী লোকটার কাছ থেকে উত্তর আদায় করতে হলে সেটাও করবি!\n\nকথাটা বলেই সে নিজের চুল ঠিক করে ব্যাগ কাঁধে তুলে নিল।\n\nকিন্তু সে জানত না, যার কাছ থেকে উত্তর আদায় করার পরিকল্পনা করছে, সেই মানুষটা ইতিমধ্যেই তার প্রতিটি পদক্ষেপের খবর রাখছে।\n\n---\n\nমির্জা কর্পোরেটের বিশাল কাচঘেরা অফিসে তখন পিনপতন নীরবতা।\n\nঅফিসের কর্মীরা সবাই নিজেদের কাজে ব্যস্ত। অথচ সবার চোখে-মুখে চাপা আতঙ্ক। কারণ, তাদের বস আদ্রিয়ান মির্জার মেজাজ আজ সকাল থেকেই ভয়ংকর খারাপ।\n\nকালো শার্টের হাতা কনুই পর্যন্ত গোটানো। এক হাতে দামি ঘড়ি, অন্য হাতে ফাইল। টেবিলের ওপাশে বসে থাকা আদ্রিয়ানের চোখে বরফশীতল দৃষ্টি।\n\n—এই রিপোর্টটা কে তৈরি করেছে?\n\nআদ্রিয়ানের গম্ভীর প্রশ্নে সামনে দাঁড়িয়ে থাকা কর্মীটির গলা শুকিয়ে গেল।\n\n—স্যার, আমি...\n\n—আমি অজুহাত শুনতে চাইনি। কাজের ভুল একবার হয়, বারবার নয়। ঠিক করে আবার জমা দিন।\n\nলোকটি দ্রুত বেরিয়ে গেল।\n\nআদ্রিয়ান ফাইলটা বন্ধ করতেই তার বিশ্বস্ত সহকারী রায়ান ঘরে প্রবেশ করল।\n\n—স্যার, আরিশা রহমান আজ বিশ্ববিদ্যালয়ে যাবে।\n\nআদ্রিয়ানের আঙুল থেমে গেল।\n\n—আমি কি তোমাকে ওর প্রতিদিনের রুটিন জানতে বলেছি?\n\nরায়ান শান্ত গলায় বলল,\n\n—না, স্যার। তবে আপনি গতকাল নিজেই ওর নিরাপত্তার বিষয়ে খোঁজ নিতে বলেছিলেন।\n\nআদ্রিয়ান কয়েক সেকেন্ড চুপ করে রইল।\n\n—ওর আশপাশে কোনো অপরিচিত লোক ঘোরাফেরা করছে কি না, খেয়াল রাখবে। কিন্তু ও যেন কিছু বুঝতে না পারে।\n\n—ঠিক আছে, স্যার।\n\nরায়ান বেরিয়ে যাওয়ার আগে একটু থেমে বলল,\n\n—স্যার, একটা কথা জিজ্ঞেস করব?\n\n—বলো।\n\n—আপনি কি সত্যিই ভাবছেন, অতীতটাকে আর কত দিন ওর কাছ থেকে লুকিয়ে রাখতে পারবেন?\n\nঘরের পরিবেশ মুহূর্তেই বদলে গেল।\n\nআদ্রিয়ান ধীরে ধীরে মুখ তুলল।\n\n—রায়ান।\n\n—জি, স্যার?\n\n—আমার অতীত নিয়ে দ্বিতীয়বার প্রশ্ন করার আগে ভেবে নেবে।\n\nরায়ান মাথা নিচু করল।\n\n—দুঃখিত, স্যার।\n\nদরজা বন্ধ হয়ে যেতেই আদ্রিয়ান চেয়ারে হেলান দিল।\n\nতার চোখের সামনে ভেসে উঠল বিশ বছর বয়সী এক মেয়ের মুখ—না, আরিশার মুখ নয়। বহু বছর আগের সেই রাতের স্মৃতি।\n\nএকটি বন্ধ দরজা। রক্তমাখা মেঝে নয়, বরং ছড়িয়ে থাকা কাগজপত্র। আতঙ্কিত কয়েকটি মুখ। আর তার বাবার শেষ কথাগুলো—\n\n“মির্জা পরিবারের ওপর বিশ্বাস করিস না, আদ্রিয়ান। সবাই যা দেখাচ্ছে, সত্যিটা তা নয়।”\n\nসেদিনের পর থেকে আদ্রিয়ান শিখেছিল, মানুষকে বিশ্বাস করার চেয়ে তাদের গোপন উদ্দেশ্য খুঁজে বের করা অনেক বেশি জরুরি।\n\nকিন্তু আরিশার ক্ষেত্রে সে নিয়মটা মানতে পারছিল না।\n\nমেয়েটা তার জীবনে আসার আগেই সে তাকে চিনত। অনেক দূর থেকে, অনেক বছর ধরে।\n\nআরিশা জানত না, তার হাসির আড়ালে কতগুলো অমীমাংসিত প্রশ্ন জমে আছে।\n\nআর আদ্রিয়ান জানত না, সত্যিটা প্রকাশ পেলে মেয়েটা তার চোখের দিকে তাকিয়ে আর কখনো বিশ্বাস করতে পারবে কি না।\n\n---\n\nবিশ্ববিদ্যালয়ের ক্যাম্পাসে ঢুকেই আরিশা বুঝতে পারল, আজ তার মন পড়াশোনায় বসবে না।\n\nতার বান্ধবী মেহরিন কাছে এসে বলল,\n\n—কী রে, মুখটা এমন শুকনো কেন? সকালে নাশতা করিসনি?\n\nআরিশা দীর্ঘশ্বাস ফেলল।\n\n—নাশতা করেছি। কিন্তু মাথার ভেতর একটা সমস্যা ঘুরছে।\n\n—কী সমস্যা?\n\n—এমন একজন মানুষকে নিয়ে, যাকে দেখলেই আমার রাগ হয়।\n\nমেহরিন চোখ বড় করে ফেলল।\n\n—ওহ! ব্যাপারটা তো সন্দেহজনক। মানুষটা কে?\n\n—একটা চলন্ত রাগের পাহাড়।\n\n—নাম বল!\n\n—আদ্রিয়ান মির্জা।\n\nমেহরিন কয়েক মুহূর্ত তাকিয়ে থেকে প্রায় চিৎকার করে উঠল,\n\n—কী! সেই আদ্রিয়ান মির্জা? যার ছবি দেখেই আমাদের ডিপার্টমেন্টের অর্ধেক মেয়ে পাগল?\n\nআরিশা বিরক্ত হয়ে বলল,\n\n—তো কী হয়েছে? দেখতে ভালো হলেই কি মানুষ ভালো হয়ে যায়?\n\n—তুই ওনাকে দেখেছিস?\n\n—দেখেছি। আর আমার মনে হয়েছে, লোকটার মুখে হাসি দেখার চেয়ে সূর্য পশ্চিম দিক থেকে ওঠা বেশি সম্ভব।\n\nমেহরিন হেসে ফেলল।\n\n—তুই সত্যিই অসাধারণ!\n\nআরিশাও হেসে উঠল। কিন্তু হাসিটা বেশিক্ষণ স্থায়ী হলো না।\n\nক্যাম্পাসের প্রধান ফটকের কাছে কালো রঙের একটি গাড়ি এসে থামল।\n\nগাড়ির ভেতরে বসে থাকা মানুষটিকে দেখামাত্র তার মুখের হাসি মিলিয়ে গেল।\n\nআদ্রিয়ান মির্জা!\n\nলোকটা এখানে কেন?\n\nআরিশা ভ্রু কুঁচকে তাকিয়ে রইল। গাড়ির দরজা খুলে আদ্রিয়ান নেমে এল। কালো পোশাক, দৃঢ় পদক্ষেপ, চোখেমুখে সেই চিরচেনা গাম্ভীর্য। আশপাশের কয়েকজন ছাত্রী ফিসফিস করে তার দিকে তাকাচ্ছিল।\n\nকিন্তু আদ্রিয়ানের দৃষ্টি ছিল শুধু একজনের দিকে।\n\nআরিশা রহমান।\n\nমেয়েটা দূর থেকে তাকিয়ে এমনভাবে ভ্রু কুঁচকে আছে, যেন সে এইমাত্র পৃথিবীর সবচেয়ে বিরক্তিকর মানুষটিকে দেখতে পেয়েছে।\n\nআদ্রিয়ানের ঠোঁটের কোণে অতি সামান্য হাসি ফুটে উঠল।\n\nমেয়েটার এই অভ্যাসটা তার ভীষণ পরিচিত।\n\nঅন্য সবাই তার সামনে কথা বলার আগে দশবার ভাবে। অথচ আরিশা তার দিকে তাকিয়েই যেন ঝগড়ার প্রস্তুতি নেয়।\n\nআর অদ্ভুত ব্যাপার হলো, আদ্রিয়ানের সেটা খারাপ লাগে না।\n\nবরং মেয়েটার এই সাহসটুকুই তাকে বারবার আরিশার দিকে টেনে নিয়ে যায়।\n\n---\n\n—আপনি এখানে কী করছেন?\n\nআরিশা সামনে এসে দাঁড়াতেই প্রশ্নটা ছুড়ে দিল।\n\nআদ্রিয়ান তার দিকে তাকাল।\n\n—কেন? এখানে আসতে হলে কি তোমার অনুমতি নিতে হবে?\n\n—না। তবে আমার পিছু নেওয়ার অভ্যাস থাকলে আগে থেকে বলে রাখবেন, আমি কিন্তু ভয় পাই না।\n\nআদ্রিয়ানের চোখে ক্ষীণ amusement ফুটে উঠল।\n\n—তুমি কি সবসময় এত বেশি কথা বলো?\n\n—আর আপনি কি সবসময় এত অহংকার নিয়ে চলেন?\n\nপাশ দিয়ে যাওয়া কয়েকজন শিক্ষার্থী থেমে গেল। একজন আরেকজনের দিকে তাকিয়ে মুচকি হাসল। এমন একজন মানুষের সঙ্গে এভাবে কথা বলার সাহস খুব কম লোকেরই আছে।\n\nআদ্রিয়ান এক পা এগিয়ে এল।\n\nআরিশা নিজের জায়গায় দাঁড়িয়ে রইল।\n\n—আমাকে ভয় পাও না?\n\n—কেন পাব? আপনি কি ভূত?\n\nআদ্রিয়ান কিছুক্ষণ তার মুখের দিকে তাকিয়ে থাকল। তারপর নিচু গলায় বলল,\n\n—তুমি জানো না, তুমি কাকে নিয়ে কথা বলছ।\n\nআরিশার হাসি মিলিয়ে গেল।\n\n—তাহলে চিনিয়ে দিন নিজেকে। তবে পরিচয় দেওয়ার সময় আপনার টাকার অঙ্কটা বলার প্রয়োজন নেই। মানুষ হিসেবে আপনি কেমন, সেটাই জানতে চাই।\n\nকথাটা শুনে আদ্রিয়ানের চোখের দৃষ্টি বদলে গেল।\n\nমেয়েটা জানে না, ঠিক এই প্রশ্নটার উত্তর সে নিজেও বহু বছর ধরে খুঁজছে।\n\nমানুষ হিসেবে সে কেমন?\n\nএকজন প্রতিশোধপরায়ণ মানুষ? একজন সফল ব্যবসায়ী? নাকি অতীতের কিছু ভুলের ভারে আটকে থাকা এমন একজন, যে নিজের সবচেয়ে প্রিয় মানুষটিকেও সত্যিটা বলতে ভয় পায়?\n\nআদ্রিয়ান কিছু বলল না।\n\nআরিশা বিরক্ত হয়ে বলল,\n\n—কী হলো? উত্তর নেই?\n\n—সব প্রশ্নের উত্তর সঙ্গে সঙ্গে দিতে নেই, আরিশা।\n\nনিজের নামটা তার মুখে শুনে আরিশা থমকে গেল।\n\n—আপনি আমার নাম জানেন কীভাবে?\n\nআদ্রিয়ান চোখ সরিয়ে নিল।\n\n—তোমার সম্পর্কে জানার মতো অনেক কিছুই আছে।\n\n—মানে?\n\n—সময় হলে বুঝবে।\n\n—আপনি সব কথা এভাবে ধাঁধার মতো বলেন কেন? সরাসরি কথা বলতে সমস্যা হয়?\n\nআদ্রিয়ান এবার তার দিকে পুরোপুরি ফিরে তাকাল।\n\n—তুমি যদি সব সত্যি জানতে পারো, তাহলে কি সেটা মেনে নিতে পারবে?\n\nআরিশার বুকের ভেতরটা কেঁপে উঠল।\n\nছবিটার কথা মনে পড়ল। বাবার সঙ্গে তার দাঁড়িয়ে থাকা সেই তরুণ ছেলেটি। আর ছবির পেছনের ভয়ংকর বাক্যটা।\n\nসে ধীরে ধীরে বলল,\n\n—সত্যিটা যত কঠিনই হোক, আমি জানতে চাই।\n\nআদ্রিয়ানের মুখ শক্ত হয়ে গেল।\n\n—তাহলে একটা কথা মনে রেখো। সব সত্যি জানার পর মানুষ আগের মতো থাকে না।\n\n—আমি বদলে যাওয়ার ভয় পাই না।\n\n—আমাকে ঘৃণা করতেও ভয় পাবে না?\n\nআরিশা তার চোখের দিকে তাকিয়ে রইল।\n\nকেন জানি না, প্রশ্নটার মধ্যে এমন কিছু ছিল, যা তার রাগকে মুহূর্তের জন্য থামিয়ে দিল।\n\nতবুও সে বলল,\n\n—ঘৃণা করার মতো কিছু করলে অবশ্যই করব।\n\nআদ্রিয়ান দীর্ঘক্ষণ তার দিকে তাকিয়ে থেকে মৃদু স্বরে বলল,\n\n—সেই দিনটা যেন কখনো না আসে।\n\nকথাটা বলে সে গাড়ির দিকে এগিয়ে গেল।\n\nআরিশা পেছন থেকে ডাকল,\n\n—শুনুন!\n\nআদ্রিয়ান থামল, কিন্তু ফিরে তাকাল না।\n\n—আমার বাবাকে আপনি চিনতেন?\n\nপ্রশ্নটা শুনে তার কাঁধ শক্ত হয়ে উঠল।\n\nকয়েক সেকেন্ড নীরবতা।\n\nতারপর আদ্রিয়ান ধীরে ধীরে বলল,\n\n—তোমার বাবার ব্যাপারে যা জানো, তার সবটাই সত্যি নয়।\n\nআরিশার মনে হলো, চারপাশের সব শব্দ হঠাৎ থেমে গেছে।\n\n—মানে কী?\n\nকিন্তু আদ্রিয়ান আর কোনো উত্তর দিল না। গাড়িতে উঠে চলে গেল।\n\nআরিশা স্থির হয়ে দাঁড়িয়ে রইল।\n\nতার মনে এখন একটাই প্রশ্ন—\n\nআদ্রিয়ান মির্জা তার বাবার অতীত সম্পর্কে কী জানে?\n\n---\n\nসন্ধ্যায় মির্জা ভিলার দোতলার একটি বন্ধ ঘরে বসে ছিল আদ্রিয়ান।\n\nঘরটিতে বহু বছর ধরে কেউ প্রবেশ করে না। দেয়ালে পুরোনো ছবি, কাঠের আলমারি আর একটি বিশাল ডেস্ক। ঘরের প্রতিটি জিনিস যেন অতীতের কোনো না কোনো সাক্ষী।\n\nআদ্রিয়ান ডেস্কের ড্রয়ার খুলে একটি পুরোনো খাম বের করল।\n\nখামের ভেতরে ছিল কয়েকটি চিঠি এবং একটি ছবি।\n\nছবিতে পাশাপাশি দাঁড়িয়ে আছেন দুজন মানুষ—আদ্রিয়ানের বাবা এবং আরিশার বাবা।\n\nতাদের মুখে হাসি।\n\nকিন্তু ছবির পেছনে লাল কালিতে লেখা কয়েকটি শব্দ আজও স্পষ্ট—\n\n“বিশ্বাসঘাতককে কখনো ক্ষমা করো না।”\n\nআদ্রিয়ান ছবিটা শক্ত করে ধরে রইল।\n\nঠিক তখনই দরজায় টোকা পড়ল।\n\n—ভেতরে আসো।\n\nরায়ান ঘরে প্রবেশ করল।\n\n—স্যার, আপনার নির্দেশমতো পুরোনো নথিগুলো খুঁজে পেয়েছি।\n\nআদ্রিয়ান ছবিটা নামিয়ে রাখল।\n\n—কিছু পেয়েছ?\n\n—জি, স্যার। আপনার বাবার মৃত্যুর আগের কয়েক মাসের কিছু নথি পাওয়া গেছে। কিন্তু একটা সমস্যা আছে।\n\n—কী সমস্যা?\n\nরায়ান একটি ফাইল এগিয়ে দিল।\n\n—এই নথিগুলোর কয়েকটি থেকে গুরুত্বপূর্ণ পৃষ্ঠা সরিয়ে ফেলা হয়েছে। আর যেসব কাগজ অবশিষ্ট আছে, সেখানে রহমান পরিবারের নাম একাধিকবার এসেছে।\n\nআদ্রিয়ানের চোখ সরু হয়ে এল।\n\n—কেউ ইচ্ছা করে প্রমাণ মুছে দিয়েছে।\n\n—আমারও তাই মনে হচ্ছে, স্যার।\n\nআদ্রিয়ান কিছুক্ষণ চুপ করে রইল। তারপর বলল,\n\n—এই ব্যাপারে কেউ যেন কিছু জানতে না পারে। বিশেষ করে আরিশা।\n\nরায়ান দ্বিধা নিয়ে বলল,\n\n—স্যার, আরিশা ম্যাডাম যদি নিজেই সত্যিটা খুঁজতে শুরু করেন?\n\nআদ্রিয়ান জানালার বাইরে তাকাল।\n\n—তাহলে তাকে থামানোর চেষ্টা করবে না।\n\nরায়ান অবাক হয়ে তাকাল।\n\n—কিন্তু স্যার...\n\n—আমি বলেছি, তাকে থামাবে না।\n\nতার কণ্ঠে এমন এক দৃঢ়তা ছিল, যার পরে আর কোনো প্রশ্নের সুযোগ রইল না।\n\nরায়ান বেরিয়ে গেলে আদ্রিয়ান আবার ছবিটা হাতে তুলে নিল।\n\n—আমি তোমাকে হারাতে পারব না, আরিশা, সে মনে মনে বলল। —কিন্তু তোমাকে সত্যিটা বলার সাহসও আমার নেই।\n\nতার চোখে জমে থাকা কঠোরতার আড়ালে লুকিয়ে ছিল এক অদ্ভুত অসহায়ত্ব।\n\nযে মেয়েটিকে সে বহু বছর ধরে আড়াল থেকে আগলে রেখেছে, একদিন সেই মেয়েটিই হয়তো তার সবচেয়ে বড় শত্রু হয়ে দাঁড়াবে।\n\nআর সেই দিনের কথা ভেবেই আদ্রিয়ানের বুকের ভেতরটা অজানা আশঙ্কায় ভারী হয়ে উঠল।\n\n---\n\nঅন্যদিকে, নিজের ঘরে বসে আরিশা ব্যাগ থেকে ছবিটা বের করল।\n\nআজকের কথাগুলো তার মাথা থেকে সরছিল না।\n\n“তোমার বাবার ব্যাপারে যা জানো, তার সবটাই সত্যি নয়।”\n\nকথাটার অর্থ কী?\n\nতার বাবা কি কোনো গোপন সত্য লুকিয়ে রেখেছিলেন? আর আদ্রিয়ান কেন সেই সত্যের সঙ্গে জড়িয়ে আছে?\n\nহঠাৎ তার ফোনে একটি অচেনা নম্বর থেকে বার্তা এল।\n\n“আদ্রিয়ান মির্জাকে বিশ্বাস করবেন না। আপনার বাবার মৃত্যুর রহস্য জানতে চাইলে পুরোনো মির্জা ভিলার বন্ধ ঘরটির খোঁজ করুন।”\n\nআরিশার আঙুল ঠান্ডা হয়ে এল।\n\nকয়েক সেকেন্ড পর আরেকটি বার্তা এল।\n\n“তবে সাবধান। ওই ঘরের দরজা খুললে আপনার জীবন আগের মতো থাকবে না।”\n\nআরিশা ধীরে ধীরে ফোনটা নামিয়ে রাখল।\n\nতার চোখে এবার ভয় নয়, দৃঢ়তা।\n\n—যে রহস্যই থাকুক, আমি সত্যিটা জানব।\n\nজানালার বাইরে তখন রাত নেমে এসেছে।\n\nআর শহরের অন্য প্রান্তে, মির্জা ভিলার বন্ধ ঘরটির সামনে দাঁড়িয়ে আদ্রিয়ানও একই ছবির দিকে তাকিয়ে ছিল।\n\nদুজন মানুষ।\n\nদুটি পরিবার।\n\nআর এমন এক অতীত, যা তাদের একে অপরের কাছে টেনে আনছে—আবার একই সঙ্গে দূরে সরিয়ে দেওয়ার ষড়যন্ত্রও করছে।\n\nকিন্তু তারা কেউই জানত না, তাদের জীবনের সবচেয়ে বড় রহস্যের উত্তর লুকিয়ে আছে সেই বন্ধ দরজার ওপাশে।\n\nচলবে...🥀🖤','\n',char(10)),3,'published',0,'2026-10-29 02:39:37','2026-10-29 02:39:37',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('8e5e1c81-2950-44e1-b00e-ea5f45a2a253','c4b7dd5c-d4f0-4324-af5f-725d78c6fd88','পর্ব-১',replace('মা আমার মাহি কে বলো চোখ খুলতে বলো মা বলো ও কী ভাবে আমাকে রেখে যাওয়ার সীদ্ধান্ত নিলো ওর এতো সাহস কথা থেকে আসে আমি আরহান মির্জা বেঁচে থাকা অবস্থায় ও কখনো আমাকে রেখে যেতে পারে না মাহি চোখ খোল বউ আমার এই বলে ইহান হাউ মাউ করে কান্না করতে থাকে..\n\n__এ দেখে আরহান মির্জার মা আফরিন বেগম কান্নায় ভেঙ্গে পড়েন, তিনি আরহান কে কখনো দেখেননি এ ভাবে কান্না করতে তার ছেলে এতো কঠিন সময় এ-ও কখনোই এ ভাবে ভেঙ্গে পড়ে নি কিন্তু আজ তার ছেলে কে এতো-টা অসহায় হয়ে পড়ে দেখে আফরিন বেগম-এর  বুক পেটে কান্না আসে\n\n.......................\n\nআরহান মির্জা; আফরিন বেগম - আলতাফ মির্জার বড়ো ছেলে এবং বাড়ির বড় ছেলে হওয়ায় পরিবারের সবার আদরের কিন্তু তার  স্বভাব ছিলো ভীষণ রাগী তার সিদ্ধান্ত সবাই এক কথায় মেনে নেয় বাড়ির ছোট-রা থাকে ভীষণ ভয় পেত...\n\n আজ ৬ বছর পর মির্জা বাড়ির বড়ো ছেলে বাড়িতে পা রাখছে এতে সবাই অনেক খুশি সবাই সবার মতো কাজ করছে ছোট্ট চাচি পপি বেগম আর মেজো চাচি ফারজানা বেগম রান্নার কাজে ব্যস্ত আফরিন বেগম নিজের ছেলে আসার খুশিতে ছেলের গড় ঘুচাতে ব্যস্ত \n\n\n---বড় মা ভাই কেনো এতো বছর দেশে আসেনি...?\n\nআহনাফ এর এমন প্রশ্ন শোনে আফরিন বেগম এ-র মুখের হাসি  ক্ষণিক এর সময় এর জন্য চলে যায় তিনি কথা ঘুরিয়ে বলেন..\n\n শুনো বাবা এটা অনেক লম্বা কাহিনি তোমাকে অন্য এক দিন বলবো যাও এখন তোমার আয়রা আপু কে ডেকে নিয়ে আসো\n\n\nআহনাফ আবার আসলো \n\nবড় মা আপুমণি-কে অনেক ডেকেছি আপুমণি ঘুমাচ্ছে \nআপু বলছে আরেক বার ডাকলে আমার মাথা কে*টে রেখে দিবে..\n\nএই মেয়েটা কে নিয়ে আর পারি না\n\nতিনি আয়রা কে ডাকার জন্য চলে যান \n\nনিছ থেকে আওয়াজ আসছে \n\nবড় মা ছোট মা মেজো মা বাবা কে কোথায় আছো দেখে যাও ভাইয়া আসছে \n\nসবাই বসার গড়ে এসে দেখে ইহান ওরফে আরহান মির্জা চলে এসেছে \n\nআফরিন বেগম ছেলেকে দেখে কান্না শুরু করে দেন এটা দেখে আলতাফ মির্জা বলেন\n\n---ওই শুরু হয়ে গেলো আমার গিন্নি কান্না বলি ছেলে টা বাড়িতে শুধু আসেছে আরহান কে ওর গড়ে নিয়ে যাও\nআরহান গড়ে আসে এসে দেখে ৬ বছর আগে যেমন রেখেছিলো ঠিক তেমনি রয়েছে \n.......\n\nশাওয়ার নিয়ে এসে শুধু বিছানায় বসেছে আহনাফ এবং আশরাফ আসে \n\n---ভাইয়া একটা কথা বলি...? \n\n---হুম \n\n---আমাদের জন্য কী আনেছো...? \n\n--- কী আনবো তদের জন্য...? \n\n---কিছু আনো নাই ভাইয়া..?\n\nআরহান ঠোঁট বেঁকিয়ে হাসে \n\n---আরে আমার যে দুই-টা রামছাগল আছে ও-ই টা কী ভাবে ভুলে যাবো বল..?\n\nআহনাফ এবং আশরাফ এক সাথে বলে উঠে\n\n---ভাইয়া আমরা রামছাগল না আমাদের গিফট গুলো দাও আমরা চলে যাচ্ছি \n\nআরহান তাঁদের একটা লাগেজ দেখিয়ে দেয়\n\nআশরাফ এবং আহনাফ চলে যাওয়ার পর আরহান মনে মনে ভাবছে\n\n---৬ বছর আগের কাহিনী এখন আবার পুনরাবৃত্তি হবে ফুফি আর সেটা আপনার মেয়েকে দিয়েই হবে....\n\n.....\n\n\n পাখিরা সামনে কী যাবো....?','\n',char(10)),1,'published',0,'2026-10-29 04:32:54','2026-10-29 11:15:04',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('8ea11586-941c-4ee3-91e9-e4227b04cccd','aca31ba8-956d-4587-8c86-eec72cc2d6be','পর্ব:২',replace('#অপূর্ণতায় তুমি \n\n#সিয়াম হোসেন\n\n#পর্ব:২\n\nঘড়ি কাটা রাত তখন ৭ টার ঘরে । আদনান গ্রামের পথ ধরে হাটছে। কলেজের মাঠ থেকে বেরিয়েছে অনেকক্ষণ আগে। এতক্ষণ বন্ধুদের সাথে আড্ডা দিচ্ছিলো। এখন বাড়িতে যাচ্ছে। রাস্তা দিয়ে হাটার সময় দেখে বাবু মিয়ার বাড়ি থেকে কান্নাকাটির আওয়াজ পাওয়া যাচ্ছে। আর বাবু মিয়া কারো উপর চিৎকার চেচামেচি করে কাউকে বিশ্রী ভাষায় গালিগালাজ করছে। আদনান সেরকম ওদিকে মন না দিয়ে বাড়ির দিকে দিয়ে যাচ্ছিল। আর মনে মনে  বললো,\n\n- এই বাবুমিয়া আবার কাকে এত খারাপ ভাবে গালি দিতাছে। আর এত কান্নাকাটিই বা কে করে।  \n\nবাবু মিয়ার বাড়ির সামনে দিয়ে যাওয়ার সময় বাড়ি থেকে বাবুমিয়ার ছোট ৯ বছরের মেয়ে শিউলি দৌড়াচ্ছে আর আদনানকে ডাকছে।\n\n-আদনান ভাই! ও আদনান ভাই!\n\nশিউলির ডাক শুনে আদনান একটু থামলো।  শিউলিকে দেখে মনে হচ্ছে কিছু একটা নিয়ে ভয়ে আছে।শিউলির এ অবস্থা দেখে কৌতুহল হয়ে জিজ্ঞেস করলো,\n\n- কিরে ডাকতাছোস কে কি হইছে? আর তোদের বাড়িতে এত কান্নাকাটি করে কে? তোর আব্বাই বা কাকে ওরকমভাবে গালি দিতাছে?\n\nশিউলি দৌড়ে এসে আদনানকে ধরে হাপাতে শুরু করে। আদনান শিউলিকে ধাতস্থ করে বলে, \n\n- এত দৌড়চ্ছিস কেন? দাড়া একটু দম নে তারপড় বল কি হয়েছে।\n\nশিউলি কিছুক্ষণ দম নিয়ে কান্না জোরানো কন্ঠে আদনানকে বলে,\n\n- আদনান ভাই আমার মারে বাচাও তুমি আমার মা রে বাচাও। আব্বা আমার মারে মাইরা শেষ করে ফালাইতাছে গো আদনান ভাই। তুমি আমার মারে বাচাও।\n\nশিউলির কথা শুনে আদনান স্তব্ধ হয়ে গেলো। এতক্ষনে বুঝতে পারলো বাবুমিয়া কাকে গালিগালাজ করতেছে। আর এত কান্নাকাটিই বা কে করতেছে। আদনান আর কিছু না ভেবে দৌড়ে গেলো শিউলিদের বাড়িতে।  গিয়ে দেখে বাবুমিয়া মোটা একটা গাছের ফালি দিয়ে শিউলির মা হালিমাকে উত্তম মধ্যম পেটাচ্ছে। আদনান দারিয়ে না থেকে বাবুমিয়ার কাছ থেকে গাছের ফালি টা নিয়ে নিলো।  বাবুমিয়া হত্বভম্ব হয়ে আদনানের দিকে তাকিয়ে রইলো। যেন বাবুমিয়া আদনানকে এখানে আশা করেননি। বাবুমিয়া থেমে যেতেই শিউলি দৌড়ে হালিমার কাছে গিয়ে হালিমাকে জরিয়ে ধরে কান্না করে দিলো। আদনান বাবুমিয়াকে কিছু বলবে তার আগেই শিউলি আদনানকে ডাকতে লাগলো। শিউলির ডাকে আদনান হালিমা আর শিউলির দিকে তাকালো। শিউলি কান্না করতে করতেই আদনানকে বললো,\n\n- আদনান ভাই দেখো আমার মা কথা কয় না কে? কি হইলো মায়ের দেখো না তুমি মা কথা কয় না কে?  কি হলো আদনান ভাই আইসা দেখো না।  \n\nশিউলি হালিমাকে জরে জরে ঝাঁকাচ্ছে কিন্তু হালিমা কিছুই বলছে না। হালিমার মাথা দিয়ে বাধ ভাঙ্গা নদীর মতো তাজা রক্ত নির্গত হচ্ছে। হাত পা ক্ষতবিক্ষত। অনেক স্থান থেকে মাংস গাছের ফালির সাথে উঠে এসেছে। এতটা নৃশংস ভাবেই না মেড়েছে হালিমাকে। আদনান হালিমার কাছে গিয়ে হালিমার নাকের কাছে গিয়ে আঙ্গুল ধরলো শ্বাস চলছে কিনা বোঝার জন্য। কিন্তু কোনো রকম শ্বাস চলছে না হালিমার। আদনান যা ভাবছে তাই যেন না হয়। কিন্তু আদনান এখনও নিশ্চিত হতে পারছে না হালিমা বেচে আছে কি মারা গেছে। তাই জলদি শিউলিকে বললো রাস্তায় গিয়ে গাড়ি থামাতে। হালিমাকে এক্ষুনি হাসপাতালে নিতে হবে। মোহনগঞ্জ থানায় একটি মাত্র সদর হাসপাতাল আছে। তাছাড়া আর কোনো চিকিৎসার ব্যবস্থা নেই। শিউলিদের গ্রাম থেকে প্রায় ১২ কিলো মিটার দুরে মোহনগঞ্জ সদর হাসপাতাল।  এতরাতে ওত দুরের পথের জন্য গাড়ি পাওয়া অসম্ভব বললেই চলে। শিউলি দৌড়ে রাস্তায় আসলো গাড়ির জন্য। কিন্তু কোনো গাড়িই ওত রাতে ওত দুর যাওয়ার জন্য রাজি হলো না। শিউলি কি করবে কিছু বুঝতে না পেড়ে আবার বাড়ি পিরে গেল। বাড়ি গিয়ে শিউলি কান্না করতে করতে আদনান কে বললো,-\n\n- আদনান ভাই রাস্তায় একটাও গাড়ি পাইলাম না।  কোনো গাড়িই হাসপাতালে যাওয়ার লাইগা রাজি হইলো না৷ এহন আমার মার কি হইবো আদনান ভাই?\n\nআদনান শিউলি কি বলবে কিছুই ওর মাথায় এলো না।  তখনই মনে পড়লো জব্বার চাচার কাছে তো গাড়ি আছে।  ওই গাড়িতে করে হালিমাকে নিয়ে যাওয়া যাবে হাসপাতালে। যেই ভাবা সেই কাজ আর একটুও সময় নষ্ট না করে জলদি জব্বার চাচার বাড়িতে গেলো। বাড়িতে গিয়ে জব্বার চাচাকে হাপাতে হাপাতে ডাকছে,\n\n-জব্বার চাচা ও জব্বার চাচা বাড়ি আসো? তাড়াতাড়ি বাহিরে আসো।  জব্বার চাচা! \n\nআদনানের ডাকে জব্বার চাচা ঘর থেকে বেরিয়ে বিরক্তি স্বরে বললেন,\n\n- কেডা রাত বিরাইতে এমন ডাকতাছে? \n\nআদনান জবাব দিলো,\n\n- আমি জব্বার চাচা আদনান তাড়াতাড়ি বাহিরে আসো জরুরি কাজ আছে।\n\nজব্বার চাচা ঘর থেকে বেরিয়ে আদনান কে বললো,\n\n-আরে তুুমি এত রাইতে আমার বাড়িত আইসো কে কি হইছে? \n\nআদনান জলদি বলা শুরু করলো,\n\n- বাবুমিয়া তার বউ কে মেরে একদম আধমরা করে ফেলেসে। তার নিশ্বাস চলছে না। তাড়াতাড়ি হাসপাতালে না নিলে অনেক বড় ক্ষতি হয়ে যেতে পারে। এত রাতে রাস্তায় কোনো গাড়িও পাচ্চি না হাসপাতালে যাওয়ার জন্য। তাই তুমার কাছো আসলাম তুমি তুমার গাড়ি টা নিয়ে তাড়াতাড়ি চলো। হালিমা চাচিকে এখনই হাসপাতালে না নিলে যে সে মারাও যেতে পারে। \n\nআদনানের কথা শুনে জব্বার তাড়াতাড়ি গাড়ি বের করে শিউলিদের বাড়ি সামনে আসলো।  আদনানও দেরি করলো না তাড়াতাড়ি বাড়িতে ডুকে হালিমাকে নিয়ে আসবে তখনই বাবুমিয়া আদনানের পথ আটকে দারায়। আর রাগে কট মট করতে করতে বলে, \n\n- এই খাড়া আদনান! কই নিয়া যাস তুই হালিমারে?  বেশি পিরিত দেখাও তাই না।  এত পিরিত ভালা না। যা ওরে ঘরে থুইয়া আয় সকালে কবিরাজ রে খবর দিমুনি আইসা কিছু অষুধ দিবো ঠিক হইয়া যাইবো।\n\nবাবুমিয়ার কথা শুনে আদনান কি বলবে কিছু বুজে পায় না। একটা মানুষ কিভাবে এতটা নিষ্ঠুর হতে পারে আদনানের জানা নেই। তখনই জব্বার চাচা এসে বাবুমিয়ার কোমর বরাবর দিলো এক লাথি।  লাথিটা এতো জরে লেগেছে যে বাবু মিয়া জোক সামলাতে না পেরে মাটিরে মুখ থুবরে পরে যায়। বাবুমিয়া মাটিতেই পরে থাকা অবস্থায় জব্বার আরো কয়টা লাথি দিয়ে আদনানকে আর হালিমাকে নিয়ে গাড়িতে গিয়ে বসে। শিউলিও আসতে চেয়েছিল কিন্তু রাত বেশি হওয়ার জন্য আর নিয়ে যাই নি। ওকে পাশের বাসার সামিয়ার মার কাছে রেখে গেছে। জব্বার চাচা তাড়াতাড়ি গাড়ি চালিয়ে হাসপাতালে নিয়ে আসে হালিমাকে।  হাসপাতালে এসে আদনান ডাক্তারকে খোজতে যায়। ডাক্তার কে খুজে তাকে সব খুলে বলে। ডাক্তার এসে হালিমাকে দেখে। কিন্তু ততক্ষনে অনেক দেরি হয়ে যায় হালিমা তো অনেক আগেই সবাই কে ছেড়ে চলে গেছে। শুধু রেখে গেছে ফুলের মতো ছোট মেয়েটাকে। ডাক্তার হালিমাকে মৃত ঘোষনা করে। \n\n- আমি দুঃখীত! তিনি তো অনেক আগেই মারা গিয়েছে!\n\nআদনান আর জব্বার চাচার যেন মাথা ঘুরে যায়। কি করবে এখন তাড়া?  কি জবাব দিবে শিউলি কে?  ওই ছোট মেয়ে কিভাবে থাকবে তার মাকে ছাড়া এই নির্দয় নিষ্ঠুর পৃথিবীতে? এই সব ভাবতে ভাবতে তারা শিউলিদের বাড়ি সামনে চলে আসে। ততক্ষণে রাত প্রায় শেষের দিকে।গাড়ির শব্দ শুনে শিউলি ছুুটে এসে আদনান কে জিজ্ঞেস করলো,\n\n- আদনান ভাই আমার মা কেমন আছে? ভালো হইয়া গেছে না আমার মা? কই মা কই?  মা কই তুমি? \n\nশিউলির উৎসাহ দেখে আদনান বুঝে উঠতে পারছে না কিভাবে শিউলি কে বলবে যে ওর মা আর এই পৃথিবীতে নেই। অনেক কসরত করে ভেতরের আবেগটুকু দমন করে শিউলি কে কাছে আনলো। শিউলির চোখ মুখ দেখেই বোঝা যাচ্ছে সারারাত ঘুমায়নি মেয়েটা। আদনান শিউলিকে নিজের কাছে এনে অতি যত্ন সহকারে বোঝানো চেষ্টা করে বললো,\n\n- দেখ শিউলি মানুষ চিরকাল আমাদের মাঝে থাকে না।কোনো না কোনো দিন তাকে এই পৃথিবীর সব কিছু ফেলে আল্লাহর কাছে চলে যেতে হয়। এই পৃথিবী আমাদের আসল ঠিকানা না।  \n\nআদনানের কথা শিউলি আগা মাথা কিছুই বুঝতে পারছে না। অবুঝের মতো শিউলি আদনানকে জিজ্ঞেস করলো,\n\n- তুমার কি হইছে আদনান ভাই? আমারে তুমি এগুলা কি বলতাছো? আমি কিছুই বুঝতাছি না। আর আমার মা কই?  সেটা আগে বলো। \n\nআদনান শান্ত গলায় উত্তর দিল,\n\n- তোর মা আর এই পৃথিবীতে নেই রে। সে অনেক দুর চলে গেছে। অনেক অনেক দুর যেখানে চলে গেলে আর কখনও কেউ ফিরে আসে না। \n\nশিউলির মাথায় যেন আকাশ ভেঙে পড়লো। এটা কি বললো ওকে আদনান। ওর এখনও কিছু বিশ্বাস হচ্ছে না। মনে হচ্চে সব সপ্ন।আর এখনই সপ্ন ভেঙে যাবে আর ওর মা ওর সামনে এসে ওকে আদর করবে। কিন্তু এগুলো কিছুই হলো না।ওর মা আসলেই আর নেই। ওকে রেখে চলে গেছে অনেক দুর।  একটাবারও ভাবলো না শিউলির কি হবে?  ছোট মেয়েটাকে পুরো পৃথিবীতে একা ফেলে পালিয়ে গিয়েছে ওর মা। মা-রা কি এত নিষ্ঠুর হতে পারে? হয়তো পারে তাইতো শিউলির মা ওকে ছেড়ে চলে গেছে। \n\n*********\n\nজমিদার বাড়ির সদর দরজার সামনে দারিয়ে আছে নীলা। সামনে সালমা এসে দরজা খুললো। নীলাকে দেখা মাত্রই সালমার রাগ আকাশ ছুয়ে গেলো৷ রাগে কট মট করতে করতে বললেন,\n\n-এতক্ষনে তোর বাড়ি ফেরার সময় হয়েছে? কোথায় ছিলি এতক্ষন? রাত কয়টা বাজে সে হিসেব আছে তোর? কি হলো মুখে কুলুপ এটে আছিস কেন কিছ জিজ্ঞেস করছি তো আমি।  উত্তর দে। \n\nনীলা কিছু বলবে তার আগেই মাহবুবুর সালমা কে বিরক্তি নিয়ে বললেন,\n\n- আচ্ছা তুমার কি একটুও জ্ঞান নেই? মেয়েটা সবে মাত্র বাড়িতে ফিরেছে। অন্তত ভেতরে তো আসতে দিবে তার আগেই ওর উপর চিল্লাচিল্লি করছো। আয় তো মা ভেতরে আয়। \n\nমাহবুবুরের কথা শুনে এবার জোহরা বেগমও রেগে গেলেন। ছেলের উপর বিরক্ত হয়ে রাগি স্বরে বললেন, \n\n- মেয়েকে এত আশকারা দিস না রে মাহবুব। মেয়ে লোক কে বেশি মাথায় তুলতে নেই।  যখন এই মেয়ে মুখে চুন কালি লাগাবে তখন বুঝবি। \n\nদাদির কথা শুনে নীলার মুখটা ছোট হয়ে এলো। অবশ্য এটা নতুন কিছু না। জোহরা সবসময়ই উঠতে বসতে নীলাকে কথা শোনায়।  নীলাঞ্জনার যেন কোনো কাজই জোহরা বেগমের ভালো লাগে না।কিন্তু কেন এমন করে সেটা জানা নেই নীলার। আচ্ছা নীলা মেয়ে বলে তো আবার এমন ব্যবহার করেন না জোহরা বেগম? নাকি অন্যকোনো কারন আছে? মাঝেমাঝে খুব অভিমান হয় দাদির উপর। সবার দাদি তাদের নাতনিকে কত ভালোবাসে স্নেহ করে। কিন্তু নীলার ভাগ্যে সেই ভালোবাসা, স্নেহ কেন নেই। এসব ভাবনার সুতো ছিরে গেলো সালমা বেগমের কর্কশ স্বরে। সালমা বেগম কখন থেকে নীলাকে জিজ্ঞেস করছো এতক্ষণ নীলা কই ছিলাে কিন্তু নীলার মুখে কোনো কথা নেই। যার ফলে সালমা আরো বেশি তেতে উঠছেন। এবার আর সালমা বেগম না সয়ং মাহবুবুর নিজে নীলাকে কাছে টেনে বসিয়ে শান্ত স্বরে জিজ্ঞেস করলো, \n\n- আমাকে বলবি তো মা কোথায় ছিলি তুই এতক্ষণ। আমি জানি আমার মেয়ে কোনো খারাপ কাজ করবে না এই বিশ্বাস আছে তোর উপর। কিন্তু বুঝিসই তো বাবা মা তোকে নিয়ে বড্ড চিন্তা করি। তোর কিছু হলে আমাদের কি হবে বল। তাই জিজ্ঞেস করছি কই ছিলি? কোনো বিপদ হয়েছিলো?\n\nনীলা মাথা নেড়ে না জানালো। মানে কোনো বিপদ হয় নি। মাহবুবুর আবার জিজ্ঞেস করলো,\n\n- তাহলে যে এত দেরি হলো যে। \n\nনীলা এবার বলা শুরু করলো।  মাথাটা মাটির দিকে নিবদ্ধ করে নরম স্বরে বললো,\n\n- আসলে আজকে একটু পুরোনো জমিদার বাড়ি গিয়েছিলাম।\n\nব্যস এতটুকু শোনা মাত্রই সালমা বেগম জোরে একটা চপেটাঘাত বসিয়ে দিলেন নীলার নরম কাতর গালে। নীলা কৃষ্ণবর্নের হওয়ার গালের লাল দাগ টুকু দেখা গেলো না।  কিন্তু চর টা কত জোরে লেগেছে সেটা একমাত্র নীলাই জানে। সালমা বেগম রাগ যেন আজ বেড়েই চলেছে। দাতে দাত পিষে নীলাকে বললো,\n\n- এই তুই কি আমাদের কথা শুনবি না কখনও? তোকে কতবার না করেছি ওই বাড়িতে না যেতে তারপড়ও কেন তুই বারবার ওই বাড়িতে যাস? কেন বল।\n\nনীলার চোখ দিয়ে বাধহীন ভাবে জল পড়ছে। তবুও নীলা সালমা বেগম কে জিজ্ঞেস করল\n\n- কেন মা কি আছে ওই বাড়িতে? কেন আমাকে যেতে মানা করো তুমি? ওই বাড়ির লোকজন তো কত ভালো। আমাকে কত যত্ন করলো। তাহলে কেন তুমি ওই বাড়িতে যেতে মানা করো?\n\nএবার আর সালমা কিছু বললো না মাহবুবুর রহমানই মেয়ে বোঝানোর জন্য নীলার সামনে এসে বসলো। চোখের পানিটুকু স্বযত্নে মুছে নীলা বোঝালো প্রযাসে বললো,\n\n- দেখ মা আমরা সব সময় যা দেখি যা শুনি সেটা সত্যি হয় না। মানুষের ভালো ব্যবহারের আড়ালে লুকিয়ে থাকে একন ভয়ানক সত্য। যা অন্য মানুষের জীবনকে শেষ করে দিতে পারে। তাই সবসময় যা দেখবি সেটা বিশ্বাস করবি না। বুজতে পেরেছিস?  \n\nনীলা মাথা নাড়িয়ে সম্মতি জানালো। কিন্তু এখন নীলার মনে আরো বেশি কৌতুহল জাগলো কি আছে ওই বাড়িতে? ওই লোকজনই বা কেমন? তারা কি আসলে ভালো?  নাকি বাবার কথার মতো তারা ভালো মানুষের মুখোশ পড়ে থাকে?\n\nচলবে.........৷','\n',char(10)),2,'published',0,'2026-10-29 06:47:01','2026-10-29 06:47:01',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('db00433b-a95f-4721-9166-6d86ea68519c','b98c6429-e76f-4896-8621-fd2d226b335c','পর্ব:০১',replace('#মাফিয়া কিংয়ের পাগল করা ভালোবাসা \n#লেখিকা: কল্পনার গল্পকন্যা\n#পর্ব: ০১\n\nরাত ১১টা ৫৫ মিনিট। শহরের সবচেয়ে বিলাসবহুল হোটেলের সামনে একের পর এক কালো গাড়ি এসে থামল। কালো স্যুট পরা দেহরক্ষীদের মাঝখান দিয়ে নেমে এল এক সুদর্শন পুরুষ। চোখে কালো চশমা, মুখে কঠিন অভিব্যক্তি। তার প্রতিটি পদক্ষেপে যেন লুকিয়ে আছে ক্ষমতা আর ভয়।\n\nসে আর কেউ নয়, আরহান খান। বয়স ২৮ বছর। শহরের সবচেয়ে ভয়ংকর মাফিয়া কিং।\n\nযার নাম শুনলে শত্রুদের বুক কেঁপে ওঠে। ভালোবাসা নামক অনুভূতিকে সে বহু বছর আগেই নিজের জীবন থেকে মুছে ফেলেছে।\n\nআরহানের ব্যক্তিগত সহকারী রায়ান এগিয়ে এসে বলল,\n\n“স্যার, মাহবুব রহমান আজকের অনুষ্ঠানে উপস্থিত আছেন।”\n\nকথাটা শুনে আরহানের চোখে জ্বলে উঠল ঘৃণা।\n\n“মাহবুব রহমান! অবশেষে সময় এসেছে তার কাছ থেকে সব হিসাব বুঝে নেওয়ার।”\n\nরায়ান ইতস্তত করে বলল, “স্যার, মাহবুব সাহেবের মেয়ে নীলাঞ্জনা রহমানও আজ এখানে এসেছে।”\n\nআরহানের ঠোঁটে রহস্যময় হাসি ফুটে উঠল।\n\n“তাহলে খেলাটা আরও আকর্ষণীয় হবে। মেয়েটার সম্পর্কে সব তথ্য চাই আমার।”\n\nঅন্যদিকে—\n\nগোলাপি শাড়ি পরে হোটেলের ভেতরে দাঁড়িয়ে আছে ২২ বছর বয়সী নীলাঞ্জনা রহমান। মিষ্টি মুখ, উজ্জ্বল চোখ আর চঞ্চল স্বভাবের মেয়েটিকে সবাই নীলা বলে ডাকে।\n\nনীলা তার বড় ভাই নাহিয়ানের দিকে তাকিয়ে বলল,\n\n“ভাইয়া, আমাকে এখানে এনে একা ফেলে কোথায় চলে গেলে? আমি কিন্তু বাসায় চলে যাব!”\n\n২৬ বছর বয়সী নাহিয়ান হেসে বলল, “এই তো আমার ছোট্ট বোনের ধৈর্য! একটু দাঁড়া, আসছি।”\n\n“তোমার এই একটু দাঁড়া আর শেষ হয় না! বিয়ে করলে বউকেও এভাবে ফেলে রাখবে?”\n\n“আগে নিজের বিয়ের চিন্তা কর, তারপর আমার বউয়ের চিন্তা করিস।”\n\nনীলা নাক উঁচু করে বলল, “আমি এমন কাউকে বিয়ে করব, যে আমার সব কথা শুনবে!”\n\nনাহিয়ান হেসে বলল, “তাহলে তো তোর বিয়ে কোনো দিনই হবে না!”\n\n“ভাইয়াআআ!”\n\nনীলার চিৎকার শুনে হাসতে হাসতে চলে গেল নাহিয়ান।\n\nমুখ ফুলিয়ে দাঁড়িয়ে থাকার সময় হঠাৎ পেছন ফিরে একজনের সঙ্গে ধাক্কা খেল নীলা। তার হাতের জুস গিয়ে পড়ল সামনের মানুষটির সাদা শার্টে।\n\nনীলা মাথা তুলে তাকাতেই থমকে গেল।\n\nসামনে দাঁড়িয়ে থাকা লোকটির চোখে তখন আগুন জ্বলছে।\n\n“চোখ কোথায় তোমার?” গম্ভীর কণ্ঠে প্রশ্ন করল আরহান।\n\nনীলা একটু ভয় পেলেও পরক্ষণেই নিজেকে সামলে নিল।\n\n“চোখ তো মাথাতেই আছে! আপনি কি দেখেননি যে আমি পেছনে ছিলাম?”\n\nআরহান অবিশ্বাসের দৃষ্টিতে তাকাল।\n\n“কী বললে তুমি?”\n\nনীলা কোমরে হাত দিয়ে বলল, “কানে কম শোনেন নাকি? একবার বলেছি তো!”\n\nচারপাশের মানুষ অবাক হয়ে তাকিয়ে রইল। আরহান খানের সামনে দাঁড়িয়ে এভাবে কথা বলার সাহস কারও নেই!\n\nআরহান ধীর পায়ে এগিয়ে এসে বলল,\n\n“তুমি জানো, আমি কে?”\n\n“না। জানার ইচ্ছাও নেই। এবার আমাকে যেতে দিন।”\n\nনীলা চলে যেতে উদ্যত হলে আরহান তার দিকে তাকিয়ে রইল। মেয়েটির চোখ দুটো দেখে তার মনে হলো, এই চোখ সে কোথাও দেখেছে। বহু বছর আগে ঘটে যাওয়া এক ভয়ংকর ঘটনার স্মৃতি হঠাৎ তার মনে ভেসে উঠল।\n\n“তোমার নাম কী?” আরহান জিজ্ঞেস করল।\n\nনীলা মুচকি হেসে বলল, “নীলাঞ্জনা রহমান। কেন, বিয়ের প্রস্তাব পাঠাবেন নাকি?”\n\nকথাটা বলে নীলা নিজেই হেসে ফেলল।\n\nকিন্তু আরহানের মুখের হাসি উধাও হয়ে গেল।\n\n“নীলাঞ্জনা রহমান!”\n\nনামটা যেন তার পুরোনো ক্ষত আবার জাগিয়ে তুলল।\n\nনীলা চলে যাওয়ার পর আরহান রায়ানকে বলল, “মেয়েটার পরিবার আর অতীত সম্পর্কে সব তথ্য চাই। কিছুই বাদ যাবে না।”\n\nকয়েক ঘণ্টা পর—\n\nআরহানের হাতে একটি ফাইল এসে পৌঁছাল। প্রথম পাতায় লেখা—\n\nনাম: নীলাঞ্জনা রহমান।\nবাবা: মাহবুব রহমান।\n\nনামটি দেখেই আরহানের হাত শক্ত হয়ে উঠল।\n\nফাইলের ভেতরে একটি পুরোনো ছবি ছিল। ছবিতে আরহানের বাবা ও মাহবুব রহমান পাশাপাশি দাঁড়িয়ে আছেন। তাঁদের মাঝখানে কোলে একটি ছোট্ট শিশু।\n\nছবির পেছনে লেখা তারিখটি দেখে আরহান স্তব্ধ হয়ে গেল। এই তারিখের সঙ্গেই জড়িয়ে আছে দুই পরিবারের বিচ্ছেদের ইতিহাস।\n\nছবির নিচে রাখা একটি চিঠি খুলল সে।\n\nচিঠিতে লেখা—\n\n“আরহান, সত্যিটা যেদিন জানবে, সেদিন হয়তো নিজের এত বছরের ঘৃণাকে আর ধরে রাখতে পারবে না। মাহবুব রহমান তোমার শত্রু হলেও পুরো সত্যিটা তুমি জানো না। নীলাঞ্জনার জীবনেও জড়িয়ে আছে সেই রাতের ভয়ংকর রহস্য।”\n\nচিঠিটি পড়ে আরহান চোখ বন্ধ করল।\n\n“যা-ই হোক, মাহবুব রহমানকে আমি ছাড়ব না। তার মেয়েই হবে আমার প্রতিশোধের প্রথম পদক্ষেপ!”\n\nকিন্তু সে জানত না, যে মেয়েটিকে সে প্রতিশোধের হাতিয়ার বানাতে চাইছে, একদিন সেই মেয়েই তার হৃদয়ের সবচেয়ে মূল্যবান মানুষ হয়ে উঠবে।\n\nযে মানুষ ভালোবাসাকে দুর্বলতা মনে করে, সেই মানুষই একদিন ভালোবাসার জন্য নিজের সবকিছু হারাতে প্রস্তুত হবে।\n\nকিন্তু নীলাঞ্জনা কি জানে, তার অতীতের সঙ্গে জড়িয়ে আছে শহরের সবচেয়ে ভয়ংকর মাফিয়া কিংয়ের জীবন?\n\nনাকি তাদের ভালোবাসাও অতীতের কোনো অজানা সত্যের কাছে হার মেনে যাবে?\n\nতা জানতে হলে চোখ রাখুন পরবর্তী পর্বে।\n\nচলবে… 🖤🥀','\n',char(10)),1,'published',0,'2026-10-29 08:24:07','2026-10-29 08:24:07',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('ca7be8c2-f0be-4179-bcfc-a221ff761c89','c4b7dd5c-d4f0-4324-af5f-725d78c6fd88','পর্ব-২',replace('সবাই খাবার টেবিল এ বসে আছে পপি বেগম বলেন\n\nনূরাহ যা তো মা আরহান আর আয়রা কে ডেকে নিয়ে আয়\n\nনূরাহ যায় আয়রা আর আরহান কে ডেকে নিয়ে আসতে\n\nআরহান এর দরজা সামনে এসে নূরাহ বলে \n\n---ভাইয়া আসবো..?\n\n---হুম আয় \n\n--- ভাইয়া মা তোমাকে ডাকছে নিচে খাবার খেতে \n\n--- তুই যা আমি আসছি\n\nনূরাহ আয়রা কে ডাকতে যায় \n\n---এই আয়রার বাচ্চা দরজা খুল ম*রার মতো আর কতো ঘুমাবি দুপুর হয়েছে উঠ মা আমার উঠ \n\nআয়রা ঘুম ঘুম চোখ এ বলে \n\n\n---আপু আর পাঁচ মিমিট \n\n---আর এক মিনিট ও না উঠ আয়রা ভাইয়া চলে আসছে \n\nআয়রা এক লাফে বিছানা থেকে উঠে বলে \n\n---কী ভাইয়া আসছে কখন কবে আর তোমরা আমাকে ডাকো নি কেনো \n\n--- তুই যেই ম*রার মতো ঘুমাচ্ছিলি বড় মা তকে ডেকে গেলেন \n এটা শুনে আয়রা এক দূর দিয়ে আরহান এর রোম এ যায় \n\n---ভাইয়া \n\nআরহান এতো জুড়ে ডাকার জন্য ভয় পেয়ে যায় \n\n--- ও মা গো বাঁচাও পেত্নী টা আমাকে মেরে ফেলল  \n\n--- ভাইয়া এমন করো না আমি পেত্নী না আচ্ছা তুমি কখন আসছো আমাকে ডাকো নি কেনো\n\n---তুই দেখেছিস কখনো মানুষ পেত্নী কে ডাকে\n\nএটা শুনে আয়রা রাগ করে পেলে \n\n---আচ্ছা বাবা সরি রাগ করিস না পুচকি ফ্রেশ হয়ে আয় নিচে খাবার খাবো\n\n---আচ্ছা তুমি যাও আমি আসছি\n\nসবাই খাবার টেবিলে বসে খাবার খাচ্ছে তখন আলতাফ মির্জা বলেন \n\n---ইহান...? \n\n---হুম বাবা বলো \n \n---কয় দিন এর জন্য আসছো আব্বু\n\n--- জানি না আব্বু যদি ভালো লাগে তাহলে বেশি দিন থাকবো না হয় তিন মাস পর চলে যাবো\n\nএই শুনে ইফতেখার মির্জা বলেন \n\n--- শুনো বাবা আসছো আর যেও না আমাদের বয়স বাড়ছে তোমরা ভাইরা ও বড় হয়েছো এখন একটু আমাদের ব্যবসার সামলাও \n\n--- কেন চাচ্চু ইভান, আয়ান,  আলভী এরা তো আছে ব্যবসা দেখবে \n\nইভান,আয়ান,আলভী শুনে বলে\n\n---ভাইয়া প্লিজ আমাদের কে ছেড়ে দাও তুমি ব্যবসা সামলাও আমরা তোমার সাথে আছি \n\nআলভী বলে \n\n---ভাইয়া ব্যবসা আমার মাথায় ঢুকে না তুমি সামলাও আমরা তোমার সাথে কাজ করবো\n\nআরহান বলে \n\n--- ঢুকবে কী ভাবে আমি দেশে ছিলাম না  বলে যা ইচ্ছা করেছো তিন ভাই কী ভাবো আমি কিছু জানি না...? \n\nআয়ান এটা শুনে মুখ থেকে খাবার পড়ে যায় \n\n---ভাইয়া আমরা কাল থেকেই কাজ এ যাব তুমি বললে এখন-ই যাবো কিন্তু প্লিজ কিছু বলো না বাবারা আছে\n\n\n..............\n\n\nমির্জা পরিবার অনেক বড় মির্জা পরিবার এর সবার বড়ো\n\n আলতাফ মির্জা  এবং আফরিন বেগম  এর  এক ছেলে এক মেয়ে আরহান মির্জা - আয়রা মির্জা \n\nদ্বিতীয় :ইফতেখার মির্জা এবং পপি বেগম এর দুই ছেলে ও এক মেয়ে  আয়ান মির্জা আলভী মির্জা ও মেয়ে নূরাহ মির্জা \n\nতৃতীয় : জফরুল মির্জা এবং ফারজানা বেগম এর দুই জমজ ছেলে আশরাফ মির্জা-আহনাফ মির্জা \n\nচতুর্থ : ফারুক মির্জা এবং লিজা বেগম এর এক ছেলে ইভান\n\nতারা চার ভাই এর এক বোন ইয়াসমিন বেগম - ফিরোজ রহমান এর দুই মেয়ে এবং এক ছেলে জান্নাত রহমান মাহিরা রহমান  ছেলে অরবিন রহমাম\n\n\nচলবে...?','\n',char(10)),2,'published',0,'2026-10-29 08:28:10','2026-10-29 11:14:57',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('e456c637-1da7-481a-9481-df53b09ff070','1cc28ac6-f37c-4ecb-b3c1-229045031adb','পর্ব - ১ : সেই অনাকাঙ্ক্ষিত রাতটি ~',replace('★ ঘৃণার নাম তুমি ★\n\nWriter : Noor Islam.\n\nপর্ব - ১ : সেই অনাকাঙ্ক্ষিত রাতটি\n\nএকটি মেয়ের শুধু আকুতি মিনতি শোনা যাচ্ছে। মেয়েটি শুধু বলেই যাচ্ছে প্লিজ আমার সাথে এমন করবেন না, আমাকে যেতে দিন, আমার সর্বনাশ করবেন না। কিন্তু ছেলেটি যেন নিতান্তই পশুর মতো আচরণ করছে। জোর করে মেয়েটার ঘাড় ধরে নিজের কাছে এনে নিজের ঠোঁট দুটো দিয়ে মেয়েটির নরম ঠোঁট দুটিকে নিজের আয়ত্তে নিয়ে নেয়। অনবরত মেয়েটির ঠোঁটে নিজের আধিপত্য বিস্তার করতে ছিলো। মেয়েটি নিজের হাত দিয়ে অনেক জোরে ধাক্কা দিচ্ছিলো, কিন্তু ছেলেটির সুগঠিত দেহের কাছে তার ক্ষীণ হাত দুটো কিছুই ছিলো না। ১০ মিনিট ধরে যেন মেয়েটির ঠোঁটের উপর আধিপত্য বিস্তার করতেই ছিলো ছেলেটি। এরপর সে মেয়েটির ঘাড়ে নিজের মুখ নিয়ে যায়। তার ঘাড়ে অনবরত কিস করতে থাকে আবার মাঝে মাঝে কামড়ও দিতে থাকে। মেয়েটি আকুতি মিনতি করেই যাচ্ছে। এরপর যেন ছেলেটি তার উপর সম্পূর্ণ নিয়ন্ত্রণ হারিয়ে ফেলে। মেয়েটির শরীর থেকে জামাটি টেনে খুলে ফেলে। ভিতরে পড়া ব্রা* টিও টেনে টুনে ছিড়ে ফেলে। নিজের মুখ গুজে দেয় মেয়েটির বুকে, মুখে তুলে নেয়, হাত দিয়ে টিপতেও থাকে। নিজের এমন অবস্থা দেখে মেয়েটি এখন শুধু আল্লাহর কাছে বলছে –\n\n" হে আল্লাহ! তুমি আমাকে এটা কিসের শাস্তি দিচ্ছো। তুমি আমার মরণ দেও, আল্লাহ। "\n\nএরপর ছেলেটি মেয়েটির পেটে চুমু দিতে থাকে। মেয়েটির পায়জামাও টেনে খুলে নেয়, আর নিজের প্যান্টও খুলে ফেলে। মেয়েটি এবারও অনেক আকুতি করতে থাকে। বলে আমার আর সর্বনাশ করবেন না, আমার উপর দয়া করুন প্লিজ। কিন্তু এ কথাগুলো আকুতিগুলো যেন ছেলেটার কানে যাচ্ছেই না। সে ব্যস্ত তার নিজের অনিয়ন্ত্রিত মনটাকে শান্তি করবার জন্য। সে মেয়েটির দুই-পা ফাঁক করে নিজের পুরুষত্বের যন্ত্রটি ঢুকাতে লাগলো। মেয়েটির জায়গাটি অনেকই ছোট ছিলো কেননা মেয়েটি সম্পূর্ণ ভার্জিন ছিলো। কিন্তু তাও ছেলেটি বার বার চেষ্টা করেই যাচ্ছিলো। অবশেষে অনেকবারের পর সে ঢুকাতে পারলেও মেয়েটি ততক্ষণে সম্পূর্ণ নিস্তেজ হয়ে গিয়েছিলো। এতক্ষণ চিৎকার করবার শক্তিটা থাকলেও এখন তাও যেন বন্ধ হয়ে গেলো। এসবের দিকে ছেলেটির কোনোই হুশ নেই। সে অমানুষের মতো কাজ করেই যাচ্ছে। টানা ৪৫ মিনিট পর ছেলেটি ক্লান্ত হয়ে পড়ে, শুয়ে পড়ে মেয়েটির শরীরের উপর। একে সারা শরীর যন্ত্রণায় শেষ তার উপর এমন একটা দেহ তার উপরই শুয়ে আছে - লজ্জা, ঘৃণা আর রাগে মেয়েটির মরে যেতে ইচ্ছা করছে।\n\nমনে মনে বলছে - " আল্লাহ, মা মারা যাবার পর আমি তো কখনো নামাজ ছাড়িনি, কখনো অন্যকে কষ্টও দেইনি,  কখনো নিজের কোনো ইচ্ছাও পূরণ করিনি, কখনো বেপর্দা ভাবে চলাফেরা করিনি, এমন কিছু করিনি যাতে আল্লাহ তুমি আমার উপর নারাজ হবে - তাহলে এটা আজ আমার সাথে কেনো? আমি তো আমারই সৎ মায়ের কথায় তার মেয়ের সাথে এখানে এসেছি। আজ এখানে এ রুমে যার সাথে আছি আমি তো তাকে কখনো দেখিনি,  চিনিও না। তাহলে কেনো? আমার কোন পাপির শাস্তি এটা, হে রব্বুল আলামিন? আমাকে তুমি মরণ দেও "\n\nএতক্ষণ সাউন্ড করে না কান্না করলেও এখন সে অনেক জোরে কেঁদে দেয়। কান্নার সাউন্ড পেয়ে ছেলেটি একবার মাথা তুলে তাকিয়ে আবারও ওদিক ফিরে ঘুমিয়ে যায়।\n\nবেশ অনেকক্ষণ মেয়েটি সেভাবেই নিস্তেজ হয়ে শুয়ে ছিলো। দরজার দিকে চোখ পড়তেই উঠে বসলো। নিজের গায়ে জামা কাপড় জড়িয়ে নিলো। দরজার কাছে আসলো এটাই সুযোগ পালিয়ে যাবার - এই আশায় সে দরজা খুলে এবার এই নরক খানা থেকে বেড়াতে পারবে। কিন্তু, এটা কি সর্বনাশ! দরজায় তো অনেক security maintain করা। একটা পিন দিলেই কেবল দরজা খুলবে, কিন্তু কি সেই পিন? তাহলে এই নরকখানা থেকে বের হতে পারবে না সে? ভাবতেই আবার কান্না এসে গেলো, অঝোরে কাঁদতে কাঁদতে যে কখন দরজার ওখানে বসেই ঘুমিয়ে পড়লো তা সে নিজেও জানে না।\n\n\n---\n\n\nসকাল হয়ে গেলো। রোদ এসে মুখে পড়তেই ঘুম ভেঙে গেলো ছেলেটির। মাথাটা প্রচুর ব্যাথা করছে, যেন কেউ মাথায় তাকে মারছে অনেক জোরে জোরে। এর মধ্যেই একজন তাকে ফোন করলো। ফোন রিসিভ করে বললো –\n\n" হ্যালো মা, বলো? "\n\n– কোথায় আছিস বাবা তুই?\n\n– এইতো হোটেলে, কেনো?\n\n– বাসায় আসিস নি, চিন্তা হচ্ছিলো খুব।\n\n– এটা কি নতুন কিছু বলো? কেনো শুধু চিন্তা করো?\n\n– বুঝেছি, বাসায় আয় তাড়াতাড়ি।\n\nকল কেটে উঠে দাঁড়াতেই চোখ দুটো নিজের কপালে উঠে যায়। নিজের এ কি অবস্থা?  শরীরে একটুও কাপড় নেই। কি হয়েছিলো?\n\nএরপর চোখ যায় দরজার সাথে ঘুমিয়ে থাকা মেয়েটির দিকে। চোখ পড়তেই আগুনের মতো লাল বর্ণ ধারণ করে নেয় চোখ দুটো। কি হয়েছিলো এখানে? প্যান্টটা সাথে সাথে পড়ে মেয়েটির বাহু ধরে একটান দিয়ে তুলে উঠায়। ঘুমের মধ্যে আকস্মিক এমন ঘটনা ঘটায় মেয়েটি হতবাক হয়ে যায়। এরপর চোখ মিলে তাকায়, খেয়াল আসতেই গতকাল রাতের ঘটনা মনে পড়ে যায়। এভাবেই কাছে টেনে তার সর্বনাশ করেছে লোকটি। এখনও আবার এমন করবে, তার তো সর্বনাশ করবার আর কিছু বাকি নেই। এরপরও আবার করবে লোকটি এমন।\n\nকিন্তু মেয়েটিকে অবাক করে ছেলেটি বলে উঠে তুমি কে? আমার রুমে কি করছো? তোমাকে কে পাঠিয়েছে বলো? কার হয়ে কাজ করেছো এমন? কতো টাকা নিয়েছো? বলো? চুপ আছো কেনো?\n\nমেয়েটি কিছুই বুঝতে পারছে না। তার কথা মনে নেই, গতকাল যার এতো বড় সর্বনাশ করেছে, এখন তাকে চিনছে না। অনেক ঘৃণা আর ক্ষোভে বললো - এখন চিনবেন কিভাবে? আপনার কাজ তো হয়ে গেছে।\n\nলোকটি চেঁচিয়ে বলে উঠলো - " What do you mean, stupid? "\n\n– কেন আপনি শুনতে পাননি? আমার সর্বনাশ করে আপনার সাধ মিটেনি?\n\n– তুমি জানো, তুমি কার সাথে এভাবে কথা বলছো? কার নামে এভাবে allegation লাগাচ্ছো?\n\n– আপনি যেই হন না কেনো, আমার কাছে আপনি একটি কাপুরুষ।\n\nএটা শুনে আরহানের মাথা গরম হয়ে গেলো আরও দ্বিগুন।\nহ্যাঁ, ছেলেটি আর কেউ নয় - দেশের একমাত্র স্বনামধন্য businessman আরহান চৌধুরী।\nচৌধুরী বাড়ির একমাত্র ছেলে। মাত্র ২২ বছর বয়সে দেশের সবচেয়ে বড় businessman হয়ে যায় সে।\nসে যেমন অন্যের জীবন গড়ে দিতে পারে ঠিক তেমনি অন্যের জীবন ধ্বংসও করে দিতে পারে।\nতাকে দেখে সকলেই ভয় পায়, সর্বদা সে গম্ভীর হয়েই থাকে।\nগম্ভীর স্বভাবের হলেও, এতোটাই সুদর্শন সে, যাকে দেখলে সবার চোখ জুড়িয়ে যায়। একবার দেখলে শুধু দেখতেই ইচ্ছা করে। ইচ্ছা করে তাকে আপন করে পেতে। সবকিছুর পাশাপাশি তার জেদ ও অহংকারও ছিলো হাই লেভেলের। কিন্তু তাও কখনো সে কোনো মেয়েকে অসম্মান করেনি,মেয়েদের দিকে বাজে ভাবে তাকায়নি, অনেক অসহায় মেয়ে তার কাছে এসেছিলো, কিন্তু কখনো কোনোদিন তাদের অসহায়ত্বের সুযোগ নেয়নি, বরং হেল্প করেছে নিঃস্বার্থভাবে। আর এই একটুখানি মেয়ে তাকে কাপুরুষ বলেছে? এতো বড় স্পর্ধা মেয়েটির।\n\nতার চোখ আরও লাল হয়ে উঠলো, নিজের রাগকে আজ সে কিছুতেই নিয়ন্ত্রণ করতে পারছে না। মেয়েটির হাত আরও শক্ত করে ধরে চিৎকার করে বললো - " তুই চিনিস আমাকে? এতো বড় সাহস তোর? কতো টাকার বিনিময়ে তুই নিজের শরীরকে বিক্রি করলি বল? "\n\nকথাটা শেষ হতেই ইনায়া সজোরে নিজের সমস্ত শক্তি দিয়ে ধাক্কা মেরে আরহানকে বললো\n\n– শুনুন মিস্টার, নিজের মতো অমানুষ আমাকে ভাববেন না। আমি আপনাকে চিনি পর্যন্তও না।\n\n– বাহ!  চিনিস না জানিস না রাত কাটিয়ে নিলি আমার সাথে?\n\n– মুখ সামলে কথা বলুন আমার সাথে।\n\n– তোর মতো পতিতা নারীর সাথে আমাকে মুখ সামলে কথা বলতে হবে? বল কার কথায় এগুলো করেছিস?\nওই খানদের কথায়?  নাকি হাওলাদারদের কথায় বল? সত্যি বল, ওরা তোকে যত দিয়েছে আমি তার দশগুণ দিবো তোকে।\n( এমন ভাবে বলার কারণ আছে যদিও আরহানের। চৌধুরী বাড়ির জাত শত্রু এই দুই পরিবার। তার উপর আরহান এতো অল্প বয়সে এতো সফলতা অর্জন করেছে, তাই সে যেন এখন তাদের চোখের বালি। এর আগেও তার নাম-সুনাম শেষ করতে অনেক পরিকল্পনা করেছিলো এই দুই পরিবার এক জোট হয়ে। কিন্তু এবার এতো বড় ষড়যন্ত্র, এতোটা নীচু আর হীন কাজ! )\n\nআরহানের মুখে পতিতা নারী কথাটি শুনে ইনায়া নিতান্তই চুপ হয়ে গেলো। শুধু মনে মনে বলতে লাগলো\n\n– সে পতিতা নারী? সে? যে কিনা কখনো এক ওয়াক্তও নামাজ ছাড়তো না, বাহিরে বের হতো না, যার কিনা কখনোই কোনো ছেলে বন্ধু অবধি ছিলো না, যাকে কিনা কেউ আজ পর্যন্ত ছুঁতেও পারেনি। অথচ যে ছেলেটা তাকে জোর করে রুমে এনে এতো সর্বনাশ করেছে, সেই তাকে পতিতা নারী বললো?\n\nভাবতে ভাবতে ইনায়ার চোখ থেকে পানি পড়তেই ছিলো। এতক্ষণ চুপ দেখে আরহানের খেয়াল এলো - সে তার হাত অনেক শক্ত করে ধরে আছে। এরপর সে হাত দুটো ছেড়ে দিলো। হাত ছেড়ে দিতেই স্পষ্ট সেখানে আঙুলের ছাপ ফুটে উঠলে। তার ফর্সা হাত দুটিতে আরহানের পাঁচ আঙুলের ছাপ লাল বর্ণ ধারণ করে আছে।\n\nআরহান এবার নিচু গলায় বললো \n\n– দেখো, তোমার অবস্থা কেমন আমি জানি না। হয়তো তুমি খুব চাপে পড়ে এমন কাজ শুরু করেছো। তোমার যতটাকা লাগে আমাকে বলো আমি তোমাকে দিবো, তাও নিজেকে এই মহাপাপ থেকে দূরে রাখো।\n\nসঙ্গে সঙ্গে ইনায়া আরহানকে একটা চড় মারে। বলে আপনি দরজা খুলে দেন, আপনার মতো নরপিশাচের কাছে আমি আর এক মুহুর্তও থাকবো না।\n\nআরহান রাগে, ক্ষোভে নিজের হাত মুষ্টিবদ্ধ করে নেয়।\n\nচলবে...!🌸✨','\n',char(10)),1,'published',0,'2026-10-29 08:29:21','2026-10-29 08:29:21',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('9ec87aa1-d13c-429c-9b78-15a9ff03fcb0','c4b7dd5c-d4f0-4324-af5f-725d78c6fd88','পর্ব-৩',replace('সবাই খাবার টেবিল এ বসে আছে পপি বেগম বলেন\n\nনূরাহ যা তো মা আরহান আর আয়রা কে ডেকে নিয়ে আয়\n\nনূরাহ যায় আয়রা আর আরহান কে ডেকে নিয়ে আসতে\n\nআরহান এর দরজা সামনে এসে নূরাহ বলে \n\n---ভাইয়া আসবো..?\n\n---হুম আয় \n\n--- ভাইয়া মা তোমাকে ডাকছে নিচে খাবার খেতে \n\n--- তুই যা আমি আসছি\n\nনূরাহ আয়রা কে ডাকতে যায় \n\n---এই আয়রার বাচ্চা দরজা খুল ম*রার মতো আর কতো ঘুমাবি দুপুর হয়েছে উঠ মা আমার উঠ \n\nআয়রা ঘুম ঘুম চোখ এ বলে \n\n\n---আপু আর পাঁচ মিমিট \n\n---আর এক মিনিট ও না উঠ আয়রা ভাইয়া চলে আসছে \n\nআয়রা এক লাফে বিছানা থেকে উঠে বলে \n\n---কী ভাইয়া আসছে কখন কবে আর তোমরা আমাকে ডাকো নি কেনো \n\n--- তুই যেই ম*রার মতো ঘুমাচ্ছিলি বড় মা তকে ডেকে গেলেন \n এটা শুনে আয়রা এক দূর দিয়ে আরহান এর রোম এ যায় \n\n---ভাইয়া \n\nআরহান এতো জুড়ে ডাকার জন্য ভয় পেয়ে যায় \n\n--- ও মা গো বাঁচাও পেত্নী টা আমাকে মেরে ফেলল  \n\n--- ভাইয়া এমন করো না আমি পেত্নী না আচ্ছা তুমি কখন আসছো আমাকে ডাকো নি কেনো\n\n---তুই দেখেছিস কখনো মানুষ পেত্নী কে ডাকে\n\nএটা শুনে আয়রা রাগ করে পেলে \n\n---আচ্ছা বাবা সরি রাগ করিস না পুচকি ফ্রেশ হয়ে আয় নিচে খাবার খাবো\n\n---আচ্ছা তুমি যাও আমি আসছি\n\nসবাই খাবার টেবিলে বসে খাবার খাচ্ছে তখন আলতাফ মির্জা বলেন \n\n---ইহান...? \n\n---হুম বাবা বলো \n \n---কয় দিন এর জন্য আসছো আব্বু\n\n--- জানি না আব্বু যদি ভালো লাগে তাহলে বেশি দিন থাকবো না হয় তিন মাস পর চলে যাবো\n\nএই শুনে ইফতেখার মির্জা বলেন \n\n--- শুনো বাবা আসছো আর যেও না আমাদের বয়স বাড়ছে তোমরা ভাইরা ও বড় হয়েছো এখন একটু আমাদের ব্যবসার সামলাও \n\n--- কেন চাচ্চু ইভান, আয়ান,  আলভী এরা তো আছে ব্যবসা দেখবে \n\nইভান,আয়ান,আলভী শুনে বলে\n\n---ভাইয়া প্লিজ আমাদের কে ছেড়ে দাও তুমি ব্যবসা সামলাও আমরা তোমার সাথে আছি \n\nআলভী বলে \n\n---ভাইয়া ব্যবসা আমার মাথায় ঢুকে না তুমি সামলাও আমরা তোমার সাথে কাজ করবো\n\nআরহান বলে \n\n--- ঢুকবে কী ভাবে আমি দেশে ছিলাম না  বলে যা ইচ্ছা করেছো তিন ভাই কী ভাবো আমি কিছু জানি না...? \n\nআয়ান এটা শুনে মুখ থেকে খাবার পড়ে যায় \n\n---ভাইয়া আমরা কাল থেকেই কাজ এ যাব তুমি বললে এখন-ই যাবো কিন্তু প্লিজ কিছু বলো না বাবারা আছে\n\n\n..............\n\n\nমির্জা পরিবার অনেক বড় মির্জা পরিবার এর সবার বড়ো\n\n আলতাফ মির্জা  এবং আফরিন বেগম  এর  এক ছেলে এক মেয়ে আরহান মির্জা - আয়রা মির্জা \n\nদ্বিতীয় :ইফতেখার মির্জা এবং পপি বেগম এর দুই ছেলে ও এক মেয়ে  আয়ান মির্জা আলভী মির্জা ও মেয়ে নূরাহ মির্জা \n\nতৃতীয় : জফরুল মির্জা এবং ফারজানা বেগম এর দুই জমজ ছেলে আশরাফ মির্জা-আহনাফ মির্জা \n\nচতুর্থ : ফারুক মির্জা এবং লিজা বেগম এর এক ছেলে ইভান\n\nতারা চার ভাই এর এক বোন ইয়াসমিন বেগম - ফিরোজ রহমান এর দুই মেয়ে এবং এক ছেলে জান্নাত রহমান মাহিরা রহমান  ছেলে অরবিন রহমাম\n\n\nচলবে...?','\n',char(10)),2,'published',0,'2026-10-29 08:31:00','2026-10-29 11:14:51',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('309cf0ac-5fa4-49ed-8bf0-31de99952151','c6cad923-5458-4e54-9718-f26151ffb31d','“প্রেমের বদলে প্রিন্সিপালের বকা”',replace('“সূচনা”:\n১. উপন্যাসের প্রধান চরিত্র\n১. আরহাম চৌধুরী — নায়ক\nদুষ্টুমির কারখানা! পড়াশোনার চেয়ে বন্ধুদের সঙ্গে ঝামেলা করতেই বেশি ভালোবাসে। নিজেকে কলেজের সবচেয়ে বুদ্ধিমান ছেলে মনে করে, যদিও পরীক্ষার হলে কলমের ক্যাপ খুলতেই পাঁচ মিনিট লাগে। 😭\n— \n২. মেহরিন ইসলাম — নায়িকা\nপড়াশোনায় ভালো, মুখে ঝাঁঝ আর বুদ্ধিতে তুখোড়। আরহামের প্রতিটি দুষ্টুমির জবাব এমনভাবে দেয় যে ছেলেটা নিজের নামও ভুলে যাওয়ার উপক্রম হয়!\n—\n৩. বাবলা — আরহামের প্রাণের বন্ধু\nসারাক্ষণ খাওয়া আর আজগুবি বুদ্ধি দেওয়াই তার কাজ। তার প্রতিটি পরিকল্পনার শেষ কথা— “দোস্ত, প্ল্যানটা ভালোই ছিল, ভাগ্যটাই খারাপ!” 🤣\n৪. তিশা — মেহরিনের বান্ধবী\nগসিপের রানী। কলেজে কে কার দিকে তাকাল, কে কার সঙ্গে কথা বলল—সব খবর তার কাছে আছে। তবে নিজের প্রেমের খবর জিজ্ঞেস করলে সে সরাসরি অস্বীকার করে!\n— \n৫. মজুমদার স্যার — কলেজের প্রিন্সিপাল\nগম্ভীর মানুষ। কলেজে শৃঙ্খলা বজায় রাখতে চান। কিন্তু আরহাম আর বাবলা যখন একসঙ্গে থাকে, তখন তাঁর রক্তচাপ না বাড়িয়ে উপায় থাকে না!\n— \n— \n“এই কলেজের সবচেয়ে বড় দুষ্টু কে, তা সবাই জানে। কিন্তু কলেজের সবচেয়ে বড় রহস্যটা কেউ জানে না। সাত দিনের মধ্যে সত্য প্রকাশ পাবে!”\nএরপর কলেজে ঘটতে থাকে অদ্ভুত সব ঘটনা।\nনোটিশ বোর্ডে রাতারাতি অদ্ভুত ছড়া দেখা যায়।\nপ্রিন্সিপাল স্যারের চেয়ারে কে যেন একটা খেলনা মুরগি রেখে যায়।\nকলেজের মাইকে হঠাৎ ঘোষণা হয়, “বাবলা যেন ক্যান্টিনের বাকি টাকা পরিশোধ করে!”\nআরহাম আর মেহরিন দুজনেই একে অপরকে দোষ দিতে থাকে।\nকিন্তু আসল রহস্য হলো— এই সব কাণ্ডের পেছনে কে আছে, আর সে কেন কলেজের প্রতিষ্ঠাবার্ষিকীর আগেই সত্য প্রকাশ করতে চাইছে?\nসবচেয়ে বড় কথা, আরহাম আর মেহরিন কি একসঙ্গে রহস্যটা সমাধান করতে পারবে, নাকি ঝগড়া করতে করতেই সাত দিন শেষ হয়ে যাবে?\n———————— \n“প্রেমের বদলে প্রিন্সিপালের বকা” \nপর্ব ১\nলেখিকা:আফরিন আক্তার \n*  *  *\n*  *  *\n. প্রথম পর্ব: কলেজে প্রথম দিনেই যুদ্ধ!\nপর্ব ১ • নতুন সকাল, পুরোনো বেয়াদবি\nসকাল ৯টা ১৫ মিনিট।\nনতুন কলেজের গেটের সামনে দাঁড়িয়ে আরহাম চৌধুরী নিজের চুল ঠিক করতে করতে বলল,\n— বাবলা, আজ থেকে আমাদের জীবন বদলে যাবে!\nবাবলা হাতে একটা সিঙ্গারা নিয়ে মুখ ভরা অবস্থায় বলল,\n— কীভাবে?\n— আজ থেকে আমি কলেজের সবচেয়ে জনপ্রিয় ছেলে হব!\nবাবলা সিঙ্গারার শেষ কামড় দিয়ে বলল,\n— আগে তোর মুখের ডান পাশে যে চাটনি লেগে আছে, সেটা মোছ। জনপ্রিয় হওয়ার আগে মানুষ যেন তোকে দেখে সিঙ্গারা না ভাবে।\nআরহাম সঙ্গে সঙ্গে পকেট থেকে রুমাল বের করল।\n— তুই আমার বন্ধু, নাকি শত্রু?\n— পরিস্থিতি অনুযায়ী দুটোই। এখন আরেকটা সিঙ্গারা কিনে দে।\nআরহাম বাবলাকে ধাক্কা দিয়ে কলেজের ভেতরে ঢুকল।\nপ্রথম ক্লাস শুরু হতে তখনও দশ মিনিট বাকি।\nকরিডর দিয়ে হাঁটতে হাঁটতে আরহাম হঠাৎ দেখল, একটা মেয়ে বই হাতে দাঁড়িয়ে আছে। মেয়েটার সামনে একটা নোটিশ বোর্ড, আর সে মন দিয়ে কিছু পড়ছে।\nআরহাম নিজের বন্ধুকে ফিসফিস করে বলল,\n— দেখ, নতুন ছাত্রী। ভাবটা দেখেছিস? মনে হচ্ছে কলেজটা ওর বাবার!\nমেয়েটা পেছন ফিরে তাকাল।\n— কিছু বললেন?\nআরহাম সঙ্গে সঙ্গে হাসল।\n— না না, আমি বলছিলাম কলেজটা খুব সুন্দর!\nমেয়েটা ভ্রু কুঁচকে বলল,\n— তাই নাকি? তা হলে আপনার মুখটা এমন বাঁকা কেন?\nআরহাম চোখ রাঙিয়ে বলল,\n— আমি হাসছি!\n— ওহ! আমি তো ভাবলাম মুখে বাতাস ঢুকে গেছে।\nবাবলা এবার এমনভাবে হাসল যে তার হাতের সিঙ্গারা মাটিতে পড়ে গেল।\nমেয়েটা নিজের বইগুলো গুছিয়ে বলল,\n— রাস্তা ছাড়ুন। ক্লাসে যেতে হবে।\nআরহাম একটু সরে দাঁড়াল।\n— নামটা কী আপনার, মিস রাগের কারখানা?\nমেয়েটা ঘুরে দাঁড়িয়ে শান্ত গলায় বলল,\n— মেহরিন ইসলাম। আর আপনার নাম?\n\n— আরহাম চৌধুরী। এই কলেজের ভবিষ্যৎ কিং!\nমেহরিন একবার আরহামের দিকে তাকিয়ে বলল,\n— তা হলে কলেজের ভবিষ্যৎ বেশ অন্ধকার!\nএই বলে সে চলে গেল।\nবাবলা আরহামের কাঁধে হাত রেখে বলল,\n— দোস্ত, প্রথম দেখাতেই তোর ভবিষ্যৎ শেষ!\nআরহাম দাঁত চেপে বলল,\n— মেয়েটাকে আমি দেখে নেব!\nবাবলা মাথা নাড়ল।\n— অবশ্যই। তবে আগে নিজের ক্লাসরুমটা দেখে নে। আমরা তো উল্টো বিল্ডিংয়ে দাঁড়িয়ে আছি!\nআরহাম চারদিকে তাকিয়ে দেখল, সত্যিই তারা ভুল ভবনে ঢুকে পড়েছে!\n—————————— \nক্লাসরুমে দ্বিতীয় বিপদ\nকোনোমতে ক্লাসে ঢুকে আরহাম শেষ বেঞ্চে বসে পড়ল। বাবলা পাশে বসেই ব্যাগ থেকে টিফিন বের করতে শুরু করল।\nঠিক তখনই শিক্ষক ক্লাসে ঢুকলেন।\n— তোমরা নতুন ছাত্র?\nআরহাম উঠে দাঁড়াল।\n— জি স্যার। আমি আরহাম। আর ও বাবলা। আমরা দুজনেই খুব মেধাবী।\nশিক্ষক চশমার ওপর দিয়ে তাকালেন।\n— তা হলে বলো, গতকাল ক্লাসে কী পড়ানো হয়েছে?\n\n— স্যার, গতকাল তো আমাদের প্রথম দিন!\nশিক্ষক কিছুক্ষণ চুপ করে থেকে বললেন,\n— বাহ! যুক্তি ভালো। কিন্তু তোমরা যে অন্য বিভাগের ক্লাসে ঢুকেছ, সেটা বুঝতে পারোনি?\nবাবলার হাত থেকে টিফিনের বাক্স পড়ে গেল।\nআরহাম ধীরে ধীরে দরজার দিকে হাঁটতে লাগল।\nশিক্ষক পেছন থেকে বললেন,\n— দাঁড়াও! তোমাদের আসল ক্লাসরুম কোথায়, সেটা জেনে যাও।\nপেছন থেকে মেহরিনের হাসির শব্দ শোনা গেল।\nসে পাশের দরজায় দাঁড়িয়ে সব দেখছিল।\n— কলেজের ভবিষ্যৎ কিং! নিজের রাজ্যটাই চিনতে পারলেন না?\nআরহাম মনে মনে শপথ করল, এই মেয়ের সঙ্গে তার ঝামেলা আজই শেষ হবে না।\nসে তখনও জানত না, এই মেয়ের সঙ্গেই তাকে কলেজের সবচেয়ে বড় রহস্যের সমাধান করতে হবে।\n———————— \nদুপুরে ক্লাস শেষ হওয়ার পর পুরো কলেজে একটা খবর ছড়িয়ে পড়ল।\nপ্রিন্সিপাল স্যারের অফিসে নাকি একটা অদ্ভুত চিঠি পাওয়া গেছে।\nআরহাম আর বাবলা কৌতূহল সামলাতে না পেরে অফিসের সামনে গেল। মেহরিন আর তিশাও সেখানে উপস্থিত।\nঅফিসের দরজা খুলে মজুমদার স্যার বেরিয়ে এলেন। তাঁর হাতে একটা সাদা খাম।\nতিনি গম্ভীর কণ্ঠে বললেন,\n— আগামী সাত দিন কলেজে বিশেষ নজরদারি চলবে। কেউ কোনো দুষ্টুমি করলে কঠোর ব্যবস্থা নেওয়া হবে।\nবাবলা আস্তে করে আরহামকে বলল,\n— দোস্ত, তুই কি কিছু করেছিস?\n— আমি কেন করব?\n— কারণ তুই কিছু না করলেও তোর চেহারা দেখে সন্দেহ হয়!\nঠিক তখনই স্যার খাম থেকে চিঠিটা বের করে পড়লেন।\nচিঠির শেষ লাইনটা শুনে সবাই চুপ হয়ে গেল।\n“যে নিজেকে সবচেয়ে চালাক ভাবে, সে-ই প্রথম ভুল করবে।”\nআরহাম মেহরিনের দিকে তাকাল।\nমেহরিনও তার দিকে তাকাল।\nদুজন একসঙ্গে বলে উঠল—\n— এটা নিশ্চয়ই তোর কাজ!\n— আমার কাজ নয়, তোর কাজ!\nতিশা মাথায় হাত দিয়ে বলল,\n— আল্লাহ! রহস্য সমাধানের আগেই এদের ঝগড়া শুরু!\nআর বাবলা পেছন থেকে বলে উঠল,\n— কেউ কি রহস্যের মধ্যে সিঙ্গারা খাওয়ার ব্যবস্থা করতে পারবে?\nচলবে.....\n———————— \n“প্রেমের বদলে প্রিন্সিপালের বকা” \nপর্ব ২\nলেখিকা:আফরিন আক্তার \n*  *  *\n*  *  *\nসকাল ৮টা ৪৫ মিনিট।\nকলেজের গেটের সামনে দাঁড়িয়ে আরহাম চৌধুরী নিজের চুল ঠিক করছিল।\nপাশে বাবলা দাঁড়িয়ে এক হাতে সিঙ্গারা আর অন্য হাতে চায়ের কাপ নিয়ে বলল,\n— দোস্ত, একটা কথা বলব?\nআরহাম চুলে হাত বুলিয়ে বলল,\n— বল। তবে আমার সৌন্দর্যের প্রশংসা হলে দাঁড়িয়ে বলবি।\n— না, তোর বিয়েতে আমাকে দাওয়াত দিবি তো?\nআরহাম ভ্রু কুঁচকে তাকাল।\nশালা, আমি এখনো বিয়েই করিনি!\n— তাই তো আগে থেকে জিজ্ঞেস করছি। পরে যদি বউয়ের ভয়ে বন্ধুকে ভুলে যাস!\nআরহাম বাবলার মাথায় একটা টোকা দিয়ে কলেজের ভেতরে ঢুকে পড়ল।\nকিন্তু আজ কলেজের পরিবেশ অন্য দিনের মতো ছিল না। সবাই তাকে দেখেই ফিসফিস করছিল।\nকেউ বলছে, “এই সেই ছেলে!”\nকেউ বলছে, “চেহারা দেখেই বোঝা যায়!”\nআরহাম থমকে দাঁড়াল।\n— বাবলা, আমার চেহারায় কী সমস্যা?\nবাবলা মনোযোগ দিয়ে তার মুখ পরীক্ষা করে বলল,\n— সমস্যা তো অনেক। তবে আজকে মনে হচ্ছে তুই বিনা অপরাধেই ফেঁসে গেছিস!\n— মানে?\n— মানে, সবাই তোকে চোরের মতো দেখছে!\nআরহাম চিৎকার করে উঠল,\n— আমি চোর না!\nপাশ দিয়ে যাওয়া এক শিক্ষক থেমে গেলেন।\n— কে চোর?\nআরহাম সঙ্গে সঙ্গে সোজা হয়ে দাঁড়াল।\n— স্যার, আমি না!\nশিক্ষক গম্ভীর মুখে বললেন,\n— আমি তো কিছু বলিইনি!\n\nবাবলা পাশে দাঁড়িয়ে ফিসফিস করল,\n— দোস্ত, তোর নিজের মুখই তোর বিরুদ্ধে সাক্ষী দিচ্ছে!\n————————— \nগোয়েন্দা মেহরিনের আবির্ভাব ;\nকলেজের লাইব্রেরির সামনে মেহরিন একটা নোটবুক হাতে দাঁড়িয়ে ছিল। পাশে তিশা।\nতিশা বলল,\n— আমার ধারণা, চিঠিটা আরহামই লিখেছে।\nমেহরিন চোখ সরু করে বলল,\n— প্রমাণ?\n— প্রমাণ নেই। কিন্তু ছেলেটার মুখ দেখলেই সন্দেহ হয়!\n— তোর কাছে পৃথিবীর অর্ধেক মানুষই সন্দেহভাজন!\nতিশা মুখ বাঁকিয়ে বলল,\n— হ্যাঁ, কারণ আমি জন্মগত গোয়েন্দা!\nঠিক তখনই আরহাম এসে তাদের সামনে দাঁড়াল।\n— এই যে মিস গোয়েন্দা, আমার নামে মিথ্যা মামলা চালাচ্ছেন কেন?\nমেহরিন ঠান্ডা গলায় বলল,\n— আপনার নামে মামলা করিনি। তবে আপনি নিজেই নিজের বিরুদ্ধে প্রচার চালাচ্ছেন।\n— কীভাবে?\n— সবাইকে চিৎকার করে বলছেন, আপনি চোর নন। অথচ কেউ আপনাকে চোর বলেওনি!\nবাবলা পেছন থেকে বলে উঠল,\n— আপু, আপনি অসাধারণ! আপনার কাছে কি আমার একটা ব্যক্তিগত সমস্যার সমাধান আছে?\nতিশা আগ্রহ নিয়ে বলল,\n— কী সমস্যা?\nবাবলা দীর্ঘশ্বাস ফেলল।\n— আমি পড়তে বসলেই ঘুম পাই। কিন্তু ঘুমাতে গেলেই ক্ষুধা পায়। এখন আমি কী করব?\nতিশা দু-সেকেন্ড চুপ থেকে বলল,\n— বিয়ে করে ফেলুন।\nবাবলা অবাক হয়ে গেল।\n— বিয়ে করলে কী হবে?\n— তখন বউ আপনাকে পড়তে বসিয়ে রাখবে আর খাবারও দেবে না!\nআরহাম হেসে মাটিতে বসে পড়ার উপক্রম হলো।\nমেহরিনও মুখ ঘুরিয়ে হাসি চাপল।\nআরহাম সেটা দেখে বলল,\n— আপনি হাসলে ভালোই লাগে!\n\nমেহরিন সঙ্গে সঙ্গে মুখ শক্ত করে বলল,\n— আর আপনি চুপ থাকলে আরও ভালো লাগে!\nবাবলা বুক চাপড়ে বলল,\n— আহা! প্রেম শুরু হওয়ার আগেই বিচ্ছেদ!\n— চুপ কর, বাবলা! — আরহাম আর মেহরিন একসঙ্গে চেঁচিয়ে উঠল।\nতিশা হেসে বলল,\n— বাহ! প্রথমবার দুজনের মত মিলেছে!\n———————— \nপ্রিন্সিপাল স্যারের জরুরি সভা\nসকাল ১০টা।\nকলেজের সব ছাত্রছাত্রীকে অডিটোরিয়ামে ডাকা হলো।\nমঞ্চে উঠে মজুমদার স্যার গম্ভীর কণ্ঠে বললেন,\n— গতকাল আমার অফিসে যে রহস্যময় চিঠি পাওয়া গেছে, তার লেখককে খুঁজে বের করতে হবে। আর আজ সকালে আমার টেবিলে আরেকটি চিঠি পাওয়া গেছে।\nপুরো অডিটোরিয়াম নিস্তব্ধ।\nস্যার চিঠিটা খুলে পড়লেন।\n“প্রিয় মজুমদার স্যার,\nআপনার কলেজে প্রতিভার অভাব নেই। বিশেষ করে এমন একজন প্রতিভাবান ছাত্র আছেন, যিনি ভুল ক্লাসে ঢুকেও নিজেকে সঠিক প্রমাণ করতে পারেন।\nতাঁকে সাবধানে রাখবেন।\nইতি,\nআপনার শুভাকাঙ্ক্ষী।”\n\nচিঠি পড়া শেষ হতেই পুরো অডিটোরিয়ামের চোখ আরহামের দিকে ঘুরে গেল।\nআরহাম উঠে দাঁড়িয়ে বলল,\n— স্যার, এটা আমার বিরুদ্ধে ষড়যন্ত্র!\nমজুমদার স্যার চশমা খুললেন।\n— আরহাম চৌধুরী!\n— জি, স্যার!\n— গতকাল তুমি ভুল ক্লাসে ঢুকেছিলে?\n— জি, স্যার। কিন্তু—\n— তুমি কি নিজেকে কলেজের ভবিষ্যৎ কিং বলেছিলে?\nআরহাম থতমত খেয়ে গেল।\n— স্যার, সেটা তো ব্যক্তিগত অনুভূতি!\nস্যার টেবিলে হাত দিয়ে বললেন,\n— চুপ! আরহাম, আজ থেকে তুমি এবং মেহরিন এই রহস্যের তদন্ত করবে।\nমেহরিন উঠে দাঁড়াল।\n— কিন্তু স্যার, আমি ওর সঙ্গে কেন?\nস্যার বললেন,\n— কারণ তোমরা দুজনেই খুব বুদ্ধিমান।\nবাবলা পেছন থেকে বিড়বিড় করল,\n— স্যার, তাহলে আমাকে কেন বাদ দিলেন? আমিও তো খুব বুদ্ধিমান!\nস্যার তার দিকে তাকালেন।\n— তোমার হাতে কী?\n— সিঙ্গারা, স্যার।\n— ক্লাসে খাবার নিয়ে এসেছ কেন?\nবাবলা গম্ভীরভাবে বলল,\n— স্যার, তদন্তের জন্য শক্তি দরকার!\nআবারও হাসির শব্দে অডিটোরিয়াম কেঁপে উঠল।\n———————— \nসভা শেষ হওয়ার পর মেহরিন আরহামের হাতে একটা কাগজ ধরিয়ে দিল।\n— এটা কী?\n— তোমার তদন্তের প্রথম সূত্র।\nআরহাম কাগজটা খুলে দেখল। সেখানে লেখা—\n“যে জায়গায় সবাই চুপ থাকে, সেখানেই প্রথম উত্তর লুকিয়ে আছে।”\nআরহাম কয়েক মুহূর্ত চিন্তা করল।\nতারপর আত্মবিশ্বাসের সঙ্গে বলল,\n— বুঝেছি! ক্যান্টিন!\nমেহরিন কপালে হাত দিল।\n— ক্যান্টিনে সবাই চুপ থাকে কখন?\nবাবলা পাশ থেকে উত্তর দিল,\n— খাবার শেষ হয়ে গেলে!\nমেহরিন দীর্ঘশ্বাস ফেলল।\n— তোমাদের দুজনকে নিয়ে রহস্য সমাধান করতে গেলে রহস্যই আত্মহত্যা করবে!\nআরহাম হঠাৎ আঙুল তুলে বলল,\n— দাঁড়াও! যেখানে সবাই চুপ থাকে... লাইব্রেরি!\nমেহরিন একটু থেমে বলল,\n— প্রথমবারের মতো একটা বুদ্ধির কাজ করেছ।\nআরহাম বুক ফুলিয়ে বলল,\n— ধন্যবাদ। আমার বুদ্ধি একটু দেরিতে কাজ করে, কিন্তু কাজ করে!\nতিনজন লাইব্রেরির দিকে রওনা দিল।\nলাইব্রেরির ভেতরে ঢুকে মেহরিন পুরোনো বইয়ের তাকগুলো পরীক্ষা করতে লাগল। আরহাম একটা বই খুলে দেখল, ভেতরে একটা ছোট কাগজ রাখা।\nকাগজে লেখা—\n“পুরোনো খাতা, তৃতীয় তাক, শেষ বই।”\nমেহরিনের চোখ বড় হয়ে গেল।\n— আরহাম, এটা সত্যিই একটা সূত্র!\nআরহাম মুচকি হেসে বলল,\n— বলেছিলাম না, আমি জিনিয়াস!\nঠিক তখন বাবলা পাশ থেকে একটা বই নামিয়ে বলল,\n— দোস্ত, এখানে একটা খাতা আছে। তবে তোর জিনিয়াস হওয়ার প্রমাণ হিসেবে আমি এই বইটা বাসায় নিয়ে যাচ্ছি।\nমেহরিন চেঁচিয়ে উঠল,\n— বাবলা! লাইব্রেরির বই বাসায় নেওয়া যায়, কিন্তু রেজিস্টারে নাম লিখে!\nবাবলা বইটা বুকে চেপে বলল,\n— আপু, আমি তো শুধু বইটাকে একটু বেড়াতে নিয়ে যাচ্ছিলাম!\nতিনজনের হাসির মাঝেই মেহরিন পুরোনো খাতাটা খুলল।\nপ্রথম পাতায় কলেজের প্রতিষ্ঠাবার্ষিকীর অনেক বছরের পুরোনো একটা ছবি।\nছবির পেছনে হাতে লেখা একটি নাম—\n“অপারেশন হাসির রাজা — ২০১২”\nআর তার ঠিক নিচে আরেকটি লাইন—\n“এবারের উত্তরাধিকারী কে?”\nআরহামের মুখের হাসি মিলিয়ে গেল।\nমেহরিন ধীরে ধীরে তার দিকে তাকাল।\n— আরহাম, তোমার কি মনে হয়... এই রহস্যের সঙ্গে তোমার পরিবারের কোনো সম্পর্ক আছে?\nআরহাম উত্তর দেওয়ার আগেই লাইব্রেরির দরজার বাইরে কারও পায়ের শব্দ শোনা গেল।\nতারপর একটা কণ্ঠ ফিসফিস করে বলল—\n— খাতাটা ওদের হাতে চলে গেছে!\nচলবে....','\n',char(10)),1,'published',0,'2026-10-29 10:46:06','2026-10-29 10:46:06',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('1c831c88-cdd8-42d3-8efa-d86ed4c5fb77','adf22c21-71fa-41da-9263-a38c83efaa14','কাজল রেখা',replace('আমার চাচাতো বোন বিয়ের আসর ছেড়ে অন্য একটা ছেলের সাথে পালিয়েছে।এখন সবাই দোষা*রোপ করছে\nআমি তাকে পালাতে সাহায্য করেছি, তাই তার হবু বর কে আমায় বিয়ে করতে হবে। অথচ আমি তার পালানোর কথা জেনেছি এই মাত্রই। কিন্তু কেউই আমার কথা বিশ্বাস করছে না কারণ, পার্লারের মেয়েরা তাকে যে রুমে সাজাচ্ছিলো সে রুমে শুধু আমি ছিলাম।\nআমার মেজোমা মেঝেতে বসে দেয়ালের সাথে পিঠ ঠেকিয়ে কাঁদছেন।অর্পিতা আপু খুব আদরের মেয়ে তার। কাঁদতে কাঁদতে নিশ্চুপ হয়ে যাচ্ছেন তিনি, একটু পর আবার হিচকি তুলে কাঁদছেন। আমাকে দোষারোপ করছেন।গা*লি দিচ্ছেন।আমি নির্বাক বসে আছি। এতোক্ষণ নিজেকে জাহির করতে করতে নিজের গলা ভেঙে গেছে।ক্লান্ত হয়ে চুপ করে গেছি।তবুও মনে হচ্ছে না কেও আমার একটা কথা বিশ্বাস করেছে।\nমেজোমা আবার শব্দ করে কেঁদে উঠলেন।চোখের পানি মুছে আমার দিকে তাকিয়ে গজগজ করে বললেন\n-"তুই এখনো ঠাট ধরে বসে থাকবি! এতো জেদ তোর, এতো! এতোবার জিজ্ঞেস করার পরও বলবি না অর্পা কোথায়?কার সাথে গেছে ও?"\n-"আমি জানি না তোমার মেয়ে কোথায়, কার সাথে গেছে?যখন কিছু জানিই না তখন উত্তর দেবো কোত্থেকে!"\n\nজবা বেগম অগ্নি দৃষ্টি তে চাইলো চাঁদনির দিকে।উঠে দাড়িয়ে চাঁদনীর গালে ঠা*স করে চ*ড় মারার ইচ্ছে পোষণ করলেন।কিন্তু সাহসে কুলাতে পারলেন না।  চাঁদনি গো ধরে বসে রইলো। বাড়ির সবাই জানে অর্পিতার সাথে ওর কেমন সম্পর্ক।মেয়েটা ওঁকে দুচক্ষে সহ্য করতে পারতো না। সাপে নেউলে সম্পর্ক ছিলো ওঁদের। চাঁদনীর গায়ের রং শ্যাম বর্ণের হওয়ায়, ছোটবেলা থেকেই অর্পিতা খুব তুচ্ছ তাচ্ছিল্য করতো ওঁকে। যদিও এসব চাঁদনী গায়ে মাখাতো না কোনো কালেই।বাড়িতে যেমন অর্পিতার অধিকার ছিলো, সমান অধিকার চাঁদনীরও ছিলো।আর চাদনী নিজের অধিকার নিয়ে সবসময় খুব সতর্ক। \nঅর্পিতা পালানোর আগে চিরকুট এ লেখে গেছে, সে এ বিয়েটা করতে পারবে না। যাকে ভালোবাসে তার সাথেই পালাচ্ছে, তাকে যাতে খোঁজার চেষ্টা করা না-হয়। অথচ বাড়ির সবাই জানতো অর্পিতা আর আধারের প্রেমের সম্পর্ক ছিলো।দু''জনের সম্মতিতেই ওঁদের ভালোবাসা পূর্ণতা দেওয়ার জন্য আজকের বিয়ের আয়োজন করা হয়েছিলো। কিন্তু অর্পিতা পালিয়ে গেলো।জবা বেগম তবুও মেয়ের দোষ দেখতে পাচ্ছেন না।যখন চাদনীর অন্যান্য কাজিনদের থেকে জানা গেলো অর্পিতা কে সাজানোর সময় সে রুমে শুধু চাদনী ছিলো, তখন তিনি চাদনী কে কথা শোনানোর খুব সুন্দর ছুতো পেলেন। এ দুই মা মেয়ের ওঁকে নিয়ে সমস্যা টা কী, তা চাদনী আজ পর্যন্ত বুঝতে পারলো না।\nবাইরে পদচারণের শব্দ শোনা গেলো।শিকদার বাড়ির তিন কর্তা কক্ষে এসে ঢুকলেন।তাদের দেখেই জবা বেগম উঠে দাঁড়ালেন। মাথায় ঘোমটা টানার কথা ভুলে, এলোমেলো পায়ে স্বামীর কাছে গিয়ে বললেন\n-"অর্পার কোনো খোঁজ পেয়েছো?আমার মেয়েটা কোথায়?"\n\nআরমান শিকদার অসহায় দৃষ্টিতে তাকালেন স্ত্রীর পানে যার অর্থ অর্পিতার খোঁজ পায়নি তারা। জবা বেগম আবার কাঁদতে শুরু করলেন।চাঁদনী নিঃস্বহায় এর মতো বসে আছে।সবার উপর খুব অভিমান জমেছে ওর।না জেনেই কিভাবে, বকাবকি করলো। সবাই মেঝো মার কথা বিশ্বাস করলো।কেও ওর কথা একবারো শুনলোও না। আরমান শিকদার অসহায় দৃষ্টিতে বড় ভাইয়ের দিকে তাকিয়ে বললেন\n-"আধার কোথায়? খুব রে*গে আছে নিশ্চয়ই?"\nঅপূর্ব শিকদার গম্ভীর স্বরে বললেন\n-"ড্রইং রুমে চুপচাপ বসে আছে।"\nঅথচ তার এখন ভাং*চুর করার কথা।সবার সাথে রাগারাগি করার কথা।জংলির মতো চিল্লা-ফাল্লা করার কথা।খুব বেশিই রাগী আর জেদ্দি সে।কিন্তু এর একটাও আধার করছে না।তার হবু বউ পালিয়েছে, যার সাথে বিয়ের আগে প্রেমের সম্পর্ক ছিলো তার।অথচ সে নিশ্চুপ।অল্প শো*কে কা*তর,অধিক শো*কে পাথর।\nচাঁদনী মাথা নিচু করে বসে আছে।কারোও একটা কথাও ওর কানে ঢুকছে না।\nআরমান শিকদার অসহায় গলায় বললেন\n-"এখন কী করবো?এতো আত্মীয় -স্বজন,সবাইকে কী জবাব দেবো।মেয়ে পালানোর কথা এতোক্ষণে হয়তো জেনে গেছে সবাই!"\nঅপূর্ব শিকদার গলা খাকাড়ি দিলেন।চাঁদনীর বাবা, আকিব শিকদারের দিকে তাকিয়ে বললেন\n-"চাঁদ কে আমি আমার আধারের বউ করতে চাচ্ছি, আকিব!"\n-"সেটা কখনোই সম্ভব না ভাইজান।আঁধার কখনোই মানবে না।আমার মেয়েটাকে এমনিতেই সবাই যথেষ্ট কথা শুনিয়েছে।দোষ না করেও বারংবার দোষী করা হচ্ছে ওঁকে।"\n\nআকিব শিকদার মুখ কালো করে বললেন।শেষ কথাটা জবা বেগমকে ঠেস মেরে বলেছে বোঝা যায়।\n\n-"আঁধার অবশ্যই মানবে।মানতে ওঁকে হবেই।এটা পরিবারের সম্মানের বিষয়!"\n-"চাঁদনী হ্যাঁ না বলা পর্যন্ত। সম্মতি দিতে পারছি না!"\n\nআকিব শিকদারের কথার প্রেক্ষিতে সবাই চাঁদনীর দিকে তাকালো।মুখ ফুলিয়ে খাটের উপর বসে আছে ও।বাচ্চাদের মতো পা দু''টো দোলাচ্ছে। চাদানীর মুখে এতোক্ষণ কথা ফোটে।বিমূঢ় স্বরে আওড়ায়\n-"তোমার সুদর্শন ছেলে আমার মতো কালী কে বিয়ে করবে না বড়বাবা।এমনিতেই উঠতে বসতে আমার গায়ের রং নিয়ে খোঁটা দেয় আমাকে।আমি যদি এই দুনিয়ার শেষ নারী হই, তবুও তোমার ছেলে আমাকে বিয়ে করতে রাজি হবে না!"\n\nঅপূর্ব শিকদার সাফাই গেয়ে বললেন\n-"কেন নিজেকে এরকম বলছিস আম্মা।তুই খুব সুন্দর বিশ্বাস কর।ঢাকা যাওয়ার পর থেকেই ওর মতিভ্রম হয়েছে, জানিস তো।নয়তো আগে তো এমন করতো না!"\n-"সেটাই তো ভয়।তোমার ছেলে খুব মর্ডান হয়ে ফিরে এসেছে।মানুষ কে মানুষ বলে গণ্য করে না।আমাকে গেঁয়ো ভুত ছাড়া কথাই বলে না।এতোকিছুর পর যদি আমি তাকে বিয়ে করি, তাহলে সে ভাববে আমার আত্মসম্মান নাই।আমি ছ্যাচড়া, তখন সে আমাকে পদে পদে অপমান করার রশিদ পেয়ে যাবে।" \n\nচাঁদনীর একগুয়ে জবাব।অপূর্ব শিকদার অসহায় দৃষ্টিতে তাকালেন আকিব শিকদারের দিকে।তিনি পরলেন মাইনকার চিপায়।একদিকে বড় ভাই,আরেকদিকে মেয়ে। অপূর্ব শিকদার অনুরোধ করলেন ভাইয়ের কাছে, চাঁদনী কে বোঝাতে।এবারে দীর্ঘশ্বাস ফেললেন তিনি।বললেন\n-"আঁধার কে গিয়ে বলো কথাটা। চাদনী কে রাজি করানোর দায়িত্ব আমার।কিন্তু আঁধার যদি উল্টাপাল্টা কিছু করে, বা আমার মেয়েকে অপমান করার চেষ্টা করে তখন কিন্তু খুব খারাপ হবে বলে দিলাম!"\n\nঅপূর্ব শিকদার সম্মতি দিয়ে বেরিয়ে গেলেন।জবা বেগম রাগে ফোঁসফোঁস করছেন।আধারের সাথে চাদনীর বিয়ে হবে এ বিষয়টা কিছুতেই তিনি মানতে পারছেন না।তার মেয়ের বর, ঘর সবকিছু চাদনীর হবে এটা ভাবতেই চাদনীর গলা টিপে দিতে মন চাচ্ছে তার।ধুপধাপ পা ফেলে বেরিয়ে গেলেন তিনি।আরমান শিকদার একপলক ভাই আর ভাইঝির দিকে তাকিয়ে তিনিও বেরিয়ে গেলেন।\n\nআকিব শিকদার হাঁটু মুড়ে মেঝেতে মেয়ের কাছে বসলেন।ওর হাত দু''টো নিজের হাতের মুঠোয় নিয়ে বললেন\n-"আধার কে বিয়ে করবি আম্মা?"\n-"মেঝোমা আমাকে অনেক কথা শুনিয়েছে বাবা। মারতেও এসেছে।মেঝো বাবা বাঁচিয়ে নিয়েছে!"\n\nপ্রশ্নের উত্তরে এমন পাল্টা অভিযোগ আকিব শিকদারের কাছে স্বাভাবিক। মেয়েটা খুব ইন্ট্রোভার্ট। সবকিছু নিজের মধ্যে গুমরে রাখে।কিন্তু বাবার কাছে সে একটা খোলা ডাইরি।তার সকল,অভিযোগ, আবদার, অভিমান সব বাবার কাছে।আকিব শিকদার মলিন হেঁসে বললেন\n-"আই এম সরি আম্মা!আমি সে সময় তোর পাশে থাকতে পারিনি।অর্পিতা কে খোঁজায় ব্যস্ত ছিলাম যে!"\n-"ইট’স ওঁকে! বাট আমি ওই সাদা গন্ডার কে বিয়ে করবো না!"\n-"তুই বাবার কথা রাখবি না?"\n-"এটা অনুরোধ করো না প্লিজ!"\n-"আঁধার অনেক ভালো ছেলে আম্মা!"\n-"জানি, কিন্তু তার জন্য আমি ভালো মেয়ে না, কারণ আমি কালো!"\n-"আমার আম্মা খুব সুন্দর।"\n-"মিথ্যা স্বান্তনা দিয়ো না।খুব গায়ে লাগে।"\n\nআকিব শিকদার অসহায় দৃষ্টিতে চাইলেন। চাদনী চোখ ফেরালো।ও দুর্বল হয়ে যাচ্ছে। মানুষটা সবসময় ওঁকে দুর্বল  করে দেয়।\n,\n\nআকিব শিকদারের কথার জালে শেষমেশ বাধ্য হয়ে রাজি হলো চাদনী।বাড়িতে অবিবাহিত বা বিবাহ উপযুক্ত মেয়ে বলতে শুধু ওই আছে।এখন মান-সম্মান বাঁচানোর জন্য ও ছাড়া ওর বাপ-চাচা আর কাওকে খুঁজে পায়নি।চাঁদনীরও আর কিছু করার ছিলো না, বড়দের চাপে পরে নিজের সবচেয়ে অপছন্দের মানুষটার বউ সাজতে হচ্ছে ওঁকে। চাদনী নিজের মায়ের বিয়ের লাল লেহেঙ্গা টা পরলো।ওর কয়কজন কাজিন মিলে খুব সাদামাটা ভাবে সাজিয়ে দিলো ওঁকে। \nযখন চাদনী সবার সাথে দোতলা থেকে ড্রইংরুমে নেমে আসছিলো, সিড়ি তে থাকা অবস্থায় আঁধারের উচ্চস্বরে বলা কথাগুলো শুনেই থমকে গেলো চাঁদনী। \n\n-"তুমি ভাবলে কী করে বাবা আমি ওই গাঁইয়া ভুত কে বিয়ে করবো?ওর কোনো যোগ্যতা আছে আমার বউ হওয়ার।নিজের মুখ আয়নায় দেখেছে ও!ওঁকে তো আমি আমার বেড পার্টনার হিসেবেও রাখবে না।এই জন্য বুঝি মিথ্যে বলে নিয়ে এসেছিলে আমাকে।আজই আমি ঢাকা ফিরে যাবো, একমুহূর্তও থাকবো না এ বাড়িতে!"\n\nচাদনী টলমলে দৃষ্টিতে মাথা তুলে তাকালো বর বেশে দাঁড়িয়ে থাকা সুদর্শন পুরুষটির দিকে।বাবার কথা রাখতে বিয়ের পিড়িতে বসেছিলো ও।তবে বাবার ভালো মেয়ে হতে গিয়ে যে এভাবে বাড়ি ভর্তি মানুষের সামনে নিজের ইজ্জত সম্মান সব খোয়া যাবে সেটা তো জানা ছিলো না ওর!আঁধার শিকদার রাগে ফুঁ*সছে।সিড়ির উপর চাদনী কে দাঁড়িয়ে থাকতে দেখতেই রাগটা আরো তড়তড়িয়ে বাড়লো ওর। সামনে বধূূবেশে দাঁড়িয়ে থাকা শ্যামা রঙের মেয়েটাকে অ*সহ্য ঠেকছে তার নিকট।নিজের স্ট্যান্ডার্ডের ব্যাপারে বরাবরই কনসার্ন থাকা আঁধার শিকদার না-কি বিয়ে করবে অজপাড়াগাঁয়ের এই কালো মেয়েটাকে!রুচিতে ধরবে ওর?প্রশ্নটা মাথা চাঁড়া দিয়ে উঠতেই টলমলে চোখে তাকিয়ে থাকা চাঁদনীর দিকে ক্রু*দ্ধ দৃষ্টিতে তাকালো ও।ঝাঁঝালো স্বরে চিল্লিয়ে বললো\n\n-"কালির ঘরের কালি, এতো শখ আমাকে বিয়ে করার!নিজের মুখ আয়নায় দেখেছিস তুই?তোকে দেখলে বমি আসে আমার।বামুন হয়ে চাঁদে হাত দেওয়ার স্বপ্ন দেখিস!"\n\nকথাটা ঠোঁট ফস্কে বের করতে না করতেই ছেলেকে ধমকে উঠলেন অপূর্ব শিকদার।আঁধার যে সিনক্রিয়েট শুরু করবে সেটা তিনি জানতেন, ছেলের অধঃপতন সম্পর্কেও ভালোই ধারণা ছিলো ওনার। কিন্তু চাঁদনী কে যে সবার সামনে এতটা হেনস্তা করবে সেটা তার ভাবনারও বাইরে ছিলো। রাগে গজগজ করতে করতে তিনি বললেন\n\n-"এসব কী ড্রামা হচ্ছে আঁধার।চাঁদ মা''কে এভাবে অপমান করার অধিকার কে দিয়েছে তোমাকে? একে তো তোমার বউ পালিয়েছে। দ্বিতীয়ত চাদনী কে অনেক কষ্টে রাজি করিয়েছি আমরা, তোমাকে বিয়ে করতে।বাড়ির মান-সম্মানের কথা ভেবে মেয়েটা নিজেকে বলি দিচ্ছে, আর তুমি তাকে কথা শোনাচ্ছো?চুপচাপ বিয়েটা করে নাও, খবরদার কোনো ধরণের নাটক করবে না!"\n\nঅ*গ্নি দৃষ্টি তে অপূর্ব শিকদারের দিকে তাকালো আঁধার।তপ্তস্বরে চিবিয়ে চিবিয়ে বললো\n\n-"নাটক তো তোমরা সবাই করছো, আমার সাথে।পেয়েছো টা কী আমাকে!তোমাদের হাতের পুতুল আমি? না আমার কোনো লেভেল নেই, যে যাকে তাকে ধরে এনে আমার উপর গছিয়ে দিচ্ছো তুমি!"\n\nঅপূর্ব শিকদার চঞ্চল দৃষ্টিতে আশেপাশে চাইলেন।ইতোমধ্যেই গুজুরগুজুর ফুসুরফুসুর শুরু করে দিয়েছে সবাই।একে তো বাড়ির এক মেয়ে পালিয়েছে, অন্যদিকে বাড়ির অন্য মেয়েকে তাঁদেরই বাড়ির ছেলে যা তা বলে অপমান করছে।\nআগত অতিথিরা যে ইচ্ছে মতো তাঁদের পরিবার নিয়ে সমালোচনা করছে সেটা বুঝতে বাকি রইলো না অপূর্ব শিকদারের।লজ্জায় মাথা হেঁইট হলো তার।ছেলের দিকে তাকিয়ে উদগ্রীব স্বরে বললেন\n\n-"এসব কী বলছো আঁধার! সবাই দেখছে, নিজের আচরণ সংযত করো।"\n\n-"দেখুক সবাই। সবাইকে নিজেই দাওয়াত করে নিয়ে এসেছো, আমার ধ্বং*সযজ্ঞ দেখাতে। এখন যখন আমি উল্টো গান গাইছি, তোমার কেনো গায়ে লাগছে?তুমি করলে আরাম, আর আমি করলে হারাম?\n\nশক্ত কন্ঠে চিবিয়ে চিবিয়ে বললো আঁধার।চাঁদনী ছলছল দৃষ্টিতে তাকালো নিজের বাবার দিকে।আকিব শিকদার অসহায় চোখে তাকাতেই কপোল বেয়ে টুপ করে এক ফোঁটা অশ্রু গড়ালো ওর।মা হারা মেয়েটার এহেন অবস্থা সহ্য হলো না ওনার।ছোটবেলা থেকে বুকের সাথে আগলে রেখে পুতুলের মতো বড় করেছেন তিনি চাঁদনী কে।সেই মেয়ের এতো বি*শ্রী অপমান বুকে কম্পন ধরালো। \nতিক্ত ঢোক গিললেন আকিব শিকদার। ফুঁ*সতে থাকা আধারের দিকে তাকিয়ে ভা*ঙা গলায় আওড়ালো \n\n-"আঁধার, আমার মেয়েটাকে আর অপমান করো না! ওর কোনো দোষ নেই।আমাদের কথা রাখতেই ও বিয়েতে রাজি হয়েছে।সব আমাদের দুই ভাইয়ের দোষ।প্লিজ ওঁকে এতো কষ্ট দিয়ে কথা বলো না।"\n\nচাচার দিকে তাকাতেই আঁধারের দৃষ্টি নরম হলো।সেই শক্ত খোলস ধরে রাখা সম্ভব হলো না আর ওর পক্ষে। আকিব শিকদারের দিকে তাকিয়ে অভিযোগের সুরে বললো\n\n-"দেখছো চাচু, সবাই কেমন করছে আমার সাথে!আমি বিয়েটা করতে চাইছি না, তবুও জোর করছে আমাকে।তুমি বলো এটা ঠিক?প্লিজ বাবাকে মানা করো আমার সাথে এমন করতে।আমি বিয়ে করবো না তোমার মেয়েকে।" \n\nআকিব শিকদার মাথা নিচু করে দাঁড়ালেন। অথৈ জলে পরেছেন তিনি।একদিকে মেয়ের কান্না ভেজা মুখ,মেয়েটার সম্মান।অন্যদিকে আঁধারের নাকচ।আজ যদি তার মেয়েটার বিয়ে ভেঙে যায়, তবে যে গ্রামবাসী ওঁকে কথার ছোবলেই মেরে ফেলবে। এই সমাজ যে শুধু মেয়েদের দোষ দেখে। আঁধার বিয়ে ভেঙে দিলেও, দোষ হবে চাঁদনীর।সবাই চাঁদনী কে দুষবে, পেছনে কথার ছোবলে পি*ষে মা*রবে।বলবে হয়তো চাঁদনীর কোনো সমস্যা আছে, তাই তার বোন পালিয়ে যাওয়ার পর, তার বোনের হবু বরের উপর গছিয়ে দিতে চাওয়া হয়েছিলো ওঁকে, তবুও মেয়েটার বিয়ে হয়নি, \n বর তাকে বিয়ের আসরে ফেলে চলে গেছে।নয়তো তার মেয়েটাকে আবার গায়ের রং নিয়ে খোঁটা দেবে।এ খোঁটা তো ছোটোবেলা থেকে কম পায়নি ও।মেয়েটা যদি সহ্য করতে না পেরে কিছু ঘটিয়ে বসে! তখন? বুক ধ্ব*ক করে উঠলো আকিব শিকদারের।পিতৃত্বে আঘাত আসতেই হৃদয় কাপলো অচিরাৎ! বাবা হয়ে মেয়ের এই অবস্থা কী করে সহ্য করবেন তিনি!\n\nচাঁদনী, পরণের লেহেঙ্গা টা দু''হাতে উঁচু করে ধরে, সিড়ি বেয়ে সোজা নেমে এসে, অপূর্ব শিকদারের মুখোমুখি দাঁড়ালো। চোখের পানি তর্জনী আঙ্গুল দিয়ে ছিটকে ফেলে ভেজা স্বরে বললো\n\n-"আমায় ক্ষমা করে দিও বড় বাবা।এতো অপমানের পর তোমার ছেলেকে বিয়ে করা আমার পক্ষে সম্ভব না। সে ঠিকই বলেছে আমার কোনো যোগ্যতা নেই তাকে বিয়ে করার।আমার মতো কালো একটি মেয়েকে তোমার সুদর্শন ছেলের পাশে মানাবে না।আই এম সরি, মাফ করে দিও।তোমার কথা রাখতে পারলাম না।"\n\n-"চাঁদ মা, কষ্ট পাস না তুই।ও তোকে বিয়ে না করে যাবে কই!একটু সময় দে আমাকে।"\n\nঅসহায় সুরে বললেন অপূর্ব শিকদার।চাঁদনীর হৃদয়ে আঘাত হানলো কথাটা।হু হু করে কেঁদে দিয়ে বললো\n \n-"আমি ফেলনা নই বড়বাবা। কালো হতে পারি,কিন্তু আত্মসম্মান বোধ আমারও আছে।এতোটাও নিচু হয়ে যায়নি, যে কেও বিয়ে করতে না চাইলে এভাবে তাকে জোর জবরদস্তি আমার সাথে বিয়ে বসাবে তুমি।বানের জলে ভেসে আসিনি আমি!"\n\nচাঁদনীর কান্নায় আকিব শিকদার অশ্রুসিক্ত চোখে তাকালেন ওর দিকে।চাঁদনী ওনার দিকে ফিরে চাইলো।হিঁচকি তুলে ভেজা গলায় আওড়ালো\n\n-"এতটা বোঝা হয়ে গেছি বাবা, যে এভাবে বিদায় করতে চাইছো।তাও অন্যের গলার কাটা বানিয়ে। সে তো আমাকে কয়েক সেকেন্ডের জন্যই সহ্য করতে পারছে না,পুরো জীবন কী করে কাটাবে আমার সাথে?"\n\nআঁধার একপলক চাঁদনীর দিকে চাইলো।মনে মনে ভেংচি কাটলো ও।বিড়বিড় করে বললো \n-"ঢং! আমার মতো ছেলে তুই সাতবার জন্ম নিলেও পাবি না।বিয়ে করার জন্য তড়পাচ্ছে,তবুও মেয়ের নাটক দেখো!দয়ার মূর্তিকে তো সবার সামনে মহান সাজতে হবে।"\n\nআঁধারের মা বর্ষা বেগম এগিয়ে এসে দু''হাতে আঁজলে নিলেন চাঁদনী কে। চোখের পানি মুছিয়ে দিয়ে, মাথায় হাত বুলিয়ে দিলেন।চাঁদনী জড়িয়ে ধরলো ওনাকে।\nবিরক্তিকর শ্বাস ফেললো আঁধার।মুখ দিয়ে চ-বর্গীয় শব্দ করে, গম্ভীর স্বরে আওড়ালো \n\n-"তোমাদের নাটক শেষ হলে বলো আমাকে, আমি বরং যাই!বিরক্ত লাগছে আমার। আজকেই ঢাকা ফিরে যাবো আমি।"\n-"তুই এখনো আমার কথা রাখবি না আঁধার?আমার কথার কোনো মূল্য নেই তোর কাছে?"\n\nঅপূর্ব শিকদারের কথায় ফের ওনার দিকে ফিরে চাইলো আঁধার। ফিচেল হেঁসে, তাচ্ছিল্য সুরে বলে\n-"যার কাছে আমার কোনো মূল্য নেই, তার কথা আমি কেন ভাবতে যাবো!"\n\nবলেই সামনে হাঁটা দিলো আঁধার।অপূর্ব শিকদার অসহায় দৃষ্টি নিবদ্ধ করলেন ছেলের পানে।চক্ষু দুটো ক্রমশ ঝাপসা হয়ে আসলো তার।বুকের টন*টনে ব্যা*থা নিমিষেই ছড়িয়ে পরলো পুরো শরীরে।শরীরের ব্যালেন্স রাখতে না পেরে পা দু''টো কাঁপতে শুরু করলো। বুকে হাত দিয়ে, চোখ-মুখ খিঁ*চে বসে পরলেন অপূর্ব শিকদার। \nচাঁদনী দেখতেই ছুটে এলো তার কাছে।হাটু মুড়ে বসে ধরলো ওনাকে।একে একে সবাই ছুটে এলো ওনার কাছে।সবার চিৎকার চেঁচামেচিতে আঁধারের পা থেমে যায়।পিছনে ফিরে চাইলো ও।দেখলো, অপূর্ব শিকদার মেঝেতে লুটিয়ে পরেছেন।আঁধারের হৃৎপিণ্ড ছলকে উঠে। আ*তঙ্কিত দৃষ্টিতে তাকিয়ে ছুটে এলো ও।সবাইকে সরিয়ে অপূর্ব শিকদারের মাথাটা নিজের কোলে নিলো। ভ*য়ার্ত দৃষ্টিতে তাকিয়ে গালে হাত ঘষে বললো\n\n-"বাবা, বাবা কী হয়েছে তোমার?"\n\nঅপূর্ব শিকদারের চোখ উল্টে আসে।আঁধারের বুক ধ্বক করে উঠলো।কন্ঠ শৃঙ্গে তুলে চেঁচিয়ে বললো \n-"কেও ডক্টর ডাকো না! বাবা, বাবা....\n-"আম্ মার চাঁদ মা''কে বি্য়ে করবিনা তুই!এভাবে বিয়ের আসরে ফেলে চলে্ গেলে যে ওর জীবনটা শেষ হয়ে যাবে!"\n\nঅনেক কষ্টে টেনে টেনে বললেন অপূর্ব শিকদার।আঁধারের হৃৎপিণ্ড তখন তড়িৎ বেগে লাফাচ্ছে। একাধারে বাবা বাবা করে ডেকে যাচ্ছে ও।অপূর্ব শিকদার বহু ক*ষ্টে আবার প্রশ্ন ছুড়লেন ছেলের উদ্দেশ্যে।আধার চোখ বন্ধ করে বড় বড় শ্বাস ফেললো। অপূর্ব শিকদারের মাথায় হাত বুলিয়ে দিয়ে শান্ত করার চেষ্টা করে বললো \n\n-"চুপ করো বাবা।প্লিজ চুপ করো।হাইপার হয়ে যাচ্ছো তুমি!"\n-"আগে বল তুই বিয়েটা করবি কি-না?"\n \nঅকূল পাথারে পড়লো আঁধার। আশেপাশে অসহায় দৃষ্টি বুলিয়ে আবার চিৎকার করে বললো \n-"ডক্টর আসছে না কেন এখনো?"\n-"আমার প্রশ্নের উত্তর দে! নয়তো আমি মরেও শান্তি পাবো না।"\n\nআহাজারি করে বললেন অপূর্ব শিকদার। চোখ দু''টো কিয়ৎক্ষণ বন্ধ করে মেললো আঁধার।নিজের বাবার আহাজারি সহ্য হলো না ওর।পলক ঝাপটে হড়বড় করে বললো\n-"করবো বিয়ে! তুমি যাকে বলবে তাকেই বিয়ে করবো!"\n,\n\nডক্টর এসে অপূর্ব শিকদারের চেকআপ করে গেছেন। জানিয়ে গেছেন অতিরিক্ত টেনশন সহ্য করতে পারেননি।আগে থেকেই যেহেতু ওনার হার্টে প্রবলেম ছিলো,তাই অতিরিক্ত হাইপার হওয়া ওনার জন্য ভালো না।ভাগ্যক্রমে আজ তিনি বেঁচে গেছেন, অতটা আঘাত হয়নি।তবে ওনাকে যাতে সর্বদা চিন্তামুক্ত রাখা হয়।\nঅনেকটা সময় কেটে গেছে।অপূর্ব শিকদারের এখন খানিকটা ভালো লাগছে।আঁধার এখনো জড়িয়ে ধরে বসে আছে তাঁকে।ভ*য়ে, আ*তঙ্কে ঘেমে-নেয়ে একাকার অবস্থা ওর।পরিবারের সবাই, আগত অতিথিরা সবাই ঘিরে দাঁড়িয়ে আছে তাকে। অপূর্ব শিকদার পিটপিট করে চোখ খুললেন।সোফার উপর থেকে ভারী মাথাটা তোলার চেষ্টা করলেন।আধারের খেয়ালে আসতেই অশান্ত হয়ে উঠলো ও। তড়িঘড়ি করে বললো\n\n-"বাবা, ঠিক লাগছে তোমার?"\n-"তুই বলেছিস চাঁদ মা কে বিয়ে করবি!এখন তোর কথা রাখার পালা।"\n\nনিম্নস্বরে বললেন অপূর্ব শিকদার।আঁধার কপালে ভাজ ফেলে তাকালো।ব্যগ্র স্বরে বললো\n-"উফ!এই এক কথা কতবার বলবা?"\n-"যতক্ষণ না বিয়ে করতে বসবি ততক্ষণ।কথার খেলাপ করবি না আধার! নয়তো আমার ম*রা মুখ দেখবি তুই!"\n-"বাবা...\n\nচিল্লিয়ে উঠলো আঁধার।মুখ ছোট করে বসলেন অপূর্ব শিকদার।আঁধার একপলক তাকালো ভয়ে জুবুথুবু হয়ে আকিব শিকদারের পাশে দাঁড়িয়ে থাকা চাঁদনীর দিকে।নাকটা সিকেয় তুলে এগিয়ে গেলো ও।শক্ত করে চাঁদনীর হাত আঁকড়ে ধরে, ট্রলি ব্যাগের ন্যায় টেনে নিয়ে গেলো ওঁকে স্টেজের দিকে।টেনেহিঁচড়ে স্টেজে তুলে ছুড়ে মারলো ওঁকে সোফার উপর।গলা উঁচিয়ে ডাকলো কাজি সাহেব কে।ডাক শুনতেই কাজি সাহেব দ্রুত পায়ে উঠলেন স্টেজে।আঁধার ক্রো*ধান্বিত স্বরে গলার স্বর উচিয়ে বললো\n\n-"এক্ষুনি বিয়ে পড়ান,কাজি সাহেব। এই মুহুর্তেই বিয়েটা হবে!" \n-"আমি তোমাকে বিয়ে করবো না দাদাভাই!"\n\nচাঁদনীর কান্নাভেজা কন্ঠ কানে বাজতেই পেছন ফিরে তাকালো আঁধার।ভ্রু কুঁচকে বললো\n\n-"কী বললি!"\n-"আমি তোমাকে বিয়ে করবো না!"\n-"কেন করবি না?"\n-"কারণ তুমি আমাকে না পারতে বিয়ে করছো!মন থেকে করছো না!"\n\nব্য*ঙ্গ করে বিকট শব্দে হাসলো আঁধার।চাঁদনী অবাক দৃষ্টিতে তাকালো।ওঁর মতো কালো মেয়েকে বিয়ে করার শোকে কী ছেলেটা পাগল হয়ে গেছে!নয়তো যে ছেলে এতোটা সময় রেগে আগুন হয়ে ছিলো, সে ছেলে এখন গা কাঁপিয়ে হাসছে।\nঅনেক কষ্টে নিজের হাসি থামালো আঁধার।চাঁদনীর অবাক দৃষ্টির দিকে তাকিয়ে তাচ্ছিল্য করে বললো\n\n-"এটিটিউড দেখাচ্ছিস তাই না! ঐ যে প্রথমে রিজেক্ট করেছিলাম সেটার প্রতিশোধ নেওয়ার চেষ্টা করছিস! কিন্তু তোর তো সে ক্ষমতা নেই রে, আমাকে রিজেক্ট করার। নিজের মুখ আয়নায় দেখে, নিজের অবস্থান জেনে তারপর আমার পাঙ্গা নিতে আসবি।আমাকে যে বিয়ে করছিস পারছিস, সেটা তোর সাত কপালের ভাগ্য।নেহাত বাবার এই অবস্হা, তাই বিয়ে করতে বাধ্য হচ্ছি তোকে।নয়তো আমাদের বাড়ির ড্রাইভারটাও তোকে বিয়ে করতে রাজি হবে না।কারণ তার গায়ের রং তোর চেয়ে দশগুণে উজ্জ্বল!"\n\nবিমূঢ় দৃষ্টিতে তাকিয়ে থাকলো চাঁদনী।ভেজা চটচটে গালদুটো নিমিষেই লজ্জায়,অপমানে লাল হয়ে উঠলো।প্রতিউত্তর করতেও যেন ভুলে বসলো ও।\nআঁধার ফের তাগাদা দিয়ে বললো \n-"কাজি সাহেব, আপনি আপনার কাজ শুরু করুন।"\n\nচাঁদনী নাকচ করার সময়টুকু পেলো না।আঁধারের বি*শ্রী অপমানে সেই ইচ্ছে বা শক্তি দুটোই হারিয়ে গেলো ওর। একে একে স্টেজে এগিয়ে আসলো সবাই। আঁধারকে হতভম্ব করে দিয়ে এতোক্ষণ চোখ দু''টো টেনে খুলতে না পারা অপূর্ব শিকদারও দিব্যি হেঁটে এলেন।আঁধার আশ্চর্যান্বিত দৃষ্টিতে, ভ*ঙ্গুর পাথর হয়ে তাকিয়ে থাকলো তার দিকে।অপূর্ব শিকদার আসতেই তাগাদা দিলেন জলদি বিয়ে পড়ানোর জন্য। স্তব্ধ, বিমূঢ় হয়ে দাঁড়িয়ে থাকা আঁধারের দিকে চোখ পরতেই আমতা আমতা করে হাসলেন তিনি।আঁধারের মেজাজ সপ্তমে চড়লো।অপূর্ব শিকদারের দিকে অগ্নি দৃষ্টিতে তাকিয়ে, চিবিয়ে চিবিয়ে বললো\n\n-"বাহ!সুস্থ হয়ে গেছো এতো জলদি! আমিতো ভেবেছিলাম কয়েকদিন বিছানা ছেড়েই উঠতে পারবে না।"\n-"সব দয়ালের ইচ্ছে!" \n\nদু-হাত উপরে তুলে নাটকীয় ভঙ্গিতে বললেন অপূর্ব শিকদার।ক্রোধান্বিত আঁখি তে তাকিয়ে থাকলো আঁধার।শাণিত স্বরে বললো\n\n-"ভাবছি তোমাকে ঢালিউডে, ভিলেন চরিত্রে ভর্তি করিয়ে দিব।ঐ যে নায়িকার বাপ, চৌধুরী সাহেব থাকে না, সে চরিত্রে! নাটক তো দেখি ভালোই পারো!" দাঁত দেখিয়ে হাসলেন তিনি।\n\nকাজি সাহেব বিয়ে পড়ানো শুরু করলেন।আঁধারকে কবুল বলতে বললেই সেকেন্ডে গড়গড়িয়ে তিন কবুল বলে দিলো সে।এবার কাজি সাহেব কনে তথা চাঁদনী কে কবুল বলতে বললেন।চাঁদনী একপলক আকিব শিকদারের দিকে তাকালো।আকিব শিকদার অপরাধী দৃষ্টিতে তাকালেন ওর দিকে।\nচাঁদনী মনে মনে নিজের মৃত মা কে স্মরণ করলো।তবে সে সময়টুকুও ধৈর্য ধরতে পারলো না আঁধার। দৃষ্টি নত করে রাখা চাঁদনীর দিকে তাকিয়ে ধমকে উঠে বললো\n\n-"কীরে তুই আবার এটিটিউড দেখাচ্ছিস? কবুল বলতে এতো সময় লাগে?"\n\nআঁধারের বাজখাঁই কন্ঠে ভ*য়ের চোটে ধরফরিয়ে কবুল বললো চাঁদনী। তিন কবুল বলতেই আঁধার উঠে দাঁড়ালো। কোনোদিক না তাকিয়ে সোজা স্টেজ ছেড়ে চলে গেলো।পেছনে রেখে গেলো স্তব্ধ হয়ে বসে থাকা বয়োজ্যেষ্ঠ মানুষগুলো কে।সাথে লাল লেহেঙ্গা পরিহিত একটি মেয়ে, নববধূ।যে চোখে হাজারো স্বপ্ন নিয়ে এই জায়গাটিতে এসেছিলো, আঁধারের নামে কবুল বলেছিলো।তার স্বপ্ন চূ*র্ণবি*চূর্ণ হয়ে ভে*ঙে যাওয়ার দায়ভার কি হনহনিয়ে চলে যাওয়া পুরুষটি নেবে!\n\n#কাজলরেখা \n#পর্ব:০১\n#তানজিনা ইসলাম\n\n#চলবে','\n',char(10)),1,'published',0,'2026-10-29 11:18:54','2026-10-29 11:18:54',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('853ab029-cdd8-4778-9fae-4f4c4e083f46','c4b7dd5c-d4f0-4324-af5f-725d78c6fd88','মির্জার বিষাক্ত মায়া পর্ব -১',replace('মা আমার মাহি কে বলো চোখ খুলতে বলো মা বলো ও কী ভাবে আমাকে রেখে যাওয়ার সীদ্ধান্ত নিলো ওর এতো সাহস কথা থেকে আসে আমি আরহান মির্জা বেঁচে থাকা অবস্থায় ও কখনো আমাকে রেখে যেতে পারে না মাহি চোখ খোল বউ আমার এই বলে ইহান হাউ মাউ করে কান্না করতে থাকে..\n\n__এ দেখে আরহান মির্জার মা আফরিন বেগম কান্নায় ভেঙ্গে পড়েন, তিনি আরহান কে কখনো দেখেননি এ ভাবে কান্না করতে তার ছেলে এতো কঠিন সময় এ-ও কখনোই এ ভাবে ভেঙ্গে পড়ে নি কিন্তু আজ তার ছেলে কে এতো-টা অসহায় হয়ে পড়ে দেখে আফরিন বেগম-এর  বুক পেটে কান্না আসে\n\n.......................\n\nআরহান মির্জা; আফরিন বেগম - আলতাফ মির্জার বড়ো ছেলে এবং বাড়ির বড় ছেলে হওয়ায় পরিবারের সবার আদরের কিন্তু তার  স্বভাব ছিলো ভীষণ রাগী তার সিদ্ধান্ত সবাই এক কথায় মেনে নেয় বাড়ির ছোট-রা থাকে ভীষণ ভয় পেত...\n\n আজ ৬ বছর পর মির্জা বাড়ির বড়ো ছেলে বাড়িতে পা রাখছে এতে সবাই অনেক খুশি সবাই সবার মতো কাজ করছে ছোট্ট চাচি পপি বেগম আর মেজো চাচি ফারজানা বেগম রান্নার কাজে ব্যস্ত আফরিন বেগম নিজের ছেলে আসার খুশিতে ছেলের গড় ঘুচাতে ব্যস্ত \n\n\n---বড় মা ভাই কেনো এতো বছর দেশে আসেনি...?\n\nআহনাফ এর এমন প্রশ্ন শোনে আফরিন বেগম এ-র মুখের হাসি  ক্ষণিক এর সময় এর জন্য চলে যায় তিনি কথা ঘুরিয়ে বলেন..\n\n শুনো বাবা এটা অনেক লম্বা কাহিনি তোমাকে অন্য এক দিন বলবো যাও এখন তোমার আয়রা আপু কে ডেকে নিয়ে আসো\n\n\nআহনাফ আবার আসলো \n\nবড় মা আপুমণি-কে অনেক ডেকেছি আপুমণি ঘুমাচ্ছে \nআপু বলছে আরেক বার ডাকলে আমার মাথা কে*টে রেখে দিবে..\n\nএই মেয়েটা কে নিয়ে আর পারি না\n\nতিনি আয়রা কে ডাকার জন্য চলে যান \n\nনিছ থেকে আওয়াজ আসছে \n\nবড় মা ছোট মা মেজো মা বাবা কে কোথায় আছো দেখে যাও ভাইয়া আসছে \n\nসবাই বসার গড়ে এসে দেখে ইহান ওরফে আরহান মির্জা চলে এসেছে \n\nআফরিন বেগম ছেলেকে দেখে কান্না শুরু করে দেন এটা দেখে আলতাফ মির্জা বলেন\n\n---ওই শুরু হয়ে গেলো আমার গিন্নি কান্না বলি ছেলে টা বাড়িতে শুধু আসেছে আরহান কে ওর গড়ে নিয়ে যাও\nআরহান গড়ে আসে এসে দেখে ৬ বছর আগে যেমন রেখেছিলো ঠিক তেমনি রয়েছে \n.......\n\nশাওয়ার নিয়ে এসে শুধু বিছানায় বসেছে আহনাফ এবং আশরাফ আসে \n\n---ভাইয়া একটা কথা বলি...? \n\n---হুম \n\n---আমাদের জন্য কী আনেছো...? \n\n--- কী আনবো তদের জন্য...? \n\n---কিছু আনো নাই ভাইয়া..?\n\nআরহান ঠোঁট বেঁকিয়ে হাসে \n\n---আরে আমার যে দুই-টা রামছাগল আছে ও-ই টা কী ভাবে ভুলে যাবো বল..?\n\nআহনাফ এবং আশরাফ এক সাথে বলে উঠে\n\n---ভাইয়া আমরা রামছাগল না আমাদের গিফট গুলো দাও আমরা চলে যাচ্ছি \n\nআরহান তাঁদের একটা লাগেজ দেখিয়ে দেয়\n\nআশরাফ এবং আহনাফ চলে যাওয়ার পর আরহান মনে মনে ভাবছে\n\n---৬ বছর আগের কাহিনী এখন আবার পুনরাবৃত্তি হবে ফুফি আর সেটা শেষ করার জন্য-ই আমি আজ দেশে এসেছি ....\n\n.....\n\n\n পাখিরা সামনে কী যাবো....?','\n',char(10)),1,'published',0,'2026-10-29 13:00:58','2026-10-29 13:00:58',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('ab36cddd-75e9-4934-b7eb-0126d6e1c46d','c4b7dd5c-d4f0-4324-af5f-725d78c6fd88','মির্জার বিষাক্ত মায়া পর্ব -২',replace('সবাই খাবার টেবিল এ বসে আছে পপি বেগম বলেন\n\nনূরাহ যা তো মা আরহান আর আয়রা কে ডেকে নিয়ে আয়\n\nনূরাহ যায় আয়রা আর আরহান কে ডেকে নিয়ে আসতে\n\nআরহান এর দরজা সামনে এসে নূরাহ বলে \n\n---ভাইয়া আসবো..?\n\n---হুম আয় \n\n--- ভাইয়া মা তোমাকে ডাকছে নিচে খাবার খেতে \n\n--- তুই যা আমি আসছি\n\nনূরাহ আয়রা কে ডাকতে যায় \n\n---এই আয়রার বাচ্চা দরজা খুল ম*রার মতো আর কতো ঘুমাবি দুপুর হয়েছে উঠ মা আমার উঠ \n\nআয়রা ঘুম ঘুম চোখ এ বলে \n\n\n---আপু আর পাঁচ মিমিট \n\n---আর এক মিনিট ও না উঠ আয়রা ভাইয়া চলে আসছে \n\nআয়রা এক লাফে বিছানা থেকে উঠে বলে \n\n---কী ভাইয়া আসছে কখন কবে আর তোমরা আমাকে ডাকো নি কেনো \n\n--- তুই যেই ম*রার মতো ঘুমাচ্ছিলি বড় মা তকে ডেকে গেলেন \n এটা শুনে আয়রা এক দূর দিয়ে আরহান এর রোম এ যায় \n\n---ভাইয়া \n\nআরহান এতো জুড়ে ডাকার জন্য ভয় পেয়ে যায় \n\n--- ও মা গো বাঁচাও পেত্নী টা আমাকে মেরে ফেলল  \n\n--- ভাইয়া এমন করো না আমি পেত্নী না আচ্ছা তুমি কখন আসছো আমাকে ডাকো নি কেনো\n\n---তুই দেখেছিস কখনো মানুষ পেত্নী কে ডাকে\n\nএটা শুনে আয়রা রাগ করে পেলে \n\n---আচ্ছা বাবা সরি রাগ করিস না পুচকি ফ্রেশ হয়ে আয় নিচে খাবার খাবো\n\n---আচ্ছা তুমি যাও আমি আসছি\n\nসবাই খাবার টেবিলে বসে খাবার খাচ্ছে তখন আলতাফ মির্জা বলেন \n\n---ইহান...? \n\n---হুম বাবা বলো \n \n---কয় দিন এর জন্য আসছো আব্বু\n\n--- জানি না আব্বু যদি ভালো লাগে তাহলে বেশি দিন থাকবো না হয় তিন মাস পর চলে যাবো\n\nএই শুনে ইফতেখার মির্জা বলেন \n\n--- শুনো বাবা আসছো আর যেও না আমাদের বয়স বাড়ছে তোমরা ভাইরা ও বড় হয়েছো এখন একটু আমাদের ব্যবসার সামলাও \n\n--- কেন চাচ্চু ইভান, আয়ান,  আলভী এরা তো আছে ব্যবসা দেখবে \n\nইভান,আয়ান,আলভী শুনে বলে\n\n---ভাইয়া প্লিজ আমাদের কে ছেড়ে দাও তুমি ব্যবসা সামলাও আমরা তোমার সাথে আছি \n\nআলভী বলে \n\n---ভাইয়া ব্যবসা আমার মাথায় ঢুকে না তুমি সামলাও আমরা তোমার সাথে কাজ করবো\n\nআরহান বলে \n\n--- ঢুকবে কী ভাবে আমি দেশে ছিলাম না  বলে যা ইচ্ছা করেছো তিন ভাই কী ভাবো আমি কিছু জানি না...? \n\nআয়ান এটা শুনে মুখ থেকে খাবার পড়ে যায় \n\n---ভাইয়া আমরা কাল থেকেই কাজ এ যাব তুমি বললে এখন-ই যাবো কিন্তু প্লিজ কিছু বলো না বাবারা আছে\n\n\n..............\n\n\nমির্জা পরিবার অনেক বড় মির্জা পরিবার এর সবার বড়ো\n\n আলতাফ মির্জা  এবং আফরিন বেগম  এর  এক ছেলে এক মেয়ে আরহান মির্জা বয়স ২৮ - আয়রা মির্জা বয়স ১৮\n\nদ্বিতীয় :ইফতেখার মির্জা এবং পপি বেগম এর দুই ছেলে ও এক মেয়ে  আয়ান মির্জা বয়স ২৬ - আলভী মির্জা বয়স ২৪ \n ও মেয়ে নূরাহ মির্জা বয়স - ২০\n\n\nতৃতীয় : জফরুল মির্জা এবং ফারজানা বেগম এর দুই জমজ ছেলে আশরাফ মির্জ বয়স ১২ া-আহনাফ মির্জা বয়স ১২ \n\nচতুর্থ : ফারুক মির্জা এবং লিজা বেগম এর এক ছেলে ইভান বয়স-২৩\n\nতারা চার ভাই এর এক বোন ইয়াসমিন বেগম - ফিরোজ রহমান এর দুই মেয়ে এবং এক ছেলে জান্নাত রহমান বয়স ১৮ \nমাহিরা রহমান ১৭  ছেলে অরবিন রহমাম ২৬\n\n\nচলবে...?','\n',char(10)),2,'published',0,'2026-10-29 13:14:36','2026-10-29 13:14:36',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('6b60a187-e2c8-4793-9f61-7ffc6ea7780d','c4b7dd5c-d4f0-4324-af5f-725d78c6fd88','মির্জার বিষাক্ত মায়া পর্ব -৩',replace('আরহান অরবিন কে কল দেয় \n\n---অরবিন কোথায় আছিস \n\n--- বাড়িতে ভাইয়া কেনো কোনো দরকার না-কি ভাইয়া...?\n\n---হ্যাঁ আমি ইভান,আলভী, আয়ান একটু বাহিরে যাবো তুই চলে আয় \n\n---আচ্ছা ভাইয়া আসছি\n\n---আচ্ছা শুন...?\n\n---হুম ভাইয়া বলো \n\n--- মাহি কেমন আছে....?\n\n---আলহামদুলিল্লাহ ভাইয়া ভালো আছে\n\n\n---ফুফি জান্নাত সবাই কেমন আছে....?\n\n---আলহামদুলিল্লাহ ভাইয়া\n\n---একটা কাজ করবি অরবিন...?\n\n---অবশ্য-ই ভাইয়া বলো কী কাজ....? \n\n---আসার সময় মাহি আর জান্নাত কে নিয়ে আসবি...?\n\n---আচ্ছা ভাইয়া\n\nতার পর আরহান মির্জা খুব সুন্দর একটি  চেক স্কাই ব্লু  শার্ট  পড়ে এবং সাদা পেন্ট পড়ে সাথে Dior এর Sauvage পারফিউম লাগান আরহান মির্জা \n\nঅরবিন আরহান কে কল দেয় \n\n--- ভাইয়া তোমরা কোথায়....? \n\n---জ্যাম এ একটু পেশে গেছি রে সালার দেশে এই অবস্থার জন্য-ই বিরক্ত লাগে বা-ল টা কখন যে আমার sunshine   কে দেখবো \n\n--- ভাইয়ার আর  ধৈর্য খুলাচ্ছে না তাই না ভাই হায় আপসোস আজ যদি আমার একটা সানশাইন থাকতো \n\n--- বেয়াদব চুপ কর আমি তর বড় ভাই \n\n---বড় ভাই আরে  তাই নাকি দুই দিন  পর হবেন আমার ছোট বোন এর জামাই আর আমি আপনার সমনধিক হবো \n\n---আজাইরা কথা রাখ ভাই আমি আসছি \n\n---ওকে বায়\n\nমাহি অরবিন কে প্রশ্ন উপর প্রশ্ন করছে\n\n---এই ভাইয়া কার জন্য অপেক্ষা করছি বলো না প্লিজ \n\n--- আরে ডেমরি চুপ থাক না আসলে দেখতে পারবি\n\n--- আচ্ছা ছেলে না মেয়ে আসবে...?\n\n--- ছেলে\n\n---দেখতে কেমন...? \n\n--- সুন্দর \n\n--- নায়ক দের মতো...? \n\n---আরে "হ" রে বইন \n\n--- ভাইয়া শেষ প্রশ্ন...? \n\n---তর শেষ প্রশ্ন আর শেষ হবে না বইন বল\n\n---যদি বেশি সুন্দর হয় ওরে কিন্তু আমার উনি বানিয়ে দিস\n\nঅরবিন একটুও অবাক হলো না সে জানে তার বোন কেমন অনেক চনচল ছেলেদের দেখলে একটু ফ্ল্যাট করে কিন্তু প্রেম করে না \nঅরবিন মনে মনে বলল\n\n--- যেই ছেলে ৬ টা বছর তর জন্য উন্মাদ হয়ে আছে তকে দেখার জন্য পাগল হয়ে আছে তকে পাওয়ার জন্য কতো-টা কষ্ট করছে থাকে  ওর করে দিব কী পাগল তুই বইনা \n\n--- আচ্ছা বইন এখন চুপ থাক আর মাথা টা খাস না \n\nজান্নাত অরবিন কে বলল \n\n--- আচ্ছা ভাইয়া আমাদের পরিবার কী আর এক হবে না...?\n\n---জানি না রে, ভাইয়া তো এ-র জন্য-ই দেশ এ এসেছে দেখা যাক কী হয় \n\nএর মাঝে গাড়ি হন বাজলো অরবিন,  জান্নাত, মাহিরা,গাড়ির কাছে গেল তখন দেখলো ছয় ফুট উচ্চতার সুদর্শন পুরুষ আরহান মির্জা। উজ্জ্বল ফর্সা গায়ের রং, ধারালো চোয়াল, ঘন কালো চুল আর সুঠাম দেহের অধিকারী সে। তার গভীর অলিভ গ্রিন চোখে মিশে আছে সোনালি আভা, যার দৃষ্টিতে লুকিয়ে থাকে এক অদ্ভুত রহস্য , পড়নে স্কাই ব্লু শার্ট সাদা পেন্ট দেখতে আকর্ষণীয় লাগছে \n\nকিশোরী মাহিরার মনে যেন ঝড় বয়ে গেল  এতো  সুদর্শন পুরুষ যার চোখ এর দিখে থাকে হৃদয় থেমে যায় কখনো ভয় আবার কখনো ডুবে যায়\n\nতার ঠোঁট বেঁকিয়ে হাসি টা যেন মাহিরার মনে তীর এর মতো গেথে যাচ্ছে\n\nতার এক ভ্রু উঁচু করে কথা বলাটা যেন মাহিরার খুব পছন্দ হয়েছে\n\n\nচলবে....💋','\n',char(10)),3,'published',0,'2026-10-29 14:18:24','2026-10-29 14:18:24',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('342cce85-11a9-4e94-9e55-11b4d318d5a0','b98c6429-e76f-4896-8621-fd2d226b335c','পর্ব:২',replace('৳মাফিয়া কিংয়ের পাগল করা ভালোবাসা \n#লেখিকা: হুমাইরা জান্নাত \n#পর্ব: ০২\n\nপর্বের নাম: প্রতিশোধের প্রথম চাল 🥀\n\nসকালের আলো জানালা দিয়ে ঘরে প্রবেশ করতেই নীলার ঘুম ভাঙল। বিছানা থেকে উঠে মোবাইল হাতে নিয়ে সে দেখল, তার ভাই নাহিয়ানের বারোটা মিসড কল!\n\nনীলা চোখ বড় বড় করে বলল,\n\n“হায় আল্লাহ! ভাইয়া আমাকে এতগুলো কল দিয়েছে! আজকে মনে হয় আমার কপালে দুঃখ আছে!”\n\nতাড়াতাড়ি ফোন করতেই ওপাশ থেকে নাহিয়ানের রাগী কণ্ঠ ভেসে এল।\n\n“মহামান্য রাজকন্যার ঘুম কি শেষ হয়েছে?”\n\nনীলা হেসে বলল, “আরে ভাইয়া, এত রাগ করছ কেন? আমি তো ঘুমাচ্ছিলাম!”\n\n“কাল রাতে বাসায় ফিরে বলেছিলি, সকালে তাড়াতাড়ি উঠবি। এখন বাজে দশটা!”\n\n“তো কী হয়েছে? সূর্য কি আমার জন্য অপেক্ষা করছিল?”\n\n“নীলা!”\n\n“আচ্ছা, আচ্ছা! আর বকবক করতে হবে না। নিচে আসছি।”\n\nফোন রেখে নীলা দ্রুত তৈরি হয়ে নিচে নেমে এল।\n\nডাইনিং টেবিলে বসে ছিলেন তার বাবা মাহবুব রহমান। বাবাকে দেখেই নীলা হাসিমুখে কাছে গিয়ে জড়িয়ে ধরল।\n\n“গুড মর্নিং, বাবা!”\n\nমাহবুব মেয়ের মাথায় হাত বুলিয়ে বললেন, “গুড মর্নিং, মা। কালকের অনুষ্ঠান কেমন লাগল?”\n\nনীলা মুখ বাঁকিয়ে বলল, “অনুষ্ঠান ভালোই ছিল। কিন্তু একটা অসহ্য লোকের সঙ্গে দেখা হয়ে সব মাটি!”\n\nনাহিয়ান হেসে বলল, “ওহ! আমাদের রাজকন্যার আবার কার সঙ্গে দেখা হলো?”\n\nনীলা রাগী চোখে তাকিয়ে বলল, “ভাইয়া, তুমি হাসছ কেন? লোকটা নিজেকে কী মনে করে কে জানে! একটু জুস পড়েছিল তার শার্টে, আর এমনভাবে তাকাচ্ছিল যেন আমি তার পুরো হোটেল কিনে নিয়েছি!”\n\nমাহবুব রহমানের হাতের চায়ের কাপ কেঁপে উঠল।\n\n“লোকটার নাম কী, নীলা?”\n\nনীলা একটু ভেবে বলল, “আরহান খান।”\n\nনামটা শুনেই মাহবুবের মুখ ফ্যাকাশে হয়ে গেল।\n\nনাহিয়ান বাবার দিকে তাকিয়ে বলল, “বাবা, কী হয়েছে তোমার?”\n\nমাহবুব নিজেকে সামলে নিয়ে বললেন, “কিছু না। তোমরা নাশতা করো।”\n\nকিন্তু তাঁর মনের ভেতর তখন বহু বছর আগের এক ভয়ংকর রাতের স্মৃতি ফিরে এসেছে।\n\nঅন্যদিকে—\n\nআরহান খানের বিশাল অফিস।\n\nকাঁচের জানালার সামনে দাঁড়িয়ে শহরের দিকে তাকিয়ে আছে আরহান। তার হাতে নীলার একটি ছবি।\n\nরায়ান সামনে দাঁড়িয়ে বলল, “স্যার, নীলাঞ্জনা রহমান সম্পর্কে যতটুকু তথ্য পাওয়া গেছে, সব এই ফাইলে আছে।”\n\nআরহান ছবিটির দিকে তাকিয়ে শীতল কণ্ঠে বলল, “মেয়েটা দেখতে যতটা সরল, তার পরিবারের ইতিহাস ততটাই জটিল।”\n\nরায়ান কিছুক্ষণ চুপ থেকে বলল, “স্যার, একটা কথা বলব?”\n\n“বলো।”\n\n“আপনি কি নিশ্চিত, মাহবুব রহমানই আপনার পরিবারের সঙ্গে যা ঘটেছে তার জন্য দায়ী?”\n\nআরহান ধীরে ধীরে রায়ানের দিকে ফিরে তাকাল।\n\n“তুমি কি আমাকে শেখাবে কাকে বিশ্বাস করতে হবে?”\n\nরায়ান মাথা নিচু করল।\n\n“না, স্যার। আমি শুধু চাই না, পুরোনো কোনো ভুলের জন্য আপনি নতুন করে ভুল সিদ্ধান্ত নিন।”\n\nআরহান কিছুক্ষণ চুপ করে রইল। তারপর টেবিলের ওপর রাখা পুরোনো ছবিটি হাতে তুলে নিল।\n\n“আমার বাবাকে হারানোর পর এই মানুষটা আমাদের পাশে দাঁড়ায়নি। আমার পরিবার ধ্বংস হয়ে গেছে, আর সে নিজের জীবন নিয়ে সুখে আছে। এবার আমার পালা।”\n\n“কী করতে চান, স্যার?”\n\nআরহানের ঠোঁটে শীতল হাসি ফুটে উঠল।\n\n“মাহবুব রহমানের সবচেয়ে প্রিয় জিনিসটা কী, রায়ান?”\n\n“তার মেয়ে নীলাঞ্জনা।”\n\n“ঠিক ধরেছ।”\n\nরায়ান অবাক হয়ে তাকাল।\n\nআরহান ধীর কণ্ঠে বলল, “আমি মেয়েটার ক্ষতি করতে চাই না। অন্তত এখনই নয়। আমি চাই, মাহবুব নিজের অতীতের মুখোমুখি হোক। আর তার জন্য নীলাঞ্জনাকে আমার জীবনে আনতেই হবে।”\n\nবিকেল ৪টা।\n\nনীলা নিজের ঘরে বসে গান শুনছিল। হঠাৎ নিচ থেকে কাজের মেয়ের ডাক এল।\n\n“আপু, আপনার জন্য একজন ভদ্রলোক এসেছেন!”\n\nনীলা বিরক্ত হয়ে বলল, “কে আবার? ভাইয়াকে বলো, আমি এখন কারও সঙ্গে দেখা করব না!”\n\nকিন্তু নিচে নেমে ড্রয়িংরুমে পা রাখতেই তার চোখ কপালে উঠে গেল।\n\nসোফায় বসে আছে সেই অসহ্য লোকটা!\n\nকালো শার্ট, হাতে দামি ঘড়ি, মুখে সেই একই গম্ভীর অভিব্যক্তি।\n\nআরহান খান!\n\nনীলা অবিশ্বাসের সুরে বলল, “আপনি এখানে কী করছেন?”\n\nআরহান ধীরে উঠে দাঁড়াল।\n\n“তোমার বাবার সঙ্গে কিছু কথা আছে।”\n\n“তাহলে বাবার সঙ্গে কথা বলুন। আমার দিকে এভাবে তাকিয়ে আছেন কেন?”\n\nআরহান মৃদু হেসে বলল, “তোমার কথা বলার ধরনটা বেশ সাহসী।”\n\nনীলা ভ্রু কুঁচকে বলল, “আর আপনার ব্যবহারটা বেশ অসহ্য!”\n\nঠিক তখনই মাহবুব রহমান ঘরে প্রবেশ করলেন। আরহানকে দেখেই তাঁর মুখের রং বদলে গেল।\n\n“তুমি এখানে কেন এসেছ, আরহান?”\n\nআরহান ধীরে ধীরে তাঁর দিকে এগিয়ে গেল।\n\n“আপনার সঙ্গে পুরোনো কিছু হিসাব মেলাতে এসেছি, মিস্টার রহমান।”\n\nমাহবুব কঠিন কণ্ঠে বললেন, “যা হয়েছে, তা বহু বছর আগের কথা। সেই অধ্যায় আবার খুলতে এসো না।”\n\n“অধ্যায়টা আপনি বন্ধ করেছেন। আমি তো এখনো শেষ পৃষ্ঠাটাও পড়িনি!”\n\nনীলা অবাক হয়ে দুজনের দিকে তাকাল।\n\n“বাবা, তোমরা একে অপরকে চেনো?”\n\nকেউ তার প্রশ্নের উত্তর দিল না।\n\nআরহান পকেট থেকে একটি খাম বের করে টেবিলে রাখল।\n\n“আগামীকাল সন্ধ্যা সাতটায় আমার অফিসে আসবেন। না এলে, আপনার অতীতের সেই গোপন কথাগুলো প্রকাশ্যে চলে আসবে।”\n\nমাহবুব রাগে কাঁপতে কাঁপতে বললেন, “আমাকে হুমকি দিচ্ছ?”\n\nআরহান শান্তভাবে উত্তর দিল, “এটাকে হুমকি নয়, শেষ সুযোগ ভাবুন।”\n\nকথাটা বলে সে দরজার দিকে এগিয়ে গেল। যাওয়ার আগে নীলার দিকে ফিরে তাকাল।\n\n“আবার দেখা হবে, নীলাঞ্জনা রহমান।”\n\nনীলা মুখ বাঁকিয়ে বলল, “আশা করি, আর দেখা হবে না!”\n\nআরহান মৃদু হাসল।\n\n“সেটা তোমার হাতে নেই, সুন্দরী।”\n\nদরজা বন্ধ হয়ে গেল।\n\nনীলা বাবার কাছে ছুটে এসে বলল, “বাবা, লোকটা কে? তোমাদের মধ্যে কী হয়েছে?”\n\nমাহবুব মেয়েকে বুকে টেনে নিলেন। তাঁর চোখে তখন গভীর আতঙ্ক।\n\n“নীলা, একটা কথা মনে রাখিস। আরহান খানের কাছ থেকে যতটা সম্ভব দূরে থাকবি।”\n\n“কিন্তু কেন, বাবা?”\n\nমাহবুব কোনো উত্তর দিলেন না।\n\nশুধু মনে মনে বললেন, যে সত্যিটা এত বছর ধরে লুকিয়ে রেখেছি, সেটা যদি আরহান জানতে পারে, তাহলে দুই পরিবারের জীবন আবারও ধ্বংস হয়ে যাবে।\n\nঅন্যদিকে, গাড়িতে বসে আরহান নীলার কথা ভাবছিল।\n\nমেয়েটার সাহসী চোখ, রাগী মুখ আর অদ্ভুত হাসিটা বারবার তার মনে ভেসে উঠছিল।\n\nসে বিরক্ত হয়ে চোখ বন্ধ করল।\n\n“কী হচ্ছে আমার? একটা মেয়ের কথা এত ভাবছি কেন?”\n\nঠিক তখনই তার ফোনে একটি অচেনা নম্বর থেকে বার্তা এল।\n\nবার্তায় লেখা—\n\n“মাহবুবকে শাস্তি দেওয়ার আগে নিজের বাবার মৃত্যুর সত্যিটা জেনে নাও। নীলাঞ্জনা তোমার শত্রু নয়, আরহান। সে তোমার অতীতের সবচেয়ে বড় রহস্যের অংশ!”\n\nবার্তাটি পড়ে আরহানের চোখ কঠিন হয়ে উঠল।\n\n“রায়ান! এই নম্বরের মালিককে খুঁজে বের করো। এখনই!”\n\nফোনটা হাতে নিয়ে সে আবার বার্তাটির দিকে তাকাল।\n\nপ্রথমবারের মতো তার মনে প্রতিশোধের পাশাপাশি একটা প্রশ্ন জেগে উঠল—\n\nনীলাঞ্জনা রহমান কি সত্যিই তার শত্রুর মেয়ে, নাকি তার জীবনের হারিয়ে যাওয়া কোনো সত্যের চাবিকাঠি?\n\nচলবে… 🖤🥀','\n',char(10)),2,'published',0,'2026-10-29 16:26:00','2026-10-29 16:26:00',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('239ee0bd-bc4d-4fa2-bf9d-d4d55920ab91','90a23f6f-1b22-44ae-9e70-6132ca169bfa','পর্ব : ১',replace('৩০৭ নম্বর কক্ষ\n\nএকটি রহস্যময় উপন্যাস\n\nলেখক: Unique Writer\n\nযে ঘরে কেউ থাকে না\n\nরাত ১১টা ৪৭ মিনিট।\n\nবাইরে প্রচণ্ড বৃষ্টি হচ্ছে। আকাশের ঘন কালো মেঘের ভেতর থেকে মাঝে মাঝে বিদ্যুৎ চমকে উঠছে। শহর থেকে প্রায় চল্লিশ কিলোমিটার দূরে, পাহাড় আর ঘন জঙ্গলে ঘেরা একটি পুরোনো হোটেলের সামনে এসে থামল একটি কালো গাড়ি।\n\nহোটেলটির নাম— রয়্যাল হেরিটেজ।\n\nএকসময় এই হোটেলে শহরের ধনী ব্যবসায়ী, রাজনীতিবিদ আর বিদেশি পর্যটকদের আনাগোনা ছিল। কিন্তু সতেরো বছর আগে ঘটে যাওয়া একটি ঘটনার পর থেকে হোটেলটির সুনাম ধীরে ধীরে হারিয়ে যায়।\n\nস্থানীয় মানুষেরা বলে, হোটেলটির তৃতীয় তলায় ৩০৭ নম্বর একটি কক্ষ আছে, যেখানে রাত বারোটার পর কেউ প্রবেশ করে না।\n\nকারণ, সেই কক্ষে প্রবেশ করা শেষ মানুষটিকে আর কখনো দেখা যায়নি।\n\nগাড়ির দরজা খুলে নামল পঁচিশ বছর বয়সী আরিয়ান রহমান। হাতে একটি কালো ব্যাগ, চোখে ক্লান্তি, আর মুখে এমন এক অভিব্যক্তি—যেন সে কোনো জায়গায় বেড়াতে আসেনি, এসেছে বহুদিনের পুরোনো একটি হিসাব মেটাতে।\n\nহোটেলের প্রধান দরজা খুলে একজন বৃদ্ধ কর্মচারী বেরিয়ে এলেন।\n\n“আপনি কি রুম বুক করেছিলেন, স্যার?”\n\nআরিয়ান পকেট থেকে একটি পুরোনো খাম বের করল।\n\n“আমার নামে একটা বুকিং থাকার কথা।”\n\nবৃদ্ধ খামটির দিকে তাকাতেই তাঁর মুখের রং বদলে গেল।\n\n“এই চিঠি... আপনি কোথায় পেলেন?”\n\n“ডাকযোগে পেয়েছি। কে পাঠিয়েছে, জানি না। শুধু এই ঠিকানাটা লেখা ছিল।”\n\nবৃদ্ধ কিছুক্ষণ চুপ করে থেকে বললেন, “আপনার নাম কী?”\n\n“আরিয়ান রহমান।”\n\nনামটি শুনে বৃদ্ধের হাত কেঁপে উঠল।\n\n“অসম্ভব!”\n\nআরিয়ান ভ্রু কুঁচকে তাকাল।\n\n“কী অসম্ভব?”\n\nবৃদ্ধ কোনো উত্তর দিলেন না। তিনি দ্রুত খামটি ফিরিয়ে দিয়ে হোটেলের ভেতরে চলে গেলেন।\n\nআরিয়ান তাঁর পিছু নিল।\n\nরিসেপশনের দেয়ালে একটি বড় ঘড়ি ঝুলছে। ঘড়ির কাঁটা এগিয়ে যাচ্ছে ধীরে ধীরে। দেয়ালের এক পাশে পুরোনো অতিথিদের কয়েকটি সাদা-কালো ছবি। ছবিগুলোর দিকে তাকাতে তাকাতে হঠাৎ থমকে গেল আরিয়ান।\n\nএকটি ছবির নিচে লেখা—\n\n“১৯ বছর আগে, রয়্যাল হেরিটেজের প্রতিষ্ঠাবার্ষিকী।”\n\nছবির এক কোণে দাঁড়িয়ে থাকা ছোট্ট ছেলেটিকে দেখে তার বুকের ভেতরটা কেমন যেন করে উঠল।\n\nছেলেটি দেখতে অবিকল তার ছোটবেলার মতো।\n\nকিন্তু ছবির তারিখ অনুযায়ী তখন তার বয়স হওয়ার কথা মাত্র ছয় বছর। আর ছবির পেছনে দাঁড়িয়ে থাকা লোকটির মুখ সে চিনতে পারল।\n\nতার বাবা।\n\nযে মানুষটি সতেরো বছর আগে নিখোঁজ হয়েছিলেন।\n\nআরিয়ান ছবিটি দেয়াল থেকে নামিয়ে বৃদ্ধ কর্মচারীর সামনে ধরল।\n\n“এই ছবিটা এখানে কীভাবে এল?”\n\nবৃদ্ধ চোখ নামিয়ে বললেন, “স্যার, দয়া করে এসব নিয়ে প্রশ্ন করবেন না।”\n\n“আমার বাবা এখানে এসেছিলেন?”\n\nবৃদ্ধ নীরব।\n\n“আমার বাবা কোথায় হারিয়ে গিয়েছিলেন, সেটা জানেন আপনি?”\n\nএবার বৃদ্ধ ধীরে ধীরে মুখ তুললেন।\n\n“আপনি যদি নিজের ভালো চান, তাহলে আজ রাতেই এই হোটেল ছেড়ে চলে যান।”\n\n“কেন?”\n\nবৃদ্ধের ঠোঁট কেঁপে উঠল।\n\n“কারণ আপনার বাবা নিখোঁজ হননি, স্যার।”\n\nআরিয়ান যেন নিজের কানকে বিশ্বাস করতে পারল না।\n\n“তাহলে?”\n\nবৃদ্ধ কিছু বলার আগেই হোটেলের তৃতীয় তলা থেকে একটি বিকট শব্দ ভেসে এল।\n\nধড়াম!\n\nতারপরই শোনা গেল একজন নারীর চিৎকার।\n\nআরিয়ান সিঁড়ির দিকে দৌড় দিল।\n\n“স্যার! দাঁড়ান!”\n\nবৃদ্ধের চিৎকার উপেক্ষা করে সে তৃতীয় তলায় উঠে গেল। লম্বা করিডোরের শেষ মাথায় একটি দরজা।\n\nদরজার গায়ে পিতলের ফলক—\n\n৩০৭।\n\nদরজাটি সামান্য খোলা।\n\nআরিয়ান ধীরে ধীরে দরজার কাছে গিয়ে ভেতরে তাকাল।\n\nঘরটি সম্পূর্ণ অন্ধকার। জানালার পর্দা বাতাসে দুলছে। মেঝেতে পড়ে আছে একটি পুরোনো কালো টেলিফোন। দেয়ালে ঝুলে থাকা আয়নাটির ওপর লাল কালিতে লেখা—\n\n“তুমি অবশেষে ফিরে এসেছ, আরিয়ান।”\n\nআরিয়ানের বুকের ভেতরটা হিম হয়ে গেল।\n\nঘরে সে একা নয়।\n\nবিছানার পাশে রাখা কাঠের টেবিলে একটি চিঠি পড়ে আছে। চিঠির ওপর তার নাম লেখা।\n\nকাঁপা হাতে চিঠিটি খুলল সে।\n\nভেতরে মাত্র তিনটি লাইন—\n\n“তোমার বাবা বেঁচে আছেন।\n\nতবে তাঁকে খুঁজে পাওয়ার আগে তোমাকে জানতে হবে, সতেরো বছর আগে ৩০৭ নম্বর কক্ষে ঠিক কী ঘটেছিল।\n\nআর মনে রেখো—এই হোটেলে কাউকে বিশ্বাস করবে না।”\n\nচিঠির নিচে একটি স্বাক্ষর।\n\nআরিয়ান রহমান।\n\nনিজের নাম দেখে সে স্তব্ধ হয়ে গেল।\n\nকারণ চিঠিটি লেখা হয়েছে আজ থেকে সতেরো বছর আগে।\n\nআর স্বাক্ষরটি তার নিজের।\n\nকিন্তু সতেরো বছর আগে তার বয়স ছিল মাত্র আট বছর।\n\n২ পর্ব...\n\n— Unique Writer','\n',char(10)),1,'published',0,'2026-10-29 17:20:43','2026-10-29 17:20:43',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('b2c4486d-c8c1-497d-9048-c492540a7d4d','b83dde16-d997-4cb8-85e6-a792492117eb','পর্ব : ১',replace('গল্প: চিঠির বাক্স  | পর্ব : ১\n\nচট্টগ্রাম বিশ্ববিদ্যালয়ে ভর্তির প্রথম দিনেই আদনান লাইব্রেরির পেছনে একটা পুরোনো কাঠের বাক্স খুঁজে পেল। ওপরে লেখা—\n"যা বলতে পারোনি, এখানে রেখে যাও"\n\nমজা করেই সে একটা চিঠি লিখে ভেতরে রেখে দিল—\n"আমি এখানে কাউকে চিনি না, খুব একা লাগছে।"\n\nপরদিন এসে দেখে, কেউ উত্তর দিয়ে গেছে—\n"একা তুমি একা নও, আমি রোজ দুপুরে এখানে আসি। - ন"\n\nএভাবেই শুরু। কোনো নাম নেই, দেখা নেই। শুধু আদনান আর ''ন'' এর চিঠি।\n\nতিন মাস চলল এভাবে। আদনান আর না দেখে থাকতে পারল না। লিখল—\n"কাল বিকেল ৪টায় লাইব্রেরির সামনের কৃষ্ণচূড়া গাছের নিচে নীল পাঞ্জাবি পরে থাকব, তুমি আসবে?"\n\nপরদিন নীল পাঞ্জাবি পরে ঠিক ৪টায় দাঁড়িয়ে রইল আদনান। কেউ এলো না। ৫টা বেজে গেল। মন খারাপ করে চলে যাওয়ার সময় বাক্সে একটা চিঠি পেল—\n"আমি এসেছিলাম, কিন্তু সাহস হয়নি সামনে আসার। তুমি যখন গাছের নিচে দাঁড়িয়ে ছিলে, আমি লাইব্রেরির দোতলার জানালা থেকে দেখছিলাম। তোমাকে খুব সুন্দর লাগছিল।"\n\nআদনান রাগ করে লিখল— "দেখা না করলে আর লিখব না।"\n\nদুই দিন কোনো চিঠি এলো না।\n\nতৃতীয় দিন বাক্সে একটা মোটা খাম। ভেতরে অনেকগুলো চিঠি আর একটা ছোট চাবি। সাথে একটা চিরকুট—\n"আমি নাফিসা, বাংলা দ্বিতীয় বর্ষ। আমার পায়ে সমস্যা, হুইলচেয়ারে চলি। তাই সামনে আসতে ভয় পেয়েছিলাম, যদি তুমি পছন্দ না করো। যদি সাহস থাকে, লাইব্রেরির পেছনের আর্কাইভ রুমে এসো, চাবিটা ওখানে লাগবে।"\n\nআদনান দৌড়ে গেল আর্কাইভ রুমে। দরজা খুলে দেখে, জানালার পাশে হুইলচেয়ারে বসে আছে একটা মেয়ে, কোলে সেই চিঠির বাক্সটা।\n\nমেয়েটা মুখ তুলে বলল— "তুমি দেরি করলে কেন? আমি তিন দিন ধরে অপেক্ষা করছি।"\n\nআদনান কিছু বলল না, তার পাশে বসে পড়ল। বলল— "এখন থেকে আর বাক্সে নয়, সামনাসামনি লিখব, হবে?"','\n',char(10)),1,'published',0,'2026-10-29 17:21:33','2026-10-29 17:21:33',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('67119e03-78e8-479e-9b1e-ef9184162ef7','b83dde16-d997-4cb8-85e6-a792492117eb','পর্ব : ২',replace('চিঠির বাক্স - পর্ব ২: আর্কাইভ রুমের পর\n\nআর্কাইভ রুমে সেদিনের পর থেকে সব বদলে গেল।\n\nআদনান এখন আর চিঠির বাক্সে চিঠি রাখে না। সে রোজ আর্কাইভ রুমে আসে। নাফিসা জানালার পাশে বই পড়ে।\n\nএকদিন আদনান জিজ্ঞেস করল— "তুমি রোজ এখানে কেন আসো?"\n\nনাফিসা হাসল— "এই রুমে কেউ আসে না। সবাই ভাবে এটা ভূতের ঘর। তাই এখানে আমার কেউ ডিস্টার্ব করে না। আমি একা থাকতে ভালোবাসি।"\n\nআদনান বলল— "আর এখন? আমি তো ডিস্টার্ব করি।"\n\nনাফিসা বলল— "তুমি ডিস্টার্ব না, তুমি অভ্যাস হয়ে গেছো।"\n\nএরপর থেকে তাদের নতুন নিয়ম হলো। রোজ একজন একটা করে শব্দ বলবে, আরেকজন সেটা দিয়ে একটা বাক্য বানাবে।\n\nআদনান বলল— "কৃষ্ণচূড়া"\nনাফিসা বলল— "কৃষ্ণচূড়ার নিচে তোমার নীল পাঞ্জাবিটা এখনো আমার চোখে ভাসে।"\n\nনাফিসা বলল— "অপেক্ষা"\nআদনান বলল— "তোমার জন্য অপেক্ষা করতে আমার একটুও কষ্ট হয় না।"\n\nএভাবে চলতে চলতে বর্ষাকাল এলো।\n\nএকদিন খুব বৃষ্টি। ভার্সিটি প্রায় ফাঁকা। আদনান আর্কাইভ রুমে এসে দেখে নাফিসা নেই। তার হুইলচেয়ারটা খালি পড়ে আছে, টেবিলের ওপর একটা ভেজা চিঠি।\n\n"আদনান, আজ আমার অপারেশন। ডাক্তার বলেছে, যদি অপারেশন সফল হয়, আমি হাঁটতে পারব। যদি না হয়, আর কখনো... যাই হোক, যদি আমি ফিরে না আসি, চিঠির বাক্সটা তুমি রেখে দিও। আর যদি ফিরে আসি, তাহলে কৃষ্ণচূড়া গাছের নিচে আমি দাঁড়িয়ে থাকব, হুইলচেয়ার ছাড়া। — নাফিসা"\n\nআদনান চিঠি হাতে নিয়ে দৌড়ে বাইরে এলো। বৃষ্টিতে ভিজে কৃষ্ণচূড়া গাছের নিচে দাঁড়িয়ে রইল।\n\nতিন দিন পর।\n\nবৃষ্টি থেমেছে। আদনান গাছের নিচে এসে দেখে, দূর থেকে একটা মেয়ে খুঁড়িয়ে খুঁড়িয়ে হেঁটে আসছে। নীল শাড়ি, হাতে সেই কাঠের বাক্সটা।\n\nনাফিসা। হুইলচেয়ার ছাড়া।\n\nআদনান কিছু বলতে পারল না। শুধু গিয়ে বাক্সটা ধরল।\n\nনাফিসা কাঁদতে কাঁদতে বলল— "বলেছিলাম না, একদিন দাঁড়িয়ে থাকব? এখন বলো, আমাকে কেমন লাগছে?"\n\nআদনান বলল— "তোমাকে আজ প্রথমবারের মতো পূর্ণ লাগছে।"\n\nনাফিসা বলল— "তাহলে এখন থেকে এই বাক্সে আর কষ্টের চিঠি রাখব না, শুধু সুখের চিঠি রাখব, রাজি?"\n\nআদনান বলল— "রাজি। প্রথম সুখের চিঠিটা আমিই রাখব— ''আজ থেকে নাফিসা আর একা নয়''।"','\n',char(10)),2,'published',0,'2026-10-29 17:21:33','2026-10-29 17:21:33',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('89f0a45a-e621-45b5-a5fd-994443b2795f','b83dde16-d997-4cb8-85e6-a792492117eb','পর্ব : ৩',replace('চিঠির বাক্স - পর্ব ৩ (শেষ পর্ব)\n\nঅপারেশনের পর নাফিসা হাঁটতে পারছে, কিন্তু খুব বেশি হাঁটতে পারে না। বেশি হাঁটলে পায়ে ব্যথা করে।\n\nএই জন্য আদনান এখন একটা নতুন কাজ করে। রোজ বিকেলে সে নাফিসার হাত ধরে ক্যাম্পাসের কৃষ্ণচূড়া গাছ থেকে লাইব্রেরি পর্যন্ত হাঁটায়। একটু একটু করে।\n\nএকদিন নাফিসা বলল— "আচ্ছা আদনান, আমি যদি কোনোদিন হাঁটতে না পারতাম, তুমি কি তাও আমাকে ভালোবাসতে?"\n\nআদনান বলল— "আমি তো তোমাকে হাঁটা দেখে ভালোবাসিনি, তোমার চিঠি পড়ে ভালোবেসেছি। তুমি হুইলচেয়ারে থাকলেও আমি বাক্সের পাশে বসে থাকতাম।"\n\nনাফিসা চুপ করে রইল। তার চোখে পানি।\n\nসেদিন ছিল তাদের শেষ সেমিস্টার। ভার্সিটি শেষ। আদনান চাকরির জন্য ঢাকায় চলে যাবে, নাফিসা চট্টগ্রামে থাকবে।\n\nযাওয়ার আগের দিন আদনান লাইব্রেরির পেছনে গেল। সেই পুরোনো কাঠের বাক্সটা এখনো আছে, কিন্তু ভেতরে আর কেউ চিঠি রাখে না।\n\nসে ভেতরে শেষ একটা চিঠি রাখল—\n"নাফিসা, এই বাক্সটা এখানেই থাক। যদি কখনো আমাদের মতো কেউ একা বোধ করে, সে যেন এখানে এসে লিখতে পারে। আর হ্যাঁ, আমি ঢাকায় গিয়েও রোজ তোমাকে চিঠি লিখব, কিন্তু খামে করে।"\n\nনাফিসা পেছন থেকে এসে বলল— "খামে কেন?"\n\nআদনান পেছনে তাকিয়ে দেখে নাফিসা দাঁড়িয়ে। হাতে একটা ছোট বাক্স — ঠিক আগের বাক্সটার মতো, কিন্তু নতুন।\n\nনাফিসা বলল— "এটা তোমার জন্য বানিয়েছি। তুমি ঢাকায় নিয়ে যাবে। যখন আমার কথা মনে পড়বে, এটাতে চিঠি লিখবে। আর আমি এখানে পুরোনো বাক্সটাতে তোমার উত্তর লিখে রাখব।"\n\nআদনান বাক্সটা নিল। দুজনেই হাসল।\n\nদুই বছর পর।\n\nচট্টগ্রাম বিশ্ববিদ্যালয়ের লাইব্রেরির পেছনে এখনো সেই পুরোনো বাক্সটা আছে। নতুন জুনিয়ররা সেখানে চিঠি রাখে। কেউ জানে না, এই বাক্স থেকেই একটা প্রেমের গল্প শুরু হয়েছিল।\n\nআর ঢাকার একটা ছোট বাসায়, আদনানের টেবিলে এখনো একটা নতুন কাঠের বাক্স থাকে। প্রতিদিন অফিস থেকে ফিরে সে সেখানে একটা করে চিঠি রাখে— "আজও তোমাকে মিস করেছি।"\n\nআর চট্টগ্রামে, নাফিসা তার পুরোনো বাক্স খুলে সেই চিঠির উত্তর লেখে।\n\nতাদের ভালোবাসা এখন আর একটা গাছ বা একটা লাইব্রেরিতে আটকে নেই, দুটো বাক্সের মধ্যে বেঁচে আছে।\n\nশেষ।','\n',char(10)),3,'published',0,'2026-10-29 17:21:33','2026-10-29 17:21:33',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('78ac2fc0-2a30-48a7-9363-47c701232083','90a23f6f-1b22-44ae-9e70-6132ca169bfa','শেষ পর্ব',replace('৩০৭ নম্বর কক্ষ\n\nএকটি রহস্যময় উপন্যাস\nলেখক: Unique Writer\n\nদ্বিতীয় অধ্যায় : \nকিন্তু সতেরো বছর আগে তার বয়স ছিল মাত্র আট বছর।\n\nআরিয়ান চিঠিটা হাতে নিয়ে স্থির হয়ে দাঁড়িয়ে রইল। বাইরে বৃষ্টির শব্দ, ঘরের ভেতর পুরোনো টেলিফোনের পাশে জমে থাকা ধুলো আর আয়নায় লেখা সেই বাক্য—সবকিছু যেন তাকে ঘিরে ধরেছে।\n\n“তুমি অবশেষে ফিরে এসেছ, আরিয়ান।”\n\nহঠাৎ পেছন থেকে দরজাটা বন্ধ হয়ে গেল।\n\nধড়াম!\n\nআরিয়ান ঘুরে দাঁড়াল। দরজার বাইরে থেকে তালা লাগানোর শব্দ পাওয়া গেল।\n\n“কে ওখানে?” সে চিৎকার করল।\n\nকোনো উত্তর এল না।\n\nঠিক তখনই টেবিলের ওপর পড়ে থাকা কালো টেলিফোনটা বেজে উঠল।\n\nট্রিং... ট্রিং...\n\nআরিয়ান ধীরে ধীরে রিসিভার তুলল।\n\nওপাশ থেকে ভেসে এল কাঁপা কণ্ঠস্বর।\n\n“আরিয়ান... তুমি কি এসেছ?”\n\nআরিয়ানের বুকের ভেতরটা কেঁপে উঠল।\n\n“কে আপনি?”\n\nকিছুক্ষণ নীরবতা। তারপর সেই কণ্ঠ বলল, “আমার গলার স্বর কি তুমি ভুলে গেছ?”\n\nআরিয়ান রিসিভারটা শক্ত করে ধরল।\n\n“বাবা?”\n\nওপাশ থেকে দীর্ঘশ্বাসের শব্দ এল।\n\n“আমার হাতে সময় খুব কম। মন দিয়ে শোনো। ঘরের উত্তর দিকের দেয়ালে একটা কাঠের আলমারি আছে। ওটার পেছনে একটা দরজা। দরজাটা খুঁজে বের করো।”\n\n“আপনি কোথায়? আপনি কি সত্যিই বেঁচে আছেন?”\n\n“হ্যাঁ, বাবা। কিন্তু এখন আমাকে খুঁজতে এসো না। আগে সত্যিটা জানো। আর মনে রেখো, তোমার সামনে যে মানুষটাকে নিরীহ মনে হচ্ছে, সে-ই হয়তো সবকিছুর জন্য দায়ী।”\n\nলাইনটা কেটে গেল।\n\nআরিয়ান কয়েকবার “বাবা! বাবা!” বলে ডাকল। কিন্তু টেলিফোনের ওপাশে তখন শুধু একটানা শোঁ শোঁ শব্দ।\n\nসে দ্রুত আলমারিটার কাছে গেল। অনেক চেষ্টা করে সেটি একটু সরাতেই পেছনে একটা ছোট লোহার দরজা দেখা গেল। দরজার গায়ে মরচে ধরা তালা।\n\nটেবিলের ড্রয়ার খুলে সে একটা চাবি পেল। চাবিটা তালায় ঢোকাতেই দরজা খুলে গেল।\n\nভেতরে সরু অন্ধকার পথ।\n\nআরিয়ান মোবাইলের আলো জ্বালিয়ে এগিয়ে গেল।\n\nকয়েক পা যেতেই তার চোখে পড়ল দেয়ালে ঝোলানো পুরোনো কিছু ছবি, কয়েকটি নথি আর একটি ছোট কাঠের বাক্স। বাক্সের ওপর লেখা—\n\n“আরিয়ান রহমান—ব্যক্তিগত নথি।”\n\nসে বাক্স খুলল।\n\nভেতরে ছিল একটি পুরোনো ডায়েরি, কয়েকটি চিঠি এবং একটি ছবি। ছবিতে তার বাবা দাঁড়িয়ে আছেন হোটেলের মালিকের পাশে। ছবির পেছনে লেখা, “সত্য লুকিয়ে রাখা যায়, মুছে ফেলা যায় না।”\n\nআরিয়ান ডায়েরিটা খুলল।\n\nপ্রথম পাতায় তার বাবার হাতের লেখা—\n\n“যদি কোনো দিন আরিয়ান এই ডায়েরি খুঁজে পায়, তাহলে সে যেন জানে—তার বাবা স্বেচ্ছায় হারিয়ে যায়নি।”\n\nপরের পাতাগুলো পড়তে পড়তে আরিয়ানের চোখ বড় হয়ে গেল।\n\nসতেরো বছর আগে তার বাবা, মাহমুদ রহমান, এই হোটেলের হিসাবরক্ষক ছিলেন। হোটেলের তৎকালীন মালিকের অবৈধ আর্থিক লেনদেনের প্রমাণ তিনি খুঁজে পেয়েছিলেন। সেই প্রমাণ প্রকাশ করার আগের রাতে তাঁকে হোটেলের ৩০৭ নম্বর কক্ষে ডেকে পাঠানো হয়।\n\nসেই রাতেই তিনি নিখোঁজ হন।\n\nহোটেলের সবাইকে বলা হয়েছিল, তিনি টাকা আত্মসাৎ করে পালিয়ে গেছেন। কিন্তু ডায়েরিতে লেখা ছিল, তাঁকে হোটেলের নিচের গোপন কক্ষে আটকে রাখা হয়েছিল। কারণ, তিনি এমন কিছু নথি লুকিয়ে রেখেছিলেন, যা প্রকাশ পেলে হোটেলের মালিকের অপরাধ প্রমাণিত হতো।\n\nআরিয়ান আরও একটি চিঠি বের করল। চিঠির তারিখ সতেরো বছর আগের। নিচে লেখা ছিল তার নিজের নাম—“আরিয়ান রহমান”।\n\nকিন্তু লেখাটা তার নিজের ছিল না।\n\nচিঠির পাশে পেন্সিলে লেখা একটি ছোট্ট নোট তার চোখে পড়ল—\n\n“শিশুটির নাম ব্যবহার করো। কেউ সন্দেহ করবে না।”\n\nতার মাথায় যেন বজ্রপাত হলো।\n\nএই চিঠি সে লেখেনি। কেউ তার নাম ব্যবহার করে চিঠিটি তৈরি করেছিল, যাতে ভবিষ্যতে তাকে এই হোটেলে ফিরিয়ে আনা যায়। আর আয়নায় লেখা কথাগুলোও কোনো অলৌকিক ঘটনা নয়—কেউ আগে থেকেই তার আগমনের অপেক্ষায় ছিল।\n\nহঠাৎ পেছনে পায়ের শব্দ শোনা গেল।\n\nআরিয়ান ঘুরে দাঁড়াল।\n\nঅন্ধকার পথের মুখে সেই বৃদ্ধ কর্মচারী দাঁড়িয়ে আছেন।\n\n“আপনি!” আরিয়ান ক্ষুব্ধ কণ্ঠে বলল। “আপনি সব জানতেন, তাই না?”\n\nবৃদ্ধ ধীরে ধীরে মাথা নত করলেন।\n\n“হ্যাঁ, স্যার। আমি সব জানতাম।”\n\n“তাহলে এত বছর চুপ ছিলেন কেন? আমার বাবাকে কোথায় রেখেছেন?”\n\nবৃদ্ধের চোখ ভিজে উঠল।\n\n“আমি আপনার বাবাকে বাঁচাতে চেয়েছিলাম। কিন্তু তখন আমি খুব দুর্বল ছিলাম। হোটেলের মালিকের লোকজন আমাকে ভয় দেখিয়েছিল। আমি মুখ খুললে আপনার বাবাকে মেরে ফেলা হবে—এমন হুমকি দিয়েছিল।”\n\n“তাহলে আজ আমাকে এখানে আসতে দিলেন কেন?”\n\nবৃদ্ধ পকেট থেকে একটা ছোট চাবি বের করলেন।\n\n“কারণ আজ আর সেই মানুষটা নেই। পুরোনো মালিক মারা গেছেন। কিন্তু তাঁর অপরাধের প্রমাণ এখনও এই হোটেলের দেয়ালের মধ্যে লুকানো আছে। আর আপনার বাবা... তিনি এখনও এখানেই আছেন।”\n\nবৃদ্ধ দেয়ালের অন্য পাশে থাকা একটা লোহার দরজার দিকে এগিয়ে গেলেন। চাবি দিয়ে তালা খুলতেই ভেতর থেকে ক্ষীণ কাশির শব্দ এল।\n\nআরিয়ান দৌড়ে ভেতরে ঢুকল।\n\nছোট্ট একটা ঘর। একটা বিছানা, পাশে ওষুধের বোতল আর জানালাহীন দেয়াল। বিছানায় শুয়ে থাকা মানুষটির চুল প্রায় সাদা, মুখে গভীর ক্লান্তির ছাপ। তবু সেই চোখ দুটো আরিয়ানের পরিচিত।\n\n“বাবা!”\n\nমানুষটি ধীরে ধীরে চোখ খুললেন।\n\nকয়েক সেকেন্ড ছেলের মুখের দিকে তাকিয়ে থেকে তাঁর ঠোঁট কেঁপে উঠল।\n\n“আরিয়ান... আমার ছেলে!”\n\nআরিয়ান বাবার পাশে বসে তাঁর হাত ধরে ফেলল। এত বছর ধরে জমে থাকা প্রশ্নগুলো একসঙ্গে বেরিয়ে এল।\n\n“আপনি কোথায় ছিলেন? সবাই বলেছে আপনি পালিয়ে গেছেন। আমাকে একবারও খুঁজলেন না কেন?”\n\nমাহমুদ রহমানের চোখ বেয়ে পানি গড়িয়ে পড়ল।\n\n“আমি পালাইনি, বাবা। আমাকে বন্দি করে রাখা হয়েছিল। প্রথম কয়েক বছর পালানোর চেষ্টা করেছি। কিন্তু তারা আমাকে অন্য জায়গায় সরিয়ে নেওয়ার ভয় দেখাত, আর তোমার ক্ষতি করার হুমকি দিত। পরে অসুস্থ হয়ে পড়ি। এই বৃদ্ধ মানুষটা গোপনে আমাকে খাবার আর ওষুধ দিয়ে বাঁচিয়ে রেখেছে।”\n\nআরিয়ান বৃদ্ধের দিকে তাকাল। বৃদ্ধ মাথা নিচু করে দাঁড়িয়ে রইলেন।\n\n“কিন্তু আমাকে এখানে ডাকা হলো কেন?” আরিয়ান জিজ্ঞেস করল।\n\nতার বাবা বালিশের নিচ থেকে একটা ছোট ধাতব বাক্স বের করলেন।\n\n“কারণ আমি জানতাম, একদিন সত্যিটা প্রকাশ করার সময় আসবে। তোমাকে যে চিঠি পাঠানো হয়েছে, সেটা আমি লিখেছি। কিন্তু তোমার নামের নিচের স্বাক্ষরটা আমার করা নয়। ওটা করেছিল হোটেলের পুরোনো মালিকের লোকেরা, যেন তোমাকে বিভ্রান্ত করা যায়। তারা চেয়েছিল তুমি এখানে এসে ভয় পেয়ে ফিরে যাও। আমি চিঠির ভেতরে এমন কিছু সংকেত রেখেছিলাম, যা শুধু এই ডায়েরি আর নথিগুলোর সঙ্গে মিলিয়ে বুঝতে পারবে।”\n\n“তাহলে ওই নারীর চিৎকার?”\n\nবৃদ্ধ এবার উত্তর দিলেন।\n\n“ওটা ছিল রেকর্ড করা শব্দ। পুরোনো মালিক ভয় ছড়াতে চাইতেন, যাতে কেউ তৃতীয় তলার ওই ঘরে না আসে। কিন্তু আজ রাতে কেউ রেকর্ডটা চালু করেছে, যাতে আপনি ছুটে গিয়ে ৩০৭ নম্বর কক্ষে ঢোকেন। আসল নথিগুলোর পথ দেখানোর জন্য আপনার বাবা ওই ঘরে চিঠিটা রেখেছিলেন।”\n\nআরিয়ান কিছুক্ষণ চুপ করে রইল।\n\n“আর ছবিটা? সেখানে আমার ছোটবেলার মতো একটা ছেলেকে দেখলাম।”\n\nমাহমুদ রহমান দীর্ঘশ্বাস ফেললেন।\n\n“ছবিটা সত্যি, কিন্তু তারিখের ফলকটি পরে বদলে দেওয়া হয়েছিল। ওই অনুষ্ঠানে আমি তোমাকে একবার হোটেলে নিয়ে এসেছিলাম। তুমি তখন ছোট ছিলে। পুরোনো মালিক ছবিটা রেখে দিয়েছিলেন, কারণ তিনি জানতেন, একদিন তোমাকে ব্যবহার করে নিজের অপরাধের প্রমাণ মুছে ফেলতে চাইবেন। কিন্তু তিনি তা করতে পারেননি।”\n\nআরিয়ান বাবার হাতে থাকা ধাতব বাক্সটা খুলল। ভেতরে ছিল হিসাবের খাতা, স্বাক্ষর করা দলিল এবং কয়েকটি পুরোনো রেকর্ডিং। সবকিছুই হোটেলের মালিকের অপরাধের প্রমাণ।\n\n“এগুলো এত বছর লুকিয়ে রেখেছিলেন?”\n\n“হ্যাঁ। আমি জানতাম, সত্যি একদিন তোমার হাতে পৌঁছাবে।”\n\nঠিক তখনই দূরে সাইরেনের শব্দ শোনা গেল।\n\nআরিয়ান অবাক হয়ে বাবার দিকে তাকাল।\n\n“পুলিশ?”\n\nবৃদ্ধ বললেন, “আমি আগেই খবর দিয়েছিলাম। এত বছর ভয় পেয়েছি, কিন্তু আর চুপ থাকতে চাইনি।”\n\nকিছুক্ষণের মধ্যে পুলিশ হোটেলে পৌঁছাল। তারা গোপন কক্ষ থেকে মাহমুদ রহমানকে উদ্ধার করল এবং নথিগুলো জব্দ করল। তদন্তে পুরোনো মালিকের অপরাধের প্রমাণ পাওয়া গেল। যারা এত বছর ধরে সত্য লুকিয়ে রেখেছিল, তাদের বিরুদ্ধেও ব্যবস্থা নেওয়া হলো।\n\nভোরের আলো ফুটতে শুরু করেছে।\n\nহোটেলের সামনে দাঁড়িয়ে আরিয়ান বাবার হাত ধরে আছে। সতেরো বছরের অন্ধকার যেন ধীরে ধীরে কেটে যাচ্ছে।\n\nকিন্তু যাওয়ার আগে সে আরেকবার তৃতীয় তলায় উঠল।\n\n৩০৭ নম্বর কক্ষের দরজা এখন খোলা। আয়নার ওপরের লাল লেখাটা মুছে ফেলা হয়েছে। কালো টেলিফোনটা নিঃশব্দে টেবিলের ওপর পড়ে আছে।\n\nআরিয়ান ঘর থেকে বেরিয়ে দরজাটা বন্ধ করতে যাবে, ঠিক তখনই তার চোখ পড়ল দরজার ভেতরের দিকে খোদাই করা একটি বাক্যে—\n\n“সত্যের দরজা একবার খুললে, তাকে আর বন্ধ করা যায় না।”\n\nসে কিছুক্ষণ লেখাটার দিকে তাকিয়ে রইল।\n\nতারপর দরজাটা বন্ধ করে সিঁড়ির দিকে এগিয়ে গেল।\n\nবাইরে তখন বৃষ্টি থেমে গেছে। আকাশের এক কোণে সূর্যের আলো ফুটছে।\n\nসতেরো বছর ধরে যে রহস্য তাকে তাড়া করে বেড়িয়েছে, তার উত্তর সে পেয়েছে। বাবা ফিরে এসেছেন, অপরাধের প্রমাণ প্রকাশ পেয়েছে, আর ৩০৭ নম্বর কক্ষের ভয়াবহ রহস্যের অবসান ঘটেছে।\n\nতবু হোটেল থেকে বেরিয়ে যাওয়ার আগে আরিয়ান একবার পেছনে তাকাল।\n\nরয়্যাল হেরিটেজের তৃতীয় তলার জানালায় কেউ দাঁড়িয়ে নেই।\n\nকোনো চিৎকার নেই। কোনো অদ্ভুত শব্দ নেই।\n\nশুধু একটি পুরোনো হোটেল, যার দেয়ালের ভেতর চাপা পড়ে ছিল বহু বছরের সত্য।\n\nআরিয়ান বাবাকে নিয়ে গাড়িতে উঠে বসল।\n\nগাড়ি ধীরে ধীরে পাহাড়ি রাস্তা পেরিয়ে শহরের দিকে এগিয়ে গেল।\n\n৩০৭ নম্বর কক্ষের দরজা বন্ধ হলো।\n\nআর এবার, সত্যিই শেষবারের মতো।\n\nসমাপ্ত।\n\n— Unique Writer','\n',char(10)),2,'published',0,'2026-10-29 17:25:26','2026-10-29 17:25:26',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('36d8adca-7199-46b2-96e7-3274fd0ddac0','b83dde16-d997-4cb8-85e6-a792492117eb','শেষ পর্ব',replace('চিঠির বাক্স - পর্ব ৩ (শেষ পর্ব)\n\nঅপারেশনের পর নাফিসা হাঁটতে পারছে, কিন্তু খুব বেশি হাঁটতে পারে না। বেশি হাঁটলে পায়ে ব্যথা করে।\n\nএই জন্য আদনান এখন একটা নতুন কাজ করে। রোজ বিকেলে সে নাফিসার হাত ধরে ক্যাম্পাসের কৃষ্ণচূড়া গাছ থেকে লাইব্রেরি পর্যন্ত হাঁটায়। একটু একটু করে।\n\nএকদিন নাফিসা বলল— "আচ্ছা আদনান, আমি যদি কোনোদিন হাঁটতে না পারতাম, তুমি কি তাও আমাকে ভালোবাসতে?"\n\nআদনান বলল— "আমি তো তোমাকে হাঁটা দেখে ভালোবাসিনি, তোমার চিঠি পড়ে ভালোবেসেছি। তুমি হুইলচেয়ারে থাকলেও আমি বাক্সের পাশে বসে থাকতাম।"\n\nনাফিসা চুপ করে রইল। তার চোখে পানি।\n\nসেদিন ছিল তাদের শেষ সেমিস্টার। ভার্সিটি শেষ। আদনান চাকরির জন্য ঢাকায় চলে যাবে, নাফিসা চট্টগ্রামে থাকবে।\n\nযাওয়ার আগের দিন আদনান লাইব্রেরির পেছনে গেল। সেই পুরোনো কাঠের বাক্সটা এখনো আছে, কিন্তু ভেতরে আর কেউ চিঠি রাখে না।\n\nসে ভেতরে শেষ একটা চিঠি রাখল—\n"নাফিসা, এই বাক্সটা এখানেই থাক। যদি কখনো আমাদের মতো কেউ একা বোধ করে, সে যেন এখানে এসে লিখতে পারে। আর হ্যাঁ, আমি ঢাকায় গিয়েও রোজ তোমাকে চিঠি লিখব, কিন্তু খামে করে।"\n\nনাফিসা পেছন থেকে এসে বলল— "খামে কেন?"\n\nআদনান পেছনে তাকিয়ে দেখে নাফিসা দাঁড়িয়ে। হাতে একটা ছোট বাক্স — ঠিক আগের বাক্সটার মতো, কিন্তু নতুন।\n\nনাফিসা বলল— "এটা তোমার জন্য বানিয়েছি। তুমি ঢাকায় নিয়ে যাবে। যখন আমার কথা মনে পড়বে, এটাতে চিঠি লিখবে। আর আমি এখানে পুরোনো বাক্সটাতে তোমার উত্তর লিখে রাখব।"\n\nআদনান বাক্সটা নিল। দুজনেই হাসল।\n\nদুই বছর পর।\n\nচট্টগ্রাম বিশ্ববিদ্যালয়ের লাইব্রেরির পেছনে এখনো সেই পুরোনো বাক্সটা আছে। নতুন জুনিয়ররা সেখানে চিঠি রাখে। কেউ জানে না, এই বাক্স থেকেই একটা প্রেমের গল্প শুরু হয়েছিল।\n\nআর ঢাকার একটা ছোট বাসায়, আদনানের টেবিলে এখনো একটা নতুন কাঠের বাক্স থাকে। প্রতিদিন অফিস থেকে ফিরে সে সেখানে একটা করে চিঠি রাখে— "আজও তোমাকে মিস করেছি।"\n\nআর চট্টগ্রামে, নাফিসা তার পুরোনো বাক্স খুলে সেই চিঠির উত্তর লেখে।\n\nতাদের ভালোবাসা এখন আর একটা গাছ বা একটা লাইব্রেরিতে আটকে নেই, দুটো বাক্সের মধ্যে বেঁচে আছে।\n\nশেষ।','\n',char(10)),3,'published',0,'2026-10-29 17:25:48','2026-10-29 17:25:48',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('d6dfb829-447c-4aef-abc3-992286953751','adf22c21-71fa-41da-9263-a38c83efaa14','কাজল রেখা, লেখিকা :তানজিনা',replace('#কাজলরেখা \n#পর্ব:০২\n#তানজিনা ইসলাম\n\nকক্ষের অবস্থা বেহাল!সুনামি বয়ে গেছে যেন! দরজার সাথে পিঠ ঠেকিয়ে শিটিয়ে দাঁড়িয়ে আছে চাঁদনী!ভয়ে বুক কাঁপছে!একটু আগেই ওর কাজিনরা মিলে আঁধারের কক্ষে ঢুকিয়ে দিয়েছে ওঁকে। তবে কক্ষের অবস্থা কেমন তা বর্ণনার বাকি রাখে না।ড্রেসিংটেবিলের কাঁচ ভেঙে, ফুলদানির ভাঙা টুকরো ছড়িয়ে ছিটিয়ে পরে আছে মেঝেতে।ছেড়া কুশনের তুলো মেঝেতে বিছানো।কারো আগ্রাসী ভয়ঙ্কর রাগ যে সুন্দর কক্ষটার উপর দিয়ে বইয়ে গেছে তা অনুভব করতেই শিরদাঁড়ায় শীতলতা বইয়ে গেলো চাঁদনীর।\nসুন্দর কক্ষটি ধ্বংসস্তুপে পরিণত হয়েছে যেন। কক্ষের যে অবস্থা হয়েছে,একটু পর যে চাঁদনীর এ অবস্থা হবে না তার কী গ্যারেন্টি!কক্ষের মালিক নিজের পছন্দের কক্ষের এ অবস্থা করতে পারলে তাহলে ওর মতো অপছন্দের কী হাল করবে!\n\nবেলকনি থেকে কথার শব্দ ভেসে আসছে!চাঁদনী বুঝলো আঁধার ওখানেই আছে।তবুও এসব ভাঙা জিনিস মাড়িয়ে সামনে যাওয়ার সাহস হলো না ওর।\nআধারের কথা থেমে গেছে।গটগট পায়ে কক্ষে ঢুকছে ও।চাঁদনীর হৃদপিন্ডের ধুকপুকানি চুড়ান্ত হলো।বাইরে থেকে শোনা যাচ্ছে ওর হৃদপিণ্ড লাফানোর শব্দ।\nআঁধার কক্ষে আসতেই ওঁকে দেখে থেমে গেলো। হাতে মোবাইল ধরা।চাদনী কে দেখতেই মোবাইলটা ছুড়ে মারলো বিছানার উপর।দ্রত পায়ে চাঁদনীর কাছে এগিয়ে এলো আঁধার!\nচাঁদনীর বাহু আঁকড়ে ধরে ঠাস করে দেওয়ালের সঙ্গে বারি খাওয়ালো! চাঁদনীর মনে হলো ওর মেরুদন্ড হয়তো মড়মড় করে ভেঙে গেছে!আঁধার গলা চেপে ধরলো ওর! হিসহিসিয়ে বললো\n-"বেয়াদব! এতো শখ আমাকে বিয়ে করার।আমাকেই পেয়েছিলি গলায় ঝুলতে।যে গায়ের রং আর কেও বিয়ে করতো না তো তোকে,তাই পরিবারের সবাই মিলে আবার উপরই গছিয়ে দিয়েছে।"\n\nচাঁদনীর শ্বাস বন্ধ হয়ে এলো।চোখ উল্টে আসলেও টু শব্দ করলো না ও।ছেড়ে দেওয়ার আকুলতাও জানালো না!চাঁদনীর অবস্থা দেখে আঁধার নিজেই ছেড়ে দিলো ওঁকে। \nকাশতে কাশতে দেওয়ালে পিঠ ঠেকিয়ে বসে গেলো চাদনী!দু’আঙ্গুল দিয়ে চিন্তিত ভঙ্গিতে কপালে স্লাইড করলো আঁধার।শক্ত গলায় বললো\n-"অর্পিতা কোথায়? কার সাথে ভেগেছে ও?মেঝোমা বললো তুই সাহায্য করেছিস ওঁকে, এটা কী সত্যি? উত্তর দে।যদি এটা সত্যি হয় তোকে জিন্দা কবরে পুতবো আমি।এসব আগে থেকেই প্ল্যান ছিলো তোর তাই না?অর্পিতা কে পালাতে সাহায্য করে আমার সাথে বিয়ে করতে বসেছিস।জানতিস আর কারো রুচিতে ধরবে না তোকে।তাই ছলাকলা করে আমাকে বিয়ে করার জন্য বড়দের টোপ হিসেবে ব্যবহার করলি!"\n\nচাঁদনী দেওয়ালের সাথে পিঠ ঠেকিয়ে মেঝেতে বসে আছে!বুকে হাত দিয়ে জোরে জোরে শ্বাস নিচ্ছে মেয়েটা!\nআঁধার এক দৃষ্টে চেয়ে থাকলো চাঁদনীর দিকে!মেয়েটার অবস্থা দেখে একটুও কষ্ট হচ্ছে না ওর।উল্টো পৈশাচিক আনন্দ হচ্ছে বুকের ভেতর। আরেকটু কষ্ট দিতে পারলে ভালো লাগতো!\nআঁধারের এসব ভাবনার মাঝেই,আচমকাই উঠে বুকের উপর দু''হাতে ধাক্কা বসালো চাঁদনী।দু’পা দুরে সরলো আধার।অবাক হতেও ভুলে গেলো যেনো ও।একাধারে ফুঁসছে চাঁদনী!চোখদুটো লাল হয়ে আছে।সাথে কোটরে অশ্রুর উপস্থিতি। কাঁপতে কাঁপতে বললো\n\n-"নিজেকে কী মনে করেছো তুমি? সুন্দর একটা চেহারা আছে বলে যাই নয় তাই বলবে আমাকে।হ্যাঁ, আমি কালো।মানছি, মানছি।দোষ করেছি আমি কালো হয়ে জন্ম নিয়ে।এই সমাজে কালো দের ভালো ভাবে বেঁচে থাকার কোনো অধিকার নেই।আমি নিজের সব দোষ মাথা পেতে নিলাম।কিন্তু আমার কোনো ইচ্ছে ছিলো না তোমাকে বিয়ে করার।বড় বাবা হাত জোর করে অনুরোধ করেছে আমাকে।তার কথা ফেলতে পারিনি আমি।বড় অন্যায় করে ফেলেছি মানছি।কিন্তু!কিন্তু, তুমি কেন বিয়ে করলে?প্রথমে তো চলেই যাচ্ছিলে, যাওনি কেন? থেকে গিয়ে বিয়ে করলে কেন? সারাজীবন খোঁটা দিতে?তুমি ছেলে হয়ে নিজের পরিবারের মানুষগুলোকে মানাতে পারোনি, আমি মেয়ে হয়ে কী করে পারতাম! অর্পিতা আপুর সাথে আমার কেমন সম্পর্ক সেটাও জানো তুমি। সে আমাকে দু’চোখে সহ্য করতে পারে না, অথচ আমার থেকেই কিনা সাহায্য নেবে!সেটা সবাই বিশ্বাসও করছে।অপবাদ দেওয়ার বেলায় সবকটা@ ওস্তাদ। \nহাহ! সবাই পেয়েছো টা কী আমাকে? যার যা ইচ্ছা তা-ই।সবার কথা মুখ বুঁজে সহ্য করতে হবে? আমার কোনো ইমোশন নেই?আমি মানুষ না?পুতুলের মতো নাচাচ্ছো কেন সবাই মিলে?"\n\nচোখমুখ লাল হয়ে গেছে চাঁদনীর।চোখের কাজল লেপ্টে বিশ্রী অবস্থা হয়ে গেছে।আঁধার ভ্রু কুঁচকে তাকিয়ে থাকলো ওর দিকে।মেয়েটার কোনো কথায়ই প্রভাব ফেরতে পারলো না ওর উপর।অহংকারে বুদ আঁধার চাঁদনীর কষ্টের একাংশ ও অনুভব করতে পারলো না।শুধু গম্ভীর গলায় বললো\n\n-"এসব সেন্টি মারা কথা তুই নিজের কাছেই রাখ!তোকে কে কী বলে, কেন বলে এসব আমার ভাবার বিষয় না।ইট’স নট মাই রেসপন্সিবিলিটি! আমি তোকে কোনোদিন স্ত্রী হিসেবে মেনে নিতে পারবো না!স্ত্রী হওয়ার চেষ্টা করিসও না!"\n\n-"তোমার স্ত্রী হতে বয়ে গেছে আমার।নেহাত বড়বাবা তোমাকে বিয়ে করতে অনুরোধ করেছিলো আমাকে।যে মানুষটার কাছে ছোট থেকে বড় হয়েছি তার কথা ফেলতে পারিনি।নয়তো আমার বাপ-জেঠার কাছে কম টাকা নেই, একটা রাজপুত্রের মতো স্বামী পেতে বেশি কসরত পোহাতে হতো না আমাকে।"\n\n-"টাকা দিয়ে স্বামী কিনতি?"\n\n-"হু,কিনতাম।তাতে তোমার সমস্যা?"\n\n-"সে তো তোর সাথে টাকার জন্য থাকতো!তোকে ভালোবাসতো না!"\n\n-"এখনও বা কী ভালোবাসা পেয়ে উল্টে যাচ্ছি, বলো!"\n\nনিষ্প্রভ দৃষ্টিতে তাকিয়ে থাকলো আঁধার।দীর্ঘশ্বাস ফেলে বললো\n-"এই রুমে থাকবি?"\n\n-"হু!সবাই ঠেলেঠুলে এখানে পাঠিয়ে দিয়েছে।মেনে না নাও, বিয়েতো করেছো।নিজের ভাগ না দিলেও তোমার জিনিসের ভাগ দিতে হবে!"\n\n-"না দিলে কী করবি?"\n\n-"মামলা ঠুকবো!"\n\n-"কীসের?"\n\n-" নারী নির্যাতনের!"\n\n-"ডরাই না তোকে!আমাকে এতোটাও আন্ডারেস্টিমেট করিস না!"\n\n-"পুলিশের ডান্ডার বারি পরলেই ডরাবা!"\n\nআঁধার ছোট ছোট চোখে তাকিয়ে থাকলো।কুটিল হাসলো চাঁদনী !সামনে দাঁড়ানো আঁধার কে উপেক্ষা করে,কাঁচ থেকে সাবধানে পা ফেলে বেডসাইডে গেলো।ব্যাগ থেকে কাপড় নিয়ে ওয়াশরুমে ঢুকে গেলো।\nবিছানার উপর গিয়ে বসলো আঁধার! ওয়াশরুমের বন্ধ দরজার দিকে তাকিয়ে গালি ছুড়লো কয়েকটা।\nলেহেঙ্গা বদলে, একটা বাদামী রঙের সুতির থ্রি পিস পরে আসলো চাঁদনী!আধার তখনও বিরস ভঙ্গিতে বেডের উপর বসে ছিলো।চাঁদনী দাঁড়িয়ে থাকলো, হাত কচলে নিজের অস্বস্তির জানান দিলো। আধারের দিকে তাকিয়ে আইঢাই করে বললো\n\n-"আমি কোথায় ঘুমাবো?"\n\n-"যেখানে মন চায় শুয়ে পর! আমার থেকে জিজ্ঞেস করছিস কেন?তোর প্যানপ্যানানি বিরক্ত লাগছে আমার।"\n\nমুখ বাকালো চাঁদনী। কিছুক্ষণ দাঁড়িয়ে থেকে দাঁত দিয়ে নখ কাটলো।পরক্ষণেই ধপ করে শুয়ে পরলো বিছানার একপাশে।আঁধার একপলক চাইলো ওর দিকে, ভ্রু কুঁচকে বললো\n-"এখানে শুবি তুই?"\n\n-"তুমিই তো বললে যেখানে মন চায় শুতে!"\n\n-"তোর সাথে এক বিছানায় ঘুমাতে পারবো না আমি!"\n\n-"তাহলে মেঝেতে শুয়ে পরো।বিছানার নরম বেড ছাড়া ঘুমাতে পারি না !ব্যাড নাইট!তোমার সাথে কোনো রাত গুড হবে বলে মনে হয় না!"\n\nহামি তুলে বললঁ চাদনী!বিরক্তিকর দৃষ্টিতে তাকিয়ে থাকলো আঁধার। চাঁদনী ভেঙচি কেটে লেপ মুড়ি দিয়ে শুয়ে পরলো।দীর্ঘশ্বাস ফেললো আঁধার। চাঁদনীর থেকে একহাত দুরত্ব রেখে বিছানার এক সাইডে শুয়ে পরলো!আবার উঠে বসে ব্যালকনিতে চলে গেলো।আজ খুব বিশ্রী ভাবে ইগো হার্ট করেছে অর্পিতা।আধার যে ওঁকে খুব ভালোবাসতো এমন না। পছন্দ করতো।সুন্দর ছিলো মেয়েটা।নিজেই আঁধারের সাথে চিপকে থাকতো সবসময়।অপছন্দ করার কোনো কিছু ছিলো না।আর আঁধার বরাবরই সুন্দরের পূজারী। কিন্তু আজ খুব রাগ হচ্ছে ওর অর্পিতার উপর।বিয়ে না করলে আগেই বলে দিতো।বা বিয়ের আগেই লা*ঙের সাথে পালিয়ে যেতো।অর্পিতার, ওর সাথে চিপকে থাকা দেখে সবাই ভেবেছিলো অর্পিতা ওঁকে ভালোবাসে।আঁধার নিজেও এমনটাই কল্পনা করেছিলো।কেও যে ওঁকে রিজেক্ট করতে পারে, আঁধার সেটা বিশ্বাস করতে পারে না।নিজের উপর খুব কনফিডেন্ট ও।কিন্তু অর্পিতা ওঁকে বিয়ে না করার জন্য পালিয়ে গেলো, এর চেয়ে বড় রিজেক্ট আর হয়না,হতে পারে না।যে ইনভিজিবাল থাপ্পড় মেয়েটা মারলো ওঁকে, তা শুধে আসলে ফেরত দেবে ও। আঁধারের আফসোস নেই, অর্পিতার পালানো তে।এমন হাজারটা সুন্দরী কে ও নিজের পেছনে পাগল বানিয়ে ঘোরাতে পারে।বাট ওই মেয়ের জন্য অমন অমাবস্যার মতো কালিকে বিয়ে করতে হলো ওর।বাপ-চাচা কী ভেবে যে অমন কাইলানির নাম চাদনী রেখেছিলো কে জানে! বন্ধুমহলে আর মুখ দেখানোর অবস্থায় নেই ও।এই বউ নিয়ে তো আঁধার ওদের সামনে যেতেই পারবে না। মূলত আফসোস টা এখানেই।আজ রাতে আর ঘুম আসবে বলে মনে হয় না।জীবনটা এতো কঠিন না হলেও পারতো।\n,\n\nবর্ষা বেগম কিচেনের সবকিছু গুছিয়ে মাত্রই সোফায় এসে বসেছেন।এখনও কয়েকজন কাছের আত্মীয় থেকে গেছে তাঁদের বাড়িতে।তাঁদের জন্য রান্নাবান্না,  খাওয়া-দাওয়ার পাঠ চুকাতে আজ অনেকটা দেরি হয়ে গেছে। বর্ষা বেগম সোফায় গা এলিয়ে দিয়ে বসেন।রাফিয়া বেগম একটু আগেই ঝেড়ে গেছে তাকে।রাফিয়া বেগম আঁধারের দাদি।বড়ই জালিম ধাঁচের একটা মহিলা।মানুষ কে কথা শুনিয়ে বড্ড তৃপ্তি পান।আর সে মানুষটা যদি বর্ষা বেগম হয় তাহলে তো আর কথাই নেই।অথচ বাড়ির আরেক বউ মহারানীর মতো কক্ষে খিল দিয়ে বসে আছে।কী এক মেয়ে পালালো তার, শোকের শেষ নেই।কিন্তু শোক টা বেশি হওয়ার কথা ছিলো বর্ষা বেগমের।কিন্তু বাড়িতে কামলা খাটতে গিয়ে শোক পালন করার ফুসরত কই তার। না, চাদনী কে তিনি ভালোবাসেন না এমন না।মা মরা মেয়েটাকে বাড়ির সব ছেলে মেয়েদের চেয়ে একটু বেশিই আদর করতেন তিনি।সুন্দর ব্যবহারের জন্য পছন্দও করতেন খুব।কিন্তু সেটা ছেলের বউ হিসেবে না! তার সুদর্শন ছেলেটার বউ কি-না অমন শ্যামা রঙের! এ দুঃখ কাকে বোঝাবেন তিনি।মা হিসেবে অমত করার অধিকার টুকুও তার ছিলো না। আগেই জানতেন কেউ তার কথা আমলে নিবে না। ইন্ট্রোভার্ট হওয়ার দরুন সব বিষয়ে চুপ থাকেন তিনি, তাই তো বড়ো জা হওয়া সত্বেও মেঝো জায়ের হম্বিতম্বি সহ্য করতে হয় তাকে। তার মেয়ে পালিয়েছে,শুধুমাত্র ওই মেয়ের জন্য ওনার ছেলেটাকে একটা কালো মেয়েকে বিয়ে করতে হয়েছে। কোথায় সে নত হয়ে থাকবে, উল্টো তাকে এসে বাঁশ দিচ্ছে। বর্ষা বেগম বিমর্ষ হয়ে বসে থাকেন।মনটা খারাপ হয় গেছে তার।প্রত্যেক মা''ই মনে মনে দোয়া করে তার ছেলের বউ খুব সুন্দরী, ফর্সা হবে।উনিও তার ব্যাতিক্রম নন। চাঁদনীর দজ্জাল শ্বাশুরি তিনি কখনোই হবেন না।এসব তার ধাঁচের না।তিনি মেয়েটা কে ভালোবাসবেন, কিন্তু মন থেকে ছেলের বউ হিসেবে মেনে নিতে পারবেন না কখনোই।\n,\n\nঅন্ধকার কামরায় অপূর্ব শিকদার আর আকিব শিকদার সামনাসামনি বসে আছেন।দু''জনের মুখেই অমানিশা! অপূর্ব শিকদার যদিও মনে মনে ভীষণ খুশি,অবশেষে বিয়েটা হওয়াতে।কিন্তু ছোট ভাইয়ের কালো মুখ দেখে সে খুশি আর বেশিক্ষণ টেকেনি তার।\n\n-"মন খারাপ তোর?"\n\nঘাড় উঁচিয়ে চাইলেন আকিব শিকদার।অপূ্র্ব শিকদার কপালে ভাজ ফেলে তাকিয়ে আছেন।দীর্ঘশ্বাস ফেললেন আকিব শিকদার। বিমর্ষ স্বরে বললেন\n\n-"নিজেকে বড়ই ব্যর্থ বাবা বলে মনে হচ্ছে ভাইয়া।মেয়ের এতো অপমানের পরও প্রতিবাদ করতে পারিনি। তার সাথে বিয়ে দিয়েছি যে আমার মেয়েটাকে এভাবে ভরা আসরে যাই নয় তাই বলেছে।আমি রাগ করিনি আঁধারের উপর।ওর রাগ জায়েজ। কিন্তু তাই বলে আমার মেয়েটাকে অপমান করবে?শুধু তোমার কথা রাখতে চাদনীর সাথে এতো বড় অন্যায় করেছি আমি।"\n\nঅপূর্ব শিকদার তিক্ত ঢোক গিলেন।কাতর স্বরে ভাইয়ের উদ্দেশ্যে বলেন\n\n-"তুই তো জানিস,অনেক আশা নিয়ে ঢাকা শহরে পাঠিয়েছিলাম ওঁকে।ভেবেছিলাম এই গ্রাম-গঞ্জের শিক্ষা প্রতিষ্ঠান ওর মেধার যথাযথ মূল্যায়ন করতে পারবে না। কিন্তু ছেলেটা যে এভাবে নষ্ট হয়ে যাবে, বিগড়ে যাবে তা তো ঘুণাক্ষরেও টের পাইনি।শহরে গিয়ে নেশায়, নারীসঙ্গে আসক্ত হয়েছে!মেধা শুধু পড়ালেখায় না, অন্য কত জায়গায় যে খরচ করেছে তা আমার মুখে উচ্চারণ করতেও বাঁধছে।জানি আমি চাঁদ মায়ের সঙ্গে অপরাধ করেছি!দোষ করেছে অর্পিতা আর আঁধার। অথচ শাস্তি পেলো আমার নিরীহ মেয়েটা।কিন্তু আমি জানি আকিব, চাদনী ছাড়া আমার আঁধারের জন্য আর কেও পার্ফেক্ট হতো না।আমু আঁধারের জন্য চাদানী কেই পছন্দ করেছিলাম।কিন্তু অর্পিতার সাথে ওর সম্পর্ক জানার পর সিদ্ধান্ত থেকে সরে আসি।কিন্তু কাল যখন নিজের ইচ্ছে পূরণ করার একটা সুযোগ পেলাম,আমি সে সুযোগ হাতছাড়া করতে চাইনি। ও ছাড়া যে আমার ছেলেটা কে কেওই সুপথে ফিরিয়ে আনতে পারতো না!আঁধার আমার হাতের বাইরে চলে গেছে রে আঁকিব! একমাত্র চাঁদ মা পারে ওঁকে সুধরাতে!"\n\n-"তোমার মনে হয় চাঁদ এতো বড় একটা দায়িত্ব নিতে পারবে?আমার মেয়েটা এখনো অনেক ছোট ভাইজান।\nসংসারের কী বুঝবে ও?নিজেকেই তো সামলাতে পারে না ও, একটা আস্ত ঘর, একটা বর কে কী করে সামলাবে ও?"\n\n-"মনে হয় কী বলছিস রে!আমার বিশ্বাস আমার চাঁদ মা পারবে!তুই জানিস না আঁধার ওঁকে কতটা ভালোবাসে ছোটবেলা থেকে।ওর জন্য হলেও নিজেকে শুদ্ধ করার চেষ্টা করবে আঁধার, দেখিস!"\n\n-"ছোট বোন হিসেবে আদর করতো! সেটাকে ভালোবাসার নাম দিও না।যদিও তুমি সেটা ধরে বসে থাকো, তবুও\nএখন আর সে ভালোবাসা অবশিষ্ট নেই ভাই।অনেক বছর কেটে গেছে।ঢাকা যাওয়ার পর আঁধার কতটা বদলে গেছে তা বলার অপেক্ষা রাখে না।ও তো চাঁদনী কে সহ্যই করতে পারছে না।ভালোবাসলে বুঝি এভাবে অপমান করতো!প্রিয় মানুষকে এভাবে অপমান করা যায়?আমার অনেক ভয় লাগছে ভাইয়া!শুধু তোমার কথা রাখতে, আমি আমার মেয়েটাকে বলি দিয়েছি।ওর কিছু হলে আমি সহ্য করতে পারবো না!\n\nঅপূর্ব শিকদার অনেকটা সময় কেমন করে যেন তাকিয়ে থাকলেন।বড় করে শ্বাস ফেলে বললেন\n-"ভালোবাসা কখনো ফুরিয়ে যায় না আকিব।আমার বিশ্বাস আমার ছেলেটা বুঝতে পারবে।এখন রেগে আছে তাই এমন করছে।একটু বিশ্বাস রাখ আমার উপর।আমার চাঁদ মায়ের উপর আমি কোনো আচ আসতে দেব না।আমাকে ক্ষমা করে দিস তুই!"\n\nআকিব শিকদার বিরস স্বরে বললেন\n-"আমি ক্ষমা করার কেউ নই ভাইয়া।যার প্রতি এতো অন্যায় করেছি সেই মেয়েটাই কোনো অভিযোগ রাখলো না।বিয়ের পর একটা শব্দ কথা বলেনি আমার সাথে।তোমার ছেলেকে তোমার কাছে ফিরিয়ে দিতে গিয়ে আমি আমার মেয়েটাকে হারিয়ে ফেললাম।"\n\n#চলবে','\n',char(10)),2,'published',0,'2026-10-29 18:15:51','2026-10-29 18:15:51',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('4467eb65-aae7-4160-a050-d335a97376c7','c4867502-b7f2-4c77-b704-eba7e96e8b8d','পর্ব - ৪',replace('~ তোমার অন্ধকারে আমার বসন্ত ~\n\nWriter : Noor Islam.\n\nপর্ব ৪: অতীতের দরজায় তুমি \n\n— তোমার পরিবারের ইতিহাস আমি তোমার নিজের চেয়েও বেশি জানি, আরিশা!\n\nআদ্রিয়ানের কথাটা শুনে আরিশা কয়েক মুহূর্ত নিশ্চুপ হয়ে রইল। তারপর ভ্রু কুঁচকে তার দিকে তাকাল।\n\n— মানে কী? আমার পরিবার সম্পর্কে আপনি কী জানেন?\n\nআদ্রিয়ান পকেটে হাত রেখে শান্ত গলায় বলল,\n\n— সব প্রশ্নের উত্তর একসঙ্গে পাওয়া যায় না, মিস রহমান।\n\n— আর সব প্রশ্নের উত্তর এড়িয়ে যাওয়াও ভদ্রতা নয়, মিস্টার মির্জা!\n\nআরিশার কথায় আদ্রিয়ানের ঠোঁটের কোণে ক্ষীণ হাসি ফুটে উঠল। মেয়েটার একটা অদ্ভুত সাহস আছে। তার সামনে দাঁড়িয়ে এভাবে কথা বলার সাহস খুব কম মানুষেরই হয়।\n\n— তোমার সাহসটা আমার বেশ পছন্দ, আরিশা।\n\n— আপনার পছন্দ-অপছন্দ জানার কোনো আগ্রহ আমার নেই।\n\nকথাটা বলেই আরিশা চলে যেতে উদ্যত হলো। কিন্তু আদ্রিয়ানের পরের কথায় তার পা থেমে গেল।\n\n— তোমার বাবার পুরোনো ছবিগুলো এখনো তোমাদের বাড়িতে আছে?\n\nআরিশা ধীরে ধীরে ঘুরে দাঁড়াল।\n\n— আমার বাবাকে আপনি চিনতেন?\n\nএবার আদ্রিয়ানের মুখের হাসি মিলিয়ে গেল। চোখে নেমে এল সেই পরিচিত শীতলতা।\n\n— হয়তো চিনতাম। আবার হয়তো এমন কিছু জানি, যা তোমার জানা উচিত নয়।\n\n— আপনি সবকিছু এত রহস্য করে বলেন কেন? সোজাসুজি কথা বলতে পারেন না?\n\n— কারণ কিছু সত্য মানুষকে বদলে দেয়, আরিশা। আর কিছু সত্য মানুষের প্রিয় মানুষগুলোকে তার কাছ থেকে কেড়ে নেয়।\n\nকথাটা বলে আদ্রিয়ান চলে গেল।\n\nআরিশা দাঁড়িয়ে রইল। বুকের ভেতর অজানা একটা অস্বস্তি জমতে লাগল। তার বাবা সম্পর্কে আদ্রিয়ান কী জানে? আর তাদের পরিবারের সঙ্গে মির্জাদের সম্পর্কই বা কী?\n\nপ্রশ্নগুলো মাথার মধ্যে ঘুরপাক খেতে লাগল।\n\n---\n\nরাত সাড়ে আটটা।\n\nমির্জা ম্যানশনের বিশাল অফিসকক্ষে বসে আছে আদ্রিয়ান। সামনে কয়েকটি পুরোনো ফাইল ছড়িয়ে আছে। জানালার বাইরে বৃষ্টি পড়ছে, অথচ তার মন পড়ে আছে অন্য কোথাও।\n\nদরজায় টোকা দিয়ে ভেতরে ঢুকল রায়ান।\n\n— স্যার, আপনি যে ফাইলগুলো চেয়েছিলেন, সেগুলো পেয়েছি।\n\nআদ্রিয়ান চোখ না তুলেই বলল,\n\n— রহমান পরিবারের পুরোনো নথিগুলোও?\n\n— জি, স্যার। তবে একটা বিষয় আছে।\n\nএবার আদ্রিয়ান মুখ তুলে তাকাল।\n\n— কী বিষয়?\n\nরায়ান একটু ইতস্তত করে বলল,\n\n— প্রায় বিশ বছর আগের একটা নথি পাওয়া যাচ্ছে না। নথিটা হারিয়ে গেছে, নাকি ইচ্ছা করে সরানো হয়েছে, সেটা বোঝা যাচ্ছে না।\n\nআদ্রিয়ানের চোয়াল শক্ত হয়ে উঠল।\n\n— যে-ই সরিয়ে থাকুক, খুঁজে বের করো।\n\n— আর ম্যাডাম আরিশা রহমান?\n\nনামটা শুনতেই আদ্রিয়ানের দৃষ্টিতে সামান্য পরিবর্তন এল।\n\n— ওর ওপর নজর রাখবে। তবে ও যেন কোনোভাবেই বিপদে না পড়ে।\n\nরায়ান কিছুক্ষণ চুপ থেকে বলল,\n\n— স্যার, একটা কথা বলব?\n\n— বলো।\n\n— আপনি কি সত্যিই ওনাকে শুধু ওই পুরোনো ঘটনার কারণেই নিজের কাছাকাছি রাখতে চাইছেন?\n\nআদ্রিয়ান ফাইল বন্ধ করে তার দিকে তাকাল।\n\n— নিজের সীমার মধ্যে থাকো, রায়ান।\n\n— সরি, স্যার।\n\nরায়ান বেরিয়ে গেল।\n\nআদ্রিয়ান একা বসে রইল। টেবিলের ড্রয়ার খুলে সে একটা পুরোনো ছবি বের করল। ছবিতে দুজন পুরুষ পাশাপাশি দাঁড়িয়ে আছে। একজনের মুখে হাসি, অন্যজনের চোখে অদ্ভুত গাম্ভীর্য।\n\nছবির পেছনে লেখা একটি নামের ওপর তার আঙুল থেমে গেল।\n\nরহমান।\n\nআদ্রিয়ান চোখ বন্ধ করল। অতীতের সেই রাতের স্মৃতি আজও তাকে তাড়া করে বেড়ায়।\n\nকিন্তু আরিশা কি সত্যিই সেই ঘটনার সঙ্গে জড়িত?\n\nনাকি সে এমন একজন, যে নিজেই জানে না তার পরিবার তাকে কত বড় সত্য থেকে দূরে রেখেছে?\n\n---\n\nপরদিন সকালে বিশ্ববিদ্যালয়ের ক্যাম্পাসে বন্ধুদের সঙ্গে বসে ছিল আরিশা। কিন্তু তার মনোযোগ কিছুতেই পড়াশোনায় ফিরছিল না।\n\nঠিক তখনই সামনে এসে দাঁড়াল একটি পরিচিত ছায়া।\n\nকালো শার্ট, গম্ভীর মুখ আর চোখে সেই দুর্বোধ্য দৃষ্টি।\n\nআদ্রিয়ান মির্জা!\n\nআরিশা অবাক হয়ে তাকাল।\n\n— আপনি এখানে কী করছেন?\n\n— তোমাকে নিতে এসেছি।\n\n— আমাকে? কেন? আমি কি আপনাকে বলেছি আমাকে নিতে আসতে?\n\n— না।\n\n— তাহলে?\n\nআদ্রিয়ান শান্তভাবে বলল,\n\n— তোমার সঙ্গে কথা আছে।\n\nআরিশা উঠে দাঁড়াল।\n\n— আমারও একটা কথা আছে। আমার জীবন নিয়ে সিদ্ধান্ত নেওয়ার অধিকার আপনাকে কে দিয়েছে?\n\nআদ্রিয়ান তার দিকে কয়েক মুহূর্ত তাকিয়ে থেকে বলল,\n\n— কেউ দেয়নি। কিন্তু তোমার বিপদ হলে আমি চুপ করে দাঁড়িয়ে থাকতে পারব না।\n\nকথাটা শুনে আরিশার বুকের ভেতর কেমন যেন হলো। তবু মুখে বিরক্তি ফুটিয়ে বলল,\n\n— আমি নিজের যত্ন নিতে পারি।\n\n— জানি।\n\n— তাহলে এত চিন্তা কেন?\n\nআদ্রিয়ান একটু ঝুঁকে নিচু গলায় বলল,\n\n— সব চিন্তার কারণ মুখে বলা যায় না, আরিশা।\n\nএই প্রথম কথাটা শুনে আরিশা কোনো জবাব খুঁজে পেল না।\n\nআদ্রিয়ান সোজা হয়ে দাঁড়াল।\n\n— আজ সন্ধ্যায় তোমাদের বাড়িতে যাবো। তোমার বাবার সম্পর্কে কিছু কথা জানাতে চাই।\n\nআরিশার মুখ মুহূর্তেই ফ্যাকাশে হয়ে গেল।\n\n— আমার বাবার সম্পর্কে?\n\n— হ্যাঁ। আর এমন কিছু দেখাতে চাই, যা দেখার পর হয়তো তুমি আমাকে আর আগের মতো ঘৃণা করতে পারবে না।\n\nকথাটা বলে আদ্রিয়ান চলে গেল।\n\nআরিশা স্থির হয়ে দাঁড়িয়ে রইল। তার মনে একসঙ্গে জন্ম নিল ভয়, কৌতূহল আর অদ্ভুত এক অনুভূতি।\n\nসন্ধ্যায় কী জানতে পারবে সে?\n\nআদ্রিয়ান কি সত্যিই তার বাবার অতীত জানে?\n\nনাকি এই মানুষটার হাতেই লুকিয়ে আছে তার পরিবারের সবচেয়ে বড় রহস্য?\n\n---\n\nসন্ধ্যা নামতেই রহমান বাড়ির দরজায় এসে পৌঁছাল একটি কালো খাম।\n\nখামের ভেতরে ছিল একটি পুরোনো ছবি আর ছোট্ট একটি চিরকুট।\n\nছবিটা হাতে নিয়ে আরিশার চোখ বিস্ময়ে বড় হয়ে গেল।\n\nছবিতে তার বাবা দাঁড়িয়ে আছেন আদ্রিয়ানের বাবার পাশে।\n\nআর ছবির পেছনে লাল কালিতে লেখা—\n\n“যে সত্য তোমার পরিবার লুকিয়েছে, সেই সত্যই একদিন তোমার ভালোবাসাকে ধ্বংস করবে।”\n\nআরিশার হাত কেঁপে উঠল।\n\nঠিক তখনই তার ফোনে একটি অচেনা নম্বর থেকে বার্তা এল।\n\n“আদ্রিয়ান মির্জাকে বিশ্বাস কোরো না। কারণ তোমার পরিবারের অতীতের জন্য সে তোমাকে কখনো ক্ষমা করবে না।”\n\nবার্তাটির দিকে তাকিয়ে আরিশার চোখে পানি জমল।\n\nসে কি আদ্রিয়ানকে বিশ্বাস করতে পারবে?\n\nনাকি যে মানুষটির চোখে সে অজান্তেই একটু একটু করে অন্যরকম অনুভূতি খুঁজে পাচ্ছে, সেই মানুষটিই একদিন তার সবচেয়ে বড় কষ্টের কারণ হবে?\n\nঅন্যদিকে, নিজের ম্যানশনের জানালার পাশে দাঁড়িয়ে আদ্রিয়ান ফোনের পর্দায় আরিশার ছবির দিকে তাকিয়ে ফিসফিস করে বলল,\n\n— তোমাকে ঘৃণা করার কথা ছিল আমার, আরিশা। তাহলে তোমার কষ্টের কথা ভাবলেই আমার নিজের এত কষ্ট হয় কেন?\n\nবাইরে তখন বৃষ্টি আরও জোরে নামছে।\n\nআর তাদের দুজনের অজান্তেই অতীতের বন্ধ দরজাটা ধীরে ধীরে খুলতে শুরু করেছে।\n\nচলবে...🥀🖤','\n',char(10)),4,'published',0,'2026-10-29 18:36:05','2026-10-29 18:36:05',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('10c68429-88e9-489a-9046-465eb0801dc0','c4867502-b7f2-4c77-b704-eba7e96e8b8d','পর্ব - ৫',replace('~ তোমার অন্ধকারে আমার বসন্ত ~\n\nWriter : Noor Islam.\n\nপর্ব ৫: ভালোবাসা নাকি প্রতিশোধ?\n\nরহমান বাড়ির ড্রয়িংরুমে বসে আছে আরিশা। তার হাতে সেই পুরোনো ছবিটা, যেখানে পাশাপাশি দাঁড়িয়ে আছেন তার বাবা আর আদ্রিয়ানের বাবা। ছবিটার দিকে যতবার তাকাচ্ছে, ততবারই মাথার ভেতর অসংখ্য প্রশ্ন ঘুরপাক খাচ্ছে।\n\nআদ্রিয়ান মির্জা আসলে কে?\n\nতার বাবার সঙ্গে আদ্রিয়ানের পরিবারের সম্পর্ক কী ছিল?\n\nআর কেনই বা কেউ তাকে আদ্রিয়ানকে বিশ্বাস করতে নিষেধ করছে?\n\n— আপু, কী হয়েছে তোমার? সেই কখন থেকে ছবিটার দিকে তাকিয়ে আছো!\n\nছোট কাজিনের কথায় বাস্তবে ফিরল আরিশা।\n\n— কিছু না।\n\n— কিছু না হলে তোমাকে এমন দেখাচ্ছে কেন?\n\nআরিশা মৃদু হাসার চেষ্টা করল।\n\n— তুই যা তো। আমার একটু একা থাকতে ইচ্ছে করছে।\n\nকাজিন চলে যেতেই আরিশা ফোনটা হাতে নিল। অচেনা নম্বর থেকে আসা বার্তাটা আবার পড়ল।\n\n“আদ্রিয়ান মির্জাকে বিশ্বাস কোরো না। কারণ তোমার পরিবারের অতীতের জন্য সে তোমাকে কখনো ক্ষমা করবে না।”\n\nবার্তাটা পড়েই তার বুকের ভেতরটা কেমন ভারী হয়ে উঠল।\n\nআদ্রিয়ানের চোখের দিকে তাকালে কেন তার মনে হয়, সেই কঠিন মানুষটার ভেতরেও কোথাও একটা চাপা কষ্ট লুকিয়ে আছে?\n\nকেন তার রাগী কণ্ঠ শুনেও আরিশার মন তাকে এড়িয়ে চলতে পারে না?\n\n— ধুর! কী সব ভাবছি আমি!\n\nনিজের মনেই কথাটা বলে ফোনটা বিছানায় ছুড়ে দিল সে।\n\nকিন্তু ফোনটা আবার বেজে উঠল।\n\nস্ক্রিনে ভেসে উঠল একটা নাম।\n\nAdrian Mirza.\n\nআরিশা কয়েক সেকেন্ড তাকিয়ে থেকে কলটা রিসিভ করল।\n\n— হ্যালো?\n\nওপাশ থেকে গম্ভীর কণ্ঠ ভেসে এল।\n\n— কোথায় তুমি?\n\n— কেন? আমার অবস্থান জানার এত শখ কেন আপনার?\n\n— প্রশ্নের উত্তর দাও, আরিশা।\n\n— নিজের বাড়িতে আছি। এবার বলুন, আর কিছু জানতে চান?\n\nকয়েক মুহূর্ত নীরব থেকে আদ্রিয়ান বলল,\n\n— তোমার সঙ্গে দেখা করতে চাই।\n\nআরিশা অবাক হলো।\n\n— কেন?\n\n— তোমার বাবার ব্যাপারে কথা আছে।\n\nকথাটা শুনেই আরিশার মুখের হাসি মিলিয়ে গেল।\n\n— কখন আসবেন?\n\n— বিশ মিনিটের মধ্যে।\n\n— আপনাকে তো আসতে বলিনি!\n\n— জানি।\n\n— তাহলে?\n\nআদ্রিয়ানের কণ্ঠে এবার সামান্য হাসির আভাস পাওয়া গেল।\n\n— তোমার অনুমতি নিয়ে আসতে গেলে হয়তো আগামীকাল হয়ে যাবে।\n\n— অসহ্য একটা মানুষ আপনি!\n\n— সেটা তোমার মুখেই সবচেয়ে বেশি শুনি।\n\nকলটা কেটে গেল।\n\nআরিশা ফোনের দিকে তাকিয়ে রইল। লোকটা কি সত্যিই সবসময় এমন? নাকি শুধু তার সামনেই এমন অদ্ভুত আচরণ করে?\n\nনিজের অজান্তেই তার ঠোঁটের কোণে হাসি ফুটে উঠল।\n\nপরমুহূর্তেই সে নিজেকে সামলে নিল।\n\nনা! আদ্রিয়ান মির্জাকে নিয়ে এত ভাবার কোনো মানে হয় না।\n\n---\n\nঠিক বিশ মিনিট পর রহমান বাড়ির সামনে এসে থামল একটি কালো গাড়ি।\n\nগাড়ি থেকে নেমে আদ্রিয়ান চারপাশে একবার চোখ বুলিয়ে নিল। কালো শার্টের হাতা কনুই পর্যন্ত গোটানো, মুখে সেই চিরচেনা গাম্ভীর্য।\n\nদরজা খুলে আরিশা সামনে এল।\n\n— আপনি সত্যিই চলে এসেছেন!\n\nআদ্রিয়ান ভ্রু তুলল।\n\n— তোমার কি মনে হয়েছিল আসব না?\n\n— আপনার মতো মানুষের কোনো ঠিক নেই।\n\n— অথচ আমার আসার অপেক্ষায় দরজার কাছেই দাঁড়িয়ে ছিলে।\n\nআরিশা চোখ বড় করে তাকাল।\n\n— কী! আমি আপনার জন্য দাঁড়িয়ে ছিলাম না!\n\n— আচ্ছা, বিশ্বাস করলাম।\n\nআদ্রিয়ানের ঠোঁটে দুষ্টু হাসি ফুটল।\n\nআরিশা বিরক্ত হয়ে মুখ ঘুরিয়ে নিল।\n\n— ভেতরে আসুন।\n\nআদ্রিয়ান ঘরে ঢুকতেই আরিশা তাকে বসতে বলল। কিন্তু সে বসার আগেই টেবিলের ওপর রাখা ছবিটা তার চোখে পড়ল।\n\nছবিটা হাতে নিয়ে তার মুখ মুহূর্তেই বদলে গেল।\n\n— এই ছবি তুমি কোথায় পেয়েছ?\n\nআরিশা তার কণ্ঠের পরিবর্তন লক্ষ করল।\n\n— গতকাল একটা খাম এসেছিল। তার ভেতরে ছিল।\n\n— খামটা কোথায়?\n\n— আমার ঘরে।\n\n— কে দিয়েছিল?\n\n— জানি না। কেন? কী হয়েছে?\n\nআদ্রিয়ান কোনো উত্তর দিল না। ছবির পেছনে চোখ পড়তেই তার আঙুল শক্ত হয়ে উঠল।\n\nসেখানে লাল কালিতে লেখা কথাগুলো সে আগেই জানত।\n\nকিন্তু যে মানুষটা এই ছবিটা আরিশার কাছে পাঠিয়েছে, সে যে আবার ফিরে এসেছে, সেটা সে কল্পনাও করেনি।\n\n— আদ্রিয়ান সাহেব?\n\nআরিশার ডাকে সে বাস্তবে ফিরল।\n\n— তোমাকে কেউ ফোন করেছে?\n\nআরিশা একটু থেমে বলল,\n\n— হ্যাঁ। একটা অচেনা নম্বর থেকে।\n\n— কী বলেছে?\n\n— আপনাকে বিশ্বাস করতে নিষেধ করেছে।\n\nকথাটা শুনে আদ্রিয়ানের চোখে মুহূর্তের জন্য তীব্র রাগ ফুটে উঠল।\n\n— নম্বরটা আমাকে দাও।\n\n— আগে বলুন, ব্যাপারটা কী?\n\n— আরিশা, এখন প্রশ্ন করার সময় নয়।\n\n— আমার পরিবারকে নিয়ে কেউ আমাকে হুমকি দিচ্ছে, আর আপনি বলছেন প্রশ্ন করার সময় নয়? আপনি কি ভাবেন, আমি আপনার কথায় সবকিছু মেনে নেব?\n\nআদ্রিয়ান তার দিকে তাকিয়ে রইল।\n\nমেয়েটার চোখে ভয় আছে, কিন্তু সেই ভয়ের চেয়েও বেশি আছে জেদ।\n\n— ঠিক আছে। জানতে চাও?\n\n— হ্যাঁ!\n\n— তাহলে একটা কথা মনে রেখো। যা-ই জানো না কেন, আমাকে শোনার আগে নিজের সিদ্ধান্ত নিও না।\n\nআরিশা ঠান্ডা গলায় বলল,\n\n— আর আপনি মনে রাখবেন, আমি কাউকে অন্ধভাবে বিশ্বাস করি না।\n\nআদ্রিয়ান ধীরে মাথা নাড়ল।\n\n— সেটাই ভালো।\n\nতারপর ছবিটা টেবিলে রেখে বলল,\n\n— এই ছবির দুই পরিবার একসময় খুব কাছের ছিল। কিন্তু একটা ঘটনার পর সবকিছু বদলে যায়। আমার পরিবার যা হারিয়েছে, তার পেছনে তোমার পরিবারের ভূমিকা আছে বলে আমি বিশ্বাস করতাম।\n\nআরিশার বুকের ভেতরটা ধক করে উঠল।\n\n— করতেন মানে? এখন করেন না?\n\nআদ্রিয়ান তার চোখের দিকে তাকাল।\n\n— এখন আমি সত্যিটা জানতে চাই।\n\n— আর যদি সত্যিই আমার পরিবার দোষী হয়?\n\nপ্রশ্নটা শুনে আদ্রিয়ান কিছুক্ষণ চুপ করে রইল।\n\nতারপর নিচু গলায় বলল,\n\n— তাহলে সত্যের মুখোমুখি হব। কিন্তু তোমাকে কোনো অপরাধের জন্য দোষী করব না, যেটা তুমি নিজে করোনি।\n\nআরিশা অবাক হয়ে তার দিকে তাকিয়ে রইল।\n\nএই প্রথম আদ্রিয়ানকে তার কাছে একটু অন্যরকম মনে হলো।\n\nএত রাগ, এত কঠিন আচরণের আড়ালে কি সত্যিই এমন একজন মানুষ লুকিয়ে আছে, যে অন্যায়ের দায় নিরপরাধ কারও ওপর চাপাতে চায় না?\n\n— আপনি কি আমাকে ঘৃণা করেন, আদ্রিয়ান?\n\nপ্রশ্নটা নিজের অজান্তেই বেরিয়ে গেল।\n\nআদ্রিয়ান স্থির হয়ে গেল।\n\nকয়েক সেকেন্ড তার দিকে তাকিয়ে থেকে বলল,\n\n— তোমাকে ঘৃণা করা আমার জন্য অনেক সহজ হতো, আরিশা।\n\n— তার মানে?\n\nআদ্রিয়ান একটু এগিয়ে এল।\n\n— তার মানে, তোমার সামনে দাঁড়ালে আমার সব হিসাব কেন এলোমেলো হয়ে যায়, সেটা এখনো বুঝতে পারিনি।\n\nআরিশার গাল লাল হয়ে উঠল।\n\n— আপনি সবসময় এমন অদ্ভুত কথা বলেন কেন?\n\n— তোমার সঙ্গে কথা বললে এমন হয়ে যায়।\n\n— আমি কিন্তু একটুও হাসছি না!\n\n— অথচ তোমার চোখ দুটো অন্য কথা বলছে।\n\nআরিশা সঙ্গে সঙ্গে মুখ ঘুরিয়ে নিল।\n\n— আপনি যান তো!\n\nআদ্রিয়ান মৃদু হেসে ফেলল।\n\nএই মেয়েটার সামনে দাঁড়ালে সে নিজের অজান্তেই এমন কিছু করে ফেলে, যা অন্য কারও সামনে কখনো করে না।\n\nকিন্তু নিজের মনের এই পরিবর্তনকে সে এখনো কোনো নাম দিতে প্রস্তুত নয়।\n\n---\n\nরাত বাড়তে লাগল।\n\nবাড়ি থেকে বের হওয়ার আগে আদ্রিয়ান আরিশাকে বলল,\n\n— আগামীকাল বিকেলে আমার অফিসে আসবে।\n\n— কেন?\n\n— ছবির ব্যাপারে আরও কিছু জানতে পারবে।\n\n— আমি না গেলে?\n\nআদ্রিয়ান এক মুহূর্ত ভেবে বলল,\n\n— তাহলে তোমার বাড়িতে এসে নিয়ে যাব।\n\nআরিশা বিরক্ত হয়ে বলল,\n\n— আপনি কি সবসময় মানুষকে বিরক্ত করেন?\n\n— না। শুধু তোমাকে।\n\nকথাটা বলে আদ্রিয়ান গাড়িতে উঠে পড়ল।\n\nআরিশা দরজার সামনে দাঁড়িয়ে রইল। লোকটার কথায় বিরক্ত হওয়ার কথা, অথচ তার মনটা অদ্ভুতভাবে ভালো হয়ে আছে।\n\nসে নিজের মনকে বোঝাল, এটা কেবল কৌতূহল।\n\nএর বেশি কিছু নয়।\n\nকিন্তু সে জানত না, গাড়িতে বসে আদ্রিয়ানও একই প্রশ্নের উত্তর খুঁজছে।\n\nকেন আরিশার চোখে কষ্ট দেখলে তার নিজের বুক ভারী হয়ে আসে?\n\nকেন মেয়েটাকে বিপদ থেকে দূরে রাখতে গিয়ে সে নিজের সব নিয়ম ভেঙে ফেলছে?\n\nআর কেন অতীতের প্রতিশোধ নেওয়ার যে শপথ সে একদিন করেছিল, আজ সেই শপথের সামনে দাঁড়িয়েও আরিশার ক্ষতি করার কথা ভাবতে পারছে না?\n\n---\n\nমির্জা ম্যানশনে ফিরে আদ্রিয়ান সোজা নিজের অফিসকক্ষে গেল।\n\nরায়ান আগে থেকেই অপেক্ষা করছিল।\n\n— স্যার, একটা খবর পেয়েছি।\n\n— বলো।\n\n— যে নম্বর থেকে ম্যাডাম আরিশাকে মেসেজ পাঠানো হয়েছে, সেটা একটা অস্থায়ী নম্বর। তবে নম্বরটা ব্যবহার করার আগে যে জায়গা থেকে সক্রিয় করা হয়েছিল, সেই জায়গার তথ্য পেয়েছি।\n\nআদ্রিয়ানের চোখ সরু হয়ে এল।\n\n— কোথায়?\n\nরায়ান একটা কাগজ এগিয়ে দিল।\n\nআদ্রিয়ান ঠিকানাটা পড়ল। পরমুহূর্তেই তার মুখের রং বদলে গেল।\n\n— অসম্ভব!\n\n— কী হয়েছে, স্যার?\n\nআদ্রিয়ান কাগজটা মুঠোয় চেপে ধরল।\n\nঠিকানাটা এমন একজনের বাড়ির, যাকে সে বহু বছর ধরে মৃত বলে জানে।\n\nএমন একজন মানুষ, যার নামের সঙ্গে জড়িয়ে আছে তার পরিবারের ধ্বংসের ইতিহাস।\n\nআদ্রিয়ান জানালার বাইরে তাকিয়ে রইল।\n\nতাহলে কি অতীতের সেই অধ্যায় এখনো শেষ হয়নি?\n\nআর যদি সেই মানুষটা সত্যিই ফিরে এসে থাকে, তাহলে আরিশা কতটা বিপদের মধ্যে রয়েছে?\n\nসে ধীর অথচ কঠিন কণ্ঠে বলল,\n\n— রায়ান, আগামীকাল থেকে আরিশার নিরাপত্তা দ্বিগুণ করবে। তবে ও যেন কিছু বুঝতে না পারে।\n\n— জি, স্যার।\n\nরায়ান চলে যাওয়ার পর আদ্রিয়ান ড্রয়ার থেকে সেই পুরোনো ছবিটা বের করল।\n\nছবির পেছনে লেখা নামটার ওপর আঙুল রেখে সে ফিসফিস করে বলল,\n\n— তুমি যদি সত্যিই ফিরে এসে থাকো, তাহলে এবার তোমার মুখোশ আমি নিজেই খুলব।\n\nতারপর কয়েক মুহূর্ত থেমে আরিশার কথা মনে পড়তেই তার চোখের দৃষ্টি বদলে গেল।\n\n— আরিশা, তোমার অতীতের সঙ্গে আমার অতীত জড়িয়ে আছে। কিন্তু আমি কথা দিচ্ছি, তোমার কোনো ক্ষতি হতে দেব না।\n\nবাইরে তখন রাতের আকাশে মেঘ জমেছে।\n\nএকদিকে অতীতের প্রতিশোধ, অন্যদিকে অজান্তেই জন্ম নেওয়া এক অনুভূতি।\n\nআদ্রিয়ান কি পারবে নিজের প্রতিশোধের শপথের চেয়েও আরিশার নিরাপত্তাকে বড় করে দেখতে?\n\nআরিশা কি পারবে এমন একজন মানুষকে বিশ্বাস করতে, যার অতীতের সঙ্গে তার পরিবারের অজানা রহস্য জড়িয়ে আছে?\n\nউত্তর লুকিয়ে আছে সেই সত্যের আড়ালে, যা এখনো কেউ জানে না।\n\nচলবে...🥀🖤','\n',char(10)),5,'published',0,'2026-10-29 19:04:06','2026-10-29 19:04:06',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('6a94c21f-d49e-4cd5-8f4a-80d1e278c722','c4b7dd5c-d4f0-4324-af5f-725d78c6fd88','মির্জা বিষাক্ত মায়া পর্ব -৪',replace('হঠাৎ আরহান কিশোরী মাহিরার দিকে গেল \n\nমাহিরা রহমান, পাঁচ ফুট উচ্চতার এক মায়াবতী। উজ্জ্বল শ্যামলা গায়ের রং, কোমর পর্যন্ত লম্বা ঘন কালো চুল আর হরিণীর মতো মায়াবী চোখ দুটো যেন যে কাউকে মুহূর্তেই মুগ্ধ করার ক্ষমতা রাখে। ঠোঁটের কোণে লেগে থাকা মিষ্টি হাসি আর মুখের সরলতা তাকে করে তুলেছে অনন্যা। তবে এই মায়াবী রূপের আড়ালে লুকিয়ে আছে একরাশ আরহান এর ভালোবাসা\n\nএতগুলো দিন পর নিজের মাহিরাকে চোখের সামনে দেখে আরহানের বুকের ভেতরটা কেমন যেন ওলটপালট হয়ে গেল। হাজারো অভিমান, জমে থাকা রাগ আর বুকের গভীরে লুকিয়ে রাখা ভালোবাসাগুলো একসঙ্গে মাথাচাড়া দিয়ে উঠল। যে মুখটা দেখার জন্য সে প্রতিটা দিন অপেক্ষা করেছে, আজ সেই মুখটা চোখের সামনে অথচ কতটা দূরে! আরহানের ইচ্ছে করছিল মাহিরাকে একটানে বুকের মধ্যে জড়িয়ে ধরে বলতে, “কোথায় ছিলে এতদিন, পাখি? জানো না তোমাকে ছাড়া তোমার এই পাষাণ মানুষটা কতটা অস্থিরতায় দিন কাটিয়েছে?”\n\nকিন্তু মুখে তার একটাও কথা ফুটল না। শুধু স্থির দৃষ্টিতে মাহিরার দিকে তাকিয়ে রইল আরহান। বুকের ভেতরটা তোলপাড় করলেও মুখে ফুটিয়ে তুলল কঠিন এক অভিব্যক্তি। কারণ সে জানে, মাহিরার সামনে নিজের দুর্বলতা প্রকাশ করা মানেই নিজের দুর্বল প্রমান করা । অথচ সত্যিটা হলো, পৃথিবীর সমস্ত মানুষের কাছে পাষাণ হতে পারলেও মাহিরার কাছে আজও সে সেই ভালোবাসায় পাগল ছেলেটাই রয়ে গেছে।\n\nআরহান বলল,\n\n--- কেমন আছো, মাহিরা...?\n\nমাহিরার কৈশোরী মন তখনও তার আরহান ভাইকে নিয়েই ভাবছে। সে যেন নিজের ভাবনার জগতে হারিয়ে গেছে।\n\nএটা দেখে অরবিন বলল,\n\n--- এই মাহি! ভাইয়া কিছু বলছে, শুন।\n\nমাহিরা অবাক হয়ে বলল,\n\n--- কী? কী বলো? হুম, শুনছি তো!\n\nমাহিরা এবার নিজেই সালাম দিল।\n\n--- আসসালামু আলাইকুম। কেমন আছেন?\n\n--- ওয়ালাইকুমুস সালাম। আলহামদুলিল্লাহ, ভালো আছি। তুমি কেমন আছো?\n\n--- জি, আলহামদুলিল্লাহ, ভালো আছি।\n\nএরপর আরহান জান্নাতকে বলল,\n\n--- জান্নাত!\n\n--- কেমন আছিস, বোন?\n\n--- আলহামদুলিল্লাহ, ভালো। তুমি কেমন আছো, ভাইয়া? প্রায় ছয় বছর পর দেখা!\n\n--- ভালো আছি। তুই তো তখন অনেক ছোট ছিলি। তবুও অন্তত তোর আমাকে মনে আছে! আর তোর বোন তো আমাকে চিনতেই পারছে না।\n\nকথাটা বলে আরহান মাহিরার দিকে তাকাল। মাহিরা কিছু না বলে চুপচাপ দাঁড়িয়ে রইল। কী বলবে, সেটাই যেন বুঝে উঠতে পারছে না সে।\n\nমাহিরা এসব দেখে কিছুই বুঝতে পারছে না। কারা এই তিনজন? আর কেনই বা সে তাঁদের সঙ্গে দেখা করতে এসেছে? হাজারো প্রশ্ন মাথায় ঘুরপাক খাচ্ছে তার। অবশেষে মাহিরা অরবিনকে একটু আলাদা ডেকে নিয়ে বলল,\n\n--- ভাইয়া, এবার তো বলো কিছু! কারা এরা? তোমরা সবাই এদের চেনো, কিন্তু আমি কেন চিনতে পারছি না? এখন যদি কিছু না বলো, তাহলে আমি বাড়ি চলে যাব!\n\nঅরবিন কিছু বলতে যাবে, ঠিক তখনই আরহান এসে বলল,\n\n--- অরবিন, তুই যা। আমি বলছি।\n\nমাহিরা অসহায় দৃষ্টিতে অরবিনের দিকে তাকিয়ে রইল। অপরিচিত একজন মানুষের সঙ্গে একা কথা বলতে তার ভীষণ ভয় হচ্ছে। তবুও মুখে কিছু বলার সাহস পাচ্ছে না সে।\n\nআরহান আবারও গম্ভীর কণ্ঠে বলল,\n\n--- যা, অরবিন। আমি ওকে বুঝিয়ে বলব।\n\nঅরবিন একবার মাহিরার দিকে তাকাল। তার চোখেমুখে স্পষ্ট উদ্বেগ। কিন্তু আরহানের কথার অবাধ্য হওয়ার সাহস হলো না তার। তাই মাহিরাকে আশ্বস্ত করার জন্য একবার মাথা নেড়ে সেখান থেকে চলে গেল।\n\nঅরবিন চলে যেতেই মাহিরার বুকের ভেতরটা ধক করে উঠল। এবার তাকে একা সামলাতে হবে এই অপরিচিত মানুষটাকে!\n\nঅরবিন চলে যেতেই আরহান মাহিরার দিকে তাকিয়ে মুচকি হেসে বলল,\n\n--- নিজের হবু জামাইকে চিনতে পারছো না, Sunshine?\n\n--- ও মা! হবু জামাই কোথা থেকে এলো...?\n\n--- কেন, পাখি? আমাকে চোখে লাগছে না?\n\n--- চোখে লাগছে, কিন্তু...\n\n--- কিন্তু কী?\n\n--- মনে লাগছে না!\n\nমাহিরার কথা শুনে আরহান মৃদু হেসে বলল,\n\n--- তাই?\n\n--- হুম!\n\nএবার মাহিরা বিরক্ত হয়ে বলল,\n\n--- আপনি কী বলবেন? কে আপনি? ভাইয়া আপনাকে চিনতে পারছে, কিন্তু আমি আপনাকে কেন চিনতে পারছি না?\n\nআরহান ভ্রু উঁচু করে বলল,\n\n--- আচ্ছা, শোনো। আমি তোমার মামাতো জামাই হই।\n\n--- কীইইই! মামাতো জামাই কীভাবে হয়?\n\n--- ওই তো, মামাতো ভাইকে বিয়ে করলেই মামাতো জামাই হয়!\n\nমাহিরা চোখ বড় বড় করে আরহানের দিকে তাকাল। লোকটা কি সত্যিই তার সঙ্গে মজা করছে, নাকি মাথার মধ্যে অন্য কোনো সমস্যা আছে?\n\nএবার মাহিরা বিরক্ত হয়ে বলল,\n\n--- প্লিজ, এবার তো বলুন আপনি কে! সেই কখন থেকে শুধু উল্টাপাল্টা কথা বলছেন!\n\nআরহান এবার একটু গম্ভীর হয়ে বলল,\n\n--- আচ্ছা, বলছি। আমি আরহান মির্জা। মির্জাবাড়ির বড় ছেলে, আলতাফ মির্জার একমাত্র ছেলে এবং ইয়াসমিন মির্জার বড় ভাইয়ের ছেলে। এবার চিনতে পারছো?\n\n--- মানে, মানে আপনি...!\n\nকথাটা শেষ করার আগেই মাহিরা ধপ করে বসে পড়ল। তার চোখেমুখে তখন অবিশ্বাস আর বিস্ময় স্পষ্ট।\n\nআরহান মুচকি হেসে বলল,\n\n--- হ্যাঁ, আমি আলতাফ মির্জার ছেলে। তোমার মামাতো ভাই।\n\n--- এটা সত্যি?\n\n--- হুম, একদম সত্যি!\n\nমাহিরা কিছুক্ষণ চুপ করে রইল। এতক্ষণ যার সঙ্গে কথা বলছিল, সে যে তার নিজের মামাতো ভাই, তা সে কল্পনাও করতে পারেনি!\n\nমির্জা পরিবারে একমাত্র মেয়ে ইয়াসমিন বেগম। একসময় এই পরিবারের সঙ্গে তাঁর সম্পর্ক ছিল গভীর। কিন্তু সময়ের সঙ্গে সঙ্গে সবকিছু বদলে গেছে। বর্তমানে মির্জা পরিবারের সঙ্গে ইয়াসমিন বেগমের আর কোনো সম্পর্ক নেই।\n\nকেন এই সম্পর্কের এমন পরিণতি হয়েছিল, তা আজও এক রহস্য। আর সেই রহস্যের আড়ালেই লুকিয়ে আছে মাহিরার জীবনের এক অজানা অধ্যায়...\n\nকিন্তু মাহিরা এসবের কিছুই জানে না। কেন তার পরিবারের সঙ্গে নানুবাড়ির কোনো সম্পর্ক নেই? কেন তার মা এত বছর ধরে নিজের বাবার বাড়িতে যান না? চার ভাইয়ের একমাত্র আদরের বোন হয়েও কেন ইয়াসমিন বেগম সবার থেকে আলাদা হয়ে গেলেন?\n\nহাজারো প্রশ্নের উত্তর আজও অজানা মাহিরার কাছে। ছোটবেলা থেকে সে শুধু জানে, তার নানুবাড়ির সঙ্গে তাদের কোনো সম্পর্ক নেই। কিন্তু কেন নেই, সেই প্রশ্নের উত্তর কখনো কেউ তাকে দেয়নি।\n\nমাঝেমধ্যে মায়ের চোখে এক অদ্ভুত বিষণ্নতা দেখেছে মাহিরা। নানুবাড়ির কথা উঠলেই মা কেমন যেন চুপ হয়ে যান। কিন্তু সেই নীরবতার আড়ালে লুকিয়ে থাকা কষ্টের কারণটা কখনো বুঝতে পারেনি সে।\n\nআজ এত বছর পর হঠাৎ মির্জা পরিবারের একজনের সামনে দাঁড়িয়ে মাহিরার মনে হাজারো প্রশ্ন জেগে উঠল।\n\nতবে কি তার মায়ের অতীতের সঙ্গে জড়িয়ে আছে কোনো গভীর রহস্য? এমন কী ঘটেছিল, যার কারণে চার ভাইয়ের একমাত্র বোনকে নিজের পরিবার থেকে দূরে সরে যেতে হয়েছিল?\n\nএসব প্রশ্নের উত্তর কি কখনো জানতে পারবে মাহিরা? নাকি তার পরিবারের অতীতের সেই অন্ধকার রহস্য চিরকালই অজানা থেকে যাবে?\n\n\nচলবে.....?😘','\n',char(10)),4,'published',0,'2026-10-30 07:53:05','2026-10-30 07:53:05',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('08c0ffe6-b1a9-4b70-b523-1cb9591d9570','4f94b40b-3163-4e82-be86-71aae1de626d','পব২',replace('তোমাতেই আমার পূর্ণতা ❤️\n\nদ্বিতীয় পর্ব: বন্ধুত্বের আড়ালে ভালোবাসা\n\n“কিছু অনুভূতি মুখে বলা যায় না, শুধু প্রিয় মানুষটির উপস্থিতিতেই হৃদয় হাসে।” 🌸\n\nসকালবেলা কলেজে এসেই মায়া দেখল, আরশ তার জন্য অপেক্ষা করছে।\n\nআরশকে দেখেই মায়া বলল,\n\n— কী ব্যাপার? আজ এত সকালে?\n\nআরশ হেসে বলল,\n\n— একজন বিশেষ মানুষের জন্য অপেক্ষা করছি।\n\nমায়া ভ্রু কুঁচকে বলল,\n\n— ওহ! কে সে?\n\n— যে এখন আমার সামনে দাঁড়িয়ে আছে।\n\nমায়া লজ্জা পেয়ে অন্যদিকে তাকাল।\n\n— আপনি না একদম অসহ্য!\n\nআরশ হেসে বলল,\n\n— তবুও তো আমার সঙ্গে কথা বলো!\n\nএভাবেই চলতে লাগল তাদের দিনগুলো।\n\nএকদিন ক্লাস শেষে আরশ মায়াকে একটা ছোট্ট গোলাপ দিল।\n\nমায়া অবাক হয়ে বলল,\n\n— এটা কেন?\n\n— এমনি।\n\n— এমনি কেউ গোলাপ দেয়?\n\nআরশ একটু চুপ থেকে বলল,\n\n— সবাইকে দিই না।\n\nমায়া গোলাপটা হাতে নিয়ে মুচকি হাসল। তার মনটা সেদিন অকারণেই ভালো হয়ে গেল।\n\nকিন্তু কয়েক দিন পর হঠাৎ আরশের আচরণ বদলে গেল। সে আর আগের মতো কথা বলে না, মায়ার দিকে তাকিয়েও যেন এড়িয়ে যায়।\n\nমায়ার খুব খারাপ লাগল।\n\nএকদিন সাহস করে জিজ্ঞেস করল,\n\n— আপনার কী হয়েছে? আমার সঙ্গে কথা বলেন না কেন?\n\nআরশ বলল,\n\n— কিছু হয়নি।\n\n— তাহলে আমাকে এড়িয়ে চলছেন কেন?\n\n— সব কথার উত্তর দেওয়া যায় না, মায়া।\n\nকথাটা শুনে মায়ার চোখে পানি চলে এল। সে আর কিছু না বলে চলে গেল।\n\nসেদিন রাতে মায়া বারবার ফোনের দিকে তাকাল। একটা মেসেজের অপেক্ষায় ছিল সে।\n\nহঠাৎ ফোনে মেসেজ এল।\n\nআরশ: রাগ করেছ?\n\nমায়া: না।\n\nআরশ: মিথ্যা বলছ।\n\nমায়া: আপনি তো এখন আর আমার খোঁজও নেন না।\n\nকিছুক্ষণ পর আরশের উত্তর এল।\n\nআরশ: তোমার সঙ্গে কথা না বললে আমার দিনটাও ভালো কাটে না। কিন্তু কিছু সমস্যার কারণে একটু চুপ হয়ে গিয়েছিলাম। সরি।\n\nমায়ার মুখে আবার হাসি ফুটল।\n\nসে লিখল,\n\nমায়া: আর কখনো এভাবে হারিয়ে যাবেন না।\n\nআরশ উত্তর দিল,\n\nআরশ: চেষ্টা করব। কারণ তোমার অভিমান ভাঙাতে আমার ভালো লাগে।\n\nমায়া ফোনটা বুকে চেপে ধরে মুচকি হাসল।\n\nকিন্তু তাদের অজান্তেই একটা নতুন ঝড় এগিয়ে আসছিল।\n\nপরদিন কলেজে এসে মায়া দেখল, আরশের পাশে দাঁড়িয়ে আছে একটি অচেনা মেয়ে।\n\nমেয়েটি আরশের হাত ধরে বলল,\n\n— আরশ, তুমি আমাকে ভুলে গেছ?\n\nমায়া দূর থেকে সবকিছু দেখছিল।\n\nতার মুখের হাসিটা ধীরে ধীরে মিলিয়ে গেল।\n\nচলবে... ❤️\n\nপরের পর্ব: কে এই অচেনা মেয়ে? আরশের জীবনে কি তবে অন্য কেউ আছে? 💔','\n',char(10)),2,'published',0,'2026-10-30 09:59:00','2026-10-30 09:59:00',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('1e563db8-ed58-45bc-a546-b8a92daddc7d','b98c6429-e76f-4896-8621-fd2d226b335c','পর্ব:০৩',replace('#মাফিয়া কিংয়ের পাগল করা ভালোবাসা \n#লেখিকা: কল্পনার গল্পকন্যা\n#পর্ব: ০৩\n\n“নীলাঞ্জনা তোমার অতীতের সবচেয়ে বড় রহস্যের অংশ!”\n\nবার্তাটা বারবার পড়ছিল আরহান। তার মাথায় একটাই প্রশ্ন—নীলা কীভাবে তার বাবার মৃত্যুর রহস্যের সঙ্গে জড়িয়ে থাকতে পারে?\n\n“স্যার, অফিসে যাব?” রায়ানের প্রশ্নে ভাবনা ভাঙল।\n\n“আগে এই নম্বরের মালিককে খুঁজে বের করো। আর মাহবুব রহমানের অতীতের প্রতিটি ঘটনা যাচাই করো। কাউকে বাদ দেবে না।”\n\n“বার্তাটা বিশ্বাস করছেন?”\n\nআরহান ফোন চেপে ধরল। “আমি কাউকে বিশ্বাস করি না। কিন্তু সত্যিটা না জেনে এবার কোনো চাল চালব না।”\n\nঅন্যদিকে, রহমান বাড়িতে নীলা বাবার সামনে দাঁড়িয়ে ছিল। মাহবুব অস্থিরভাবে ঘরের এদিক-ওদিক হাঁটছিলেন।\n\n“বাবা, তুমি আমাকে কিছুই বলছ না কেন? আরহান খান তোমাকে কীসের হিসাব মেলাতে বলল?”\n\n“নীলা, সব কথা জানার সময় এখনও আসেনি।”\n\nঠিক তখন নাহিয়ান ঘরে ঢুকল। নীলা বলল, “আরহান খান এসেছিল। বাবাকে হুমকি দিয়ে গেছে।”\n\nনাহিয়ানের মুখ শক্ত হয়ে গেল। “ওই লোক এখানে এসেছিল? তুমি তাকে চেনো না, নীলা। খান পরিবারের সঙ্গে আমাদের পুরোনো বিরোধ আছে, কিন্তু বিস্তারিত আমিও জানি না।”\n\nসে বাবার দিকে ফিরল। “বাবা, কী নিয়ে এত ভয় পাচ্ছ?”\n\nমাহবুব চোখ নামিয়ে বললেন, “তোমরা কেউ আরহানের সঙ্গে একা দেখা করবে না। বিশেষ করে তুই, নীলা।”\n\nকিন্তু নীলার মনে তখন হাজারো প্রশ্ন। আরহান খান কে? কেন তার বাবার নাম শুনলেই সবাই এমন অস্থির হয়ে পড়ে?\n\nসন্ধ্যায় আরহান অফিসে পুরোনো নথি খুলল। একটি বিবর্ণ ছবিতে তার বাবা আর মাহবুবকে পাশাপাশি দাঁড়িয়ে হাসতে দেখা যায়। ছবির পেছনের তারিখটি বাবার মৃত্যুর মাত্র এক দিন আগের।\n\nরায়ান এসে বলল, “স্যার, আপনার বাবার মৃত্যুর আগের রাতে তিনি মাহবুব রহমানের সঙ্গে দেখা করেছিলেন। পুরোনো কর্মচারী কাদের আলী নাকি কিছু জানে, কিন্তু বহু বছর আগে উধাও হয়ে গেছে।”\n\nআরহান তাকাল। “কাদের আলীকে খুঁজে বের করো।”\n\nরায়ান চলে গেলে আরহান নীলার ছবিটা হাতে নিল।\n\n“তুমি আমার প্রতিশোধের পথ, নীলাঞ্জনা,” সে নিজেকে বোঝাল। “এর বেশি কিছু নয়।”\n\nকিন্তু নিজের কথাতেই তার মন সায় দিল না। নীলার চোখে সে অপরাধীর পরিবারের অহংকার দেখেনি; দেখেছিল সরল রাগ আর নির্ভীকতা। তবে কি এত বছর ধরে সে ভুল মানুষকে দোষ দিয়ে এসেছে?\n\nপরদিন সকালে নীলা কলেজে যাওয়ার জন্য বেরিয়ে গেটের কাছে থমকে দাঁড়াল। রাস্তার ওপারে কালো গাড়ির পাশে দাঁড়িয়ে আছে আরহান খান। নীলাকে দেখেই সে এগিয়ে এল।\n\nনীলা বিরক্ত হয়ে বলল, “আপনি আবার এখানে? আমাদের বাড়িতে হুমকি দিয়ে এবার কলেজের সামনে হাজির?”\n\n“তোমার বাবার সম্পর্কে কিছু জানতে চাই।”\n\n“নিজের শত্রুর মেয়েকে দিয়ে তার বাবার খবর নেবেন? বাহ, সাহস তো কম নয়!”\n\nআরহানের মুখ শক্ত হলো। “আমি তোমাকে শত্রু বলিনি।”\n\n“কিন্তু আপনার চোখে সেটাই লেখা।”\n\n“তোমার বাবাকে জিজ্ঞেস করো—সেই রাতে তিনি আমার বাবার সঙ্গে কেন দেখা করেছিলেন।”\n\nনীলার পা থেমে গেল। “কোন রাত?”\n\n“যে রাতের পর আমার পরিবার সবকিছু হারিয়েছিল।”\n\nনীলা দৃঢ় কণ্ঠে বলল, “আমি জানি না আপনি কী বলতে চাইছেন। বাবাকে অপরাধী ভাবার আগে প্রমাণ নিয়ে আসবেন।”\n\nআরহান থমকে গেল। “প্রমাণ খুঁজছি বলেই তোমার কাছে এসেছি।”\n\n“তাহলে খুঁজুন। আমাকে জড়াবেন না।”\n\nনীলা চলে যেতে উদ্যত হলে আরহান নিচু স্বরে বলল, “সাবধানে থেকো। কেউ আমাদের দুজনকেই নজরে রাখছে।”\n\nনীলা কোনো উত্তর না দিয়ে চলে গেল। আরহান তার নিরাপত্তা নিয়ে চিন্তিত হয়ে পড়ল।\n\nবাড়ি ফিরে নীলা বাবাকে প্রশ্ন করতেই মাহবুবের হাত থেকে পানির গ্লাস পড়ে ভেঙে গেল।\n\n“তুই কার কাছ থেকে এই কথা শুনেছিস?”\n\n“আরহান বলেছে। বাবা, সেই রাতে আসলে কী ঘটেছিল?”\n\nমাহবুবের ঠোঁট কাঁপল। তিনি উত্তর দেওয়ার আগেই জানালার বাইরে একটি কালো গাড়ি এসে থামল। গাড়ির কাচের আড়াল থেকে কেউ বাড়ির দিকে তাকিয়ে ছিল।\n\nমাহবুব পর্দা সরিয়ে ফিসফিস করলেন, “না… ওরা আবার ফিরে এসেছে!”\n\nনীলা তাকাল। “ওরা কারা, বাবা?”\n\nমাহবুব উত্তর দিলেন না। শুধু মেয়েকে কাছে টেনে বললেন, “আজ থেকে একা কোথাও যাবি না। আরহানকে বিশ্বাস করিস না, কিন্তু তার কাছ থেকে দূরেও থাকিস না। সত্যিটা হয়তো তার কাছেই আছে।”\n\nসেই রাতেই আরহানের ফোনে আরেকটি বার্তা এল—\n\n“কাদের আলীকে খুঁজে লাভ নেই। সত্যিটা রহমান বাড়ির পুরোনো ঘড়ির ভেতরে লুকানো। দেরি করলে নীলাঞ্জনার জীবন বিপদে পড়বে।”\n\nআরহান উঠে দাঁড়িয়ে রায়ানকে ফোন করল। “রহমান বাড়ির ওপর নজর রাখো। নীলার গায়ে কেউ যেন হাত না দেয়।” সে বুঝল, বিষয়টা আর শুধু প্রতিশোধের নেই।\n\nচলবে… 🖤🥀','\n',char(10)),3,'published',0,'2026-10-30 11:44:06','2026-10-30 11:44:06',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('317d4e91-d4db-4cc0-923c-788082200e0b','1ac803b2-41a1-4776-8e00-c04cfaabe4af','পর্ব:০২',replace('Worked for 10s\n\n🖤 অনিচ্ছায় তুমি, অনুভবে তুমি 🖤\n\nলেখিকা: হুমাইরা জান্নাত\nপর্ব: ০২\n\nসকালের আলো ধীরে ধীরে চৌধুরী বাড়ির প্রতিটি জানালায় ছড়িয়ে পড়েছে।\n\nবাড়ির সবাই একে একে ঘুম থেকে উঠে পড়েছে। রান্নাঘর থেকে ভেসে আসছে নাশতা তৈরির শব্দ। কাজের লোকেরা ব্যস্ত, আর বসার ঘরে বসে খবরের কাগজ পড়ছেন মাহির চৌধুরী।\n\nতিন বছর পর বাড়ির বড় ছেলে ফিরে এসেছে। তাই আজ সবার মনেই আলাদা আনন্দ।\n\nঅন্যদিকে, নিজের ঘরে ঘুমাচ্ছিল মাহিরা।\n\nগত রাতে অনেকক্ষণ পর্যন্ত তার ঘুম আসেনি। তিন বছর পর আরহামকে সামনে থেকে দেখেছে সে। অথচ মানুষটার মধ্যে কোনো পরিবর্তন নেই। সেই একই গম্ভীর মুখ, একই অবহেলা।\n\nমাহিরা বালিশের পাশে রাখা ফোনটা হাতে নিয়ে সময় দেখল।\n\nসকাল আটটা!\n\nসে তাড়াতাড়ি বিছানা থেকে উঠে বসে বলল,\n\n— আল্লাহ! আজকে তো আমার ক্লাস আছে!\n\nদ্রুত বিছানা ছেড়ে বাথরুমে ঢুকে পড়ল সে।\n\nকিছুক্ষণ পর গোসল সেরে বেরিয়ে এসে আলমারি খুলল। একটা সুন্দর সালোয়ার-কামিজ বের করে পরে নিল। তারপর চুলগুলো আঁচড়ে ব্যাগ গোছাতে শুরু করল।\n\nআয়নার সামনে দাঁড়িয়ে নিজেকে দেখে বলল,\n\n— আজকে কিন্তু কোনোভাবেই মেজাজ খারাপ করা যাবে না। বিশ্ববিদ্যালয়ে গিয়ে তানিয়ার সঙ্গে একটু আড্ডা দেব। তারপর বাসায় ফিরে শান্তিতে থাকব।\n\nকথাটা বলেই নিজেকে একটা হাসি উপহার দিল।\n\nকিন্তু নিচে যে তার জন্য অন্য রকম একটা সকাল অপেক্ষা করছে, সেটা সে জানত না।\n\nঅন্যদিকে, আরহামের ঘর।\n\nআরহাম ঘুম থেকে উঠে ফ্রেশ হয়ে নিচে যাওয়ার প্রস্তুতি নিচ্ছিল। তিন বছর পর নিজের বাড়িতে ফিরলেও তার প্রতিদিনের অভ্যাসের কোনো পরিবর্তন হয়নি।\n\nঠিক তখনই দরজায় টোকা পড়ল।\n\n— আসব বাবা?\n\nআরহাম দরজার দিকে তাকিয়ে বলল,\n\n— আসো, মা।\n\nমেহেরিমা বেগম ঘরে ঢুকে ছেলের দিকে তাকিয়ে মৃদু হাসলেন।\n\n— ঘুম ভালো হয়েছে তো?\n\n— হ্যাঁ, মা।\n\n— চল, নিচে চল। সবাই নাশতার টেবিলে তোর জন্য অপেক্ষা করছে।\n\nআরহাম ঘড়ির দিকে তাকিয়ে বলল,\n\n— তোমরা খেয়ে নিলেই পারতে। আমার জন্য অপেক্ষা করার কী আছে?\n\nমেহেরিমা বেগম ছেলের কাছে এসে তার কাঁধে হাত রাখলেন।\n\n— তিন বছর পর ছেলে বাড়ি ফিরেছে। তার সঙ্গে একসঙ্গে নাশতা করব না, তা কি হয়?\n\nআরহাম মায়ের দিকে তাকিয়ে মৃদু হাসল।\n\n— আচ্ছা, চলো।\n\nদুজন একসঙ্গে নিচে নেমে এল।\n\nনাশতার টেবিলে তখন জাহানারা বেগম, মাহির চৌধুরীসহ পরিবারের অন্য সদস্যরা বসে ছিলেন।\n\nআরহামকে দেখে দাদি বললেন,\n\n— আয়, বাবা। আমার পাশে এসে বস।\n\nআরহাম দাদির পাশে বসে বলল,\n\n— কেমন আছেন, দাদি?\n\n— আমি ভালো আছি। তুই কেমন আছিস, সেটাই বল।\n\n— ভালো আছি।\n\nজাহানারা বেগম নাতির মাথায় হাত বুলিয়ে বললেন,\n\n— এবার আর কোথাও যাওয়ার কথা ভাববি না। অনেক দিন তো বিদেশে থাকলি।\n\nআরহাম মৃদু হেসে বলল,\n\n— আপাতত কোথাও যাচ্ছি না, দাদি।\n\n— এই তো আমার ভালো ছেলে!\n\nকথাটা শুনে সবাই হেসে উঠল।\n\nঠিক তখনই সিঁড়ি দিয়ে নামতে নামতে মাহিরা বলে উঠল,\n\n— সুপ্রভাত সবাইকে!\n\nসবাই তার দিকে তাকাল।\n\nমেহেরিমা বেগম বললেন,\n\n— এই তো আমাদের ঘুমকুমারী এসে গেছে!\n\nমাহিরা মুখ বাঁকিয়ে বলল,\n\n— মা, আমি কিন্তু ঘুমকুমারী না। আমার ঘুমের খুব শখ, এই যা!\n\nদাদি হেসে বললেন,\n\n— আয় মা, এখানে বস।\n\nমাহিরা দাদির পাশে বসতে যাচ্ছিল, কিন্তু তার চোখ পড়ল আরহামের দিকে।\n\nগত রাতের মতো আজও মানুষটা নিজের ফোনের দিকে তাকিয়ে আছে।\n\nমাহিরা মনে মনে বলল,\n\n''বাহ! দেশে ফিরে প্রথম সকালেই ফোনের সঙ্গে প্রেম শুরু হয়ে গেছে!''\n\nনিজের মনেই হেসে ফেলল সে।\n\nমেহেরিমা বেগম বললেন,\n\n— কী হয়েছে, মা? একা একা হাসছিস কেন?\n\nমাহিরা দ্রুত মাথা নেড়ে বলল,\n\n— কিছু না, মা। এমনিই।\n\nজাহানারা বেগম মাহিরাকে খাবার দিতে দিতে বললেন,\n\n— নে মা, নাশতা কর।\n\nমাহিরা প্লেটে খাবার নিয়ে খেতে শুরু করল।\n\nকিছুক্ষণ পর মেহেরিমা বেগম বললেন,\n\n— মাহিরা, আজ বিশ্ববিদ্যালয়ে যাবি?\n\n— হ্যাঁ, মা। আজকে ক্লাস আছে।\n\n— আরহামও আজ অফিসে যাবে। চাইলে ওর সঙ্গে চলে যেতে পারিস।\n\nকথাটা শুনে মাহিরার হাত থেমে গেল।\n\nসে একবার আরহামের দিকে তাকিয়ে আবার মায়ের দিকে তাকাল।\n\n— না মা, আমার গাড়ি আছে। আমি নিজেই চলে যাব।\n\nমেহেরিমা বেগম বললেন,\n\n— আরে, একই পথে গেলে একসঙ্গে যেতে সমস্যা কী?\n\nমাহিরা কিছু বলার আগেই আরহাম গম্ভীর গলায় বলল,\n\n— আমার অফিসে যাওয়ার সময় নির্দিষ্ট। ওর ক্লাসের সময়ের সঙ্গে মিলবে কি না জানি না।\n\nমাহিরা সঙ্গে সঙ্গে বলল,\n\n— চিন্তা করবেন না। আপনাকে আমার জন্য অপেক্ষা করতে হবে না।\n\nআরহাম এবার ফোন থেকে মুখ তুলে তার দিকে তাকাল।\n\n— আমি তো অপেক্ষা করার কথাও বলিনি।\n\nমাহিরা মুচকি হেসে বলল,\n\n— আমিও তো বলিনি যে আপনি অপেক্ষা করবেন।\n\nদুজনের কথার মাঝখানে জাহানারা বেগম বলে উঠলেন,\n\n— তোরা দুজন নাশতা করবি, নাকি সকাল সকাল ঝগড়া শুরু করবি?\n\nমাহিরা সঙ্গে সঙ্গে দাদির গলা জড়িয়ে ধরে বলল,\n\n— দাদি, আমি তো কিছুই বলিনি। উনিই আমাকে কথা শোনাচ্ছেন।\n\nআরহাম বিরক্ত হয়ে বলল,\n\n— আমি তোমাকে কিছু বলিনি।\n\n— আচ্ছা, ঠিক আছে। আপনি কিছু বলেননি। আমি নিজেই নিজের সঙ্গে কথা বলছিলাম।\n\nমাহিরার কথা শুনে দাদি হেসে ফেললেন।\n\nআরহাম আর কোনো উত্তর না দিয়ে আবার নিজের খাবারে মনোযোগ দিল।\n\nমাহিরা মনে মনে বলল,\n\n''উফ! কী অসহ্য মানুষ!''\n\nনাশতা শেষ করে মাহিরা ব্যাগ হাতে উঠে দাঁড়াল।\n\n— মা, আমি যাচ্ছি।\n\nরোকেয়া বেগম বললেন,\n\n— সাবধানে যাস। আর দুপুরে সময়মতো খেয়ে নিবি।\n\n— ঠিক আছে, মা।\n\nদাদির কাছে গিয়ে সালাম করে বেরিয়ে গেল সে।\n\nআরহামও কিছুক্ষণ পর অফিসে যাওয়ার জন্য উঠে দাঁড়াল।\n\nজাহানারা বেগম নাতির হাত ধরে বললেন,\n\n— বাবা, মাহিরার সঙ্গে একটু ভালোভাবে কথা বলিস। মেয়েটা অনেক কষ্ট পেয়েছে।\n\nআরহাম কিছুক্ষণ চুপ করে থেকে বলল,\n\n— দাদি, আমি এখন অফিসে যাচ্ছি। পরে কথা হবে।\n\nকথাটা বলে সে বেরিয়ে গেল।\n\nজাহানারা বেগম দীর্ঘশ্বাস ফেললেন।\n\nতিনি মনে মনে শুধু একটাই প্রার্থনা করলেন, একদিন যেন এই দুজন মানুষ একে অপরকে বুঝতে শেখে।\n\n\n---\n\nঅন্যদিকে, বিশ্ববিদ্যালয়ের সামনে গাড়ি থেকে নেমে মাহিরা তানিয়াকে ফোন করল।\n\n— হ্যালো, তানিয়া! কোথায় তুই?\n\nওপাশ থেকে তানিয়া বলল,\n\n— গেটের সামনে। তুই কোথায়?\n\n— আমিও চলে এসেছি। দাঁড়া, আসছি।\n\nফোন রেখে মাহিরা দ্রুত গেটের দিকে এগিয়ে গেল।\n\nতানিয়া তাকে দেখেই বলল,\n\n— এই যে ম্যাডাম! আজ এত দেরি কেন?\n\nমাহিরা দীর্ঘশ্বাস ফেলে বলল,\n\n— আর বলিস না। সকালে বাসায় এমন একটা বিরক্তিকর পরিস্থিতির মধ্যে পড়েছিলাম!\n\nতানিয়া ভ্রু কুঁচকে বলল,\n\n— কী হয়েছে আবার?\n\nমাহিরা চারদিকে তাকিয়ে নিচু গলায় বলল,\n\n— আমার জীবনের সবচেয়ে বড় বিরক্তিটা আবার বাসায় ফিরে এসেছে।\n\nতানিয়া কিছুক্ষণ তার দিকে তাকিয়ে থেকে হেসে ফেলল।\n\n— আরহাম ভাইয়া?\n\nমাহিরা চোখ বড় বড় করে বলল,\n\n— আস্তে! এত জোরে বলছিস কেন?\n\n— তাহলে ঠিকই ধরেছি!\n\n— হ্যাঁ। মানুষটা দেশে ফিরে এসেছে, আর আমার শান্তিটাও মনে হয় সঙ্গে করে নিয়ে গেছে।\n\nতানিয়া হাসতে হাসতে বলল,\n\n— আচ্ছা, আচ্ছা। এবার বল, কাল রাতে তোদের কথা হয়েছে?\n\nমাহিরা মুখ গম্ভীর করে বলল,\n\n— কথা হয়েছে মানে? দুটো প্রশ্নের উত্তর দিয়েছে। তাও এক শব্দে!\n\n— বাহ! তিন বছর পর দেখা, আর কথাবার্তা মাত্র দুই শব্দে?\n\n— হ্যাঁ। মনে হয় শব্দেরও অভাব পড়েছে!\n\nদুজনেই হেসে উঠল।\n\nতানিয়া মাহিরার হাত ধরে বলল,\n\n— বাদ দে। আজ সারাদিন শুধু পড়াশোনা আর আড্ডা। কোনো মন খারাপ চলবে না।\n\nমাহিরা হাসিমুখে বলল,\n\n— একদম ঠিক বলেছিস। আমি আর কারও জন্য নিজের মেজাজ নষ্ট করব না।\n\nএরপর দুজন ক্লাসরুমের দিকে এগিয়ে গেল।\n\n\n---\n\nঅন্যদিকে, চৌধুরী গ্রুপের অফিস।\n\nআরহাম নিজের কেবিনে বসে কাজ করছিল। তিন বছর বিদেশে থাকার পরও ব্যবসার প্রতিটি বিষয় তার নখদর্পণে।\n\nতার ব্যক্তিগত সহকারী রায়ান কিছু ফাইল নিয়ে কেবিনে প্রবেশ করল।\n\n— স্যার, আপনার আজকের মিটিংয়ের ফাইলগুলো।\n\nআরহাম ফাইলগুলো হাতে নিয়ে বলল,\n\n— টেবিলে রেখে যাও।\n\n— জি, স্যার।\n\nরায়ান ফাইল রেখে চলে যেতে উদ্যত হলে আরহাম বলল,\n\n— এক মিনিট।\n\nরায়ান থেমে গেল।\n\n— জি, স্যার?\n\n— আগামী কয়েক দিনের মিটিংগুলো একটু গুছিয়ে দাও। পরিবারের সঙ্গে কিছুটা সময় কাটাতে চাই।\n\nরায়ান অবাক হলেও কিছু প্রকাশ করল না।\n\n— ঠিক আছে, স্যার।\n\nআরহাম আবার কাজে মনোযোগ দিল।\n\nকিন্তু কিছুক্ষণ পর তার ফোনে একটি কল এল।\n\nফোনের স্ক্রিনে মায়ের নাম দেখে কল রিসিভ করল।\n\n— হ্যাঁ, মা।\n\nওপাশ থেকে মেহেরিমা বেগম বললেন,\n\n— বাবা, আজ কি সময়মতো বাসায় ফিরতে পারবি?\n\n— কেন, মা?\n\n— তোর দাদি সবাইকে নিয়ে সন্ধ্যায় একসঙ্গে বসতে চায়। তুই থাকলে ভালো হয়।\n\nআরহাম কিছুক্ষণ ভেবে বলল,\n\n— ঠিক আছে। চেষ্টা করব।\n\n— চেষ্টা না, সময়মতো আসবি কিন্তু।\n\nআরহাম মৃদু হেসে বলল,\n\n— আচ্ছা, মা।\n\nকল শেষ করে সে আবার কাজে মন দিল।\n\n\n---\n\nবিকেল।\n\nবিশ্ববিদ্যালয়ের ক্লাস শেষ করে মাহিরা বাড়ি ফিরল।\n\nবাড়িতে ঢুকেই সে বুঝতে পারল, সবাই বসার ঘরে বসে আছে।\n\nতানিয়ার সঙ্গে আড্ডা দিয়ে তার মনটাও বেশ ভালো হয়ে গেছে।\n\nসে হাসিমুখে বলল,\n\n— আসসালামু আলাইকুম! আমার অনুপস্থিতিতে কী কী আলোচনা হচ্ছে?\n\nজাহানারা বেগম হেসে বললেন,\n\n— আয় মা, তোর কথাই বলছিলাম।\n\nমাহিরা অবাক হয়ে বলল,\n\n— আমার কথা? আবার কী করলাম আমি?\n\nমাহির চৌধুরী হেসে বললেন,\n\n— তুই নাকি আজকাল পড়াশোনার চেয়ে আড্ডা বেশি দিস?\n\nমাহিরা সঙ্গে সঙ্গে তানিয়ার নাম না নিয়ে বলল,\n\n— বাবা, এগুলো সব মিথ্যা অপবাদ! আমি খুব মনোযোগ দিয়ে পড়াশোনা করি।\n\nঠিক তখনই পেছন থেকে একটা গম্ভীর কণ্ঠ ভেসে এল,\n\n— সেটা তো তোর রেজাল্ট দেখলেই বোঝা যাবে।\n\nমাহিরা ঘুরে তাকাল।\n\nআরহাম!\n\nসে কখন যে বাড়িতে এসেছে, মাহিরা খেয়ালই করেনি।\n\nমাহিরা ভ্রু কুঁচকে বলল,\n\n— আমার রেজাল্ট নিয়ে আপনাকে এত চিন্তা করতে হবে না।\n\nআরহাম স্বাভাবিক গলায় বলল,\n\n— আমি চিন্তা করছি না। শুধু বললাম।\n\nমাহিরা মুখ বাঁকিয়ে বলল,\n\n— তাহলে না বললেও পারতেন।\n\nআরহাম কোনো উত্তর দিল না।\n\nসে সোফায় বসে পড়ল।\n\nজাহানারা বেগম দুজনের দিকে তাকিয়ে মুচকি হাসলেন।\n\n— তোরা দুজন একটু শান্তিতে থাকতে পারিস না?\n\nমাহিরা দাদির পাশে গিয়ে বসে বলল,\n\n— দাদি, আমি কিন্তু শান্তিতেই থাকি। কেউ কেউ আমাকে শান্তিতে থাকতে দেয় না।\n\nআরহাম এবার তার দিকে তাকিয়ে বলল,\n\n— সব দোষ আমার?\n\nমাহিরা মিষ্টি হেসে বলল,\n\n— আপনি চাইলে নিজের দোষ নিজেই বুঝতে পারেন।\n\nকথাটা শুনে মাহির চৌধুরী হেসে ফেললেন।\n\nআরহাম শুধু দীর্ঘশ্বাস ছাড়ল।\n\nতবে আজ প্রথমবার তার মনে হলো, মাহিরা আগের মতো নেই।\n\nআগে সে আরহামের সামনে এলেই নানা অজুহাতে কথা বলার চেষ্টা করত। আর এখন সুযোগ পেলেই তার সঙ্গে তর্ক করছে।\n\nকিন্তু কেন?\n\nএই প্রশ্নটা এক মুহূর্তের জন্য তার মনে এলেও সে গুরুত্ব দিল না।\n\nঅন্যদিকে, মাহিরাও মনে মনে ঠিক করে নিল, আরহামের সঙ্গে যতটা সম্ভব কম কথা বলবে।\n\nকিন্তু একই বাড়িতে থাকলে কি আর এত সহজে সেটা সম্ভব?\n\nসময়ই হয়তো তার উত্তর দেবে।\n\nসন্ধ্যার আড্ডা, পরিবারের হাসি-আনন্দ আর দুজনের ছোট ছোট খুনসুটির মধ্য দিয়ে চৌধুরী বাড়ির দিনটা শেষ হতে চলল।\n\nকিন্তু তাদের সম্পর্কের বরফ এখনো গলেনি।\n\nবরং তিন বছর পর শুরু হয়েছে এক নতুন অধ্যায়—যেখানে অভিমান আছে, বিরক্তি আছে, তর্ক আছে; আর আছে একে অপরকে নতুন করে চেনার অপেক্ষা।\n\nচলবে… 🖤\n\nপর্বটি ভালো লাগলে লাইক দিয়ে কমেন্টে জানিয়ো। \n***উপন্যাস টির পর্ব তাড়াতাড়ি পেতে হলে আমার ফেসবুক পেজ (হুমাইরা জান্নাত//Humaira Jannat) পেজটি ফলো করে রাখো ওখানে ___ অনিচ্ছায় তুমি, অনুভবে তুমি উপন্যাস এর পর্ব তাড়াতাড়ি দেওয়া হবে। তাই পেজটি ফলো করে রাখো 🌸','\n',char(10)),2,'published',0,'2026-10-30 11:50:32','2026-10-30 11:50:32',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('55ccb666-5bbf-4046-9299-b25ebde1a148','95b4cdd4-4d37-4bb2-ba1c-996e967b1061','পর্ব ৬',replace('রাত তখন প্রায় এগারোটা।\nআরিশের ঘরের জানালায় বৃষ্টির ফোঁটা এসে পড়ছিল। ফোনের স্ক্রিনে নওরিনের শেষ মেসেজটা তখনও খোলা।\n\n“আরিশ, তোমাকে একটা সত্য জানাতে হবে। এত দিন আমি তোমার কাছ থেকে যে কথাটা লুকিয়ে রেখেছিলাম, সেটাই আমাদের বিচ্ছেদের আসল কারণ।”\n\nআরিশ অনেকক্ষণ মেসেজটার দিকে তাকিয়ে রইল।\n\nযে মানুষটাকে একসময় নিজের পৃথিবী ভেবেছিল, সেই মানুষটাই আজ আবার তার অতীতের দরজায় দাঁড়িয়ে। অথচ সেই দরজার ওপাশে কী আছে, তা জানার সাহস তার হচ্ছিল না।\n\nকিছুক্ষণ পর আরিশ লিখল,\n\n“কাল দেখা হবে। সব কথা খুলে বলবে।”\n\nনওরিন সঙ্গে সঙ্গে উত্তর দিল।\n\n“ধন্যবাদ, আরিশ। আমি জানি, তোমার কাছে ক্ষমা চাওয়ার অধিকারটুকুও হয়তো আমার নেই। তবুও কাল সব বলব।”\n\nআরিশ ফোনটা পাশে রেখে চোখ বন্ধ করল।\n\nকিন্তু ঘুম এল না।\n\nবারবার তার মনে পড়তে লাগল মায়ার কথা।\n\nমায়ার সঙ্গে কথা বললে তার মনটা অদ্ভুতভাবে শান্ত হয়ে যায়। মায়া কখনো তার অতীত নিয়ে জোর করে প্রশ্ন করেনি। কখনো তাকে বদলে দেওয়ার চেষ্টা করেনি। শুধু পাশে থেকেছে।\n\nআরিশ নিজেই বুঝতে পারছিল, মায়া তার জীবনে ধীরে ধীরে এমন একটা জায়গা তৈরি করছে, যেখানে সে আবার বিশ্বাস করতে শিখছে।\n\nপরদিন বিকেলে কলেজের পেছনের পুরোনো বটগাছটার নিচে মায়া দাঁড়িয়ে ছিল।\n\nআরিশ দূর থেকে তাকে দেখে এগিয়ে গেল।\n\n“অনেকক্ষণ অপেক্ষা করছ?”\n\nমায়া মাথা নাড়ল।\n\n“না। একটু আগে এসেছি।”\n\nআরিশ তার পাশে দাঁড়াল।\n\nকিছুক্ষণ দুজনেই চুপ।\n\nতারপর মায়া বলল,\n\n“কাল রাতে তোমার সঙ্গে কথা বলতে চেয়েছিলাম। কিন্তু মনে হলো, তুমি হয়তো নিজের মতো থাকতে চাইছ।”\n\nআরিশ অবাক হয়ে তাকাল।\n\n“তুমি কীভাবে বুঝলে?”\n\n“তোমার কথার মধ্যে একটা অস্থিরতা ছিল। তুমি কিছু বলতে চাইছিলে, কিন্তু বলছিলে না।”\n\nআরিশ হালকা হাসল।\n\n“তুমি সব বুঝে ফেলো কেন?”\n\nমায়া মৃদু স্বরে বলল,\n\n“সব বুঝি না। শুধু তোমার চুপ করে থাকাটা বুঝতে চেষ্টা করি।”\n\nআরিশের হাসিটা ধীরে ধীরে মিলিয়ে গেল।\n\n“আজ নওরিনের সঙ্গে আবার দেখা করব।”\n\nমায়া কিছুক্ষণ চুপ করে রইল।\n\nতারপর বলল,\n\n“তুমি কি এখনো ওকে ভালোবাসো?”\n\nপ্রশ্নটা শুনে আরিশ থমকে গেল।\n\nসে উত্তর দিতে চাইল, কিন্তু শব্দ খুঁজে পেল না।\n\nমায়া তার দিকে তাকিয়ে বলল,\n\n“উত্তর দিতে হবে না। আমি শুধু জানতে চেয়েছিলাম।”\n\nআরিশ নিচু স্বরে বলল,\n\n“আমি জানি না, মায়া। একটা সময় ওকে ছাড়া কিছু ভাবতে পারতাম না। কিন্তু এখন... এখন সবকিছু আগের মতো মনে হয় না।”\n\nমায়া চোখ নামিয়ে বলল,\n\n“তাহলে নিজের মনকে সময় দাও। তাড়াহুড়ো করে কোনো সিদ্ধান্ত নিও না।”\n\nআরিশ কিছুক্ষণ তার দিকে তাকিয়ে রইল।\n\n“তুমি আমার ওপর রাগ করছ না?”\n\n“কেন রাগ করব?”\n\n“কারণ আমি এখনো আমার অতীত থেকে পুরোপুরি বের হতে পারিনি।”\n\nমায়া একটু হেসে বলল,\n\n“তোমার অতীত তোমার জীবনের একটা অংশ। সেটা মুছে ফেলতে হবে না। শুধু এমনভাবে বাঁচতে হবে, যেন অতীত তোমার বর্তমানটা কেড়ে নিতে না পারে।”\n\nআরিশের বুকের ভেতর কথাগুলো কোথাও গভীরভাবে ছুঁয়ে গেল।\n\nসে আস্তে করে বলল,\n\n“তুমি জানো, তোমার সঙ্গে কথা বললে আমার মনে হয়, সবকিছু আবার নতুন করে শুরু করা সম্ভব।”\n\nমায়া এবার তার দিকে তাকাল।\n\n“তাহলে নতুন করে শুরু করার আগে নিজের পুরোনো কষ্টগুলোকে বুঝে নাও।”\n\nকথাটা বলে মায়া চলে গেল।\n\nআরিশ কিছুক্ষণ বটগাছটার নিচে দাঁড়িয়ে রইল।\n\nতার মনে হলো, মায়া তাকে কোনো সিদ্ধান্তের দিকে ঠেলে দিচ্ছে না। বরং নিজের সিদ্ধান্ত নিজে নেওয়ার সাহস দিচ্ছে।\n\nসন্ধ্যায় আরিশ পৌঁছাল সেই পুরোনো ক্যাফেতে।\n\nনওরিন আগে থেকেই বসে ছিল।\n\nআরিশ সামনে বসতেই নওরিন বলল,\n\n“তুমি এসেছ, এটা আমার কাছে অনেক বড় ব্যাপার।”\n\nআরিশ শান্ত গলায় বলল,\n\n“তুমি বলেছিলে, আমাদের বিচ্ছেদের আসল কারণটা জানাবে।”\n\nনওরিন মাথা নিচু করল।\n\n“হ্যাঁ। আজ আর কিছু লুকাব না।”\n\nসে ব্যাগ থেকে একটা পুরোনো খাম বের করল।\n\nখামের ভেতরে কয়েকটা চিঠি আর একটা ছবি ছিল।\n\nছবিটা দেখে আরিশের চোখ থেমে গেল।\n\nছবিতে সে আর নওরিন পাশাপাশি দাঁড়িয়ে ছিল। সেই দিনটার কথা তার মনে পড়ে গেল, যেদিন নওরিন হঠাৎ তার জীবন থেকে হারিয়ে গিয়েছিল।\n\nআরিশ ছবিটা টেবিলে রেখে বলল,\n\n“এগুলো কেন এনেছ?”\n\nনওরিন কাঁপা গলায় বলল,\n\n“কারণ আমি চাই, তুমি সবকিছু নিজের চোখে দেখো।”\n\nসে একটা চিঠি আরিশের দিকে এগিয়ে দিল।\n\n“এটা তোমার জন্য লেখা হয়েছিল। কিন্তু তখন তোমাকে দিতে পারিনি।”\n\nআরিশ চিঠিটা খুলল।\n\nচিঠির প্রথম কয়েকটা লাইন পড়তেই তার মুখের ভাব বদলে গেল।\n\n“আরিশ,\n\nআমি জানি, তুমি আমাকে ভুল বুঝবে। হয়তো কোনোদিন ক্ষমাও করবে না। কিন্তু তোমাকে একটা কথা জানানো দরকার।\n\nআমার চলে যাওয়ার সিদ্ধান্তটা শুধু আমার ছিল না।\n\nতোমার কাছ থেকে দূরে যাওয়ার আগে আমি এমন একটা সত্য জানতে পেরেছিলাম, যেটা তোমাকে বলার সাহস আমার হয়নি।”\n\nআরিশ চিঠিটা নামিয়ে নওরিনের দিকে তাকাল।\n\n“কী সত্য?”\n\nনওরিন চোখের পানি মুছে বলল,\n\n“তোমার মনে আছে, আমাদের শেষ দেখা হওয়ার আগের দিন তুমি আমাকে ফোন করেছিলে?”\n\n“মনে আছে।”\n\n“সেদিন আমি তোমার সঙ্গে দেখা করতে চেয়েছিলাম। কিন্তু আমার পরিবারের একজন আমাকে তোমার সঙ্গে দেখা করতে নিষেধ করেছিল।”\n\nআরিশের কপালে ভাঁজ পড়ল।\n\n“কেন?”\n\nনওরিন কিছুক্ষণ চুপ করে থেকে বলল,\n\n“কারণ তারা তোমার সম্পর্কে এমন কিছু জানতে পেরেছিল, যেটা আমি বিশ্বাস করতে পারিনি।”\n\nআরিশের কণ্ঠ কঠিন হয়ে উঠল।\n\n“আমার সম্পর্কে কী?”\n\nনওরিন তার চোখের দিকে তাকাল।\n\n“তারা বলেছিল, তুমি নাকি আমার সঙ্গে সম্পর্ক রাখার পাশাপাশি অন্য একজনের সঙ্গেও কথা বলছিলে। এমনকি তারা আমাকে কিছু মেসেজও দেখিয়েছিল।”\n\nআরিশ অবাক হয়ে বলল,\n\n“কী বলছ তুমি? আমি কখনো—”\n\n“আমি জানি,” নওরিন দ্রুত বলল। “এখন আমি জানি, সেই মেসেজগুলো সত্যি ছিল না।”\n\nআরিশের মুখটা ফ্যাকাশে হয়ে গেল।\n\n“তাহলে তুমি আমাকে বিশ্বাস করোনি?”\n\nনওরিন চোখ নামিয়ে বলল,\n\n“আমি তখন খুব ভেঙে পড়েছিলাম। তোমাকে প্রশ্ন করার বদলে আমি নিজেই সিদ্ধান্ত নিয়ে ফেলেছিলাম। তারপর পরিবার আমাকে অন্য শহরে নিয়ে যায়। আমি তোমাকে ফোন করতে চেয়েছিলাম, কিন্তু প্রতিবারই আমাকে থামানো হয়েছিল।”\n\nআরিশ দীর্ঘশ্বাস ফেলল।\n\n“তুমি একবারও আমাকে সত্যিটা জানার সুযোগ দিলে না।”\n\nনওরিনের চোখ দিয়ে পানি গড়িয়ে পড়ল।\n\n“আমি ভুল করেছি, আরিশ। খুব বড় ভুল।”\n\nআরিশ চুপ করে রইল।\n\nতার মনে হচ্ছিল, এত বছর ধরে যে প্রশ্নটা তাকে কষ্ট দিয়েছে, তার উত্তর হয়তো আজ পেয়ে গেছে।\n\nকিন্তু উত্তর পাওয়ার পরও বুকের ভেতরের কষ্টটা কমল না।\n\nসে ধীরে বলল,\n\n“তুমি কি জানো, তোমার চলে যাওয়ার পর আমি কতবার নিজেকে দোষ দিয়েছি? কতবার ভেবেছি, হয়তো আমার মধ্যেই কোনো ভুল ছিল?”\n\nনওরিন মাথা নিচু করে বলল,\n\n“আমি জানি। আর সেই কারণেই আজ তোমার সামনে দাঁড়িয়ে ক্ষমা চাইছি।”\n\nআরিশ কিছুক্ষণ চুপ করে থেকে বলল,\n\n“তুমি কি এখনো আমাকে ভালোবাসো?”\n\nনওরিনের চোখে আবার পানি চলে এল।\n\n“হ্যাঁ। আমি এখনো তোমাকে ভালোবাসি।”\n\nক্যাফের চারপাশে তখন সন্ধ্যার আলো ধীরে ধীরে ম্লান হয়ে আসছিল।\n\nআরিশ জানালার বাইরে তাকাল।\n\nএকসময় এই কথাটা শুনলে তার পৃথিবীটা আনন্দে ভরে উঠত।\n\nকিন্তু আজ সেই একই কথা শুনে তার মনে শুধু একটা প্রশ্ন জাগল।\n\nসে কি এখনো সেই মানুষটাকে ভালোবাসে, নাকি শুধু পুরোনো স্মৃতিগুলোকে?\n\nনওরিন আস্তে করে বলল,\n\n“আমি জানি, তুমি এখন অন্য কাউকে নিয়ে ভাবছ।”\n\nআরিশ তার দিকে তাকাল।\n\n“মায়ার কথা বলছ?”\n\nনওরিন মাথা নাড়ল।\n\n“হ্যাঁ। তোমার চোখে ওর জন্য একটা আলাদা অনুভূতি দেখেছি।”\n\nআরিশ কিছু বলল না।\n\nনওরিন আবার বলল,\n\n“আমি তোমাকে ফিরে পেতে চাই। কিন্তু তোমার জীবনে যদি সত্যিই অন্য কেউ এসে থাকে, তাহলে আমি তোমাকে জোর করব না।”\n\nআরিশ শান্ত গলায় বলল,\n\n“নওরিন, তোমার কথাগুলো শুনেছি। তোমার ভুলটাও বুঝেছি। কিন্তু শুধু সত্যিটা জানলেই সবকিছু আগের মতো হয়ে যায় না।”\n\nনওরিন মাথা নাড়ল।\n\n“আমি বুঝতে পারছি।”\n\n“আমি তোমাকে ক্ষমা করার চেষ্টা করব। কিন্তু আমাদের সম্পর্কটা আবার শুরু করতে পারব কি না, সেটা এখনই বলতে পারছি না।”\n\nনওরিন চোখ মুছে বলল,\n\n“আমি তোমার সিদ্ধান্তের অপেক্ষা করব।”\n\nআরিশ উঠে দাঁড়াল।\n\n“আমাকে কিছু সময় দাও।”\n\nনওরিন বলল,\n\n“যত সময় লাগে।”\n\nক্যাফে থেকে বেরিয়ে আরিশ ফোনটা হাতে নিল।\n\nমায়ার একটা মেসেজ এসেছে।\n\n“কথা হয়েছে?”\n\nআরিশ কিছুক্ষণ ভেবে লিখল,\n\n“হ্যাঁ। আজ অনেক কিছু জানতে পেরেছি।”\n\nমায়া উত্তর দিল,\n\n“তোমার মনটা এখন কেমন?”\n\nআরিশ লিখল,\n\n“জানি না। তবে একটা কথা বুঝেছি।”\n\n“কী কথা?”\n\nআরিশ অনেকক্ষণ স্ক্রিনের দিকে তাকিয়ে থেকে লিখল,\n\n“কিছু মানুষ অতীত হয়ে যায়, কিন্তু তাদের স্মৃতি থেকে যায়। আর কিছু মানুষ বর্তমান হয়ে আসে, অথচ কখন যে তারা মনের ভেতর জায়গা করে নেয়, তা বোঝা যায় না।”\n\nমায়া মেসেজটা পড়ে চুপ করে রইল।\n\nতারপর লিখল,\n\n“হয়তো এটাই জীবনের গল্প।”\n\nআরিশ ফোনটা বুকের কাছে ধরে রাখল।\n\nতার মনে হচ্ছিল, সে একটা নতুন গল্পের সামনে দাঁড়িয়ে আছে।\n\nকিন্তু সেই গল্পের শুরুটা কোথায়, তা এখনো জানে না।\n\nঠিক তখনই নওরিনের আরেকটা মেসেজ এল।\n\n“আরিশ, একটা কথা বলতে ভুলে গিয়েছিলাম। তোমাকে যে মেসেজগুলো দেখানো হয়েছিল, সেগুলো শুধু তোমাকে ভুল বোঝানোর জন্য তৈরি করা হয়নি।”\n\nআরিশ থমকে গেল।\n\nপরের মেসেজটা আসতে কয়েক সেকেন্ড সময় লাগল।\n\n“সেই মেসেজগুলো তৈরি করেছিল এমন একজন, যাকে তুমি খুব ভালোভাবে চেনো।”\n\nআরিশের বুকের ভেতরটা কেঁপে উঠল।\n\nসে লিখল,\n\n“কে?”\n\nনওরিনের উত্তর এল।\n\n“তুমি কি তিথিকে মনে করতে পারছ?”\n\nআরিশের চোখ স্থির হয়ে গেল।\n\nতিথি।\n\nতার ছোটবেলার বন্ধু।\n\nযে এত দিন তার পাশে ছিল।\n\nযে মায়ার সঙ্গেও পরিচিত হয়েছে।\n\nআরিশের মাথায় হাজারটা প্রশ্ন ঘুরতে লাগল।\n\nতিথি কেন?\n\nতিথি কীভাবে তাদের বিচ্ছেদের সঙ্গে জড়িয়ে পড়ল?\n\nআর সবচেয়ে বড় কথা—\n\nতিথি কি এত দিন ধরে তার কাছ থেকে কোনো সত্য লুকিয়ে রেখেছিল?\n\nআরিশ ফোনটা শক্ত করে ধরে দাঁড়িয়ে রইল।\n\nতার অতীতের দরজা খুলেছিল নওরিন।\n\nকিন্তু সেই দরজার ওপাশে দাঁড়িয়ে ছিল এমন একজন, যার কথা সে কখনো ভাবেনি।\n\nচলবে…','\n',char(10)),6,'published',0,'2026-10-30 12:40:18','2026-10-30 12:40:18',5,0);
INSERT INTO "chapters" ("id","book_id","title","body","position","status","views","created_at","updated_at","minutes","reward_ad") VALUES('735a11a9-d56f-432f-b2a6-f3ba44435081','6b7c1105-1b75-4e90-8d98-234684d5046e','অতীতের মাশুল পর্ব - ১',replace('লেখিকা-মাহি রহমান \n\nলেখিকার কিছু কথা \n\nআমার গল্পে কিছু খারাপ ভাষা ব্যবহার করা হতে পারে, যা গল্পের চরিত্র ও পরিস্থিতির প্রয়োজনে লেখা। তাই অনুগ্রহ করে বিষয়টি ক্ষমাসুন্দর দৃষ্টিতে দেখবেন। আর আমি একজন নতুন লেখিকা, তাই লেখার মধ্যে কোনো বানান ভুল বা অনিচ্ছাকৃত ভুলত্রুটি থাকলে ক্ষমা করে দেবেন। আপনাদের ভালোবাসা, সহযোগিতা ও সুন্দর মন্তব্য আমাকে আরও ভালো লেখার অনুপ্রেরণা জোগাবে। আশা করি, আমার গল্পের চরিত্রগুলো ও তাদের অনুভূতি আপনাদের হৃদয় ছুঁয়ে যাবে। 💗📖\n\nভালোবাসা ও দোয়া চাই সবার কাছে। 🥀🖤\n\n\nপ্রিয় খন্দকার সাহেব,\n\nআমার পাখি আমাকে ভালোবেসে বিয়ে করেও ভালোবাসল না! এই দুঃখ নিয়ে কোথায় যাব আমি? কেন করলেন, খন্দকার সাহেব, আমার সঙ্গে এমন অবিচার? এই বিচ্ছেদের ব্যথা আমি কোথায় রাখব?\n\nআপনি যদি একবার বুঝতেন, আপনার জন্য আমার বুকের ভেতরটা কতটা পুড়ে! আপনাকে নিয়ে সারা জীবন একসঙ্গে থাকার স্বপ্ন দেখেই তো আপনার অর্ধাঙ্গিনী হয়েছিলাম। অথচ আমার ভাগ্য আমাকে সেই স্বপ্নটুকুও পূরণ করতে দিল না।\n\nআমার বাবা-মা অনেক আগেই আমাকে ছেড়ে চলে গেছেন। তারপর আপনাকে ভালোবেসেছিলাম। ভেবেছিলাম, আপনিই হবেন আমার শেষ আশ্রয়, আমার বেঁচে থাকার শেষ অবলম্বন। কিন্তু কথায় আছে না, অভাগী যে দিকে যায়, নদীর জলও নাকি শুকিয়ে যায়!\n\nআপনার এত অত্যাচার সহ্য করেও আপনার পাশে ছিলাম। প্রতিবার নিজের চোখের জল লুকিয়ে ভেবেছি, একদিন হয়তো আপনি আমার ভালোবাসা বুঝবেন। একদিন হয়তো আমার মাথায় হাত রেখে বলবেন, ‘পাখি, আমি আছি তো!’\n\nকিন্তু আমার সেই অপেক্ষার অবসান হলো না, খন্দকার সাহেব। বরং যেদিন দেখলাম, আপনি অন্য এক নারীর সঙ্গে, সেদিন আমার শেষ আশাটুকুও ভেঙে গেল। সেদিন বুঝলাম, যে মানুষটার জন্য নিজের সবটুকু উজাড় করে দিয়েছি, তার হৃদয়ে আমার জন্য একটুখানি জায়গাও নেই।\n\nজানেন, খন্দকার সাহেব, আমার সবচেয়ে বড় আফসোস কী?\n\nআমার অতীত! আমার অতীতের সেই একটি ভুল! যদি সেদিন সেই ভুলটা না করতাম, তাহলে হয়তো আজ আমার জীবনটা অন্য রকম হতো। হয়তো আপনি আজ আমার হতেন, আর আমাকে এভাবে নিজের ভালোবাসার কাছে হার মানতে হতো না।\n\nআপনাকে দোষ দিয়েও তো শান্তি পাই না, আবার আপনাকে ভালোবেসেও শান্তি পেলাম না। কী অদ্ভুত, তাই না? যে মানুষটা আমার সমস্ত কষ্টের কারণ, সেই মানুষটাই আবার আমার সবচেয়ে বড় দুর্বলতা!\n\nআমি জানি না, কোনো দিন আমার অভাব আপনাকে ছুঁয়ে যাবে কি না। কোনো এক নিঃশব্দ রাতে আমার কথা মনে পড়বে কি না। শুধু এটুকু জানি, আমি আপনাকে সত্যিই ভালোবেসেছিলাম, খন্দকার সাহেব। আমার ভালোবাসায় কোনো অভিনয় ছিল না, কোনো স্বার্থ ছিল না। ছিল শুধু আপনাকে নিয়ে বেঁচে থাকার এক বুক স্বপ্ন।\n\nইতি, আপনার সেই অভাগী পাখি। 🥀\n\nমাহির এই চিঠি পড়ে আদিয়ান খন্দকার হাউমাউ করে কাঁদছে। মাহির পাশে বসে তার হাতটা নিজের দুহাতের মুঠোয় নিয়ে কাঁপা কাঁপা কণ্ঠে বলল—\n\n— মাহি, বউ আমার! একবার ফিরে আয় না। একবার আমি আদিয়ান কথা দিচ্ছি, তোকে আর কখনো কষ্ট দেব না। তুই একবার চোখ খোল, পাখি! একবার ‘খন্দকার সাহেব’ বলে ডাক দে। একবার শুধু আমার দিকে তাকিয়ে কথা বল, পাখি। আমাকে ছেড়ে চলে যাস না, বউ! আমি বাঁচব কী করে তোকে ছাড়া?\n\nকথাগুলো বলতে বলতে আদিয়ান মাহির হাতটা নিজের বুকের কাছে চেপে ধরল। তার চোখের পানি একের পর এক গড়িয়ে পড়ছে। অথচ মাহি নির্বাক! নেই কোনো অভিমান মাখা কথা, নেই সেই মিষ্টি কণ্ঠে আদিয়ানকে বিরক্ত করার বায়না।\n\n— জানিস, পাখি? তুই না আমার সঙ্গে ঝগড়া করতিস, আমার ওপর রাগ করে থাকতিস। আমি তখন তোকে বুঝতাম না। তোর চোখের পানির মূল্য বুঝিনি, তোর অভিমানগুলোকে ছেলেমানুষি ভেবেছি। আজ তুই চুপ করে আছিস, আর আমি তোর একটা কথা শোনার জন্য পাগলের মতো ছটফট করছি! কেন এমন করলি, মাহি? কেন আমাকে এভাবে একা করে দিলি?\n\nআদিয়ান মাহির কপালে নিজের কপাল ঠেকিয়ে ফুঁপিয়ে কেঁদে উঠল।\n\n— ফিরে আয়, বউ! তোর কাছে ক্ষমা চাইব, তোর সব অভিযোগ শুনব। তুই যত খুশি বকিস, যত খুশি অভিমান করিস, তবু আমার কাছ থেকে দূরে যাস না। তুই জানিস না, তোর এই আদিয়ানটা তোকে ছাড়া একেবারেই অচল। আমি যে তোকে ভীষণ ভালোবাসি, পাখি! ভীষণ ভালোবাসি! \n\n\n\nচলবে....🥹','\n',char(10)),1,'published',0,'2026-10-30 14:17:31','2026-10-30 14:17:31',5,0);
