INSERT INTO "writers" ("id","username","writer_name","email","password_hash","salt","avatar_url","bio","follower_count","badge","is_active","approval_required","created_at","email_verified","referred_by","referral_counted") VALUES('4d9616bf-770c-4c11-8f2f-0f1e435e858f','Elmailmabehrouz','Elma ilma behrouz','xyteeetools@gmail.com','fdc75c92cdec1ab8a7fca3ababcd38d8d4ac9abee776e008baff07b454a3b6f2','7bd5f4a570ef4ad3a8af5f89d6b5ffca','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/287b3ae3-8493-4993-b701-0f5f00d24a75.jpg','ইলমা বেহরোজ। ডাকনাম ইলমা। জন্ম ২০০৩ সালের ১৮ জুলাই। জন্ম স্থান নেত্রকোনা হলেও তার বেড়ে ওঠা সিলেটে। ছোটোবেলা থেকেই গল্প/উপন্যাসের প্রতি ছিল তার ভীষণ ঝোঁক। ক্লাসের ফাঁকে লুকিয়ে গল্পের বই পড়ার কারণে ̧গুরুজনদের তপ্তবাক ̈ও হজম করতে হয়েছে বহুবার। তবুও এই অভ্যাস কে কখনো বাদ দিতে পারেননি। সমাপ্ত গল্পকে নিজ কল্পনায় নতুনভাবে রূপ দেওয়া ছিল তার অন্যতম শখ। স্কুলের গন্ডি পেড়িয়ে একসময় তিনি সোশ্যাল মিডিয়ার গল্পরাজ্যের সঙ্গে পরিচিত হোন। যেখানে সবাই নিজ ̄ চিন্তাশক্তি প্রয়োগ করে নিজ লেখাকে আক্ষরিক রূপ দিয়ে সবার মাঝে ছড়িয়ে দেয়। তাৎক্ষণিক নিজের কল্পনায় সাজানো গল্পগুলোকেও লিখিত রূপ দিতে শুরু করলেন তিনি। পাঠকদের থেকে আশানুরূপ সাড়া পেয়ে লেখালেখির যাত্রা অব্যাহত রাখার ইচ্ছে আরও বৃদ্ধি পায়। ফলসরূপ, রক্তে মিশে যাওয়া লেখালেখিকে আরেক ধাপ এগিয়ে নিতে পাঠকদের প্রতি ভালোবাসা থেকে বইয়ের পাতায় প্রকাশ করলেন তাঁর প্রথম বই ‘মায়ামৃগ’',1,'verified',1,0,'2026-09-22T05:33:14.563Z',1,NULL,0);
