INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('70c1cda4-c95b-464d-978a-4ebf4e1e8989','d629fc94-1098-473a-a221-c331893027b4','বৃষ্টির দিনে তোমার প্রেমে','আরিফ ও নীলাঞ্জনার প্রথম দেখা হয় এক বৃষ্টিভেজা বিকেলে। একটি ছোট্ট পরিচয় থেকে শুরু হয় তাদের বন্ধুত্ব, আর সেই বন্ধুত্ব একসময় রূপ নেয় গভীর ভালোবাসায়। কিন্তু ভালোবাসার পথে কি সবকিছু সহজ হয়? দূরত্ব, অভিমান আর নানা বাধা পেরিয়ে তারা কি একসঙ্গে থাকতে পারবে? জানতে পড়ুন এক মিষ্টি প্রেমের গল্প—“বৃষ্টির দিনে তোমার প্রেমে”।','রোমান্টিক','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/b654e627-b536-4bcb-9e25-f9cfa9b72bf8.png','published',NULL,0,0,3,'2026-10-26T13:55:00.485Z','2026-10-26T14:03:27.459Z',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('24fb44c4-96fb-4234-8c16-ef1ce749b2b8','706bfae5-c0a3-4ec8-82f4-7218526c2c85','রোদজ্বলা সেই বিকেল','অচেনা শহরের পরিচয় থেকে গভীর প্রেম। বাধা পেরিয়ে কি মিলবে অরুণাভ ও তিন্নি? পড়ুন এক অমর ভালোবাসার গল্প।','উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/04d3098d-9fe6-42b2-b65d-c60e353544d9.jpg','published',NULL,0,0,4,'2026-10-05T15:35:46.702Z','2026-10-05T15:42:28.477Z',0,'ongoing','','','','both','episodes',0,'ongoing');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('01791ab9-4890-4566-b4aa-d57ee8724b71','9b877a4e-2678-49d8-9d3a-7114433c9e80','সে আর কখনো ফিরবে না',replace('গল্প: সে আর কখনো ফিরবে না\n\nলেখিকা: মারিয়া ইসলাম মায়া','\n',char(10)),'ছোট গল্প','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/3a701c23-f043-48b6-8690-ebaf27ed5a08.jpg','published',NULL,0,0,1,'2026-10-07T03:14:14.351Z','2026-10-07T08:33:44.830Z',0,'new','','','','both','episodes',0,'ongoing');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('e0052cdd-dcdb-4118-9658-095c43de1b3c','67f9c0b1-070f-4dfb-ae8c-300449aca19d','আমি তোমায় চাই','আমার এই টি সুধু এমনি বানানো কেউ কিছু৷ মনে করবেন না।','রোমান্টিক',NULL,'published',NULL,0,0,0,'2026-10-07T08:20:15.380Z','2026-10-07T09:52:31.468Z',0,'ongoing','','','','both','episodes',0,'ongoing');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('eff4318c-c351-43aa-b2c9-b014fe2bcaaa','149ea1df-eea6-41cb-a88a-19256dd65cd1','আমাদের অসমাপ্ত গল্প',replace('কিছু ভালোবাসা হঠাৎ করেই জীবনে আসে, হৃদয়ে হাজারো স্বপ্ন জাগায়, আবার কখনো নীরবে দূরে চলে যায়।\n\nআরিশ ও মায়ার গল্পটা ঠিক তেমনই। প্রথম দেখা, মিষ্টি ঝগড়া, অভিমান, একে অপরের প্রতি অজান্তেই দুর্বল হয়ে পড়া—সবকিছু মিলিয়ে তাদের জীবন হয়ে ওঠে ভালোবাসার এক নতুন অধ্যায়।\n\nকিন্তু ভাগ্য কি সব ভালোবাসাকে পূর্ণতা দেয়? পরিবারের বাধা, ভুল বোঝাবুঝি আর অতীতের কিছু গোপন সত্য কি তাদের আলাদা করে দেবে?\n\nনাকি সব বাধা পেরিয়ে একদিন তারা খুঁজে পাবে একে অপরকে?\n\nজানতে হলে পড়তে হবে—আমাদের অসমাপ্ত গল্প। কারণ কিছু গল্পের শেষ হয় না, শুধু অপেক্ষায় থাকে নতুন একটি অধ্যায়ের।','\n',char(10)),'উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/70b46916-803b-458b-a78d-3945c27448a7.png','published',NULL,0,0,6,'2026-10-26T14:25:10.168Z','2026-10-30 12:40:18',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('66b49e08-df3b-46cc-aba4-808653ec737f','6074cc27-0926-46e9-9703-893ec44af4aa','Toxic Lover','👀🕊️','উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/4b067b09-52b2-4707-8f2d-36669fb2376b.png','published','',0,0,1,'2026-10-27 09:10:44','2026-10-27 09:20:19',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('8b856a2a-1574-4668-abce-d98d9699ccb2','3f51a19e-6eec-4f6f-a2a5-2ffae3936328','ছায়াসাম্রাজ্য — শেষ উত্তরাধিকারী',replace('সাতটি জাদুর রাজ্য, একটি হারিয়ে যাওয়া সাম্রাজ্য আর এমন এক কিশোর, যার জন্মের রহস্য জানলে কেঁপে উঠবে পুরো পৃথিবী।\n\nসাধারণ জীবন কাটানো আরিন কখনো জানত না যে তার শরীরে ঘুমিয়ে আছে হাজার বছর আগের এক ধ্বংস হয়ে যাওয়া সাম্রাজ্যের শক্তি। তার ষোলোতম জন্মদিনে আকাশে দেখা দিল কালো চাঁদ, জেগে উঠল নিষিদ্ধ জাদু, আর তার হাতে ফুটে উঠল এক রহস্যময় চিহ্ন।\n\nসেই রাতেই নিখোঁজ হয়ে গেল তার বাবা। রেখে গেলেন একটি ভাঙা তলোয়ার, রক্তে লেখা একটি বার্তা এবং এমন এক নাম—যে নাম উচ্চারণ করাও নিষিদ্ধ।\n\nবাবাকে খুঁজতে গিয়ে আরিন প্রবেশ করবে এমন এক জগতে, যেখানে ছায়ারা কথা বলে, মৃত রাজারা স্বপ্নে ফিরে আসে, আর প্রতিটি জাদুর পেছনে লুকিয়ে থাকে ভয়ংকর মূল্য।\n\nকিন্তু সবচেয়ে বড় রহস্য হলো—আরিন কি পৃথিবীকে বাঁচানোর জন্য জন্মেছে, নাকি পৃথিবীকে ধ্বংস করার জন্য?\n\nছায়াসাম্রাজ্যের দরজা খুলেছে। এবার আর কিছুই আগের মতো থাকবে না।','\n',char(10)),'রহস্য','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/29a4bf94-f72f-4651-871c-4fd9cacd80af.jpg','published','',0,0,2,'2026-10-27 15:50:10','2026-10-27 17:09:55',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('fd05cd1d-c934-42e8-8e95-d4bcaabd469f','3f51a19e-6eec-4f6f-a2a5-2ffae3936328','অন্ধকার পেড়িয়ে আলো','রাফি একজন সাধারণ ছেলে, যে অভাব ও ব্যর্থতার মধ্যেও নিজের জীবনে সফল হতে চায়। পরীক্ষায় খারাপ ফল করে এবং মানুষের কটুকথা শুনে সে ভেঙে পড়লেও, এক বৃদ্ধের উপদেশ তাকে নতুন করে সাহস জোগায়। এরপর রাফি নিজের ভুল শুধরে প্রতিদিন পরিশ্রম করার সিদ্ধান্ত নেয়। সে বিশ্বাস করতে শেখে, আজকের খারাপ সময়ই তার জীবনের শেষ নয়—চেষ্টা চালিয়ে গেলে একদিন সফলতা আসবেই।','ছোট গল্প','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/c11edc94-4267-400c-b815-c35c886084d5.png','published','',0,0,1,'2026-10-27 16:15:38','2026-10-27 16:31:59',0,'সম্পূর্ণ','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('027c0167-f892-4c78-a712-5a6a8ab896d6','690b94e2-758c-4c2d-9fa1-4b979d490e09','অপূর্ণতায় তুমি','‘অপূর্ণতায় তুমি’ একটি রহস্য, প্রতিশোধ, ভালোবাসা ও আবেগে ঘেরা উপন্যাস। নীলা, নাদিম ও আদনানের জীবনের জটিল অনুভূতির পাশাপাশি নাইম ও রিমির ভালোবাসার গল্প এগিয়ে চলে ভিন্ন এক পথে। অন্যদিকে, জমিদার মাহবুবুর রহমানের অতীত, মাহতাবের রহস্যময় কর্মকাণ্ড এবং একের পর এক শিশু নিখোঁজ হওয়ার ঘটনা গল্পটিকে আরও রহস্যময় করে তুলেছে। ভালোবাসা, অতীতের প্রতিশোধ আর অজানা রহস্যের জালে জড়িয়ে পড়েছে সবার জীবন।','থ্রিলার','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/a19b425a-265b-4da8-bf31-2afc60e9d503.jpg','published','',0,0,2,'2026-10-27 16:45:44','2026-10-29 06:47:00',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('63a81b40-8f56-4d49-873a-f37e1cec579f','74910fac-b015-45a6-ab66-3aa6c9249fed','কাঠগোলা','তোমার কাছে একটু সময় চেয়েছিলাম, চেয়েছিলাম একটু ভালোবাসা আর যত্ন। চেয়েছিলাম আমার কথাগুলো মন দিয়ে শুনবে, চেয়েছিলাম আমার অভিমানগুলো বুঝতে চেষ্টা করবে। কিন্তু তুমি আমাকে বারবার অবহেলা করেছ, আমার অনুভূতিগুলোকে কখনো গুরুত্ব দাওনি। তবুও তোমার কাছে ভালোবাসা চেয়ে গেছি, কারণ মনটা যে তোমাকেই আপন ভেবেছিল। আজ বুঝেছি, ভালোবাসা জোর করে পাওয়া যায় না, তাই তোমাকে ভালোবেসেই দূরে সরে যেতে শিখছি। ❤️‍🩹🥀','উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/3e182c58-f4a6-4eab-ba38-877abebb35ee.png','rejected','',0,0,0,'2026-10-27 17:01:27','2026-10-30 02:42:03',0,'সম্পূর্ণ','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('59d6163e-3bdc-414c-8083-68052c2c646c','3f51a19e-6eec-4f6f-a2a5-2ffae3936328','রক্তে লেখা একাত্তর','১৯৭১ সালের একটি ছোট্ট গ্রামের সাধারণ এক কিশোরের জীবন কীভাবে যুদ্ধের আগুনে বদলে যায়, কীভাবে সে পরিবার, বন্ধুত্ব, হারানোর বেদনা আর স্বাধীনতার স্বপ্নের মধ্য দিয়ে বড় হয়ে ওঠে—সেই কাহিনি।','উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/3c6c2549-4436-4695-9488-1dfb377cae71.png','published','',0,0,1,'2026-10-27 17:53:23','2026-10-27 18:06:27',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('60b1652d-77a4-40df-a475-11c9c23a2cff','081bf6b2-d877-408e-bc55-1509aa3ae2ee','তোমাকে না বলা কথা গুলো','The feeling of one sided love and not telling him is all about the mind','কবিতা','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/22ee9a15-9ea2-462a-8c47-66438558bf03.png','published','',0,0,2,'2026-10-27 18:05:28','2026-10-28 08:17:26',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('a8ed6eeb-9aca-4555-a381-33ce721e9d6b','3f51a19e-6eec-4f6f-a2a5-2ffae3936328','লাল বাড়ির কাহিনি',replace('লাল বাড়ির রহস্য — সারাংশ\n\nএক রহস্যময় রাতে গ্রামের পুরোনো লাল বাড়িতে খুন হন জমিদার রাশেদ চৌধুরী। বন্ধ ঘরের ভেতরে ঘটে যাওয়া এই খুনের কোনো সূত্র খুঁজে পায় না পুলিশ। রহস্যের সমাধানে আসে তরুণ গোয়েন্দা আরিয়ান রহমান। তদন্ত করতে গিয়ে সে আবিষ্কার করে একটি গোপন ঘর, পুরোনো ছবি এবং দশ বছর আগে নিখোঁজ হওয়া নিজের বাবার সঙ্গে এই বাড়ির অদ্ভুত সম্পর্ক। কিন্তু সত্যের কাছাকাছি পৌঁছাতেই অন্ধকার থেকে ভেসে আসে এক হুমকি। কে এই খুনি? আর আরিয়ানের বাবার নিখোঁজ হওয়ার পেছনে কি লুকিয়ে আছে ভয়ংকর কোনো রহস্য?','\n',char(10)),'ভৌতিক','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/0ce2762b-0c8a-4ece-a33f-90a4ec068ff3.jpg','published','',0,0,7,'2026-10-27 18:33:41','2026-10-28 04:59:39',0,'সম্পূর্ণ','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('b5eb789f-42d2-4728-b681-435e4f18cbf9','f769b066-a571-443c-bae0-5e55f60a77c2','পরিচয়হীন তুমি',replace('📖 পরিচয়হীন তুমি\n✍️ লেখক: নাঈম রহমান ভুঁইয়া\n\nমৃত্যুর আট মাস পর হঠাৎ মিহি ম্যামের আইডিতে সবুজ বাতি জ্বলতে দেখে স্তব্ধ নাঈম! ওপাশ থেকে উত্তরও আসছে, অথচ মিহি তো বহু আগেই পৃথিবী ছেড়ে চলে গেছেন! তবে কি কেউ তার পরিচয়ে লুকিয়ে আছে, নাকি এর পেছনে রয়েছে আরও গভীর কোনো রহস্য?\n\nমৃত মানুষের আইডি থেকে আসা সেই মেসেজের আড়ালে কে? 👀 রহস্যের শুরু, নাকি নতুন কোনো বিপদের সংকেত?','\n',char(10)),'রোমান্টিক','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/9e65a25f-ebe2-4730-8576-97b6dfbf9525.png','rejected','',0,0,0,'2026-10-28 01:10:08','2026-10-30 02:41:59',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('11c0c351-b1ea-4883-861b-7a298c9bc554','1051375b-265a-43ea-b18d-2fae9351d030','তুমি আমার শেষ ঠিকানা',replace('গল্পের নাম: তুমি আমার শেষ ঠিকানা ❤️\n\nআরিয়ান ও নীলার গল্পটি দুটি অচেনা মানুষের প্রথম দেখা থেকে শুরু হওয়া এক মিষ্টি ভালোবাসার গল্প। প্রথমে খুনসুটি, তারপর বন্ধুত্ব, আর ধীরে ধীরে একে অপরের প্রতি গভীর টান—সব মিলিয়ে তাদের সম্পর্ক হয়ে ওঠে বিশেষ। কিন্তু নীলার পরিবার যখন তার বিয়ের কথা ভাবতে শুরু করে, তখন আরিয়ানের মনে জন্ম নেয় নীলাকে হারানোর ভয়। নিজের মনের কথা কি আরিয়ান নীলাকে বলতে পারবে? নাকি সময়ের আগেই তাদের ভালোবাসার গল্পে নেমে আসবে বিচ্ছেদের ছায়া? জানতে হলে পড়তে হবে ‘তুমি আমার শেষ ঠিকানা’—ভালোবাসা, আবেগ, অভিমান ও অপেক্ষায় ভরা একটি রোমান্টিক উপন্যাস।','\n',char(10)),'রোমান্টিক','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/c4e64623-5e0e-4625-ac38-e87e5879c6cd.png','published','',0,0,5,'2026-10-28 05:21:36','2026-10-29 02:22:56',0,'সম্পূর্ণ','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('3e3d06de-10c6-4ea7-a257-f1498c88d9b5','f6b48591-238d-4b74-892a-d0c4de4d9e4b','~ তোমার অন্ধকারে আমার বসন্ত ~','**তীব্র প্রেম,গোপন অতীত আর ভালোবাসায় নতুন জীবনের গল্প**🌙🖊️','রোমান্টিক','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/9d7d0ec5-f9e0-4274-ac31-e05e32a848b3.png','published','',0,0,5,'2026-10-28 10:11:50','2026-10-29 19:04:06',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('14afd96d-44d7-41b0-938e-2949061c9eef','2b893024-44b6-4aac-ba8e-a5b690a4687f','তুমি আমার শেষ ঠিকানা',replace('💕 পর্ব ১: তাবাস্সুমের পরিবার\nতাবাস্সুম বাবা-মায়ের একমাত্র মেয়ে। তার বাবা আব্দুল করিম, মা নাসরিন বেগম আর বড় ভাই তামিম। তামিম বোনকে খুব ভালোবাসে, তবে সব সময় বোনের সঙ্গে মজা করে।\nসকালে তাবাস্সুম রান্নাঘরে মাকে সাহায্য করছিল।\nমা বললেন, “তাবাস্সুম, তোর বাবা বলছিলেন, তোর জন্য একটা ভালো সম্বন্ধ এসেছে।”\nতাবাস্সুমের হাত থেমে গেল।\n“কার সম্বন্ধ, মা?”\nমা হেসে বললেন, “তোরই তো! আর কার?”\nতাবাস্সুম লজ্জা পেয়ে বলল, “মা, আবার শুরু করলে!”\nপাশ থেকে তামিম বলে উঠল, “আমার বোনের বিয়ে হবে, আর আমি বরকে আগে জেরা করব!”\nতাবাস্সুম একটা বালিশ তুলে ভাইয়ের দিকে ছুড়ে মারল“ভাইয়া! তোমাকে কে বলেছে আমার বিয়ে হচ্ছে?”\nতামিম হেসে বলল, “বিয়ের কথা শুনেই তো তোর মুখ লাল হয়ে গেছে!”\nসবাই হেসে উঠল। কিন্তু তাবাস্সুমের মনে তখন একটাই প্রশ্ন—যদি সেই ছেলেটা তিহান হয়?\nকারণ তিহানের কথা সে কাউকে কখনো বলেনি।\n💙 পর্ব ২: তিহানের পরিবার\nতিহানদের পরিবারও বেশ বড়।\nতার বাবা মাহমুদ সাহেব, মা শায়লা বেগম, বড় বোন তানিয়া আর ছোট ভাই তূর্য।\nতিহান পরিবারের বড় ছেলে। বাবা চান, ছেলে নিজের ব্যবসার দায়িত্ব নিক। মা চান, ছেলের বিয়ে দিয়ে সংসারী করতে।\nএকদিন রাতের খাবারের টেবিলে শায়লা বেগম বললেন, “তিহান, একটা কথা বলব?”।।, “তিহান, একটা কথা বলব?”\nতিহান খাবার খেতে খেতে বলল, “বলো, মা।”\n“তোর বিয়ের কথা ভাবছি।”\nতূর্য সঙ্গে সঙ্গে বলে উঠল, “বাহ! ভাইয়ার বিয়ে! ভাবি এলে আমি আর ভাইয়াকে বিরক্ত করব না!”\nতানিয়া হেসে বলল, “তুই আবার ভাইকে বিরক্ত করিস না? সারাদিন তো ভাইয়ের পেছনেই ঘুরিস!”\nতিহান বিরক্তির ভান করে বলল, “তোমরা খাওয়া শেষ করবে, নাকি আমার বিয়ে এখানেই দিয়ে দেবে?”\nমাহমুদ সাহেব গম্ভীরভাবে বললেন, “আমরা চাই, তুই নিজের পছন্দ থাকলে আমাদের জানাস।”\nতিহান চুপ হয়ে গেল।\nতার চোখের সামনে ভেসে উঠল একটি মুখ।','\n',char(10)),'ছোট গল্প','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/0ba367d8-9ece-46cf-aaf1-8bae4f2a5ae1.png','published','',0,0,2,'2026-10-28 10:13:47','2026-10-29 02:08:56',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('2cbfcf10-9c24-49b8-bbdb-dfd3372f5ce8','1879b7b2-0201-4230-ad6f-3dc59409c4e2','তোমাতেই আমার পূর্ণতা',replace('কিছু মানুষ জীবনে আসে, হৃদয়জুড়ে ভালোবাসা হয়ে থেকে যায়। ❤️\n\nকখনো মিষ্টি খুনসুটি, কখনো ছোট্ট অভিমান, আবার কখনো একে অপরকে হারানোর ভয়—সব মিলিয়েই ভালোবাসার গল্প।\n\nদুজন মানুষ একে অপরকে ভীষণ ভালোবাসে। অথচ কিছু ভুল বোঝাবুঝি, কিছু না বলা কথা আর জমে থাকা অভিমান তাদের আলাদা করে দেয়। দূরত্ব বাড়লেও কি মুছে যায় মনের টান? নাকি ভাগ্য আবারও তাদের একই পথে ফিরিয়ে আনে?\n\nঅভিমান ভেঙে, চোখের জল মুছে, সব বাধা পেরিয়ে তারা কি আবার একে অপরের হাত ধরতে পারবে?\n\nএটি শুধু প্রেমের গল্প নয়, এটি অপেক্ষার গল্প, হারিয়ে গিয়েও ফিরে পাওয়ার গল্প, আর এমন এক ভালোবাসার গল্প—যেখানে হাজারো অপূর্ণতার মাঝেও একজন মানুষই হয়ে ওঠে অন্যজনের পূর্ণতা।\n\n“তোমাতেই আমার পূর্ণতা” 🌸💌','\n',char(10)),'ছোট গল্প','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/20b78edb-836a-4576-aafb-1c72be6e4110.png','published','',0,0,2,'2026-10-28 10:20:23','2026-10-30 09:59:00',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('da54f2b7-02e2-47d4-bfdd-ce0b13baf438','e2a8f8d7-b2e1-4ca7-8b38-a12b6c76e0b7','অনিচ্ছায় তুমি অনুভবে তুমি','কাজিন রিলেটেড,জোর করে বিয়ে দেওয়া। উপন্যাস এর নায়ক গম্ভীর,রাগ, বদমেজাজি আর নায়িকা চঞ্চল, দুষ্টু,মায়াবী এদের নিয়ে উপন্যাস।','উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/613a5bd4-c076-4a15-8c13-bb9fa010f513.png','published','',0,0,2,'2026-10-28 14:09:07','2026-10-30 11:50:32',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('b0fe08bd-dc35-4339-98f0-69401976196a','69efdc6f-b8b0-4be5-a275-9ecd357408e3','লাল শাড়ি','বন্ধুত্ব শেষ হবে ভেবে নিজের ভালোবাসার মানুষকে ছেড়ে দেই ফারাজ। এরপর থেকেই মিষ্টির জীবনে নেমে আসে ঝড়....!!','ছোট গল্প','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/131f3980-c2c8-40ee-ba17-837ee563f5b3.jpg','published','',0,0,1,'2026-10-28 14:49:32','2026-10-28 15:51:45',0,'সম্পূর্ণ','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('6ccb462b-20ed-4927-afba-3fed8d8cb4d5','5d524306-4a18-4d7c-b246-6f0d4341bbda','মির্জার বিষাক্ত মায়া','🖤🥀 “প্রিয়সী, তুমি আমার জীবনের সেই অভিশাপ, যাকে আমি মুক্তি দিতে চাই না; সেই পাপ, যার প্রায়শ্চিত্ত করতে আমার অনন্তকালও কম পড়বে। তোমাকে ভালোবাসতে গিয়ে আমি আমার ভেতরের মানুষটাকে কবর দিয়েছি, অথচ তোমার জন্য বাঁচিয়ে রেখেছি আমার শেষ কোমলতাটুকু। তুমি আমার অন্ধকার, আমার উন্মাদনা, আমার সর্বনাশের নেশা! আর যদি কোনোদিন আমার গল্পের শেষ পৃষ্ঠায় আমার নামটুকুও অবশিষ্ট না থাকে, তবুও মনে রেখো—একটা দানবও একদিন ভালোবেসেছিল, আর তার সমস্ত অন্ধকারের ওপারে একমাত্র তুমিই ছিলে তার জান্নাত, তার সর্বনাশ, তার অনন্তকাল…!” 🥀🖤','রহস্য','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/80c5e8c6-48bb-4719-921e-641639fdcbc8.png','published','',0,0,4,'2026-10-28 15:47:43','2026-10-30 07:53:05',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('fa1e8dc4-5d5d-4657-a04f-5368b400045a','3f51a19e-6eec-4f6f-a2a5-2ffae3936328','THE BLACK BILLIONAIRE',replace('The Black Billionaire — সারাংশ\n\nআরিয়ান রহমান একজন তরুণ উদ্যোক্তা, যার স্বপ্ন নিজের ব্যবসায়িক সাম্রাজ্য গড়ে তোলা। সামান্য পুঁজি থেকে শুরু করে সে ধীরে ধীরে সফলতার পথে এগিয়ে যায়। কিন্তু প্রভাবশালী ব্যবসায়ী রাশেদ করিমের সঙ্গে একটি বড় চুক্তি তার জীবনকে অন্যদিকে নিয়ে যায়। চুক্তির আড়ালে লুকিয়ে আছে রহস্য, প্রতারণা ও কোটি টাকার খেলা। নিজের স্বপ্ন, সম্মান ও ব্যবসা রক্ষার লড়াইয়ে আরিয়ানকে মুখোমুখি হতে হবে বিশ্বাসঘাতকতা, শত্রুতা এবং নির্মম ব্যবসায়িক ষড়যন্ত্রের।','\n',char(10)),'উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/250452ce-30c5-495b-8602-e8d3bec0e884.jpg','published','',0,0,1,'2026-10-28 16:57:27','2026-10-28 17:30:34',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('5d5cf223-1205-4823-bfb9-372022109953','3f51a19e-6eec-4f6f-a2a5-2ffae3936328','১৩ নম্বর ঘর','Book Description: গ্রামের এক পরিত্যক্ত জমিদারবাড়িতে আছে এমন একটি ঘর, যেটি দিনের আলোতেও খোলা যায় না। বহু বছর আগে সেখানে নিখোঁজ হয়েছিল একটি পরিবার। এক রাতে সেই বাড়িতে প্রবেশ করে নীলয়। তারপর থেকে প্রতি রাতে তার দরজায় তিনবার টোকা পড়ে—কিন্তু দরজার ওপাশে কেউ থাকে না।','উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/244e74ce-e332-413a-98af-cef53c39d817.jpg','published','',0,0,1,'2026-10-28 17:03:10','2026-10-28 17:08:44',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('94930b51-c177-4390-b399-3c3bd104fc88','ff77a29c-28d1-4568-814b-03891b109f1c','অবাধ্য ভালোবাসা','তুমি আমি আছি থেকে দূরে আর দূরে থেকেই যেন হৃদয় মাজারে 🤍✨','উপন্যাস','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/e2b46d82-8d5d-475a-992c-773c9279ce2f.png','rejected','',0,0,0,'2026-10-28 17:52:38','2026-10-30 02:41:48',0,'চলমান','','','','both','episodes',0,'');
INSERT INTO "stories" ("id","writer_id","title","description","category","cover_url","status","review_note","views","likes","chapters_count","created_at","updated_at","hide_title_on_cover","display_status","author_name","pdf_url","dedication","visible_on","story_type","is_new","writer_status") VALUES('18c1bcd4-b588-42e1-a8cd-037fc3782715','67c9cf28-dac3-455d-9ccb-29fe52cb5e58','চিঠির বাক্স','একটি বাক্স, দুটি মানুষ, অসংখ্য না বলা কথা। ক্যাম্পাসের কৃষ্ণচূড়া গাছ, বৃষ্টি ভেজা বিকেল আর হুইলচেয়ারে বসা এক মেয়ের অপেক্ষার গল্প — চিঠির বাক্স। একটি মিষ্টি প্রেমের গল্প যা আপনাকে কাঁদাবে, হাসাবে।','রোমান্টিক','https://pub-55f5f01908bd4e3094ea07f7deaa7978.r2.dev/books/8cc45acc-a35d-4e4f-9c26-759863a2fb87.png','published','',0,0,3,'2026-10-28 18:26:57','2026-10-29 17:21:32',0,'সম্পূর্ণ','','','','both','episodes',0,'');
