PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE categories (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      cover_url TEXT,
      position INTEGER DEFAULT 0,
      is_active INTEGER DEFAULT 1,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    , icon TEXT DEFAULT 'book-open', color TEXT DEFAULT '#DDF5EC', visible_on TEXT DEFAULT 'both', requested_by TEXT DEFAULT '');
CREATE TABLE books (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      author TEXT NOT NULL,
      category_id TEXT,
      cover_url TEXT,
      description TEXT DEFAULT '',
      status TEXT DEFAULT 'draft',
      writer_status TEXT DEFAULT 'complete',
      is_new INTEGER DEFAULT 0,
      featured INTEGER DEFAULT 0,
      views INTEGER DEFAULT 0,
      likes INTEGER DEFAULT 0,
      dislikes INTEGER DEFAULT 0,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , color TEXT DEFAULT '#123E39', accent TEXT DEFAULT '#F5C660', home_section TEXT DEFAULT '', views_visible INTEGER DEFAULT 1, display_status TEXT DEFAULT '', hide_title_on_cover INTEGER DEFAULT 0, pdf_url TEXT DEFAULT '', dedication TEXT DEFAULT '', author_name TEXT DEFAULT '', show_ads INTEGER DEFAULT 1, pdf_reward_ad INTEGER DEFAULT 0, visible_on TEXT DEFAULT 'both', story_type TEXT DEFAULT 'episodes', short_id TEXT DEFAULT '');
CREATE TABLE chapters (
      id TEXT PRIMARY KEY,
      book_id TEXT NOT NULL,
      title TEXT NOT NULL,
      body TEXT DEFAULT '',
      position INTEGER DEFAULT 0,
      status TEXT DEFAULT 'draft',
      views INTEGER DEFAULT 0,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , minutes INTEGER DEFAULT 5, reward_ad INTEGER DEFAULT 0);
CREATE TABLE devices (
      id TEXT PRIMARY KEY,
      device_key TEXT UNIQUE NOT NULL,
      display_name TEXT,
      last_seen_at TEXT DEFAULT CURRENT_TIMESTAMP,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    , push_token TEXT DEFAULT '');
CREATE TABLE writers (
      id TEXT PRIMARY KEY,
      username TEXT UNIQUE NOT NULL,
      writer_name TEXT NOT NULL,
      email TEXT,
      password_hash TEXT,
      salt TEXT,
      avatar_url TEXT,
      bio TEXT DEFAULT '',
      follower_count INTEGER DEFAULT 0,
      badge TEXT DEFAULT 'none',
      is_active INTEGER DEFAULT 1,
      approval_required INTEGER DEFAULT 1,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    , email_verified INTEGER DEFAULT 1, referred_by TEXT DEFAULT NULL, referral_counted INTEGER DEFAULT 0);
CREATE TABLE stories (
      id TEXT PRIMARY KEY,
      writer_id TEXT NOT NULL,
      title TEXT NOT NULL,
      description TEXT DEFAULT '',
      category TEXT,
      cover_url TEXT,
      status TEXT DEFAULT 'pending',
      review_note TEXT,
      views INTEGER DEFAULT 0,
      likes INTEGER DEFAULT 0,
      chapters_count INTEGER DEFAULT 0,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , hide_title_on_cover INTEGER DEFAULT 0, display_status TEXT DEFAULT '', author_name TEXT DEFAULT '', pdf_url TEXT DEFAULT '', dedication TEXT DEFAULT '', visible_on TEXT DEFAULT 'both', story_type TEXT DEFAULT 'episodes', is_new INTEGER DEFAULT 0, writer_status TEXT DEFAULT '');
CREATE TABLE story_chapters (
      id TEXT PRIMARY KEY,
      story_id TEXT NOT NULL,
      title TEXT NOT NULL,
      body TEXT DEFAULT '',
      position INTEGER DEFAULT 0,
      status TEXT DEFAULT 'draft',
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , minutes INTEGER DEFAULT 5);
CREATE TABLE reactions (
      id TEXT PRIMARY KEY,
      device_id TEXT NOT NULL,
      book_id TEXT NOT NULL,
      value TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(device_id, book_id)
    );
CREATE TABLE follows (
      id TEXT PRIMARY KEY,
      device_id TEXT NOT NULL,
      writer_id TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP, follower_writer_id TEXT DEFAULT NULL, follower_user_id TEXT DEFAULT NULL,
      UNIQUE(device_id, writer_id)
    );
CREATE TABLE comments (
      id TEXT PRIMARY KEY,
      device_id TEXT,
      book_id TEXT NOT NULL,
      chapter_id TEXT,
      display_name TEXT NOT NULL,
      body TEXT NOT NULL,
      status TEXT DEFAULT 'approved',
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    , avatar_url TEXT DEFAULT '');
CREATE TABLE user_state (
      device_key TEXT PRIMARY KEY,
      favorites TEXT DEFAULT '[]',
      history TEXT DEFAULT '[]',
      bookmarks TEXT DEFAULT '[]',
      settings TEXT DEFAULT '{}',
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE notifications (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      body TEXT NOT NULL,
      icon TEXT DEFAULT 'bell',
      url TEXT,
      status TEXT DEFAULT 'sent',
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    , target TEXT DEFAULT '', read INTEGER DEFAULT 0, story_cover TEXT DEFAULT '', device_id TEXT DEFAULT '');
CREATE TABLE moderators (
      id TEXT PRIMARY KEY,
      username TEXT UNIQUE NOT NULL,
      display_name TEXT NOT NULL DEFAULT '',
      password_hash TEXT NOT NULL,
      salt TEXT NOT NULL,
      is_active INTEGER DEFAULT 1,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      last_login_at TEXT
    , last_login_ip TEXT, last_login_device TEXT, last_login_network TEXT);
CREATE TABLE moderator_sessions (
      token_hash TEXT PRIMARY KEY,
      moderator_id TEXT NOT NULL,
      expires_at TEXT NOT NULL,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE app_config (
      key TEXT PRIMARY KEY,
      value TEXT
    );
CREATE TABLE home_settings (
      id TEXT PRIMARY KEY,
      sections TEXT,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , views_visible INTEGER DEFAULT 1, comments_approval INTEGER DEFAULT 1);
CREATE TABLE about_content (
      id TEXT PRIMARY KEY,
      title TEXT,
      subtitle TEXT,
      description TEXT,
      features TEXT,
      version TEXT,
      developer TEXT,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE reports (
      id TEXT PRIMARY KEY,
      book_id TEXT,
      chapter_id TEXT,
      device_id TEXT,
      reason TEXT,
      details TEXT,
      status TEXT DEFAULT 'pending',
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    , reporter_name TEXT DEFAULT 'Anonymous', admin_note TEXT DEFAULT '');
CREATE TABLE writer_activities (
      id TEXT PRIMARY KEY,
      writer_id TEXT NOT NULL,
      type TEXT NOT NULL,
      data TEXT DEFAULT '{}',
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE writer_notifications (
    id TEXT PRIMARY KEY,
    writer_id TEXT NOT NULL,
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    type TEXT DEFAULT 'info',
    story_id TEXT,
    url TEXT DEFAULT '',
    avatar_url TEXT DEFAULT '',
    story_title TEXT DEFAULT '',
    story_cover TEXT DEFAULT '',
    is_read INTEGER DEFAULT 0,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
  );
CREATE TABLE verification_codes (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  code_hash TEXT NOT NULL,
  purpose TEXT NOT NULL,
  attempts INTEGER DEFAULT 0,
  consumed INTEGER DEFAULT 0,
  ip TEXT DEFAULT '',
  expires_at TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE referrals (
  id TEXT PRIMARY KEY,
  code TEXT UNIQUE NOT NULL,
  writer_id TEXT UNIQUE,
  uses INTEGER DEFAULT 0,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  username TEXT UNIQUE NOT NULL,
  email TEXT UNIQUE,
  password_hash TEXT,
  salt TEXT DEFAULT '',
  display_name TEXT DEFAULT '',
  avatar_url TEXT DEFAULT '',
  bio TEXT DEFAULT '',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE affiliate_apps (
  id TEXT PRIMARY KEY,
  platform TEXT,
  username TEXT,
  followers INTEGER DEFAULT 0,
  contact TEXT,
  status TEXT DEFAULT 'pending',
  ip TEXT DEFAULT '',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE deletion_requests (
  id TEXT PRIMARY KEY,
  contact TEXT,
  identifier TEXT,
  details TEXT,
  status TEXT DEFAULT 'pending',
  ip TEXT DEFAULT '',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admin_activity (
  id TEXT PRIMARY KEY,
  action TEXT,
  details TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE quiz_scores (
  id TEXT PRIMARY KEY,
  who TEXT NOT NULL UNIQUE,
  name TEXT DEFAULT '',
  xp INTEGER DEFAULT 0,
  day TEXT DEFAULT (date('now')),
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE quiz_answers (
  id TEXT PRIMARY KEY,
  who TEXT NOT NULL,
  qid TEXT NOT NULL,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(who, qid)
);
CREATE TABLE view_events (
    id TEXT PRIMARY KEY,
    device_id TEXT,
    book_id TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
  );
CREATE TABLE moderator_login_logs (id TEXT PRIMARY KEY, moderator_id TEXT NOT NULL, ip TEXT, city TEXT, country TEXT, isp TEXT, user_agent TEXT, device TEXT, logged_in_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE conversations (
  id TEXT PRIMARY KEY,
  direct_key TEXT UNIQUE, -- e.g. min(w1, w2) || '_' || max(w1, w2)
  last_message_id TEXT,
  last_message_text TEXT DEFAULT '',
  last_message_at TEXT DEFAULT CURRENT_TIMESTAMP,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE conversation_members (
  id TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  writer_id TEXT NOT NULL REFERENCES writers(id) ON DELETE CASCADE,
  last_read_message_id TEXT,
  last_read_at TEXT,
  unread_count INTEGER DEFAULT 0,
  is_muted INTEGER DEFAULT 0,
  is_archived INTEGER DEFAULT 0,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(conversation_id, writer_id)
);
CREATE TABLE messages (
  id TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  sender_id TEXT NOT NULL REFERENCES writers(id) ON DELETE CASCADE,
  reply_to_id TEXT REFERENCES messages(id) ON DELETE SET NULL,
  message_type TEXT NOT NULL DEFAULT 'text', -- 'text', 'image'
  content TEXT NOT NULL DEFAULT '',
  media_url TEXT DEFAULT '',
  media_meta TEXT DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'sent', -- 'sent', 'delivered', 'read'
  is_deleted INTEGER DEFAULT 0,
  deleted_for TEXT DEFAULT '[]', -- JSON array of writer_ids who deleted for themselves
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
, reactions TEXT DEFAULT '{}');
CREATE TABLE message_receipts (
  id TEXT PRIMARY KEY,
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  writer_id TEXT NOT NULL REFERENCES writers(id) ON DELETE CASCADE,
  status TEXT NOT NULL, -- 'delivered', 'read'
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(message_id, writer_id)
);
CREATE TABLE user_presence (
  writer_id TEXT PRIMARY KEY REFERENCES writers(id) ON DELETE CASCADE,
  is_online INTEGER DEFAULT 0,
  last_seen_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_blocks (
  id TEXT PRIMARY KEY,
  blocker_id TEXT NOT NULL REFERENCES writers(id) ON DELETE CASCADE,
  blocked_id TEXT NOT NULL REFERENCES writers(id) ON DELETE CASCADE,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(blocker_id, blocked_id)
);
CREATE TABLE writer_devices (
  id TEXT PRIMARY KEY,
  writer_id TEXT NOT NULL REFERENCES writers(id) ON DELETE CASCADE,
  device_key TEXT NOT NULL,
  push_token TEXT NOT NULL,
  platform TEXT DEFAULT 'android',
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(writer_id, device_key)
);
CREATE INDEX idx_moderator_sessions_moderator ON moderator_sessions(moderator_id);
CREATE INDEX idx_verification_codes_email ON verification_codes(email, purpose);
CREATE INDEX idx_view_events_book ON view_events(book_id);
CREATE INDEX idx_view_events_device ON view_events(device_id);
CREATE INDEX idx_mod_logs_moderator ON moderator_login_logs(moderator_id);
CREATE INDEX idx_conv_members_writer ON conversation_members(writer_id, conversation_id);
CREATE INDEX idx_messages_conv_created ON messages(conversation_id, created_at DESC);
CREATE INDEX idx_messages_sender ON messages(sender_id);
CREATE INDEX idx_user_blocks_pair ON user_blocks(blocker_id, blocked_id);
CREATE INDEX idx_writer_devices_writer ON writer_devices(writer_id);
CREATE VIEW story_reports AS SELECT * FROM reports;
